INSERT INTO verses (sura, aya, text) VALUES (1, 1, 'Bismillâhirrahmânirrahîm');
INSERT INTO verses (sura, aya, text) VALUES (1, 2, 'Hamt, âlemlerin Rabbi olan Allah''a mahsustur.');
INSERT INTO verses (sura, aya, text) VALUES (1, 3, 'O Rahmân''dır, Rahîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (1, 4, 'Din/Hesap gününün sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (1, 5, 'Yalnız sana ibadet eder ve yalnız senden yardım dileriz.');
INSERT INTO verses (sura, aya, text) VALUES (1, 6, 'Bizi doğru yola ilet.');
INSERT INTO verses (sura, aya, text) VALUES (1, 7, 'Nimet verdiğin kimselerin yoluna. Gazaba uğrayanların ve sapanların değil.');
INSERT INTO verses (sura, aya, text) VALUES (2, 1, 'Elif, Lâm, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (2, 2, 'Hiç kuşkusuz bu kitap, takva sahipleri için yol göstericidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 3, 'Onlar gaybe inanırlar, namazı dosdoğru kılarlar, kendilerine rızık olarak verdiğimizden de Allah yolunda harcarlar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 4, 'Onlar, sana indirilene, senden önce indirilenlere ve ahirete de kesin olarak iman ederler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 5, 'İşte onlar Rableri katından bir hidayet üzeredir ve kurtuluşa erecek olanlar onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 6, 'Kâfirlere gelince, onları uyarsan da uyarmasan da birdir, iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 7, 'Allah, onların kalplerini ve kulaklarını mühürlemiştir, gözlerinde de perde vardır. Onlar için büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 8, 'İnsanlardan bir kısmı da iman etmediği halde; "Allah’a ve ahiret gününe iman ettik" derler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 9, 'Allah’ı ve Müminleri aldatmaya çalışırlar. Oysa sadece kendilerini aldatırlar da bunun farkında değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 10, 'Onların kalplerinde bir hastalık vardır. Allah da onların hastalığını artırmıştır. Söyledikleri yalana karşılık da onlara acı veren bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 11, 'Onlara: "Yeryüzünde bozgunculuk yapmayın!" dendiği zaman; "Bizler sadece ıslah edicileriz." derler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 12, 'İyi bilin ki, onlar bozguncuların ta kendileridir. Fakat farkında değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 13, 'Onlara: "Siz de insanların iman ettiği gibi iman edin!" denilince; "Akılsızların iman ettiği gibi mi iman edelim?" derler. Dikkat edin! Asıl akılsızlar kendileridir, fakat bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 14, '(Bu münafıklar) İman edenlere rastladıkları zaman; "Biz de iman ettik", derler. Şeytanları ile baş başa kalınca da: "Biz, sizin yanınızdayız. Onlarla (Müminlerle) sadece alay ediyoruz." derler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 15, 'Allah da onlarla alay eder ve onları taşkınlıkları içinde şaşkın bir halde bırakır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 16, 'İşte onlar, hidayete karşılık sapıklığı satın almış kimselerdir. Bu yüzden alışverişleri onlara kâr getirmemiş ve (sonuçta) doğru yolu bulamamışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 17, 'Onların (münafıkların) hali, (geceleyin) ateş yakan kimsenin haline benzer. Ateş etrafını aydınlattığı sırada Allah, onun ışığını giderir ve onları karanlıklar içerisinde görmez bir halde bırakır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 18, 'Onlar sağır, dilsiz ve körlerdir. Bu sebeple onlar asla dönmezler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 19, 'Yahut onlar gökten boşalan bir yağmura tutulmuş kimselere benzerler. O yağmurda karanlıklar, gök gürültüsü ve şimşek vardır. Onlar yıldırımın şiddetinden ve ölüm korkusundan dolayı parmaklarıyla kulaklarını tıkayıp, kapatırlar. Şüphesiz Allah, kâfirleri çepeçevre kuşatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 20, '(O esnada) şimşek onların gözlerini aniden alacakmış gibi olur. Şimşek parıldadığında yürürler, ortalık birden kararınca da orada dikilip kalıverirler. Eğer Allah isteseydi onların kulaklarını sağır ve gözlerini kör ederdi. Şüphesiz Allah her şeye gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 21, 'Ey insanlar! Sizi ve sizden öncekileri yaratan Rabbinize ibadet ediniz ki, böylece takva sahibi olur, sakınırsınız.');
INSERT INTO verses (sura, aya, text) VALUES (2, 22, 'O, sizin için yeryüzünü döşedi ve gökyüzünü bina etti. Gökten su indirip onunla size rızık olsun diye ürünler yetiştirdi. Öyleyse, bunları bile bile Allah’a ortak koşmayın.');
INSERT INTO verses (sura, aya, text) VALUES (2, 23, 'Kulumuza indirdiğimiz (Kur’an) dan bir şüpheniz varsa; haydi siz de ona benzer bir sûre getirin. Eğer doğru sözlüler iseniz, Allah’tan başka güvendiklerinizi de yardıma çağırın.');
INSERT INTO verses (sura, aya, text) VALUES (2, 24, 'Eğer bu işi yapamazsanız ki, elbette yapamayacaksınız. O zaman, kâfirler için hazırlanan (ve) yakıtı insanlar ve taşlar olan ateşten kendinizi koruyun.');
INSERT INTO verses (sura, aya, text) VALUES (2, 25, 'İman eden ve salih amel işleyen kimselere, içinden ırmaklar akan cennetler olduğunu müjdele! Ne zaman oradaki meyvelerden rızıklandırılsalar: "Bu, daha önce de rızıklandığımız şey" diyecekler. O meyveler kendilerine (dünyadakilerin) bir benzeri olarak verilecektir ve orada onlar için tertemiz eşler de vardır ve onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 26, 'Allah, bir sivrisineği ve onun üzerinde bir şeyi örnek vermekten haya etmez. İman edenler, onun Rablerinden gelen bir gerçek olduğunu bilirler, ama kâfirler; "Allah bu misalle ne demek istiyor?" derler. Allah, bu misalle birçoklarını dalalette bırakır, birçoklarını da hidayete erdirir. Onunla ancak fasıkları saptırır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 27, 'Onlar, Allah ile yapılan sözleşmeyi kabul ettikten sonra bozan, Allah’ın, birleştirilmesini emrettiği şeyi koparan ve yeryüzünde bozgunculuk yapanlardır. İşte kaybedecek olanlar onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 28, 'Allah''ı nasıl inkâr edersiniz? Hâlbuki ölü idiniz de sizleri diriltti, sonra öldürecek, sonra tekrar diriltecek ve sonunda O''na döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 29, 'O, yeryüzündeki her şeyi sizin için yaratan, sonra gökyüzüne yönelip yedi kat gök olarak düzenleyendir. O, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 30, 'Hani Rabbin meleklere: "Ben yeryüzünde bir halife yaratacağım." demişti. Melekler de: "Yeryüzünde bozgunculuk edecek, kanlar dökecek birini mi yaratacaksın? Oysa biz seni (durmadan) hamt ile tesbih ve takdis ediyoruz." dediler. Allah da "Sizin bilmediğiniz şeyleri ben bilirim." buyurmuştu.');
INSERT INTO verses (sura, aya, text) VALUES (2, 31, 'Allah, Âdem’e bütün varlıkların isimlerini öğretti. Sonra onları meleklere göstererek: “Eğer doğru söyleyenler iseniz, haydi bana bunların isimlerini bildirin.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 32, '(Melekler) "Sen yücesin! Seni eksiklikten tenzih ederiz. Senin bize öğrettiğinden başka hiçbir ilmimiz yoktur. Şüphesiz her şeyi hakkıyla bilen, her şeyi hikmetle yapan sensin.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 33, 'Allah şöyle dedi: “Ey Âdem! Onlara bunların isimlerini söyle.” Âdem, meleklere onların isimlerini bildirince Allah: “Size, göklerin ve yerin gaybını şüphesiz ki ben bilirim, yine açığa vurduklarınızı da, gizli tuttuklarınızı da ben bilirim demedim mi?” buyurdu.');
INSERT INTO verses (sura, aya, text) VALUES (2, 34, 'Hani Meleklere: "Âdem''e (saygı ve hürmet için) secde edin!" demiştik de İblis hariç bütün melekler hemen secde edivermişlerdi. İblis bundan kaçınmış, büyüklenmiş ve kâfirlerden olmuştu.');
INSERT INTO verses (sura, aya, text) VALUES (2, 35, 'Ve demiştik ki: "Ey Âdem! Sen ve eşin Cennet''e yerleşin, dilediğiniz yerden bol bol yiyin. Yalnız şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz."');
INSERT INTO verses (sura, aya, text) VALUES (2, 36, 'Derken şeytan oradan ikisinin de ayağını kaydırdı, onları bulundukları yerden çıkardı. Biz de onlara: "Birbirinize düşman olarak inin, yeryüzünde sizin için bir barınak ve belli bir süreye kadar orada yaşamak vardır." dedik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 37, 'Derken, Âdem (vahy yoluyla) Rabbinden birtakım kelimeler aldı, (onlarla amel edip Rabbine yalvardı). O da bunun üzerine tövbesini kabul etti. Şüphesiz O, tövbeleri çok kabul edendir, çok bağışlayandır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 38, 'Dedik ki: "Hepiniz oradan (Cennet''ten) inin.Tarafımdan size bir yol gösterici gelir de kim ona uyarsa, onlar için hiçbir korku yoktur ve onlar üzülmeyeceklerdir."');
INSERT INTO verses (sura, aya, text) VALUES (2, 39, 'Ayetlerimizi yalanlayıp, inkâr edenler cehennemliktirler. Onlar, orada ebedi kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 40, 'Ey İsrailoğulları! Size verdiğim nimeti hatırlayın. Bana verdiğiniz sözü yerine getirin ki ben de size verdiğim vaadi yerine getireyim. Yalnızca benden korkun.');
INSERT INTO verses (sura, aya, text) VALUES (2, 41, 'Elinizde bulunan Tevrat’ı tasdik edici olarak indirdiğim Kur’an’a iman edin ve onu inkâr edenlerin ilki siz olmayın. Ayetlerimi az bir paha karşılığında satmayın; yalnızca benden sakının!');
INSERT INTO verses (sura, aya, text) VALUES (2, 42, 'Hakka batılı karıştırmayın, bile bile hakkı gizlemeyin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 43, 'Namazı kılın, zekâtı verin, rükû edenlerle birlikte rükû edin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 44, 'İnsanlara iyiliği emredersiniz de, kendinizi unutur musunuz? Kitabı (Tevrat''ı) okuyup durduğunuz halde düşünmez misiniz?');
INSERT INTO verses (sura, aya, text) VALUES (2, 45, 'Sabır ve namazla Allah’tan yardım isteyin ve şüphesiz bu (namaz), huşu duyanlardan başkasına ağır gelir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 46, 'Onlar, Rablerine kavuşacaklarını ve gerçekten O’na döneceklerini bilirler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 47, 'Ey İsrailoğulları! Size verdiğim nimetimi ve sizi diğer toplumlara üstün kıldığımı hatırlayıp, anın.');
INSERT INTO verses (sura, aya, text) VALUES (2, 48, 'Kimsenin kimseden faydalanamayacağı, hiç kimseden (Allah izin vermedikçe) bir şefaatin kabul edilmeyeceği, kimseden bir fidyenin alınmayacağı ve yardım da görülmeyeceği bir günden kendinizi koruyun.');
INSERT INTO verses (sura, aya, text) VALUES (2, 49, 'Hani size azabın en kötüsünü tattıran, yeni doğan oğullarınızı boğazlayan ve kızlarınızı hayatta bırakan Firavun ailesinden sizi kurtarmıştık ve bunda sizin için Rabbiniz tarafından büyük bir imtihan vardı.');
INSERT INTO verses (sura, aya, text) VALUES (2, 50, 'Hani, sizin için denizi yarmış, sizi kurtarmış, gözlerinizin önünde Firavun hanedanını suda boğmuştuk.');
INSERT INTO verses (sura, aya, text) VALUES (2, 51, 'Hani, biz Mûsâ ile kırk gece için sözleşmiştik. Ama siz zalimlik ederek onun ardından buzağıya tapınmıştınız.');
INSERT INTO verses (sura, aya, text) VALUES (2, 52, 'Bundan sonra da yine belki şükredersiniz diye sizi affetmiştik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 53, 'Hani, doğru yolu bulasınız diye size Kitab’ı (Tevrat’ı) ve Furkan’ı (Hak ile bâtılı ayıran ilahî hükümleri) vermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 54, 'Mûsâ, kavmine dedi ki: “Ey kavmim! Sizler, buzağıyı ilâh edinmekle kendinize yazık ettiniz. Gelin yaratıcınıza tövbe edin ve birbirinizi öldürün. Bu, yaratıcınız katında sizin için daha iyidir." Böylece Allah da onların tövbesini kabul etti. Çünkü O, tövbeleri çok kabul edendir, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 55, '"Ey Mûsâ! Allah’ı apaçık görmedikçe sana inanmayacağız." demiştiniz de, bunun üzerine bakıp dururken sizi yıldırım çarpmıştı');
INSERT INTO verses (sura, aya, text) VALUES (2, 56, 'Sonra, şükredesiniz diye ölümünüzün ardından sizi tekrar dirilttik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 57, 'Bulutlarla sizi gölgelendirdik, kudret helvası ve bıldırcın gönderdik. Size rızık olarak verdiğimiz güzel şeylerden yiyin, dedik. Fakat onlar bize değil ancak kendilerine zulmediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (2, 58, 'Hani: (İsrailoğullarına) "Şu kasabaya girip, dilediğiniz yerden istediğinizi bol bol yiyin. Kapısından secde ederek/boynu bükük, zelil olarak girin ve “Bağışla” deyin de sizi bağışlayalım. Güzel davrananların mükâfatını da artıracağız." demiştik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 59, 'Fakat, zulmedenler kendilerine söylenmiş olan sözü başka bir sözle değiştirdiler. Biz de, zalimlere, günah işleyerek yoldan çıktıkları için gökten kahredici bir azap indirmiştik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 60, 'Mûsâ, (çölde) halkı için su aradığında: "Değneğinle taşa vur!" dedik. Ondan on iki pınar fışkırdı ve her grup su içeceği pınarı öğrenmişti. Allah’ın rızkından yiyin, için; fakat yeryüzünde bozguncular olarak taşkınlık yapmayın!');
INSERT INTO verses (sura, aya, text) VALUES (2, 61, 'Hani, “Ey Mûsâ! Biz bir çeşit yemeğe asla katlanamayız. O hâlde bizim için Rabbine yalvar da, o bize yerden biten sebze, salatalık, sarımsak, mercimek, soğan versin” demiştiniz. O da size: “İyi olanı düşük olanla değiştirmek mi istiyorsunuz? Öyle ise inin şehre! İstedikleriniz orada var." demişti. Böylece zillet ve yoksulluk onları kapladı. Onlar, Allah’ın gazabına uğradılar. Bunun sebebi; onların, Allah’ın ayetlerini inkâr ediyor, peygamberleri de haksız yere öldürüyor olmaları idi. Bunların hepsi isyanları ve taşkınlıkları sebebiyledir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 62, 'Şüphesiz iman edenler, Yahudiler, Hristiyanlar ve Sâbiîlerden kim Allah’a ve ahiret gününe iman eder ve salih amel işlerse; onlara Rableri katında mükâfatlar vardır. Onlara bir korku yoktur, üzülmeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 63, 'Hani, sizden sağlam bir söz almış, Tûr dağını da üzerinize kaldırmış ve “Sakınasınız diye, size verdiğimiz kitabı sıkı tutun, onun içindekileri düşünün” demiştik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 64, 'Bundan sonra yine yüz çevirmiştiniz. Eğer Allah’ın size bol lütfu ve merhameti olmasaydı, elbette hüsrana uğrayanlardan olurdunuz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 65, 'Şüphesiz siz, içinizden cumartesi yasağını çiğneyenleri biliyorsunuz. İşte biz onlara, “Aşağılık maymunlar olun!” demiştik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 66, 'Böylece onların (maymunlara çevrilmiş insanların) akıbetini hem onu görenlere, hem de kendilerinden sonra geleceklere bir ibret ve Allah’tan korkanlar için de bir öğüt vesilesi kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (2, 67, 'Hani Mûsâ kavmine: "Allah, size bir inek kesmenizi emrediyor" demişti. Onlar: "Bizimle alay mı ediyorsun?" demişlerdi. Mûsâ da: "Ben cahillerden olmaktan Allah’a sığınırım" demişti');
INSERT INTO verses (sura, aya, text) VALUES (2, 68, 'Bizim için Rabbine dua et de bize onun nasıl bir şey olduğunu açıklasın, dediler. Mûsâ şöyle dedi: “(Rabbim) diyor ki: O, ne yaşlı, ne körpe, ikisi arası bir inektir. Haydi, emrolunduğunuz işi yapın.”');
INSERT INTO verses (sura, aya, text) VALUES (2, 69, 'Onlar: “Bizim için Rabbine dua et de, rengi neymiş, açıklasın.” dediler. Mûsâ: "Allah, onun, bakanların içini açan, parlak sarı bir inek olduğunu söylüyor." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 70, 'Onlar: (Ey Mûsâ) Rabbine dua et, bize açıkça bildirsin. Nasıl bir inek olduğunu anlayamadık. Allah dilerse elbette biz hidayete erenlerden oluruz, dediler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 71, 'Mûsâ şöyle dedi: “Rabbim diyor ki; o, çift sürmek, ekin sulamak için boyunduruğa vurulmamış, kusursuz, hiç alacası olmayan bir inektir.” Onlar: “İşte, şimdi tam doğrusunu bildirdin” dediler. Nihayet o ineği kestiler. Neredeyse bunu yapmayacaklardı.');
INSERT INTO verses (sura, aya, text) VALUES (2, 72, 'Hani, bir kimseyi öldürmüştünüz de suçu birbirinizin üstüne atmıştınız. Halbuki Allah, gizlemekte olduğunuzu ortaya çıkaracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 73, '“İneğin bir parçası ile öldürülene vurun” dedik. İşte, Allah ölüleri böyle diriltir, düşünesiniz diye mucizelerini de size böyle gösterir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 74, '(Ne var ki) bunlardan sonra yine kalpleriniz taş gibi yahut daha sert bir şekilde katılaşmıştı. Halbuki içinden nehirler kaynayan, yarılıp (içlerinden) sular çıkan ve Allah korkusundan yuvarlanan nice taşlar vardır! Allah yapmakta olduklarınızdan gafil değildir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 75, 'Şimdi (ey Müminler) size iman edeceklerini mi umuyorsunuz? Oysa onlardan bir grup vardı ki, Allah’ın sözünü işitirlerdi de düşünüp akıl erdirdikten sonra, bile bile onu tahrif ederlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 76, '(Münafıklar) iman edenlerle karşılaştıkları zaman “İman ettik” derler, birbirleriyle yalnız kaldıklarında; "Rabbinizin yanında size karşı delil getirsinler diye mi, Allah’ın size açıkladığını onlara anlatıp duruyorsunuz?" derlerdi. Bunu akıl etmiyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (2, 77, 'Onlar bilmiyorlar mı ki, Allah onların gizli tuttuklarını da, açığa vurduklarını da bilir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 78, 'Onların bir kısmının okuyup yazması yoktur. Kitabı (Tevrat''ı) bilmezler, bildikleri sadece bir takım yalan ve kuruntulardır. Onlar yalnızca zanneder dururlar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 79, 'Kitabı kendi elleriyle yazıp sonra onu az bir bedel karşılığında satabilmek için: «Bu, Allah katındandır» diyenlerin vay haline! Vay ellerinin yazmış olduğundan dolayı başlarına geleceklere! Kazandıklarından dolayı vay onların haline!');
INSERT INTO verses (sura, aya, text) VALUES (2, 80, 'İsrailoğulları "Ateş bize sayılı bir kaç günden başka dokunmayacaktır" derler. Onlara: "Allah katından bir söz mü aldınız? Eğer, öyle ise Allah sözünden dönmez; yoksa Allah hakkında bilmediğiniz bir şey mi söylüyorsunuz?" de.');
INSERT INTO verses (sura, aya, text) VALUES (2, 81, 'Hayır! günah işleyip günahı kendisini kuşatmış olan kimseler, cehennemlikler işte onlardır. Onlar orada ebedi kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 82, 'İman edip salih ameller işleyenler ise cennetliklerdir. Onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 83, 'İsrailoğulları''ndan: "Allah’tan başkasına ibadet etmeyin, anaya, babaya, yakın akrabaya, yetimlere, yoksullara iyilik edin, insanlara güzel söz söyleyin, namazı kılın, zekâtı verin!" diye söz almıştık. Sonra siz pek azınız dışında sözünüzden döndünüz ve hala da dönmeye devam ediyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 84, '(Ey İsrailoğulları!) “Birbirinizin kanını dökmeyeceksiniz, birbirinizi yurtlarınızdan çıkarmayacaksınız” diye de sizden kesin söz almıştık. Sonra bunu böylece kabul etmiştiniz. Kendiniz de buna hâlâ şahitlik etmektesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 85, 'Ama siz, birbirinizi öldüren, içinizden bir kesime karşı kötülük ve zulümde yardımlaşarak size haram olduğu hâlde onları yurtlarından çıkaran, size esir olarak geldiklerinde ise fidye verip kendilerini kurtaran kimselersiniz. Yoksa siz kitabın (Tevrat’ın) bir kısmına inanıp, bir kısmını inkâr mı ediyorsunuz? Şu hâlde içinizden böyle yapanın cezası dünya hayatında rezil olmak ve kıyamet gününde azabın en şiddetlisine uğratılmaktan başka bir şey değildir. Çünkü Allah, yaptıklarınızdan habersiz değildir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 86, 'İşte onlar, ahirete karşılık dünya hayatını satın alan kimselerdir. Onlardan azap hiç hafifletilmeyecektir. Ve onlar, hiçbir yardım da göremeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 87, 'Andolsun biz Mûsâ''ya kitabı (Tevrat''ı) verdik. Ondan sonra art arda peygamberler gönderdik. Meryemoğlu İsa''ya da deliller verdik. Ve onu, Rûhu''l-Kudüs (Cebrâil) ile destekledik. Ama ne zaman size bir peygamber nefislerinizin hoşlanmadığı bir şey getirdiyse büyüklük taslayarak kimini yalanladığınız, kimini de öldürdüğünüz doğru değil mi');
INSERT INTO verses (sura, aya, text) VALUES (2, 88, '(Yahudiler Peygamberlerle alay ederek) Kalplerimiz perdelidir! dediler. Hayır! Allah, küfürleri yüzünden onları lanetlemiştir. Ancak onların çok az bir kısmı iman eder.');
INSERT INTO verses (sura, aya, text) VALUES (2, 89, 'Allah katından kendilerine ellerindekini (Tevrat’ı) tasdik eden bir kitap (Kur’an) gelince onu inkâr ettiler. Oysa, daha önce (bu kitabı getirecek peygamber ile) inkârcılara karşı yardım istiyorlardı. (Tevrat’tan) tanıyıp bildikleri (bu peygamber) kendilerine gelince onu inkâr ettiler. Allah’ın lâneti inkârcıların üzerine olsun.');
INSERT INTO verses (sura, aya, text) VALUES (2, 90, 'Allah''ın kullarından dilediğine, (Kitap) indirmesini çekemeyerek, Allah''ın indirdiğini (Kur''an''ı) inkâr etmekle, kendilerini ne kötü bir şey karşılığında sattılar. Bu yüzden gazab üstüne gazaba uğradılar. Kâfirlere alçaltıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 91, 'Onlara: “Allah’ın indirdiğine (Kur’an’a) iman edin” denilince, “Biz sadece bize indirilene (Tevrat’a) iman ederiz” deyip, ondan sonra geleni (Kur’an’ı) inkâr ederler. Halbuki o, ellerinde bulunanı (Tevrat’ı) tasdik eden hak bir kitaptır. De ki: “Eğer iman eden kimseler idiyseniz, daha önce niçin Allah’ın peygamberlerini öldürüyordunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (2, 92, 'Andolsun, Mûsâ size açık mucizeler getirmişti de, sonra onun ardından buzağıyı ilah edinmiştiniz. Siz işte o zalimlersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 93, 'Hani, Tûr dağını tepenize dikerek sizden söz almıştık, “Size verdiğimize (Kitab’a) sımsıkı sarılın; ona kulak verin” demiştik. Onlar: “İşittik, karşı geldik” demişlerdi. Küfürleri yüzünden buzağı sevgisi onların kalplerine içirilip, sindirilmişti. Onlara de ki: "(Tevrat’a beslediğinizi iddia ettiğiniz) imanınızın size emrettiği şey ne kötüdür, eğer inanan kimselerseniz!"');
INSERT INTO verses (sura, aya, text) VALUES (2, 94, '(Ey Muhammed, onlara:) De ki: “Eğer (iddia ettiğiniz gibi) Allah katındaki ahiret yurdu (Cennet) diğer insanlar için değil de yalnız sizinse ve doğru söyleyenler iseniz haydi ölümü temenni edin!”');
INSERT INTO verses (sura, aya, text) VALUES (2, 95, 'Fakat kendi elleriyle önceden yaptıkları işler yüzünden ölümü hiçbir zaman temenni edemezler. Allah, o zalimleri en iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 96, 'Sen onları diğer insanların hayata en düşkünlerinden; hatta, Allah’a ortak koşanlardan bile yaşamaya daha düşkün olduklarını görürsün. Onların her biri bin yıl yaşamak ister. Halbuki uzun yaşamak, onları azaptan kurtaracak değildir. Zira Allah, onların bütün yaptıklarını görendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 97, 'De ki: “Her kim Cebrâîl’e düşman ise, bilsin ki o, Allah’ın izni ile Kur’an’ı; önceki kitapları doğrulayıcı, Müminler için de bir hidayet rehberi ve müjde verici olarak senin kalbine indirmiştir.”');
INSERT INTO verses (sura, aya, text) VALUES (2, 98, 'Her kim Allah’a, meleklerine, rasûllerine, Cebrâil’e ve Mîkâil’e düşman olursa, şüphesiz Allah da o kâfirlerin düşmanıdır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 99, 'Andolsun biz, sana apaçık ayetler indirdik. Onları fasıklardan başkası inkâr etmez.');
INSERT INTO verses (sura, aya, text) VALUES (2, 100, 'Onlar ne zaman bir söz vermişlerse, içlerinden bir grup bu sözü bozup atmadı mı? Zaten onların çoğu iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 101, 'Onlara ne zaman ellerinde bulunanı (Tevrat''ı) tasdik eden bir rasûl gelse kendilerine kitap verilenlerden bir grup, sanki Allah’ın kitabını bilmiyorlarmış gibi arkalarına attılar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 102, 'Onlar şeytanların, Süleyman’ın saltanatı hakkında uydurdukları şeylere tabi oldular. Oysa Süleyman kâfir değildi. (Fakat insanlara sihri öğreten) şeytanlar kâfir idi. Onlar insanlara büyüyü Babil''deki iki meleğe, Hârut ile Mârut’a indirileni öğretiyorlardı. O ikisi: Biz bir imtihan vesilesiyiz, sakın kâfir olma! demedikçe, hiç kimseye bir şey öğretmiyorlardı. O ikisinden karı ile kocanın arasını ayıracak şeyler öğreniyorlardı. Halbuki onlar, Allah''ın izni olmadıkça o sihirle hiç kimseye zarar veremezlerdi. Onlar kendilerine faydalı olanı değil zararlı olanı öğreniyorlardı. Andolsun onlar, o büyüyü satın alanın ahirette bir nasibi olmadığını gayet iyi biliyorlardı. Kendilerini sattıkları şeyin ne kadar kötü olduğunu keşke anlasalardı!');
INSERT INTO verses (sura, aya, text) VALUES (2, 103, 'Eğer onlar iman edip takva sahibi olsalardı, elbette Allah katında verilecek sevap daha hayırlı olurdu. Keşke bilselerdi!');
INSERT INTO verses (sura, aya, text) VALUES (2, 104, 'Ey iman edenler! “Râinâ” (bizi gözet) demeyin! “Unzurnâ” (bize bak) deyin ve sözü dinleyin. Kâfirler için çok acı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 105, '(Ey Müminler!) Kitap ehli olan kâfirler de, müşrikler de size Rabbinizden hiçbir hayır indirilmesini istemezler. Allah ise rahmetiyle dilediği kimseyi seçerek ihsanda bulunur. Şüphesiz Allah en büyük lütuf ve ihsan sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 106, 'Biz neshettiğimiz veya unutturduğumuz bir ayetin yerine ya ondan daha hayırlısını veya onun benzerini getiririz. Allah’ın her şeye gücünün yettiğini bilmez misin?');
INSERT INTO verses (sura, aya, text) VALUES (2, 107, 'Bilmez misin ki, göklerin ve yerin hükümranlığı Allah’ındır. Sizin için Allah’tan başka ne bir dost, ne de bir yardımcı vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 108, 'Yoksa siz de daha önce Mûsâ’nın sorguya çekildiği gibi peygamberinizi sorguya çekmek mi istiyorsunuz? Kim imanı, küfür ile değiştirirse doğru yoldan sapmış olur.');
INSERT INTO verses (sura, aya, text) VALUES (2, 109, 'Kitap ehlinden bir çoğu, hak kendilerine apaçık belli olduktan sonra, içlerindeki haset yüzünden, sizi imanınızdan sonra tekrar küfre döndürmeyi arzu ederler. Öyleyse onlara Allah’ın emri gelinceye kadar bırakıp, terk edin. Kendi hallerine bırakınız. Şüphesiz Allah’ın gücü her şeye yeter.');
INSERT INTO verses (sura, aya, text) VALUES (2, 110, 'Namazı kılın, zekâtı verin, kendiniz için önden ne hayır yollarsanız Allah katında onu bulursunuz. Şüphesiz Allah, yaptıklarınızı en iyi görendir!');
INSERT INTO verses (sura, aya, text) VALUES (2, 111, '(Ehl-i kitap:) Bir de; “Yahudi ve Hristiyanlardan başkası Cennet’e giremeyecek” dediler. Bu, onların kuruntusudur. De ki: “Eğer doğru söylüyorsanız (iddianızı ispat edecek) delilinizi getirin.”');
INSERT INTO verses (sura, aya, text) VALUES (2, 112, 'Bilâkis, kim muhsin olarak yüzünü Allah''a döndürürse (Allah''a hakkıyla kulluk ederse) ecri Rabbi katındadır. Onlar için ne bir korku vardır, ne de üzülürler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 113, 'Yahudiler: “Hristiyanlar hiçbir şey üzere değildir” dediler. Hristiyanlar da, “Yahudiler hiçbir şey üzere değildir” dediler. Oysa hepsi kitabı okuyorlar. (Kitabı) bilmeyenler de birbirleri hakkında tıpkı onların söylediklerini söylediler. Allah, ihtilâfa düştükleri hususlarda kıyamet günü onlar hakkında hükmünü verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 114, 'Allah’ın mescitlerinde, Allah’ın isminin anılmasını yasaklayanlardan ve onların harap olmalarına çalışanlardan daha zalim kim olabilir? Böyleleri oralara (eğer girerlerse) ancak korka korka girebilmelidirler. Bunlar için dünyada rezillik, ahirette de büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 115, 'Doğu da Allah’ındır batı da. Ne tarafa yönelirseniz yönelin Allah’ın yüzü oradadır. Şüphesiz Allah, her şeyi kuşatandır, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 116, '"Allah çocuk edindi" diyorlar. Hâşâ! O bundan münezzehtir. Bilakis, göklerde ve yerde olanların hepsi O’nundur. Hepsi O’na boyun eğmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 117, 'O, göklerin ve yerin yaratıcısıdır. Bir şeyin olmasını istediği zaman ona sadece “Ol!” der, o da hemen oluverir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 118, 'Bilmeyenler: "Ne olur Allah bizimle konuşsa veya bize bir mucize gelse?" demektedirler. Onlardan öncekiler de tıpkı onların söyledikleri gibi söylemişlerdi. Kalpleri (nasıl da) birbirine benzemiş. Oysa biz, iyice bilmek isteyen bir toplum için ayetlerimizi apaçık göstermişizdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 119, 'Şüphesiz biz seni hak ile müjdeleyici ve uyarıcı olarak gönderdik. Cehennem halkından sen sorumlu değilsin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 120, 'Yahudiler de Hristiyanlar da, sen onların dinine uymadıkça, asla senden hoşnut olmazlar. De ki: Asıl doğru yol Allah’ın gösterdiği yoldur. Sana gelen ilimden sonra eğer onların arzularına uyacak olursan, Allah’tan seni koruyacak bir veli de bir yardımcı da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (2, 121, 'Kendilerine kitap verdiğimiz kimseler, onu hakkıyla okurlar. İşte bunlar ona iman eden kimselerdir. Onu inkâr edenlere gelince, işte onlar hüsrana uğrayanların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 122, 'Ey İsrailoğulları! Size verdiğim nimeti ve sizi (bir zamanlar) diğer toplumlara üstün kıldığımı hatırlayın.');
INSERT INTO verses (sura, aya, text) VALUES (2, 123, 'Kimsenin kimse adına bir şey ödemeyeceği, kimseden fidye kabul edilmeyeceği, kimseye şefaatin fayda vermeyeceği ve kendilerine yardım da edilmeyeceği bir günden kendinizi koruyun!');
INSERT INTO verses (sura, aya, text) VALUES (2, 124, 'Hani Rabbi, İbrahim’i birtakım emirlerle imtihan etmiş, İbrahim onların hepsini yerine getirmiş de Rabbi şöyle buyurmuştu: “Ben seni insanlara önder yapacağım.” İbrahim de, “Soyumdan gelenlerden de (önderler yap, ya Rabbi!)” demişti. Bunun üzerine Rabbi: "Benim ahdime (verdiğim söze) zalimler nail olamaz." diye buyurdu.');
INSERT INTO verses (sura, aya, text) VALUES (2, 125, 'Hani, biz Kâbe’yi insanlara dönüş/toplantı ve güven yeri kılmıştık. Siz de Makam-ı İbrahim’den kendinize bir namaz yeri edinin. İbrahim ve İsmail’e: “Tavaf edenler, kendini ibadete verenler, rükû ve secde edenler için evimi (Kâbe’yi) tertemiz tutun!" diye emrettik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 126, 'Hani İbrahim: "Rabbim! Bu şehri güvenli bir şehir kıl! Halkından Allah’a ve ahiret gününe iman edenleri çeşitli ürünlerle rızıklandır" demişti. Allah da: “İnkâr edeni az bir süre (bu geçici kısa hayatta) rızıklandırır, sonra onu Cehennem azabına girmek zorunda bırakırım. Ne kötü varılacak yerdir orası!” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (2, 127, 'Hani İbrahim, İsmail’le birlikte Kâbe’nin temellerini yükseltiyor (ve şöyle dua ediyorlardı): "Rabbimiz! Bizden bu (amelimizi) kabul buyur. Şüphesiz sen hakkıyla işitensin, hakkıyla bilensin."');
INSERT INTO verses (sura, aya, text) VALUES (2, 128, 'Rabbimiz! Bizi sana teslim olan iki kul eyle ve soyumuzdan da sana teslim olan bir ümmet çıkar. Bize ibadet yollarımızı göster ve tevbelerimizi kabul et! Zira tevbeleri kabul edip, çokça rahmet eden ancak sensin!');
INSERT INTO verses (sura, aya, text) VALUES (2, 129, 'Rabbimiz! İçlerinden senin ayetlerini onlara okuyan, kitap ve hikmeti öğreten ve onları (şirkten) arındıran bir rasûl gönder. Şüphesiz Aziz ve Hakim olan ancak sensin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 130, 'Kendini bilmezden başka İbrahim’in dininden kim yüz çevirir? Andolsun, biz İbrahim’i bu dünyada seçkin kıldık. Şüphesiz o ahirette de salih kimselerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 131, 'Rabbi ona: “Teslim ol”! dediğinde, "Âlemlerin Rabbine teslim oldum" demişti.');
INSERT INTO verses (sura, aya, text) VALUES (2, 132, 'İbrahim, bunu kendi oğullarına da vasiyet etti. Ya''kûb da öyle yaptı ve: “Oğullarım! Allah, sizin için bu dini (İslâm’ı) seçti. Siz de ancak Müslümanlar olarak can verin!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 133, 'Yoksa siz Ya''kûb’un, ölüm döşeğinde iken çocuklarına: “Benden sonra kime ibadet edeceksiniz?” dediği, onların da: “Senin ilâhına ve ataların İbrahim, İsmail ve İshak’ın ilâhı olan tek bir ilâha ibadet edeceğiz. Bizler O’na boyun eğmiş müslümanlarız.” dedikleri zaman orada hazır mı bulunuyordunuz?');
INSERT INTO verses (sura, aya, text) VALUES (2, 134, 'Onlar bir ümmetti gelip, geçti. Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorumlu tutulacak değilsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 135, 'Yahudi ve Hıristiyan olun ki, doğru yolu bulasınız, demektedirler. Sen de ki: "Hayır! Hanif (her türlü batıl dinden uzak durup, yalnızca hak dine yönelen kimse) olarak, İbrahim’in dinine (tabi oluruz). O, müşriklerden değildi."');
INSERT INTO verses (sura, aya, text) VALUES (2, 136, 'Deyin ki: ''''Biz Allah’a, bize indirilene (Kur’an’a), İbrahim, İsmail, İshak, Ya''kûb ve torunlarına indirilene, Mûsâ ve İsa’ya verilen (Tevrat ve İncil) ile bütün diğer peygamberlere Rablerinden verilene iman ettik. Onlardan hiçbirini diğerinden ayırt etmeyiz ve biz ona teslim olmuş kimseleriz.''''');
INSERT INTO verses (sura, aya, text) VALUES (2, 137, 'Eğer onlar (Yahudi ve Hıristiyanlar) böyle sizin iman ettiğiniz gibi iman ederlerse, gerçekten doğru yolu bulmuş olurlar; yüz çevirirlerse onlar elbette derin bir ayrılığa düşmüş olurlar. Allah, onlara karşı sana yeter. O, hakkıyla işitendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 138, 'Allah’ın boyası (dini ile boyanmaya bakın) Kimin boyası/dini Allah’ınkinden daha güzel olabilir? Biz yalnız ona ibadet edenleriz.''''');
INSERT INTO verses (sura, aya, text) VALUES (2, 139, 'Onlara (Ehl-i kitaba) de ki: ''''Allah hakkında mı bizimle tartışıp duruyorsunuz? Halbuki O, bizim de Rabbimiz, sizin de Rabbinizdir. Bizim yaptıklarımız bize, sizin yaptıklarınız da size aittir. Biz O’na gönülden bağlanmış kimseleriz.''''');
INSERT INTO verses (sura, aya, text) VALUES (2, 140, 'Yoksa siz, İbrahim’in, İsmail’in, İshak’ın, Ya''kûb''un ve torunlarının, Yahudi yahut Hristiyan olduklarını mı söylüyorsunuz? (Onlara) De ki: Siz mi daha iyi bilirsiniz, yoksa Allah mı? Allah tarafından kendisine bildirilen gerçeği gizleyenden daha zalim kim vardır? Allah yaptıklarınızdan gâfil değildir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 141, 'Onlar bir ümmetti gelip, geçti. Onların kazandıkları kendilerinin, sizin kazandıklarınız sizindir. Siz onların yaptıklarından sorumlu tutulacak değilsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 142, 'İnsanlardan bazı akılsızlar şöyle diyeceklerdir: "Onları şimdiye kadar yöneldikleri kıblelerinden çeviren nedir?" De ki: "Doğu da, batı da Allah''ındır. O, dilediğini doğru yola iletir."');
INSERT INTO verses (sura, aya, text) VALUES (2, 143, 'Böylece, sizler insanlara birer şahit olasınız ve Peygamber de size şahit olsun diye, sizi orta yollu bir ümmet kıldık. Her ne kadar Allah’ın doğru yolu gösterdiği kimselerden başkasına bu ağır gelse de biz, yönelmekte olduğun kıbleyi ancak; Peygamber’e uyanlarla, yüz çevirip geri dönenleri ayırt edelim diye kıble yaptık. Allah, imanınızı (namazınızı) boşa çıkaracak değildir. Şüphesiz Allah, insanlara karşı çok şefkatli ve çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 144, '(Ey Muhammed!) Biz, senin yüzünü çok defa semaya doğru çevirip durduğunu görüyoruz. Elbette seni razı olacağın bir kıbleye döndüreceğiz. Artık yüzünü Mescid-i Haram tarafına çevir. (Ey Müslümanlar!) Sizler nerede olursanız olun, (namazda) yüzünüzü ona doğru çevirin. Şüphesiz kendilerine kitap verilenler de, bunun Rableri katından gelmiş bir gerçek olduğunu bilmektedirler. Allah onların yaptıklarından habersiz değildir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 145, 'Andolsun ki sen, kendilerine kitap verilmiş olanlara her türlü delili de getirsen, onlar yine de senin kıblene uymazlar. Sen de onların kıblesine uyacak değilsin. Zaten onlar da birbirlerinin kıblesine uymazlar. Andolsun ki, eğer sana gelen bunca ilimden sonra onların arzularına uyarsan, şüphesiz o zaman zalimlerden olursun.');
INSERT INTO verses (sura, aya, text) VALUES (2, 146, 'Kendilerine kitap verdiklerimiz, peygamberi, kendi çocuklarını tanıdıkları gibi tanırlar. Buna rağmen onların bir kısmı, gerçeği bile bile gizlerler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 147, 'Gerçek, senin Rabbinden gelendir. Öyleyse sakın şüpheye düşenlerden olma!');
INSERT INTO verses (sura, aya, text) VALUES (2, 148, 'Her bir ümmetin yöneldiği bir yön vardır. Öyleyse sizler, hayır işlerinde yarışın. Nerede olursanız olun, sonunda Allah sizi huzurunda toplayacaktır. Şüphesiz Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (2, 149, 'Nereden yola çıkarsan çık, namazda yüzünü Mescid-i Haram''a doğru çevir. Şüphesiz bu, Rabbinden gelen bir gerçektir. Allah, sizin yaptıklarınızdan asla habersiz değildir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 150, '(Ey Rasûlüm!) Nereden yola çıkarsan çık, (namazda) yüzünü Mescid-i Haram yönüne çevir. Siz de nerede olursanız olun, yüzünüzü o yöne doğru çeviriniz ki; zalim olanları müstesna, insanların aleyhinizde bir delili bulunmasın. Onlardan korkmayın, sadece benden korkun. Böylece size olan nimetimi tamamlayayım da belki doğru yolu bulursunuz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 151, 'Nitekim içinizden size ayetlerimizi okuyan, sizi tertemiz yapan, size kitabı, hikmeti ve bilmediğiniz şeyleri öğreten, sizden bir elçi gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (2, 152, 'O halde yalnız beni anın ki, ben de sizi anayım. Bana şükredin ve sakın bana nankörlük etmeyin!');
INSERT INTO verses (sura, aya, text) VALUES (2, 153, 'Ey iman edenler! Sabrederek ve namaz kılarak Allah''tan yardım dileyin! Şüphesiz ki Allah, sabredenlerle beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 154, 'Allah yolunda öldürülenlere “ölüler” demeyin. Bilakis onlar diridirler, fakat siz anlayamazsınız.');
INSERT INTO verses (sura, aya, text) VALUES (2, 155, 'Andolsun ki sizi, biraz korku, biraz açlık, biraz da mallardan, canlardan ve mahsullerden yana eksiklikle imtihan edeceğiz. Sabredenleri müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (2, 156, 'Onlar ki, başlarına bir musibet geldiği zaman "Muhakkak biz Allah''a aitiz ve şüphesiz O''na geri döneceğiz" derler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 157, 'Onlar, Rablerinden övgü ve rahmete mazhar olanlardır. İşte onlar, doğru yolu bulanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 158, 'Şüphesiz Safâ ve Merve Allah''ın nişanelerindendir. Her kim Kâbe’de hac veya umre yaparsa, o ikisini tavaf etmesinde de bir sakınca yoktur. Kim gönülden bir iyilik yaparsa, muhakkak ki Allah şükrün karşılığını veren ve her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 159, 'İndirdiğimiz apaçık delilleri ve dosdoğru yolu, kitapta insanlara açıkladıktan sonra gizleyenlere gelince, onlara Allah da lanet eder, bütün lanet ediciler de lanet ederler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 160, 'Ancak tövbe edip ıslah edenler ve gizlediklerini beyan edenler bundan müstesnadır. Çünkü ben onların tövbelerini kabul ederim. Zira ben tövbeleri çokça kabul edip pek çok merhamet edenim.');
INSERT INTO verses (sura, aya, text) VALUES (2, 161, 'İnkâr etmiş ve kâfir olarak can vermiş olanlara gelince, işte Allah''ın, meleklerin ve bütün insanların laneti onların üzerinedir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 162, 'Onlar ebedî olarak lanet içinde kalırlar. Artık onların ne azapları hafifletilir, ne de bir mühlet verilir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 163, 'Sizin ilahınız tek bir ilahtır. Ondan bir başka hak ilah yoktur. O, Rahmân ve Rahîm olandır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 164, 'Şüphesiz göklerin ve yerin yaratılışında, gece ve gündüzün birbirinin ardınca gelişinde, insanların faydalanacağı şeyleri denizde taşıyıp giden gemilerde, Allah''ın gökten indirdirerek ölmüş olan yeryüzünü dirilttiği suda, ardından orada bütün hayvanları yaymasında, gök ile yer arasında Allah''ın emrine boyun eğmiş rüzgârları ve bulutlar yönlendirmesinde, aklını kullanan bir topluluk için nice deliller vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 165, 'İnsanların bir kısmı da, Allah''tan başkalarını O''na denk tutarak, onları, Allah''ı sever gibi severler. İman edenlerin Allah''a olan sevgileri ise (onlarınkinden) daha fazladır. Keşke o zalimler, azapla yüz yüze geldiklerinde anlayacakları gibi bütün gücün yalnızca Allah''ın olduğunu ve Allah''ın azabının çok çetin olduğunu bir bilselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 166, 'O zaman kendilerine uyulanlar, kendilerine uyanlardan uzaklaşacak, azabı görecekler ve aralarındaki bağlar da kopmuş olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 167, '(Kötülere) Uyanlar şöyle derler: “Keşke dünyaya bir dönüşümüz olsaydı da onların şimdi bizden uzaklaştıkları gibi, biz de onlardan uzaklaşsaydık.” Böylece Allah, onlara işledikleri fiilleri pişmanlık kaynağı olarak gösterir. Onlar ateşten çıkacak da değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 168, 'Ey insanlar! Yeryüzündeki temiz ve helal şeylerden yiyin. Şeytan''ın adımlarına uymayın! Zira o sizin için apaçık bir düşmandır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 169, 'Muhakkak ki o size, kötülüğü, hayâsızlığı ve Allah hakkında bilmediğiniz şeyleri söylemenizi emreder.');
INSERT INTO verses (sura, aya, text) VALUES (2, 170, 'Onlara, (Müşriklere) “Allah''ın indirdiği kitaba uyunuz!” dendiği zaman, “Hayır, biz atalarımızın yoluna uyarız” derler. Ya ataları akıl erdiremeyen ve doğru yolda olmayan kimseler idiyseler?');
INSERT INTO verses (sura, aya, text) VALUES (2, 171, '(Hidayet çağrısına kulak vermeyen) kâfirlerin durumu, çobanların çağırdığı fakat, onun bağırıp çağırışından başka bir şey işitmeyen (bir şey anlamayan) hayvanların durumu gibidir. Onlar öyle sağır, dilsiz ve körlerdir ki akıllarını kullanmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 172, 'Ey iman edenler! Size verdiğimiz rızıkların temiz olanlarından yiyin ve eğer sadece Allah''a ibadet ediyorsanız, O''na şükredin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 173, 'Allah size, ölüyü, kanı, domuz etini ve Allah''tan başkası adına kesilen hayvanları haram kıldı. Kim bunları yemeye mecbur kalırsa, taşkınlık etmemek, aşırı gitmemek şartıyla bunlardan yemesinde bir günah yoktur. Şüphesiz Allah çok bağışlayıcı ve merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 174, 'Allah''ın indirdiği kitaptan bir şey gizleyip de, onu az bir kazanç karşılığı değiştirenlere gelince, onlar karınlarını Cehennem ateşinden başka bir şeyle doldurmuyorlar. Kıyamet günü Allah onlarla konuşmayacak ve onları temize çıkarmayacaktır. Onlar için elem verici bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 175, 'Onlar doğru yolu bırakıp sapıklığı; mağfireti bırakıp azabı satın alan kimselerdir. Ateşe karşı ne kadar dayanıklıdırlar!');
INSERT INTO verses (sura, aya, text) VALUES (2, 176, 'Bu azabın sebebi şudur: Şüphesiz Allah, bu kitabı hak olarak indirmiştir. O kitap hakkında ihtilafa düşenler elbette haktan uzak bir ayrılık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 177, 'Yüzlerinizi doğu ve batı yönüne döndürmeniz iyilik değildir. Fakat iyilik Allah’a, ahiret gününe, meleklere, kitaba ve peygamberlere iman eden, malına olan sevgisine rağmen; akrabaya, yetimlere, yoksullara, yolda kalmışlara, isteyenlere, kölelere ve esirlere veren, namazı dosdoğru kılan, zekâtı veren, sözleştikleri zaman sözlerini yerine getiren, sıkıntıda, hastalıkta ve savaşta sabredenlerin yaptıklarıdır. İşte doğru ve takvalı olanlar onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 178, 'Ey İman edenler! Öldürülenler hakkında size kısas farz kılındı. Hür olan ile hür, köle ile köle, kadın ile kadın. Öldüren kişi, kardeşi (maktulün velisi) tarafından bağışlanmışsa artık ona örfe uymak ve bağışlayana güzellikle diyet ödemek gerekir. Bu, Rabbinizden bir hafifletme ve rahmettir. Bundan sonra da haddi aşan kimseye elem verici azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 179, 'Ey akıl sahipleri! Kısasta sizin için hayat vardır. Umulur ki sakınırsınız.');
INSERT INTO verses (sura, aya, text) VALUES (2, 180, 'Sizden birinize ölüm geldiği zaman, eğer geriye bir mal bırakacaksa; anaya, babaya, yakınlara uygun bir biçimde vasiyet etmek, muttakiler üzerine farz kılındı.');
INSERT INTO verses (sura, aya, text) VALUES (2, 181, 'Vasiyeti işittikten sonra onu değiştiren olursa da, bunun günahı değiştirenlerin üzerinedir. Allah, şüphesiz işiten ve bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 182, 'Vasiyet edenin yanlış yada haksız bir paylaşım yapmasından endişe duyan kimse (tarafların) aralarını düzeltmesinde bir günah yoktur. Şüphesiz Allah, çok bağışlayıcı ve çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 183, 'Ey İman edenler! Oruç, sizden öncekilere farz kılındığı gibi, Allah’a karşı takva sahibi olursunuz diye size de farz kılındı.');
INSERT INTO verses (sura, aya, text) VALUES (2, 184, 'Oruç, sayılı günlerdir. İçinizden hasta veya yolcu olanlar, tutamadığı günlerin sayısınca diğer günlerde tutsun. Oruca dayanamayanlar ise, bir yoksul doyuracak kadar fidye versin. Kim gönülden bir iyilik yaparsa, o iyiliği kendine yapmıştır. Şunu bilin ki; oruç tutmanız sizin için daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 185, 'Ramazan ayı, insanlara yol gösterici, doğrunun ve doğruyu eğriden ayırmanın açık delilleri olarak Kur''an''ın indirildiği aydır. Öyle ise sizden ramazan ayını idrak edenler onda oruç tutsun. Kim o anda hasta veya yolcu olursa (tutamadığı günler sayısınca) başka günlerde kaza etsin. Allah sizin için kolaylık ister, zorluk istemez. Bütün bunlar, sayıyı tamamlamanız ve size doğru yolu göstermesine karşılık, Allah''ı tekbir/tazim etmeniz, şükretmeniz içindir');
INSERT INTO verses (sura, aya, text) VALUES (2, 186, 'Kullarım sana beni sorarlarsa; şüphe yok ki ben çok yakınım. Bana dua ettiği zaman, dua edenin duasına karşılık veririm. O halde onlar da benim davetime icabet etsinler ve bana iman etsinler ki, doğru yolda olsunlar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 187, 'Oruç gecesi kadınlarınıza yaklaşmanız size helal kılındı. Onlar sizin örtünüzdür, siz de onların örtüsüsünüz. Allah, nefsinize ihanet etmekte olduğunuzu biliyordu. Bu sebeple, tevbenizi kabul edip sizi bağışladı. Artık onlara yaklaşın ve Allah’ın sizin için takdir ettiğini dileyin. Fecir vakti geldiğinde beyaz iplik, siyah iplikten ayırt edilinceye kadar yiyin için, sonra geceye kadar orucu tamamlayın! Sizler, mescitlerde itikâfa çekilmiş olduğunuz halde kadınlarınıza yaklaşmayın! Bunlar, Allah''ın koyduğu sınırlardır. Bu sınırlara yaklaşmayın! İşte Allah, kötülüklerden korunmaları için insanlara ayetlerini böylece açıklar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 188, 'Aranızda birbirinizin mallarını haksız yere yemeyin. İnsanların mallarından bir kısmını bile bile günaha girerek yemek için onları hâkimlere/yöneticilere (rüşvet olarak) vermeyin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 189, 'Sana hilal şeklinde yeni doğan aylar hakkında soru sorarlar. De ki: Onlar, insanlar ve hac için vakit ölçüleridir. İyilik, evlere arkasından girmeniz değildir. Fakat iyilik, kötülükten sakınan kimsenin yaptığıdır. Evlere kapılarından girin. Allah’tan da sakının ki, kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 190, 'Allah yolunda sizinle savaşanlarla siz de savaşın, fakat aşırı gitmeyin. Doğrusu Allah aşırı gidenleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (2, 191, 'Sizinle savaşanları nerede yakalarsanız öldürün. Onları, sizi çıkardıkları yerden çıkarın. Fitne, öldürmekten daha kötüdür. Onlar, Mescid-i Haram’ın yanında sizinle savaşmadıkça, siz de onlarla orada savaşmayın. Fakat, onlar sizinle orada savaşırlarsa onlarla savaşın. İşte kâfirlerin cezası budur.');
INSERT INTO verses (sura, aya, text) VALUES (2, 192, 'Eğer savaşmaktan vazgeçerlerse; şüphesiz ki Allah, çok bağışlayıcı ve çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 193, 'Fitne kalmayıncaya, din/ibadet yalnız Allah''a yapılıncaya kadar, onlarla savaşın. Eğer savaşa son verirlerse zalimlerden başkasına düşmanlık yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (2, 194, 'Haram ay, haram aya karşılıktır ve hürmetli olan şeylere karşılık kısas vardır. O halde size saldırana, onun size saldırdığı gibi siz de saldırın. Allah’tan sakının ve Allah’ın takva sahipleriyle beraber olduğunu bilin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 195, 'Allah yolunda infak edin. Kendi ellerinizle kendinizi tehlikeye atmayın. İşlerinizi iyi yapın. Şüphesiz Allah ihsan sahiplerini sever.');
INSERT INTO verses (sura, aya, text) VALUES (2, 196, 'Haccı da, umreyi de Allah için tamamlayın. Eğer haccı tamamlamaktan alıkonursanız, oraya kolayınıza gelen bir kurban gönderin. Kurban yerine ulaşıncaya kadar da başlarınızı tıraş etmeyin. İçinizden hasta olan ya da başından bir rahatsızlığı bulunan kimse, oruç, sadaka veya kurban olarak fidye ödesin. Güven içinde olduğunuzda hacca kadar umre ile faydalanmak isteyen kimse, kolayına gelen bir kurban kessin. Bunu bulamayan hac esnasında üç gün, döndüğü vakit de yedi gün -ki bu tam on gün eder- oruç tutsun. Bu, ailesi Mecsid-i Haram’da oturmayan kimseler içindir. Allah’tan sakının ve Allah’ın cezasının şiddetli olacağını bilin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 197, 'Hac bilinen aylardadır. Kim bu aylarda niyet ederek hacca başlarsa bilmelidir ki, hacda hanımlarınıza yaklaşmak, günah işlemek ve tartışmak yasaktır. Allah yaptığınız bütün iyilikleri bilir. Sizler (hac için gereken masraflarınızı) yol azığınızı hazırlayın. Şüphesiz azığın en hayırlısı takvadır. Ey akıl sahipleri! Benden korkun.');
INSERT INTO verses (sura, aya, text) VALUES (2, 198, 'Rabbinizden (hac ibadeti sırasında ticaret yaparak) rızık istemenizde herhangi bir günah yoktur. Arafat’tan ayrılınca Meş’ar-i Haram’da/Müzdelife''de Allah’ı zikredin. Nitekim O, size hidayet etmeden önce gerçekten dalalette olanlardan idiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 199, 'Sonra insanların akıp geldiği yerden siz de akıp gelin. Allah''tan bağışlanmanızı isteyin. Çünkü Allah çok bağışlayıcıdır, çok merhamet edicidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 200, 'Hac ibadetinizi bitirince atalarınızı andığınız gibi, hatta daha da kuvvetli bir anışla Allah’ı zikredin. İnsanlardan: "Rabbimiz! Bize bu dünyada ver." diyen vardır. Onun ahirette hiçbir nasibi yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (2, 201, 'İnsanlardan: “Rabbimiz! Bize bu dünyada da iyilik ver, ahirette de iyilik ver ve bizi ateşin azabından koru!” diyen kimseler de vardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 202, 'İşte onlara, kazançlarından ötürü bir pay/karşılık vardır. Nitekim Allah, hesabı çok çabuk görür.');
INSERT INTO verses (sura, aya, text) VALUES (2, 203, 'Allah’ı sayılı günlerde de anın. Günahtan sakınan kimseye, acele edip (Mina’daki ibadeti) iki günde bitirse de günah yoktur, geri kalsa da günah yoktur. Allah’tan sakının, O''nun huzurunda toplanacağınızı bilin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 204, 'İnsanlardan öyleleri vardır ki, dünya hayatı hakkında konuştuklarında bu senin hoşuna gider. Hatta böylesi kalbindekilerine (samimi olduğuna) Allah''ı şahit tutar. Halbuki o, hasımların en yamanıdır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 205, 'Senin yanından ayrılınca yeryüzünde bozgunculuk yapmaya, ekini ve nesli yok etmeye çalışır. Allah bozgunculuğu sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (2, 206, 'Ona, Allah’tan kork, denince gururu kendisine günah işletir. Ona Cehennem yeter. Gerçekten (orası, varılacak) yerin en kötüsüdür.');
INSERT INTO verses (sura, aya, text) VALUES (2, 207, 'İnsanlar arasında, Allah’ın rızasını kazanmak için canını feda edenler vardır. Allah kullarına karşı çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 208, 'Ey iman edenler! Hep birden İslam dinine tümüyle eksiksiz girin, Şeytan''ın adımlarına uymayın! O sizin apaçık düşmanınızdır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 209, 'Eğer size apaçık deliller geldiği halde yine de hata ederseniz, bilin ki Allah Azîz''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 210, 'Bulut gölgeleri ile birlikte Allah’ın ve meleklerin gelmesini ve işin bitirilmesini mi bekliyorlar? Bütün işler Allah’a döndürülüp götürülecektir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 211, 'İsrâiloğulları''na bir sor, onlara apaçık nice ayetler verdik. Kim, Allah’ın nimeti kendisine ulaştıktan sonra onu değiştirirse, şüphesiz Allah’ın cezası çok şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 212, 'Dünya hayatı kâfirlere süslü gösterildi. Bu yüzden iman edenlerle alay ederler. Oysa takva sahipleri, kıyamet günü onların çok üstündedirler. Allah dilediğine hesapsız rızık verir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 213, 'İnsanlar tek bir ümmetti. Sonra Allah, müjdeleyici ve uyarıcı olarak peygamberleri gönderdi ve insanların ayrılığa düştükleri hususlarda aralarında hükmetmesi için onlarla birlikte hak olan kitaplar indirdi. Ancak kitap gönderilenler, kendilerine apaçık deliller geldikten sonra aralarındaki hırs ve kıskançlık yüzünden onda ayrılığa düştüler. Allah ise iman edenleri, onların hakkında ayrılığa düştükleri doğruya kendi izniyle ulaştırdı. Allah, dilediğini doğru yola iletir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 214, '(Ey Müminler) sizden önce gelenlerin durumu, sizin başınıza gelmeden Cennet''e gireceğinizi mi zannettiniz? Onlara öyle yoksulluk ve sıkıntı geldi ve öyle sarsıldılar ki, hatta Peygamber ve beraberindeki Müminler; "Allah''ın yardımı ne zaman?" dediler. İyi bilin ki Allah’ın yardımı yakındır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 215, 'Sana (Allah yolunda) sadaka olarak ne vereceklerini soruyorlar. De ki: Hayırdan infak edeceğiniz şey; anaya, babaya, akrabaya, yetimlere, yoksullara ve yolda kalmışlaradır. Hayır olarak yaptığınız şeyleri, Allah şüphesiz en iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 216, 'Sizin için hoş olmasa da savaş size farz kılındı. Olabilir ki sizin hoşlanmadığınız bir şey, sizin için iyidir ve ihtimal ki sizin hoşlandığınız bir şey sizin için kötüdür. Siz bilmezsiniz Allah bilir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 217, 'Sana haram ayı onda savaşmayı soruyorlar. De ki: O ayda savaşmak büyük suçtur, Allah yolundan alıkoymak, onu inkâr etmek, Mescid-i Haram’a (girmeye) engel olmak ve halkını oradan çıkarmak Allah katında daha büyük suçtur. Fitne (çıkarmak)/şirk ise, öldürmekten daha büyüktür. Güçleri yeterse sizi dininizden döndürünceye kadar sizinle savaşmaya devam ederler. Sizden kim dininden dönüp, kâfir olarak ölürse, işte onlar, amelleri dünyada ve ahirette boşa gidenlerdir. İşte onlar ateş ehlidir. Orada ebedi kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 218, 'Şüphesiz iman edenler, hicret edenler ve Allah yolunda cihat edenler, işte onlar Allah’ın rahmetini umarlar. Allah günahları bağışlayandır, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 219, 'Sana içki ve kumarı soruyorlar. De ki: Onlarda büyük günah ve insanlara bazı faydalar vardır. Günahları faydasından daha büyüktür. Ne sarf edeceklerini sana soruyorlar. De ki: İhtiyaçtan fazlasını! İşte Allah, size düşünesiniz diye ayetleri (böyle) açıklıyor.');
INSERT INTO verses (sura, aya, text) VALUES (2, 220, 'Hem dünya ve hem de ahiret konusunda sana yetimleri soruyorlar. De ki: Onların işlerini düzeltmek hayırlıdır. Eğer onları aranıza katarsanız artık onlar sizin kardeşlerinizdir. Allah, bozanla düzelteni bilir. Allah dileseydi (yetimlerle bir arada yaşama işiyle) sizi zora sokardı. Şüphesiz Allah güçlüdür, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 221, 'İman etmedikleri sürece Allah’a ortak koşan (müşrik) kadınlarla evlenmeyin. Şundan emin olun ki Mümin bir cariye, sizin hoşunuza gitse de müşrik bir hür kadından iyidir. İman etmedikleri sürece müşrik erkeklerle de kadınlarınızı evlendirmeyin. Şundan da emin olun ki imanlı bir köle, sizin hoşunuza gitse bile müşrik bir hür kişiden daha iyidir. Onlar insanları ateşe çağırırlar, Allah ise izni ile cennete ve bağışlanmaya çağırır, gerektikçe hatırlasınlar diye insanlara ayetlerini açıklar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 222, 'Sana, kadınların aybaşı halinden soruyorlar. De ki: “O bir rahatsızlıktır. Bu sebeple adet halindeyken kadınlardan uzak durun ve temizlenene kadar onlara yaklaşmayın. Temizlendikleri zaman da Allah’ın size buyurduğu yoldan yaklaşın.” Şüphesiz Allah, daima tövbe edenleri sever ve temizlenenleri de sever.');
INSERT INTO verses (sura, aya, text) VALUES (2, 223, 'Kadınlar sizin tarlanızdır, o halde tarlanıza dilediğiniz gibi varın. Kendiniz için ileriye yönelik hazırlık yapın. Allah’tan korkun ve O’na kavuşacağınızı bilin. Müminlere müjde ver.');
INSERT INTO verses (sura, aya, text) VALUES (2, 224, 'Allah adına yaptığınız yeminlerinizi iyilik etmeye, günahlardan uzak durmaya ve insanların arasını düzeltmeye engel yapmayın. Allah, her şeyi hakkıyla işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 225, 'Allah sizi, kasıtsız olarak yaptığınız yeminlerden dolayı sorumlu tutmaz. Lâkin kalplerinizin kasıtlı yaptığı yeminlerden dolayı sizi sorumlu tutar. Allah çok bağışlayandır, çok şefkat ve merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 226, 'Kadınlarına yaklaşmamaya yemin edenlerin dört ay bekleme süreleri vardır. Eğer yeminlerinden dönerlerse, şüphesiz Allah, çokça bağışlayandır, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 227, 'Eğer boşanmaya karar verirlerse şüphesiz Allah hakkıyla işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 228, 'Boşanmış kadınlar, kendi başlarına üç (adet) dönemi beklerler. Eğer onlar Allah’a ve ahiret gününe iman etmişlerse, Allah’ın kendi rahimlerinde yarattığını gizlemeleri helal değildir. Eğer, bu süre içinde barışmak isterlerse kocaları onları almaya daha çok hak sahibidirler. Erkeklerin hanımları üzerinde bulunan hakları gibi, hanımların da kocaları üzerinde meşrû çerçevede hakları vardır. Erkekler, kadınlardan bir derece daha üstündürler. Allah, mutlak galiptir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 229, '(Dönüş yapılabilecek) boşama iki defadır. Sonrası ya iyilikle geçinmek, ya da güzellikle bırakmaktır. (Evlilikte) tarafların Allah’ın belirlediği ölçüleri koruyamama endişeleri dışında kadınlara verdiklerinizden (boşanma esnasında) bir şeyi geri almanız sizin için helâl olmaz. Eğer onlar Allah’ın belirlediği ölçüleri gözetmeyecekler diye endişe ederseniz, o zaman kadının (boşanmak için) bedel vermesinde ikisine de günah yoktur. Bunlar Allah’ın koyduğu sınırlardır. Sakın bunları aşmayın. Allah’ın koyduğu sınırları kim aşarsa, onlar zalimlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 230, 'Eğer erkek karısını (üçüncü defa) boşarsa; kadın, onun dışında bir başka kocayla nikâhlanmadıkça ona helâl olmaz. (Bu koca da) onu boşadığı takdirde, onlar (kadın ile ilk kocası) Allah’ın koyduğu ölçüleri gözetebileceklerine inanıyorlarsa tekrar birbirlerine dönüp evlenmelerinde bir günah yoktur. İşte bunlar Allah’ın, anlayan bir toplum için açıkladığı ölçüleridir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 231, 'Kadınları boşadığınızda bekleme süreleri sona ererken ya onları güzellikle tutun, ya da güzellikle bırakın, fakat haklarına tecavüz etmek için onlara zararlı olacak şekilde tutmayın. Böyle yapan şüphesiz kendisine zulmetmiş olur. Allah’ın ayetlerini eğlence edinmeyin. Allah’ın üzerinizdeki nimetini ve size öğüt vermek için indirdiği kitabı, hikmeti düşünün. Allah’tan korkun ve bilin ki Allah, şüphesiz her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 232, 'Kadınları boşadığınız vakit, onlar da bekleme sürelerini bitirince aralarında meşru bir şekilde anlaştıkları takdirde, kocalarıyla birlikte (tekrardan) evlenmelerine engel olmayın. İşte, sizden Allah’a ve ahiret gününe iman edenlere, bununla öğüt veriliyor. Bu, sizin için daha faydalı ve daha temizdir. Allah bilir, siz bilmezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 233, 'Emzirmeyi tamamlamak isteyenler için anneler çocuklarını iki tam yıl emzirirler. Onların (annelerin) yiyeceği, giyeceği, örfe uygun olarak babaya aittir. Hiçbir kimseye gücünün üstünde bir yük ve sorumluluk teklif edilmez. -Hiçbir anne ve hiçbir baba çocuğu sebebiyle zarara uğratılmasın- (Baba ölmüşse) mirasçı da aynı şeyle sorumludur. Eğer (anne ve baba) kendi aralarında danışıp anlaşarak (iki yıl dolmadan) çocuğu sütten kesmek isterlerse, onlara günah yoktur. Eğer çocuklarınızı (bir sütanneye) emzirtmek isterseniz örfe uygun olarak vereceğiniz ücreti güzelce ödediğiniz takdirde size bir günah yoktur. Allah’a karşı gelmekten sakının ve bilin ki Allah, yapmakta olduklarınızı hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 234, 'İçinizden ölenlerin (geride) bırakmış olduğu hanımlar, kendi kendilerine dört ay on gün beklerler. Bekleme müddetlerini bitirdikleri vakit, kendileri hakkında yaptıkları meşru işlerde size bir günah yoktur. Allah yapmakta olduklarınızı bilir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 235, 'Böyle (iddet beklemekte olan) kadınlara kapalı bir şekilde evlenme teklif etmenizde veya içinizden onlarla evlenmeyi geçirmenizde size bir günah yoktur. Allah, sizin onları anacağınızı bilmektedir. Fakat meşru sözler dışında onlarla gizlice sözleşmeyin, müddet sona erene kadar nikâh akdine kalkışmayın. İçinizde olanı Allah’ın bildiğini bilin de, O’ndan çekinin. Allah’ın çokça bağışlayan ve Halim (Kullarına azabı göndermede acele etmez) olduğunu bilin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 236, 'Kadınlara temas edip, dokunmadan ve mehirlerini biçmeden, onları boşarsanız sizin üzerinize bir günah yoktur. Zengin olanlar kendi halince, fakir olanlar da yine kendi halince uygun bir şekilde onları (bir şeyler vererek) faydalandırın. Bu, iyilik sahiplerinin üzerine bir yükümlülüktür.');
INSERT INTO verses (sura, aya, text) VALUES (2, 237, 'Eğer onlara mehir biçer de, temas etmeden onları boşarsanız mehrin yarısı onların hakkıdır. Ancak kadınlar bundan vazgeçer ya da nikâh bağı elinde bulunan erkek, mehrin yarısını ve daha fazlasını bağışlarsa o başka. Mehrin hepsini bağışlamanız takvaya daha uygundur. Aranızdaki iyiliği unutmayın. Allah, şüphesiz yaptıklarınızı hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 238, 'Namazlara ve orta namaza (ikindi namazına) devam edin. Gönülden bağlılık ve saygı ile Allah’ın huzuruna durun.');
INSERT INTO verses (sura, aya, text) VALUES (2, 239, 'Eğer herhangi bir tehlikeden korkarsanız yaya yahut binek üzerinde namaz kılın. Güvene kavuştuğunuz zaman ise, daha önce bilmediğiniz şeyleri size öğrettiği gibi Allah’ı zikredin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 240, 'İçinizden ölüp geriye eşler bırakan erkekler, bir seneye kadar eşleri evlerinden (mirasçılar tarafından) çıkarılmayacak bir geçimlik vasiyet etmiş olmalıdırlar. Şayet kadınlar kendileri çıkarlarsa, kendi haklarında uygun olanı yapmalarından dolayı size bir mesuliyet (günah) yoktur. Allah mutlak galiptir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 241, 'Boşanmış kadınlara örfe uygun şekilde bir geçimlik sağlanmalıdır. Bu muttakiler üzerine bir görevdir. Bu, iyilik sahiplerinin üzerine bir yükümlülüktür.');
INSERT INTO verses (sura, aya, text) VALUES (2, 242, 'Düşünesiniz diye Allah, size ayetlerini işte böyle açıklıyor.');
INSERT INTO verses (sura, aya, text) VALUES (2, 243, 'Binlerce kişi iken ölüm korkusuyla yurtlarından çıkanları görmedin mi? Allah onlara: “Ölün!” dedi, sonra da onları tekrar diriltti. Şüphesiz Allah, insanlara karşı lütuf sahibidir. Ama insanların çoğu şükretmezler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 244, 'Allah yolunda savaşın ve bilin ki; Allah her şeyi işiten ve bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 245, 'Kim Allah rızası için ( karşılığını beklemeden ) gönlünden bir borç verirse ( veya Allah yolunda harcama yaparsa ) bilsin ki ; Allah bunun karşılığını, mükâfaatını kat kat fazlasıyla öder. Rızkı daraltan da genişleten de Allah’tır ve O ‘na döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 246, 'Mûsâ''dan sonra İsrailoğulları''nın ileri gelenlerini görmedin mi? Peygamberlerinden birine: "Bize bir hükümdar gönder de Allah yolunda savaşalım" demişlerdi. Peygamberleri:" Ya, savaş size farz olunca savaşmazsanız?" demişti. "Bizler neden Allah yolunda savaşmayalım ki, biz yurtlarımızdan ve oğullarımızdan uzaklaştırıldık" demişlerdi. Fakat üzerlerine savaş farz kılınınca içlerinden pek azı hariç yüz çevirdiler. Allah, zalimleri şüphesiz bilir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 247, 'Peygamberleri onlara, dedi ki: Allah, Tâlût’u size hükümdar gönderdi. O bizim üzerimize nasıl hükümdar olabilir? Biz hükümdarlığa ondan daha layığız. Ona, malca da bir bolluk verilmemiştir, dediler. Peygamber de: Allah, onu sizin üzerinize seçti, onun bilgisini ve gücünü artırdı. Allah, mülkünü dilediğine verir. Allah’ın lütfu geniştir. O, her şeyi bilendir, dedi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 248, 'Peygamberleri onlara, “Onun hükümdarlığının alameti, size sandığın gelmesidir. Onda Rabbinizden gelen bir huzur, Mûsâ ailesinin ve Hârûn ailesinin bıraktıklarından kalanlar vardır ve onu melekler taşır. Eğer iman etmişseniz, bunda sizin için apaçık delil vardır” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 249, 'Tâlût, ordusuyla birlikte ayrıldığında: "Allah, sizi bir ırmakla imtihan edecektir. Kim sudan içerse benden değildir, sadece eliyle bir avuç almasından başka ondan tatmayan bendendir." dedi. Onlardan pek azı hariç o sudan içtiler. Nihayet Tâlût ve kendisiyle beraber iman edenler ırmağı geçince, ötekiler: "Bugün Câlût’a ve onun ordusuna karşı koyacak gücümüz yok." dediler. Rablerine kavuşacaklarını düşünenler ise: "Nice sayıca az topluluklar, Allah’ın izni ile sayıca çok olan toplulukları yenmişlerdir. Allah sabredenlerle beraberdir." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 250, 'Câlût ve ordusuna karşı çıktıklarında: "Rabbimiz! üzerimize sabır yağdır. Ayaklarımıza sebat ver, bu kâfir topluma karşı bize yardım et, zafer ver!" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (2, 251, 'Neticede Allah’ın izniyle onları bozguna uğrattılar. Dâvut da, Câlût’u öldürdü. Allah, Davut’a hükümdarlık ve hikmet verdi, ona dilediğinden öğretti. Allah’ın insanları birbirleriyle savması olmasaydı, yeryüzünün düzeni bozulurdu. Fakat Allah, âlemlere karşı lütuf sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 252, 'İşte bunlar Allah’ın ayetleridir. Biz onları sana hakkıyla okuyoruz. Şüphesiz sen de gönderilmiş peygamberlerdensin.');
INSERT INTO verses (sura, aya, text) VALUES (2, 253, 'İşte bu rasûller yok mu, biz onların bazısını bazısından üstün kıldık. Allah''ın konuştuğu ve bazılarının da derecelerini yükselttiği kimseler onlardandır. Meryemoğlu İsa''ya apaçık deliller vermiş ve onu Ruhu''l-Kudüs (Cebrâil) ile desteklemişizdir. Eğer Allah dileseydi, bu peygamberlerden sonra gelen milletler, kendilerine gelen apaçık delillerden sonra birbirlerini öldürmezlerdi. Fakat onlar ihtilâfa düştüler. Onlardan bir kısmı iman etti; bir kısmı da küfre girdi. Eğer Allah dileseydi, birbirlerini öldürmezlerdi. Fakat Allah, dilediğini yapar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 254, 'Ey iman edenler! İçinde hiçbir alışverişin, hiçbir dostluğun ve şefâatin olmadığı gün gelmeden önce, size rızık olarak verdiğimiz şeylerden Allah yolunda harcayın. Kâfirler ise, onlar zalimlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 255, 'Allah; O''ndan başka hakkıyla ibadete layık hiçbir hak ilâh olmayandır; Hayy''dır (diridir); Kayyûm''dur. (kendi zâtiyle kâimdir.) O''nu ne bir uyuklama, ne de bir uyku tutar. Göklerde ve yerde ne varsa hepsi O''nundur. İzni olmadan, O''nun yanında kim şefaat edebilir? Onların önünde ve arkasında olan her şeyi bilir. Onlar ise, O''nun dilediği kadarından başka ilminden hiçbir şey kavrayamazlar. O''nun Kürsü''sü gökleri ve yeri kaplamıştır. Onların her ikisini de görüp gözetmek O''na ağır gelmez. O, çok yücedir, çok büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (2, 256, 'Dinde zorlama yoktur. Hak yol, bâtıl yoldan ayrılmıştır. Kim tâğûtu inkâr eder, Allah''a iman ederse, kopması mümkün olmayan en sağlam kulpa tutunmuş olur. Allah, hakkıyla işiten ve hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 257, 'Allah, iman edenlerin dostudur; onları karanlıklardan aydınlığa çıkarır. Kâfirlerin dostları ise tâğûttur, onları aydınlıktan karanlıklara çıkarırlar. İşte onlar cehennemliklerdir. Orada ebedî olarak kalırlar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 258, 'Allah''ın kendisine hükümranlık vermesinden dolayı, rabbi hakkında İbrahim''le tartışanı görmedin mi? İbrahim (ona): "Rabbim hem diriltir, hemde öldürür" deyince; o, "Ben de diriltir ve öldürürüm" demişti. Fakat İbrahim: "Allah, Güneşi doğudan getirir; sen de onu batıdan getir." deyince, o inkâr eden şaşırıp kalmıştı. Allah, zâlimler topluluğunu doğru yola iletmez.');
INSERT INTO verses (sura, aya, text) VALUES (2, 259, 'Yahut altı üstüne gelmiş bir kasabaya uğrayan kimse gibisini görmedin mi? Allah, bunu ölümünden sonra nasıl diriltecek? dedi. Bunun üzerine Allah onu öldürüp yüz sene bıraktı; sonra tekrar diriltti. "Ne kadar kaldın?" dedi. "Bir gün yahut daha az" dedi. Allah ona: "Hayır, yüz sene kaldın. Yiyeceğine ve içeceğine bir bak, henüz bozulmamıştır. Eşeğine de bak. Seni insanlara ibret kılacağız. Kemiklere bak, onları nasıl birleştirip yerli yerine koyuyor ve sonra onlara nasıl et giydiriyoruz?" dedi. Durum kendisince anlaşılınca: "Şimdi iyice biliyorum ki, Allah her şeye kadirdir," dedi.');
INSERT INTO verses (sura, aya, text) VALUES (2, 260, 'Hani İbrahim Rabbine: "Ey Rabbim! Ölüyü nasıl dirilttiğini bana göster." demişti. Rabbi ona: "Yoksa inanmıyor musun?" dedi. İbrahim: "Hayır! İnandım, fakat kalbimin mutmain olması için." demişti. "Öyleyse dört kuş tut, onları yanına al. Sonra (kesip parçala), her dağın başına onlardan bir parça koy. Ardından onları kendine çağır; koşarak sana gelirler. Bil ki şüphesiz Allah Azîz''dir, Hakîm''dir."');
INSERT INTO verses (sura, aya, text) VALUES (2, 261, 'Allah yolunda mallarını harcayanların örneği, yedi başak bitiren bir tane gibidir ki, her başakta yüz tane vardır. Allah dilediğine kat kat verir. Allah, ihsanı bol olandır, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 262, 'Mallarını Allah yolunda infak edip sonra infak ettikleri şeyin ardından başa kakmayan ve eza etmeyenlerin ecirleri Rablerinin katındadır. Onlara korku yoktur ve onlar üzülmeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 263, 'Güzel söz ve bağışlama, arkasından incitme gelen sadakadan daha iyidir. Allah çok zengindir, Halim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 264, 'Ey iman edenler! Allah''a ve ahiret gününe iman etmediği halde malını gösteriş için harcayan kimse gibi, başa kakmak ve incitmek suretiyle yaptığınız hayırlarınızı boşa çıkarmayın. Artık onun durumu, üzerinde biraz toprak bulunan düz kayaya benzer ki, sağanak bir yağmur isabet etmiş de onu çıplak pürüzsüz kaya haline getirivermiştir. Bunlar kazandıklarından hiçbir şeye sahip olamazlar. Allah, kâfirleri doğru yola iletmez.');
INSERT INTO verses (sura, aya, text) VALUES (2, 265, 'Mallarını Allah''ın rızasını kazanmak ve içlerindeki imanı sağlamlaştırmak için sarf edenlerin durumu ise bir tepe üzerindeki bahçenin haline benzer. Kuvvetli bir sağanak düşünce meyvelerini iki kat verir. Bol yağmur isabet etmezse de çisinti vardır. Allah, yaptıklarınızı görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 266, 'Sizden biriniz arzu eder mi ki, hurma ve üzüm ağaçlarıyla dolu, altından ırmaklar akan ve içinde her çeşit meyveden bulunan bir bahçesi olsun da, kendisi ihtiyarlamış, çocukları da güçsüz kalmışken, bahçesi ateşli bir kasırga ile yanıversin. Düşünesiniz diye Allah, size ayetlerini böyle açıklar.');
INSERT INTO verses (sura, aya, text) VALUES (2, 267, 'Ey iman edenler! Gerek kazandıklarınızın ve gerekse yerden sizin için çıkardıklarımızın iyilerinden bağışta bulunun. Göz yummadan alıcısı olmayacağınız kötü şeyleri vermeye kalkışmayın. Bilin ki Allah, hiçbir şeye ihtiyacı olmayan ve hamt edilmeye layık olandır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 268, 'Şeytan sizi fakirlikle korkutur ve size cimriliği telkin eder. Allah ise, size mağfiretini ve bolluk vadediyor. Allah her şeyi kuşatandır ve her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 269, 'O, hikmeti dilediği kimseye verir. Hikmet verilen kimseye pek çok hayır da verilmiştir. Akıl sahiplerinden başkası öğüt alıp düşünmez.');
INSERT INTO verses (sura, aya, text) VALUES (2, 270, 'Yaptığınız her harcamayı ve adadığınız her adağı muhakkak Allah bilir. O gün zalimler için hiç bir yardımcı yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (2, 271, 'Eğer sadakaları açık olarak verirseniz o, ne güzeldir. Şayet onu gizleyip de fakirlere verirseniz, o da sizin için (daha) hayırlıdır. (Allah bununla) günahlarınızı örtüp, bağışlar. Allah, yaptıklarınızdan tamamıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 272, '(Ey Muhammed!) Onları hidayete erdirmek senin üzerine (bir sorumluluk) değildir. Fakat Allah, dilediği kimseyi hidayete erdirir. İyilik olarak her ne verirseniz, o kendiniz içindir. Zaten siz, yalnız Allah’ın rızasını/vechini kazanmak için verirsiniz. İyilik olarak ne verirseniz (bunun karşılığı) size eksiksizce ödenecektir. Ve siz, haksızlığa uğratılmazsınız.');
INSERT INTO verses (sura, aya, text) VALUES (2, 273, '(Sadakalar) Allah yolunda mahsur kalmış, kazanç için yeryüzünde dolaşamayan, çekingenliklerinden dolayı bilmeyenlerin onları zengin zannettikleri, senin de simalarından tanıdığın ısrarlı bir şekilde insanlardan istemeyen fakirler içindir. Hayır olarak ne harcarsanız, şüphesiz Allah onu hakkıyla bilir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 274, 'Gece ve gündüz, gizli ve açık olarak mallarından verenler, işte onlar için Rableri katında mükâfatlar vardır! Onlara korku yoktur, mahzun da olmayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 275, 'Faiz yiyenler, ancak şeytanın çarptığı kimsenin kalktığı gibi kalkarlar. Bu, onların, “Alışveriş de faiz gibidir” demelerinden dolayıdır. Oysa Allah, alışverişi helâl, faizi haram kılmıştır. Bundan böyle kime Rabbinden bir öğüt gelir de (o öğüte uyarak) faizden vazgeçerse, artık önceden aldığı onun olur. Durumu da Allah’a kalmıştır. (Allah, onu affeder.) Kim tekrar (faize) dönerse, işte onlar cehennemliklerdir. Orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 276, 'Allah, faizi yok eder, sadakaları ise bereketlendirir. Allah, hiçbir günahkâr kâfiri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (2, 277, 'Şüphesiz iman edenler, salih amel işleyenler, namazı dosdoğru kılanlar ve zekâtı verenler için Rableri katında mükâfatları vardır. Onlara korku yoktur. Onlar, mahzun da olmayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 278, 'Ey iman edenler! Eğer gerçekten Mümin iseniz, Allah’tan korkun ve faizden geri kalanı bırakın.');
INSERT INTO verses (sura, aya, text) VALUES (2, 279, 'Eğer böyle yapmazsanız, bunun Allah’a ve elçisine karşı açılmış bir savaş olduğunu bilin. Şayet tevbe ederseniz, ana paranız sizindir. (Böylece) zulmetmemiş ve de zulme uğramamış olursunuz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 280, 'Eğer (borçlu) darda ise eli genişleyinceye kadar ona mühlet verin. Sadaka olarak bağışlamanız, bilirseniz sizin için daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 281, 'Allah''a döndürüleceğiniz ve sonra zulme uğramadan herkesin kazancının kendisine eksiksiz verileceği günden korkunuz.');
INSERT INTO verses (sura, aya, text) VALUES (2, 282, 'Ey iman edenler! Belirli bir süreye kadar borçlandığınız zaman onu yazın. Aranızda bir kâtip doğru olarak yazsın. Kâtip, Allah’ın kendisine öğrettiği gibi yazmaktan kaçınmasın, yazsın. (Katibe) borçlu olan yazdırsın. Rabbi olan Allah’tan korksun da ondan hiçbir şeyi eksiltmesin. Eğer borçlu cahil/sefih veya zayıf ya da bizzat kendisi yazdırmaya gücü yetmezse, velisi (onu) dosdoğru yazdırsın. Erkeklerinizden iki de şahit bulundurun. Eğer iki erkek yoksa, razı olacağınız şahitlerden, bir erkek ve biri unuttuğu zaman diğerinin ona hatırlatması için iki kadın şahitler çağrıldıklarında (şahitlik etmekten) kaçınmasınlar. Küçük olsun, büyük olsun borcu süresiyle birlikte yazmaya üşenmeyin. Bu, Allah katında daha adaletli, şahitlik için daha sağlam, şüpheye düşmemeniz için de en isabetli olandır. Ancak aranızda yaptığınız alışverişin peşin bir ticaret olması halinde onu yazmamanızın bir günahı yoktur. Alışveriş yaptığınız zaman da şahit tutun. Yazana da şahide de zarar verilmesin. Eğer bir zarar verirseniz bu şüphesiz, sizin hak yoldan çıkmanız demektir. Allah’tan korkun. Allah (bunları) size öğretmektedir. Allah her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 283, 'Eğer yolculukta iseniz bir kâtip de bulamazsanız, (borca karşılık) alınmış rehinler yeterlidir. Eğer birbirinize güvenirseniz, kendisine güvenilen kimse emanetini ödesin. Şahitliği gizlemeyin; kim onu gizlerse, o mutlaka kalben günahkârdır. Allah, yapmakta olduklarınızı bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (2, 284, 'Göklerde ve yerde ne varsa Allah’ındır. İçinizdekini açıklasanız da gizleseniz de Allah, onunla sizi hesaba çeker. Sonra da dilediği kimseyi bağışlar, dilediği kimseyi de azaba uğratır. Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (2, 285, 'Peygamber, Rabbinden kendisine indirilene iman etmiştir, Müminler de! Hepsi de Allah’a, meleklerine, kitaplarına ve peygamberlerine iman etmiş ve Allah’ın peygamberlerinden hiçbirini (diğerinden) ayırmayız. İşittik ve itaat ettik, demişlerdir. Rabbimiz! Bağışlamanı dileriz, dönüş sanadır.');
INSERT INTO verses (sura, aya, text) VALUES (2, 286, 'Allah, hiç kimseye gücünün üstünde bir şey (sorumluluk) yüklemez. (Herkesin) kazandığı (iyilik) lehine ve işlediği (kötülük) ise aleyhinedir! Rabbimiz, eğer unuttuk veya hata yaptıysak bizi hesaba çekme. Rabbimiz! Bizden öncekilere yüklediğin gibi bize de ağır bir görev yükleme. Rabbimiz! Gücümüzün yetmeyeceğini bize taşıtma. Bizi affet, bizi bağışla ve bize merhamet et. Sen bizim mevlâmızsın. Kâfir topluma karşı bize yardım et.');
INSERT INTO verses (sura, aya, text) VALUES (3, 1, 'Elif, Lâm, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (3, 2, 'Allah, kendisinden başka (ibadet edilmeye layık) hak ilah olmayan, her zaman diri, ölümsüz, bütün varlıkların tek yöneteni ve gözeteni olan tek hak ilahtır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 3, 'O, sana kitabı hak ve önceki kitapları tasdik edici olarak indirdi. Tevrat ile İncil''i de indirmişti.');
INSERT INTO verses (sura, aya, text) VALUES (3, 4, 'Daha önce, insanlar için yol gösterici ve hakkı batıldan ayıran/Furkan''ı da indirmişti. Allah’ın ayetlerini inkâr edenlere, şiddetli bir azap vardır. Allah çok güçlüdür, intikam sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 5, 'Allah’a yer ve gökte olanlardan hiçbir şey gizli kalmaz.');
INSERT INTO verses (sura, aya, text) VALUES (3, 6, 'Ana rahminde size dilediği gibi şekil veren O’dur. Kendinden başka (ibadete layık hak) ilah olmayan, Aziz ve Hakim olan O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (3, 7, 'Sana kitabı indiren O’dur. Onun bir kısmı, muhkem ki bunlar kitabın özüdür. Bir kısmı da müteşabih ayetlerdir. Kalplerinde eğrilik olanlar, fitne çıkarmak ve (kendilerine göre) onun tevilini yapmak için onun müteşabih olanlarına uyarlar. Oysa, onun tevilini Allah’tan başkası bilmez. İlimde derinleşenler ise “Biz, ona iman ettik, onun hepsi Rabbimizin katındandır.” derler. Temiz akıl sahiplerinden başkası düşünmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 8, 'Rabbimiz! Bizi doğru yola ilettikten sonra, kalplerimizi eğriltme. Bize katından rahmet bahşet! Şüphesiz sen, bol bol bahşedensin.');
INSERT INTO verses (sura, aya, text) VALUES (3, 9, 'Rabbimiz! Hakkında şüphe olmayan günde bütün insanları mutlaka toplayacak olan şüphesiz sensin. Şüphesiz ki Allah sözünden asla dönmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 10, 'Şüphesiz kâfir olanlara ne malları ve ne de çocukları Allah''ın (azabına) karşılık hiçbir fayda sağlamaz. İşte bunlar, ateşin yakıtı olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 11, 'Tıpkı Firavun Hanedanı ve onlardan öncekilerin durumu gibi ayetlerimizi yalanladılar da Allah da onları günahları sebebiyle cezalandırdı. Allah, cezası çok çetin olandır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 12, '(Rasûlüm) Kâfirlere de ki: Yakında yenilgiye uğrayacak ve toplanıp Cehennem''e sürüleceksiniz. Orası ne kötü yerleşme yeridir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 13, '(Bedir''de) Karşı karşıya gelen iki toplulukta, sizin için bir ayet vardır. Bunlardan biri Allah yolunda savaşıyordu, diğeri ise kâfir idi. Gözleriyle onların kendilerinin iki misli olduklarını görüyorlardı. Allah, dilediğini yardımıyla güçlendirir. Bunda, basiret sahipleri için gerçekten ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 14, 'Nefsî arzulardan olan, kadınlara, evlatlara, öbek öbek yığılmış altın ve gümüşe, güzel cins atlara, davarlara ve ekinlere karşı aşırı sevgi insanlara çekici ve hoş gösterildi. Oysa bunlar, (fani olan) dünya hayatının nimetleridir. Asıl varılacak güzel yer Allah katındadır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 15, 'De ki: Size, bundan daha hayırlı olanı haber vereyim mi? Allah’tan korkan/günahlardan sakınanlara, altından nehirler akan ebedi kalacakları Cennetler vardır. Tertemiz eşler ve Allah’ın rızası vardır. Allah, kullarını hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 16, 'Onlar: "Rabbimiz! Biz, kesin olarak iman ettik. Bizim günahlarımızı bağışla ve bizi ateşin azabından koru!" derler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 17, '(Onlar): Sabredenler, sadık olanlar, gönülden boyun eğip itaat edenler, sadaka verenler ve seher vakitlerinde bağışlanma dileyenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 18, 'Allah şahittir ki kendisinden başka (ibadet edilmeye layık hak) bir ilah yoktur. Melekler ve adaleti ayakta tutan ilim sahipleri de (buna şahittir.) O’ndan başka (hak) ilah yoktur. O, Aziz''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 19, 'Şüphesiz, Allah katında din İslam’dır. Kendilerine kitap verilenler, kendilerine ilim geldikten sonra, sadece aralarındaki haset ve kıskançlık yüzünden ihtilafa düştüler. Kim Allah’ın ayetlerini inkâr ederse şüphesiz Allah, hesabı çok çabuk görendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 20, 'Seninle tartışmaya girişirlerse de ki: "Ben, bana tabi olanlarla birlikte yüzümü Allah’a teslim ettim." Kendilerine kitap verilenlere ve ümmilere de de ki: "Siz de teslim oldunuz mu?" Eğer teslim oldularsa doğru yolu bulmuşlar demektir. Eğer yüz çevirirlerse, sana düşen yalnızca tebliğdir. Allah kullarını görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 21, 'Allah’ın ayetlerini inkâr edenlere, peygamberleri haksız yere öldürenlere, insanlardan adaleti emredenleri öldürenlere, işte onlara acıklı bir azap müjdesi ver.');
INSERT INTO verses (sura, aya, text) VALUES (3, 22, 'Bunlar, dünya ve ahirette amelleri boşa çıkanlardır. Bunların bir yardımcısı da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (3, 23, 'Kendilerine kitaptan bir pay verilenleri görmedin mi? Aralarında hüküm vermesi için Allah’ın kitabına çağırılıyorlar da sonra onlardan bir kısmı yüz çevirerek dönüp gidiyor.');
INSERT INTO verses (sura, aya, text) VALUES (3, 24, 'Bu, (haktan yüz çeviriş) onların: "Sayılı günlerden başka bize, asla ateş dokunmayacak" demeleri yüzündendir. Ve uydura geldikleri yalanlar, dinlerinde kendilerini aldatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 25, 'Hakkında şüphe olmayan günde, onları bir araya topladığımız ve her nefse yaptığının karşılığının tam verilip asla haksızlığa uğratılmadığı o zaman, halleri nasıl olacak?');
INSERT INTO verses (sura, aya, text) VALUES (3, 26, 'De ki: Ey hakimiyetin yegane maliki Allah’ım! Mülkü dilediğine verirsin, dilediğinden de mülkü çekip alırsın, dilediğini yükseltir/aziz kılarsın, dilediğini de alçaltır/zelil edersin. Bütün hayır senin elindedir, şüphesiz senin her şeye gücün yeter.');
INSERT INTO verses (sura, aya, text) VALUES (3, 27, 'Geceyi gündüze geçirir, gündüzü de geceye sokarsın. Diriyi ölüden çıkarır, ölüyü de diriden çıkarırsın. Dilediğine de hesapsız rızık verirsin.');
INSERT INTO verses (sura, aya, text) VALUES (3, 28, 'Müminler, Müminleri bırakıp kâfirleri veli/dost edinmesinler. Kim böyle yaparsa Allah ile ilişiğini kesmiş olur. Ancak onlardan (gelebilecek tehlikeden) korunmanız başkadır. Allah, asıl sizi kendisi hakkında korkutup uyarmaktadır. Dönüş Allah’adır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 29, 'De ki: İçinizdekini gizleseniz de açıklasanız da onu Allah bilir. Göklerde ve yerde olan her şeyi bilir. Allah’ın her şeye de gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (3, 30, 'Herkes, yaptığı bütün iyilikleri de kötülükleri de karşısında bulacağı o gün isteyecek ki, kötülükleri ile kendi arasında uzun bir mesafe bulunsun. Allah, asıl sizi kendisi hakkında korkutup uyarmaktadır. Allah kullarına karşı da çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 31, 'De ki: Allah’ı seviyorsanız, bana tabi olun ki Allah da sizi sevsin ve günahlarınızı bağışlasın. Allah, çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 32, 'De ki: Allah’a ve Rasûlüne itaat edin! Eğer yüz çevirirlerse, şüphesiz Allah, kâfirleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 33, 'Allah; Âdem’i, Nûh’u, İbrahim ailesini ve İmran Ailesi''ni toplumlar üzerine seçkin kıldı.');
INSERT INTO verses (sura, aya, text) VALUES (3, 34, 'Bunlar birbirlerinin soylarından gelen bir nesildir. Allah, hakkıyla işiten ve hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 35, 'Hani İmran’ın karısı: "Rabbim karnımda olanı sadece sana hizmet etmek üzere adadım, benden bunu kabul buyur. Şüphesiz sen, hakkıyla işitensin, hakkıyla bilensin." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (3, 36, 'Onu doğurunca da: "Rabbim! Ben, kız doğurdum. (Hâlbuki Allah, neyi doğuracağını en iyi bilendir) Erkek, kız gibi değildir. Adını Meryem koydum, O’nu da, onun soyunu da kovulmuş şeytandan sana sığındırıyorum." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (3, 37, 'Rabbi, onu güzel bir kabul ile kabul etti ve onu güzel bir şekilde yetiştirdi. Zekeriya’yı da ona bakmakla görevlendirdi. Zekeriya ne zaman yanına, onun bulunduğu ibadet mahalline girse, O’nun yanında bir yiyecek bulurdu: Meryem, bu sana nereden geldi? dediğinde, o şöyle cevap verirdi: Bu, Allah katından! Doğrusu Allah, dilediği kimseye hesapsız rızık bağışlar.');
INSERT INTO verses (sura, aya, text) VALUES (3, 38, 'Zekeriya orada Rabbine dua etti: "Rabbim! Bana katından tertemiz bir soy ver! Sen duayı en iyi bir şekilde işitensin." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (3, 39, '(Zekeriya) mabedde namaz kılarken melekler ona: “Allah sana, Allah''tan bir kelimeyi (İsa’yı) doğrulayıcı, efendi, nefsine hâkim ve salihlerden bir peygamber olarak Yahya’yı müjdeler!” diye seslendiler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 40, '"Rabbim! Ben iyice yaşlanmış, karım da kısır iken nasıl benim bir oğlum olacak?" dedi. Allah: "Öyle de olsa, Allah dilediğini yapar!" buyurdu.');
INSERT INTO verses (sura, aya, text) VALUES (3, 41, 'Zekeriyya: “Ey Rabbim! Bana bir işaret göster” diye niyaz etti. Allah da: "Senin delilin, üç gün insanlarla işaretle anlaşmak dışında hiç konuşmamandır. Rabbini çokça zikret ve akşam, sabah tesbih et!" buyurdu.');
INSERT INTO verses (sura, aya, text) VALUES (3, 42, 'Hani bir zamanlar da melekler şöyle demişlerdi: "Ey Meryem! Allah seni seçip tertemiz yarattı ve seni dünya kadınlarına üstün kıldı."');
INSERT INTO verses (sura, aya, text) VALUES (3, 43, '"Ey Meryem! Rabbine gönülden boyun eğ, secde et, rükû edenlerle birlikte rükû et!"');
INSERT INTO verses (sura, aya, text) VALUES (3, 44, '(Ey Peygamber!) Bunlar, sana vahyettiğimiz gayb haberlerindendir. Meryem’e hangisi kefil olacak diye kalemlerini atarlarken (kura çekerlerken) sen yanlarında değildin, konuyu tartışırlarken de yanlarında değildin.');
INSERT INTO verses (sura, aya, text) VALUES (3, 45, 'Melekler demişti ki: Ey Meryem! Allah sana adı Mesih Meryemoğlu İsa olan, dünya ve ahirette itibarlı ve öncülerden/mukarrebinden olacak kendisinden bir kelimeyi (İsa’yı) müjdeliyor.');
INSERT INTO verses (sura, aya, text) VALUES (3, 46, 'O, insanlarla beşikte iken de yetişkin iken de konuşacaktır ve o, salihlerden biridir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 47, 'Meryem, şöyle dedi: "Rabbim! Bana bir beşer dokunmamışken nasıl çocuğum olabilir?" (Melek şöyle cevap verdi:) "İşte böyle! Allah neyi dilerse yaratır. Bir işin olmasını isterse ona “ol” der ve o da hemen oluverir."');
INSERT INTO verses (sura, aya, text) VALUES (3, 48, 'O’na kitabı, hikmeti, Tevrat ve İncil’i öğretecektir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 49, 'Ben size Rabbinizden bir ayet ile geldim. Ben size, çamurdan kuş şeklinde bir şey yapıp ona üfleyeceğim. Allah’ın izniyle, o hemen kuş oluverecektir. Allah’ın izniyle kör ve (cildi) alacalı olan (hastaları) iyileştirir ve ölüleri diriltirim. Yediklerinizi ve evlerinizde sakladıklarınızı da size haber vereceğim. Eğer Müminler iseniz bunda sizin için bir delil vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 50, 'Benden önce gelen Tevrat’ı tasdik etmekle beraber size haram edilen şeylerin bir kısmını helal kılmak üzere, Rabbinizden size bir ayet getirdim. Allah’tan korkun ve bana itaat edin!');
INSERT INTO verses (sura, aya, text) VALUES (3, 51, 'Şüphesiz Allah, benim de Rabbim sizin de Rabbinizdir. O’na ibadet edin! Doğru yol budur.');
INSERT INTO verses (sura, aya, text) VALUES (3, 52, 'İsa, onların küfrünü hissedince: "Allah uğrunda bana yardımcı olacak kim vardır?" dedi. Havariler de şöyle cevap verdiler: "Biz Allah’ın yardımcılarıyız, Allah’a iman ettik, O’na teslim olduğumuza da şahit ol!"');
INSERT INTO verses (sura, aya, text) VALUES (3, 53, 'Rabbimiz, indirdiğine iman ettik, peygambere tabi olduk, bizi şahit olanlarla beraber yaz!');
INSERT INTO verses (sura, aya, text) VALUES (3, 54, '(İsrailoğulları) tuzak kurdular (ve buna karşılık) Allah da bir tuzak kurdu. Allah, düzen/tuzak kurucuların en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 55, 'Allah, İsa’ya şöyle buyurmuştu: "Ey İsa! Seni vefat ettireceğim ve seni kendime yükselteceğim. Kâfirlerden seni tertemiz kurtaracağım. Sana tabi olanları kıyamet gününe kadar inkâr edenlerin/kâfirlerin üstünde tutacağım. Sonra bana döneceksiniz. Sizin aranızda, hakkında ihtilaf ettiğiniz konularda hüküm vereceğim."');
INSERT INTO verses (sura, aya, text) VALUES (3, 56, 'O kâfir olanlara gelince, ben onları dünyada da ahirette de en şiddetli bir azaba çarptıracağım ve onların hiçbir yardımcıları da olmayacak.');
INSERT INTO verses (sura, aya, text) VALUES (3, 57, 'İman eden ve salih amel işleyenlere ise eksiksiz mükâfatlarını verecektir. Allah, zalimleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 58, '(Ey Muhammed!) Bunlar sana okuduğumuz âyetlerden ve hikmet dolu Zikir''dendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 59, 'Allah katında (yaratılış olarak) İsa’nın örneği, Âdem’in örneği gibidir. Kendisini topraktan yaratıp sonra ona “Ol!” dedi ve oluverdi.');
INSERT INTO verses (sura, aya, text) VALUES (3, 60, 'Bu gerçek senin Rabbindendir. O halde sakın şüphe edenlerden olma!');
INSERT INTO verses (sura, aya, text) VALUES (3, 61, 'Sana ilim geldikten sonra, bu hususta seninle kim tartışacak olursa, de ki: "Gelin, oğullarımızı, oğullarınızı, kadınlarımızı, kadınlarınızı, kendilerimizi ve kendilerinizi çağıralım. Sonra da dua ederek Allah’ın lanetinin yalancılara olmasını dileyelim."');
INSERT INTO verses (sura, aya, text) VALUES (3, 62, 'Şüphesiz bu anlatılanlar gerçek olan kıssalardır. Allah’tan başka (ibadete layık hak) ilah yoktur. Allah, elbette Aziz''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 63, 'Eğer yüz çevirirlerse şüphesiz Allah, bozguncuları hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 64, 'De ki: “Ey kitap ehli! Bizimle sizin aranızda ortak bir söze gelin: Yalnız Allah’a ibadet edelim. O’na hiçbir şeyi ortak koşmayalım. Allah’ı bırakıp da kimimiz kimimizi ilâh edinmesin.” Eğer onlar yine yüz çevirirlerse, deyin ki: “Şahit olun, biz Müslümanlarız.”');
INSERT INTO verses (sura, aya, text) VALUES (3, 65, 'Ey Ehl-i kitap! İbrahim hakkında niçin tartışıyorsunuz? Tevrat da İncil de şüphesiz ondan sonra indirilmiştir. Akıl etmiyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (3, 66, 'İşte siz böyle kimselersiniz. İlminiz olan şey hakkında tartışıyorsunuz. Ya ilminiz olmayan şey (İbrahim) hakkında neden tartışırsınız? Oysa Allah bilir, sizler bilmezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (3, 67, 'İbrahim bir Yahudi değildi, bir Hıristiyan da değildi. Fakat, hanif (şirkten uzak) bir Müslümandı. Müşriklerden de değildi.');
INSERT INTO verses (sura, aya, text) VALUES (3, 68, 'Doğrusu İbrahim’e en yakın olanlar; ona tabi olanlar ve bu peygambere (Muhammed''e) iman edenlerdir. Allah, Müminlerin velisidir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 69, 'Kitap ehlinden bir kısmı sizi saptırmak isterler. Fakat yalnızca kendilerini yoldan çıkarırlar da bunun farkına varmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (3, 70, 'Ey Ehl-i kitap! (Gerçeğe) şahit olduğunuz halde, niçin Allah’ın ayetlerini inkâr ediyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (3, 71, 'Ey Ehl-i kitap! Niçin hakla batılı karıştırıyor ve bile bile hakkı gizliyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (3, 72, 'Kitap ehlinden bir topluluk: "İman edenlere indirilene günün başında (sabahleyin) iman edin, sonunda (akşamleyin) inkâr edin, belki (dinlerinden) dönerler." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (3, 73, '"Sizin dininize uyanlardan başkasına inanmayın” derler. Ey Rasûlüm! De ki: “Doğru yol, Allah''ın yoludur.” Yine onlar şöyle derler: "(Müslümanlardan) Birine, size verilen ilmi (öğretirseniz onlar bu ilmi öğrenir de) ve (sonra) bunu Rabbinizin huzurunda aleyhinize delil olarak (kullanırlar)” De ki: Nimet ve lütuf Allah’ın elindedir. Onu dilediğine verir. Allah, ihsanı bol olan, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 74, 'O, rahmetini dilediğine has kılar. Allah, büyük lütuf sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 75, 'Kitap ehlinden öylesi vardır ki, ona yüklerle mal emanet etsen, onu sana (eksiksiz) iade eder. Fakat onlardan öylesi de vardır ki, ona bir dinar emanet etsen, tepesine dikilip durmadıkça onu sana iade etmez. Bu da onların, “Ümmîlere karşı (yaptıklarımızdan) bize vebal yoktur” demelerinden dolayıdır. Onlar, bile bile Allah’a karşı yalan söylerler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 76, 'Hayır! (Gerçek, onların dediği değil.) Kim sözünü yerine getirir ve Allah’a karşı gelmekten sakınırsa, şüphesiz Allah da sakınanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (3, 77, 'Allah’a verdikleri sözü ve ettikleri yeminlerini az bir pahaya değiştirenlere gelince, onların ahirette bir nasibi olmayacaktır. Allah, kıyamet gününde onlarla konuşmayacak, onlara bakmayacak ve onları temize çıkarmayacaktır. Onlar için acı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 78, 'Onların bir kısmı, kitaptan olmadığı halde, sizin kitaptan zannetmeniz için (kitaba bakarak) dillerini eğip bükerler. O, Allah katından olmadığı halde: “Allah katındandır” derler. Bile bile Allah hakkında yalan söylerler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 79, 'Allah''ın, kendisine kitabı, hükmü ve peygamberliği verdiği bir insana (peygambere), “Allah''ı bırakıp bana ibadet edin” demek yaraşmaz. Lakin (her peygamber), “Öğrettiğiniz ve okuduğunuz kitap gereğince Rabbanî insanlar olunuz” der');
INSERT INTO verses (sura, aya, text) VALUES (3, 80, 'O, size melekleri ve peygamberleri rabler edinmenizi emretmez. Size, Müslüman olduktan sonra hiç kâfir olmayı emreder mi?');
INSERT INTO verses (sura, aya, text) VALUES (3, 81, 'Hani, Allah tüm peygamberlerden; “Size vereceğim her kitap ve hikmetten sonra, elinizdekini doğrulayan bir peygamber geldiğinde, ona mutlaka iman edecek ve ona mutlaka yardım edeceksiniz.” diye söz almıştı. Onlara: “Bunu kabul ettiniz mi? Verdiğim bu ağır görevi üstlendiniz mi?” demişti. Onlar da: "Kabul ettik" diye cevap verdiler. Bunun üzerine Allah da: "Şahit olun! Ben de sizinle birlikte şahitlik edenlerdenim" buyurmuştu.');
INSERT INTO verses (sura, aya, text) VALUES (3, 82, 'Artık kim bundan sonra yüz çevirirse, işte onlar fasıkların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 83, 'Allah’ın dininden başka bir din mi arzu ediyorlar? Oysa, göklerde ve yerde olanların hepsi isteyerek ve isyemeyerek O’na teslim olmuştur. Ve O''na döndürüleceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 84, 'Deyin ki: ''''Biz Allah’a, bize indirilene (Kur’an’a), İbrahim, İsmail, İshak, Ya''kûb ve torunlarına indirilene, Mûsâ ve İsa’ya verilen (Tevrat ve İncil) ile bütün diğer peygamberlere Rablerinden verilene iman ettik. Onlardan hiçbirini diğerinden ayırt etmeyiz. Biz Allah''a teslim olanlarız."');
INSERT INTO verses (sura, aya, text) VALUES (3, 85, 'Kim İslam’dan başka bir din ararsa, (bu) ondan asla kabul edilmeyecektir. O, ahirette de hüsrana uğrayanlardandır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 86, 'İman edip, peygamberin hak olduğuna şehadet ettikten ve kendilerine açık belgeler geldikten sonra kâfir olan bir topluluğa Allah nasıl hidayet eder? Allah zalim topluma hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 87, 'İşte onların cezası, Allah’ın meleklerin ve bütün insanların lanetinin üzerlerine olmasıdır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 88, 'Orada ebedi kalacaklar. Azap, onlardan hafifletilmez ve onlara mühlet de verilmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 89, 'Ancak, bu hatalarından sonra tevbe edip, hallerini düzeltenler müstesnadır. Muhakkak ki Allah, çokça affedendir, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 90, 'İman ettikten sonra kâfir olup küfürlerini arttıranların tevbeleri asla kabul edilmeyecektir. Onlar sapıkların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 91, 'Şüphesiz, kâfir olup bu halde kâfir olarak ölenlerin hiçbirinden, yeryüzünü dolduracak kadar altın fidye verse dahi asla kabul edilmeyecektir. İşte acıklı azap bunlar içindir. Onlar için hiçbir yardımcı da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (3, 92, 'Sevdiğiniz şeylerden infak etmedikçe iyiliğe asla erişemezsiniz. Her ne harcarsanız Allah onu hakkıyla bilir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 93, 'Tevrat indirilmeden önce, İsrail’in (Ya''kûb’un) kendisine haram kıldığı dışında, yiyeceklerin hepsi İsrailoğulları''na helâl idi. De ki: ''''Eğer doğru söyleyenler iseniz, haydi Tevrat’ı getirip okuyun.''''');
INSERT INTO verses (sura, aya, text) VALUES (3, 94, 'Artık bundan sonra Allah’a karşı kim yalan uydurursa, işte onlar zalimlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 95, 'De ki: Allah doğru söylemiştir. Öyleyse, hanif olan İbrahim’in yoluna uyun! O, müşriklerden değildi.');
INSERT INTO verses (sura, aya, text) VALUES (3, 96, 'İnsanlar için (mabed olarak) kurulan ilk ev şüphesiz Mekke''deki mübarek ve âlemlere hidayet kaynağı olan (Kâbe) dir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 97, 'Orada apaçık deliller, Makam-ı İbrahim vardır. Kim oraya girerse güven içinde olur. Yoluna güç yetirebilenlerin (Kâbe''yi) haccetmesi, Allah’ın insanlar üzerine (yüklediği) hakkıdır. Kim inkâr ederse (bu hakkı tanımazsa), şüphesiz Allah bütün âlemlerden müstağnidir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 98, 'De ki: Ey Ehl-i Kitap! Allah, yaptıklarınızı görüp dururken Allah’ın âyetlerini niçin inkâr ediyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (3, 99, 'De ki: Ey Ehl-i kitap! (Gerçeği) görüp bildiğiniz halde niçin Allah''ın yolunu eğri göstermeye yeltenerek Müminleri Allah yolundan çevirmeye kalkışıyorsunuz? Allah yaptıklarınızdan gâfil değildir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 100, 'Ey iman edenler! Eğer kitap verilenlerden bir gruba itaat edecek olursanız, sizi iman ettikten sonra kâfirler olarak döndürürler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 101, 'Size Allah’ın ayetleri okunur dururken, üstelik Allah''ın peygamberi de aranızda bulunurken nasıl olurda inkâra saparsınız ? Her kim Allah’a bağlanırsa kesinlikle doğru yola iletilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 102, 'Ey iman edenler! Allah’tan gerektiği gibi sakının ve yalnızca Müslümanlar olarak can verin.');
INSERT INTO verses (sura, aya, text) VALUES (3, 103, 'Topluca Allah’ın ipine sımsıkı sarılın ve ayrılığa düşmeyin! Allah’ın üzerinizdeki nimetini düşünün. Hani siz düşman idiniz de O, kalplerinizi birleştirdi. O''nun bu nimeti ile kardeşler oldunuz. Siz, bir ateş çukurunun kenarında idiniz de sizi oradan kurtardı. Doğru yola çıkasınız diye, Allah size ayetlerini işte böyle açıklıyor.');
INSERT INTO verses (sura, aya, text) VALUES (3, 104, 'Sizden hayra davet eden, iyiliği emredip, kötülükten uzaklaştıran bir ümmet bulunsun. İşte kurtuluşa erenler onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 105, 'Kendilerine apaçık deliller geldikten sonra parçalanıp ayrılığa düşenler gibi olmayın. İşte onlar için büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 106, 'Bir takım yüzlerin parladığı ve bir takım yüzlerin de karardığı o günde yüzleri kararanlara: İmanınızdan sonra kâfir mi oldunuz? Öyleyse, kâfir olduğunuz için tadın azabı (denir).');
INSERT INTO verses (sura, aya, text) VALUES (3, 107, 'Yüzleri ağaranlar ise Allah’ın rahmeti içindedirler. Onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 108, 'İşte bunlar Allah’ın, sana hak olarak okuduğumuz ayetleridir. Allah, âlemlerdeki hiçbir kimseye zulmetmek istemez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 109, 'Göklerde ve yerde ne varsa Allah’ındır. Bütün işler ancak Allah’a döndürülür.');
INSERT INTO verses (sura, aya, text) VALUES (3, 110, 'Siz, insanlar için çıkarılmış en hayırlı ümmetsiniz. İyiliği emreder, kötülükten men eder ve Allah’a iman edersiniz. Kitap ehli de iman etseydi elbette kendileri için hayırlı olurdu. Onlardan iman edenler de var. Ama pek çoğu fasık kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 111, 'Onlar size eziyetten başka bir zarar veremezler. Eğer sizinle savaşmaya kalkışsalar, size arkalarını dönüp kaçarlar. Sonra onlara yardım da edilmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 112, 'Onlar (Yahudiler) nerede bulunsalar, Allah''ın ipine (ahdine) ve insanların ipine (emanına) sığınanlar müstesna, onlara alçaklık damgası vurulmuştur. Allah''tan bir gazaba uğramışlardır ve onlara miskinlik damgası vurulmuştur. Çünkü onlar, Allah''ın ayetlerinin inkâr ediyorlar ve haksız yere peygamberlerini öldürüyorlardı. Bu da, onların isyan etmiş ve haddi aşmış bulunmalarındandır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 113, 'Ehl-i kitabın hepsi bir değildir. Onlardan; geceleri Allah’ın ayetlerini okuyup duran, secdeye kapanan bir topluluk vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 114, 'Onlar, Allah’a ve ahiret gününe iman ederler. İyiliği emreder, kötülükten men eder, hayır işlerinde birbirleriyle yarışırlar. İşte onlar salihlerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 115, 'Yaptıkları hiçbir iyilik inkâr edilmeyecektir. Allah muttakileri çok iyi bilmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 116, 'Kâfirlerin ne malları ne evlatları Allah’a karşı bir fayda sağlamayacaktır. İşte onlar ateş ehlidirler. Onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 117, 'Onların, bu dünya hayatında yapmakta oldukları harcamaların durumu, kendilerine zulmetmiş olan bir kavmin ekinlerini vurup da mahveden kavurucu bir rüzgârın durumu gibidir. Allah onlara zulmetmiş değildir, aksine onlar kendi kendilerine zulmetmişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 118, 'Ey iman edenler! Sizden olmayanı sırdaş edinmeyin. Zira onlar size ellerinden gelen her türlü kötülüğü yaparlar, size sıkıntı verecek şeyleri arzu ederler. Öfkeleri ağızlarından taşmaktadır. İçlerinde gizledikleri (nefret) ise daha da büyüktür. Eğer düşünüp anlıyorsanız size âyetleri açıkladık.');
INSERT INTO verses (sura, aya, text) VALUES (3, 119, 'İşte siz öyle kimselersiniz ki, onları seversiniz; onlar ise bütün kitaplara iman ettiğiniz halde sizi sevmezler. Onlar sizinle karşılaştıkları zaman “iman ettik” derler. Ama kendi başlarına kaldıklarında, size karşı kinlerinden dolayı parmaklarının uçlarını ısırırlar. De ki: Öfkenizden ölün! Şüphesiz ki Allah, sinelerde olanı hakkıyla bilir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 120, 'Size bir iyilik dokunursa, bu onları üzer. Başınıza bir kötülük gelse, ona sevinirler. Eğer siz sabırlı olur, Allah’a karşı gelmekten sakınırsanız, onların hileleri size hiçbir zarar vermez. Çünkü Allah, onların yaptıklarını tam olarak kuşatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 121, 'Hani sen Müminleri (Uhud’da) savaş mevzilerine yerleştirmek için, sabah erken ailenden (evinden) ayrılmıştın. Allah, hakkıyla işitendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 122, 'Hani sizden iki topluluk çözülüp dağılmaya yüz tutmuş idi; oysa Allah onların velisi idi. İman edenler yalnız Allah''a tevekkül etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 123, 'Andolsun, siz son derece güçsüz iken Allah size Bedir’de yardım etmişti. O halde Allah’a karşı gelmekten sakının ki şükretmiş olasınız.');
INSERT INTO verses (sura, aya, text) VALUES (3, 124, 'Hani sen Müminlere: “Rabbinizin, indirilmiş üç bin melek ile yardım etmesi size yetmez mi?” diyordun.');
INSERT INTO verses (sura, aya, text) VALUES (3, 125, 'Evet! Sabrettiğiniz ve Allah’a karşı gelmekten sakındığınız takdirde onlar ansızın üzerinize gelseler bile Rabbiniz nişanlı beş bin melekle size yardım eder.');
INSERT INTO verses (sura, aya, text) VALUES (3, 126, 'Allah, bu yardımı size sadece müjde olması ve kalplerinizin bununla yatışması için yaptı. Zafer, ancak Aziz ve Hakim olan Allah katındandır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 127, 'Bir de Allah, bu (yardımı) kâfirlerden bir kısmını helâk etsin ya da perişan etsin de ümitsiz olarak dönüp gitsinler diye yaptı.');
INSERT INTO verses (sura, aya, text) VALUES (3, 128, 'Bu işte senin yapacağın bir şey yoktur. Allah, ya tevbelerini kabul edip onları affeder ya da zalim olduklarından dolayı onlara azap eder.');
INSERT INTO verses (sura, aya, text) VALUES (3, 129, 'Göklerde ve yerde ne varsa hepsi Allah’ındır! O, dilediğini bağışlar, dilediğine azap eder. Allah, çok bağışlayan ve merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 130, 'Ey iman edenler! Kat kat arttırılmış olarak faiz yemeyin. Allah’a karşı gelmekten sakının ki, kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (3, 131, 'Kâfirler için hazırlanmış ateşten kendinizi koruyun.');
INSERT INTO verses (sura, aya, text) VALUES (3, 132, 'Allah''a ve Rasûl''e itaat edin ki, merhamete erdirilesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (3, 133, 'Rabbinizin mağfiretine ve takva sahipleri için hazırlanmış, eni gökler ve yer kadar olan cennete koşuşun!');
INSERT INTO verses (sura, aya, text) VALUES (3, 134, 'Muttakiler, bollukta ve darlıkta Allah yolunda harcayanlar, öfkelerini yenenler, insanları affedenlerdir. Allah, iyilik edenleri sever.');
INSERT INTO verses (sura, aya, text) VALUES (3, 135, 'Yine onlar, bir günah işlediklerinde veya nefislerine zulmettiklerinde Allah’ı zikredip günahları için mağfiret dilerler. Allah’tan başka günahları kim bağışlar? Onlar, yaptıklarında bile bile ısrar etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 136, 'İşte onların mükâfatı Rableri tarafından bağışlanma ve içinden ırmaklar akan Cennetler''dir ki, orada ebedî kalacaklardır. Böyle amel edenlerin mükâfatı pek de güzeldir!');
INSERT INTO verses (sura, aya, text) VALUES (3, 137, 'Sizden önce nice (milletler hakkında) ilahi kanunlar gelip geçmiştir. Onun için yeryüzünde gezin de (Allah''ın ayetlerini) yalancıların sonunun ne olduğuna bir bakın!');
INSERT INTO verses (sura, aya, text) VALUES (3, 138, 'Bu (Kur’an), insanlar için bir açıklama, Takvâ sahipleri için bir hidayet ve öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (3, 139, 'Gevşemeyin, hüzünlenmeyin. Eğer (gerçekten) iman etmiş kimseler iseniz üstün olan sizlersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (3, 140, 'Eğer siz (Uhud’da) bir yara aldıysanız, şüphesiz o topluluk da (Müşrikler de Bedir’de) benzeri bir yara almıştı. İşte (iyi veya kötü) günleri insanlar arasında (böyle) döndürür dururuz. (Bazen bir topluma iyi ya da kötü günler gösteririz, bazen öbürüne.) Allah, sizden iman edenleri ayırt etmek, sizden şahitler edinmek için böyle yapar. Allah, zalimleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (3, 141, 'Bir de Allah, iman edenleri arındırmak ve kâfirleri helak etmek için böyle yapar.');
INSERT INTO verses (sura, aya, text) VALUES (3, 142, 'Yoksa siz; Allah, içinizden cihad edenleri (sınayıp) ayırt etmeden ve yine sabredenleri (sınayıp) ayırt etmeden Cennet''e gireceğinizi mi sandınız?');
INSERT INTO verses (sura, aya, text) VALUES (3, 143, 'Andolsun, siz ölümle karşılaşmadan (Uhud''tan) önce (şehitliği) ölümü temenni ediyordunuz. İşte onu gördünüz, ama bakıp duruyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (3, 144, 'Muhammed, ancak bir peygamberdir. Ondan önce de peygamberler gelip geçmiştir. Şimdi o ölür veya öldürülürse gerisin geriye (eski dininize) mi döneceksiniz? Kim gerisin geriye dönerse, Allah’a hiçbir zarar veremez. Allah, şükredenleri mükâfatlandıracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 145, 'Hiçbir kimse Allah’ın izni olmadan ölmez. Ölüm belirli bir süreye göre yazılmıştır. Kim dünya menfaatini isterse, kendisine ondan veririz. Kim de ahiret mükâfatını isterse, ona da ondan veririz. Biz şükredenleri mükâfatlandıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (3, 146, 'Nice peygamberler vardır ki , onunla birlikte bir çok Allah dostları savaştılar . Allah yolunda başlarına gelenlerden dolayı gevşemediler , yılmadılar , boyun eğmediler. Allah sabredenleri sever.');
INSERT INTO verses (sura, aya, text) VALUES (3, 147, 'Onların sözleri ancak, “Rabbimiz! Bizim günahlarımızı ve işimizdeki taşkınlıklarımızı bağışla ve (yolunda) ayaklarımızı sabit kıl. Kâfir topluma karşı bize yardım et!” demekten ibaretti.');
INSERT INTO verses (sura, aya, text) VALUES (3, 148, 'Bu yüzden Allah onlara dünya sevabını ve ahiret sevabının güzelliğini verdi. Allah ihsan sahiplerini sever.');
INSERT INTO verses (sura, aya, text) VALUES (3, 149, 'Ey iman edenler! Siz eğer kâfir olanlara uyarsanız, sizi gerisin geriye (küfre) çevirirler de büsbütün hüsrana uğrarsınız.');
INSERT INTO verses (sura, aya, text) VALUES (3, 150, 'Halbuki sizin mevlanız/yardımcınız Allah’tır. O, yardımcıların en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 151, 'Hakkında hiçbir delil indirmediği şeyleri Allah’a şirk koştukları için kâfirlerin kalbine korku salacağız. Onların varacağı yer ateştir. Zalimlerin varacağı yer ne kötüdür.');
INSERT INTO verses (sura, aya, text) VALUES (3, 152, 'Allah, elbette size verdiği sözü tuttu. O''nun izniyle düşmanlarınızı yok etmek üzereydiniz. Fakat, Allah size arzuladıklarınızı (zaferi) gösterdikten sonra zaaf gösterdiniz, ayrılığa düştünüz ve (peygamberin) emrine itaatsizlik ettiniz. İçinizden dünyayı isteyenler de vardı, ahireti isteyenler de. Sonra imtihan etmek için onların karşısında sizi bozguna uğrattı. Artık Allah sizi affetmiştir. Çünkü Allah, Müminlere karşı çok lütufkardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 153, 'Peygamber, arkanızdan sizi çağırırken siz durmadan dağa yukarı kaçıyor, hiç kimseye dönüp bakmıyordunuz. Bundan dolayı Allah, size keder üstüne keder verdi ki, (bu durumlara alışasınız ve daha sonra) elinizden gidene ve başınıza gelene üzülmeyesiniz. Allah, yaptıklarınızdan hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 154, 'Sonra o kederin ardından (Allah) üzerinize içinizden bir kısmını örtüp bürüyen bir güven, bir uyku indirdi. Bir kısmınız da kendi canlarının kaygısına düşmüştü. Allah’a karşı cahiliye zannı gibi gerçek dışı zanda bulunuyorlar: “Bu işte bizim hiçbir dahlimiz yok” diyorlardı. De ki: “Bütün iş, Allah’ındır.” Onlar sana açıklayamadıklarını içlerinde saklıyorlar ve diyorlar ki: “Bu konuda bizim elimizde bir şey olsaydı, burada öldürülmezdik.” De ki: “Evlerinizde dahi olsaydınız, üzerlerine öldürülmesi yazılmış bulunanlar mutlaka yatacakları (öldürülecekleri) yerlere çıkıp gideceklerdi. Allah, bunu göğüslerinizdekini denemek, kalplerinizdekini arındırmak için yaptı. Allah, göğüslerin özünü (kalplerde olanı) bilir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 155, 'İki topluluğun karşılaştığı gün, içinizden yüz çevirip kaçanları, Şeytan ancak yaptıkları bazı hatalardan dolayı yoldan kaydırmak istemişti. Ama yine de Allah onları affetti. Kuşkusuz Allah çok bağışlayandır, Halîm''dir. (Hemen cezalandırmaz, mühlet verir.)');
INSERT INTO verses (sura, aya, text) VALUES (3, 156, 'Ey iman edenler! Kardeşleri sefere veya savaşa çıktığında onlar hakkında: “Onlar bizim yanımızda olsalardı, ölmezlerdi ve öldürülmezlerdi” diyen kâfirler gibi olmayın. Allah, bunu onların kalplerine dayanılmaz bir üzüntü olarak koydu. Yaşatan da öldüren de Allah’tır. Allah, yaptıklarınızı görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 157, 'Andolsun, eğer Allah yolunda öldürülür veya ölürseniz, Allah’ın bağışlaması ve rahmeti onların topladıkları (dünyalıkları)ndan daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 158, 'Andolsun, ölseniz de öldürülseniz de, Allah’ın huzurunda toplanacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (3, 159, 'Allah’ın rahmeti sayesinde sen onlara karşı yumuşak davrandın. Eğer kaba, katı yürekli olsaydın, onlar senin etrafından dağılıp giderlerdi. Artık sen onları affet. Onlar için Allah’tan bağışlama dile. İş konusunda onlarla istişare et. Bir kere de karar verip azmettin mi artık Allah’a tevekkül et! (Ona dayanıp güven). Şüphesiz Allah, tevekkül edenleri sever.');
INSERT INTO verses (sura, aya, text) VALUES (3, 160, 'Allah size yardım ederse, kimse size galip gelemez. Eğer sizi yardımsız bırakırsa, ondan sonra size kim yardım edebilir? Müminler, ancak Allah’a tevekkül etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 161, 'Bir peygamberin (ganimet malına) hıyanet etmesi olur şey değildir. Kim emanete hıyanet ederse, kıyamet günü hıyanet ettiği malı yüklenerek gelir. Sonra da hiçbir haksızlığa uğratılmaksızın herkese kazandığının karşılığı tastamam ödenir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 162, 'Hiç, Allah’ın rızasına uyan kimse, Allah’ın gazabına uğrayan ve varacağı yer Cehennem olan kimse gibi olur mu? O, ne kötü varılacak yerdir!');
INSERT INTO verses (sura, aya, text) VALUES (3, 163, 'Onlar (insanlar) Allah’ın katında derece derecedirler. Allah, onların yaptıklarını görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 164, 'Andolsun Allah, Müminlere kendi içlerinden; onlara ayetlerini okuyan, onları arıtıp tertemiz yapan, onlara kitap ve hikmeti öğreten bir peygamber göndermekle büyük bir lütufta bulunmuştur. Oysa onlar, daha önce apaçık bir sapıklık içinde idiler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 165, 'Onların (müşriklerin) başına (Bedir’de) iki mislini getirdiğiniz bir musibet (Uhud’da) sizin başınıza geldiğinde, “Bu, nereden başımıza geldi?” dediniz, öyle mi? De ki: “O (musibet), kendinizdendir.” Şüphesiz Allah’ın gücü her şeye hakkıyla yeter.');
INSERT INTO verses (sura, aya, text) VALUES (3, 166, 'İki ordunun çarpıştığı gün başınıza gelen ancak Allah’ın izniyle idi ve Müminleri ortaya çıkarmak içindi.');
INSERT INTO verses (sura, aya, text) VALUES (3, 167, 'Ve münafıklık edenleri de açığa vurmak içindir. Onlara (münafıklara): “Gelin, Allah yolunda savaşın veya savunmaya geçin!” denildi de onlar; “Biz savaş olacağını bilseydik, elbette sizin peşinizden gelirdik.” dediler. Onlar o gün, imandan çok küfre yakın idiler. Ağızlarıyla kalplerinde olmayanı söylüyorlardı. Oysa Allah, içlerinde gizledikleri şeyi çok iyi bilmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 168, '(Onlar), kendileri oturup kaldıkları halde kardeşleri için: "Eğer bize uysalardı, öldürülmezlerdi” diyen kimselerdir. De ki: Eğer doğru söyleyenler iseniz kendinizden ölümü savın.');
INSERT INTO verses (sura, aya, text) VALUES (3, 169, 'Allah yolunda öldürülenleri sakın ölüler sanma. Çünkü onlar, Rablerinin katında diridirler ve rızıklandırılırlar.');
INSERT INTO verses (sura, aya, text) VALUES (3, 170, 'Onlar, Allah’ın kendilerine fazlından vermiş olduklarıyla sevinç içindedirler. Arkalarından gelip, henüz kendilerine katılmamış olanlara (şehitler için), bir korku olmayacağı ve üzülmeyecekleri müjdesini verirler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 171, 'Onlar Allah’tan bir nimet, bir lütuf ve Allah’ın Müminlerin ecrini boşa çıkarmayacağı müjdesinin sevinci içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 172, 'Onlar (Uhud''da) yaralandıktan sonra Allah’ın ve peygamberinin davetine uyan kimselerdir. Onlardan iyilik eden ve takva sahibi olanlar için büyük bir ecir vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 173, 'Onlara bazı kimseler: "İnsanlar sizinle savaşmak için toplandı; onlardan korkun!" dediklerinde bu onların imanını arttırdı ve; “Allah bize yeter, O ne güzel vekildir” diye karşılık verdiler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 174, 'Bundan dolayı Allah’tan bir nimet ve lütufla kendilerine hiçbir fenalık dokunmadan geri döndüler ve Allah’ın rızasına uydular. Allah, büyük lütuf sahibidir');
INSERT INTO verses (sura, aya, text) VALUES (3, 175, 'O Şeytan sizi ancak kendi dostlarıyla korkutur. Onlardan korkmayın, eğer Mümin iseniz, sadece benden korkun.');
INSERT INTO verses (sura, aya, text) VALUES (3, 176, 'Küfürde yarışanlar seni üzmesin. Onlar, Allah’a hiçbir şekilde zarar veremezler. Allah, onlara ahirette bir pay bırakmamak istiyor. Onlar için büyük azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 177, 'Şüphe yok ki iman karşılığında küfrü satın alanlar, Allah’a hiçbir zarar veremezler. Onlar için elem verici bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 178, 'Kâfirler, kendilerine vermiş olduğumuz mühletin sakın kendileri için hayırlı olduğunu sanmasınlar. Biz, onların ancak günahları artsın diye ömürlerini uzatıyoruz. Onlar için alçaltıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 179, 'Allah iman edenleri üzerinde bulunduğunuz bu halde asla bırakacak değildir, sonunda temizi pisten ayıracaktır. Allah, size gaybı bildirecek de değildir. Fakat Allah, peygamberlerinden dilediğini seçer (gaybı ona bildirir). O halde, Allah’a ve peygamberlerine iman edin. Eğer iman eder ve Allah’a karşı gelmekten sakınırsanız sizin için büyük bir mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 180, 'Allah’ın kendilerine lütfundan verdiği nimetlerde cimrilik edenler, bunun, kendileri için hayırlı olduğunu sanmasınlar, aksine bu onlar için şerdir. Cimrilik ettikleri şey kıyamet gününde boyunlarına dolanacaktır. Göklerin ve yerin mirası Allah’ındır. Allah, yaptıklarınızdan hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 181, '“Allah fakirdir, biz zenginiz” diyen Yahudilerin sözünü andolsun ki, Allah duyup işitmiştir. Hem bu söylediklerini hem de haksız yere peygamberleri öldürmelerini elbette (bir tarafa) yazacağız ve “Yakıcı azabı tadın bakalım” diyeceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (3, 182, 'Bu, kendi ellerinizin (önceden yapıp) gönderdiklerinin karşılığıdır. Allah, kullara asla zulmedici değildir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 183, '''Allah, bize gökten inen, ateşin yiyeceği bir kurban getirmedikçe hiçbir rasûle iman etmememizi (Tevrat''ta) emretti'''' diyenlere de ki: Benden önce size peygamberler apaçık delillerle ve söylediğiniz (mucize) ile gelmişti. Eğer sözünüzde samimi iseniz niçin onları öldürdünüz?');
INSERT INTO verses (sura, aya, text) VALUES (3, 184, 'Eğer onlar seni yalanlarlarsa, senden önce açık delilleri, hikmetli sayfaları ve aydınlatıcı kitabı getiren nice peygamberler de yalanlanmıştı.');
INSERT INTO verses (sura, aya, text) VALUES (3, 185, 'Her canlı ölümü tadacaktır. Kıyamet günü yaptıklarınızın karşılığı size tastamam verilecektir. Kim Cehennem''den uzaklaştırılıp Cennet''e sokulursa, gerçekten kurtuluşa ermiştir. Dünya hayatı, aldatıcı metadan başka bir şey değildir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 186, 'Andolsun, mallarınız ve canlarınızla imtihana çekileceksiniz. Sizden önce kendilerine kitap verilenlerden ve müşriklerden üzücü birçok söz işiteceksiniz. Eğer sabreder ve Allah’a karşı gelmekten sakınırsanız, bilin ki bunlar (yapmaya değer) azmi gerektiren işlerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 187, 'Hani Allah, kendilerine kitap verilenlerden, “Onu (Kitabı) mutlaka insanlara açıklayacaksınız, onu gizlemeyeceksiniz!” diye sağlam söz almıştı. Fakat onlar verdikleri sözü, arkalarına atıp onu az bir bedele sattılar. Yaptıkları bu alışveriş ne kadar kötüdür!');
INSERT INTO verses (sura, aya, text) VALUES (3, 188, 'Sanma ki ettiklerine sevinen, yapmadıkları ile övülmek isteyenler, evet, sanma ki onlar azaptan kurtulacaklardır. Onlar için elem verici bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 189, 'Göklerin ve yerin hükümranlığı Allah’ındır. Allah, her şeye hakkıyla gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 190, 'Göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelip gidişinde selim akıl sahipleri için elbette ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 191, 'Onlar ayaktayken, otururken ve yanları üzerine yatarken Allah’ı zikrederler. Göklerin ve yerin yaratılışı üzerinde düşünürler. “Rabbimiz! Bunu boş yere yaratmadın, seni tüm noksanlıklardan tenzih ederiz. Bizi ateş azabından koru!” derler.');
INSERT INTO verses (sura, aya, text) VALUES (3, 192, 'Rabbimiz! Sen kimi Cehennem ateşine sokarsan, onu rezil etmişsindir. Zalimlerin hiç yardımcıları yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (3, 193, 'Rabbimiz! Biz, "Rabbinize iman edin" diye imana çağıran bir davetçi işittik, hemen iman ettik. Rabbimiz! Günahlarımızı bağışla, kötülüklerimizi ört ve canımızı iyilerle beraber al.');
INSERT INTO verses (sura, aya, text) VALUES (3, 194, 'Rabbimiz! Peygamberlerinle vadettiklerini bize ver, kıyamet günü bizi rezil etme. Sen şüphesiz sözünden caymazsın.');
INSERT INTO verses (sura, aya, text) VALUES (3, 195, 'Rableri, onlara şu karşılığı verdi: "İçinizden gerek erkek gerek kadın olsun (salih) amel işleyenin amelini karşılıksız bırakarak boşa çıkarmayacağım. Kiminiz kiminizdensiniz (sizler sevap ve cezada denksiniz). Hicret edenler, yurtlarından çıkarılanlar, yolumda eziyet görenler, savaşanlar ve öldürülenlerin de andolsun günahlarını elbette örteceğim. Allah katından bir mükâfat olmak üzere, onları içinden ırmaklar akan Cennetlere koyacağım. Mükâfatın en güzeli Allah katındadır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 196, 'Kâfirlerin refah içinde diyar diyar dolaşmaları sakın seni aldatmasın.');
INSERT INTO verses (sura, aya, text) VALUES (3, 197, 'Az bir geçimlik sonra varacakları yer Cehennem''dir. Orası ne kötü yerleşim yeridir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 198, 'Fakat Rablerine karşı gelmekten sakınanlar için, Allah tarafından bir ikram olarak, altlarından ırmaklar akan, ebedî olarak kalacakları Cennetler vardır. İyiler için Allah katındaki (nimetler) daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (3, 199, 'Ehl-i Kitap''tan öyleleri var ki, Allah’a, size indirilene ve kendilerine indirilene, Allah’tan korkarak iman ederler. Allah’ın ayetlerini az bir değere satmazlar. İşte onlara Rableri katında mükâfatları vardır. Şüphesiz Allah, hesabı çabuk görendir.');
INSERT INTO verses (sura, aya, text) VALUES (3, 200, 'Ey iman edenler! Sabredin. Sabır göstermede dayanın. (Cihat için) hazırlıklı ve uyanık olun ve Allah’a karşı gelmekten sakının ki, kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (4, 1, 'Ey insanlar! Sizi bir tek nefisten yaratan ve ondan da eşini yaratan; ikisinden birçok erkek ve kadın (meydana getirip) yayan Rabbinize karşı gelmekten sakının. Kendisi adına birbirinizden dilekte bulunduğunuz Allah’a karşı gelmekten ve akrabalık bağlarını koparmaktan sakının. Şüphesiz Allah, üzerinizde bir gözetleyicidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 2, 'Yetimlere mallarını verin. Temizi pis olanla (helâli haramla) değişmeyin. Onların mallarını kendi mallarınıza katıp yemeyin. Çünkü bu, büyük bir günahtır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 3, 'Eğer, (velisi olduğunuz) yetim kızlar (ile evlenip onlar) hakkında adaletsizlik etmekten korkarsanız, (onları değil) size helâl olan (başka) kadınlardan iki, üç, dörde kadar evlenin. Eğer (o kadınlar arasında da) adaletli davranmayacağınızdan korkarsanız, o taktirde bir tane alın veya sahip olduğunuz (cariyeler) ile yetinin. Bu, haksızlık etmemeniz için daha elverişlidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 4, 'Kadınlara mehirlerini gönül hoşluğuyla verin. Eğer kendi istekleriyle o mehrin bir kısmını size bağışlarlarsa, onu da afiyetle yiyin.');
INSERT INTO verses (sura, aya, text) VALUES (4, 5, 'Allah’ın, sizin için geçim kaynağı yaptığı mallarınızı sefihlere vermeyin. Fakat o maldan onlara yedirin, giydirin ve onlara güzel söz söyleyin.');
INSERT INTO verses (sura, aya, text) VALUES (4, 6, 'Yetimleri nikah çağına gelinceye kadar deneyin. Evlenme çağına (büluğa) erdiklerinde, eğer reşid olduklarını görürseniz, mallarını kendilerine verin. Büyüyecekler (ve mallarını geri alacaklar) diye israf ederek ve aceleye getirerek mallarını yemeyin. (Velilerden) kim zengin ise (yetim malından yemeğe) tenezzül etmesin. Kim de fakir ise, aklın ve dinin gereklerine uygun bir biçimde (hizmetinin karşılığı kadar) yesin. Mallarını kendilerine geri verdiğiniz zaman da yanlarında şahit bulundurun. Hesap görücü olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 7, 'Ana, baba ve akrabaların (miras olarak) bıraktıklarından erkeklere bir pay vardır. Ana, baba ve akrabaların bıraktıklarından kadınlara da bir pay vardır. Allah, bırakılan malın azından da çoğundan da bunları farz kılınmış birer hisse olarak belirlemiştir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 8, 'Miras taksiminde (kendilerine pay düşmeyen) yakınlar, yetimler ve fakirler hazır bulunurlarsa, onlara da maldan bir şeyler verin ve onlara (gönüllerini alacak) güzel sözler söyleyin.');
INSERT INTO verses (sura, aya, text) VALUES (4, 9, 'Geriye (küçük) zayıf çocuklar bırakıp, (onlar adına) endişe duyanlar,(himayeleri altındaki yetimler hakkında da aynı endişeyi taşıyıp) Allah''tan sakınsınlar. Dosdoğru söz söylesinler.');
INSERT INTO verses (sura, aya, text) VALUES (4, 10, 'Yetimlerin mallarını haksız yere yiyenler, karınlarına sadece ateş doldururlar ve alevli bir ateşe atılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 11, 'Allah, size çocuklarınız(ın alacağı miras) hakkında bir erkeğe iki kadının payı kadarını emreder. (Çocuklar sadece) ikiden fazla kız iseler, (ölenin geriye) bıraktığının üçte ikisi onlarındır. Eğer kız bir ise (mirasın) yarısı onundur. Ölenin çocuğu varsa, geriye bıraktığı maldan, ana babasından her birinin altıda bir hissesi vardır. Eğer çocuğu yok da (yalnız) ana babası ona varis oluyorsa, anasına üçte bir düşer. Eğer kardeşleri varsa, anasının hissesi altıda birdir. (Bu paylaştırma, ölenin) yapacağı vasiyetten ya da borcundan sonradır. Babalarınız ve oğullarınızdan, hangisinin size daha faydalı olduğunu bilemezsiniz. Bunlar, Allah tarafından farz kılınmıştır. Şüphesiz Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 12, 'Eğer çocukları yoksa, hanımlarınızın geriye bıraktıklarının yarısı sizindir. Eğer çocukları varsa, bıraktıklarının dörtte biri sizindir. (Bu paylaştırma, ölen hanımlarınızın) yaptıkları vasiyetlerin yerine getirilmesi, yahut borçlarının ödenmesinden sonradır. Eğer sizin çocuğunuz yoksa, bıraktığınızın dörtte biri onlarındır. Eğer çocuğunuz varsa, bıraktığınızın sekizde biri onlarındır. (Yine bu paylaştırma) yaptığınız vasiyetin yerine getirilmesinden yahut borçlarınızın ödenmesinden sonradır. Eğer kendisine varis olunan bir erkek veya bir kadının evladı ve babası olmaz ve bir erkek veya bir kız kardeşi bulunursa, ona altıda bir düşer. Eğer (kardeşler) birden fazla olurlarsa, üçte birde ortaktırlar. (Bu paylaştırma varislere) zarar vermeksizin yapılan vasiyetin yerine getirilmesinden, yahut borcun ödenmesinden sonra yapılır. (Bütün bunlar) Allah’ın emridir. Allah, hakkıyla bilendir, Halîm''dir. (Hemen cezalandırmaz, mühlet verir.)');
INSERT INTO verses (sura, aya, text) VALUES (4, 13, 'İşte bu (hükümler) Allah’ın koyduğu sınırlarıdır. Kim Allah’a ve Rasûlüne itaat ederse; Allah onu, içinden ırmaklar akan, içinde ebedî kalacakları Cennetlere sokar. İşte bu en büyük kurtuluştur.');
INSERT INTO verses (sura, aya, text) VALUES (4, 14, 'Kim de Allah’a ve Rasûlüne isyan eder ve O’nun koyduğu sınırları aşarsa, Allah onu ebedî kalacağı Cehennem ateşine sokar. Onun için alçaltıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 15, 'Kadınlarınızdan fuhuş (zina) yapanlara karşı içinizden dört şahit getirin. Eğer onlar şahitlik ederlerse, o kadınları ölüm alıp götürünceye veya Allah onlar hakkında bir yol açıncaya kadar kendilerini evlerde tutun (dışarı çıkarmayın).');
INSERT INTO verses (sura, aya, text) VALUES (4, 16, 'Sizlerden zina edenlerin her ikisini de incitip eziyet edin. Eğer onlar tevbe edip ıslah olurlarsa, onları incitip eziyet etmekten vazgeçin. Çünkü Allah, tevbeleri çok kabul edendir, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 17, 'Allah katında (makbul) tevbe, ancak cahillikle bilmeyerek günah işleyip sonra çok geçmeden tevbe edenlerin tevbesidir. İşte Allah, bunların tevbelerini kabul buyurur. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 18, 'Yoksa (makbul) tevbe, kötülükleri (günahları) işleyip de kendisine ölüm gelip çatınca, “İşte ben şimdi tevbe ettim” diyen kimseler ile kâfir olarak ölenlerinki değildir. Bunlar için ahirette elem dolu bir azap hazırlamışızdır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 19, 'Ey iman edenler! (Ölen babalarınızın) kadınlarını miras yoluyla zorla almanız size helal değildir. Apaçık bir fuhuş işlemedikçe (mehir olarak) verdiklerinizin bir kısmını elde etmek için onları (başkalarıyla evlenmelerine) engel olmak için nikahınızda tutmayın. Onlarla güzel güzel geçinin. Onlardan hoşlanmasanız bile, umulur ki sizin hoşunuza gitmeyen bir şeyde Allah bir çok hayır takdir eder.');
INSERT INTO verses (sura, aya, text) VALUES (4, 20, 'Eğer bir eşin yerine başka bir eş almak isterseniz, öncekine yüklerle (mehir) vermiş olsanız bile ondan hiçbir şeyi geri almayın. İftira ederek ve açık günaha girerek mi verdiğinizi geri alacaksınız?');
INSERT INTO verses (sura, aya, text) VALUES (4, 21, 'Hem, siz eşlerinizle birleşmiş ve onlar da sizden sağlam bir söz almış iken, onu nasıl (geri) alırsınız?');
INSERT INTO verses (sura, aya, text) VALUES (4, 22, 'Kadınlardan babalarınızın nikâhladıklarını nikâhlamayın. Ancak geçmişte olan müstesnâ. Çünkü bu bir hayâsızlık, öfke ve nefret gerektiren bir iştir. Bu, ne kötü bir yoldur.');
INSERT INTO verses (sura, aya, text) VALUES (4, 23, 'Analarınız, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, erkek kardeş kızları, kız kardeş kızları, sizi emziren süt anneleriniz, süt kardeşleriniz, karılarınızın anaları, kendileriyle gerdeğe girmiş olduğunuz karılarınızdan olup evlerinizde büyüttüğünüz üvey kızlarınız, -Eğer analarıyla zifafa girmemiş iseniz (annelerini boşayıp, onlarla nikâh kıymanızda) bir sakınca yoktur- kendi öz oğullarınızın karıları ve iki kız kardeşi birden almanız size haram kılınmıştır. Ancak geçen geçmiştir. (Bu sebeple üzerinize bir günah yoktur). Allah, şüphesiz çok bağışlayıcı ve merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 24, 'Maliki bulunduğunuz cariyeler müstesna, evli kadınlarla evlenmeniz de haram kılındı. Bunlar, Allah''ın üzerinize farz kıldığı hükümlerdir. Bunların dışında kalanlar ise, iffetli yaşamak ve zina etmemek şartıyla mallarınızla (mehirlerini verip) istemeniz size helâl kılındı. Onlardan (nikâhlanıp) faydalanmanıza karşılık sabit bir hak olarak kendilerine mehirlerini verin. Mehir belirlendikten sonra, onunla ilgili olarak uzlaştığınız şeyler konusunda size günah yoktur. Şüphesiz ki Allah, (her şeyi) hakkıyla bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 25, 'Sizden, hür Mümin kadınlarla evlenmeye maddi açıdan güç yetiremeyen kimse, ellerinizin altında olan Mümin cariyelerinizden alsın. Allah sizin imanınızı çok iyi bilir. Bazınız bazınızdansınız (hepiniz birsiniz). Onlarla, zinadan kaçınmaları, iffetli olmaları ve gizli dost tutmamış olmaları halinde velilerinin izniyle evlenin ve örfe uygun bir şekilde mehirlerini verin. Evlendiklerinde zina edecek olurlarsa, onlara, hür kadınlara edilen azabın yarısı edilir. (Başkasına ait cariye ile evlenme hususundaki) Bu (izin) içinizden, günaha girme korkusu olanlaradır. Sabretmeniz (başkasına ait cariyelerle evlenmemeniz) sizin için daha hayırlıdır. Allah çok bağışlayıcıdır, çok merhamet edicidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 26, 'Allah size (hükümlerini) açıklamak, sizden öncekilerin yollarına hidayet etmek ve tevbenizi kabul buyurmak ister. Allah her şeyi bilendir, hikmet sahibidir');
INSERT INTO verses (sura, aya, text) VALUES (4, 27, 'Allah, sizin tevbenizi kabul etmek istiyor. Şehvetlerine uyanlar ise sizin büyük bir sapıklığa düşmenizi istiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (4, 28, 'Allah, sizden (ağır yükümlülükleri) hafifletmek istiyor. Çünkü insan zayıf yaratılmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 29, 'Ey iman edenler! Mallarınızı aranızda batıl yollarla yemeyin. Ancak karşılıklı rıza ile yapılan ticaretle olursa başka. Kendinizi helâk etmeyin. Şüphesiz Allah, size karşı çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 30, 'Kim haddi aşarak ve zulmederek bunu yaparsa, onu Cehennem ateşine atacağız. Bu, Allah’a pek kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 31, 'Size yasaklananların büyüklerinden kaçınırsanız, sizin kusurlarınızı (küçük günahlarınızı) örteriz ve sizi onurlu bir makama (Cennet''e) girdiririz.');
INSERT INTO verses (sura, aya, text) VALUES (4, 32, '(Allah’ın sizi, birbirinizden üstün kıldığı (başkalarında olup da sizde olmayanı) hasretle arzu edip durmayın. Erkekler için kazandıklarının bir sevabı olduğu gibi, kadınlar için de kazandıklarının bir sevabı vardır. Allah’ın kendi fazlından (bağışından) isteyin. Şüphesiz Allah, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 33, 'Ana babanın ve yakın akrabanın geride bıraktıklarından her biri için mirasçılar belirledik. Yeminlerinizle (yardımlaşmak için) söz verdiğiniz kimselere de kendi paylarını verin. Elbette Allah, her şeye şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 34, 'Allah''ın insanlardan bir kısmını diğerlerine üstün kılmasından ve erkeklerin mallarından sarfetmelerinden dolayı erkekler kadınlar üzerine hakimdirler. İyi kadınlar, gönülden (Allah’a) boyun eğen, Allah’ın koruduğu gizlilikleri kocaları olmadıkları zaman (namus ve diğer korunması gerekenleri) koruyanlardır. Baş kaldırmasından endişe ettiğiniz kadınlara öğüt verin. Daha sonra yataklarında yalnız bırakın ve (sonunda) onlara vurun. Eğer size itaat ederlerse, onlara (vurmaya başka) yol aramayın. Elbette Allah yüksektedir, yücedir ve büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (4, 35, 'Eğer karı-kocanın arasının açılmasından endişe ederseniz, erkeğin ailesinden bir hakem, kadının ailesinden bir hakem gönderin. İki taraf (arayı) düzeltmek isterlerse, Allah da onları uzlaştırır. Şüphesiz Allah, hakkıyla bilendir, hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 36, 'Yalnızca Allah’a ibadet edin ve O''na hiçbir şeyi ortak koşmayın. Ana babaya, akrabaya, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolda kalmışa, elinizin altındakilere iyilik edin. Şüphesiz Allah, kibirlenen ve övünen kimseleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (4, 37, 'Onlar, cimrilik ederler ve de herkese cimriliği tavsiye ederler. Allah''ın kendilerine lütfundan verdiği nimeti gizlerler. Biz kâfirlere alçaltıcı bir azap hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (4, 38, 'Onlar ki, Allah’a ve ahiret gününe iman etmedikleri halde, mallarını insanlara gösteriş için infak ederler. Şeytan kimin arkadaşı olmuşsa, o ne kötü bir arkadaştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 39, 'Bunlar, Allah’a ve ahiret gününe iman etselerdi ve Allah’ın verdiği rızıktan infak etselerdi ne olurdu? Allah, onları en iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 40, 'Şüphesiz Allah, zerre miktarı kadar bile haksızlık yapmaz. Bir iyilik olursa onu kat kat artırır ve kendi katından büyük bir mükâfat verir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 41, 'Her ümmetten bir şahit getirdiğimiz ve seni de onların üzerine bir şahit yaptığımız zaman, bakalım onların hâli nice olacak!');
INSERT INTO verses (sura, aya, text) VALUES (4, 42, 'O gün, küfre sapıp da Peygamber''e isyan edenler, yerle bir olmayı severek isteyecekler ve Allah’tan hiçbir sözü gizleyemeyecekler.');
INSERT INTO verses (sura, aya, text) VALUES (4, 43, 'Ey iman edenler! Sarhoş iken ne dediğinizi bilinceye dek namaza yaklaşmayın. Cünüp iken de içinden geçici olmanız dışında gusledinceye kadar namaza (ve camiye) yaklaşmayın. Eğer hasta veya yolculukta iseniz veya tuvaletten gelmişseniz yahut kadınlarınızla münasebette bulunmuş da su bulamamışsanız, temiz bir toprakla teyemmüm edin, yüzlerinize ve ellerinize hafifçe sürün (mesh edin). Şüphesiz Allah affeden ve bağışlayandır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 44, 'Kitaptan kendilerine belli bir pay verilen kimseleri görmüyor musun? Sapıklığı satın alıyor ve sizin de doğru yoldan sapmanızı arzu ediyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (4, 45, 'Allah, sizin düşmanlarınızı çok daha iyi bilir. Allah, dost olarak yeter. Allah, yardımcı olarak da yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 46, 'Yahudilerin bir kısmı, kelimelerin oldukları anlamlarını tahrif ederek; dillerini eğip büker, "İşittik, (emirlerine) isyan ettik, dinle, dinlemez olası ve râinâ (bizi gözet diyerek kendi dilleriyle söverler)" ve dine dil uzatırlar. Eğer, “İşittik ve itaat ettik, sen de işit ve (râinâ yerine) bize de bak!” deselerdi elbette kendileri için daha hayırlı ve daha doğru olurdu. Fakat, Allah, onları küfürleri dolayısıyla lanetlemiştir. Onların çok azından başkası iman etmez.');
INSERT INTO verses (sura, aya, text) VALUES (4, 47, 'Ey kendilerine kitap verilenler! Birtakım yüzleri silip de tersine çevirmeden yahut cumartesi halkını lanetlediğimiz gibi onları lanetlemeden, yanınızda bulunanı (Tevrat’ı) doğrulayıcı olarak indirdiğimiz bu kitaba (Kur’an’a) iman edin. Allah’ın emri mutlaka yerine gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 48, 'Allah, kendisine şirk koşulmasını asla bağışlamaz, bunun dışındakilerden dilediğini bağışlar. Kim, Allah’a şirk koşarsa büyük bir günahla iftira etmiş olur.');
INSERT INTO verses (sura, aya, text) VALUES (4, 49, 'Kendilerini temize çıkaranları görmedin mi? Allah dilediğini temize çıkarır ve hurma çekirdeğinin üzerindeki ince iplik/lif kadar bile zulme uğratılmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (4, 50, 'Allah’a karşı nasıl da yalan uydurduklarına bir bak! Bu, apaçık bir günah olarak onlara yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 51, 'Kendilerine kitaptan bir pay verilenleri görmüyor musun? Cibt’e ve Tâğût’a iman ediyorlar ve de kâfirler hakkında şöyle diyorlar: “Onlar, iman edenlerden daha doğru bir yoldadır."');
INSERT INTO verses (sura, aya, text) VALUES (4, 52, 'Onlar, Allah’ın lanet ettiği kimselerdir. Allah kime lanet ederse, artık ona asla bir yardımcı bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (4, 53, 'Yoksa onların hükümdarlıkta bir payları mı var? Eğer, öyle olsaydı insanlara, bir hurma çekirdeğinin üzerindeki oyuk miktarı bir pay bile vermezlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (4, 54, 'Yoksa onlar, Allah’ın kendi fazlından insanlara verdiklerine mi hased ediyorlar? Biz, İbrahim’in ailesine kitabı ve hikmeti vermişizdir. Onlara büyük bir mülk (saltanat) verdik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 55, 'Onlar arasından ona iman edenler de var, ondan yüz çevirenler de. Onlara çılgın alevli ateş olarak Cehennem yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 56, 'Şüphesiz ayetlerimizi inkâr edenleri biz ateşe atacağız. Derileri yanıp döküldükçe, azabı tatmaları için onların derilerini yenileyeceğiz. Şüphesiz Allah, mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 57, 'İman edip salih amel işleyenleri, altından ırmaklar akan, içinde ebedî kalacakları Cennetlere sokacağız. Onlar için orada tertemiz eşler vardır. Onları kalıcı gölgeliklere yerleştireceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (4, 58, 'Şüphesiz Allah sizlere, emanetleri ehline teslim etmenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emrediyor. Bununla, Allah size ne güzel bir öğüt veriyor. Doğrusu Allah işitendir, görendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 59, 'Ey iman edenler! Allah’a itaat edin. Peygamber’e itaat edin ve sizden olan ulu’l-emre (idarecilere) de. Herhangi bir hususta anlaşmazlığa düştüğünüz takdirde, Allah’a ve ahiret gününe gerçekten inanıyorsanız, onu Allah ve Rasûlüne arz edin. Bu, daha iyidir. Sonuç bakımından da daha güzeldir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 60, '(Ey Muhammed!) Sana indirilen Kur’an’a ve senden önce indirilene iman ettiklerini iddia edenleri görmüyor musun? Tâğût’u inkâr etmeleri kendilerine emrolunduğu halde, onun önünde muhakeme olmak istiyorlar. Şeytan da onları derin bir sapıklığa düşürmek istiyor.');
INSERT INTO verses (sura, aya, text) VALUES (4, 61, 'Münafıklara: "Haydi Allah’ın indirdiğine ve Peygamber’e gelin!" denildiği zaman, o münafıkların senden büsbütün yüz çevirip uzaklaştıklarını görürsün.');
INSERT INTO verses (sura, aya, text) VALUES (4, 62, 'Nasıl oluyor da, kendi elleriyle yaptıkları yüzünden başlarına bir musibet geldiği zaman sana gelip Allah’a yemin ederek; “Biz, iyilik ve ara bulmaktan başka bir şey istemedik” diyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (4, 63, 'Onlar, Allah’ın kalplerindekini bildiği kimselerdir. Öyleyse onlara aldırma. Onlara öğüt ver ve onlara, kendileri hakkında etkili ve güzel söz söyle.');
INSERT INTO verses (sura, aya, text) VALUES (4, 64, 'Biz, her bir peygamberi ancak, Allah’ın izniyle kendilerine itaat edilsin diye gönderdik. Eğer onlar, nefislerine zulmettikleri zaman, sana gelip Allah’tan bağışlanma dilemiş olsalardı, Peygamber de onlar için bağışlanma dileseydi, elbette Allah’ı tövbeleri kabul eden ve çok merhametli olarak bulurlardı.');
INSERT INTO verses (sura, aya, text) VALUES (4, 65, 'Hayır! Rabbine andolsun ki, aralarında çekiştikleri konularda seni hakem kılıp, verdiğin hükme kalplerinde hiçbir sıkıntı duymadan tam bir teslimiyetle teslim olmadıkça iman etmiş olmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (4, 66, 'Eğer gerçekten biz, onlara; “Kendinizi öldürün veya yurtlarınızdan çıkın!” diye emretmiş olsaydık, onlardan pek azı dışında çoğu bunu yapmazdı. Onlar kendilerine verilen öğüdü yerine getirselerdi, bu onlar için daha hayırlı ve daha sağlam olurdu.');
INSERT INTO verses (sura, aya, text) VALUES (4, 67, 'Biz de o zaman onlara katımızdan büyük bir mükâfat verirdik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 68, 'Ve elbette onları dosdoğru bir yola iletirdik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 69, 'Kimler de Allah’a ve Peygamber’e itaat ederse, artık onlar Allah’ın kendilerine nimet verdiği peygamberler, sıddıklar, şehitler ve salihlerle beraberdirler. Onlar ne güzel arkadaştır!');
INSERT INTO verses (sura, aya, text) VALUES (4, 70, 'İşte bu, Allah’ın bir lütfudur. Bir bilen olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 71, 'Ey iman edenler! (Düşmana karşı) tedbirinizi alın ve bölük bölük veya hep birden savaşa gidin.');
INSERT INTO verses (sura, aya, text) VALUES (4, 72, 'Şüphesiz, aranızda öyle kimseler var ki, (onların her biri savaşa gitme konusunda) hakikaten pek ağır davranır. Eğer başınıza bir musibet gelirse, “Allah, bana lütfetti de onlarla beraber bulunmadım” der.');
INSERT INTO verses (sura, aya, text) VALUES (4, 73, 'Eğer Allah’tan size bir lütuf (zafer) erişse, bu sefer de sizinle kendisi arasında hiçbir dostluk yokmuş gibi şöyle der: "Keşke ben de onlarla beraber olsaydım da büyük bir başarıya (ganimete) ulaşsaydım."');
INSERT INTO verses (sura, aya, text) VALUES (4, 74, 'O halde, dünya hayatı yerine ahireti alanlar, Allah yolunda savaşsınlar. Kim Allah yolunda savaşır, öldürülür veya galip gelirse, biz ona büyük bir ecir vereceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (4, 75, 'Size ne oluyor da "Ey Rabbimiz! Bizi, halkı zalim olan şu memleketten çıkar ve bize katından bir veli, bir yardımcı gönder." diyen zayıf bırakılmış erkekler, kadınlar ve çocuklar uğruna Allah yolunda savaşmıyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (4, 76, 'İman edenler, Allah yolunda savaşırlar. Kâfirler de tâğût yolunda savaşırlar. O halde, siz Şeytan''ın dostlarına karşı savaşın. Şüphesiz Şeytan''ın hilesi zayıftır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 77, 'Daha önce kendilerine, "(Savaşmaktan) ellerinizi çekin, namazı kılın, zekâtı verin!” denilenleri görmedin mi? Üzerlerine savaş yazılınca, hemen içlerinden bir kısmı; insanlardan, Allah’tan korkar gibi, hatta daha çok korkarlar ve: "Rabbimiz! Niçin bize savaş yazdın? Bizi yakın bir zamana kadar erteleseydin ya!” derler. De ki: “Dünya geçimliği azdır. Ahiret, Allah’a karşı gelmekten sakınan kimse için daha hayırlıdır. Size kıl kadar haksızlık edilmez."');
INSERT INTO verses (sura, aya, text) VALUES (4, 78, 'Her nerede olsanız olun, sapasağlam kaleler içinde bile olsanız ölüm gelip sizi bulur. Onların başına bir iyilik gelse: "Bu, Allah’tandır." derler. Onlara bir kötülük dokunsa "Bu, sendendir" derler. De ki: “Hepsi Allah’tandır.” Bu topluluğa ne oluyor ki; neredeyse hiç bir sözü anlamıyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (4, 79, 'Sana gelen her iyilik Allah’tandır. Kötülük olarak gelenler de kendi nefsindendir. Biz, seni insanlara elçi olarak gönderdik. Şahit olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 80, 'Kim, peygambere itaat ederse, şüphesiz Allah’a itaat etmiş olur. Kim de yüz çevirirse, biz seni onların başına bir bekçi olarak göndermedik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 81, 'Sana "İtaat ediyoruz” derler. Fakat senin yanından çıktıklarında, içlerinden birtakımı, geceleyin; (senin gündüz) söylediklerinin aksini kurarlar. Allah, onların geceleyin kurduklarını yazmaktadır. Sen onlara aldırma. Allah’a tevekkül et. Vekil olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 82, 'Hâlâ Kur’an’ı düşünüp anlamaya çalışmıyorlar mı? Eğer o, Allah’tan başkası tarafından (indirilmiş) olsaydı, mutlaka onda birçok çelişki bulurlardı.');
INSERT INTO verses (sura, aya, text) VALUES (4, 83, 'Onlara güven veya korkuya dair bir haber gelince hemen onu yayarlar; halbuki onu, Rasûl''e veya emir sahibi olanlara götürselerdi, onlardan sonuç çıkarmaya kadir olanlar, onun ne olduğunu bilirlerdi. Allah''ın size lütuf ve rahmeti olmasaydı, pek azınız müstesna, şeytana uyup giderdiniz.');
INSERT INTO verses (sura, aya, text) VALUES (4, 84, 'Öyleyse, Allah yolunda savaş! Sen yalnızca kendinden sorumlusun. Müminleri de savaşa teşvik et. Umulur ki Allah küfredenlerin gücünü kırar. Allah''ın gücü de, cezası da pek şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 85, '(Kim, güzel bir işe aracılık ederse, onun bu işte (sevapta ) bir nasibi olur. Kim de kötü bir işe aracılık ederse, onun da bundan (günahtan) bir payı olur. Allah her şeyin karşılığını vericidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 86, 'Size bir selam verildiği zaman, ondan daha güzeliyle veya aynı selamla karşılık verin. Şüphesiz Allah, her şeyin üzerinde hesabı görendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 87, 'Allah’tan başka hak ilah yoktur. Kendisinde hiçbir şüphe olmayan kıyamet gününde sizleri elbette bir araya getirecektir. Allah’tan daha doğru sözlü kim vardır?');
INSERT INTO verses (sura, aya, text) VALUES (4, 88, 'Size ne oluyor da münafıklar hakkında iki gruba ayrıldınız? Allah, onları yaptıkları işlerden dolayı baş aşağı ederek eski konumlarına (küfre) döndürmüştür. Allah’ın saptırdığını doğru yola getirmek mi istiyorsunuz? Allah kimi saptırırsa, sen onun için asla bir çıkış yolu bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (4, 89, 'Onlar, kendileri küfre saptıkları gibi, keşke siz de küfre sapsanız da eşit olasınız isterler. Allah yolunda hicret etmedikçe onlardan dost edinmeyin. Dolayısıyla eğer yüz çevirirlerse, bu durumda onları tutun ve bulduğunuz yerde öldürün. Onlardan dost ve yardımcı edinmeyin.');
INSERT INTO verses (sura, aya, text) VALUES (4, 90, 'Ancak sizinle aralarında anlaşma bulunan bir kavme sığınanlar veya ne sizinle ne de kendi kavimleriyle savaşmak istemediklerinden göğüsleri daralarak size gelenler bundan müstesnadır. Eğer Allah dileseydi, bunları size musallat eder ve bunlar da sizinle savaşırlardı. O halde, onlar sizden uzak durur, sizinle savaşmazlar ve size barış teklif ederlerse, artık Allah onlara saldırmak için size yol vermez.');
INSERT INTO verses (sura, aya, text) VALUES (4, 91, 'Hem sizden hem de kendi kavminden güven içinde olmayı isteyen başkalarını da bulacaksınız. Ama fitneye her sevk edildiklerinde ona (şiddetle) atılırlar. Şayet sizden uzak durmaz, barış istemez ve ellerini de çekmezlerse, onları bulduğunuz yerde tutup öldürün. İşte onların aleyhlerine (savaşmanız için) size apaçık bir delil verdik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 92, 'Bir Müminin bir Mümini hata dışında öldürmesi olmaz. Eğer bir kimse bir Mümini yanlışlıkla öldürürse, onun cezası Mümin bir köle azat etmek ve öldürülenin ailesi bağışlamadıkça, ailesine teslim edilen bir diyettir. Eğer ölen, Mümin olduğu halde size düşman bir toplumdan ise, bu takdirde ceza bir Mümin köle azat etmektir. Eğer sizinle aranızda anlaşma bulunan bir toplumdan ise, öldürülenin ailesine teslim olunan bir diyet ve Mümin bir köle azat etmektir. Fakat kim bunu bulamazsa, Allah tarafından tövbesinin kabul edilmesi için iki ay peş peşe oruç tutmaktır. Allah her şeyi bilendir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 93, 'Kim bir Mümini kasten öldürürse cezası, içinde ebedi kalacağı Cehennem''dir. Allah, ona gazap etmiş, onu lanetlemiş ve ona büyük bir azap hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 94, 'Ey iman edenler! Allah yolunda savaşa çıktığınızda durumu iyice araştırıp anlamadan size selam veren kimseye, dünya hayatını arzulayarak; “Sen Mümin değilsin!” demeyin. Zira Allah katında pek çok ganimetler vardır. Daha önceden siz de öyleydiniz de, Allah size ihsan etti. Öyleyse iyice araştırıp anlayın. Allah şüphesiz yaptıklarınızdan haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 95, 'Müminlerden özür sahibi olmaksızın geri kalanlarla, Allah yolunda mallarıyla ve canlarıyla savaşanlar bir olmazlar. Allah, mallarıyla ve canlarıyla savaşanları, derece bakımından geri kalanlardan üstün kıldı. Bununla beraber Allah, hepsine güzellik (Cennet''i) vaat etmiştir. Fakat Allah savaşanlara, geride kalanların üstünde pek büyük bir mükâfat vermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 96, 'Mücahitler için Allah katından dereceler, mağfiret ve rahmet vardır. Allah, çokça bağışlayandır, merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 97, 'Melekler kendi nefislerine zulüm edenlerin canlarını aldıkları zaman onlara, “Ne işte idiniz?” deyince, “Biz yeryüzünde zayıf bırakılmış kimselerdik” derler. Melekler de “Allah''ın arzı geniş değil miydi? Hicret etseydiniz ya!” cevabını verirler. İşte onların varacakları yer cehennemdir. Orası pek de kötü dönülecek yerdir!');
INSERT INTO verses (sura, aya, text) VALUES (4, 98, 'Ancak gerçekten zayıf ve güçsüz olan, çaresiz kalan ve hicret etmeye yol bulamayan erkekler, kadınlar ve çocuklar başkadır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 99, 'Umulur ki Allah onları affeder. Şüphesiz Allah, affedendir, bağışlayandır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 100, 'Kim, Allah yolunda hicret ederse, yeryüzünde barınacak birçok geniş yer bulur. Kim, evinden Allah’a ve Rasûlüne hicret etmek için ayrılır da kendisine ölüm yetişirse, onun mükâfatı Allah’a aittir. Allah, çok bağışlayıcı ve merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 101, 'Yeryüzünde bir yolculuğa çıktığınız zaman, kâfirlerin size saldırmasından korkarsanız, namazı kısaltmanızdan ötürü size bir günah yoktur. Şüphesiz kâfirler, sizin apaçık düşmanınızdır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 102, 'Sen (savaş meydanında) onların aralarında olup da namazlarını kıldırdığın zaman, bir kısmı seninle beraber namaza dursun ve silahlarını da yanlarına alsınlar; secdeyi yaptıktan sonra onlar arkanıza geçsinler;kılmayan öbür kısım gelsin, seninle beraber kılsınlar, tedbirli olsunlar, silahlarını alsınlar. Kâfirler arzu ederler ki, silâhlarınızdan ve eşyanızdan bir gafil olsanız da size ani bir baskın yapsalar. Eğer yağmur dolayısıyla size bir eziyet/zorluk olursa veya hasta olursanız silahlarınızı bırakmanızda bir günah yoktur. Yine de tedbirli olun. Allah, Kâfirlere aşağılayıcı bir azap hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 103, 'Namazı tamamladıktan sonra, ayakta, otururken ve yatarken de Allah’ı zikredin. Emniyete ve sükuna kavuştuğunuz zaman namazı dosdoğru şekliyle kılın. Namaz şüphesiz iman edenlere belirli vakitlerde farz kılınmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 104, 'O topluluğu aramada/takip etmekte gevşeklik göstermeyin. Siz (yaralanıp) acı duyuyorsanız onlar da sizin hissettiğiniz gibi acı duyuyor. Onların ümit etmediği şeyi (sevap ve zaferi) siz Allah Teâlâ''dan ümit edersiniz. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 105, 'Şüphesiz biz, sana kitabı insanlar arasında Allah’ın sana gösterdiği şekilde hüküm veresin diye hak olarak indirdik. Hainlerin savunucusu olma!');
INSERT INTO verses (sura, aya, text) VALUES (4, 106, 'Allah’tan mağfiret dile. Şüphesiz Allah, çokça bağışlayan ve merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 107, 'Nefislerine (günah işleyerek) hainlik edenleri savunma. Şüphesiz Allah, hainlik eden günahkârları sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (4, 108, 'İnsanlardan gizlerler de Allah''tan gizlemezler. Hâlbuki onlar O''nun razı olmayacağı sözü, geceleyin konuşup düzenledikleri zaman da O onlarla beraberdi. Allah yapacakları her şeyi kuşatıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 109, 'İşte siz, dünya hayatında onları savunuyorsunuz. Kıyamet gününde kim onları Allah''a karşı müdafaa eder, kim onlara vekil olur?');
INSERT INTO verses (sura, aya, text) VALUES (4, 110, 'Kim bir kötülük işler veya kendi nefsine zulmeder de ardından Allah’tan bağışlanma dilerse, Allah’ı çokça bağışlayıcı ve merhamet eden olarak bulur.');
INSERT INTO verses (sura, aya, text) VALUES (4, 111, 'Kim bir günah işlerse, o günahı sadece kendi aleyhine işlemiş olur. Allah her şeyi bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 112, 'Kim de bir hata veya günah kazanır da sonra onu bir suçsuzun üzerine atarsa, muhakkak ki, büyük bir iftira ve apaçık bir günah yüklenmiş olur.');
INSERT INTO verses (sura, aya, text) VALUES (4, 113, 'Eğer Allah’ın lütfu ve rahmeti senin üzerinde olmasaydı, onlardan bir grup seni saptırmaya çalışmıştı. Onlar, kendilerinden başkasını saptıramazlar ve sana hiçbir şeyle zarar veremezler. Allah sana kitabı ve hikmeti indirmiş, önceden bilmediklerini öğretmiştir. Allah’ın senin üzerindeki lütuf ve ihsanı çok büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (4, 114, 'Ancak bir sadaka vermeyi veya iyilikte bulunmayı ya da insanların arasını düzeltmeyi emredenler dışında, onların fısıldaşmalarının çoğunda hayır yoktur. Kim Allah’ın rızasını gözeterek böyle yaparsa Biz ona büyük bir mükâfat vereceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (4, 115, 'Kim, kendisine doğru yol apaçık belli olduktan sonra rasûle muhalefet eder ve Müminlerin yolundan başka bir yola uyarsa, onu girmiş olduğu bu yolda bırakır ve Cehennem''e atarız. O, ne kötü bir dönüş yeridir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 116, 'Allah, kendisine şirk koşulmasını asla bağışlamaz, bunun dışındaki (günahları) dilediği kimse için bağışlar. Kim Allah’a şirk koşarsa büsbütün sapıtmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 117, 'Onlar, Allah''ı bırakırlar da, yalnız dişilere taparlar (isimleri dişi ismi olan batıl tanrılardan istiyorlar). Böylece ancak inatçı şeytana ibadet ediyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (4, 118, 'Allah ona lanet etmiştir. O da: “Andolsun, kullarından belli bir pay alacağım” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (4, 119, 'Ve onları saptıracağım, onları boş kuruntularla aldatacağım. Onlara emredeceğim de (putlara adak için) hayvanların kulaklarını yaracaklar. Onlara emredeceğim de Allah’ın yarattığını değiştirecekler. Kim Allah’ı bırakıp da Şeytan''ı veli edinirse, apaçık bir hüsrana uğramıştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 120, 'Şeytan onlara vaadeder ve onları kuruntuya düşürür. Halbuki, şeytan onlara bir aldatmadan başka bir şey vaadetmez.');
INSERT INTO verses (sura, aya, text) VALUES (4, 121, 'İşte onların barınacakları yer Cehennem''dir ve ondan kurtulmak için hiçbir yer bulamayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 122, 'İman edip salih ameller işleyenlere gelince onları, altından ırmaklar akan ve içinde ebedî kalacakları Cennetlere sokacağız. Allah''ın vaadi haktır. Allah''tan daha doğru sözlü kim vardır?');
INSERT INTO verses (sura, aya, text) VALUES (4, 123, 'İş, ne sizin kuruntunuza, ne de kitap ehlinin kuruntusuna göredir. Kim kötü bir iş yaparsa, onunla cezalandırılır. O, kendisine Allah’tan başka ne bir dost, ne de bir yardımcı bulabilir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 124, 'Mümin olarak kim bir salih amel işlerse erkek olsun, kadın olsun işte bunlar Cennet''e girecekler ve bir hurma çekirdeğinin üzerindeki çukur kadar bile haksızlık görmeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 125, 'Kimin dini, iyilik yaparak kendini Allah’a teslim eden ve hakka yönelen İbrahim’in dinine tabi olan kimsenin dininden daha güzeldir? Allah, İbrahim’i dost/halil edindi.');
INSERT INTO verses (sura, aya, text) VALUES (4, 126, 'Göklerde ve yerde ne varsa hepsi Allah’ındır. Allah bütün her şeyi kuşatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 127, 'Kadınlar hakkında senden fetva isterler, de ki: "Onlar hakkında fetvayı size Allah veriyor: "Bu fetva, kendilerine yazılan şeyi vermeyip kendileriyle evlenmeyi arzuladığınız yetim kadınlara ve bir de zavallı çocuklara ve yetimlere doğrulukla bakmanız hususunda Kitap''da size okunandır". Ne iyilik yaparsaniz Allah onu şüphesiz çok iyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 128, 'Eğer bir kadın, kocasının geçimsizliğinden veya yüz çevirmesinden korkuyorsa, bir anlaşma ile aralarını düzeltmelerinde bir günah yoktur. Anlaşma daha iyidir. Nefisler kıskançlığa meyyaldir. Eğer iyilik eder ve geçimsizlikten sakınırsanız, şüphesiz Allah, yaptığınız her şeyden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 129, 'Ne kadar isteseniz de kadınlarınız arasında (sevgide) eşit davranamazsınız. O halde büsbütün birine meyledip de diğerlerini askıda (kocasızmış gibi) bırakmayın. Eğer (amellerinizi) düzeltir ve (haksızlıktan) sakınırsanız bilin ki, Allah affedici ve merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 130, 'Eğer (eşler) birbirinden ayrılırsa, Allah lütfuyla her birini zenginleştirir, Allah’ın ihsanı geniştir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 131, 'Göklerde ve yerde ne varsa hepsi Allah’ındır. Sizden önce kendilerine kitap verilenlere de, size de Allah’tan korkun diye tavsiye ettik. Eğer inkâr ederseniz bilin ki, göklerde ve yerde olan her şey Allah’ındır. Allah hiçbir şeye muhtaç değildir. Hamt edilmeye layık olandır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 132, 'Göklerde ve yerde ne varsa Allah’ındır. Vekil olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 133, 'Ey insanlar! Eğer O dilerse sizi yok eder ve (yerinize) başkalarını getirir. Allah’ın buna elbette gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 134, 'Kim dünya mükâfatını isterse, bilsin ki dünyanın da, ahiretin de mükâfatı Allah''ın katındadır. Allah herşeyi, işitendir, görendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 135, 'Ey iman edenler! Kendiniz, ana babanız ve yakınlarınız aleyhlerine de olsa, Allah için şahit olarak adaleti ayakta tutanlardan olunuz. Zengin olsun fakir olsun doğru şahitlik edin. Allah, her ikisine de sizden daha yakındır. Nefsinizin arzusuna uyarak adaletten ayrılmayın. Eğer (şahitlik konusunda) dilinizi eğip bükerseniz ve (yerine getirmekten) yüz çevirirseniz, şüphesiz Allah yaptıklarınızdan haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 136, 'Ey iman edenler! Allah’a, peygamberine, peygamberine indirdiği kitaba ve daha önce indirdiği kitaba iman ediniz. Kim, Allah’ı, meleklerini, kitaplarını, peygamberlerini ve ahiret gününü inkâr ederse, şüphesiz uzak bir sapıklığın içine düşmüştür.');
INSERT INTO verses (sura, aya, text) VALUES (4, 137, 'İman edip ardından kâfir olanlar sonra tekrar iman edip daha sonra da kâfir olup küfürlerini artıranları Allah bağışlamayacaktır ve onlara bir yol da göstermeyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 138, 'Münafıklara, kendileri için çok elem verici bir azabın olduğunu müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (4, 139, 'Onlar, Müminleri bırakıp kâfirleri dost/veli edinirler. Kâfirlerin yanında güç/zafer mi arıyorlar? İzzet bütünüyle Allah’a aittir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 140, 'Allah, size kitabında şunu da indirmiştir: Allah’ın ayetlerinin inkâr edildiğini ve ayetleriyle alay edildiğini işittiğiniz zaman, başka konuya geçinceye kadar onlarla oturmayın. (Eğer oturursanız) siz de onlar gibi olursunuz. Allah, bütün münafıkları ve kâfirleri Cehennem''de toplayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 141, 'Sizi gözetleyen (münafık) kimseler, eğer size Allah’tan bir zafer gelirse: "Sizinle beraber değil miydik?" derler. Eğer kâfirlere (savaşta) bir hisse düşerse: “Size (yardım ederek) üstünlük sağlayıp sizi Müminlerden korumadık mı?” derler. Allah, kıyamet günü aranızda hüküm verecektir. Allah, kâfirlere Müminlerin aleyhine bir yol vermeyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 142, '(Doğrusu münafıklar (sözde), Allah''ı aldatmak isterler. Hâlbuki Allah onların oyunlarını başlarına çevirmektedir. Namaza kalktıkları zaman, üşenerek kalkarlar. İnsanlara gösteriş yaparlar ve Allah''ı pek az anarlar.');
INSERT INTO verses (sura, aya, text) VALUES (4, 143, 'İmanla küfür arasında tereddüt ederek, ne Müminlere ne de kâfirlere bağlıdırlar. Allah, kimi saptırırsa onun için asla hidayetin bir yolunu bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (4, 144, 'Ey iman edenler! Müminleri bırakıp kâfirleri veli edinmeyin. (Böyle yaparak) Kendi aleyhinize Allah’a apaçık bir delil mi vermek istiyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (4, 145, '(Münafıklar Cehennem''in en aşağı tabakasındadırlar. Artık onlara asla bir yardımcı bulamazsın.)');
INSERT INTO verses (sura, aya, text) VALUES (4, 146, 'Ancak, tevbe edenler, (hallerini) düzeltip, Allah’a bağlananlar ve dinlerini Allah''a halis kılanlar işte onlar Müminlerle beraberdir. Allah, Müminlere büyük bir mükâfat verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 147, 'Eğer şükreder ve iman ederseniz, Allah size niye azap etsin ki? Allah, şükrün karşılığını verendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 148, 'Allah kötü sözün açıkça söylenmesini sevmez; ancak haksızlığa uğrayan başka. Allah her şeyi işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 149, 'Bir hayrı açıklar veya gizlerseniz, yahut bir kötülüğü affederseniz (bilin ki), Allah da çok affedicidir, her şeye hakkıyla gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 150, 'Allah’ı ve rasûllerini inkâr edenler, Allah ile rasûllerinin arasını ayırmak isteyenler; "Bir kısmına iman eder; bir kısmını inkâr ederiz” diyerek (iman ile küfür) arasında bir yol tutmak isterler.');
INSERT INTO verses (sura, aya, text) VALUES (4, 151, 'İşte onlar, gerçekten kâfirdirler. Bu kâfirler için rezil edici bir azap hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (4, 152, 'Allah’a ve rasûllerine iman edip, rasûllerinden hiçbirinin arasında ayrım yapmayanlara ise, onlara mükâfatları verilecektir. Allah, bağışlayan, merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 153, 'Ehl-i Kitap senin kendilerine gökten bir kitap indirmeni istiyorlar. Mûsâ’dan bundan daha büyüğünü istemişlerdi: Bize Allah’ı apaçık göster, demişlerdi. Zulümleri yüzünden onları yıldırım çarpmıştı. kendilerine deliller geldikten sonra da buzağıyı ilah edinmişlerdi. Ardından onları bağışladık ve Mûsâ''ya apaçık delil verdik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 154, 'Söz verdikleri için dağı onların tepesine kaldırdık. Onlara: "Kapıdan secde ederek girin!" dedik. Onlara: "Cumartesi günü yasağını çiğnemeyin!" diyerek onlardan kesin bir söz aldık.');
INSERT INTO verses (sura, aya, text) VALUES (4, 155, 'Verdikleri sözü bozmaları, Allah’ın ayetlerini inkâr etmeleri ve peygamberleri haksız yere öldürmeleri ve kalplerimiz perdelidir, demeleri sebebiyle, Allah, küfürlerine karşılık onların kalplerini mühürledi. Artık onlar, pek azı hariç iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (4, 156, 'Bu, küfürleri ve Meryem’e büyük bir iftirada bulunmaları sebebiyledir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 157, 'Allah’ın Rasûlü Meryem oğlu İsâ Mesih’i biz öldürdük, demeleri sebebiyle (onları lanetledik). Oysa onu öldürmediler, asmadılar da. Ancak ona benzeyen biri kendilerine gösterildi. Onun hakkında ihtilaf edenler, bu konuda şüphe içindedirler. Onların zanna uymaktan başka bir bilgileri de yoktur. Kesinlikle onu öldürmediler.');
INSERT INTO verses (sura, aya, text) VALUES (4, 158, 'Aksine Allah, onu kendi katına yükseltti. Allah, Aziz''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 159, 'Ehl-i Kitap''tan hiç kimse yoktur ki ölümünden önce, ona (İsâ’ya) iman edecek olmasın. Kıyamet günü, o (İsâ) onların aleyhine şahit olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 160, 'Böylece Yahudilerin zulümleri ve de birçok kimseleri Allah yolundan alıkoymaları sebebiyle (önceleri) kendilerine helal kılınmış temiz şeyleri onlara haram kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (4, 161, 'Kendilerine yasaklanmış olmasına rağmen faiz almaları ve insanların mallarını batıl yolla yemeleri dolayısıyla, kâfir olanlar için acı veren bir azap hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (4, 162, 'Fakat onlardan ilimde derinleşip sana indirilene, senden önce indirilenlere iman eden, namazı dosdoğru kılan, zekât veren Müminlere, Allah’a ve ahiret gününe iman etmiş olanlara, işte onlara çok büyük bir mükâfat vereceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (4, 163, 'Nûh’a ve ondan sonra gelen peygamberlere vahyettiğimiz gibi sana da vahyettik. İbrahim’e, İsmail’e, İshak’a, Ya''kûb’a, torunlarına, İsâ’ya, Eyyûb’a, Yûnus’a, Hârûn’a ve Süleyman’a da vahyettik. Dâvud’a da Zebur’u verdik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 164, 'Peygamberlerden bir kısmını daha önce sana anlatmış, bir kısmını da anlatmamıştık ve Allah, Mûsâ ile gerçekten konuştu.');
INSERT INTO verses (sura, aya, text) VALUES (4, 165, 'Müjdeleyiciler ve uyarıcılar olarak rasûller gönderdik ki, rasûllerden sonra insanların Allah’a karşı bir bahaneleri olmasın. Allah Aziz''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 166, 'Lakin, Allah sana indirdiğine şahitlik eder ki, onu kendi ilmi ile indirmiştir. Melekler de şahitlik ederler. Şahit olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 167, 'Şüphesiz inkâr edenler, insanları Allah yolundan alıkoyanlar derin bir sapıklığa düşmüşlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 168, 'Kâfir olup, zulmedenleri Allah asla, bağışlayacak ve doğru yola iletecek değildir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 169, 'Cehennemin yolundan başkasına; ki onlar orada ebediyyen kalıcıdırlar. Bu ise Allah’a pek kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 170, 'Ey insanlar! Şüphesiz Rasûl size Rabbinizden hak olan şey ile geldi. Öyleyse iman etmeniz sizin için hayırlıdır. Eğer inkâr ederseniz, göklerde ve yerde olanlar Allah’ındır. Allah Alim''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 171, 'Ey Ehli Kitap! Dininizde taşkınlık etmeyin. Allah hakkında doğru olandan başka bir şey söylemeyin. Meryem oğlu İsâ Mesih, sadece Allah’ın Rasûlü ve Meryem''e ulaştırdığı bir kelimesi ve kendinden bir ruhtur. Allah’a ve peygamberlerine iman edin! “Üçtür” demeyin. Kendi iyiliğiniz için bundan vazgeçin. Allah sadece tek bir ilahtır, bir çocuğu olmaktan münezzehtir. Göklerdeki ve yerdekiler O''nundur. Vekil olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (4, 172, 'Mesih, Allah’a kul olmaktan asla büyüklenip çekinmemiştir. Yakın melekler de (kulluktan çekinmezler). Kim Allah’a kulluktan çekinir ve büyüklük taslarsa; bilsin ki Allah, herkesi huzurunda toplayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 173, 'İman edip salih ameller işleyenlere mükâfatlarını verecek ve onlara nimetini daha da artıracak, (ibadet etmekten) çekinenleri ve büyüklük taslayanları da acı bir azap ile cezalandıracaktır. Kendilerine Allah’tan başka bir veli ve yardımcı da bulamayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (4, 174, 'Ey insanlar! Size Rabbinizden kesin bir delil geldi ve size apaçık bir nur indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (4, 175, 'Allah, kendisine iman edip, Kur’an’a sarılanları rahmetine ve bol nimetlerine girdirecek ve onları kendisine (götüren) dosdoğru bir yola iletecektir.');
INSERT INTO verses (sura, aya, text) VALUES (4, 176, 'Senden fetva isterler. De ki: Allah size kelâle/babasız ve çocuksuz miras bırakan kimse hakkında hükmü açıklıyor. Eğer çocuğu olmayıp bir kız kardeşi bulunan kimse ölürse, bıraktığının yarısı kız kardeşinindir. Eğer kız kardeş ölür de çocuğu da bulunmazsa, erkek kardeş malının tümüne varis olur. Eğer iki kız kardeşi varsa bu ikisine (erkek kardeşin bıraktığı) mirasın üçte ikisi düşer. Eğer mirasçılar erkek ve kadın kardeşler ise, erkeğe iki kadının hissesi kadar düşer. Sapmayasınız diye Allah size (hükmünü) açıklıyor. Allah her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 1, 'Ey iman edenler! Sözleşmelerinizi yerine getirin. Haram kılındığı size bildirilenler dışında, davarların (eti) size helâl kılınmıştır. (Hac ya da umre için) ihram halinde iken de avlanmak helâl değildir. Allah dilediği hükmü verir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 2, 'Ey iman edenler! Allah’ın nişanelerine, haram aya, (Kâbe''ye hediye edilen) kurbana (yine hediyelik olduğuna işaret) gerdanlık takılan hayvanlara, Rablerinin lütfunu arayarak Beyt-i Haram''a yönelmiş kimselere (saldırı ve saygısızlığı), helal saymayın. İhramdan çıktığınız zaman avlanın. Sizi Mescid-i Haram’a girmenizi engellediği için bir topluma olan kininiz, aşırı gitmenize sebep olmasın. İyilik ve takva hususunda birbirinize yardımcı olun. Günah ve düşmanlık hususunda birbirinize yardım etmeyin. Allah’tan sakının/takvalı olun. Allah’ın cezalandırması şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 3, 'Leş, kan, domuz eti, Allah’tan başkası adına kesilenler, boğulmuş, bir şey vurularak öldürülmüş, düşüp ölmüş, süsülmüş, yırtıcı hayvanlar tarafından yenilmiş olanlar -(ölmeden önce yetişip) kestikleriniz hariç- ve (ibadet olunan putlar) dikili taşlar adına kesilen hayvanlar ve (karar vermek için) kaseler (içine yap-yapma-boş yazıp bu şekilde karar vermeniz) ile kura çekmeniz size haram kılınmıştır. İşte bunları yapmak (Allah''a itaatten) çıkmaktır. Bugün kâfirler, sizin dininizden (döneceğiniz hakkında) ümitlerini kesmişlerdir. Onlardan korkmayın, benden korkun. Bugün sizin dininizi kemale erdirdim, üzerinizdeki nimetimi tamamladım ve sizin için din olarak İslam’dan razı oldum. Kim, açlık dolayısıyla zorda kalırsa, günaha yönelme kasdı olmadan (bu yasaklanan hayvanlardan yiyebilir.) Allah, çokça bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 4, 'Sana, kendilerine neyin helal kılındığını soruyorlar. De ki: Temiz olanlar size helal kılınmıştır. Allah''ın size öğrettiğinden öğrenip, eğittiğiniz avcı hayvanların sizin için tuttuklarını yiyin. (Onu av için salarken) üzerine Allah’ın adını anın (besmele çekin). Allah’tan sakının/takvalı olun. Doğrusu Allah, hesabı çabucak görüverir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 5, 'Bu gün size temiz ve hoş şeyler helâl kılındı. Kendilerine kitap verilenlerin yiyecekleri size helâl, sizin yiyecekleriniz de onlara helâldir. Mümin kadınlardan iffetli olanlarla, daha önce kendilerine kitap verilenlerden (Yahudi ve Hristiyan) hür ve iffetli kadınlar da, mehirlerini vermeniz kaydıyla; evlenmek, zina etmemek ve gizli dost tutmamak üzere size helâldir. Her kim de inanılması gerekenleri inkâr ederse, bütün işlediği boşa gider. Ahirette de o, ziyana uğrayanlardandır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 6, 'Ey İman edenler! Namaza kalktığınız zaman yüzlerinizi, dirseklere kadar ellerinizi, başınızı mesh edip, topuklara kadar ayaklarınızı yıkayınız. Eğer cünüp iseniz (gusül alarak) temizlenin, hasta veya yolculukta iseniz veya biriniz tuvaletten gelmişseniz yahut kadınlarınızla münasebette bulunmuş da su bulamamışsanız temiz bir toprakla teyemmüm edin, yüzlerinizi ve ellerinizi onunla meshedin. Allah, size zorluk çıkarmak istemez. Allah sizi arındırmak ve üzerinizdeki nimetini tamamlamak ister. Umulur ki şükredersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (5, 7, 'Allah’ın size olan nimetini ve “İşittik, itaat ettik!” dediğinizde sizden aldığı sağlam sözünüzü düşünün, Allah’tan sakının/takvalı olun. Allah, kalplerde olanı çok iyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 8, 'Ey İman edenler! Allah için adaleti ayakta tutan şahitler olun. Bir topluma olan öfkeniz sizi adaletsizliğe sürüklemesin, adil olun, bu takvaya daha uygundur. Allah’tan sakının/takvalı olun. Şüphesiz Allah, yaptıklarınızın tümünden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 9, 'Allah, iman edip salih amel işleyenlere mağfiret ve büyük bir mükâfat olduğunu vadetmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 10, 'Kafir olup da ayetlerimizi yalanlayanlar var ya; işte onlar cehennemliklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 11, 'Ey iman edenler! Allah’ın üzerinizdeki nimetini düşünün. Hani bir topluluk size (saldırmak için) elini uzatmıştı da Allah onların ellerini sizden çekmişti. Allah’tan sakının/takvalı olun. Müminler ancak Allah’a tevekkül etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 12, 'Allah İsrailoğulları''ndan sağlam bir söz almıştı. Onlardan on iki temsilci (başkan) seçmiştik. Allah: "Ben sizinleyim" dedi. Namaz kılarsanız, zekat verirseniz, rasûllerime iman eder ve onlara yardım ederseniz, Allah’a güzel bir borç verirseniz, elbette sizin kötülüklerinizi örterim. Sizi altından nehirler akan Cennetlere sokarım. Bundan sonra sizden kim küfredip inkâr ederse doğru yoldan sapmış olur.');
INSERT INTO verses (sura, aya, text) VALUES (5, 13, 'Sözlerini bozdukları için onları lanetledik, kalplerini katılaştırdık. Kelimeleri yerlerinden tahrif edip,değiştirdiler. Kendilerine hatırlatılanlardan bir kısmını unuttular. İçlerinden çok azı dışında onların daima hainliklerini görürsün. Yine de sen onları affet ve aldırış etme. Allah, ihsan sahiplerini sever.');
INSERT INTO verses (sura, aya, text) VALUES (5, 14, 'Biz Hristiyanız, diyenlerden de sağlam söz almıştık. Onlar da kendilerine hatırlatılanlardan bir kısmını unuttular. Bu yüzden aralarına kıyamete kadar sürecek düşmanlık ve kin saldık. Allah, onların yapmakta olduklarını (hesap günü) kendilerine haber verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 15, 'Kitap''dan gizleyip durduğunuzun çoğunu size açıkça anlatan ve çoğunu da (açıklamadan) geçiveren rasûlümüz gelmiştir. Doğrusu size Allah’tan bir aydınlatıcı ve apaçık/açıklayıcı bir kitap gelmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 16, 'Allah, rızasına uyanları onunla selamet yollarına eriştirir ve onları izni ile karanlıklardan aydınlığa çıkarır. Onları dosdoğru yola iletir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 17, 'Allah, Meryem oğlu Mesih’tir, diyenler kâfir olmuştur. De ki: Allah, Meryem oğlu Mesih’i, anasını ve yeryüzünde olanların hepsini yok etmeyi dilese, Allah’a karşı kim buna engel olabilir. Göklerin, yerin ve arasındakilerin mülkü Allah’ındır. O, dilediğini yaratır. Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (5, 18, 'Yahudi ve Hristiyanlar: Biz, Allah’ın oğulları ve sevdikleri kimseleriz dediler. De ki: Öyleyse günahlarınız sebebiyle Allah, size niye azap ediyor? Hayır, siz de onun yarattıklarından bir beşersiniz! Allah dilediğini bağışlar, dilediğine azap eder. Göklerin, yerin ve ikisinin arasındakilerin mülkü Allah’ındır. Ve ancak dönüş de O’nadır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 19, 'Ey Ehl-i Kitap! Peygamberlerin arasının kesildiği bir dönemde; “Bize, müjdeci ve uyarıcı gelmedi.” demeyesiniz diye, size gerçekleri açıkça anlatan Rasûlümüz geldi. O, müjdeci ve uyarıcı olarak gelmiştir. Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (5, 20, 'Hani Mûsâ, kavmine demişti ki: Ey kavmim! Allah’ın, üzerinizdeki nimetini hatırlayın. Hani içinizden peygamberler çıkarmıştı. Sizi hükümdarlar kılmıştı ve (diğer) toplumlardan hiçbirine vermediğini size vermişti.');
INSERT INTO verses (sura, aya, text) VALUES (5, 21, 'Ey kavmim! Allah’ın size yazdığı Arz-ı Mukaddes''e /kutsal yere girin. Ardınıza dönmeyin! Yoksa hüsrana uğrayanlar olursunuz, demişti.');
INSERT INTO verses (sura, aya, text) VALUES (5, 22, 'Ey Mûsâ! Orada zorba bir kavim var, onlar oradan çıkmadıkça biz oraya girmeyeceğiz. Eğer çıkarlarsa biz de gireriz, diye karşılık vermişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 23, '(Allah''tan) Korkanlar arasında bulunan Allah’ın kendilerine nimet verdiği iki adam, üzerlerine (şehrin) kapısından girin, oradan girerseniz, muhakkak galip gelirsiniz. Eğer, Mümin kimseler iseniz, ancak Allah’a tevekkül edin, demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 24, 'Ey Mûsâ! Onlar orada oldukça biz asla oraya girmeyeceğiz. Sen ve Rabbin gidin savaşın. Biz burada oturacağız, demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 25, 'Mûsâ: Rabbim! Ben kendimden ve kardeşimden başkasına güç yetiremiyorum. Artık bizimle bu fasık toplumun arasını ayır, dedi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 26, 'Allah da: Orası onlara kırk yıl haram kılındı. Yeryüzünde şaşkın şaşkın dolaşacaklar. Sen, fasık toplum için tasalanma! dedi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 27, 'Onlara Âdem’in iki oğlunun haberini anlat. İkisi de birer kurban sunmuşlar, birininki kabul edilmiş; diğerininki edilmemişti. (Kurbanı kabul edilmeyen): Kesinlikle seni öldüreceğim! dedi. Diğeri: Allah, ancak muttakilerden kabul eder. dedi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 28, 'Beni öldürmek için elini bana uzatırsan, ben seni öldürmek için elimi sana uzatmam. Çünkü ben, alemlerin Rabbi olan Allah’tan korkarım.');
INSERT INTO verses (sura, aya, text) VALUES (5, 29, 'Ben, hem benim günahımı hem kendi günahını yüklenerek sonunda cehennemliklerden olmanı isterim, zulmedenlerin cezası işte budur, dedi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 30, 'Nefsi ona kardeşini öldürmeyi güzel gösterdi. Ve onu öldürerek hüsrana uğrayanlardan oldu.');
INSERT INTO verses (sura, aya, text) VALUES (5, 31, 'Allah, kardeşinin cesedini nasıl gömeceğini göstermek için ona yeri eşeleyen bir karga gönderdi. "Yazıklar olsun bana! Şu karga kadar olup da kardeşimin cesedini örtmekten âciz miyim ben?” dedi ve pişman olanlardan oldu.');
INSERT INTO verses (sura, aya, text) VALUES (5, 32, 'İşte bunun için İsrâiloğulları''na şöyle yazdık: Kim, bir nefse (haksız yere) kıyarsa veya yeryüzünde bozgunculuk çıkartmaya karşılık olmaksızın öldürürse, bütün insanları öldürmüş gibi olur. Her kim de birini (öldürmez) yaşatırsa, sanki bütün insanları yaşatmış gibi olur. Rasûllerimiz onlara açık delillerle gelmişti ama bundan sonra onların çoğu yeryüzünde aşırı gittiler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 33, 'Allah ve Rasûlüyle savaşanların ve yeryüzünde bozgunculuğa gayret edenlerin cezası, öldürülmek, asılmak, çaprazlama el ve ayaklarının kesilmesi ya da yerlerinden sürgün edilmektir. Bu, onlara dünyada bir rezilliktir. Onlara ahirette daha büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 34, 'Ancak onları yakalamadan önce tevbe edenler bunun dışındadır. Biliniz ki Allah, çokça bağışlayan ve merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 35, 'Ey İman edenler! Allah’tan sakının/takvalı olun. O’na (yakınlaştıracak ibadetlerle) vesile/yol arayın ve yolunda cihat edin ki, kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (5, 36, 'Doğrusu, yeryüzünde olanların hepsi ve bir misli daha kâfirlerin olsa da kıyamet gününün azabından kurtulmak için fidye verseler kabul edilmez. Onlara acı verici bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 37, 'Ateşten çıkmak isterler, ama ondan çıkabilecek değillerdir. Onlara sürekli, daima bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 38, 'Erkek hırsız ve kadın hırsızın yaptıklarına karşılık, Allah tarafından bir ceza olarak ellerini (bileklerden) kesin. Allah çok güçlüdür, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 39, 'Kim de zulüm işledikten sonra tevbe eder ve halini düzeltirse, Allah tevbesini kabul eder. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 40, 'Bilmez misin ki göklerin ve yerin mülkü Allah''ındır? Allah, dilediğine azap eder, dilediğini ise bağışlar. Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (5, 41, 'Ey Peygamber! Kalpleri inanmamışken, ağızlarıyla “İman ettik” diyerek küfürde yarışanlar, seni üzmesin. Yahudilerden yalana kulak verenler ve sana gelmeyen başka bir topluluk hesabına seni dinleyenler kelimeleri (konuldukları) yerlerinden tahrif ederler. Size şu hüküm verilirse alın, o verilmezse kaçının, derler. Allah’ın fitneye düşmesini dilediği kimse için Allah’a karşı senin elinden bir şey gelmez. İşte onlar, Allah’ın kalplerini arındırmak istemediği kimselerdir. Onlara dünyada rezillik, ahirette de büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 42, 'Onlar (Yahudiler), yalana kulak verenler, haram yiyenlerdir. Eğer sana gelirlerse aralarında hüküm ver veya onlardan yüz çevir. Onlardan yüz çevirirsen, sana hiçbir zarar veremezler. Eğer hüküm verirsen aralarında adaletle hükmet. Allah adil olanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (5, 43, 'İçinde Allah''ın hükmü bulunan Tevrat yanlarında olduğu halde nasıl seni hakem kılıyorlar da sonra, bunun arkasından yüz çevirip gidiyorlar? İşte bunlar Mümin değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 44, 'Doğrusu biz içinde bir hidayet ve bir nur bulunan Tevrat''ı indirdik. Teslim olmuş peygamberler, Yahudilere onunla hükmederlerdi. Rabbani âlimler ve bilginler de Allah''ın kitabını korumakla görevli kılındıklarından ve onun üzerine şahitler olduklarından (onunla hükmederlerdi). Öyleyse insanlardan korkmayın, benden korkun ve ayetlerimi az bir değere karşılık satmayın. Kim Allah''ın indirdiğiyle hükmetmezse, işte onlar kâfirlerdir');
INSERT INTO verses (sura, aya, text) VALUES (5, 45, 'Kitapta onlara cana can, göze göz, buruna burun, kulağa kulak, dişe diş ve yaralara karşılık kısas yazdık. Kim hakkından vazgeçerse bu onun günahlarına kefaret olur. Allah’ın indirdikleriyle hükmetmeyenler, işte onlar zalimlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 46, 'Onların ardından Meryem oğlu İsâ’yı kendinden önce gelen Tevrat’ı doğrulayıcı olarak gönderdik. Ona, içinde hidayet ve nur olan, kendinden önceki Tevrat’ı tasdik eden ve muttakiler için yol gösterici ve bir öğüt olan İncil’i verdik.');
INSERT INTO verses (sura, aya, text) VALUES (5, 47, 'İncil ehli, Allah’ın onda indirdikleri ile hükmetsinler. Allah’ın indirdikleriyle hükmetmeyenler, işte onlar fasıklardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 48, 'Kur’an’ı sana, önce gelen kitapları doğrulayıcı ve onların üzerine şahit olarak hak ile indirdik. Allah’ın indirdikleri ile aralarında hükmet! Sana gelen haktan sonra onların arzularına uyma! Sizin her biriniz için bir şeriat ve yol belirledik. Eğer Allah dileseydi sizi tek bir ümmet yapardı. Fakat size verdikleriyle sizi imtihan etmektedir. Hayırlarda yarışın. Hepinizin dönüşü Allah’adır. Allah, size hakkında ihtilaf ettiğiniz şeyleri açıklayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 49, 'Şu halde, Allah’ın indirdiği (kitap) ile aralarında hükmet, onların arzularına uyma. Allah’ın sana indirdiği Kur’an’ın bir kısmından seni vazgeçirmelerinden sakın. Eğer yüz çevirirlerse bil ki, Allah bir kısım günahları yüzünden onları cezalandırmak istiyor. İnsanların çoğu gerçekten fasıktır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 50, 'Onlar, cahiliye hükmünü mü arzuluyorlar? Yakinen bilen bir topluluk için Allah''tan daha iyi hüküm veren kimdir?');
INSERT INTO verses (sura, aya, text) VALUES (5, 51, 'Ey İman edenler! Yahudi ve Hristiyanları veli/dost edinmeyin. Onlar birbirlerinin velileridir. Sizden kim onları veli edinirse, o da onlardandır. Allah, zalim topluma hidayet vermez.');
INSERT INTO verses (sura, aya, text) VALUES (5, 52, 'Kalplerinde hastalık olanların: "Bize bir felaket gelmesinden korkuyoruz" diyerek onlara koşuştuklarını görürsün. Umulur ki Allah, bir fetih verir veya katından bir emir getirir de içlerinde gizlediklerine pişman olurlar.');
INSERT INTO verses (sura, aya, text) VALUES (5, 53, 'Müminler: "Sizinle beraber olduklarına var güçleriyle Allah’a yemin edenler bunlar mıdır?" derler. Onların amelleri boşa gitmiş ve hüsrana uğrayanlardan olmuşlardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 54, 'Ey iman edenler! Sizden kim dininden dönerse (bilsin ki ), Allah (onların yerine) sevdiği bir toplum getirir. Onlar da Allah’ı severler. Müminlere karşı alçak gönüllü, kâfirlere karşı güçlü, Allah yolunda cihat eder ve kınayıcıların kınamasından korkmazlar. İşte bu, Allah’ın lütfudur. Onu dilediğine verir. Allah (lütfu) geniştir, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 55, 'Sizin veliniz/yardımcınız ancak Allah’tır, Rasûlüdür ve Allah’ın emirlerine boyun eğerek namazı kılan, zekâtı veren Müminlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 56, 'Kim Allah’ı, peygamberini ve iman edenleri veli edinirse (bilsin ki), elbette Allah’ın taraftarları galip gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 57, 'Ey iman edenler! Kendilerine sizden önce kitap verilenlerden dininizi alay ve eğlenceye alanları ve kâfirleri veli edinmeyin. Mümin iseniz ancak Allah''tan sakının/takvalı olun.');
INSERT INTO verses (sura, aya, text) VALUES (5, 58, 'Namaza çağırdığınızda, onu alaya ve eğlenceye alırlar. Bu, onların akletmeyen bir toplum olmasındandır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 59, 'De ki: Ey Ehl-i Kitap! Yalnızca Allah''a, bize indirilene ve daha önce indirilene iman ettiğimiz için mi bizi yadırgıyorsunuz? Oysa çoğunuz yoldan çıkmış kimselersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (5, 60, 'De ki: “Allah katında cezası bundan daha kötü olanı size haber vereyim mi? Allah''ın lânet ettiği, gazapta bulunduğu, kendilerinden maymunlar ve domuzlar kıldığı ve tağuta kulluk eden kimse. İşte onlar yeri en kötü ve de doğru yoldan en çok sapmış olanlardır.”');
INSERT INTO verses (sura, aya, text) VALUES (5, 61, 'Size geldiklerinde: "İman ettik" derler. Oysa yanınıza kâfir olarak girmiş ve yine kâfir olarak çıkmışlardır. Gizlemekte olduklarını Allah çok iyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 62, 'Onların çoğunu günah işlemede, düşmanlık etmede ve haram yemede yarışırken görürsün, yaptıkları ne kötüdür!');
INSERT INTO verses (sura, aya, text) VALUES (5, 63, 'Rabbânî âlimler ve hahamların onlara günah söz söylemeyi ve haram yemeyi yasak etmeleri gerekmez miydi? Yapmakta oldukları ne kötüdür.');
INSERT INTO verses (sura, aya, text) VALUES (5, 64, 'Yahudiler: "Allah’ın eli bağlıdır/sıkıdır" dediler. Söylediklerinden ötürü elleri bağlandı ve onlara lanet edildi! Oysa Allah’ın her iki eli de açıktır, nasıl dilerse verir. Elbette Rabbinden sana indirilenler, onların çoğunun azgınlığını ve küfrünü arttıracaktır. Onların arasına kıyamete kadar (sürecek) düşmanlık ve kin saldık. Savaş ateşini ne zaman körükleseler Allah onu söndürür. Yeryüzünde bozgunculuğa koşarlar. Allah bozguncuları sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (5, 65, 'Eğer Ehl-i Kitap, iman edip Allah’tan sakınsaydı/ takvalı olsaydı, onların kötülüklerini örter ve onları Naîm Cennetleri''ne sokardık.');
INSERT INTO verses (sura, aya, text) VALUES (5, 66, 'Eğer onlar, Tevrat’ı, İncil’i ve Rablerinden kendilerine indirilen Kur’an’ı gereğince uygulasalardı üstlerinden ve ayakları altından (rızıklarını) yerlerdi. İçlerinden orta yolu tutan bir ümmet varsa da bir çoğunun yapmakta oldukları pek kötüdür.');
INSERT INTO verses (sura, aya, text) VALUES (5, 67, 'Ey Rasûl! Rabbinden sana indirileni tebliğ et! Eğer bunu yapmazsan, Allah''ın dinini tebliğ etmemiş olursun. Allah seni insanlardan korur. Allah, kâfir topluma hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (5, 68, 'De ki: Ey Ehl-i Kitap, Tevrat’ı, İncil’i ve Rabbinizden size indirileni gereğince uygulamadıkça hiçbir şey/din üzerine olamazsınız. Andolsun ki Rabbinden sana indirilen (Kur’an) onlardan çoğunun azgınlık ve küfrünü arttırır. O halde kâfirler toplumu için üzülme!');
INSERT INTO verses (sura, aya, text) VALUES (5, 69, 'Şüphesiz iman edenler, Yahudiler, Hristiyanlar ve Sabiilerden kim Allah’a ve ahiret gününe iman eder ve salih amel işlerse, onlara Rableri katında mükâfatlar vardır. Onlara bir korku yoktur, üzülmeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 70, 'İsrailoğulları''ndan sağlam söz almış ve onlara rasûller göndermiştik. Onlara, nefislerinin hoşlanmadığı bir şeyle bir elçi geldiğinde onların bir kısmını yalanlar ve bir kısmını da öldürürlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 71, 'Bir fitnenin/azabın olmayacağını sandılar körleştiler, sağırlaştılar. Sonra Allah onların tevbesini kabul etti. Ardından yine onların çoğu körleşip, sağır oldular. Allah, yaptıklarını çok iyi görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 72, 'Şüphesiz, “Allah, Meryem oğlu Mesih’in kendisidir” diyenler kâfir olmuştur. Mesih şöyle demiştir: "Ey İsrailoğulları! Benim Rabbim ve sizin Rabbiniz olan Allah’a ibadet edin. Kim Allah’a şirk koşarsa, Allah ona Cennet''i haram kılar, onun yeri Cehennem olur. Zalimler için hiçbir yardımcı yoktur."');
INSERT INTO verses (sura, aya, text) VALUES (5, 73, 'Şüphesiz, Allah, üçün üçüncüsüdür, diyenler kâfir olmuştur. Halbuki (ibadete layık) tek (hak) olan ilahtan başka bir (hak) ilah yoktur. Söylediklerinden vazgeçmezlerse elbette küfredenlere acıklı bir azap dokunacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 74, 'Hâlâ Allah''a tevbe edip O''ndan af dilemiyorlar mı? Allah çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 75, 'Meryem oğlu Mesih, ancak bir rasûldür. Ondan önce de rasûller geçmiştir. Onun annesi de dosdoğru/çok sadık idi. İkisi de yemek yerdi. Onlara ayetleri nasıl açıkladığımıza bir bak, sonra da onların (haktan) nasıl çevrildiklerine bak!');
INSERT INTO verses (sura, aya, text) VALUES (5, 76, '(Ey Muhammed!) De ki: Siz Allah ile birlikte size zarar da fayda da sağlamayan (ilahlara mı) ibadet ediyorsunuz? Oysa Allah, her şeyi hakkıyla işitendir, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 77, 'De ki: Ey Ehl-i Kitap! Dininizde haksız olarak aşırı gitmeyin. Kendileri önceden sapmış, çoklarını da saptırmış ve doğru yoldan ayrılmış olan bir topluluğun arzularına uymayın.');
INSERT INTO verses (sura, aya, text) VALUES (5, 78, 'İsrailoğulları''ndan kâfir olanlar, Dâvûd’un ve Meryem oğlu İsâ’nın dili ile lanetlenmiştir. Bu lanet, isyan etmeleri ve haddi aşmalarından dolayı idi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 79, 'Onlar işledikleri herhangi bir kötülükten birbirlerini vazgeçirmeye çalışmazlardı. Onların yapmakta oldukları gerçekten ne kötü bir şeydi!');
INSERT INTO verses (sura, aya, text) VALUES (5, 80, 'Onlardan bir çok kimsenin, kâfirleri veli edindiklerini görürsün. Nefislerinin yaptığı (ameller) ne kötüdür. Allah, onlara gazap etmiştir ve onlar azapta ebedîdirler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 81, 'Eğer Allah’a, peygambere ve ona indirilene (Kur’an’a) iman ediyor olsalardı, onları (müşrikleri) dost edinmezlerdi. Fakat onlardan birçoğu fasık kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 82, '(Ey Muhammed!) İman edenlere düşmanlık etmede, insanların en şiddetlisinin kesinlikle Yahudiler ile Allah’a ortak koşanlar olduğunu görürsün. Yine onların iman edenlere sevgi bakımından en yakınının da “Biz Hristiyanlarız!” diyenler olduğunu mutlaka görürsün. Çünkü onların içinde keşişler ve rahipler vardır. Onlar büyüklük de taslamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (5, 83, 'Peygamber’e indirileni (Kur’an’ı) dinledikleri zaman hakkı tanımalarından dolayı gözlerinin yaşla dolup taştığını görürsün. “Ey Rabbimiz! İman ettik. Artık bizi (hakikate) şahitlik edenler (Muhammed’in ümmeti) ile beraber yaz!” derler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 84, 'Rabbimizin bizi salih kimselerle birlikte (Cennet''e) sokmasını umarken ne diye Allah’a ve bize gelen hakka iman etmeyelim ki?');
INSERT INTO verses (sura, aya, text) VALUES (5, 85, 'Bu sözlerine karşılık olarak Allah, onlara içinde ırmaklar akan, orada ebedî kalacakları Cennetler vermiştir. İşte bu ihsan sahiplerinin mükâfatıdır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 86, 'Kâfir olup da ayetlerimizi yalanlayanlara gelince, işte onlar Cehennem ehlidirler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 87, 'Ey iman edenler! Allah’ın size helâl kıldığı temiz şeyleri haram kılmayın ve haddi aşmayın. Çünkü Allah, haddi aşanları sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (5, 88, 'Allah’ın size verdiği helâl ve temiz rızıktan yiyin ve kendisine iman ettiğiniz Allah’a karşı gelmekten sakının.');
INSERT INTO verses (sura, aya, text) VALUES (5, 89, 'Allah, boş bulunarak ettiğiniz yeminlerlen sizi sorumlu tutmaz. Bilip, kasıtlı olarak yaptığınız yeminlerden dolayı sorumlu tutar. Bu durumda yeminin keffareti, ailenize yedirdiğinizin orta hâllisinden on yoksulu doyurmak yahut onları giydirmek ya da bir köle azat etmektir. Kim (bu imkânı) bulamazsa, onun keffareti üç gün oruç tutmaktır. İşte yemin ettiğiniz vakit yeminlerinizin keffareti budur. Yeminlerinizi tutun. Şükredesiniz diye Allah, ayetlerini işte böyle açıklıyor.');
INSERT INTO verses (sura, aya, text) VALUES (5, 90, 'Ey iman edenler! Şarap (içki), kumar, putlar ve fal okları, Şeytan''ın pis işlerindendir. Artık bunlardan kaçının ki, kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (5, 91, 'Şeytan, içki ve kumarla, ancak aranıza düşmanlık ve kin sokmak; sizi Allah’ı anmaktan ve namazdan alıkoymak ister. Artık vazgeçiyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (5, 92, 'Allah’a itaat edin, Rasûle de itaat edin ve (emirlerine aykırı hareket etmekten) sakının. Şayet yüz çevirirseniz bilmiş olun ki, elçimize düşen sadece apaçık tebliğdir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 93, 'İman edip salih amel işleyenler; sakınıp/takvalı olup, iman eder ve salih ameller işlerseler (haram olmadan) önce tatmış olduklarından ötürü onlara bir günah yoktur. Sonra iman etmeye, takvalı olup iyiliklerde bulunmaya devam ederlerse, işte Allah böyle iyilik yapanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (5, 94, 'Ey iman edenler! Andolsun Allah sizleri, ellerinizin ve mızraklarınızın erişebileceği av(lar) ile elbette imtihan edecek ki, görmediği halde kendisinden korkanı ayırıp meydana çıkarsın. Bu (uyarıdan) sonra kim sınırı aşarsa, onun için elem dolu bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 95, 'Ey iman edenler! İhramlı iken av hayvanını öldürmeyin. Sizden kim bilerek onu öldürürse; cezası, içinizden adalet sahibi iki kimsenin hükmüyle, Kâbe''ye ulaştırılacak kurban olarak (koyun, keçi, inek ve deve gibi) (avladığının) benzeri bir hayvandır. Ya da yoksulları doyurma keffaretidir veya buna denk gelecek kadar oruç tutmasıdır. Böylelikle, işlediğinin vebalini tatmış olur. Allah, geçmişte olanı affetmiştir. Fakat kim bir daha böyle yaparsa, Allah ondan intikam alır. Allah mutlak galiptir, intikam sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 96, 'Deniz avı ve onu yemek size de yolculara da geçimlik olarak helal kılınmıştır. İhramlı bulunduğunuz sürece kara avı size haram kılınmıştır. Huzurunda toplanacağınız Allah’a karşı gelmekten sakının.');
INSERT INTO verses (sura, aya, text) VALUES (5, 97, 'Allah Kâ’be’yi, Beyt-i Haram’ı, Haram ayları, kurbanı ve boyunları gerdanlıklı kurbanlıkları da insanlar için bir kıyâm/ ayakta kalma (ve canlanma) sebebi kıldı. Bunlar, Allah’ın göklerde ve yerde olan her şeyi bildiğini ve Allah’ın her şeyi en iyi bilen olduğunu sizin de bilmeniz içindir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 98, 'Bilin ki, Allah’ın cezası çetindir ve Allah çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 99, 'Rasûlün görevi ancak tebliğdir. Açıkladığınızı da gizlediğinizi de Allah bilir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 100, 'De ki: “Pis ile temiz bir olmaz. Pisin çokluğu hoşuna gitse bile.” Ey akıl sahipleri! Allah’a karşı gelmekten sakının ki kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (5, 101, 'Ey iman edenler! Size açıklandığı takdirde sizi üzecek olan şeylere dair soru sormayın. Eğer Kur’an indirilirken bunlara dair soru sorarsanız size açıklanır. (Hâlbuki) Allah onları bağışlamıştır. Allah, çok bağışlayandır, Halîm''dir. (Hemen cezalandırmaz, mühlet verir.)');
INSERT INTO verses (sura, aya, text) VALUES (5, 102, 'Sizden önceki bir millet o tür şeyleri sordu da sonra o yüzden kâfir oldu.');
INSERT INTO verses (sura, aya, text) VALUES (5, 103, 'Allah, ne “Bahîre”, ne “Sâibe”, ne “Vasîle”, ne de “Hâm” diye bir şey meşru kılmıştır. Fakat, o kâfirler Allah’a karşı yalan uyduruyorlar. Zaten çoklarının aklı da ermez.');
INSERT INTO verses (sura, aya, text) VALUES (5, 104, '(Onlara, “Allah''ın indirdiği kitaba uyunuz!” dendiği zaman, “Hayır, biz atalarımızın yoluna uyarız” derler. Ya ataları akıl erdiremeyen ve doğru yol üzerinde bulunmuyor iselerde mi?');
INSERT INTO verses (sura, aya, text) VALUES (5, 105, 'Ey iman edenler! Siz kendinizden sorumlusunuz. Siz hidayette olursanız, doğru yoldan sapan kimse size zarar veremez. Hepinizin dönüşü Allah’adır. Yapmakta olduklarınızı o size haber verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (5, 106, 'Ey iman edenler! Birinizin ölümü yaklaştığı zaman, vasiyet sırasında aranızda şahitlik (edecek olanlar) sizden adaletli iki kişidir. Yahut seferde olup da başınıza ölüm musibeti gelirse, sizin dışınızdan başka iki kişi şahitlik eder. Eğer şüphe ederseniz, onları namazdan sonra alıkorsunuz da Allah adına, “Akraba da olsa, şahitliğimizi hiçbir karşılığa değişmeyiz. Allah için yaptığımız şahitliği gizlemeyiz. Gizlediğimiz takdirde, şüphesiz günahkârlardan oluruz.” diye yemin ederler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 107, '(Eğer sonradan) o ikisinin (yalan söyleyerek) günaha düştükleri belli olursa, ölenin yakınlarından diğer iki kişi onların yerine geçerler ve; “Bizim şahitliğimiz, bu ikisinin (yalancı) şahitliğinden (kabul olma hususunda) daha geçerlidir. Biz (kimsenin hakkına) tecavüz etmedik, aksi takdirde biz, elbette zalimlerden oluruz" diye Allah''a yemin ederler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 108, 'Bu, (hüküm), şahitliği gerektiği şekilde yapmaya, yahut yeminlerinden sonra, yeminlerin (mirasçılar tarafından) reddedilmesinden korkmalarına (çekinmelerine çare olarak) daha uygundur. Allah’a karşı gelmekten sakının ve dinleyin. Allah, fasık toplumu doğruya iletmez.');
INSERT INTO verses (sura, aya, text) VALUES (5, 109, 'Allah peygamberleri toplayacağı gün: “Size ne cevap verildi?” buyuracak, onlar da: “Bizim hiçbir bilgimiz yok. Şüphesiz gaybları çok iyi bilen ancak sensin.” diyecekler.');
INSERT INTO verses (sura, aya, text) VALUES (5, 110, 'Allah o zaman şöyle diyecek: “Ey Meryem oğlu İsâ, senin üzerindeki ve annenin üzerindeki nimetimi hatırla. Hani ben, seni Rûhu’l-Kudüs (Cebrâil) ile desteklemiştim. Beşikteyken de, yetişkin iken de insanlarla konuşuyordun. Hani sana kitabı (yazıyı), hikmeti, Tevrat’ı ve İncil’i de öğretmiştim. Hani benim iznimle çamurdan bir kuş suretine benzer bir şeyi yapıyordun; ona üfürüyordun da iznimle (canlı) bir kuş oluveriyordu. Anadan doğma körü, abrası (alaca hastalığına yakalanmışı) da yine benim iznimle iyi ediyordun. Yine benim iznimle ölüleri (kabirlerinden diri olarak) çıkartıyordun. Ve hani İsrailoğulları''nı kendilerine apaçık mucizelerle geldiğin zamanda senden (zarar vermelerini engelleyerek) çekmiştim de içlerinden kâfir olanları; “Bu apaçık bir sihirden başka bir şey değildir” demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 111, 'Hani Havârilere: “Bana ve rasûlüme iman edin!” diye vahiy etmiştim de: “İman ettik. Gerçekten Müslümanlar olduğumuza sen de şahit ol!” demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 112, 'Hani Havâriler: “Ey Meryem oğlu İsâ! Rabbin gökten bize bir sofra indirebilir mi?” demişlerdi. O: “Eğer iman edenlerdenseniz, Allah’tan korkun!” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (5, 113, 'Havariler ise: "Ondan yemek istiyoruz, (böylece) kalplerimiz mutmain olsun ve bize doğruyu söylediğini bilelim ve buna şahitlerden olalım." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 114, 'Meryem oğlu İsâ: "Allah’ım! Rabbimiz, gökten bize bir sofra indir. Bu, hem bizim için, hem de öncemiz ve sonramız için bir bayram ve senden bir mucize olsun. Bizi rızıklandır. Sen, rızık verenlerin en hayırlısısın." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 115, 'Allah buyurdu ki: “Gerçekten ben onu size indireceğim. Ama bundan sonra sizden kim kâfir olursa, ben onu âlemlerden kimseyi azaplandırmayacağım bir azapla azablandıracağım.”');
INSERT INTO verses (sura, aya, text) VALUES (5, 116, 'Allah, “Ey Meryem oğlu İsa! İnsanlara, “Beni ve annemi Allah''ı bırakarak iki ilah edinin, diye sen mi söyledin?” dediğinde, “Münezzehsin sen, hakkım olmayan bir sözü söylemek bana yakışmaz. Eğer bunu söylediysem, mutlaka sen onu bilirsin. Sen bende olanı bilirsin, ama ben sende olanı bilmem. Gerçekten gaipleri bilen sadece sensin” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (5, 117, '“Ben onlara, sadece bana emrettiğin şeyi söyledim. Benim de Rabbim, sizin de Rabbiniz olan Allah’a ibadet edin (dedim.) Aralarında bulunduğum sürece onlara şahit oldum. Ama beni içlerinden aldığında, artık üzerilerine gözetleyici yalnız sen oldun. Sen, her şeye hakkıyla şahitsin.”');
INSERT INTO verses (sura, aya, text) VALUES (5, 118, 'Eğer onlara azap edersen, onlar şüphesiz senin kullarındır. Şayet onları bağışlarsan, şüphesiz sen Aziz ve Hakim olansın.');
INSERT INTO verses (sura, aya, text) VALUES (5, 119, 'Allah, şöyle diyecek: “Bugün, doğrulara, doğruluklarının yarar sağlayacağı gündür.” Onlara içinden ırmaklar akan, içinde ebedî kalacakları cennetler vardır. Allah, onlardan razı olmuş, onlar da Allah’tan razı olmuşlardır. İşte bu büyük başarıdır.');
INSERT INTO verses (sura, aya, text) VALUES (5, 120, 'Göklerin, yerin ve içindekilerin mülkü Allah’a aittir. O her şeye kadirdir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 1, 'Hamt, gökleri ve yeri yaratan, karanlıkları ve aydınlığı var eden Allah’a mahsustur. Böyle iken kâfirler Rablerine (ibadet etmede başkalarını) denk tutuyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 2, 'O, sizi çamurdan yaratan, sonra da bir ecel tayin edendir. Bir de O''nun katında belirli bir ecel (kıyamet günü) vardır. Siz ise hâlâ şüphe ediyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 3, 'O , göklerde ve yerde tek Allah’tır. Gizlinizi de açığınızı da bilir, neyi yapıp ettiğinizi de bilir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 4, 'Onlara Rabblerinin âyetlerinden bir âyet gelse mutlaka ondan yüz çevirirler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 5, 'İşte onlar, hak kendilerine geldiğinde onu yalanladılar. Fakat kendisiyle alay etmekte oldukları şeyin haberleri yakında onlara gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 6, 'Bizim, kendilerinden önce nice nesilleri yok ettiğimizi görmediler mi? Onları, sizi yerleştirmediğimiz bir şekilde yeryüzünde yerleştirmiş (imkân ve iktidar vermiş), gökten üzerlerine bol bol yağmur indirmiş, altlarından ırmaklar akıtmıştık. Böyle iken günahları yüzünden onları helâk ettik ve arkalarından başka bir nesil yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (6, 7, 'Eğer Biz sana kağıt üzerinde yazılı bir kitap indirseydik, onlar da o kitaba elleriyle dokunsalardı yine de kâfir olanlar: “Bu yalnızca bir sihirdir.” derlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 8, '"Ona ne diye bir melek indirilmedi?” dediler. Eğer biz bir melek indirseydik (iman etmemeleri halinde) herhalde iş bitirilmiş olurdu. Ve sonra kendilerine (azıcık) bir süre (bile) verilmezdi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 9, 'Eğer (Rasûlü) melek kılsaydık, yine bu (meleği) bir adam şeklinde kılar ve onları yine içinde bulundukları şüpheye düşürmüş olurduk.');
INSERT INTO verses (sura, aya, text) VALUES (6, 10, 'Andolsun, senden önce de birçok peygamberle alay edildi de içlerinden alay edenleri, o alaya aldıkları şey kuşatıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 11, 'De ki: “Yeryüzünde gezip dolaşın; sonra da yalanlayanların sonu nice oldu, bir bakıverin.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 12, 'Yine de ki: “Göklerde ve yerde olanlar kimindir?” De ki: “Allah’ındır. O, rahmet etmeyi kendi üzerine yazmıştır. Hakkında hiçbir şüphe bulunmayan kıyamet günü sizi elbette bir araya toplayacaktır. Kendilerini hüsrana sokanlar, işte onlar iman etmezler."');
INSERT INTO verses (sura, aya, text) VALUES (6, 13, 'Gecenin ve gündüzün içinde barınan her şey Onundur. O, her şeyi işitendir, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 14, 'De ki: "Gökleri ve yeri yoktan yaratan, doyuran fakat doyurulmayan Allah’tan başkasını mı dost edineceğim." De ki: “Ben İslâm’a girenlerin ilki olmakla emrolundum ve (bana:) sakın müşriklerden olma! (denildi).”');
INSERT INTO verses (sura, aya, text) VALUES (6, 15, 'De ki: Eğer Rabbime isyan edersem, elbette ben büyük bir günün azabından korkarım!');
INSERT INTO verses (sura, aya, text) VALUES (6, 16, 'O gün kim azaptan kurtarılırsa, gerçekten Allah ona rahmet etmiştir. İşte apaçık kurtuluş budur.');
INSERT INTO verses (sura, aya, text) VALUES (6, 17, 'Allah sana bir zarar dokundursa, onu yine kendisinden başka giderecek yoktur ve eğer sana bir hayır dokundursa, kuşkusuz O, her şeye kadirdir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 18, 'O, kullarının üstünde kâhir/yegane tasarruf sahibidir O, hüküm ve hikmet sahibidir, (her şeyden) hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 19, 'De ki: “Şahitlik bakımından hangi şey daha büyüktür?” De ki: “Allah benimle sizin aranızda şahittir. İşte bu Kur’an bana, onunla sizi ve eriştiği herkesi uyarayım diye vahyolundu. Gerçekten siz mi Allah ile beraber başka ilâhlar olduğuna şahitlik ediyorsunuz?” De ki: “Ben şahitlik etmem.” De ki: “(İbadete layık) tek (hak) ilahtır ve şüphesiz ben sizin Allah’a ortak koştuğunuz şeylerden uzağım.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 20, 'Kendilerine kitap verdiğimiz kimseler onu kendi öz oğullarını tanıdıkları gibi tanırlar. Kendilerini hüsrana uğratanlar ise iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 21, 'Allah’a karşı yalan uydurandan ya da O’nun ayetlerini yalanlayandan daha zalim kim olabilir? Şüphesiz ki, zalimler kurtuluşa eremez.');
INSERT INTO verses (sura, aya, text) VALUES (6, 22, 'O gün onların hepsini toplayacağız; sonra da Allah’a şirk koşanlara diyeceğiz ki: “İddia etmiş olduğunuz ortaklarınız nerede?"');
INSERT INTO verses (sura, aya, text) VALUES (6, 23, 'Sonra onların (bu imtihana) mazeretleri: "Rabbimiz Allah''a yemin olsun ki, biz ortak koşanlar olmadık!" demekten başka bir şey olmayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 24, 'Kendilerine karşı nasıl yalan söylediklerine bir bak ve uydurdukları (ilahları) onları nasıl yüzüstü bırakıp kayboluverdi?');
INSERT INTO verses (sura, aya, text) VALUES (6, 25, 'İçlerinden sana kulak verenler vardır. Halbuki Biz, onu anlayamasınlar diye kalblerine perdeler, kulaklarına ağırlık koyduk. Her türlü ayeti/mucizeyi görseler de ona yine iman etmezler. Hatta sana gelseler seninle mücadele ederler. O kâfirler: “Bu (Kur’ân), eskilerin masallarından başka bir şey değildir.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 26, 'Onlar, hem (halkı) ona uymaktan alıkoyar, hem kendileri de ondan uzaklaşırlar. Sonuçta kendilerini helak ederler de farkında olmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 27, 'Ateşin karşısında durdurulup da, “Ah! Keşke dünyaya geri döndürülsek de Rabbimizin ayetlerini yalanlamasak ve Müminlerden olsak.” dedikleri vakit (hâllerini) bir görsen!');
INSERT INTO verses (sura, aya, text) VALUES (6, 28, 'Hayır! Daha önce gizlemekte oldukları şeyler kendilerine göründü. Eğer (dünyaya) geri gönderilseler yine kendilerine yasak edilen şeylere döneceklerdir. Zira onlar gerçekten yalancıdırlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 29, 'Onlar: “Bu (hayat), ancak dünya hayatımızdır. Biz diriltilecek de değiliz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 30, 'Rablerinin huzurunda durduruldukları zaman, sen onları bir görsen: O vakit Allah onlara, bu yeniden dirilme olayı gerçek değil miymiş? diyecek, onlar da “Rabbimize andolsun ki, evet” diyeceklerdir (Allah): “Öyleyse inkâr etmekte olduğunuzdan dolayı tadın azabı!” diyecek.');
INSERT INTO verses (sura, aya, text) VALUES (6, 31, 'Allah ile karşılaşmayı yalanlayanlar hüsrana uğramışlardır. Kıyamet ansızın onların başına geldiği zaman; “Dünyada işlediğimiz kusurlardan dolayı yazıklar olsun bize!” derler. Sırtlarında da günahlarını taşırlar. Dikkat edin! O yüklenip taşıdıkları ne kötüdür.');
INSERT INTO verses (sura, aya, text) VALUES (6, 32, 'Dünya hayatı bir oyun ve eğlenceden başka bir şey değildir. Ahiret yurdu, takva sahipleri için elbette daha hayırlıdır. Hâlâ akıl etmez misiniz?');
INSERT INTO verses (sura, aya, text) VALUES (6, 33, 'Onların söylediklerinin seni üzdüğünü elbette biliyoruz. Fakat onlar seni yalanlamıyorlar. O zalimler, bile bile Allah’ın ayetlerini inkâr ediyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 34, 'Andolsun ki, senden önce de birçok peygamberler yalanlanmıştı da, onlar yalanlanmalarına ve eziyet edilmelerine karşı sabretmişler ve nihayet kendilerine yardımımız yetişmişti. Allah’ın kelimelerini (kanunlarını) değiştirebilecek yoktur. Andolsun ki (önceki) peygamberlerin haberlerinden bir kısmı sana gelmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 35, 'Eğer onların yüz çevirmeleri sana ağır geldiyse, bir tünel açıp yerin dibine inerek yahut göğe de bir merdiven dayayıp onlara bir ayet getirmeye gücün yeterse (hiç durma yap)! Eğer Allah dileseydi, elbette onları hidayet üzere toplardı. O halde sakın cahillerden olma!');
INSERT INTO verses (sura, aya, text) VALUES (6, 36, '(Davete), ancak (bütün kalpleriyle) kulak verenler uyar. Ölüleri ise Allah diriltecektir. Sonra yalnız O’na döndürüleceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 37, '“Rabbinden ona bir âyet (mûcize) indirilseydi ya!” dediler. De ki: Allah, bir mucize indirmeye elbette kadirdir. Fakat onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 38, 'Yeryüzünde gezen her türlü canlı ve (gökte) iki kanadıyla uçan bütün kuşlar, ancak sizin gibi birer ümmettirler. Biz o Kitap''ta (Levh-i Mahfuz''da) hiçbir şeyi eksik bırakmadık; sonra (bütün bunlar) Rablerinin huzuruna getirileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 39, 'Ayetlerimizi yalanlayanlar, karanlıklar içinde kalmış sağır ve dilsizlerdir. Allah dilediğini saptırır, dilediğini de dosdoğru yol üzerinde tutar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 40, 'De ki: “Söyleyin bakalım. Acaba size Allah’ın azabı gelse veya size kıyamet saati gelip çatsa, siz Allah’tan başkasını mı yalvarırsınız? Eğer (putların size yararı dokunduğu iddianızda) doğru söyleyenlerseniz (haydi onları yardıma çağırın).');
INSERT INTO verses (sura, aya, text) VALUES (6, 41, 'Hayır, yalnız O’na yalvarırsınız. O da dilerse (kaldırılması için) yalvardığınız şeyi giderir; siz de şirk koştuğunuz şeyleri unutursunuz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 42, 'Andolsun, senden önce de ümmetlere peygamberler gönderdik ve belki yalvarırlar diye kendilerini darlık ve sıkıntıya soktuk.');
INSERT INTO verses (sura, aya, text) VALUES (6, 43, 'Hiç olmazsa azabımız kendilerine gelince boyun eğip yalvarmaları gerekmez miydi? Fakat, kalpleri katılaşmış ve Şeytan, yaptıklarını kendilerine güzel göstermişti.');
INSERT INTO verses (sura, aya, text) VALUES (6, 44, 'Verilen öğütleri unuttukları bir sırada, her şeyin kapılarını onlara açtık. Kendilerine verilenler ile şımarıp azdıkları zaman, onları ansızın bütün ümitlerini yitirmiş bir halde yakaladık.');
INSERT INTO verses (sura, aya, text) VALUES (6, 45, 'Böylece o zalim toplumun kökü kesildi. Hamt, âlemlerin Rabbi Allah''a mahsustur.');
INSERT INTO verses (sura, aya, text) VALUES (6, 46, 'De ki: Söyleyin bana! Allah, kulaklarınızı ve gözlerinizi alsa, kalplerinizi de mühürlese, Allah’tan başka onu size geri getirecek ilâh kimdir? Ayetleri nasıl açıkladığımıza bir bak, sonra da onlar nasıl yüz çeviriyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 47, 'De ki: “Bana haber verin. Eğer Allah’ın azabı size ansızın yahut açıktan açığa gelip çatsa, zalimler topluluğundan başkası helâk olur mu?”');
INSERT INTO verses (sura, aya, text) VALUES (6, 48, 'Biz, peygamberleri yalnız müjdeciler ve uyarıcılar olarak göndeririz. Kim iman edip, salih amel işlerse o kimselere bir korku yoktur ve onlar üzülmeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 49, 'Ayetlerimizi yalanlayanlara gelince; onlara, yapmış oldukları fısk sebebiyle azap dokunacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 50, 'De ki: “Ben size yanımda Allah’ın hazineleri vardır, demiyorum. Ben gaybı da bilmem. Size, şüphesiz ben bir meleğim de demiyorum. Ben, ancak bana vahyolunan (Kur’an) a uyarım.” De ki: “Hiç görmeyenle gören bir olur mu? Hiç düşünmüyor musunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (6, 51, 'Rablerinin huzurunda toplanacaklarından korkanları (Kur''an) ile uyar ki onların, Rablerinden başka ne bir veli, ne de bir şefaatçisi vardır. Umulur ki sakınırlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 52, 'Rablerinin rızasını isteyerek sabah akşam O’na dua edenleri yanından uzaklaştırma. Onların hesabından senin üzerinde bir şey (yükümlülük), senin hesabından da onların üzerine bir şey (yükümlülük) yoktur ki onları kovarsan o takdirde zâlimlerden olursun.');
INSERT INTO verses (sura, aya, text) VALUES (6, 53, 'Böylece, “Allah, aramızdan bunlara mı (hidayet vererek) ihsanda bulundu?” desinler diye onları birbiriyle sınadık. Allah, şükredenleri en iyi bilen değil midir?');
INSERT INTO verses (sura, aya, text) VALUES (6, 54, 'Ayetlerimize iman edenler yanına geldikleri zaman de ki: "Selam size! Rabbiniz, rahmet etmeyi kendi üzerine yazmıştır. İçinizden kim cahillikle bir kötülük işler de ardından tevbe edip salih ameller işlerse, şüphesiz Allah çokça bağışlayandır, çokça merhamet edendir."');
INSERT INTO verses (sura, aya, text) VALUES (6, 55, 'Günahkârların yolu iyice belli olsun diye âyetleri işte böyle apaçık bir şekilde açıklıyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 56, 'De ki: “Sizin, Allah’tan başka ibadet ettiğiniz şeylere ibadet etmem bana kesinlikle yasaklandı. Ben sizin arzularınıza uymam. (Uyarsam) o takdirde sapmış olurum, hidayete erenlerden olmam.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 57, 'De ki: “Şüphesiz ben Rabbimden gelmiş apaçık bir delil üzerindeyim. Siz ise onu yalanladınız. Sizin acele gelmesini istediğiniz şey (azap), benim yanımda değildir. Hüküm yalnız Allah’a aittir. O, hakkı haber verir. O, (hakkı batıldan) ayırt edenlerin en hayırlısıdır.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 58, 'De ki: Sizin çabukça gelmesini istediğiniz şey benim yanımda olsaydı, benimle sizin aranızda iş elbette bitirilmiş olurdu. Allah, zalimleri en iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 59, 'Gaybın anahtarları O’nun yanındadır. Onları, kendisinden başkası bilmez. Karada ve denizde olan her şeyi bilir. Onun ilmi olmadan hiçbir yaprak düşmez ve yerin karanlıklarında hiçbir tane, hiçbir yaş ve hiçbir kuru yoktur ki apaçık bir kitapta bulunmasın.');
INSERT INTO verses (sura, aya, text) VALUES (6, 60, 'O, geceleyin sizi öldüren (ölümü andıran bir halde uyutan), gündüz de ne işlediğinizi bilendir. Sonra belirlenmiş ecel tamamlansın diye gündüzün sizi dirilten (uyandıran) O''dur. Sonra dönüşünüz yine O''nadır. Sonunda O, yaptıklarınızı size haber verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 61, 'O, kullarının üstünde yegâne hâkimiyet sahibidir. Üzerinize de koruyucu melekler gönderir. Nihayet birinize ölüm geldiği vakit (görevli) elçilerimiz onun canını alır ve onlar görevlerinde asla kusur etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 62, 'Sonra gerçek mevlâları olan Allah’a döndürülürler. Dikkat edin, hüküm O’na aittir. O, hesap görenlerin en hızlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 63, 'De ki: Karanın ve denizin karanlıklarından (tehlikelerinden) sizi kim kurtarır ki? (O zaman) O''na gizli gizli yalvararak eğer bizi bundan kurtarırsan andolsun şükredenlerden olacağız diye dua ederdiniz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 64, 'De ki: Sizi ondan ve bütün sıkıntılardan kurtaracak olan Allah’tır. Böyle olduğu halde siz yine de şirk koşuyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 65, 'De ki: "Üzerinizden veya ayaklarınızın altından bir azap göndermeye ya da sizi gruplara ayırarak kiminizin şiddetini kiminize (savaş ve fitne ile) tattırmaya kadîr olan O’dur. (ibret alıp) anlasınlar diye ayetlerimizi nasıl açıkladığımıza bir bak!"');
INSERT INTO verses (sura, aya, text) VALUES (6, 66, 'O (Kur’an) hak olduğu hâlde, kavmin onu yalanladı. De ki: “Ben size vekil (kefil) değilim.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 67, 'Her haberin gerçekleşeceği bir zaman vardır. İleride anlayacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (6, 68, 'Ayetlerimiz hakkında ileri geri konuşmaya dalanları gördüğün vakit başka bir söze dalıncaya kadar onlardan yüz çevir, uzaklaş. Şayet Şeytan sana unutturursa hatırladıktan sonra (kalk), o zalimler grubu ile beraber oturma.');
INSERT INTO verses (sura, aya, text) VALUES (6, 69, 'Allah’tan sakınıp, takvalı olanlara, zalimlerin hesabından hiçbir sorumluluk yoktur. Fakat, Allah’tan sakınıp takvalı olmaları için (onlara) bir öğüt verme vardır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 70, 'Dinlerini oyun ve eğlence edinenleri ve dünya hayatı kendilerini aldatmış olanları bırak. Allah’dan başka bir dost ve bir şefâatçısı olmayan her bir nefsin, kazandıkları (günahlar) yüzünden helâke sürüklenmemesi için sen onunla (Kur’ân’la) öğüt ver.(Kurtuluşu için) her türlü fidyeyi verse de bu ondan kabul edilmez. İşte onlar kazandıkları yüzünden helâke sürüklenmiş kimselerdir. Küfre saplanıp kalmalarından dolayı onlara kaynar bir içecek ve elem dolu bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 71, 'De ki: “Allah’ı bırakıp bize fayda ve zarar vermeyen şeylere mi ibadet edelim? Allah bizi hidâyete kavuşturduktan sonra ökçelerimiz üzerine gerisin geriye mi döndürülelim?" Hani arkadaşları: “Bize gel!” diye hidâyete çağırdıkları halde, yeryüzünde şaşkın şaşkın dolaşırken, Şeytanların saptırdıkları kimse gibi mi olalım?” De ki: “Asıl hidâyet Allah’ın gösterdiği doğru yoldur. Ve biz âlemlerin Rabbine teslim olmakla emrolunduk.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 72, 'Bir de bize; “Namazı dosdoğru kılın ve Allah’a karşı gelmekten sakının” diye emrolundu. O, huzurunda toplanacağınız Allah’tır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 73, 'O, gökleri ve yeri hak ile yaratandır. O’nun “ol!” diyeceği (kıyamet) günü her şey oluverir. O’nun sözü haktır. Sûr’a üfürüleceği günde mülk (ve hakimiyet) yalnız O’nundur. Görüneni de görünmeyeni de bilendir. O Hakîm''dir, her şeyden haberdar olandır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 74, 'Hani İbrahim, babası Âzer’e: “Sen putları ilâh mı ediniyorsun? Şüphesiz, ben seni de, kavmini de apaçık bir sapıklık içinde görüyorum.” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (6, 75, 'Biz, İbrahim’e yakinen bilip iman edenlerden oluversin diye göklerin ve yerin mülkünü böylece gösterdik.');
INSERT INTO verses (sura, aya, text) VALUES (6, 76, 'Üzerine gece karanlığı basınca, bir yıldız gördü. “İşte Rabbim!” dedi. Yıldız batınca da, “Ben öyle batanları sevmem” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 77, 'Ay’ı doğarken görünce de, “İşte Rabbim!” dedi. Ay da batınca, “Andolsun ki, Rabbim bana doğru yolu göstermezse, mutlaka ben de sapıklardan olurum” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 78, 'Güneşi doğarken görünce de: “İşte benim Rabbim! Bu daha büyük” dedi. O da batınca (kavmine dönüp), “Ey kavmim! Ben sizin Allah’a ortak koştuğunuz şeylerden uzağım.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 79, '“Ben, hakka yönelen birisi olarak yüzümü, gökleri ve yeri yaratana döndürdüm. Ben, Allah’a şirk koşanlardan değilim.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 80, 'Kavmi ona karşı delil getirmeye kalkıştı. O da dedi ki: “(Allah) beni doğru yola iletmişken Allah hakkında benimle tartışmaya mı kalkışıyorsunuz? Hem sizin O’na ortak koştuklarınızdan ben korkmam; ancak Rabbimin bir şey dilemiş olması başka. Rabbimin ilmi her şeyi kuşatmıştır. Hâlâ düşünüp öğüt almayacak mısınız?');
INSERT INTO verses (sura, aya, text) VALUES (6, 81, '“Allah’ın size, hakkında hiçbir delil indirmediği şeyleri O’na şirk koşmaktan korkmuyorsunuz da, ben sizin şirk koştuğunuz şeylerden ne diye korkayım? Öyle ise iki taraftan hangisi güvende olmaya daha lâyıktır? Eğer biliyorsanız (haydi söyleyin!)');
INSERT INTO verses (sura, aya, text) VALUES (6, 82, 'İman edenler ve imanlarına zulüm (şirk) karıştırmayanlara gelince; işte güven onlar içindir, hidayete erenler de onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 83, 'İşte bu, kavmine karşı İbrahim’e verdiğimiz delilimizdir. Biz, dilediğimiz kimselerin derecelerini yükseltiriz. O, Hakim ve her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 84, 'İbrahim’e, İshak ve Ya''kûb’u bağışladık, her birini de hidayete erdirdik. Daha önce Núh’u hidayete erdirmiştik. O’nun soyundan Dâvud, Süleyman, Eyyûb, Yûsuf, Mûsâ ve Hârûn’u da hidayete erdirmiştik. İşte iyileri biz böyle mükâfatlandırırız');
INSERT INTO verses (sura, aya, text) VALUES (6, 85, 'Zekeriyya’ya, Yahyâ’ya, İsâ’ya, İlyas’a da (hidâyet verdik). Hepsi salihlerdendi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 86, 'İsmail’e, Elyesa’ya,Yûnus’a ve Lût’a da (hidâyet verdik). Her birini âlemlere üstün kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (6, 87, 'Onların babalarından, zürriyetlerinden ve kardeşlerinden bazılarını da (hidâyete erdirdik). Onları seçtik ve onları doğru bir yola da ilettik.');
INSERT INTO verses (sura, aya, text) VALUES (6, 88, 'Bu Allah’ın hidâyetidir. O, kullarından kimi dilerse onunla hidâyete erdirir. Eğer onlar dahi şirk koşsalardı, yaptıkları her şey boşa giderdi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 89, 'Onlar, kendilerine kitap, hikmet ve nübüvvet verdiğimiz kimselerdir. Şimdi bunlar (Kureyşliler) onları inkâr edip, küfre sapıyorlarsa biz de yerlerine onları inkâr edip, küfre sapmayan bir topluluğu onlara vekil kılarız.');
INSERT INTO verses (sura, aya, text) VALUES (6, 90, 'İşte bunlar Allah’ın hidâyet ettiği kimselerdir. O halde sen de onların hidâyetlerine uy. De ki: “Ben buna karşılık sizden bir ücret istemiyorum. Bu (Kur''an) âlemlere bir öğütten başka bir şey değildir.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 91, 'Allah’ın bir kimseye, hiçbir şey indirmediğini söyleyerek, Allah’ın kadrini gereği gibi bilemediler. De ki: Öyleyse Mûsâ’nın insanlar için aydınlatıcı ve yol gösterici olarak getirdiği, o kitabı kim indirdi? Siz onu parça parça kâğıtlara (yazıyor) bir kısmını açıklıyor, çoğunu da gizliyorsunuz. Sizin de atalarınızın da bilemediği şeyler (Kur''an''la) size öğretilmiştir. (Rasûlüm) “Allah''tır” (onu indiren) de, sonra onları bırak da daldıkları sapıklarında oynayadursunlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 92, 'İşte bu (Kur’an) da, bereket kaynağı, kendinden öncekileri (ilâhî kitapları) tasdik eden ve şehirler anasını (Mekke’yi) ve bütün çevresini (tüm insanlığı) uyarasın diye indirdiğimiz bir kitaptır. Ahirete iman edenler, ona iman eder ve onlar namazlarına da devam ederler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 93, 'Allah’a karşı yalan uyduran veya kendine bir şey vahyedilmemişken, “Bana vahyolundu” diyen, ya da “Allah’ın indirdiğinin benzerini ben de indireceğim.” diye laf eden kimseden daha zalim kimdir? Zalimlerin şiddetli ölüm sancıları içinde çırpındığı; meleklerin ellerini uzatmış, “Haydi canlarınızı kurtarın! Allah’a karşı doğru olmayanı söylediğiniz ve O’nun ayetlerinden kibirlenerek yüz çevirdiğiniz için bugün aşağılayıcı azap ile cezalandırılacaksınız” diyecekleri zaman hallerini bir görsen!');
INSERT INTO verses (sura, aya, text) VALUES (6, 94, 'Sizi ilk defa yarattığımız gibi, bize tek başınıza geldiniz. Size bağışladıklarımızı arkanızda bıraktınız. Allah''ın (ibadet hususunda) ortakları olduğunu ileri sürdüğünüz o şefaatçilerinizi beraberinizde göremiyoruz. Şüphesiz aranızdaki bağlar kopmuş; (Allah''a ibadet hususunda ortak olduklarını) iddia ettikleriniz sizden ayrılıp gitmişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 95, 'Taneyi ve çekirdeği yarıp filizlendiren, ölüden diriyi çıkaran, diriden de ölüyü çıkaran Allah’tır. İşte Allah budur! O halde (haktan) nasıl dönersiniz?');
INSERT INTO verses (sura, aya, text) VALUES (6, 96, 'O, karanlığı yarıp sabahı çıkarandır. Geceyi dinlenme zamanı, Güneş''i ve Ay''ı da ince birer hesap ölçüsü kıldı. Bütün bunlar mutlak güç sahibinin, hakkıyla bilenin takdiridir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 97, 'Karanın ve denizin karanlıklarında kendileriyle doğru yolu bulasınız diye sizin için yıldızları yaratan O’dur. Şüphesiz biz, bilen bir topluluk için âyetleri ayrı ayrı açıkladık.');
INSERT INTO verses (sura, aya, text) VALUES (6, 98, 'O, sizi bir tek candan yaratandır. Sizin bir karar kılma yeriniz, bir de emanet bırakılma yeriniz var. Biz anlayan bir toplum için âyetleri ayrı ayrı açıklamışızdır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 99, 'Gökten su indiren de O’dur. O su ile her çeşit bitkiyi bitirdik. O bitkiden bir yeşillik meydana getirdik ki, bu yeşillikten üst üste binmiş taneler, hurma tomurcuğundan (koparılması kolay) sarkmış salkımlar, üzüm bağları, (yaprakları) birbirine benzeyen ve (meyveleri) benzemeyen zeytin ve nar çıkarırız. Meyve verdikleri ve bir de olgunlaştıkları zaman meyvesine bir bakın. İşte bütün bunlarda, iman eden bir toplum için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 100, 'Allah’ın yarattığı cinleri O’na ortak koştular. Cahilce O’nun için oğullar ve kızlar uydurdular. O, onların vasıflandırdıklarından münezzeh ve çok yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 101, 'Gökleri ve yeri yoktan var eden O’dur. O’nun bir eşi yokken nasıl bir oğlu olabilir? Hem her şeyi O yaratmıştır ve her şeyi hakkıyla bilen de O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (6, 102, 'İşte bu, Rabbiniz Allah’tır. Ondan başka (hak) ilah yoktur. Her şeyin yaratıcısıdır. O’na ibadet edin. O, her şey üzerinde vekildir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 103, 'Gözler O’nu onu ihata ve idrak edemez. O ise bütün gözleri kuşatmıştır. O, lütuf sahibidir, her şeyden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 104, 'Size Rabbinizden apaçık deliller gelmiştir. Artık kim görürse kendi lehine; kim de (hakkı) görmezse kendi aleyhinedir. Ben başınızda bekçi değilim.');
INSERT INTO verses (sura, aya, text) VALUES (6, 105, 'Biz ayetleri türlü türlü genişçe beyan ederiz. Ta ki onlar, ''''sen (başkasından) okumuşsun'''' derler. Biz, (hak ve batılı) bilen kimselere ayetleri böylece açıklamaktayız.');
INSERT INTO verses (sura, aya, text) VALUES (6, 106, 'Rabbinden sana vahyedilene uy. O’ndan başka (hak) ilah yoktur. Müşriklerden de yüz çevir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 107, 'Eğer Allah dileseydi onlar şirk koşmazlardı. Seni onlara gözetici kılmadık. Sen onlara vekil de değilsin.');
INSERT INTO verses (sura, aya, text) VALUES (6, 108, 'Müşriklerin, Allah’tan başka dua ettiklerine sövmeyin ki, onlar da taşkınlık ederek cahilce Allah’a sövmesinler. Her toplumun yaptığını böyle süslemişizdir. Sonra Rablerine döndürülürler de O, kendilerine (dünyada) ne yaptıklarını haber verir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 109, '(Müşrikler), kendilerine bir mucize gelirse, ona mutlaka iman edeceklerine dair var güçleriyle Allah’ın adına yemin ederler. De ki: “Mucizeler ancak Allah katındadır. O mucizeler geldiği vakit de inanmayacaklarını siz ne bileceksiniz?”');
INSERT INTO verses (sura, aya, text) VALUES (6, 110, 'Onların kalplerini ve gözlerini tersine çeviririz de, ilk defa iman etmedikleri gibi yine iman etmezler. Biz de onları azgınlıkları içinde bocalar bir halde bırakırız.');
INSERT INTO verses (sura, aya, text) VALUES (6, 111, 'Biz, onlara melekleri de indirsek, onlarla ölüler de konuşsa ve her şeyi toplayıp önlerine de koysak, Allah dilemedikçe onlar yine de iman etmezlerdi. Fakat onların çoğu bilmiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 112, 'Böylece biz, her peygambere insan ve cin şeytanlarını düşman kıldık. Aldatmak için birbirlerine süslü sözler telkin ederler. Rabbin dileseydi bunu yapamazlardı. Öyleyse sen onları iftiraları ile baş başa bırak.');
INSERT INTO verses (sura, aya, text) VALUES (6, 113, 'O sözleri, ahirete iman etmeyenlerin kalpleri ona meyletsin, bir de ondan hoşnut olsun ve işledikleri günahları işlemeye devam etsinler diye söylerler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 114, '“O, size kitabı ayrıntılı olarak indirmişken, Allah’tan başka bir hakem mi arayayım?” Kendilerine kitap verdiğimiz kimseler, onun Rabbin tarafından hak olarak indirilmiş olduğunu kesinlikle bilirler. Sakın sen de şüphe edenlerden olma!');
INSERT INTO verses (sura, aya, text) VALUES (6, 115, 'Rabbinin sözü doğruluk ve adalet bakımından eksiksizdir. Onun sözlerini değiştirebilecek yoktur O, her şeyi işiten, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 116, 'Eğer sen yeryüzünde bulunanların çoğuna itaat edersen, seni Allah yolundan saptırırlar. Çünkü onlar, sadece zanna uyarlar ve sadece yalan uydururlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 117, 'Doğrusu Rabbin, yolundan kimin saptığını daha iyi bilir. Hidayete ermiş olanları da en iyi O bilir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 118, 'Eğer ayetlerine iman eden kimseler iseniz artık üzerine Allah’ın ismi anılarak kesilmiş hayvanlardan yiyin!');
INSERT INTO verses (sura, aya, text) VALUES (6, 119, 'Size ne oluyor da, Allah’ın ismi anılarak kesilenlerden yemiyorsunuz? Oysa Allah, zorda kalmanız dışında, size haram olanları ayrıntılarıyla açıklamıştır. Doğrusu birçokları, heva ve heveslerine uyarak, bilmeden saptırıyorlar. Şüphesiz Rabbin, haddi aşanları en iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 120, 'Günahın açıktan olanını da, gizli olanını da terk edin. Günah işleyenler, işledikleri suça karşılık mutlaka cezalandırılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 121, 'Üzerine Allah’ın adı anılmadan kesilen hayvanları yemeyin. Şüphesiz bu, günahtır. Şeytanlar, dostlarına sizinle mücadele etmeleri için fısıldarlar. Eğer onlara uyarsanız, şüphesiz siz de müşriklerden olursunuz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 122, 'Ölü iken (imanla) kendisini dirilttiğimiz, insanlar arasında ona yürümesi için nur verdiğimiz kimse, içinden çıkamayacağı karanlıklarda kalan kimse gibi midir? Kâfirlere yaptıkları işler böyle süslü gösterilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 123, 'Böylece her kasabada, oralarda bozgunculuk yapmaları için günahkârlarının liderler yaptık. Hâlbuki onlar ancak kendilerine aldatırlar, ama farkında olmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (6, 124, 'Onlara bir ayet geldiği zaman; “Allah’ın Rasûllerine verilen, bize de verilmedikçe iman etmeyeceğiz” derler. Oysa Allah, peygamberliği kime vereceğini daha iyi bilir. Bu, suçlu günahkârlara Allah katında bir küçüklük, yaptıkıları hilekârlıklar yüzünden de şiddetli bir azab isabet edecektir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 125, 'Allah, kimi doğru yola iletmek isterse, onun gönlünü İslam’a açar. Kimi de saptırmak isterse, göğe yükseliyormuş gibi, kalbini dar ve sıkıntılı kılar. Allah iman etmeyenlerin üstüne pisliği/azabı işte böyle verir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 126, 'Rabbinin dosdoğru yolu işte budur. Öğüt alan topluluk için ayetleri etraflıca açıkladık.');
INSERT INTO verses (sura, aya, text) VALUES (6, 127, 'Onlar için, Rablerinin katında selamet yurdu vardır. O, yapmakta olduklarından ötürü onların velisi (dost ve yardımcısı)dir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 128, 'Allah, hepsini o gün toplayarak; "Ey cin topluluğu! İnsanların çoğunu yoldan çıkardınız." der. Onların dostları olan insanlar ise; "Rabbimiz, birbirimizden istifade ettik ve bizim için belirlediğin sürenin sonuna ulaştık" derler. Allah: "Allah''ın dilediği hariç, Cehennem sizin ebedi olarak kalacağınız meskeniniz olsun.” der. Şüphesiz Rabbin Hakîm''dir, Alîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 129, 'İşte biz, kazanmakta oldukları günahlar sebebiyle zalimlerin bir kısmını diğer bir kısmına böyle musallat ederiz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 130, '“Ey cin ve insan topluluğu! İçinizden size ayetlerimi anlatan ve bu günle karşılaşacağınıza dair, sizi uyaran rasûller gelmedi mi?” Onlar: "Biz kendi aleyhimize şahidiz" diyeceklerdir. Dünya hayatı onları aldattı da, kâfir olduklarına dair kendi aleyhlerine şahitlik ettiler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 131, 'Bu (rasûllerin gönderilmesi) halkı habersizken, Rabbinin ülkeleri haksız yere yok etmeyeceğinden dolayıdır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 132, 'Herkesin amellerine göre dereceleri vardır. Rabbin onların yaptıklarından habersiz değildir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 133, 'Rabbin hiçbir şeye ihtiyaç duymayan, merhamet sahibidir. O dilerse sizi yok eder ve daha sonra dilediğini sizin yerinize getirir, tıpkı sizi başka bir topluluğun soyundan var ettiği gibi.');
INSERT INTO verses (sura, aya, text) VALUES (6, 134, 'Şüphesiz size vadedilen şeyler mutlaka gelecektir. Siz bunun önüne geçemezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 135, 'De ki: "Ey kavmim! Siz elinizden geleni yapın. Şüphesiz ben de yapacağım. Bu yurdun akıbetinin kim için olduğunu öğreneceksiniz. Gerçek şu ki, zalimler asla kurtuluşa eremezler."');
INSERT INTO verses (sura, aya, text) VALUES (6, 136, 'Allah’ın yarattığı ekin ve hayvandan, kendi zanlarınca Allah’a bir hisse ayırıp da, “Bu Allah’ındır, bu da ortaklarımızındır” diyorlar. Ortakları için ayırdıkları Allah''a ulaşmıyordu, fakat Allah için ayırdıkları ortaklarına ulaşıyordu! Ne kadar da kötü hüküm veriyorlar!');
INSERT INTO verses (sura, aya, text) VALUES (6, 137, 'Böylece onların ortakları, müşriklerden bir çoğuna evlatlarını öldürmeyi de hoş göstermiştir. Hem onları helâk etmek için, hem de dinlerini kendilerine karma karışık etmek için. Eğer Allah dileseydi bunu yapamazlardı. Öyleyse onları uydurduklarıyla baş başa bırak!');
INSERT INTO verses (sura, aya, text) VALUES (6, 138, 'Bir de (asılsız iddialarda bulunarak) dediler ki: “Bunlar yasaklanmış hayvanlar ve ekinlerdir. Onları bizim dilediklerimizden başkası yiyemez. (Şunlar da) sırtları (binilmesi ve yük yüklemesi) haram edilmiş hayvanlardır.” Bir kısım hayvanları da keserken üzerlerine Allah’ın adını anmazlar. (Bütün bunları) Allah’a iftira ederek yaparlar. Bu iftiraları sebebiyle Allah onları cezalandıracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 139, 'Bir de: "Bu hayvanların karınlarındakiler ise sadece erkeklerimiz içindir. Kadınlarımıza haramdır, ama eğer ölü doğarlarsa hepsi bunu yemekte ortaktır." derler. Allah, onların bu vasıflarının cezasını yakında verecektir. Şüphesiz Rabbin hikmet sahibidir, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 140, 'Akılsızlıkları yüzünden, bilgisizce çocuklarını öldüren ve Allah’ın kendilerine verdiği rızıkları, Allah’a iftira ederek haram sayanlar, elbette hüsrana uğramıştır. Onlar sapıklığa düşmüş ve asla doğru yolu bulacak da değildirler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 141, 'Çardaklı ve çardaksız bağları inşa eden Allah''tır. Tadları çeşitli ekin ve hurmaları, zeytin ve narı birbirine hem benzeyen ve hem de benzemeyen şekilde yaratan O''dur. Meyve verdikleri zaman onların meyvelerinden yiyin ve hasat edildiği zaman da hakkını verin. Sakın israf etmeyin. Çünkü O, israf edenleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (6, 142, 'Hayvanlardan yük taşıyacak, (yapağısından) döşek yapılacak olanları da (yaratan O’dur). Allah’ın size rızık olarak verdiklerinden yiyin, fakat sakın Şeytan''ın adımlarına uymayın. Çünkü o, sizin apaçık bir düşmanınızdır.');
INSERT INTO verses (sura, aya, text) VALUES (6, 143, 'Sekiz çift hayvan, koyundan iki ve keçiden iki tane. De ki: "O, iki erkeği mi, yoksa iki dişiyi mi, ya da bu iki dişinin rahimlerinde bulunanları mı haram kıldı? Eğer doğru söylüyorsanız bir bilgiye dayanarak bana haber verin."');
INSERT INTO verses (sura, aya, text) VALUES (6, 144, 'Deveden iki ve sığırdan da iki tane. De ki: "O, iki erkeği mi, yoksa iki dişiyi mi ya da bu iki dişinin rahimlerinde bulunanları mı haram kıldı? Yoksa siz, Allah’ın bunları size emrettiğine şahit mi oldunuz?" Sırf insanları saptırmak için, bir bilgiye dayanmadığı halde Allah’a karşı yalan uydurandan daha zalim kim olabilir? Allah, zalimler topluluğuna hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (6, 145, 'De ki: “Bana vahyolunanlar arasında ölmüş hayvan eti, akıtılmış kan, bir pislik olan domuz eti veya bir günah olarak Allah''tan başkası adına kesilen hayvanlar dışında haram kılınan başka bir şey bulamıyorum.” Kim zaruret halinde, bunları arzulamadan ve zaruret miktarını aşmadan bunlardan yerse; şüphesiz Rabbin, çokça bağışlayandır, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 146, 'Yahudilere de bütün tırnaklı hayvanları haram kıldık. Sırtlarında veya bağırsaklarında bulunan ya da kemiğe karışanlar dışında sığır ve koyunun iç yağlarını da onlara haram kıldık. Böylece, azgınlıkları sebebiyle onları cezalandırdık. Şüphe yok ki biz doğru söyleyenleriz.');
INSERT INTO verses (sura, aya, text) VALUES (6, 147, 'Seni yalanlayacak olurlarsa, de ki: “Rabbiniz geniş bir rahmet sahibidir. O’nun azabı günahkârlar topluluğundan geri çevirilemez.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 148, 'Müşrikler: "Allah dileseydi ne biz, ne de babalarımız şirk koşardık ve hiçbir şeyi de haram kılmazdık" diyecekler. Bizim elem verici azabımızı tadana kadar onlardan öncekiler de yalanlamışlardı. De ki: “Bize gösterebileceğiniz bir deliliniz var mı? Siz, sadece zanna uyuyor ve sadece uyduruyorsunuz."');
INSERT INTO verses (sura, aya, text) VALUES (6, 149, 'De ki: "En kesin delil Allah’ındır. O, dileseydi elbette hepinize hidayet ederdi."');
INSERT INTO verses (sura, aya, text) VALUES (6, 150, 'De ki: “Haydi, Allah''ın bunları haram kıldığına dair şahitlik edecek şahitlerinizi getirin.” Şahitlik ederlerse sakın onlarla beraber şahitlik etme. Ayetlerimizi yalanlayıp, ahirete iman etmeyen ve başkalarını Rablerine denk tutanların heveslerine sakın uyma.');
INSERT INTO verses (sura, aya, text) VALUES (6, 151, 'De ki: “Gelin de Rabbinizin size neyi haram kıldığını okuyayım. O’na hiçbir şeyi ortak koşmayın. Anne-babaya iyilik edin. Yoksulluk endişesiyle çocuklarınızı öldürmeyin. Sizin de, onların da rızıklarını biz veririz! Fuhşiyatın açığına da gizlisine de yaklaşmayın. Allah’ın haram kıldığı cana haksız yere kıymayın. Umulur da akıl edersiniz diye size işte bunları emrediyor.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 152, 'Bir de yetimin malına, rüştüne erinceye kadar en güzel olandan başka bir şekilde yaklaşmayın. Ölçüyü ve tartıyı dosdoğru yapın. Biz hiç kimseye gücünün üzerinde sorumluluk yüklemeyiz. Akraba bile olsa konuştuğunuz zaman adaletli olun ve Allah’a verdiğiniz sözünüzü yerine getirin! Umulur ki, düşünüp öğüt alırsınız diye size, işte bunları emrediyor.');
INSERT INTO verses (sura, aya, text) VALUES (6, 153, 'İşte bu, benim dosdoğru yolumdur, buna uyun! Sizi, Onun yolundan saptırıp, ayıracak başka yollara uymayın! Umulur da takvalı olursunuz diye işte size bunu emrediyor.');
INSERT INTO verses (sura, aya, text) VALUES (6, 154, 'Sonra iyilik yapanlara nimeti tamamlamak, her şeyi açıklamak, hidayet ve rahmete erdirmek için Mûsâ’ya Kitab’ı (Tevrat’ı) verdik ki, Rablerinin huzuruna varacaklarına iman etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (6, 155, 'Bu, mübarek olarak indirdiğimiz bir kitaptır. O’na tabi olun ve takvalı olun ki size merhamet edilsin.');
INSERT INTO verses (sura, aya, text) VALUES (6, 156, '“Bizden önce kitap yalnız iki topluluğa (Yahudi ve Hristiyanlara) indirildi ve biz onların okuduklarından habersiz kimseler idik” demeyesiniz diye (size Kur’ân’ı indirdik).');
INSERT INTO verses (sura, aya, text) VALUES (6, 157, 'Yahut da; "Kitap bize indirilmiş olsaydı, onlardan daha fazla hidayet üzere olurduk.” demeyesiniz diye; size, Rabbinizden açık bir belge, hidayet ve rahmet gelmiştir. Allah’ın ayetlerini yalanlayanlardan ve onlardan yüz çevirenden daha zalim kim olabilir? Ayetlerimizden yüz çevirenleri, yüz çevirmelerinden ötürü çok kötü bir azapla cezalandıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (6, 158, 'Onlar kendilerine meleklerin gelmesinden yahut Rabbinin gelmesinden yahut Rabbinin âyetlerinden birisinin gelmesinden başkasını mı bekliyorlar? Rabbinin ayetlerinin geldiği gün, daha önceden iman etmemiş ya da imanıyla bir iyilik kazanmamış kimseye artık imanı bir fayda sağlamayacaktır. De ki: "Bekleyin bakalım, biz de bekliyoruz!"');
INSERT INTO verses (sura, aya, text) VALUES (6, 159, 'Dinlerini parça parça edip fırka fırka ayrılanlar var ya; senin onlarla hiçbir ilişkin yoktur. Onların işi ancak Allah’a aittir. Sonra O, yaptıklarını kendilerine haber verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (6, 160, 'Kim bir iyilikle gelirse, ona on katı (mükâfat) verilecektir. Kim de bir kötülükle gelirse, yalnızca onun karşılığı ile cezalandırılacaktır ve onlara zulmedilmez.');
INSERT INTO verses (sura, aya, text) VALUES (6, 161, 'De ki: “Hiç şüphesiz Rabbim, beni dosdoğru bir yola, dimdik ayakta duran bir dine, hanîf olan İbrahim’in dinine iletti. O, müşriklerden olmadı.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 162, 'De ki: “Benim namazım, kurbanım, hayatım ve ölümüm âlemlerin Rabbi olan Allah içindir.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 163, '“O’nun hiçbir ortağı yoktur. İşte ben bununla emrolundum ve ben Müslümanların ilkiyim.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 164, 'De ki: “O, her şeyin Rabbi iken, ben O’ndan başka bir rab mi arayacağım? Herkesin kazandığı günah yalnızca kendisi aleyhinedir. Günahkâr hiçbir nefis başkasının günahını yüklenmez. Sonunda dönüşünüz yalnızca Rabbinize olacak ve hakkında ayrılığa düştüğünüz şeyleri O, size haber verecektir.”');
INSERT INTO verses (sura, aya, text) VALUES (6, 165, 'Sizi yeryüzünün halifeleri kılan ve size verdikleriyle sizi sınamak için kiminizi kiminizden derecelerle üstün kılan O’dur. Şüphesiz Rabbin, cezası çabuk olandır. Çok bağışlayan ve merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 1, 'Elif, Lâm, Mîm, Sâd.[1]');
INSERT INTO verses (sura, aya, text) VALUES (7, 2, 'Bu sana indirilen bir kitaptır. Öyleyse Müminleri bununla uyarman ve öğüt vermen için kalbinde hiçbir sıkıntı olmasın.');
INSERT INTO verses (sura, aya, text) VALUES (7, 3, 'Rabbinizden size indirilmiş olana uyun, Onun dışında dost edindiklerinize uymayın. Ne kadar az öğüt alıyorsunuz!');
INSERT INTO verses (sura, aya, text) VALUES (7, 4, 'Nice yurtları helak ettik. Onlara azabımız gece uykusuna dalmışken yahut gündüz istirahat hâlinde iken gelmişti.');
INSERT INTO verses (sura, aya, text) VALUES (7, 5, 'Azabımız onlara geldiği vakit; “Biz, gerçekten zalim kimselerdik!” demekten başka söyleyecek sözleri olmadı.');
INSERT INTO verses (sura, aya, text) VALUES (7, 6, 'Andolsun ki, kendilerine peygamber gönderilenleri de, peygamberleri de elbette sorgulayacağız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 7, 'Andolsun, onlara (yaptıklarını) tam bir bilgi ile anlatacağız. Biz onlardan gâib/uzak değildik.');
INSERT INTO verses (sura, aya, text) VALUES (7, 8, 'İşte o gün amellerin tartılması bir hakikattir. Tartıları ağır gelenler, işte onlar kurtuluşa erenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 9, 'Tartıları hafif gelenler, ayetlerimize yaptıkları zulümlerden ötürü kendilerini hüsrana sokanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 10, 'Andolsun sizi yeryüzüne yerleştirip orada sizin için geçimlikler sağladık. Buna rağmen ne kadar da az şükrediyorsunuz!');
INSERT INTO verses (sura, aya, text) VALUES (7, 11, 'Andolsun sizi yarattık, ardından da şekil verdik. Sonra meleklere: “Âdem’e secde edin.” dedik. İblis dışında hepsi secde ettiler. O ise, secde edenlerden olmadı.');
INSERT INTO verses (sura, aya, text) VALUES (7, 12, 'Allah: “Sana emrettiğim zaman, secde etmene ne engel oldu?” dedi. İblis: “Ben, ondan daha hayırlıyım. Beni ateşten, onu ise çamurdan yarattın.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 13, 'Allah ona dedi ki: "Hemen in oradan. Artık orada büyüklük taslamak senin haddin değildir. Hemen çık git. Zira sen, aşağılık kimselerdensin."');
INSERT INTO verses (sura, aya, text) VALUES (7, 14, 'İblis: “Öyleyse bana, onların tekrar diriltilecekleri güne kadar mühlet ver!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 15, 'Allah dedi ki: “O halde sen, kendisine mühlet verilenlerdensin.''''');
INSERT INTO verses (sura, aya, text) VALUES (7, 16, '(İblis) “ Öyleyse beni azdırmana karşılık, ben de onlar için senin dosdoğru yolunun üzerinde oturacağım.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 17, '"Ardından onlara, önlerinden, arkalarından, sağlarından ve sollarından sokulacağım. Böylece sen onların çoğunu şükredenlerden bulmayacaksın."');
INSERT INTO verses (sura, aya, text) VALUES (7, 18, '(Allah da ona) “Yerilmiş, kınanmış ve kovulmuş olarak çık oradan! Onlardan sana tabi olanlarla beraber hepinizi Cehennem''e dolduracağım” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 19, 'Ve: "Ey Âdem! Sen ve eşin Cennet''e yerleşin, dilediğiniz yerden bol bol yiyin. Yalnız şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz."');
INSERT INTO verses (sura, aya, text) VALUES (7, 20, 'Şeytan, örtülü olan avret yerlerini onlara göstermek için ikisine de vesvese vererek “Rabbiniz size bu ağacı sırf melek olursunuz veya ebedî kalanlardan olursunuz diye yasakladı.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 21, 'Ve: “Şüphesiz ben size öğüt verenlerdenim.” diye de onlara yemin etti.');
INSERT INTO verses (sura, aya, text) VALUES (7, 22, 'Bu sûretle onları kandırarak aşağıya düşürdü. Ağacın meyvesinden tattıklarında, mahrem yerleri birbirine görünüverdi ve oraları Cennet yapraklarıyla örtmeye başladılar. Rableri, o ikisine: “İkinize, bu ağacı yasaklamadım mı? Şeytan ikinizin apaçık düşmanıdır demedim mi?” diye seslendi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 23, 'O ikisi: "Rabbimiz! Biz kendimize zulmettik. Eğer bizi bağışlamaz ve bize merhamet etmezsen elbette hüsrana uğrayanlardan oluruz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 24, '(Yüce Allah) buyurdu ki: “Birbirinize düşman olarak oradan inin! Siz yeryüzünde bir süreye kadar yerleşip kalacak ve orada geçineceksiniz.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 25, 'Dedi ki: "Orada yaşayacak, orada ölecek ve tekrar oradan diriltilip çıkarılacaksınız."');
INSERT INTO verses (sura, aya, text) VALUES (7, 26, 'Ey Âdemoğlu! Size mahrem yerlerinizi örteceğiniz ve bir de süslenip güzelleşeceğiniz elbiseler indirdik. Takva elbisesi ise, bunlardan daha da hayırlıdır. İşte bunlar, umulur da öğüt alırlar diye indirilen Allah ayetlerindendir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 27, 'Ey Âdemoğlu! Şeytan; ana ve babanızı, mahrem yerlerini birbirine göstermek için elbiselerini sıyırarak Cennet''ten çıkardığı gibi, sakın sizi de fitneye düşürmesin. O ve ordusu, sizin onları göremediğiniz yerden sizi görürler. Doğrusu biz şeytanları, iman etmeyenlerin dostları kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (7, 28, 'Onlar, çirkin bir iş yaptıkları zaman: “Biz, atalarımızı böyle yaparken bulduk. Allah da bunu bize emretti.” derler. Onlara de ki: “Allah, asla kötülüğü emretmez. Allah’a karşı bilmediğiniz şeyleri mi söylüyorsunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (7, 29, 'De ki: "Rabbim adaleti emretti; her secde yerinde yüzünüzü O''na doğrultun; dinde samimi olarak O''na yalvarın. Sizi yarattığı gibi yine O''na döneceksiniz."');
INSERT INTO verses (sura, aya, text) VALUES (7, 30, 'O, kimine hidayet verdi, kimine de sapıklık hak oldu. Çünkü bunlar Allah''ı bırakıp şeytanları dost edinmiş ve kendilerini doğru yolda sanmışlardı.');
INSERT INTO verses (sura, aya, text) VALUES (7, 31, 'Ey Âdemoğlu! Her mescidde ziynetlerinizi takının. Yiyin, için; fakat israf etmeyin. Çünkü Allah, israf edenleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (7, 32, 'De ki: “Allah’ın kulları için çıkardığı zineti, temiz ve hoş rızıkları kim haram kılmıştır?” De ki: “Onlar, dünya hayatında iman edenler içindir. Kıyamet gününde de yalnız onlara mahsustur.” Bilen bir toplum için ayetleri işte böyle açıklıyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (7, 33, 'De ki: “Rabbim ancak hayasızlıkları, onların açık olanını, gizli olanını; günahı, haksızca yapılan taşkınlıkları, hakkında hiçbir delil indirmemiş olduğu halde Allah’a şirk koşmanızı ve Allah hakkında bilmediğiniz şeyleri söylemenizi haram kılmıştır.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 34, 'Her ümmetin bir eceli vardır. Ecelleri geldiği vakit onu ne bir an erteleyebilirler, ne de öne alabilirler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 35, 'Ey Âdemoğlu! Size, içinizden ayetlerimi okuyan peygamberler geldiğinde, kim sakınıp takvalı olur ve kendini düzeltirse; artık onlar için bir korku yoktur. Onlar üzülecek de değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 36, 'Ayetlerimizi yalanlayanlar ve onlara karşı büyüklük taslayanlar, işte onlar cehennemliklerdir. Onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 37, 'Allah’a karşı yalan uydurarak iftira edenden yahut O’nun âyetlerini yalanlayandan daha zâlim kim olabilir? Kitapta yazılı olan nasipleri elbette onlara ulaşacaktır. Nihayet elçilerimiz onların canlarını almaya gelince: “Allah’ın dışında dua ettikleriniz hani nerede?” diyecekler. Onlar da: “Bizden uzaklaşıp gittiler.” diyerek kâfir olduklarına dair kendi aleyhlerine şahitlik edeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 38, 'Diyecek ki: “Cinlerden ve insanlardan, sizden önce gelip geçen ümmetlerle birlikte siz de girin ateşe.” Her bir ümmet, ateşe girdikçe kendi kardeşine (dindaşına) lanet edecek. Sonunda hepsi orada bir araya toplanınca, sonra gelenler öncekiler için: “Rabbimiz! İşte bizi bunlar saptırdılar. Onlara ateşten kat kat azap ver!” derler. Allah da: “Herkese kat kat azap vardır, fakat siz bilmiyorsunuz” der.');
INSERT INTO verses (sura, aya, text) VALUES (7, 39, 'Öncekiler de, kendilerinden sonra gelenlere: “Sizin, bizden herhangi bir üstünlüğünüz yoktur. Siz de kazanmış olduklarınıza karşılık azabı tadın!” derler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 40, 'Ayetlerimizi yalanlayıp onlara karşı büyüklük taslayanlara gökyüzünün kapıları açılmayacak, deve iğne deliğinden geçmedikçe, onlar da Cennet''e giremeyeceklerdir. İşte biz, suçluları böyle cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 41, 'Onlara, Cehennem''de ateşten döşekler ve üstlerine de ateşten örtüler vardır. İşte biz, zalimleri böyle cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 42, 'İman ederek salih amel işleyenlere gelince -ki biz kimseye gücünün üstünde bir yük yüklemeyiz- onlar cennetliklerdir. Orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 43, 'Kalplerinde kin adına ne varsa söküp atarız. Altlarından ırmaklar akarken onlar şöyle derler: "Bize bunu hidayet eden Allah’a hamdolsun. Allah bize hidayet etmeseydi; şüphesiz biz doğru yolu bulamazdık. Rabbimizin elçileri hakkı getirmişlerdir.” “İşte siz, yaptıklarınızın karşılığı olarak şu Cennet''e varis kılındınız!” diye onlara seslenilir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 44, 'Cennet ehli, Cehennem ehline şöyle seslenir: “Biz, Rabbimizin bize vadettiğini hakikaten bulduk. Siz de Rabbinizin vaadini gerçekten buldunuz mu?” Onlar da: “Evet!” derler. Aralarında bir münadi: “Allah’ın laneti zalimlerin üzerine olsun!” diye seslenir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 45, 'Onlar, Allah yolundan alıkoyan ve yolu eğriltmek isteyen kimselerdir. Aynı zamanda ahireti de inkâr ederler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 46, 'İki taraf arasında bir perde (engel) vardır. A''raf''ta da herkesi simalarından tanıyan birtakım adamlar vardır. Cennetliklere “Selam size” diye seslenirler. Onlar, çok arzuladıkları halde henüz oraya girmemişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 47, 'Gözleri cehennemlikler tarafına çevrilince; “Rabbimiz, bizi zalimler topluluğuyla beraber kılma!” derler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 48, 'Araf''ta bulunanlar, simalarından tanıdıkları kimselere seslenerek, “Çokluğunuz ve büyüklük taslıyor olmanız size hiçbir fayda vermedi.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 49, '“Sizin, ‘Allah bunları rahmete erdirmez’ diye yemin ettikleriniz şunlar mı?” (Sonra cennetliklere dönerek) “Haydi, girin Cennet''e. Size korku yok. Siz üzülecek de değilsiniz.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 50, 'Cehennem halkı, Cennet halkına: “Bize de biraz su ya da Allah’ın size verdiği rızıklardan gönderin” diye seslenirler. Cennet halkı da onlara “Şüphesiz Allah, bunları kâfirlere haram kılmıştır!” derler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 51, 'Onlar dinlerini oyun ve eğlence edinmişler ve dünya hayatı da kendilerini aldatmıştı. İşte onlar bu günlerine kavuşacaklarını nasıl unuttular ve âyetlerimizi nasıl inkâr edip durdularsa, biz de onları bugün öyle unuturuz.');
INSERT INTO verses (sura, aya, text) VALUES (7, 52, 'Gerçekten onlara, inanan bir toplum için yol gösterici ve rahmet olarak, ilim üzere açıkladığımız bir kitap getirdik.');
INSERT INTO verses (sura, aya, text) VALUES (7, 53, 'Onlar zamanı gelince bildirdiklerinin gerçekleşmesinden başkasını mı bekliyorlar? Ortaya çıktığı gün, önceleri onu unutmuş olanlar; “Kuşkusuz Rabbimizin elçileri gerçeği getirmişlerdi. Şimdi bize şefaat edecek bir şefaatçi var mıdır? Veyahut yaptıklarımızdan daha başka şeyler yapmamız için bir geri dönüş hakkımız var mıdır?” derler. Onlar, kendilerini hüsrana uğratmış ve uydurdukları şeyler de kaybolup onlardan ayrılmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 54, 'Şüphesiz gökleri ve yeri altı günde yaratmış olan Rabbiniz Allah, sonrasında arşın üstüne yükselmiştir. Birbirlerini durmadan takip eden geceyi gündüze bürüyüp örter. Güneş, Ay ve yıldızlar da O''nun emrine boyun eğmiştir. Dikkat edin! Yaratma da, emir de yalnızca O''na aittir. Âlemlerin Rabbi olan Allah ne yücedir!');
INSERT INTO verses (sura, aya, text) VALUES (7, 55, 'Rabbinize yalvara yakara, gizlice dua edin. Şüphesiz O, haddi aşanları sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (7, 56, 'Yeryüzünün ıslah edilmesinden sonra orada bozgunculuk yapmayın. Allah’a korku ve ümitle dua edin. Şüphesiz Allah’ın rahmeti hayırseverlere pek yakındır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 57, 'Rahmetinin önünden rüzgârları müjde olmak üzere gönderen O’dur. Rüzgârlar, ağır yağmur yüklü bulutları yüklendiği zaman biz, onu ölü bir bölgeye sürer ve oraya su indiririz. Böylelikle onunla bütün ürünlerden çıkarırız. İşte biz ölüleri de böyle çıkaracağız. Belki düşünüp ibret alırsınız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 58, '(Toprağı) iyi ve elverişli beldenin bitkisi, Rabbinin izniyle bol ve bereketli çıkar. (Toprağı) kötü ve elverişsiz olandan ise, faydasız bitkiden başkası çıkmaz. Şükreden bir toplum için ayetleri işte böyle açıklarız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 59, 'Şüphesiz biz Nûh’u kavmine peygamber olarak gönderdik. Kavmine dedi ki: “Ey kavmim! Allah’a ibadet edin. Sizin O''ndan başka bir ilahınız yoktur. Doğrusu ben, sizin için büyük günün azabından korkuyorum."');
INSERT INTO verses (sura, aya, text) VALUES (7, 60, 'Kavminin ileri gelenleri: “Biz, seni açıkça bir dalalet içinde görüyoruz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 61, 'O da dedi ki: “Ey kavmim! Bende hiçbir sapıklık yoktur. Ben, ancak âlemlerin Rabbi tarafından gönderilen bir peygamberim.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 62, '“Size, Rabbimin vahyettiklerini bildiriyor ve nasihat ediyorum. Ben, Allah''ın katından sizin bilmediğiniz şeyleri biliyorum.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 63, 'Sizi uyarması ve sizin de Allah’a karşı gelmekten sakınıp rahmete ulaşmanız için, içinizden bir adam aracılığı ile Rabbinizden size bir zikir (vahiy ve öğüt) gelmesine şaştınız mı?');
INSERT INTO verses (sura, aya, text) VALUES (7, 64, 'Fakat onu yalanladılar. Biz de onu ve gemide onunla beraber olanları kurtardık. Ayetlerimizi yalanlayanları da suda boğduk. Şüphesiz onlar, kör bir milletti.');
INSERT INTO verses (sura, aya, text) VALUES (7, 65, 'Âd kavmine de kardeşleri Hûd’u gönderdik: "Ey halkım! Allah’a ibadet edin. Sizin O’ndan başka ilahınız yoktur. Hâlâ sakınmayacak mısınız." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 66, 'Kavminin ileri gelenlerinden kâfir olanlar da: “Biz senin aklında bir hafiflik görüyoruz ve gerçekten biz seni yalancılardan sanıyoruz” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 67, '"Ey kavmim! Ben sefih değilim. Fakat ben (size) âlemlerin Rabbi tarafından (gönderilmiş) bir peygamberim.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 68, '“Rabbimin vahyettiklerini size tebliğ ediyorum. Ben sizin için güvenilir bir nasihatçıyım.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 69, 'Sizi uyarması için aranızdan bir adamla size Rabbinizden vahiy gelmesine şaşırdınız mı? Sizi, Nûh''un kavminden sonra yeryüzünün halifeleri kıldığını ve yaratılış yönüyle gücünüzü arttırdığını hatırlayın. Allah''ın nimetlerini anın ki, kurtuluşa erebilesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (7, 70, '"Bize, bir tek ilaha ibadet etmemiz ve atalarımızın ibadet ettiklerini bırakmamız için mi geldin? Eğer doğru söylüyorsan, bizi tehdit ettiğin azabı getir bakalım!" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 71, 'Dedi ki: “Gerçekten Rabbinizden size bir azap ve gazap gelecektir. Yüce Allah’ın haklarında hiçbir delil indirmediği, kendinizin ve atalarınızın taktığı (ilâh diye adlandırdığınız) bir takım adlar hakkında mı benimle tartışıyorsunuz? Artık (azabı) bekleyin. Şüphesiz ben de sizinle birlikte (onu) bekleyenlerdenim.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 72, 'Onu ve beraberindekileri katımızdan bir rahmetle kurtardık. Ayetlerimizi yalanlayarak iman etmeyenlerin de kökünü kuruttuk.');
INSERT INTO verses (sura, aya, text) VALUES (7, 73, 'Semûd kavmine de kardeşleri Salih''i gönderdik. Onlara dedi ki: “Ey kavmim! Allah’a ibadet edin. Sizin O''ndan başka bir ilahınız yoktur. Rabbinizden size apaçık bir delil geldi. Allah’ın bu dişi devesi, sizin için bir mucizedir. Onu bırakın, Allah’ın toprağında otlasın, ona bir kötülük etmeyin. Yoksa sizi acı bir azap yakalar.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 74, 'Âd kavminin ardından sizi halifeler yaptığını, ovalarında köşkler kurup dağlarında evler inşa ettiğiniz bu topraklara yerleştirdiğini hatırlayın. Allah’ın nimetlerini düşünün de, yeryüzünde bozgunculuk yaparak taşkınlık etmeyin!');
INSERT INTO verses (sura, aya, text) VALUES (7, 75, 'O’nun kavminden büyüklük taslayanların ileri gelenleri, içlerinden zayıf gördükleri iman edenlere şöyle dediler: "Salih’in gerçekten Rabbi tarafından gönderilmiş bir peygamber olduğunu biliyor musunuz?" Onlar da dediler ki: "Biz, şüphesiz onunla gönderilene iman ediyoruz."');
INSERT INTO verses (sura, aya, text) VALUES (7, 76, 'Büyüklük taslayanlar ise; "Biz sizin iman ettiğinize karşı kâfiriz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 77, 'Böylece o dişi deveyi boğazlayarak Rablerinin emrine başkaldırdılar ve şöyle dediler: “Ey Salih, eğer sen gönderilmiş peygamberlerden isen bizi tehdit edip durduğunu getir!” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 78, 'Onları dehşetli bir sarsıntı tuttu ve oldukları yerde diz üstü çöküp kaldılar.');
INSERT INTO verses (sura, aya, text) VALUES (7, 79, 'Artık, Salih onlardan yüz çevirdi ve; “Andolsun, ben size Rabbimin vahyettiklerini tebliğ ettim ve size nasihatta bulundum. Fakat siz nasihat edenleri sevmiyorsunuz.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 80, 'Hani Lût da kavmine şöyle demişti: "Sizden evvel âlemlerden hiç kimsenin yapmadığı hayasızlığı mı yapıyorsunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (7, 81, '“Siz, kadınları bırakıp da erkeklere şehvetle yanaşıyorsunuz. Doğrusu siz ölçüyü aşmış bir toplumsunuz.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 82, 'Kavminin cevabı yalnızca: “Çıkarın onları (Lût’u ve ona uyanları) ülkenizden. Çünkü onlar fazla temiz kalmak isteyen insanlarmış” demek oldu.');
INSERT INTO verses (sura, aya, text) VALUES (7, 83, 'Bunun üzerine Biz de hem onu hem de ehlini kurtardık. Ancak karısı geride kalıp helâk edilenlerden oldu.');
INSERT INTO verses (sura, aya, text) VALUES (7, 84, 'Geriye kalanların üzerine öyle bir yağmur yağdırdık ki! Suçluların sonunun nasıl olduğuna bir bak!');
INSERT INTO verses (sura, aya, text) VALUES (7, 85, 'Medyen halkına da kardeşleri Şuayb’ı gönderdik. Onlara şöyle dedi: "Ey kavmim! Allah’a ibadet edin. Sizin O''ndan başka bir ilahınız yoktur. Rabbinizden size apaçık bir delil geldi. Ölçü ve tartıyı tam yapın, insanların eşyalarını eksik vermeyin. Islah edildikten sonra yeryüzünde bozgunculuk etmeyin. Eğer iman ediyorsanız, bu sizin için en hayırlı olandır."');
INSERT INTO verses (sura, aya, text) VALUES (7, 86, 'Ve siz öyle her yolun başında oturarak Allah’a iman edenleri tehdit edip ve eğriliğini arayarak Allah’ın yolundan alıkoymayın. Düşünün ki siz vaktiyle çok az idiniz de sizi çoğalttı. Bozguncuların sonunun nasıl olduğuna da bir bakın.');
INSERT INTO verses (sura, aya, text) VALUES (7, 87, 'Eğer benimle gönderilene içinizden bir grup iman edip, bir grup da iman etmemişse, hüküm verenlerin en hayırlısı olan Allah, aramızda hüküm verinceye kadar sabredin.');
INSERT INTO verses (sura, aya, text) VALUES (7, 88, 'Şuayb’ın kavminden büyüklük taslayan ileri gelenler dediler ki: "Ey Şuayb! Elbette seni ve seninle birlikte iman edenleri memleketimizden çıkaracağız yahut mutlaka bizim dinimize döneceksiniz." dediler. Şuayb: “İstemesek de mi?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 89, '“Allah, bizi sizin dininizden kurtardıktan sonra eğer ona dönersek mutlaka Allah’a karşı yalan uydurmuş oluruz. Rabbimiz Allah’ın dilemesi olmadıkça, sizin dininize dönmemiz bizim için olacak şey değildir. Rabbimiz her şeyi ilmiyle kuşatmıştır. Biz yalnız Allah’a tevekkül ettik. Ey Rabbimiz! Bizimle kavmimiz arasında gerçekle hükmet. Çünkü sen hükmedenlerin en hayırlısısın.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 90, '(Şuayb’ın) kavminden kâfir olan ileri gelenler dediler ki: “(Ey ahali!) Andolsun ki eğer Şuayb’a uyarsanız, o takdirde mutlaka siz zarar edenler olursunuz.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 91, 'Derken, onları o korkunç sarsıntı yakaladı da yurtlarında yüzüstü hareketsiz çöke kaldılar.');
INSERT INTO verses (sura, aya, text) VALUES (7, 92, 'Şuayb’ı yalanlayanlar sanki orada hiç yaşamamışlardı. Şuayb’ı yalanlayanlar var ya, asıl ziyana uğrayanlar onlar oldu.');
INSERT INTO verses (sura, aya, text) VALUES (7, 93, '(Şuayb) onlardan yüz çevirdi ve dedi ki: "Ey kavmim! Size Rabbimin gönderdiklerini açıklamış ve size nasihat etmiştim. Şimdi kâfir bir kavme karşı nasıl üzülebilirim."');
INSERT INTO verses (sura, aya, text) VALUES (7, 94, 'Biz, hangi memlekete bir peygamber gönderdiysek, yalvarıp yakarsınlar diye mutlaka oranın halkını yoksulluk ve darlığa uğratmışızdır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 95, 'Sonra kötülüğün (sıkıntı ve darlığın) yerine iyiliği (bolluk ve genişliği) getirdik. Nihayet çoğaldılar ve (nankörlük edip): “Atalarımız da darlığa uğramış ve bolluğa kavuşmuşlardı.” dediler. Biz de farkında değillerken onları ansızın yakaladık.');
INSERT INTO verses (sura, aya, text) VALUES (7, 96, 'Eğer (yalanlayan) memleketlerin halkı iman edip, takvalı olsalardı; biz de onlara gökten ve yerden bereketler açardık. Fakat yalanladılar. Bu sebeple onları yapmakta olduklarıyla yakaladık.');
INSERT INTO verses (sura, aya, text) VALUES (7, 97, 'Acaba o ülkelerin halkı, geceleyin uyurlarken azabımızın kendilerine geleceğinden güvende mi oldular?');
INSERT INTO verses (sura, aya, text) VALUES (7, 98, 'Ya da ülkelerin halkı azabımızın güpegündüz onlar eğlencede iken başlarına gelivermesinden güvende mi oldular?');
INSERT INTO verses (sura, aya, text) VALUES (7, 99, 'Allah’ın tuzağından emin mi oldular? Allah’ın tuzağından hüsrana uğramış toplumdan başkası asla emin olmaz.');
INSERT INTO verses (sura, aya, text) VALUES (7, 100, 'Önceki sahiplerinden sonra yeryüzüne varis olanlara, hâlâ (şu gerçek) belli olmadı mı? Dilemiş olsaydık onları da, günahları yüzünden felakete uğratır ve kalpleri üzerine mühür basardık; böylece işitmez ve anlamaz duruma gelirlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 101, 'İşte bu sana haberlerini anlattığımız ülkelerdir. Onlara elçilerimiz apaçık delillerle gelmişlerdi de daha önce yalanladıklarına iman etmeye yanaşmadılar. İşte Allah, kâfirlerin kalplerini böyle mühürler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 102, 'Onların çoğunda ahde vefa bulamadık. Aksine onların çoğunu hak yoldan çıkmış fasıklar olarak bulduk.');
INSERT INTO verses (sura, aya, text) VALUES (7, 103, 'Sonra onların ardından Mûsâ’yı, apaçık mucizelerimizle Firavun’a ve onun ileri gelen adamlarına peygamber olarak gönderdik de onlara (mucizelere karşı) zalimlik ettiler. Bak, bozguncuların sonu nasıl oldu.');
INSERT INTO verses (sura, aya, text) VALUES (7, 104, 'Mûsâ dedi ki: “Ey Firavun! Şüphesiz ki ben âlemlerin Rabbi tarafından gönderilmiş bir peygamberim.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 105, 'Bana yaraşan, Allah hakkında gerçek olandan başkasını söylememektir. Size Rabbinizden apaçık delillerle geldim. Artık İsrailoğulları''nı benimle beraber gönder.');
INSERT INTO verses (sura, aya, text) VALUES (7, 106, '“Eğer sen bir ayet ile gelmişsen ve eğer doğru söyleyenlerden isen haydi onu göster!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 107, 'Bunun üzerine asâsını (yere) bıraktı. (Asâ) hemen apaçık bir ejderha oluverdi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 108, 'Elini çıkardı. Ne görsünler! O bakanlara bembeyaz parlıyordu.');
INSERT INTO verses (sura, aya, text) VALUES (7, 109, 'Firavun’un kavminden ileri gelenler, dediler ki: “Şüphesiz bu adam gayet bilgin bir sihirbazdır.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 110, '“Sizi yurdunuzdan çıkarmak istiyor.” (Firavun sordu): “O halde ne buyurursunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (7, 111, 'Onu ve kardeşini şimdilik beklet ve şehirlere (görevli) toplayıcılar gönder.');
INSERT INTO verses (sura, aya, text) VALUES (7, 112, '“Sana ne kadar bilgin sihirbaz varsa hepsini getirsinler.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 113, 'Sihirbazlar Firavun’a gelerek dediler ki: "Eğer biz galip gelirsek bir mükâfat var, değil mi?"');
INSERT INTO verses (sura, aya, text) VALUES (7, 114, '"Evet! Elbette siz bana yakın kimselerden olacaksınız." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 115, 'Sihirbazlar: "Ey Mûsâ! (Asanı) önce ya sen at ya da önce atanlar biz olalım." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 116, 'O da: "Siz atın!" dedi. Onlar atınca, insanların gözlerini büyülediler, onları korkuttular ve büyük bir sihir gösterdiler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 117, 'Biz de Mûsâ''ya asanı at diye vahyettik. Birdenbire asâ onların uydurduklarını yuttu.');
INSERT INTO verses (sura, aya, text) VALUES (7, 118, 'Böylece hak yerini buldu ve onların yapmış oldukları şeylerin hepsi boşa çıktı.');
INSERT INTO verses (sura, aya, text) VALUES (7, 119, 'Orada mağlup oldular ve küçük düştüler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 120, 'Sihirbazlar hep birden secdeye kapandılar.');
INSERT INTO verses (sura, aya, text) VALUES (7, 121, '"Âlemlerin Rabbine iman ettik." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 122, 'Mûsâ''nın ve Hârûn’un Rabbine!');
INSERT INTO verses (sura, aya, text) VALUES (7, 123, 'Firavun, onlara şöyle dedi: "Ben size izin vermeden önce, ona iman mı ettiniz? Bu kesin bir tuzaktır. Halkı şehirden çıkarmak için, bu tuzağı kurdunuz. Artık yakında bileceksiniz."');
INSERT INTO verses (sura, aya, text) VALUES (7, 124, '“Hiç şüphesiz ellerinizi ayaklarınızı çaprazlama keseceğim ve sonra da hepinizi asacağım.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 125, '"Şüphesiz biz, Rabbimize döneceğiz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 126, '"Sen, Rabbimizin ayetleri bize geldiğinde ona iman ettiğimiz için bizden intikam alıyorsun. Rabbimiz! Üzerimize sabır yağdır ve Müslüman olarak canımızı al!" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 127, 'Firavun kavminden ileri gelen kesim: "Mûsâ’yı ve kavmini yeryüzünde bozgunculuk etsinler, seni ve senin ilahlarını terk etsinler diye mi bırakacaksın?" dediler. Firavun: "Onların erkek çocuklarını öldürürüz. Kadınlarını da sağ bırakırız. Biz, onlar üzerinde tam bir hakimiyet sahibiyiz." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 128, 'Mûsâ kavmine: “Allah’tan yardım dileyin ve sabredin. Şüphesiz ki yeryüzü Allah’ındır, kullarından dilediğine onu miras verir. İyi akıbet ise, takvâ sahiplerinin olacaktır.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 129, 'Onlar: “Sen bize gelmezden evvel de geldikten sonra da işkenceye uğratıldık.” dediler. Dedi ki: “Rabbinizin düşmanlarınızı yok etmesi, yeryüzünde sizi onların yerine geçirmesi ve böylece nasıl amel edeceğinize bakması umulur” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 130, 'Firavun hanedanını belki düşünüp, öğüt alırlar diye kuraklık ve yıllarca ürünlerini eksiltmekle cezalandırdık.');
INSERT INTO verses (sura, aya, text) VALUES (7, 131, 'Onlara bir iyilik geldiği zaman; “Bu bizim hakkımızdır” derler. Onlara bir kötülük dokunduğu zaman onu Mûsâ ve onun yanındakilerin uğursuzluğuna verirlerdi. Dikkat edin! Onların başına gelen uğursuzlukları sadece Allah katındandır. Fakat onların çoğu bilmiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (7, 132, 'Ve dediler ki: “Bizi büyülemek için her ne mûcize getirirsen sana asla iman edecek değiliz.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 133, 'Biz de onlara ayrı ayrı ayetler (mûcizeler) olmak üzere başlarına tûfân, çekirge, haşarât/ürün güvesi, kurbağalar ve kan gönderdik. Fakat yine büyüklük tasladılar. Onlar günahkâr bir topluluk idiler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 134, 'Üzerlerine azap çökünce: “Ey Mûsâ! Sana olan ahdi adına bizim için Rabbine dua et. Şâyet bu azabı bizden kaldırırsan, andolsun sana iman edeceğiz ve İsrailoğullarını da mutlaka seninle birlikte göndereceğiz” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 135, 'Biz kendisine erişecekleri bir süreye kadar üzerlerinden azabı giderince, bir de bakarsın ki onlar ahitlerini bozmuşlar bile.');
INSERT INTO verses (sura, aya, text) VALUES (7, 136, 'Bu yüzden onlardan intikam aldık. Ayetlerimizi yalanlamaları ve onları umursamamaları sebebiyle kendilerini denizde boğduk.');
INSERT INTO verses (sura, aya, text) VALUES (7, 137, 'Hor görülüp ezilmekte olan kavmi (İsrailoğulları''nı), toprağına bolluk ve bereket verdiğimiz yerin (Şam bölgesinin) doğu ve batı taraflarına mirasçı kıldık. İsrailoğulları’nın sabretmelerine karşılık olarak Rabbinin güzel sözü/vaadi gerçekleşti. Firavun ve kavminin yaptıklarını ve kurup yükselttikleri şeyleri yerle bir ettik.');
INSERT INTO verses (sura, aya, text) VALUES (7, 138, 'İsrailoğulları''nı denizden geçirmiştik. Kendilerine ait bir takım putlarına ibadet edip, duran bir topluluğa rastgeldiler. "Ey Mûsâ! Bunların ilahları gibi bize de bir ilah yapsana!" dediler. Mûsâ da onlara: "Şüphesiz, cahillik eden bir toplumsunuz!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 139, 'Şüphesiz bunların içinde bulundukları (şirk) helâke mahkûmdur ve yapmakta oldukları batıldır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 140, '"O, sizi âlemlere üstün kılmış iken size Allah’tan başka bir ilah mı arayayım?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 141, 'Hani size azabın en kötüsünü tattıran, yeni doğan oğullarınızı öldüren ve kızlarınızı hayatta sağ bırakan Firavun ailesinden sizi kurtarmıştık ve bunda sizin için Rabbiniz tarafından büyük bir imtihan vardı.');
INSERT INTO verses (sura, aya, text) VALUES (7, 142, 'Mûsâ’ya otuz gece sözleştik, buna on (gece) daha kattık. Böylece Rabbinin belirlediği vakit kırk geceye tamamlandı. Mûsâ, kardeşi Hârûn’a: “Kavmim arasında benim yerime geç ve ıslah et. Sakın bozguncuların yoluna uyma!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 143, 'Mûsâ, belirlediğimiz vakitte gelince Rabbi onunla konuştu. Mûsâ dedi ki: "Rabbim! Bana (kendini) göster de sana bakayım!" Rabbi: "Beni göremeyeceksin, fakat dağa bak; dağ yerinde durursa sen de beni göreceksin." dedi. Rabbi dağa tecelli edince onu yerle bir etti. Mûsâ bayılarak yere kapandı. Ayıldığında: "Sen tüm noksanlıklardan münezzehsin, sana tevbe ettim. (Kavmim içinde) Sana iman edenlerin ilkiyim." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 144, '(Allah): “Ey Mûsâ! Risaletlerimle ve kelâmımla seni insanlar üzerine seçkin kıldım. Öyleyse sana verdiğimi al ve şükredenlerden ol” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 145, 'Bir de ona Levhalar’da her şeye ait bir öğüt ve herşeye dair açıklamayı yazdık: "Haydi bunları kuvvetle al. Kavmine de bunları en güzel şekilde tutmalarını emret. Yakında size fasıkların yurdunu göstereceğim."');
INSERT INTO verses (sura, aya, text) VALUES (7, 146, 'Haksız yere yeryüzünde büyüklenen kimseleri ayetlerimizi (anlayıp, ibret almaktan) uzak tutacağım. Onlar bütün ayetleri görseler de iman etmezler. Doğru yolu görseler onu yol edinmezler. Sapıklık yolunu gördüklerinde onu yol edinirler. İşte bu, onların ayetlerimizi yalanlamaları ve onlardan gafil olmalarından dolayıdır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 147, 'Ayetlerimizi ve ahiret buluşmasını yalanlayanların amelleri boşa gitmiştir. Onlar (dünyada) yaptıklarından başkasıyla mı cezalandırılacaklardı?');
INSERT INTO verses (sura, aya, text) VALUES (7, 148, 'Mûsâ ’nın kavmi, onun ardından süs eşyalarından (yapılmış) böğüren bir buzağı heykelini ilah edindiler. Onun kendileriyle konuşmadığını ve onlara bir yol göstermediğini görmüyorlar mı? Onu (ilah) edindiler ve böylece zalimlerden oldular.');
INSERT INTO verses (sura, aya, text) VALUES (7, 149, 'Pişman olup da kendilerinin gerçekten sapmış olduklarını görünce: "Eğer Rabbimiz, bize merhamet etmez ise ve bizi bağışlamazsa hüsrana uğrayanlardan oluruz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 150, 'Mûsâ kavmine kızgın ve üzgün olarak dönünce: "Benim ardımdan ne kötü işler yaptınız. Rabbinizin emrini beklemeyip acele mi ettiniz?" dedi. Levhaları (öfkesinden) attı ve kardeşinin başını tutarak kendisine çekti. (Kardeşi): "Ey anamın oğlu! Toplum beni güçsüz gördü/küçümsedi, neredeyse beni öldürüyorlardı. Bana düşmanları sevindirecek şekilde davranma, zalim toplumla bir tutma!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 151, '“Rabbim! Beni de kardeşimi de bağışla! Bizi rahmetine al. Sen rahmet edenlerin en merhametlisisin!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 152, 'Şüphesiz buzağıyı (ilah) edinenlere Rabblerinden bir gazab, dünya hayatında da bir aşağılanma erişecektir. Biz iftira edenleri işte böyle cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 153, 'O kötü amelleri işleyip de ardından tevbekâr olarak iman edenlere gelince şüphe yok ki, Rabbin ondan (tövbeden) sonra elbette çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 154, 'Mûsâ ’nın öfkesi yatışınca levhaları aldı. Onlardaki yazıda Rabblerinden korkanlara hidayet ve rahmet vardı.');
INSERT INTO verses (sura, aya, text) VALUES (7, 155, 'Mûsâ belirlediğimiz vakit için kavminden yetmiş adam seçti. Onları kuvvetli bir sarsıntı alınca, Mûsâ: "Rabbim! Eğer dileseydin onları ve beni daha önce helâk ederdin. İçimizdeki sefih/akılsızların yaptıkları yüzünden bizi helâk mı edeceksin? Bu senin imtihanından başka bir şey değildir. Sen, onunla dilediğini sapıttırır ve dilediğine de hidayet edersin. Sen bizim velimizsin. Bizi affet, bize merhamet et! Sen bağışlayanların en hayırlısısın!"');
INSERT INTO verses (sura, aya, text) VALUES (7, 156, 'Bize bu dünyada ve ahirette iyilik yaz; biz sana (tevbe ile) yöneldik. Allah: "Azabıma dilediğimi uğratırım. Rahmetim ise her şeyi kuşatmıştır. Rahmetimi takvalı olanlara, zekât verenlere ve ayetlerimize iman etmiş olanlara yazacağım." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (7, 157, 'Onlar ki, yanlarında bulunan Tevrat ve İncil''de yazılı buldukları ümmî Peygambere, Rasûle tâbi olurlar. (O peygamber) onlara iyiliği emreder ve kötülüklerden nehyeder, temiz şeyleri helal, pis şeyleri haram kılar. Üzerlerindeki ağır yükleri ve zorlukları kaldırır. Ona iman edenler, onu destekleyip yardım eden ve onunla indirilen nura uyanlar, işte onlar kurtuluşa erenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 158, 'De ki: “Ey insanlar! Şüphesiz ben göklerin ve yerin mülkü (ve hakimiyeti) kendisinin olan, kendisinden başka hiçbir (hak) ilah bulunmayan, hem dirilten, hem öldüren, Allah’ın size, hepinize gönderdiği peygamberiyim. O halde Allah’a ve O’nun sözlerine iman eden ümmî peygamber olan Rasûlüne iman edin ve ona uyun ki, doğru yolu bulmuş olasınız.”');
INSERT INTO verses (sura, aya, text) VALUES (7, 159, 'Mûsâ ’nın kavminden (insanları) hak ile doğru yola ileten ve onunla adaletli davranan bir topluluk da vardı.');
INSERT INTO verses (sura, aya, text) VALUES (7, 160, 'Onları on iki kabileye ayırmıştık. Kavmi Mûsâ ’dan su istediğinde biz ona, “Asânı taşa vur!” diye vahyettik. Oradan on iki kaynak fışkırdı. Her kabile su içeceği yeri öğrendi. Onları bulut ile gölgelendirdik. Onlara kudret helvası ve bıldırcın yedirdik. Size rızık olarak verdiğimiz şeylerin temiz olanlarından yiyin. Biz onlara zulmetmedik, fakat onlar kendilerine zulmettiler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 161, 'Hani: "Şu kasabaya girip, dilediğiniz yerden istediğinizi yiyin. Kapısından secde ederek/ boynu bükük, zelil olarak girin ve; «Bağışla!» deyin de sizi bağışlayalım, ihsan sahipleri için daha fazlasını vereceğiz." denilmişti.');
INSERT INTO verses (sura, aya, text) VALUES (7, 162, 'Fakat zulmedenler kendilerine söylenmiş olan sözü başka bir sözle değiştirdiler. Biz de zalimlere, günah işleyerek yoldan çıktıkları için gökten kahredici bir azap indirmiştik.');
INSERT INTO verses (sura, aya, text) VALUES (7, 163, 'Onlara deniz kenarındaki cumartesi yasağını çiğneyen kasabayı sor! Onlara avları Cumartesi günlerinde (suyun üstünde) akın akın geliyor, başka günlerde gelmiyorlardı. İşte onları fasıklık ettikleri için böyle imtihan ediyorduk.');
INSERT INTO verses (sura, aya, text) VALUES (7, 164, 'Onlardan bir topluluk şöyle diyordu: "Allah’ın helâk edeceği ve şiddetli bir ceza ile cezalandıracağı topluma niye öğüt veriyorsunuz?" Onlar da: "Rabbinize karşı bir mazeret beyan edelim diye bir de belki sakınırlar/takvalı olurlar diye öğüt veriyoruz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 165, 'Kendilerine hatırlatılanı unuttuklarında, kötülükten men edenleri kurtarıp, zalimleri fasıklık yapmaları sebebiyle çok çetin bir ceza ile yakaladık.');
INSERT INTO verses (sura, aya, text) VALUES (7, 166, 'Yasaklandıkları şeylerde diretip ısrar edince onlara: “Aşağılık maymunlar olun!” dedik.');
INSERT INTO verses (sura, aya, text) VALUES (7, 167, 'O vakit Rabbin onlara; Kıyamet gününe kadar üzerlerine mutlaka kendilerini en kötü azaba uğratacak kimseler göndereceğini bildirdi. Rabbinin ceza vermesi çok hızlıdır. Şüphesiz O; çokça bağışlayan, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 168, 'Onları yeryüzünde (parça parça) topluluklara böldük. Onların içinde salih olanlar da vardır aşağı (derecelerde) olanlar da! Onları belki dönerler diye iyilik ve kötülükle imtihan ederiz.');
INSERT INTO verses (sura, aya, text) VALUES (7, 169, 'Onlardan sonra arkalarından kötü kimseler gelip yerlerine geçti. Kitaba da mirasçı oldular. Biz nasıl olsa bağışlanacağız diyerek, bu dünyanın geçici menfaatini alıyorlardı. Yine onlara, ona benzer bir menfaat daha gelse onu da alıyorlardı. Allah hakkında, gerçek dışında bir şey söylemeyeceklerine dair onlardan kitapta söz alınmamış mıydı? Ve onlar kitaptakini okuyup öğrenmemişler miydi? Takva sahipleri için ahiret yurdu çok hayırlıdır. Akletmiyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (7, 170, 'Kitaba sımsıkı sarılanlara ve namazı dosdoğru kılanlara gelince, şüphesiz biz ıslah edenlerin mükâfatını boşa çıkarmayız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 171, 'Hani dağı sanki bir gölgelikmiş gibi onların üstüne kaldırmıştık da üzerlerine düşecek sanmışlardı. (Onlara:) “Size verdiğimiz kitaba sımsıkı sarılın ve onun içindekileri hatırlayın ki, Allah’a karşı gelmekten sakınasınız.” demiştik.');
INSERT INTO verses (sura, aya, text) VALUES (7, 172, 'Hani Rabbin (ezelde) Âdemoğullarının sulplerinden zürriyetlerini almış, onları kendilerine karşı şahit tutarak: “Ben sizin Rabbiniz değil miyim?” demişti. Onlar da: “Evet, şahit olduk (ki Rabbimizsin)” demişlerdi. Böyle yapmamız kıyamet günü: “Biz bundan habersizdik” dememeniz içindir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 173, 'Ya da bizim atalarımız önceden şirk koşmuşlar. Biz de onlardan sonra gelen bir nesiliz. Batıla düşenlerin yaptıklarından dolayı bizi helâk mi edeceksin? demeyesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (7, 174, 'İşte biz ayetleri böyle açıklarız. Belki (tevhide) dönerler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 175, 'Sen onlara kendisine ayetlerimizi verdiğimiz halde onlardan sıyrılıp çıkmış, derken Şeytan''ın takibine uğrayan ve sonunda azgınlardan olmuş kimsenin haberini oku!');
INSERT INTO verses (sura, aya, text) VALUES (7, 176, 'Dileseydik onu ayetlerimizle yükseltirdik. Fakat o dünyaya saplanıp, kaldı, hevesine uydu. Onun misali, üzerine yürüsen de kendi haline bıraksan da dilini çıkartıp soluyan köpeğe benzer. Ayetlerimizi yalanlayan kavmin misali budur. Kıssayı anlat, belki düşünürler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 177, 'Ayetlerimizi yalanlayan ve kendi nefislerine zulmetmiş olan kavmin durumu ne kötüdür!');
INSERT INTO verses (sura, aya, text) VALUES (7, 178, 'Allah kime hidayet verirse o doğru yolu bulmuş olur. Kimi de saptırırsa onlar hüsrana uğrayanların ta kendileridirler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 179, 'Andolsun, biz cinler ve insanlardan birçoğunu Cehennem için yaratmışızdır. Çünkü onların kalpleri vardır ama kavrayıp anlamazlar. Gözleri vardır, onunla görmezler; kulakları vardır, onunla işitmezler. Onlar hayvanlar gibidir, hatta onlardan daha şaşkındırlar.');
INSERT INTO verses (sura, aya, text) VALUES (7, 180, 'En güzel isimler Allah’ındır. O halde O’na bunlarla dua edin. O’nun isimlerinde eğriliğe sapanları terk edin. Onlar yapmakta olduklarının cezasını göreceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 181, 'Yarattıklarımızdan öyle bir ümmet vardır ki, hakla yol gösterirler ve onunla adaletle hükmederler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 182, 'Ayetlerimizi yalanlayanları ise yavaş yavaş bilmedikleri bir yerden (helâka) yaklaştıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 183, 'Ben onlara mühlet veririm. Muhakkak ki benim tuzağım pek çetindir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 184, 'Onlar düşünmediler mi ki arkadaşlarında (Peygamber’de) delilikten bir eser yoktur. O, ancak apaçık bir uyarıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 185, 'Onlar göklerin ve yerin hükümranlığını, Allah’ın yarattığı her şeyi, ecellerinin yaklaşmış olabileceğini görüp düşünmüyorlar mı? Bundan sonra hangi söze iman edecekler?');
INSERT INTO verses (sura, aya, text) VALUES (7, 186, 'Allah kimi saptırırsa, ona hidayet edecek yoktur. Onları azgınlıkları içerisinde şaşkın bir halde bırakır.');
INSERT INTO verses (sura, aya, text) VALUES (7, 187, 'Sana (kıyamet) saatinin ne zaman kopacağını soruyorlar. De ki: "Onun bilgisi Rabbimin katındadır. Onun vaktini O’ndan başkası açığa çıkaramaz. Göklere ve yere o saat ağır gelir. Kıyamet ansızın gelir. Sanki sen onu biliyormuşsun gibi sana soruyorlar." De ki: "Onun ilmi sadece Allah katındadır. Ama insanların çoğu (bunu) bilmezler."');
INSERT INTO verses (sura, aya, text) VALUES (7, 188, 'De ki: “Ben kendim için Allah’ın (benim hakkımda) dilediğinden başka ne bir fayda sağlayabilirim, ne de bir zarar. Eğer ben gaybı bilseydim, hayır yapmayı arttırırdım ve bana bir kötülük de dokunmazdı. Ben sadece iman eden bir toplum için uyarıcı ve müjdeciyim.');
INSERT INTO verses (sura, aya, text) VALUES (7, 189, 'Allah, sizi bir tek nefisten yaratan ve kendisi ile huzur bulsun diye eşini de ondan var edendir. (İnsan) eşiyle birleşince eşi hafif bir yük yüklenir (gebe kalır) ve (bir müddet) onu taşır. Gebeliği ağırlaşınca her ikisi de Rableri Allah’a: “Eğer salih bir çocuk verirsen, elbette şükredenlerden olacağız.” diye dua ederler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 190, 'Allah onlara salih/kusursuz bir evlat verince, kendilerine verdiği şey hakkında Allah''a ortaklar koştular. Allah, onların ortak koştukları şeylerden yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 191, 'Kendileri yaratılmış oldukları halde hiçbir şey yaratmaya kudreti olmayan şeyleri (Allah''a) ortak mı koşuyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (7, 192, 'Hâlbuki ortak koştukları şeyler ne onlara yardımda bulunabilir ne de bizzat kendilerine yardım edebilirler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 193, 'Onları doğru yola çağırsanız, size uymazlar. Onları çağırsanız da sussanız da sizin için birdir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 194, 'Allah’ı bırakıp da dua/ibadet ettikleriniz sizin gibi kullardır. Eğer doğru söyleyenlerseniz, onlara dua edin de size cevap versinler!');
INSERT INTO verses (sura, aya, text) VALUES (7, 195, 'Onların yürüyecek ayakları mı var? Yahut tutacak elleri mi var? Veya görecek gözleri mi var ya da işitecek kulakları mı var? De ki: “Haydi, çağırın ortaklarınızı, sonra bana tuzak kurun da bana göz açtırmayın bakalım!”');
INSERT INTO verses (sura, aya, text) VALUES (7, 196, 'Çünkü benim velim, kitabı (Kur’an’ı) indiren Allah’tır. O, bütün salih kulları koruyup, yardım eder.');
INSERT INTO verses (sura, aya, text) VALUES (7, 197, 'O’ndan başka dua/ibadet ettikleriniz ne size yardımda bulunabilir ne de bizzat kendilerine yardım edebilirler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 198, 'Onları doğru yola çağırsanız sizi işitmezler. Onları sana bakar görürsün fakat onlar görmezler.');
INSERT INTO verses (sura, aya, text) VALUES (7, 199, 'Af yolunu tut, iyiliği emret, cahillerden de yüz çevir!');
INSERT INTO verses (sura, aya, text) VALUES (7, 200, 'Şeytan''dan sana bir vesvese gelirse, hemen Allah’a sığın. Allah her şeyi işitendir. Her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (7, 201, 'Takvâ sahiplerine şeytandan bir vesvese geldiğinde iyice düşünürler. Bakarsın ki onlar görüp bilmişler bile.');
INSERT INTO verses (sura, aya, text) VALUES (7, 202, '(Şeytanların) dostlarına gelince, şeytanlar onları azgınlığa sürüklerler. Sonra da yakalarını bırakmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (7, 203, 'Onlara bir ayet getirmediğin zaman: "Kendin bir ayet uydursaydın ya!" derler. De ki: "Ben, ancak Rabbimden bana vahyolunana uyarım. Bu, Rabbinizden gelen açık delillerdir. İman eden bir toplum için hidayet ve rahmettir."');
INSERT INTO verses (sura, aya, text) VALUES (7, 204, 'Kur’an okunduğu zaman ona kulak verip dinleyin ve susun ki, merhamet olunasınız.');
INSERT INTO verses (sura, aya, text) VALUES (7, 205, 'Rabbini, içinden yalvararak ve korkarak, yüksek olmayan bir sesle sabah-akşam zikret ve gafillerden olma!');
INSERT INTO verses (sura, aya, text) VALUES (7, 206, 'Doğrusu Rabbinin katında olanlar, O''na ibadet etmekten büyüklenmezler, O''nu tenzih ederler ve yalnız O''na secde ederler');
INSERT INTO verses (sura, aya, text) VALUES (8, 1, 'Sana Enfâl''i soruyorlar. De ki: Enfâl Allah’ın ve Rasûl’ündür. Allah’tan sakının (takvalı olun), aranızı düzeltin. Eğer Mümin iseniz Allah’a ve Rasûlüne itaat ediniz."');
INSERT INTO verses (sura, aya, text) VALUES (8, 2, 'Gerçek Müminler ancak o kimselerdir ki; Allah anıldığı zaman kalpleri titrer, ayetleri okunduğu zaman (bu), onların imanını artırır ve onlar ancak Rablerine tevekkül eden kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 3, 'Onlar namazlarını dosdoğru kılarlar, kendilerine rızık olarak verdiğimizden de Allah yolunda harcarlar.');
INSERT INTO verses (sura, aya, text) VALUES (8, 4, 'İşte onlar gerçek Müminlerin ta kendileridir. Onlar için Rableri katında dereceler, mağfiret ve cömert bir rızık vardır.');
INSERT INTO verses (sura, aya, text) VALUES (8, 5, 'Nitekim Rabbin, seni hak uğrunda evinden çıkardığında gerçekten Müminlerden bir kesim isteksizdiler.');
INSERT INTO verses (sura, aya, text) VALUES (8, 6, 'Gerçek apaçık ortaya çıktıktan sonra bile, sanki göz göre göre ölüme sürükleniyorlarmış gibi seninle bu hususta tartışıyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (8, 7, 'Hani Allah, size iki taifeden (ordu ya da kervandan) birini, o sizindir diye vadediyordu. Siz de güçsüz olanın (kervanın) sizin olmasını istiyordunuz. Oysa Allah, kelimeleriyle hakkı/İslamı yüceltmek, kâfirlerin ardını/kökünü kesmek istiyordu.');
INSERT INTO verses (sura, aya, text) VALUES (8, 8, 'Bu, günahkârların hoşuna gitmese de hakkı (İslamı) yüceltmek ve batılı da ortadan kaldırmak içindir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 9, 'Hani siz Rabbinizden imdat istiyordunuz da: “Muhakkak Ben size birbiri ardınca bin melek ile yardım ediyorum” diye duanıza karşılık vermişti.');
INSERT INTO verses (sura, aya, text) VALUES (8, 10, 'Allah, bunu yanlızca bir müjde olması ve kalplerinizin yatışması için yaptı. Yardım yalnızca Allah katındandır. Şüphe yok ki Allah mutlak galiptir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 11, 'Hani (Allah) kendi tarafından bir güvenlik olarak sizi hafif bir uykuya daldırıyor; sizi temizlemek, sizden Şeytan''ın vesvesesini gidermek, kalplerinizi pekiştirmek ve ayaklarınızı sağlam bastırmak için üzerinize gökten yağmur yağdırıyordu.');
INSERT INTO verses (sura, aya, text) VALUES (8, 12, 'O an Rabbin meleklere şöyle vahyediyordu: "Ben sizinle beraberim, iman edenlere sebat verin! Ben kâfirlerin kalbine korku salacağım. Artık onların boyunlarının üstüne de vurun, onların her parmağına da vurun.”');
INSERT INTO verses (sura, aya, text) VALUES (8, 13, 'Bu, onların Allah’a ve Rasûlüne karşı gelmelerindendir. Her kim de Allah’a ve Rasûlüne karşı gelirse; bilsin ki Allah’ın cezası şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 14, 'İşte bu sizin; tadın bunu. (Ahirette) kâfirler için bir de Cehennem azabı vardır.');
INSERT INTO verses (sura, aya, text) VALUES (8, 15, 'Ey iman edenler, (savaş için) toplu bir halde kâfirlerle karşılaştığınız zaman, onlara arkanızı dönüp kaçmayın.');
INSERT INTO verses (sura, aya, text) VALUES (8, 16, '-Savaş taktiği olarak düşmanı vurmak için çekilme ya da diğer bir birliğe katılmak durumu hariç- böyle bir günde her kim onlara arkasını dönerse; mutlaka o, Allah’ın gazabına uğramış olur. Onun varacağı yer de Cehennem''dir. Ne kötü varılacak yerdir orası!');
INSERT INTO verses (sura, aya, text) VALUES (8, 17, '(Bedir''de) onları siz öldürmediniz, fakat onları Allah öldürdü. Attığında da sen atmadın, fakat Allah attı. Müminleri güzel bir imtihanla denemek için (böyle yaptı). Şüphesiz Allah her şeyi işitendir, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 18, 'İşte durum bu. Bir de Allah, kâfirlerin tuzağını zayıf düşürendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 19, '(Ey kâfirler!) Fetih istiyorsanız, işte size fetih gelmiştir. Eğer (küfrünüze ve savaşa) son verirseniz bu sizin için daha hayırlıdır. Ve eğer tekrar dönerseniz biz de döneriz. Topluluğunuz kalabalık olsa bile size bir fayda vermeyecektir. Çünkü Allah, Müminlerle beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 20, 'Ey iman edenler! Allah’a ve Rasûlüne itaat edin! İşitip durduğunuz halde ondan yüz çevirmeyin!');
INSERT INTO verses (sura, aya, text) VALUES (8, 21, 'Dinlemedikleri halde; “İşittik” diyenler gibi de olmayın!');
INSERT INTO verses (sura, aya, text) VALUES (8, 22, 'Allah katında canlıların en kötüsü (hakka karşı) sağır ve dilsiz kimselerdir ki, onlar akletmezler.');
INSERT INTO verses (sura, aya, text) VALUES (8, 23, 'Allah, onlarda bir hayır olduğunu bilseydi; elbette onlara işittirirdi. Onlara işittirseydi, onlar yine de yüz çevirerek dönerlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (8, 24, 'Ey iman edenler! Sizi, size hayat verecek şeylere çağırdığı zaman Allah ve Rasûlü’nün çağrısına uyun ve bilin ki Allah, kişi ile kalbi arasına girer. Yine bilin ki, O’nun huzurunda toplanacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (8, 25, 'İçinizden sadece zalimlere dokunmakla kalmayacak olan bir fitneden de sakının. Allah’ın azabının çok şiddetli olduğunu bilin!');
INSERT INTO verses (sura, aya, text) VALUES (8, 26, 'O vakti hatırlayın ki siz yeryüzünde güçsüz ve zayıf idiniz. İnsanların sizi kapıp götürmesinden korkuyordunuz. Derken Allah sizi barındırdı, yardımıyla destekledi ve sizi temiz şeylerden rızıklandırdı ki şükredesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (8, 27, 'Ey iman edenler! Allah’a ve Peygamber’e hainlik etmeyin; (sonra) bile bile kendi emanetlerinize hainlik etmiş olursunuz.');
INSERT INTO verses (sura, aya, text) VALUES (8, 28, 'Biliniz ki mallarınız ve çocuklarınız bir imtihandır. Allah katında ise büyük mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (8, 29, 'Ey iman edenler! Eğer Allah’tan sakınırsanız. O size iyiyi kötüden ayıracak bir anlayış verir. Ve sizin günahlarınızı örter, sizi bağışlar. Allah son derece büyük lütuf sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 30, 'Hani o kâfirler seni tutup bağlamak yahut öldürmek yahut seni (Mekke’den) çıkarmak için sana tuzak kuruyorlardı. Onlar bu tuzağı kurarlarken Allah da bunun karşılığında kendilerine tuzak kuruyordu. Allah, tuzak kuranların en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (8, 31, 'Onlara ayetlerimiz okunduğu zaman: “İşittik, eğer dilersek biz de bunun benzerini elbette söylerdik. Bu, eskilerin masallarından başka bir şey değildir” demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (8, 32, 'Hani onlar: “Ey Allah’ım! Eğer bu senin katından gelen bir hak ise başımıza gökten taş yağdır, yahut bize acı bir azap ver!” demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (8, 33, 'Oysa sen onların içinde iken, Allah onlara azap edecek değildir. Onlar istiğfar edip dururken de Allah onları azablandıracak değildir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 34, 'Onlar Mescid-i Haram’dan (Müminleri) men ederken, Allah onlara ne diye azap etmesin ki! Üstelik onlar Allah''ın evliyaları da değiller. Allah''ın evliyaları yalnızca muttakilerdir. Fakat onların çokları bunu bilmez.');
INSERT INTO verses (sura, aya, text) VALUES (8, 35, 'Onların Kâbe’deki namazları, ıslık çalmak ve el çırpmaktan başka bir şey değildir. Öyleyse küfrünüzden dolayı tadın azabı!');
INSERT INTO verses (sura, aya, text) VALUES (8, 36, 'Kâfirler, mallarını Allah’ın yolundan alıkoymak için harcarlar. Daha da harcayacaklardır. Sonra bu, onlara bir yürek acısı olacaktır. Sonra da yenilgiye uğrayacaklardır. Kâfir olanlar toplanıp Cehennem''e sürüleceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 37, 'Bu Allah''ın pis olanı temizden ayırması, pis olanları üst üste koyup hepsini yığarak Cehennem''e koyması içindir. İşte onlar, ziyana uğrayanların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 38, 'Kâfir olanlara (küfürlerinden) vazgeçerlerse önceden yaptıklarının bağışlanacağını, tekrar dönerlerse öncekiler hakkında uygulanan ilahi kanunun onlara da uygulanacağını söyle.');
INSERT INTO verses (sura, aya, text) VALUES (8, 39, 'Hiçbir fitne kalmayıncaya ve din bütünüyle Allah’ın oluncaya kadar onlarla savaşın. Eğer vazgeçerlerse, muhakkak Allah ne yaptıklarını iyice görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 40, 'Eğer yüz çevirirlerse bilin ki, Allah sizin mevlanızdır. O ne güzel mevlâ, ne güzel yardımcıdır!');
INSERT INTO verses (sura, aya, text) VALUES (8, 41, 'Eğer Allah’a, Furkân günü (Bedir''de) olan iki ordunun birbirleriyle karşılaştıkları günde kulumuza indirdiğimize iman etmişseniz, bilin ki ganimet olarak aldığınız herhangi bir şeyin beşte biri Allah’a, Râsûlün’e, yakınlarına, yetimlere, yoksullara ve yolculara aittir. Allah her şeye gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 42, 'Hatırlayın ki, (Bedir Savaşı''nda) siz vâdinin yakın kenarında (Medine tarafında) idiniz, onlar da uzak kenarında (Mekke tarafında) idiler. Kervan da sizden daha aşağıda (deniz sahilinde) idi. Eğer (savaş için) sözleşmiş olsaydınız, sözleştiğiniz vakit hususunda ihtilâfa düşerdiniz. Fakat Allah, gerekli olan emri yerine getirmesi, helâk olanın açık bir delille (gözüyle gördükten sonra) helâk olması, yaşayanın da açık bir delille yaşaması için (böyle yaptı). Çünkü Allah hakkıyla işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 43, 'Hani Allah sana onları uykunda az gösteriyordu. Eğer sana onları çok gösterseydi elbette gevşerdiniz ve o iş hakkında birbirinizle çekişirdiniz. Fakat Allah (sizi bunlardan) kurtardı. Çünkü O, göğüslerin özünü (kalplerde olanı) hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 44, 'Hani karşılaştığınız zaman onları gözlerinize az gösteriyor, sizi de onların gözlerinde azaltıyordu ki Allah, olacak bir işi gerçekleştirsin. Bütün işler Allah’a döndürülür.');
INSERT INTO verses (sura, aya, text) VALUES (8, 45, 'Ey iman edenler! (Savaş için) bir toplulukla karşılaştığınız zaman sebat edin ve Allah’ı çok zikredin ki kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (8, 46, 'Allah’a ve Rasûlüne itaat edin; çekişip ayrılığa düşmeyin. Yoksa korkar ve gücünüzü kaybedersiniz. Sabredin! Çünkü Allah sabredenlerle beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 47, 'Şımarıp böbürlenmek, insanlara gösteriş yapmak ve (halkı) Allah yolundan alıkoymak için yurtlarından çıkanlar (Mekke müşrikleri) gibi olmayın. Allah, onların yaptıklarını çepeçevre kuşatandır.');
INSERT INTO verses (sura, aya, text) VALUES (8, 48, 'Hani Şeytan, onlara yaptıklarını süslemiş ve; “Bu gün artık insanlardan size galip gelecek (kimse) yok, mutlaka ben de size yardımcıyım.” demişti. Fakat iki taraf (savaş alanında) yüz yüze gelince (Şeytan), gerisin geriye dönüp; “Ben sizden uzağım. Çünkü ben sizin görmediğiniz şeyler (melekler) görüyorum. Ben Allah’tan korkarım. Allah, cezası çetin olandır.” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (8, 49, 'Hani münafıklar ve kalplerinde hastalık bulunan kimseler; “Bunları, dinleri aldatmış.” diyorlardı. Hâlbuki kim Allah’a tevekkül ederse, hiç şüphesiz Allah mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 50, 'Melekler, kâfirlerin yüzlerine ve ardlarına vura vura ve; “Haydi tadın bakalım ateşin azabını!” diyerek canlarını alırken bir görseydin.');
INSERT INTO verses (sura, aya, text) VALUES (8, 51, '(Ey kâfirler!) Bu, sizin ellerinizin önceden yaptığının karşılığıdır. Yoksa, Allah kullarına zulmedici değildir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 52, 'Firavun hanedanı ve onlardan öncekilerin gidişi/tutumu gibi onlar, Allah’ın ayetlerini inkâr ettiler, Allah da onları günahları sebebiyle yakalayıp yok etti. Allah; güçlüdür, cezası çok şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 53, 'Bunun sebebi şudur: Bir toplum kendilerinde bulunan (iyi davranışlar)ı değiştirmedikçe, Allah onlara verdiği bir nimeti değiştirmez ve şüphesiz Allah hakkıyla işitendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 54, 'Bunların durumu tıpkı Firavun ailesi ve onlardan öncekilerin durumu gibidir. Onlar Rablerinin ayetlerini yalanlamışlar, biz de onları günahları sebebiyle helâk etmiştik ve Firavun ailesini de suda boğmuştuk. Hepsi de zalim kimselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (8, 55, 'Şüphesiz Allah katında, yeryüzünde yürüyen canlıların en kötüsü kâfirlerdir. Artık onlar iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (8, 56, 'Onlar, kendileriyle antlaşma yaptığın, sonra da her defasında anlaşmalarını hiç çekinmeden bozan kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 57, 'Eğer onları savaşta yakalarsan, bunlar(a vereceğin ceza) ile arkalarındakileri de dağıt ki ibret alsınlar.');
INSERT INTO verses (sura, aya, text) VALUES (8, 58, '(Anlaşma yaptığın) bir kavmin hainlik etmesinden korkarsan, sen de anlaşmayı bozduğunu aynı şekilde onlara bildir. Çünkü Allah, hainleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (8, 59, 'Kâfirler, kaçıp-kurtardıklarını zannetmesinler. Onlar asla aciz bırakamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (8, 60, 'Onlara karşı gücünüzün yettiğince kuvvet ve (cihad için) bağlanıp beslenen atlar hazırlayın ki, bunlarla Allah''ın düşmanını, sizin düşmanınızı ve bunlardan ayrı sizin bilmediğiniz ama Allah''ın bildiği daha başkalarını korkutasınız. Allah yolunda her ne harcarsanız karşılığı size tam olarak ödenir. Size zulmedilmez.');
INSERT INTO verses (sura, aya, text) VALUES (8, 61, 'Eğer onlar; barışa yanaşırlarsa, sen de onlara yanaş ve Allah’a tevekkül et. Çünkü O hakkıyla işitendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 62, 'Seni aldatmak isterlerse bil ki, şüphesiz Allah sana yeter. O, seni yardımıyla ve Müminlerle destekleyendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 63, 'Ve (Allah), onların kalplerini birleştirmiştir. Sen yeryüzünde bulunan her şeyi verseydin, yine onların gönüllerini birleştiremezdin, fakat Allah onların aralarını bulup kaynaştırdı. Şüphesiz O Aziz''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 64, 'Ey Peygamber! Sana ve sana uyan Müminlere Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (8, 65, 'Ey Peygamber! Müminleri savaşa teşvik et. Eğer içinizde sabırlı yirmi kişi bulunursa, iki yüz kişiye galip gelirler. Eğer içinizde (sabırlı) yüz kişi bulunursa, kâfirlerden bin kişiye galip gelirler. Çünkü onlar anlamaz bir topluluktur.');
INSERT INTO verses (sura, aya, text) VALUES (8, 66, 'Şimdi Allah yükünüzü hafifletti, zira içinizde zaaf bulunduğunu biliyordu. Eğer içinizde sabırlı yüz kişi olursa iki yüz kişiye galip gelirler. Eğer içinizde (sabırlı) bin kişi olursa, Allah’ın izniyle iki bin kişiye galip gelirler. Allah, sabredenlerle beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 67, 'Yeryüzünde düşmanı tamamıyla sindirip hâkim duruma gelmedikçe, hiçbir peygambere esir almak yakışmaz. Siz geçici dünya menfaatini istiyorsunuz. Hâlbuki Allah ahireti (kazanmanızı) istiyor. Allah; mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 68, 'Eğer Allah’ın daha önce verilmiş bir hükmü olmasaydı, aldığınıza (fidye) karşılık size büyük bir azap dokunurdu.');
INSERT INTO verses (sura, aya, text) VALUES (8, 69, 'Artık elde ettiğiniz ganimetten helâl ve temiz olarak yiyin. Allah’a karşı gelmekten sakının. Şüphesiz Allah; çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 70, 'Ey Peygamber! Elinizdeki esirlere de ki: Eğer Allah, kalplerinizde (iman, ihlâs, iyi niyet gibi) bir hayır (olduğunu) bilirse, sizden alınan fidyeden daha hayırlısını size verir ve sizi bağışlar. Allah; çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 71, 'Eğer sana hainlik etmek isterlerse, (bil ki) onlar daha önce Allah’a da hainlik etmişlerdi de, Allah onlara karşı (sana) imkân (kudret) vermişti. Allah, hakkıyla bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 72, 'İman edip hicret eden ve Allah yolunda mallarıyla, canlarıyla cihad edenler ve (muhacirleri) barındırıp (onlara) yardım edenler var ya, işte onlar birbirlerinin velileridir. İman edip hicret etmeyenlere gelince, hicret edinceye kadar onların velayetleri size ait değildir. Eğer din konusunda sizden yardım isterlerse, sizinle aralarında sözleşme bulunan bir kavme karşı olmadıkça onlara yardım etmeniz gerekir. Allah, yaptıklarınızı hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (8, 73, 'Kâfirler de birbirlerinin velileridir. Eğer siz bunların gereğini yapmazsanız, yeryüzünde bir fitne ve büyük bir fesad olur.');
INSERT INTO verses (sura, aya, text) VALUES (8, 74, 'İman edip hicret eden ve Allah yolunda cihad edenler ve (Muhacirler''i) barındırıp (onlara) yardım edenler var ya; işte onlar gerçek Müminlerdir. Onlar için bir bağışlanma ve bol bir rızık vardır.');
INSERT INTO verses (sura, aya, text) VALUES (8, 75, 'Daha sonra iman edip hicret eden ve sizinle birlikte cihad edenlere gelince, işte onlar da sizdendir. Allah’ın kitabınca, kan akrabaları birbirlerine (varis olmaya) daha lâyıktırlar. Şüphesiz Allah; hakkıyla işitendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 1, 'Allah ve Rasûlünden, kendileriyle anlaşma yapmış olduğunuz müşriklere kesin bir uyarı!');
INSERT INTO verses (sura, aya, text) VALUES (9, 2, 'Yeryüzünde dört ay daha dolaşın. Şunu bilin ki, siz Allah’ı aciz bırakacak değilsiniz. Allah ise, kâfirleri perişan edecektir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 3, 'Hacc-ı ekber gününde, Allah ve Rasûlünden bütün insanlara bir bildiridir: Allah ve Rasûlü, Allah’a ortak koşanlardan uzaktır. Eğer tövbe ederseniz, bu sizin için hayırlıdır. Ama yüz çevirirseniz, şunu iyi bilin ki, siz Allah’ı aciz bırakabilecek değilsiniz. Kâfirlere, elem dolu bir azabı müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (9, 4, 'Ancak Allah’a ortak koşanlardan, kendileriyle anlaşma yapmış olduğunuz, sonra da anlaşmalarında size karşı hiçbir eksiklik yapmamış ve sizin aleyhinize hiç kimseye yardım etmemiş olanlar, bu hükmün dışındadır. Onların anlaşmalarını, süreleri bitinceye kadar tamamlayın. Şüphesiz Allah, kendine karşı gelmekten sakınanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (9, 5, 'Haram aylar çıkınca, Allah’a şirk koşanları artık bulduğunuz yerde öldürün, onları yakalayıp hapsedin ve her gözetleme yerine oturup onları gözetleyin. Eğer tevbe ederler, namazı kılıp zekâtı da verirlerse kendilerini serbest bırakın. Şüphesiz Allah çok bağışlayıcıdır, çok merhamet edicidir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 6, 'Eğer Allah’a ortak koşanlardan biri senden eman/sığınma talebinde bulunursa ona eman ver. Ta ki, Allah’ın kelâmını dinlesin. Sonra onu emin olacağı yere kadar ulaştır. Bu, onların bilmeyen bir kavim olduklarından dolayı böyledir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 7, 'Allah’a ortak koşanların Allah katında ve Rasûlü yanında bir ahdi nasıl olabilir? Ancak Mescid-i Haram’ın yanında kendileriyle anlaşma yaptıklarınız başkadır. Bunlar size karşı doğru davrandığı sürece, siz de onlara doğru davranın. Çünkü Allah, kendine karşı gelmekten sakınanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (9, 8, 'Onların bir ahdi nasıl olabilir ki? Eğer onlar size üstün gelselerdi, sizin hakkınızda ne akrabalık (bağlarını), ne de anlaşma (yükümlülüğünü) gözetirlerdi. Ağızlarıyla sizi hoşnut etmeye çalışıyorlar, oysa kalpleri buna karşı çıkıyor. Onların pek çoğu fasık kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 9, 'Allah’ın ayetlerini az bir bedel karşılığında sattılar ve (insanları) O’nun yolundan alıkoydular. Bunların yapmakta oldukları şeyler gerçekten ne kötüdür!');
INSERT INTO verses (sura, aya, text) VALUES (9, 10, 'Bir Mümin hakkında ne akrabalık (bağlarını), ne de anlaşma (yükümlülüğünü) gözetirler. İşte onlar taşkınlık yapanların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 11, 'Eğer tevbe edip, namazı kılar ve zekâtı verirlerse, artık onlar sizin din kardeşlerinizdir. Bilen bir kavme ayetleri işte böyle ayrı ayrı açıklarız.');
INSERT INTO verses (sura, aya, text) VALUES (9, 12, 'Eğer anlaşmalarından sonra yeminlerini bozar ve dininize dil uzatırlarsa, o zaman küfrün elebaşıları ile savaşın. Çünkü onların yeminleri yoktur/riayet etmezler. Umulur ki (böylece) vazgeçerler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 13, 'Yeminlerini bozan, peygamberi yurdundan çıkarmaya kalkışan ve savaşa evvela kendileri başlayan bir toplumla savaşmayacak mısınız? Yoksa onlardan korkuyor musunuz? Eğer Mümin iseniz kendisinden korkulmaya Allah daha layıktır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 14, 'Onlarla savaşın ki, Allah sizin ellerinizle onlara azap etsin, rezil etsin ve sizi onların üzerlerine galip kılsın, Mümin toplumun gönüllerine şifa versin.');
INSERT INTO verses (sura, aya, text) VALUES (9, 15, 'Kalplerinizdeki öfkeyi gidersin. Allah, dilediğinin tevbesini kabul eder. Allah; Alîm''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 16, 'Allah, içinizden cihad edenleri; Allah’tan, Rasûlünden ve Müminlerden başkasını yakın dost edinmeyenleri ortaya çıkarmadan sizi bırakacak mı sandınız? Allah işlediklerinizin hepsinden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 17, 'Müşrikler, kendilerinin kâfirliğine bizzat şahitlik edip dururlarken Allah’ın mescitlerini imar etmeleri yakışık almaz. Onların yaptıkları işler boşa çıkmıştır. Onlar, Cehennem''de ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 18, 'Allah’ın mescitlerini sadece Allah’a ve ahiret gününe iman eden, namazı ikame eden, zekâtı veren ve ancak Allah’tan başkasından korkmayanlar imar eder. İşte onlar doğru yolda olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 19, 'Hacca gelenlere su vermeyi, Mescid-i Haram’ı imar etmeyi, Allah’a ve ahiret gününe iman edenle ve Allah yolunda cihad edenle denk mi tutuyorsunuz? Allah katında denk değildirler. Allah, zalim olan topluma hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (9, 20, 'İman eden, hicret eden ve Allah yolunda mallarıyla, canlarıyla cihad eden kimselere Allah katında en büyük dereceler vardır. İşte kurtulanlar onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 21, 'Rableri onlara rahmetini, rızasını, onlara içlerinde tükenmez ve ebedî bir naîm (nimet) bulunan cennetleri müjdeler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 22, 'İçlerinde ebedî ve sürekli kalacaklar. Doğrusu Allah katında büyük mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 23, 'Ey İman edenler! Eğer küfrü imana tercih ediyorlarsa, babalarınızı ve kardeşlerinizi veli edinmeyin. Sizden kim onları veli edinirse, işte onlar da zalimlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 24, 'De ki: Babalarınız, oğullarınız, kardeşleriniz, eşleriniz, akrabalarınız, elde ettiğiniz mallar, durgun gitmesinden korktuğunuz ticaret, hoşunuza giden konutlar size Allah’tan, Rasûlünden ve O’nun yolunda cihaddan daha sevimli ise Allah’ın (azap) emri gelene kadar bekleyin! Allah fasık toplumlara hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (9, 25, 'Gerçekten Allah birçok yerde ve Huneyn Savaşı gününde size yardım etmiştir. Hani, çokluğunuz size kendinizi beğendirmiş, fakat (bu çokluk) size hiçbir yarar sağlamamış, yeryüzü bütün genişliğine rağmen size dar gelmişti. Sonra gerisin geri dönüp gitmiştiniz.');
INSERT INTO verses (sura, aya, text) VALUES (9, 26, 'Sonra Allah, Rasûlüne ve Müminlere sükûnet/huzur indirdi ve görmediğiniz ordular indirdi ve kâfirlere azap etti. Kâfirlerin cezası işte budur.');
INSERT INTO verses (sura, aya, text) VALUES (9, 27, 'Allah, bundan sonra da dilediğinin tevbesini kabul eder. Allah çokça bağışlayan, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 28, 'Ey İman edenler! Doğrusu müşrikler necistir. Bu sebeple bu yıldan sonra Mescid-i Haram’a yaklaşmasınlar. Eğer fakirlikten korkuyorsanız, dilerse Allah sizi ihsanı ile zengin kılacaktır. Şüphesiz Allah Alîm''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 29, 'Kitap verilenlerden, Allah’a ve ahiret gününe iman etmeyen, Allah’ın ve Rasûlü''nün haram kıldığı şeyleri haram kılmayıp hak dini din edinmeyenlerle küçülerek/boyunlarını büküp elleriyle cizye verene kadar savaşın!');
INSERT INTO verses (sura, aya, text) VALUES (9, 30, 'Yahudiler: "Uzeyir Allah’ın oğludur." dediler. Hristiyanlar da "Mesih Allah’ın oğludur." dediler. Bu, daha önce kâfir olanların sözlerine benzeterek onların ağızlarıyla söyledikleri (uydurma) sözleridir. Allah onları kahretsin, nasıl da (haktan) çevriliyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 31, 'Onlar, Allah ile birlikte alimlerini, rahiplerini ve Meryem oğlu Mesih’i de rabler edindiler. Oysa tek ilahtan başkasına ibadet etmemekle emrolunmuşlardı. Ondan başka (hak) ilah yoktur. Allah, onların koştuğu şirkten münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 32, 'Allah’ın nurunu ağızlarıyla söndürmek isterler. Kâfirler istemese de Allah nurunu muhakkak tamamlayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 33, 'O (Allah), müşrikler hoşlanmasalar da (kendi) dinini bütün dinlere üstün kılmak için Rasûlünü hidayet ve hak din ile gönderendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 34, 'Ey İman edenler! Hahamlar ve rahiplerin çoğu, insanların mallarını haksız olarak yerler ve Allah’ın yolundan alıkorlar. Altın ve gümüşü biriktirip de Allah yolunda harcamayanlara acıklı bir azap ile müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (9, 35, 'Bunlar Cehennem ateşinde kızdırıldığı gün, alınları, böğürleri ve sırtları onlarla dağlanacak; "Bu kendiniz için biriktirdiğinizdir. Biriktirdiğinizi tadın!" denecektir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 36, 'Gökleri ve yeri yarattığı günde Allah''ın (Levh-i Mahfuz''daki) yazısında Allah katında ayların sayısı on ikidir. Bunlardan dördü haram aylardır. Bu dosdoğru bir dindir. O aylarda kendinize zulmetmeyin. Fakat sizinle topyekün savaşan müşriklerle de topyekün savaşın! Bilin ki Allah muttakilerle beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 37, 'Haram ayları başka aylara ertelemek küfürde ileri gitmektir. Bununla kâfir olanlar saptırılırlar. Allah’ın haram kıldığı ayların sayısına denk getirmek için onu bir yıl helâl bir yıl haram sayıyorlar. Böylece Allah’ın haram kıldığını helâl kılıyorlar. Kötü amelleri, kendilerine güzel görünüyor. Allah kâfir toplumlara hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (9, 38, 'Ey İman edenler! Size ne oluyor da; "Allah yolunda savaşa çıkın!" dendiği zaman yere çöküp kaldınız? Ahireti bırakıp dünya hayatına mı razı oldunuz? Oysa dünya hayatının metası ahirete göre pek azdır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 39, 'Eğer savaşa çıkmazsanız, Allah sizi acıklı bir azapla cezalandırır ve yerinize de başka bir toplum getirir. O’na herhangi bir zarar da veremezsiniz. Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (9, 40, 'Eğer siz ona (Rasûlullah''a) yardım etmezseniz, ona Allah yardım etmiştir. Hani, kâfirler onu iki kişiden biri olarak (Ebu Bekir ile birlikte Mekke''den) çıkarmışlardı. O ikisi mağaradaydı. O, arkadaşına: "Üzülme! Çünkü Allah bizimle beraberdir." diyordu. Allah, O’na sükûnet/huzur vermiş ve onu görmediğiniz ordularla desteklemiştir. Kâfirlerin sözünü alçaltmıştır. Allah''ın kelimesi ise, o en yücedir. Allah Aziz''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 41, 'Gerek hafif/kolaylık, gerek ağırlık/zorlukta savaşa çıkın! Mallarınız ve canlarınızla Allah yolunda cihad edin! Eğer bilirseniz bu sizin için çok hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 42, 'Kolay elde edilen kazanç, yakın bir yolculuk olsaydı (Tebuk''ta) sana uyarlardı. Fakat, meşakkat (mesafe) onlara uzak geldi. "Gücümüz yetseydi sizinle beraber çıkardık." diye Allah’a yemin edeceklerdir. Kendilerini helâk ediyorlar. Allah, gerçekten onların yalancı olduğunu biliyor.');
INSERT INTO verses (sura, aya, text) VALUES (9, 43, 'Allah, seni affetsin! Doğru söyleyenler sana iyice belli olup, yalancıları bilinceye kadar beklemeden niçin onlara izin verdin?');
INSERT INTO verses (sura, aya, text) VALUES (9, 44, 'Allah’a ve ahiret gününe iman edenler mallarıyla ve canlarıyla cihad etmek istedikleri için senden izin istemezler. Allah, muttakileri çok iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 45, 'Ancak Allah’a ve ahiret gününe iman etmeyen, kalpleri şüpheye düşüp şüphelerinde bocalayan kimseler senden izin isterler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 46, 'Eğer savaşa çıkmak isteselerdi bir hazırlık yaparlardı. Fakat Allah, onların davranışlarını kerih gördü de onları alıkoydu. "Geride kalanlarla (acizlerle) beraber oturun!" denildi.');
INSERT INTO verses (sura, aya, text) VALUES (9, 47, 'Aranızda savaşa çıkmış olsalardı, size bozgunculuktan başka bir katkıları olmayacak ve sizi fitneye düşürmek için aranızda (koğuculuk yaparak) koşuşturacaklardı. Aranızda onları dinleyecek kişiler de vardı. Allah zalimleri bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 48, '(Münafıklar) Daha önce de fitne koparmak istemişlerdi. Sana karşı bir takım işler çeviriyorlardı. Sonunda hak geldi, onların istememesine rağmen Allah’ın emri üstün oldu.');
INSERT INTO verses (sura, aya, text) VALUES (9, 49, 'Onlardan: "Bana izin ver, beni fitneye düşürme!" diyenler vardır. Bilin ki onlar fitneye düşmüşlerdi. Cehennem ise, o kâfirleri çepeçevre kuşatacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 50, 'Sana bir iyilik gelirse onların fenasına gider. Sana bir musibet gelirse; "Biz önceden işimizi (sağlama) aldık." deyip sevinerek dönüp giderler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 51, 'De ki: Allah’ın bize yazdığından başkası başımıza gelmez. O, bizim mevlamızdır. Müminler Allah’a güvenip, tevekkül etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 52, 'De ki: "Bize iki iyiden (şehadet ya da zaferden) başka bir şeyin gelmesini mi bekliyorsunuz? Oysa biz, Allah’ın kendi katından veya bizim elimizle sizi bir azaba uğratmasını bekliyoruz. Bekleyin siz, biz de sizinle bekleyenleriz!"');
INSERT INTO verses (sura, aya, text) VALUES (9, 53, 'De ki: "İstekli veya isteksiz olarak infak edin, nasıl olsa kabul edilmeyecektir. Siz, şüphesiz fasık bir topluluksunuz."');
INSERT INTO verses (sura, aya, text) VALUES (9, 54, 'Verdiklerinin kabul olunmasına engel olan, Allah ve Rasûlüne (iman etmek yerine) kâfir olmaları, namaza ancak tembel tembel gelmeleri ve infaklarını istemeyerek vermeleridir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 55, 'Artık onların malları da evlatları da seni imrendirmesin. Doğrusu Allah, bunlar yüzünden dünya hayatında onları azaba uğratmayı ve canlarının, kâfirler olarak, güçlükle çıkmasını ister.');
INSERT INTO verses (sura, aya, text) VALUES (9, 56, 'Onlar, sizden olduklarına dair Allah’a yemin ederler. Onlar sizden değillerdir. Aksine onlar korkak bir toplumdur.');
INSERT INTO verses (sura, aya, text) VALUES (9, 57, 'Bir sığınak, mağaralar veya girecek bir yer bulsalar kaçarak oraya yönelirler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 58, 'İçlerinden sadakalar konusunda sana dil uzatanlar da var. Kendilerine ondan bir pay verilirse, hoşnut olurlar; eğer kendilerine ondan bir pay verilmezse hemen kızarlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 59, 'Eğer onlar, Allah ve Rasûlü''nün kendilerine verdiğinden hoşnut olup; "Allah bize yeter, Allah bize bol nimetinden verecektir. Rasûlü de (Allah''ın verdiklerinden verecektir) ve biz gerçekten ancak Allah''a rağbet edenleriz.” deselerdi daha hayırlı olurdu.');
INSERT INTO verses (sura, aya, text) VALUES (9, 60, 'Sadakalar/zekâtlar, Allah’tan bir farz olarak fakirler, miskinler, onu toplayan memurlar, kalpleri (İslam’a) ısındırılanlar, köleler, borçlular, Allah yolunda (cihad edenler) ve yolda kalanlar içindir. Allah Alîm''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 61, 'Onların içinde: "O, bir kulaktır (her duyduğuna inanıyor), diyerek onu üzenler vardır." De ki: "O, sizin için hayrı (dinleyip, inanan) bir kulaktır. Allah''a iman eder, Müminlere inanıp güvenir ve sizden iman edenler için de bir rahmettir. Allah’ın Rasûlünü üzenlere acıklı bir azap vardır."');
INSERT INTO verses (sura, aya, text) VALUES (9, 62, 'Sizi razı etmek için Allah’a yemin ederler. Eğer Mümin iseler Allah’ı ve Rasûlünü razı etmeleri daha gereklidir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 63, 'Allah''a ve Peygamberine karşı gelmeye kalkan için içinde sonsuza kadar kalacağı cehennem olduğunu bilmediler mi? En büyük rüsvaylık işte budur!');
INSERT INTO verses (sura, aya, text) VALUES (9, 64, 'Münafıklar, kendileri hakkında kalplerinde bulunanı kendilerine haber verecek bir surenin indirileceğinden çekiniyorlar. De ki: “Alay edin bakalım. Allah, çekindiğiniz şeyi ortaya çıkaracaktır.”');
INSERT INTO verses (sura, aya, text) VALUES (9, 65, 'Onlara soracak olursan: "Sadece biz eğlenip oynuyorduk." diyecekler. De ki: "Allah ile ayetleriyle ve Rasûlüyle mi eğleniyordunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (9, 66, 'Özür beyan etmeyin. İman ettikten sonra kâfir oldunuz. İçinizden (af dileyen) bir kısmınızı bağışlasak bile, suçlu oldukları için bir kısmınıza azap edeceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (9, 67, 'Münafık erkekler ve kadınlar birbirlerinin aynıdır. Kötülüğü emrederler, iyiliğe engel olurlar. Elleri de (infak etmede) sıkıdır. Allah’ı unuttular. Allah da onları unuttu. Gerçekten münafıklar, fasıkların ta kendisidir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 68, 'Allah, münafık erkeklere ve münafık kadınlara ve tüm kâfirlere, içinde ebedî kalacakları Cehennem''i vadetti. Bu onlara yeter. Allah, onları lanetlemiştir. Onlara kalıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 69, '(Ey münafıklar!) Siz de kendinizden öncekiler gibisiniz. Onlar sizden daha kuvvetliydiler, malları ve evlatları da daha çoktu. Nasiplerine düşenin tadını çıkardılar. Sizden öncekilerin nasiplerinden faydalandıkları gibi siz de nasibinize düşenden yararlandınız. Onların daldıkları gibi siz de (batıla) daldınız. İşte bunlar, dünyada ve ahirette yaptıkları amelleri boşa gidenlerdir. İşte onlar hüsrana uğrayanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 70, 'Onlara, kendilerinden önce geçen Nûh, Âd, Semûd kavimlerinin, İbrahim kavminin, Medyen halkının ve alt üst olmuş (Lût kavmi) şehirlerinin haberleri gelmedi mi? Rasûlleri, onlara apaçık deliller getirmişlerdi. Allah, onlara zulmetmemiş; fakat onlar kendi nefislerine zulmetmişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (9, 71, 'Mümin erkekler ve Mümin kadınlar birbirlerinin velileridir. İyiliği emrederler; kötülüğe engel olurlar. Namazı ikame ederler, zekât verirler, Allah’a ve Rasûlüne itaat ederler. İşte bunlara Allah rahmet edecektir. Allah şüphesiz Aziz''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 72, 'Allah, Mümin erkeklere ve Mümin kadınlara, ebedî olarak kalacakları, içinden ırmaklar akan Cennetler ve Adn Cennetlerinde çok güzel köşkler vadetti. Allah’ın rızası ise, bunların hepsinden daha büyüktür. İşte bu büyük başarıdır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 73, 'Ey Peygamber! Kâfirlere ve münafıklara karşı cihad et ve onlara karşı çetin ol. Onların varacakları yer Cehennem''dir. Ne kötü bir varış yeridir orası!');
INSERT INTO verses (sura, aya, text) VALUES (9, 74, 'Bir şey söylemediklerine dair Allah’a yemin ediyorlar. Hâlbuki o küfür sözünü söylediler ve onlar müslümanlıklarından sonra kâfir oldular. Ayrıca başaramadıkları şeye (Peygamberi öldürmeye) de yeltendiler. Sırf, Allah ve Rasûlü kendi lütfu ile onları zengin kıldığı için intikam almaya kalktılar. Eğer tevbe ederlerse, kendileri için hayırlı olur. Şayet yüz çevirirlerse, Allah onları dünyada ve ahirette elem dolu bir azaba çarptıracaktır. Artık onlar için yeryüzünde ne bir dost, ne de bir yardımcı vardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 75, 'İçlerinde; "Allah bize bol nimetinden verirse, kesinlikle sadaka vereceğiz ve doğru kimselerden olacağız." diye O’na söz verenler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 76, 'Fakat Allah lütfundan onlara (zenginlik) verince, onda cimrilik edip (Allah''ın emrinden) yüz çevirerek sözlerinden döndüler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 77, 'Allah’a verdikleri sözü tutmadıkları ve yalan söyledikleri için O da kalplerine, kendisiyle karşılaşacakları güne kadar (sürecek) bir nifak soktu.');
INSERT INTO verses (sura, aya, text) VALUES (9, 78, '(Münafıklar) Allah’ın, içlerinde gizlediklerini ve fısıltılarını bildiğini ve Allah’ın gaybleri çok iyi bilen olduğunu bilmediler mi?');
INSERT INTO verses (sura, aya, text) VALUES (9, 79, 'Sadakalarda (gönülden fazlasıyla) veren Müminleri ayıplayan ve (az da olsa) ellerinden geldiği kadarını verebilenlerle alay eden kimselerle, Allah da alay eder. Onlara acıklı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 80, 'Onlar için ister bağışlanma dile, ister dileme (fark etmez.) Onlar için yetmiş kez bağışlanma dilesen de, Allah onları asla affetmeyecektir. Bu, onların Allah ve Rasûlüne (iman etmeyip) kâfir olmaları sebebiyledir. Allah, fasık topluluğu doğru yola iletmez.');
INSERT INTO verses (sura, aya, text) VALUES (9, 81, 'Allah Rasûlü''nün ardından onun aksine (Tebük Savaşı''ndan) geri kalanlar, oturup kalmalarına sevindiler. Allah yolunda mallarıyla canlarıyla cihat hoşlarına gitmedi de sıcakta savaşa çıkmayın, dediler. De ki: "Cehennem ateşi daha sıcaktır." Keşke anlayabilselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (9, 82, 'Artık yaptıklarının cezası olarak az gülsünler, çok ağlasınlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 83, 'Allah seni geri döndürüp, onlardan bir toplulukla karşılaştırdığı zaman, senden savaşa çıkmak için izin isterlerse de ki: "Benimle asla çıkamayacaksınız, benim yanımda hiçbir düşmanla savaşamayacaksınız. Çünkü siz baştan oturup kalmaya razı oldunuz. Artık geri kalanlarla beraber oturun!"');
INSERT INTO verses (sura, aya, text) VALUES (9, 84, 'Onlardan ölen hiçbirine asla namaz kılma ve kabrinin başında durma. Çünkü onlar Allah’a ve Rasûlü’ne kâfir oldular ve fâsık olarak öldüler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 85, '(Ey Muhammed!) Onların malları ve evlatları seni imrendirmesin. Allah, bunlarla ancak dünyada kendilerine azap etmeyi ve canlarının kâfir olarak çıkmasını istiyor.');
INSERT INTO verses (sura, aya, text) VALUES (9, 86, '“Allah’a iman edin ve Rasûlü ile birlikte cihat edin” diye bir sure indirildiğinde, onlardan servet sahibi olanlar senden izin istediler ve; “Bizi bırak da oturup kalanlarla birlikte olalım.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 87, 'Onlar geride kalan (kadın ve çocuk)larla birlikte olmaya razı oldular ve kalpleri mühürlendi. Artık onlar anlamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 88, 'Fakat Peygamber ve beraberindeki Müminler; mallarıyla, canlarıyla cihat ettiler. Bütün hayırlar işte bunlarındır. İşte bunlar kurtuluşa erenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 89, 'Allah onlara içinde ebedî kalacakları, içinden ırmaklar akan Cennetler hazırlamıştır. İşte bu büyük başarıdır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 90, 'Bedevîlerden mazeret ileri sürenler, kendilerine izin verilsin diye geldiler. Allah’a ve Rasûlüne yalan söyleyenler ise (mazeret bile belirtmeden) oturup kaldılar. Onlardan kâfir olanlara elem dolu bir azap isabet edecektir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 91, 'Allah’a ve Rasûlüne karşı sadık ve samimi oldukları takdirde, güçsüzlere, hastalara ve (seferde) harcayacakları bir şey bulamayanlara (sefere katılmadıkları için) bir günah yoktur. İyilikte/ihsanda bulunan kimselerin (kınanması) için de bir sebep yoktur. Allah; çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 92, 'Kendilerini bindirip (cepheye) sevk edesin diye sana geldikleri zaman, senin; “Sizi bindirebileceğim bir şey bulamıyorum.” dediğin, bu uğurda harcayacakları bir şey bulamadıklarından dolayı üzüntüden gözleri yaş döke döke geri dönen kimselere de bir sorumluluk yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (9, 93, 'Sorumluluk ancak, zengin oldukları halde senden izin isteyenleredir. Bunlar, geride kalan(kadın ve çocuk)larla birlikte olmaya razı oldular. Allah da kalplerini mühürledi. Artık onlar bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 94, 'Kendilerine döndüğünüz vakit size özür beyan ederler. De ki: Özür beyan etmeyin, size inanmayacağız. Allah sizin haberlerinizi bize bildirmiştir. Allah da yaptıklarınızı görecektir, Rasûlü de. Sonra gaybı ve görünenleri bilene döndürüleceksiniz. O da size yaptıklarınızı haber verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 95, 'Döndüğünüzde onlara ilişmemeniz için Allah’a yemin edeceklerdir. Siz onlardan yüz çevirin. Onlar pistir, kazandıklarının karşılığı olarak barınakları Cehennem''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 96, 'Kendilerinden razı olasınız diye size yemin ederler. Siz onlardan razı olsanız bile Allah fasıklar topluluğundan razı olmaz.');
INSERT INTO verses (sura, aya, text) VALUES (9, 97, 'Bedeviler küfür ve nifak bakımından daha şiddetlidir. Allah’ın Rasûlü''ne indirdiğinin sınırlarını bilmemeye daha yatkındırlar. Allah her şeyi bilendir ve Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 98, 'Bedevilerden, Allah yolunda infak ettiklerini ziyan sayanlar ve sizin başınıza belalar gelmesini bekleyenler vardır. Belalar onlara olsun! Allah şüphesiz her şeyi işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 99, 'Bedevîlerden öylesi de vardır ki, Allah''a ve ahiret gününe iman eder, (hayır için) harcayacağını Allah katında yakınlığa ve Peygamber''in dualarını almaya vesile edinir. İyi bilin ki bunlar (ettikleri infak ve aldıkları dua), onlar için bir yakınlıktır. Allah onları rahmetine sokacaktır. Allah şüphesiz çokça bağışlayandır, merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 100, '(İman etmede) ilk ve öncü olan Muhacirler''den, Ensar''dan ve onlara güzelce tabi olanlardan Allah razı olmuştur. Onlar da Allah’tan razı olmuşlardır. Allah onlara altlarından ırmaklar akan ve içinde ebedî kalacakları Cennetler hazırlamıştır. İşte en büyük kurtuluş budur.');
INSERT INTO verses (sura, aya, text) VALUES (9, 101, '(Ey Medineliler!) Çevrenizdeki bedevilerden münafıklar vardır ve Medineliler içinde de nifakta direnen kimseler vardır. Onları siz bilmezsiniz. Biz onları biliyoruz. Onlara iki kere azap edeceğiz. Sonra da onlar büyük bir azaba uğrayacaklar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 102, '(Savaştan geri kalan) Diğer bir kısım da, günahlarını itiraf ettiler. Bunlar salih amelle kötü ameli birbirine karıştırmışlardır. Umulur ki Allah, tevbelerini kabul eder. Çünkü Allah, çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 103, 'Onların mallarından, onları kendisiyle arındıracağın ve temizleyeceğin bir sadaka (zekât) al ve onlara dua et! Çünkü senin duan onlar için sükûnettir.(Onların kalplerini yatıştırır.) Allah, hakkıyla işitendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 104, 'Kulların tevbesini ancak Allah''ın kabul ettiğini, sadakaları da O''nun kabul ettiğini bilmiyorlar mı? Allah tevbeleri çokça kabul edendir, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 105, 'De ki: (Yapacağınız amelleri) yapın, Allah yaptıklarınızı görecektir. Rasûlü ve Müminler de. Gaybı ve görüleni bilen Allah’a döndürüleceksiniz. O size yapmakta olduğunuz amellerinizi haber verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 106, '(Savaşa katılmayan) diğer bir kısım da, Allah’ın (haklarındaki) emrine bırakılmışlardır. Allah onlara ya azap eder ya da tevbelerini kabul eder. O, her şeyi hakkıyla bilendir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 107, 'Zarar vermek, küfre sapmak, iman edenlerin arasını ayırmak, Allah ve elçisine karşı savaşanlara daha önceden gözcülük etmek üzere bir mescit (mescid-i Dırar) kurup, “Biz sadece iyilik yapmak istedik” diye yemin ederler. Ama Allah şâhitlik eder ki, bunlar mutlaka yalancıdırlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 108, 'O mescidde asla (namaza) durma! İlk günden beri takva üzerine bina edilen mescidde (Kuba Mescidi''nde namaza) durman çok daha uygundur. Orada (madden ve mânen) temizlenip, arınmayı arzulayan adamlar vardır. Allah, temizlenip arınanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (9, 109, 'Binasını, Allah’tan sakınma/takvalı olma ve O’nun rızası üzerine kuran kimse mi hayırlıdır; yoksa binasını yıkılmak üzere olan bir yerin kenarına yapıp da onunla beraber Cehennem ateşine yuvarlanan kimse mi? Allah, zalim toplumlara hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (9, 110, 'Yaptıkları binaları, kalpleri parça parça oluncaya dek bir şüphe (kaynağı) olarak kalmaya devam edecektir. Allah, her şeyi hakkıyle bilendir;Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 111, 'Allah, Müminlerden canlarını ve mallarını Cennet karşılığında satın almıştır. (Onlar) Allah yolunda savaşarak öldürürler ve öldürülürler. Bu, Tevrat’ta, İncil’de ve Kur’an’da Allah üzerinde hak bir vaaddir. Verdiği sözü Allah’tan daha çok tutan kim vardır? Öyleyse O’nunla yaptığınız alışverişe sevinin. İşte en büyük kazanç budur.');
INSERT INTO verses (sura, aya, text) VALUES (9, 112, '(Bu Cennet''i kazananlar) Allah’a tevbe eden, ibadet eden, hamt eden, (ibadet için) rükû yapan, secde eden, iyilikleri emreden, kötülükleri yasaklayan, Allah’ın sınırlarını koruyan kimselerdir. Müminleri müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (9, 113, 'Cehennemlik oldukları (küfür üzere öldükleri) anlaşıldıktan sonra, akraba bile olsalar müşrikler için bağışlanma dilemek peygambere ve iman edenlere yaraşmaz.');
INSERT INTO verses (sura, aya, text) VALUES (9, 114, 'İbrahim’in babası için bağışlanma dilemesi, sadece ona verdiği bir sözden dolayı idi. Allah’ın düşmanı olduğunu kesin olarak anlayınca ondan uzaklaştı. İbrahim, gerçekten çok dua edip yalvaran ve yumuşak kalpli biriydi.');
INSERT INTO verses (sura, aya, text) VALUES (9, 115, 'Allah bir kavme hidâyet verdikten sonra, sakınacakları şeyleri kendilerine apaçık bildirmedikçe onları saptırmaz. Şüphesiz Allah her şeyi çok iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 116, 'Göklerin ve yerin mülkü elbette Allah’ındır. Dirilten ve öldüren O’dur. Sizin Allah’tan başka bir veliniz ve yardımcınız yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (9, 117, 'Allah, peygamberin, Muhacirler''in, Ensar''ın ve sıkıntılı bir zamanda (Tebuk Savaşı''nda) bir kısmının kalpleri meyletmek üzere iken peygambere tabi olan kimselerin tevbelerini kabul etti. Sonra onların tevbelerini kabul buyurdu. Şüphesiz O çok şefkatlidir, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 118, '(Savaştan geri kalan) Üç kişiye, bütün genişliğine rağmen yeryüzü dar gelmiş ve nefisleri kendilerini (üzüntüden) sıkmıştı. Allah’tan başka bir sığınak olmadığını anladılar. Sonra Allah, onları tevbe etmeye muvaffak kıldı da onlar da tevbe ettiler ve Allah onların tevbelerini kabul buyurdu. Şüphesiz tevbeleri çokça kabul eden, çokça merhamet eden O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (9, 119, 'Ey iman edenler! Allah’a karşı gelmekten sakının ve sâdıklarla beraber olun.');
INSERT INTO verses (sura, aya, text) VALUES (9, 120, 'Gerek Medine’lilerin, gerek onların çevresinde bulunan bedevilerin Rasûlullah’tan geri kalmaları ve kendilerini O’na tercih etmeleri yaraşmaz. Mutlaka onlara Allah yolunda bir susuzluk, bir yorgunluk ve bir açlık isabet etmesi, kâfirleri öfkelendirecek bir yere ayak basmaları ve düşmana karşı bir başarı kazanmaları karşılığında salih bir amel yazılacaktır. Şüphesiz Allah, iyilik yapanların ecrini zayi etmez.');
INSERT INTO verses (sura, aya, text) VALUES (9, 121, 'Küçük ve büyük infak ettikleri her nafaka ve (Allah yolunda) aştıkları her vadi yaptıkları işin daha güzeliyle Allah''ın kendilerini mükâfatlandırması için onlar adına yazılmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (9, 122, 'Müminlerin toptan savaşa çıkmaları uygun değildir. Ama her topluluktan bir grup çıksın. Ta ki dinde derin bilgiye kavuşma ve kavimleri geri döndüklerinde onları uyarmak için (geride bir topluluk kalsın). Umulur ki sakınırlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 123, 'Ey iman edenler! Kâfirlerden yakınınızda bulunanlarla savaşın ki, sizde kendilerine karşı bir sertlik bulsunlar. Bilin ki Allah takvâ sahipleriyle beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 124, 'Bir sûre indirilince aralarında: "Bu hanginizin imanını artırdı?" diyen kimseler vardır. O, iman eden kimselerin imanını artırmıştır. Onlar, bunu birbirlerine müjdelerler.');
INSERT INTO verses (sura, aya, text) VALUES (9, 125, 'Kalplerinde hastalık olanların ise pisliklerine pislik katmıştır ve onlar kâfirler olarak ölmüşlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 126, 'Görmüyorlar mı ki, onlar her yıl bir veya iki kere belaya çarptırılıp imtihan ediliyorlar? Sonra ne tevbe ederler, ne de ibret alırlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 127, 'Bir sure indirildiği zaman, birbirlerine bakarlar; "Sizi birisi görüyor mu?" derler, sonra da çekip giderler. Allah onların kalplerini ters çevirmiştir. Çünkü onlar anlamayan bir toplulukturlar.');
INSERT INTO verses (sura, aya, text) VALUES (9, 128, 'Andolsun ki size, içinizden sizin sıkıntıya uğramanız kendisine ağır gelen, size düşkün, Müminlere şefkatli ve merhametli bir rasûl gelmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (9, 129, 'Eğer imandan yüz çevirirlerse de ki: "Bana Allah yeter, O’ndan başka (hak) ilah yoktur. Yalnız O’na tevekkül ettim. O, yüce arşın Rabbidir."');
INSERT INTO verses (sura, aya, text) VALUES (10, 1, 'Elif Lâm Râ.[1] İşte bunlar hakîm olan (hikmet dolu) kitabın ayetleridir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 2, 'İçlerinden bir adama insanları uyar ve iman edenlere, Rableri katında kendileri için bir doğruluk makamı bulunduğunu müjdele diye vahyetmemiz, insanlar için şaşılacak bir şey mi oldu ki o kâfirler, “Bu elbette apaçık bir sihirbazdır” dediler?');
INSERT INTO verses (sura, aya, text) VALUES (10, 3, 'Şüphesiz Rabbiniz O Allah''tır ki, gökleri ve yeri altı günde yaratan sonra Arş''a istivâ eden (yükselen) ve işleri yerli yerince yönetendir. O''nun izni olmadan kimse şefaatçi olamaz. İşte sizin Rabbiniz Allah budur. O halde (sadece) O’na ibadet edin! Öğüt almıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (10, 4, 'Hepinizin dönüşü O’nadır. Allah’ın vaadi haktır. O, (mahlûkatı) önce (yoktan) yaratır. Sonra da iman edip salih amel işleyenleri adaletle karşılığını vermek için yeniden diriltir. Kâfirlere gelince, kâfirlik yaptıkları için onlara kızgın bir içecek ve can yakan bir ceza vardır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 5, 'Güneşi ışık (kaynağı), Ay''ı da nur/aydınlık kılan, yılların sayısını ve hesabı bilmeniz için Ay''a menziller (konak yerleri) takdir eden O’dur. Allah bunları sadece hak olarak yaratmıştır. O, bilen bir toplum için ayetleri apaçık bir şekilde işte böyle açıklar.');
INSERT INTO verses (sura, aya, text) VALUES (10, 6, 'Gece ile gündüzün birbiri ardınca gelişinde, Allah’ın göklerde ve yerde yarattığı şeylerde sakınan bir toplum için ayetler/deliller vardır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 7, '(Hesap için) Bizimle karşılaşmayı ummayan ve dünya hayatına razı olup onunla tatmin olanlar, işte onlar ayetlerimizden gafildirler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 8, 'İşte bunların kazandıklarının karşılığı olarak varacakları yer ateştir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 9, '(Fakat) iman edip salih ameller işleyenlere gelince, Rableri onları imanları sebebiyle hidayete erdirir. Nimetlerle dolu Cennetlerde altlarından ırmaklar akar.');
INSERT INTO verses (sura, aya, text) VALUES (10, 10, 'Orada duaları: "Allah’ım! Sen tüm noksanlıklardan münezzehsin" dir. (Aralarında ki) selamlaşmaları “Selam”dır, dualarının sonu ise: ”Âlemlerin Rabbine hamdolsun” dur.');
INSERT INTO verses (sura, aya, text) VALUES (10, 11, 'Eğer Allah, insanlara hayrı çarçabuk istedikleri gibi şerri de acilen verseydi, hemen ecellerine hükmedilirdi. (Helak edilirlerdi.) Bizimle buluşmayı ümit etmeyenleri azgınlıkları içinde bocalar bir halde bırakırız.');
INSERT INTO verses (sura, aya, text) VALUES (10, 12, 'İnsana bir darlık dokunduğu zaman, yatarken otururken veya ayakta iken bize dua edip yalvarır. Biz onun darlığını giderdiğimizde sanki başına gelen darlık sebebiyle bize hiç yalvarmamış gibi geçip gider. İşte böyle müsriflere (haddi aşanlara) yapmakta oldukları süslü gösterilir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 13, 'Andolsun, sizden önceki nice nesilleri peygamberleri kendilerine apaçık deliller getirdikleri hâlde (yalanlayıp) zulmettikleri vakit helâk ettik. Onlar zaten iman edecek değillerdi. İşte biz günahkârlar topluluğunu böyle cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (10, 14, 'Sonra, onların ardından nasıl amel işleyeceğinizi görmek için sizi yeryüzünün halifeleri yaptık.');
INSERT INTO verses (sura, aya, text) VALUES (10, 15, 'Kendilerine ayetlerimiz açık açık okununca, bizimle karşılaşmayı ummayanlar: "Bundan başka bir Kur’an getir ya da bunu değiştir" dediler. De ki: "O’nu kendime göre değiştirmem mümkün değildir. Ben, sadece bana vahyedilene uyarım. Ben eğer Rabbime isyan edersem büyük bir günün azabından korkarım."');
INSERT INTO verses (sura, aya, text) VALUES (10, 16, 'De ki: Eğer Allah dileseydi onu size hiç okumazdım ve onu size hiç bildirmezdi. Daha önce sizin aranızda bir ömür yaşadım, hiç akletmiyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (10, 17, 'Allah adına yalan uydurandan veya Allah''ın ayetlerini yalan sayandan daha zalim kim olabilir? Suçlular kesinlikle kurtuluşa eremezler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 18, 'Onlar Allah ile birlikte kendilerine ne bir zarar ne de bir fayda vermeyecek olan şeylere ibadet ederler. Bir de: “Bunlar Allah katında bizim şefâatçilerimizdir” derler. De ki: Allah’a, göklerde ve yerde bilmediği bir şeyi mi haber veriyorsunuz? Allah, onların şirk koşmalarından münezzehtir ve çok yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 19, 'İnsanlar, aslında, tek bir ümmet idiler. Fakat sonradan ayrılığa düştüler. Eğer Rabbin tarafından önceden verilmiş bir söz olmasaydı, aralarında ayrılığa düştükleri şeyde hüküm verilirdi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 20, 'Rabbinden ona bir mucize indirilseydi ya! derler. De ki: Gayb ancak Allah’ındır. Bekleyiniz ben de sizinle birlikte bekleyenlerdenim.');
INSERT INTO verses (sura, aya, text) VALUES (10, 21, 'Kendilerine dokunan bir sıkıntıdan sonra, insanlara bir rahmet (ferahlık ve mutluluk) tattırdığımız zaman bir de bakarsın ki, âyetlerimiz hakkında onların bir tuzakları vardır. De ki: “Allah, daha çabuk tuzak kurar.” Şüphesiz elçilerimiz (melekler) kurmakta olduğunuz tuzakları yazıyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (10, 22, 'Sizi karada ve denizde yürüten O’dur. Öyle ki, siz bir gemide iken ve güzel bir rüzgar ile akıp götürürken bu yüzden (yolcular) neşelenirlerken, o gemiye şiddetli bir fırtına gelip çatar, her yerden onlara dalgalar hücum eder ve onlar çepeçevre kuşatıldıklarını anlarlar da dini yalnız Allah''a halis kılarak: "Eğer bizi bundan kurtarırsan mutlaka şükredenlerden olacağız" diye Allah''a dua ederek yalvarırlar.');
INSERT INTO verses (sura, aya, text) VALUES (10, 23, 'Fakat Allah onları kurtarınca, bir de bakarsın ki yeryüzünde (şirk koşarak) haksız yere taşkınlıkta bulunurlar. Ey İnsanlar! Sizin taşkınlığınız, sırf kendi aleyhinizedir. (Bununla) sadece dünya hayatının yararını elde edersiniz. Sonunda dönüşünüz bizedir. (Biz de) bütün yaptıklarınızı size haber vereceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (10, 24, 'Dünya hayatının örneği, gökten indirdiğimiz su gibidir. Onunla insanların ve hayvanların yiyeceği bitkiler, o su sayesinde gürleşip birbirine girer. Yeryüzü tüm güzelliklerini takınıp süslenip bezenir. Sahipleride artık bunları toplayabileceklerini sandıkları sırada, geceleyin veya gündüzün emrimiz gelir de onu sanki dün yerinde yokmuş gibi kökünden biçilmiş bir hale getiririz. İşte düşünen bir topluma ayetleri böyle açıklıyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (10, 25, 'Allah, selam yurduna (Cennet''e) çağırır, dileyeni de dosdoğru yola hidayet eder.');
INSERT INTO verses (sura, aya, text) VALUES (10, 26, 'İyi amellerde bulunanlara, güzellik (Cennet) ve fazlası (Allah -Azze ve Celle-''nin yüzüne bakmak) vardır. Onların yüzlerini karartı ve zillet bürümez. Onlar Cennet ehlidir, onlar orada ebedidirler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 27, 'Kötü amel işleyenlere, kötülükleri kadar ceza vardır. Onları zillet bürümüştür. Onları Allah’a karşı koruyacak kimse yoktur. Sanki onların yüzleri gecenin karanlık parçalarıyla kaplanmış gibidir. İşte onlar ateş ehlidir. Onlar, orada ebedidirler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 28, 'O gün onların hepsini bir araya toplarız. Sonra şirk koşanlara: "Siz ve ortaklarınız (şirk koştuklarınız) yerlerinize!" deriz ve aralarını ayırırız. Ortak koştukları onlara: "Siz bize ibadet etmiyordunuz ki." derler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 29, 'Allah, sizinle bizim aramızda şahit olarak yeter. Gerçekten sizin bize ibadet ettiğinizden haberimiz yoktu, derler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 30, 'İşte orada (o gün) herkes önceden yaptıklarını görüp, kavrar ve gerçek mevlaları olan Allah’a döndürülürler ve uydurdukları şeyler (şirk koştukları şeyler) de onları terkedip gider.');
INSERT INTO verses (sura, aya, text) VALUES (10, 31, 'De ki: “Gökten ve yerden size rızık veren kimdir? Kulak ve gözlerin sahibi kimdir? Diriyi ölüden çıkaran, ölüyü de diriden çıkaran kimdir? Her işi düzenleyen kimdir?” Onlar, “Allah''tır!” diyecekler. O halde “O''na karşı gelmekten sakınmaz mısınız?” de.');
INSERT INTO verses (sura, aya, text) VALUES (10, 32, 'İşte hak olan Rabbiniz Allah budur. Haktan sonra da sapıklıktan başka ne vardır? O halde nasıl (haktan) çevriliyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (10, 33, 'İşte Rabbinin: “Gerçekten onlar iman etmezler” sözü o fâsıklar için böylece sabit olmuştur.');
INSERT INTO verses (sura, aya, text) VALUES (10, 34, 'De ki: Ortak koştuklarınızdan ilk defa (yoktan) yaratan ve sonra bunu tekrar eden var mıdır? De ki: İlk olarak (yoktan) yaratan ve onu tekrarlayan Allah’tır. O halde nasıl (haktan batıla) çevriliyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (10, 35, 'De ki: Ortak koştuklarınızdan hakka hidayet edebilecek olan var mıdır? De ki: Allah, hakka hidayet eder. Hakka hidayet eden mi uyulmaya daha layıktır; yoksa hidayet verilmedikçe kendi kendine doğru yolu bulamayan mı? Nasıl böyle (batıl) hüküm veriyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (10, 36, 'Onların çoğu sadece zanna uyarlar. Gerçekte zan, hakikat karşısında bir şey ifade etmez. Şüphesiz ki Allah, onların her yaptıklarını bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 37, 'Bu Kur''an Allah''tandır. Başkası tarafından uydurulmuş bir (kitap) değildir. Ancak kendinden öncekini doğrulayan ve o kitabı açıklayandır. Onda şüphe yoktur, o âlemlerin Rabbindendir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 38, 'Yoksa onu (Muhammed kendisi) uydurdu mu diyorlar? De ki: “Eğer doğru söyleyenler iseniz, haydi siz de onun benzeri bir sure getirin ve Allah’tan başka, çağırabileceğiniz kim varsa onları da yardıma çağırın."');
INSERT INTO verses (sura, aya, text) VALUES (10, 39, 'Onlar, ilmini kavrayamadıkları ve henüz (onlara vadolunup da) gerçekleşmemiş olan şeyi yalanladılar. Onlardan öncekiler de böyle yalanlamışlardı. Zalimlerin sonunun nasıl olduğuna bir bak!');
INSERT INTO verses (sura, aya, text) VALUES (10, 40, 'Aralarında ona (Kur''an''a) iman edenler de vardır, iman etmeyenler de. Rabbin ise fesat çıkaranları çok iyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 41, 'Seni yalanlarlarsa; de ki: "Benim amellerim bana, sizin amelleriniz de size aittir. Siz benim yaptığım amellerden uzaksınız, ben de sizin yaptığınız amellerden uzağım."');
INSERT INTO verses (sura, aya, text) VALUES (10, 42, 'Onlardan sana kulak verenler de vardır. Fakat sağırlara, hele akılları da ermiyorsa, sen mi işittireceksin?');
INSERT INTO verses (sura, aya, text) VALUES (10, 43, 'Onlardan sana bakanlar vardır. Basiretlerini kaybetmişlerse, körlere sen mi yol göstereceksin?');
INSERT INTO verses (sura, aya, text) VALUES (10, 44, 'Şüphesiz ki Allah insanlara hiçbir şekilde zulmetmez, fakat insanlar kendilerine zulmederler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 45, 'Onları yeniden diriltip hepsini bir araya toplayacağı gün, sanki gündüzün bir saatinden başka kalmamışlar (yeni ayrılmışlar) gibi, aralarında tanışırlar. Allah’a kavuşmayı yalan sayanlar, ziyana uğramış ve doğru yolu bulamamışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 46, 'Onlara vadettiğimizin bir kısmını sana (sen hayattayken) gösteririz, ya da seni vefat ettiririz. Onların dönüşü bizedir. Sonra Allah, onların yaptıklarına da şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 47, 'Her ümmet için bir rasûl vardır. (Ahirette) onlara Rasulleri geldiğinde aralarında adaletle hükmedilir ve onlara zulmedilmez.');
INSERT INTO verses (sura, aya, text) VALUES (10, 48, '"Ve eğer doğru söylüyorsanız, bu vaad ne zaman gerçekleşecektir?" derler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 49, '(Ey Muhammed) De ki: Allah’ın dilediğinden başka kendim için bir zarar da faydaya da sahip değilim. Her ümmetin bir eceli vardır. Eceli geldiği zaman bir saat bile geri de bırakılmaz, ileri de alınmaz.');
INSERT INTO verses (sura, aya, text) VALUES (10, 50, 'De ki: (Ey müşrikler!) Ne dersiniz? Allah’ın azabı size gece veya gündüz gelirse ne yaparsınız? Suçlular niye bunda acele ediyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (10, 51, 'O (azap), gerçekleştikten sonra mı ona iman edeceksiniz? (Size o vakit denilecek ki:) Şimdi mi (İman ediyorsunuz)? Siz onu acele istiyordunuz.');
INSERT INTO verses (sura, aya, text) VALUES (10, 52, 'Sonra zalimlere şöyle denir: "Sonsuz azabı tadın, kazanmakta olduğunuzdan başkasının karşılığını mı bulacaksınız?"');
INSERT INTO verses (sura, aya, text) VALUES (10, 53, 'O (azap) gerçek midir?” diye senden haber soruyorlar. De ki: “Evet! Rabbime andolsun ki o elbette gerçektir. Siz ondan kaçamayacaksınız."');
INSERT INTO verses (sura, aya, text) VALUES (10, 54, '(O zaman) zulmeden herkes yeryüzündeki bütün servete sahip olsa (azaptan kurtulmak için) elbette onu feda eder. Ve azabı gördükleri zaman için için yanarlar. Aralarında adaletle hükmolunur ve onlara zulmedilmez.');
INSERT INTO verses (sura, aya, text) VALUES (10, 55, 'Bilesiniz ki, göklerdeki her şey, yerdeki her şey Allah’ındır. Yine bilesiniz ki, Allah’ın vaadi haktır. Fakat onların çoğu bunu bilmez.');
INSERT INTO verses (sura, aya, text) VALUES (10, 56, 'Dirilten ve öldüren O’dur. O’na döndürüleceksiniz!');
INSERT INTO verses (sura, aya, text) VALUES (10, 57, 'Ey insanlar! Rabbinizden size bir öğüt, göğüslerdeki (şüphe ve sıkıntılar) için bir şifa ve Müminler için bir hidayet ve rahmet gelmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 58, 'De ki: Ancak Allah’ın lütfu ve rahmetiyle, işte bunlarla sevinsinler. Bu, onların (dünya malı olarak) topladıklarından daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 59, '(Ey Muhammed!) De ki: "Biliyor musunuz, Allah''ın size indirdiği rızıktan bir kısmını helâl, bir kısmını da haram kıldınız?" De ki: "Allah mı size izin verdi, yoksa Allah''a iftira mı ediyorsunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (10, 60, 'Allah’a karşı yalan uyduranların, kıyamet günü hakkındaki zanları nedir? Şüphesiz Allah insanlara karşı çok lütufkârdır, fakat onların çoğu (O’nun nimetlerine) şükretmezler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 61, '(Ey Muhammed!) Sen hangi işte bulunursan bulun, ona dair Kur’an’dan ne okursan oku ve (ey insanlar, sizler de) hangi şeyi yaparsanız yapın, siz ona daldığınızda biz sizi mutlaka görürüz. Ne yerde, ne de gökte zerre ağırlığınca, (hatta) bu zerreden daha küçük veya daha büyük olsun, hiçbir şey Rabbinden uzak (ve gizli) olmaz. Hepsi muhakkak apaçık bir kitapta (Levh-i Mahfuz''da yazılı)dır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 62, 'Bilesiniz ki, Allah''ın dostlarına korku yoktur, onlar üzülmeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 63, 'Onlar Allah’a iman etmiş ve takva sahibi olan kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 64, 'Dünya hayatında da ahirette de müjde onlaradır. Allah’ın sözlerinde hiçbir değişme yoktur. Bu büyük kurtuluştur.');
INSERT INTO verses (sura, aya, text) VALUES (10, 65, '(Ey Muhammed!) Müşriklerin sözleri seni üzmesin; çünkü bütün izzet (ve üstünlük) Allah''ındır. O, her şeyi hakkıyla işiten, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 66, 'İyi bilin ki, göklerde ve yerde kim varsa hepsi Allah’ındır. Allah’ı bırakıp da ortak koştuklarına dua edenler yalnızca zanna uyanlardır. Onlar, zandan başka bir şeyin ardına düşmüyorlar ve onlar sadece yalan söylüyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (10, 67, 'Size geceyi dinlenesiniz diye karanlık ve gündüzü de (çalışasınız diye) aydınlık olarak yaratan Allah’tır. Kulak veren toplum için bunlarda ayetler (ibretler) vardır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 68, '(Müşrikler) “Allah bir çocuk edindi.” dediler. Subhânallah! O, bundan münezzehtir, mustağnidir. Göklerde ve yerde olan her şey O’nundur. Bu hususta bir deliliniz de yoktur. O halde Allah hakkında bilmediğiniz bir şeyi mi söylüyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (10, 69, 'De ki: Allah hakkında yalan uyduranlar asla kurtuluşa eremezler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 70, 'Dünyada biraz geçimlik, sonra dönüşleri yine bize olacaktır. Biz de onlara kâfir olmaları sebebiyle şiddetli azabı tattıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (10, 71, 'Onlara Nûh’un haberini oku! Hani kavmine demişti ki: "Ey Kavmim! İçinizde bulunmam ve Allah’ın ayetlerini hatırlatmam eğer size ağır geliyorsa, ben yalnız Allah’a tevekkül ettim. Haydi! Ortak koştuklarınızla gücünüzü birleştirin. Sonrada yapacağınızı gizli kılmayın. Ardından hükmünüzü uygulayın ve bana mühlet de vermeyin."');
INSERT INTO verses (sura, aya, text) VALUES (10, 72, 'Eğer yüz çevirirseniz bilin ki, ben sizden bir karşılık istememiştim. Benim ecrim sadece Allah’a aittir. Ben müslümanlardan olmakla emrolundum.');
INSERT INTO verses (sura, aya, text) VALUES (10, 73, 'Onu yalanlamışlardı. Biz de onu ve onunla birlikte gemide olanları kurtarmış, ayetlerimizi yalanlayanları ise suda boğmuştuk. Uyarılanların sonunun nasıl olduğuna bak!');
INSERT INTO verses (sura, aya, text) VALUES (10, 74, 'Sonra onun arkasından kendi kavimlerine rasûller göndermiştik. (O toplumlara) Rasûller apaçık delillerle gelmişlerdi. Daha önce yalanladıkları şeye iman edecek değillerdi. İşte, haddi aşanların kalplerini böyle mühürleriz.');
INSERT INTO verses (sura, aya, text) VALUES (10, 75, 'Sonra onların ardından Mûsâ ve Hârûn’u ayetlerimizle Firavun ve kavmine gönderdik. Fakat büyüklük taslamışlardı. Onlar günahkâr bir kavim idi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 76, 'Katımızdan onlara hak geldiği zaman, onlar: "Bu, apaçık bir sihirdir!" demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 77, 'Mûsâ: "Size gelen hak için mi böyle söylüyorsunuz? Bu sihir midir? Sihirbazlar asla kurtuluşa eremezler." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (10, 78, 'Onlar ise: "Sen bize, babalarımızı bulduğumuz yoldan bizi çevirmek için ve yeryüzünde büyüklük/hüküm sadece ikinizin olsun diye mi geldin? Biz ikinize de iman etmiyoruz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 79, 'Firavun ise: "Bütün bilgin sihirbazları bana getirin!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 80, 'Sihirbazlar gelince Mûsâ onlara: "Atacağınızı atın!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 81, 'Onlar, atınca Mûsâ: "Yaptığınız şeyler sihirdir. Şüphesiz Allah onları boşa çıkaracaktır. Allah fesad çıkaranların işlerini düzeltmez." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 82, 'Günahkârlar hoşlanmasa da Allah sözleriyle hakkı ortaya çıkaracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 83, 'Kavminden Mûsâ''ya ’ya çok az bir topluluğun dışında iman eden olmadı. Onlar Firavun ve kavminin kendilerini (dinlerinden) çevirmesinden korkuyorlardı. Çünkü Firavun, o yerde üstündü ve o aşırı gidenlerdendi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 84, 'Mûsâ: "Ey Kavmim! Allah’a iman ettiyseniz ve Müslümanlar iseniz sadece O’na tevekkül edin!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 85, 'Onlar da şöyle dediler: “Biz yalnız Allah’a tevekkül ettik. Ey Rabbimiz! Bizi zalimler topluluğunun baskı ve şiddetine maruz bırakma!”');
INSERT INTO verses (sura, aya, text) VALUES (10, 86, 'Rahmetinle bizi kâfirlerden kurtar, dediler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 87, 'Mûsâ ve kardeşine: "Mısır’da kavminize evler hazırlayın, evlerinizi namazgâh edinin, namazı ikame edin ve iman edenlere müjde verin!"diye vahyettik.');
INSERT INTO verses (sura, aya, text) VALUES (10, 88, 'Mûsâ: "Rabbimiz! Doğrusu sen Firavun’a ve (ileri gelen) kavmine ziynetler ve dünya hayatında mallar verdin. Rabbimiz! Onlar (bununla) senin yolundan saptırıyorlar. Rabbimiz! Onların mallarını yok et, kalplerini katılaştır. Çünkü onlar, can yakıcı azabı görmedikçe iman etmezler." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 89, 'Allah: "İkinizin duası da kabul olundu, (dininiz üzere) istikamet edin; bilmeyenlerin yoluna asla uymayın!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 90, 'İsrailoğulları''nı denizden geçirdik. Firavun ve askerleri, haksızlık ve düşmanlıkla arkalarına düştüler. Firavun boğulacağı anda: "İsrailoğulları’nın iman ettiği ilahtan başka (hak) ilah olmadığına iman ettim. Artık ben de Müslümanlardanım." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (10, 91, 'Şimdi mi? Sen, önceden isyan etmiş ve bozgunculardan olmuştun!');
INSERT INTO verses (sura, aya, text) VALUES (10, 92, '(Ey Firavun!) Bugün senin cesedini arkandan gelenlere ibret olması için kurtaracağız. Şüphesiz, insanların çoğu bizim ayetlerimizden gafildir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 93, 'İsrailoğulları''nı hoşlanacakları evlere yerleştirmiş, temiz yiyeceklerle onları rızıklandırmıştık. Kendilerine ilim gelene kadar da anlaşmazlığa düşmemişlerdi. Şüphesiz Rabbin, anlaşamadıkları konu hakkında kıyamet günü aralarında hüküm verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 94, '(Rasûlüm!) Eğer sana indirdiğimizden (bu anlattığımız olaylardan) kuşkuda isen, senden önce kitabı (Tevrat''ı) okuyanlara sor. Andolsun ki, Rabbinden sana hak gelmiştir. Sakın şüphecilerden olma!');
INSERT INTO verses (sura, aya, text) VALUES (10, 95, 'Ve sakın Allah’ın ayetlerini yalanlayanlardan da olma; yoksa hüsrana uğrayanlardan olursun!');
INSERT INTO verses (sura, aya, text) VALUES (10, 96, 'Şüphesiz Rabbinin sözü (azaba uğrayacakları hükmü) gerçekleşmiş olanlar, iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (10, 97, 'Bütün mucizeler gelmiş olsa bile, elem verici azabı görünceye kadar inanmayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 98, 'Yûnus’un kavminden başka, keşke (azabı görmeden) iman edip, imanı kendisine fayda veren bir tek memleket halkı olsaydı ya! Onlar iman edince, dünya hayatında onlardan zillet azabını gidermiş ve belirli bir süre daha geçindirmiştik.');
INSERT INTO verses (sura, aya, text) VALUES (10, 99, 'Eğer Rabbin dileseydi, yeryüzünde bulunanların tümü iman ederdi. Öyleyken insanları iman etmeye sen mi zorlayacaksın?');
INSERT INTO verses (sura, aya, text) VALUES (10, 100, 'Allah’ın izni olmadıkça hiçbir nefis iman etmez ve azabını akıllarını kullanmayanların üzerine verir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 101, 'De ki: “Göklerde ve yerde neler var; bir bakın.” O âyetler ve korkutmalar, iman etmeyecek bir topluluğa fayda vermez.');
INSERT INTO verses (sura, aya, text) VALUES (10, 102, 'Kendilerinden önce gelip geçmişlerin (başlarından geçen azap) günlerinin bir benzerini mi bekliyorlar? (Öyle mi?) Bekleyin, ben de sizinle beraber beklemekteyim, de!');
INSERT INTO verses (sura, aya, text) VALUES (10, 103, 'Sonra biz rasûllerimizi ve iman edenleri kurtarırız. İman edenleri kurtarmak üzerimize bir haktır.');
INSERT INTO verses (sura, aya, text) VALUES (10, 104, 'De ki: Ey İnsanlar! Benim dinimden şüphede iseniz; bilin ki ben Allah’tan başka ibadet ettiklerinize ibadet etmem, ancak sizi öldürecek olan Allah’a ibadet ederim. Ben, Müminlerden olmakla emrolundum.');
INSERT INTO verses (sura, aya, text) VALUES (10, 105, 'Yüzünü dine hanif olarak döndür, sakın müşriklerden olma!');
INSERT INTO verses (sura, aya, text) VALUES (10, 106, 'Allah’ı bırakıp, sana fayda da zarar da veremeyecek olan şeylere dua edip yalvarma! Eğer böyle yaparsan kesinlikle zalimlerden olursun.');
INSERT INTO verses (sura, aya, text) VALUES (10, 107, 'Allah sana bir zarar dokundurursa onu O’ndan başka giderecek yoktur. Sana bir iyilik dilerse; O’nun lütfunu geri çevirecek de yoktur. O, lütfunu kullarından dilediğine eriştirir. O, çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (10, 108, 'De ki: "Ey insanlar, size Rabbinizden gerçek (Kur’an) gelmiştir. Artık kim doğru yola girerse, ancak kendisi için girer. Kim de saparsa ancak kendi aleyhine sapar. Ben sizden sorumlu değilim.''''');
INSERT INTO verses (sura, aya, text) VALUES (10, 109, '(Ey Muhammed!) Sana vahyolunana uy ve Allah hükmünü verinceye kadar sabret. O, hüküm verenlerin en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 1, 'Elif Lâm Râ.[1] Bu, Hakim ve her şeyden haberdar olan Allah tarafından ayetleri sağlam kılınmış, tam olarak açıklanmış bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 2, 'Allah’tan başkasına ibadet etmeyesiniz. Ben, O’nun tarafından sizler için bir uyarıcı ve müjdeciyim.');
INSERT INTO verses (sura, aya, text) VALUES (11, 3, 'Rabbinizden mağfiret dileyin, sonra da tevbe ile O''na dönün ki, sizi belli bir süreye kadar güzel bir şekilde geçindirip, yaşatsın ve her fazilet sahibine faziletinin karşılığını versin. Şayet yüz çevirirseniz, şüphesiz ben o zaman sizin hakkınızda o büyük günün azabından korkarım.');
INSERT INTO verses (sura, aya, text) VALUES (11, 4, 'Dönüşünüz Allah’adır. O’nun her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (11, 5, 'Bilin ki; onlar (içlerindekini) O’ndan gizlemek için göğüslerini dürüp bükerler. Elbiseleriyle örtündükleri zaman da onların gizlediklerini de açığa vurduklarını da bilir. Çünkü O, kalplerin özünde olanı çok iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 6, 'Yeryüzünde hiçbir canlı yoktur ki, rızkı Allah’a ait olmasın. Her birinin (dünyada) duracakları yeri de, (öldükten sonra) emaneten konulacakları yeri de O bilir. Bunların hepsi açık bir kitapta (Levh-i Mahfuz’da yazılı)dır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 7, 'O''nun arşı su üzerinde iken amel bakımından hanginizin daha iyi olduğunu denemek için gökleri ve yeri altı günde yaratan O''dur. Şayet sen: "Kesinlikle siz, öldükten sonra yine dirileceksiniz" demiş olsan, kâfirler: "Bu apaçık büyüden başka bir şey değildir." derler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 8, 'Andolsun, biz onlardan azabı belirli bir süreye kadar geciktirsek, o zaman da mutlaka “Onu ne alıkoyuyor?” derler. İyi bilin ki, azap onlara geleceği gün, kendilerinden bir daha uzaklaştırılmaz ve alay etmekte oldukları şey, kendilerini çepeçevre kuşatmış olur.');
INSERT INTO verses (sura, aya, text) VALUES (11, 9, 'Eğer insanlara tarafımızdan bir rahmet tattırıp, sonra onu kendisinden geri alırsak, o artık ümitsiz bir nankör olur.');
INSERT INTO verses (sura, aya, text) VALUES (11, 10, 'Eğer ona, kendisine dokunan sıkıntıdan sonra nimetler verirsek şöyle söyleyecektir: Kötülükler benden uzaklaştı. O, gerçekten şımaracak ve övünecektir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 11, 'Sabreden ve salih ameller işleyen kimseler böyle değildir. İşte onlara, mağfiret ve büyük bir mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 12, 'Şimdi sen: “Ona bir hazine indirilmeli yahut onunla beraber bir de bir melek gelmeli değil miydi?” demeleri dolayısıyla göğsün daralıp sana vahyolunanlardan bir kısmını terk mi edeceksin? Sen ancak bir uyarıcısın. Allah ise her şeye vekildir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 13, 'Yoksa: ''Onu kendisi uydurdu'' mu diyorlar? De ki: ''Haydi siz, yalan üzere uydurulmuş olarak onun benzeri on sure getirin ve eğer doğruysanız, Allah''tan başka çağırabildiklerinizi çağırın.''');
INSERT INTO verses (sura, aya, text) VALUES (11, 14, 'Eğer size karşılık vermezlerse, onun (Kur''an''ın) ancak Allah’ın ilmi ile indirilmiş olduğunu ve O’ndan başka (hak) ilah olmadığını bilin! Artık siz Müslüman oluyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (11, 15, 'Kim yalnız dünya hayatını ve onun ziynetini isterse, biz onlara yaptıklarının karşılığını orada tastamam öderiz. Orada onlar bir eksikliğe uğratılmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (11, 16, 'İşte onlar, kendileri için ahirette ateşten başka bir şey olmayan kimselerdir. (Dünyada) yaptıkları şeyler, orada boşa gitmiştir. Zaten bütün yapmakta oldukları da boş şeylerdir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 17, 'Rabbi katından (gelen) açık bir delil üzere olan ve ardından Rabbinden bir şahidin takip ettiği ve kendisinden önce bir de önder ve rahmet olarak Mûsâ ''nın kitabı bulunan kimse (kâfirler gibi) midir? Bunlar o (kitaba) inanırlar. Hangi topluluk onu inkâr ederse vadedilen yeri ateştir. O''ndan (Kitap) tan şüphen olmasın. Şüphesiz O, Rabbinden (gelen) haktır. Fakat, insanların çoğu iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 18, 'Allah’a karşı yalan düzerek iftira edenden daha zâlim kim olabilir? İşte bunlar, Rablerine arz edilecekler ve şâhitler de, “Rablerine karşı yalan söyleyenler işte bunlardır” diyeceklerdir. Biliniz ki, Allah’ın lâneti zalimler üzerinedir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 19, 'Onlar (halkı) Allah yolundan alıkoyan ve onu eğri ve çelişkili göstermek isteyen kimselerdir. Hem de onlar ahireti inkâr edenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 20, 'Bunlar, yeryüzünde (Allah''ı) aciz bırakacak değillerdir. Onların Allah’tan başka bir velisi/yardımcısı da yoktur. Onlara kat kat azap vardır. Çünkü onlar, (hakkı) işitmezler ve görmezlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 21, 'İşte bunlar, kendilerini ziyana uğratan kimselerdir. Uydurmakta oldukları şeyler de kendilerini yüz üstü bırakıp kaybolup gitmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 22, 'Gerçekten onlar, ahirette en çok hüsrana uğrayanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 23, 'İman edip, salih ameller işleyen ve Rablerine gönülden bağlananlara gelince, işte onlar cennetliklerdir. Onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 24, 'Bu iki zümrenin durumu, kör ve sağır ile gören ve işiten kimseler gibidir. Bunların durumları hiç birbirlerine denk olur mu? Hâlâ düşünmez misiniz?');
INSERT INTO verses (sura, aya, text) VALUES (11, 25, 'Andolsun, biz Nûh’u kavmine peygamber olarak gönderdik. Onlara şöyle dedi: ''''Ben sizin için apaçık bir uyarıcıyım.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 26, 'Allah’tan başkasına tapmayın/ibadet etmeyin! Ben, size (gelecek) elem verici bir günün azabından korkuyorum.');
INSERT INTO verses (sura, aya, text) VALUES (11, 27, 'Halkının ileri gelen kâfir takımı: "Biz, senin sadece bizim gibi bir insan olduğunu görüyoruz. Sana, görüşü olmayan, ayak takımından başka kimsenin tabi olduğunu da görmüyoruz. Sizin bizim üzerimize bir üstünlüğünüzü de görmüyoruz. Aksine sizin yalancılar olduğunuza inanıyoruz" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 28, 'Nûh dedi ki: “Ey Kavmim! Söyleyin bakalım; şâyet ben Rabbimden gelen apaçık bir delil üzerinde isem ve O, kendi katından bana bir rahmet vermiş de siz ona karşı kör kalmışsanız, onu istemediğiniz hâlde, biz sizi ona zorlayacak mıyız?”');
INSERT INTO verses (sura, aya, text) VALUES (11, 29, '''Ey kavmim! Buna karşı ben sizden herhangi bir mal da istemiyorum. Benim mükâfatım ancak Allah’a aittir. Ben o iman edenleri (teklifinize uyarak) kovacak da değilim. Çünkü onlar Rablerine kavuşacaklardır. Fakat ben sizin bilgisizce davranan bir toplum olduğunuzu görüyorum.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 30, '“Ey kavmim! Eğer ben onları kovarsam, Allah''a karşı bana kim yardım eder? Hiç düşünmüyor musunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (11, 31, 'Size ben, “Allah’ın hazineleri yanımdadır” demiyorum, gaybı da bilmem. “Ben bir meleğim” de demiyorum. Sizin hor gördüğünüz kimseler için, “Allah, onlara asla hiçbir hayır vermez” de diyemem. Allah, onların içlerindekini daha iyi bilir. Böyle bir şey söylersem, o zaman ben gerçekten zalimlerden olurum.');
INSERT INTO verses (sura, aya, text) VALUES (11, 32, 'Dediler ki: “Ey Nûh! Bizimle tartıştın ve tartışmayı uzattın. Eğer doğru söyleyenlerden isen, haydi kendisiyle bizi tehdit ettiğin azabı getir.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 33, 'Nûh dedi ki: “Onu size, dilerse ancak Allah getirir ve siz (Allah’tan) kaçamayacaksınız.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 34, 'Ben size öğüt vermek istesem de, eğer Allah sizi azdırmak istemişse, öğüdüm size fayda vermez. O, sizin Rabbinizdir ve O’na döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (11, 35, '(Ey Muhammed!) Yoksa “Onu (Kur’an’ı) kendisi uydurdu mu?" diyorlar. De ki: “Eğer onu uydurmuşsam, suçum bana âittir. Ben de sizin işlemekte olduğunuz suçlardan uzağım.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 36, 'Nûh''a, “Senin kavminden, gerçekten iman etmiş olanlardan başkası artık iman etmeyecektir; o halde yaptıkları şeylerden dolayı üzülme” diye vahyolundu.');
INSERT INTO verses (sura, aya, text) VALUES (11, 37, 'Gözlerimizin önünde vahyettiğimize göre gemi yap, zulmedenler hakkında bana birşey söyleme! Muhakkak onlar boğulacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 38, '(Nûh) gemiyi yapıyordu. Kavminden ileri gelenler her ne zaman yanına uğrasalar, onunla alay ediyorlardı. Dedi ki: ''''Bizimle alay ediyorsanız, sizin bizimle alay ettiğiniz gibi biz de sizinle alay edeceğiz.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 39, 'Birazdan alçaltıcı azabın kime geleceğini ve kalıcı azabın kimi kuşatacağını anlayacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (11, 40, 'Sonunda emrimiz gelip, tandır (içinden sular) kaynamaya başlayınca: "Her cinsten birer çifti ve kendileri hakkında daha önce hüküm verilmiş olanlar dışındaki aileni ve iman edenleri gemiye bindir" dedik. Zaten onun yanında iman etmiş olan kimseler çok azdı.');
INSERT INTO verses (sura, aya, text) VALUES (11, 41, '(Nûh), “Binin ona. Onun yüzüp gitmesi de durması da Allah’ın adıyladır. Şüphesiz Rabbim çok bağışlayandır, çok merhamet edendir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 42, 'Gemi dağlar gibi dalgalar arasında akıp onları götürüyordu. Nûh, bir kenara çekilmiş oğluna: "Yavrucuğum, bizimle bin, kâfirlerle olma!" diye seslendi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 43, 'O, (Oğlu) “Ben, kendimi sudan koruyacak bir dağa sığınacağım” dedi. Nûh, “Bugün Allah’ın rahmet ettikleri hariç, O’nun azabından korunacak hiç kimse yoktur” dedi. Derken aralarına dalga giriverdi de oğlu boğulanlardan oldu.');
INSERT INTO verses (sura, aya, text) VALUES (11, 44, '“Ey yeryüzü! Yut suyunu. Ey gök! Tut suyunu” denildi. Su çekildi, iş bitirildi. Gemi de Cûdî’ye oturdu ve; “Zalimler topluluğu, Allah’ın rahmetinden uzak olsun!” denildi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 45, 'Nûh, Rabbine seslenip şöyle dedi: “Rabbim! Şüphesiz oğlum da ailemdendir. Senin vaadin elbette gerçektir. Sen de hükmedenlerin en iyi hükmedenisin.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 46, 'Allah: “Ey Nûh! O, asla senin ailenden değildir. Onun yaptığı, iyi olmayan bir iştir. O halde, hakkında hiçbir bilgin olmayan şeyi benden isteme. Ben cahillerden olmayasın diye sana öğüt veriyorum.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 47, 'Nûh, “Rabbim! Şüphesiz ben senden hakkında bilgim olmayan şeyi istemekten sana sığınırım. Eğer beni bağışlamaz ve bana acımazsan, şüphesiz ziyana uğrayanlardan olurum.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 48, 'Ona denildi ki: ''''Ey Nûh! Sana ve seninle birlikte bulunanlardan birçok ümmete bizden esenlik ve bereketlerle (gemiden) in. Daha birtakım ümmetler de olacak ki, biz onları (dünyada) faydalandıracağız. Sonra da bizden kendilerine elem dolu bir azap dokunacak.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 49, 'İşte bunlar, sana vahyettiğimiz gayb haberlerindendir. Bundan önce onları ne sen biliyordun, ne de kavmin. O halde sabret. Çünkü (iyi) sonuç, Allah’a karşı gelmekten sakınanların olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 50, 'Âd toplumuna da kardeşleri Hûd’u gönderdik: "Ey halkım! (yalnızca) Allah’a ibadet edin. Sizin O’ndan başka hak ilahınız yoktur. (Başka ilahlara ibadet ederek) Siz sadece iftira ediyordunuz." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 51, 'Ey halkım! Sizden bir ücret beklemiyorum. Benim ecrim, beni yoktan yaratana aittir. Aklınızı kullanmıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (11, 52, 'Ey kavmim! Rabbinizden mağfiret dileyin, sonra da O''na tevbe edin ki üzerinize bol bol yağmur göndersin ve kuvvetinize kuvvet katsın. Günahkârlar olarak yüz çevirmeyin.');
INSERT INTO verses (sura, aya, text) VALUES (11, 53, '"Ey Hûd! Sen bize apaçık bir delil getirmedin, biz de senin sözünle ilahlarımızı bırakacak ve sana iman edecek değiliz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 54, 'Biz ancak ilahlarımızdan biri seni kötü çarpmış demekten başka bir şey demeyiz, dediler. Hûd: Ben, Allah’ı şahit tutuyorum. Siz de şahit olun ki, ben sizin O’nu bırakıp koştuğunuz şirklerden uzağım.');
INSERT INTO verses (sura, aya, text) VALUES (11, 55, 'Bana hepiniz toptan tuzağınızı kurun. Sonra da bana mühlet vermeyin, dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 56, 'Şüphesiz ben, benim de sizin de Rabbiniz olan Allah’a tevekkül ettim. Hareket eden ne kadar canlı varsa hepsinin alnından tutan O’dur. Benim Rabbim gerçekten dosdoğru bir yol üzeredir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 57, '"Eğer yüz çevirirseniz şüphesiz ki benimle size gönderileni size tebliğ ettim. Rabbim sizin yerinize başka bir kavim getirir ve siz O’na hiçbir zarar veremezsiniz. Çünkü benim Rabbim her şeyi gözetendir."');
INSERT INTO verses (sura, aya, text) VALUES (11, 58, 'Emrimiz gelince, Hûd''u ve onunla beraber iman edenleri tarafımızdan bir rahmetle kurtardık, onları ağır bir azaptan kurtuluşa erdirdik.');
INSERT INTO verses (sura, aya, text) VALUES (11, 59, 'İşte Âd kavmi! Rablerinin ayetlerini inkâr ettiler. O’nun peygamberlerine karşı geldiler ve inatçı her zorbanın emrine uydular!');
INSERT INTO verses (sura, aya, text) VALUES (11, 60, 'Onlar hem bu dünyada hem de kıyamet gününde lânete tâbi tutuldular. Biliniz ki, Âd (kavmi) Rablerini inkâr ettiler. (Şunu da) bilin ki Hûd''un kavmi Âd, Allah''ın rahmetinden uzak kılındı.');
INSERT INTO verses (sura, aya, text) VALUES (11, 61, 'Semûd kavmine de kardeşleri Salih’i peygamber gönderdik. Dedi ki: “Ey kavmim! Yalnızca Allah’a ibadet edin. Sizin O’ndan başka hiçbir ilâhınız yok. O, sizi yerden yaratıp sizi orada bir ömür boyu yaşattı. O halde O’ndan mağfiret dileyin. Sonra O’na tevbe edin. Şüphesiz ki Rabbim çok yakındır, duaları kabul edendir.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 62, '"Ey Salih! Sen bundan önce, içimizde ümit beslenilen bir kimseydin; şimdi babalarımızın ibadet ettiklerine ibadet etmekten bizi men mi ediyorsun? Doğrusu bizi çağırdığın şeyden çok kuşkulandıran bir şüphe içindeyiz" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 63, 'Salih, dedi ki: “Ey kavmim! Söyleyin bakayım, eğer ben Rabbim tarafından apaçık bir delil üzerinde isem ve bana tarafından bir rahmet (peygamberlik) vermişse, O’na karşı geldiğim takdirde beni Allah’tan kim koruyabilir? Demek ki, zarara uğratmaktan başka bana katkınız olmaz.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 64, '“Ey kavmim! İşte size mucize olarak Allah’ın dişi bir devesi. Bırakın onu, Allah’ın arzında yayılıp otlasın. Ona kötülük dokundurmayın, yoksa sizi yakında bir azap yakalar.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 65, 'Derken deveyi kestiler. Salih, dedi ki: “Yurdunuzda üç gün daha yaşayın. (Sonra helâk olacaksınız.) İşte bu, yalanlanamayacak bir tehdittir.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 66, 'Emrimiz gelince, Sâlih''i ve onunla beraber iman edenleri, bizden bir rahmet olarak (azaptan) ve o günün zilletinden kurtardık. Şüphesiz Rabbin mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 67, 'Zalimleri ise bir çığlık aldı ve yurtlarında cansız olarak çöküp kaldılar.');
INSERT INTO verses (sura, aya, text) VALUES (11, 68, 'Sanki orada hiç yaşamamışlardı. Biliniz ki Semûd kavmi Rablerini inkâr etti. (Yine) biliniz ki Semûd kavmi Allah’ın rahmetinden uzaklaştı.');
INSERT INTO verses (sura, aya, text) VALUES (11, 69, 'Andolsun, elçilerimiz (melekler), İbrahim’e müjde getirip; “Selâm sana!” dediler. O, “Size de selâm” dedi ve kızartılmış bir buzağı getirmekte gecikmedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 70, 'Ellerinin buna uzanmadığını görünce, onlardan çekindi ve kalbine bir korku girdi. Onlar (onun bu halini görünce): "Korkma, biz Lût kavmi için gönderildik." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 71, 'İbrahim’in karısı ayakta idi. (Bu sözleri duyunca) güldü. Ona da İshak’ı müjdeledik; İshak’ın arkasından da Yakûb’u.');
INSERT INTO verses (sura, aya, text) VALUES (11, 72, '(İbrahim''in karısı) Vay halime! Ben ihtiyar bir kadınım, kocam da yaşlı olduğu halde nasıl doğurabilirim? Bu şaşılacak bir şey! dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 73, 'Melekler: “Allah’ın emrine mi şaşıyorsun? Allah’ın rahmeti ve bereketi size olsun ey (peygamber ocağının) ev halkı! Şüphesiz O, övülmeye lâyıktır, şanı yücedir.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 74, '"İbrahim’in korkusu gidip kendisine müjde gelince, Lût kavmi hakkında bizim (elçilerimiz) le tartışmaya koyuldu."');
INSERT INTO verses (sura, aya, text) VALUES (11, 75, 'Doğrusu İbrahim, yumuşak huylu, duygulu ve gönülden (Allah''a) yönelen biriydi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 76, 'Elçilerimiz: “Ey İbrahim bundan vazgeç! Çünkü Rabbinin emri kesin olarak gelmiştir. Şüphesiz onlara geri döndürülemeyecek bir azap gelecektir.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 77, 'Elçilerimiz Lût’a gelince onların yüzünden üzüldü, göğsü daraldı ve; “Bu çok zor bir gün” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 78, 'Daha önce çirkin işler yapan halk, koşarak ona geldiler. Lût: "Ey kavmim! İşte bunlar, kızlarımdır. Onlar sizin için en temiz olandır. Allah’tan sakının, misafirlerime beni rezil etmeyin. İçinizde hiç mi aklı başında olan bir adam yok?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 79, 'Senin kızlarını istemediğimizi biliyorsun. Bizim ne istediğimizi de elbette biliyorsun, dediler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 80, '(Lût da:) “Keşke size karşı (koyacak) bir gücüm olsaydı, ya da sağlam bir desteğe dayanabilseydim” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 81, '(Melekler) dediler ki: “Ey Lût! Biz Rabbinin elçileriyiz. Onlar sana asla ulaşamayacaklar. Geceleyin bir vakitte aileni al götür. İçinizden kimse ardına bakmasın. Ancak karın müstesna. (Onu bırak.) Çünkü onların (kavminin) başına gelecek olan azap, onun başına da gelecektir. Onların azapla buluşma zamanı sabahtır. Sabah yakın değil midir?”');
INSERT INTO verses (sura, aya, text) VALUES (11, 82, '(Azap) emrimiz gelince oranın altını üstüne getirdik. Üzerine de Rabbinin katında işaretlenmiş pişirilmiş balçıktan taşlar yağdırdık.');
INSERT INTO verses (sura, aya, text) VALUES (11, 83, 'Rabbinin katından, işaretlenerek (yağdırılmıştır). Bu (azap) şimdi de zalimlerden (Mekkeli''lerden) uzak değildir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 84, 'Medyen halkına da kardeşleri Şu’ayb’ı peygamber gönderdik. O, şöyle dedi: “Ey kavmim! Yalnızca Allah’a ibadet edin. Sizin O’ndan başka hiçbir ilâhınız yoktur. Ölçüyü ve tartıyı eksik yapmayın. Ben sizi bolluk içinde görüyorum. Ben sizin adınıza kuşatıcı bir günün azabından korkuyorum.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 85, '''Ey kavmim! Ölçüyü ve tartıyı adaletle tam yapın. İnsanların eşyalarını (mallarını ve haklarını) eksiltmeyin. Yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 86, '''Eğer iman eden kimseler iseniz Allah’ın bıraktığı helâl kazanç sizin için daha hayırlıdır. Ben sizin başınızda bir bekçi değilim.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 87, 'Dediler ki: "Ey Şuayb! Atalarımızın ibadet ettikleri şeyleri yahut mallarımız hususunda dilediğimizi yapmayı terketmemizi sana namazın mı emrediyor? Oysa sen yumuşak huylu ve çok akıllısın!');
INSERT INTO verses (sura, aya, text) VALUES (11, 88, 'Şuayb, şöyle dedi: ''''Ey kavmim! Söyleyin bakayım. Ya ben Rabbimden gelen açık bir delil üzere isem ve katından bana güzel bir rızık vermişse! Ben size yasakladığımı kendim yapmak istemiyorum. Ben sadece gücüm yettiğince (sizi) düzeltmek istiyorum. Başarım ancak Allah’ın yardımı iledir. Ben sadece O’na tevekkül ettim ve sadece O’na yöneliyorum.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 89, '“Ey Kavmim! Bana karşı olan düşmanlığınız, Nûh kavminin veya Hûd kavminin yahut Salih kavminin başına gelenin benzeri gibi bir felaketi sakın sizin de başınıza getirmesin. (Ve unutmayın ki) Lût kavmi sizden uzak değildir.”');
INSERT INTO verses (sura, aya, text) VALUES (11, 90, '''Rabbinizden bağışlanma dileyin, sonra O’na tevbe edin. Şüphesiz Rabbim çok merhametlidir, çok sevendir.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 91, 'Dediler ki: ''''Ey Şuayb! Dediklerinin çoğunu anlamıyoruz. Hem biz seni aramızda zayıf görüyoruz. Eğer kabilen olmasaydı, seni taşa tutardık. Zaten sen bizce itibarlı biri değilsin.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 92, 'Şuayb, şöyle dedi: ''''Ey kavmim! Benim kabilem sizce Allah’tan daha itibarlı mı ki, O’na sırt çevirdiniz? Şüphesiz Rabbim, sizin yaptıklarınızı çepeçevre kuşatıcıdır.''''');
INSERT INTO verses (sura, aya, text) VALUES (11, 93, 'Ey halkım! Elinizden gelen, her şeyi yapın, ben de yapacağım. Kime rezil edici bir azabın geleceğini, kimin yalancı olduğunu bileceksiniz. Bekleyin, doğrusu ben de sizinle bekliyorum.');
INSERT INTO verses (sura, aya, text) VALUES (11, 94, 'Emrimiz gelince, Şuayb’ı ve onunla birlikte iman edenleri katımızdan bir rahmetle kurtardık. Zulmedenleri ise o korkunç (uğultulu) ses yakaladı da yurtlarında dizüstü çökekaldılar.');
INSERT INTO verses (sura, aya, text) VALUES (11, 95, 'Sanki orada hiç yaşamamışlardı. Biliniz ki Semûd kavmi, Allah’ın rahmetinden uzaklaştığı gibi Medyen halkı da uzaklaştı.');
INSERT INTO verses (sura, aya, text) VALUES (11, 96, 'Mûsâ’yı da ayetlerimizle ve açık bir delil ile göndermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (11, 97, 'Firavun''a ve onun ileri gelenlerine (gönderdik). Fakat onlar Firavun''un emrine uydular. Oysa Firavun''un emri doğru değildi.');
INSERT INTO verses (sura, aya, text) VALUES (11, 98, 'Firavun, kıyamet gününde kavminin önüne geçecek ve onları ateşe götürecektir. Ne kötü varış yeridir orası!');
INSERT INTO verses (sura, aya, text) VALUES (11, 99, 'Onlar, hem bu dünyada, hem de kıyamet gününde lânete uğratıldılar. Ne kötü bağıştır bu onlara verilen!');
INSERT INTO verses (sura, aya, text) VALUES (11, 100, 'İşte bunlar sana kıssa olarak anlattığımız ülkelere ait haberlerdendir. Onlardan ayakta duranlar da var, yıkılıp gidenler de.');
INSERT INTO verses (sura, aya, text) VALUES (11, 101, 'Biz onlara zulmetmedik. Fakat onlar kendilerine zulmettiler. Rabbinin emri gelince, Allah’ı bırakıp da dua ettikleri ilâhları kendilerine hiçbir fayda sağlamadı. İlâhları onların sadece ziyanlarını artırdı.');
INSERT INTO verses (sura, aya, text) VALUES (11, 102, 'Zulme sapmış memleketlerin halkını yakaladığında, Rabbinin yakalaması işte böyledir! Şüphesiz O’nun yakalaması can yakıcı ve şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 103, 'Şüphesiz, ahiret azabından korkanlar için bunda bir ibret vardır. Bu, insanların (hesap ve ceza için) toplanacakları bir gündür. O, tanık olunacak bir gündür.');
INSERT INTO verses (sura, aya, text) VALUES (11, 104, 'Biz onu (kıyamet gününü) ancak belirli bir zamana kadar erteliyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (11, 105, 'O gün geldiği zaman Allah’ın izni olmadan hiçbir kimse konuşamaz. Onlardan kimisi bedbaht, kimisi bahtiyardır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 106, 'Bedbaht olanlar ateştedirler. Onlar orada yüksek hırıltılarla ve inleyerek solurlar.');
INSERT INTO verses (sura, aya, text) VALUES (11, 107, 'Onlar, gökler ve yerler ayakta durdukça orada ebedî olarak kalacaklardır. Ancak Rabbinin dilemesi başka. Şüphesiz Rabbin, istediğini yapandır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 108, 'Bahtiyar olanlar ise Cennet''tedirler. Gökler ve yer ayakta durdukça, orada ebedî kalacaklardır. Ancak Rabbinin dilediği kimseler (Müminlerden bir kısım günahkârlar) müstesna. Bu tükenmez/kesintisiz bir lütuftur.');
INSERT INTO verses (sura, aya, text) VALUES (11, 109, 'Öyleyse sakın onların ibadet ettiği şeylerden kuşkun olmasın. Onlar ancak, evvelce babalarının tapındıkları gibi tapınıyorlar. Biz, onlara paylarını eksiksiz olarak vereceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (11, 110, 'Andolsun Biz Mûsâ’ya o Kitabı verdik de hakkında ayrılığa düşüldü. Daha önce Rabbin tarafından verilmiş bir söz olmasaydı, aralarında (azabın gelmesi için) hükmedilmiş olurdu. Onlar, hâlâ bundan şek ve şüphe içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (11, 111, 'Şüphesiz Rabbin onların her birine, yaptıklarının karşılığını tastamam verecektir. Şüphesiz Rabbin onların yaptıklarından hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (11, 112, 'Öyle ise emrolunduğun gibi dosdoğru ol. Beraberindeki tevbe edenler de dosdoğru olsunlar.Ve aşırı gitmeyin. Şüphesiz O, yaptıklarınızı hakkıyla görür.');
INSERT INTO verses (sura, aya, text) VALUES (11, 113, 'Bir de zulmedenlere meyletmeyin. Yoksa size de ateş dokunur. Sizin Allah’tan başka yardımcılarınız yoktur. Sonra size yardım da edilmez.');
INSERT INTO verses (sura, aya, text) VALUES (11, 114, '(Ey Muhammed!) Gündüzün iki tarafında ve gecenin gündüze yakın vakitlerinde namaz kıl. Çünkü iyilikler kötülükleri giderir. Bu, öğüt alanlar için bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (11, 115, '(Ey Muhammed!) Sabırlı ol! Çünkü Allah ihsan sahibi kimselerin mükâfatını zayi etmez.');
INSERT INTO verses (sura, aya, text) VALUES (11, 116, 'Sizden önceki nesiller arasında yeryüzünde fesâdı engelleyecek fazilet sahipleri olmalı değil miydi? Fakat onlardan, kurtuluşa erdirdiğimiz az bir kısmı müstesnadır. Zalimler ise, yalnız kendilerine verilen refahın ardına düştüler ve günahkâr kimseler oldular.');
INSERT INTO verses (sura, aya, text) VALUES (11, 117, 'Halkı ıslah eden kimseler iken, senin Rabbin o memleketleri zulüm ile helak edecek değildir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 118, 'Eğer Rabbin dileseydi, insanları tek bir millet/din üzere kılardı. Fakat onlar ihtilaf edip durmaktadırlar.');
INSERT INTO verses (sura, aya, text) VALUES (11, 119, 'Rabbinin rahmet ettikleri müstesnâ. Zaten onları bunun için yaratmıştır. Rabbinin: “Andolsun ki Ben cehennemi cin ve insanlarla dolduracağım” sözü de tümüyle gerçekleşmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 120, 'Peygamberlerin haberlerinden senin kalbine sebat verecek her şeyi sana anlatıyoruz. Bunlarda, sana hak, Müminlere de bir öğüt ve hatırlatma gelmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (11, 121, 'İman etmeyenlere şöyle de: "Elinizden gelen her şeyi yapın, ben de yapacağım."');
INSERT INTO verses (sura, aya, text) VALUES (11, 122, 'Bekleyin! Şüphesiz biz de bekleyicileriz.');
INSERT INTO verses (sura, aya, text) VALUES (11, 123, 'Göklerin ve yerin gaybı yalnız Allah’a mahsustur. Bütün işler O’na döndürülür. Öyle ise sadece O’na ibadet et ve O’na tevekkül edip, güven. Rabbin yaptıklarınızdan asla gafil değildir.');
INSERT INTO verses (sura, aya, text) VALUES (12, 1, 'Elif, Lâm, Râ.[1] Bunlar apaçık Kitab''ın ayetleridir.');
INSERT INTO verses (sura, aya, text) VALUES (12, 2, 'Biz, onu akledip anlayasınız diye Arapça bir Kur’an olarak indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (12, 3, 'Sana bu Kur’an’ı vahyetmekle kıssaların en güzelini anlatıyoruz. Hâlbuki daha önce sen bunlardan habersiz idin.');
INSERT INTO verses (sura, aya, text) VALUES (12, 4, 'Hani Yûsuf babasına şöyle demişti: “Babacığım, (rüyamda) on bir yıldız, Güneş''i ve Ay’ı gördüm. Gördüm ki onlar bana secde ediyorlardı.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 5, 'Babası, şöyle dedi: “Yavrucuğum! Rüyanı kardeşlerine sakın anlatma! Yoksa, sana tuzak kurarlar. Çünkü Şeytan, insanın apaçık düşmanıdır.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 6, '“İşte Rabbin seni böylece seçecek, sana (rüyada görülen) olayların yorumunu öğretecek ve daha önce ataların İbrahim ve İshak’a nimetlerini tamamladığı gibi sana ve Ya''kûb soyuna da tamamlayacaktır. Şüphesiz Rabbin hakkıyla bilendir, hüküm ve hikmet sahibidir.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 7, 'Andolsun, Yûsuf ve kardeşlerinde (hakikati arayıp) soranlar için ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (12, 8, 'Kardeşleri dediler ki: ''''Biz kalabalık bir topluluk olduğumuz halde, Yûsuf ve kardeşi (Bünyamin) babamıza bizden daha sevgilidir. Doğrusu babamız açık bir yanılgı içindedir.''''');
INSERT INTO verses (sura, aya, text) VALUES (12, 9, '“Yûsuf’u öldürün veya onu bir yere atın ki babanız sadece size yönelsin. Ondan sonra (tövbe edip) salih kimseler olursunuz.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 10, 'Onlardan bir sözcü, “Yûsuf’u öldürmeyin, onu bir kuyunun dibine bırakın ki geçen kervanlardan biri onu bulup alsın. Eğer yapacaksanız böyle yapın” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 11, 'Babalarına şöyle dediler: “Ey babamız! Yûsuf hakkında bize neden güvenmiyorsun? Hâlbuki biz onun iyiliğini isteyen kişileriz.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 12, '''Yarın onu bizimle beraber gönder de gezip oynasın. Biz onu mutlaka koruruz.''''');
INSERT INTO verses (sura, aya, text) VALUES (12, 13, 'Babaları: “Doğrusu onu götürmeniz beni üzer, siz ondan habersiz iken onu kurt yer, diye korkuyorum.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 14, 'Onlar da: “Andolsun biz kuvvetli bir topluluk iken onu kurt yerse (o takdirde) biz gerçekten hüsrana uğrayanlardan oluruz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 15, 'Yûsuf''u götürüp bir kuyunun derinliklerine bırakmayı kararlaştırdıklarında, biz ona, “Şüphesiz sen, farkında olmadıkları bir sırada, bu yaptıklarını onlara haber vereceksin” diye vahyettik.');
INSERT INTO verses (sura, aya, text) VALUES (12, 16, 'Akşam, ağlaya ağlaya babalarına geldiler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 17, '"Ey babamız, biz yarış yapalım diye gittik; Yûsuf’u da eşyamızın yanında bırakmıştık. (Bir de ne görelim) onu kurt yemiş. Her ne kadar doğru söylesek de sen bize inanmazsın'''' dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 18, 'Bir de üzerine, sahte bir kan bulaştırılmış gömleğini getirdiler. Ya''kûb dedi ki: “Hayır! Nefisleriniz sizi aldatıp böyle bir işe sürükledi. Artık bana düşen, güzel bir sabırdır. Anlattıklarınıza karşı yardımı istenilecek de ancak Allah’tır.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 19, 'Bir kervan gelmiş, sucularını suya göndermişlerdi. Sucu kovasını kuyuya salınca; “Müjde! Müjde! İşte bir oğlan!” dedi. Onu alıp bir ticaret malı olarak sakladılar. Oysa Allah, onların yaptıklarını biliyordu.');
INSERT INTO verses (sura, aya, text) VALUES (12, 20, '(Kafile Mısır''a vardığında) onu düşük bir fiyata, sayılı birkaç dirheme sattılar. Bunların ona rağbetleri yoktu.');
INSERT INTO verses (sura, aya, text) VALUES (12, 21, 'Onu satın alan Mısırlı kişi, hanımına dedi ki: “Ona iyi bak. Belki bize yararı dokunur veya onu evlat ediniriz.” İşte böylece biz Yûsuf’u o yere (Mısır’a) yerleştirdik ve ona (rüyadaki) olayların yorumunu öğretelim diye böyle yaptık. Allah, emrini yerine getirmeye kadirdir. Fakat insanların çoğu (bunu) bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 22, 'Yûsuf, ergenlik çağına girince, ona hüküm ve ilim verdik, işte biz, iyileri böyle mükâfatlandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (12, 23, 'Evinde bulunduğu kadın (gönlünü ona kaptırıp) ondan arzuladığı şeyi elde etmek istedi ve kapıları kilitleyerek, “Haydi gelsene!” dedi. O ise, “Allah’a sığınırım, çünkü o (kocan) benim efendimdir, bana iyi baktı. Şüphesiz zalimler kurtuluşa eremezler.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 24, 'Andolsun, kadın onu arzulamıştı. Eğer Rabbinin burhanını görmemiş olsaydı, Yûsuf da ona istek duyacaktı. Biz, ondan kötülüğü ve fuhşu uzaklaştırmak için işte böyle yaptık. Çünkü o, ihlâsa erdirilmiş kullarımızdandı.');
INSERT INTO verses (sura, aya, text) VALUES (12, 25, 'İkisi de kapıya koştular. Kadın, Yûsuf’un gömleğini arkadan yırttı. Kapının yanında hanımın efendisine rastladılar. Kadın dedi ki: “Senin ailene kötülük yapmak isteyenin cezası, ancak zindana atılmak veya can yakıcı bir azaptır.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 26, 'Yûsuf: “O, benden arzusunu elde etmek istedi” dedi. Kadının ailesinden bir şahit de şöyle şahitlik etti: “Eğer onun gömleği önden yırtılmışsa, kadın doğru söylemiştir, o (Yûsuf) yalancılardandır.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 27, '“Eğer gömleği arkadan yırtılmışsa, kadın yalan söylemiştir. O (Yûsuf) ise, doğru söyleyenlerdendir.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 28, 'Kadının kocası Yûsuf’un gömleğinin arkadan yırtıldığını görünce, dedi ki: “Şüphesiz bu, siz kadınların hilesidir. Doğrusu siz kadınların hilesi büyüktür” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 29, '“Ey Yûsuf! Sen bundan (bu hadiseyi söylemekten) kaçın. (Ey Kadın!) Sen de günahının bağışlanmasını dile. Çünkü sen günah işleyenlerdensin.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 30, 'Şehirde birtakım kadınlar, “Aziz’in karısı, (hizmetçisi olan) delikanlısından arzusunu elde etmek istemiş. Ona olan aşkı yüreğine işlemiş. Şüphesiz biz onu açık bir şaşkınlık içinde görüyoruz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 31, 'O kadınların gizlice aleyhinde konuştuklarını işitince kendilerine haber gönderdi. Onlar için oturup yaslanacakları yer hazırladı. Her birine birer de bıçak verdi ve Yûsuf’a: “Çık karşılarına” dedi. Kadınlar Yûsuf’u görünce, onu pek büyüttüler ve şaşkınlıkla ellerini kestiler. “Hâşâ! Allah için, bu bir insan değil, ancak şerefli bir melektir.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 32, 'Kadın dedi ki: “Kendisi dolayısı ile beni ayıpladığınız işte budur. Andolsun, ben onu arzuladım. Fakat o, iffetinden dolayı bundan kaçındı. Andolsun, eğer emrettiğimi yapmazsa, mutlaka zindana atılacak ve zillete uğrayanlardan olacak.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 33, 'Yûsuf: “Ey Rabbim! Zindan bana, bunların beni dâvet ettiği şeyden daha sevimlidir. Onların tuzaklarını benden uzaklaştırmazsan, onlara meyleder ve cahillerden olurum.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 34, 'Bunun üzerine Rabbi onun duasını kabul etti ve o kadınların hilesini uzaklaştırdı. Hiç şüphe yoktur ki Allah, her şeyi hakkıyla işitendir; hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (12, 35, 'Sonra onlara (Yûsuf''un iffetine ilişkin) delilleri görmelerinin ardından, onu belli bir vakte kadar zindana atma (görüşü) belirdi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 36, 'Onunla beraber zindana iki delikanlı daha girdi. Biri: “Ben rüyamda şaraplık üzüm sıktığımı gördüm” dedi. Diğeri: “Ben de rüyamda başımın üzerinde, kuşların yediği bir ekmek taşıdığımı gördüm. Bize bunun yorumunu haber ver. Doğrusu biz seni, ihsan sahiplerinden görmekteyiz” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 37, 'Yûsuf dedi ki: “Size, rızık olarak verilen yemek henüz ulaşmadan ben size onun ne olduğunu mutlaka haber veririm. Bu, bana Rabbimin öğrettiklerindendir. Ben, Allah’a iman etmeyen ve ahireti inkâr eden bir milletin dinini terk ettim.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 38, '“Atalarım İbrahim, İshak ve Ya''kûb’un dinine tâbi oldum. Allah''a her hangi bir ortak koşmak bize yaraşmaz. Bu, bize ve insanlara Allah’ın bir lütfudur, fakat insanların çoğu şükretmezler.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 39, '“Ey zindan arkadaşlarım! Ayrı ayrı ilâhlar mı daha iyidir, yoksa mutlak hâkimiyet sahibi olan tek Allah mı?”');
INSERT INTO verses (sura, aya, text) VALUES (12, 40, '“Allah''ı bırakıp da taptıklarınız, sizin ve atalarınızın taktığı birtakım isimlerden başka bir şey değildir. Allah onlar hakkında herhangi bir delil indirmemiştir. Hüküm ancak Allah’a aittir. O size kendisinden başkasına ibadet etmemenizi emretmiştir. İşte en doğru din budur. Fakat insanların çoğu bilmezler.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 41, '“Ey zindan arkadaşlarım! (Rüyanızın yorumuna gelince,) biriniz efendisine şarap sunacak, diğeri ise asılacak ve kuşlar başından yiyecektir. Yorumunu sorduğunuz iş (artık) olup bitmiştir.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 42, 'Yûsuf, bu ikisinden kurtulacağını düşündüğü kişiye: “Efendinin yanında beni an!”, dedi. Fakat şeytan, efendisinin yanında, ondan (Yûsuf''tan) söz etmeyi ona unutturdu da bu yüzden o, birkaç yıl daha zindanda kaldı.');
INSERT INTO verses (sura, aya, text) VALUES (12, 43, 'Kral: “Ben rüyamda yedi semiz ineği, yedi zayıf ineğin yediğini; ayrıca yedi yeşil başak ve yedi de kuru başak görüyorum. Ey ileri gelenler! Eğer rüya yorumluyorsanız, rüyamı bana yorumlayın.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 44, 'Dediler ki: “Bunlar karmakarışık rüyalardır. Biz böyle rüyaların yorumunu bilenlerden değiliz.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 45, 'Zindandaki iki kişiden kurtulmuş olan, uzun bir süre sonra (Yûsuf’u) hatırladı ve: “Ben size onun yorumunu haber veririm, hemen beni (Yûsuf''a) gönderin.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 46, '(Zindana varınca), “Yûsuf! Ey doğru sözlü! Rüyada yedi semiz ineği yedi zayıf ineğin yemesi, bir de yedi yeşil başakla diğer yedi kuru başak hakkında bize yorum yap. Ümid ederim ki (vereceğin bilgi ile) insanlara dönerim de onlar da (senin değerini) bilirler” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 47, 'Yûsuf dedi ki: “Yedi yıl her zamanki gibi ekin. Birazını yiyip biçtiğiniz ekini başağında bırakın."');
INSERT INTO verses (sura, aya, text) VALUES (12, 48, 'Sonra bunun ardından, saklayacaklarınızdan az bir miktar (tohumluk) hariç, o yıllar için biriktirdiklerinizi yeyip bitirecek yedi kıtlık yılı gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (12, 49, '“Sonra bunun ardından insanların yağmura kavuşacağı bir yıl gelecek. O zaman (bol rızka kavuşup şıra ve yağ gibi ürünleri) sıkacaklar.''''');
INSERT INTO verses (sura, aya, text) VALUES (12, 50, 'Kral: “Onu bana getirin” dedi. Elçi, Yûsuf’a gelince (Yûsuf) dedi ki: “Efendine dön de, ellerini kesen o kadınlara ne oldu, diye sor. Şüphesiz Rabbim onların hilesini hakkıyla bilendir.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 51, 'Kral, kadınlara: “Yûsuf’u arzuladığınız zaman durumunuz neydi?” dedi. Kadınlar: “Hâşâ! Allah için, biz onun bir kötülüğünü bilmiyoruz” dediler. Aziz’in karısı ise: “Şimdi gerçek ortaya çıktı. Ondan ben murad almak istedim. Şüphesiz Yûsuf doğru söyleyenlerdendir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 52, '(Yûsuf), “Benim böyle yapmam, Aziz’in yokluğunda, benim kendisine hainlik etmediğimi ve Allah’ın hainlerin tuzaklarını başarıya ulaştırmayacağını bilmesi içindi.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 53, '"Ben nefsimi temize çıkarmam. Çünkü Rabbimin merhamet ettiği hariç, nefis aşırı derecede kötülüğü emreder. Şüphesiz Rabbim çok bağışlayandır, çok merhamet edendir'''' dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 54, 'Hükümdar: "Onu bana getirin, kendime has (müsteşar) alayım." dedi. Onunla konuşunca: "Şüphesiz bugün sen yanımızda yüksek makam sahibi ve güvenilir bir kişisin."');
INSERT INTO verses (sura, aya, text) VALUES (12, 55, 'Yûsuf: “Beni ülkenin hazinelerine bakmakla görevlendir. Çünkü ben iyi koruyucu ve bilgili bir kişiyim” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 56, 'Böylece Yûsuf’a, dilediği yerde konaklamak üzere ülkede imkân ve iktidar verdik. Biz rahmetimizi istediğimize veririz ve iyi davrananların mükâfatını zayi etmeyiz.');
INSERT INTO verses (sura, aya, text) VALUES (12, 57, 'Elbetteki, ahiret mükâfatı, iman edenler ve Allah’a karşı gelmekten sakınanlar için daha iyidir.');
INSERT INTO verses (sura, aya, text) VALUES (12, 58, 'Yûsuf’un kardeşleri gelip onun huzuruna girdiler. O (Yûsuf) kendilerini tanıdığı halde onlar onu tanımadılar.');
INSERT INTO verses (sura, aya, text) VALUES (12, 59, 'Yûsuf, onların yüklerini hazırlatınca dedi ki: “Sizin, baba bir kardeşinizi de bana getirin. Görmüyor musunuz? Ölçeği tam dolduruyorum ve ben misafir ağırlayanların en iyisiyim.”');
INSERT INTO verses (sura, aya, text) VALUES (12, 60, 'Eğer onu bana getirmezseniz, artık benim yanımda size verilecek tek ölçek (zahire) bile yoktur ve bir daha da bana yaklaşmayın.');
INSERT INTO verses (sura, aya, text) VALUES (12, 61, '“Onu babasından istemeye çalışacağız. Kuşkusuz bunu yapacağız.');
INSERT INTO verses (sura, aya, text) VALUES (12, 62, 'Yûsuf, memurlarına dedi ki: “Onların ödedikleri ölçek bedellerini yüklerinin içine koyun. Umulur ki ailelerine varınca onu anlarlar da belki yine dönüp gelirler."');
INSERT INTO verses (sura, aya, text) VALUES (12, 63, 'Onlar, babalarına döndüklerinde: “Ey babamız! Bize artık erzak verilmeyecek. Kardeşimizi (Bünyamin’i) bizimle gönder ki erzak alalım. Onu biz elbette koruruz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 64, 'Ya''kûb onlara: “Onun hakkında size ancak, daha önce kardeşi hakkında güvendiğim kadar güvenebilirim! Allah en iyi koruyandır ve O, merhametlilerin en merhametlisidir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 65, 'Yüklerini açıp zahire bedellerinin kendilerine geri verildiğini gördüler. “Ey babamız! Daha ne isteriz? İşte ödediğimiz bedeller de bize geri verilmiş. Onunla yine ailemize yiyecek getirir, kardeşimizi korur ve bir deve yükü zahire de fazladan alırız. Çünkü bu getirdiğimiz az bir miktardır.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 66, 'Babaları: “ Kuşatılıp çaresiz durumda kalmanız dışında, onu bana geri getireceğinize dair Allah adına sağlam bir söz vermedikçe, onu sizinle göndermeyeceğim” dedi. Ona güvencelerini verdiklerinde, “Allah söylediklerimize vekildir” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 67, '“Ey oğullarım, hepiniz (Mısır’a) bir kapıdan girmeyin, ayrı ayrı kapılardan girin. Bununla beraber Allah’dan size gelecek hiçbir şeyi sizden geri çeviremem. Hüküm ancak Allah’ındır. Ben, yalnız O’na güvenip dayandım. Tevekkül edenler de yalnız O’na güvenip dayanmalıdır” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 68, 'Babalarının emrettiği şekilde (ayrı kapılardan) girdiklerinde (bile) bu, Allah’tan gelecek hiçbir şeyi onlardan uzaklaştıracak değildi. Sadece Ya''kûp, içindeki bir dileği ortaya koymuş oldu. Şüphesiz o, biz kendisine öğrettiğimiz için bilgi sahibidir. Fakat insanların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 69, 'Yûsuf’un huzuruna girdiklerinde; o, kardeşini yanına çekti bağrına bastı ve (gizlice) “Haberin olsun ben senin kardeşinim, artık onların yaptıklarına üzülme!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 70, 'Yûsuf, onların yüklerini hazırlatırken su kabını kardeşinin yüküne koydurdu. Sonra bir münâdi: “Ey kafile (durun)! Siz gerçekten hırsızlık yaptınız.” diye bağırdı.');
INSERT INTO verses (sura, aya, text) VALUES (12, 71, 'Yûsuf ’un kardeşleri onlara dönerek: “Ne kaybettiniz?” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 72, 'Onlar: “Hükümdarın (ölçü) kabını kaybettik. Onu getirene bir deve yükü ödül var. (Münadi): Ben buna kefilim” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 73, '“Allah’a andolsun, siz de biliyorsunuz ki biz bu ülkede fesat çıkarmak için gelmedik, hırsız da değiliz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 74, 'Onlar: “Eğer yalancı iseniz, hırsızlığın cezası nedir?” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 75, 'Onlar da: “Cezası, su kabı kimin yükünde bulunursa, o kimsenin kendisi(nin alıkonması) onun cezasıdır. Biz zalimleri böyle cezalandırırız.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 76, 'Yûsuf kardeşinin yükünden önce onlarınkini aramaya başladı; sonra kardeşinin yükünden su kabını çıkardı. İşte biz Yûsuf''a böyle bir plan kullanmasını vahyettik. Çünkü hükümdarın kanunlarına göre kardeşini alıkoyamazdı. Ancak Allah''ın dilemesi başka. Dilediğimizi derecelerle yükseltiriz. Her ilim sahibinden üstün bir bilen bulunur.');
INSERT INTO verses (sura, aya, text) VALUES (12, 77, 'Dediler ki: “Eğer o çalmış bulunuyorsa, daha önce onun bir kardeşi de çalmıştı.” Yûsuf, bu (sözleri) içinde gizledi ve onlara belli etmedi. İçinden, “Siz kötü bir durumdasınız; anlattığınızı Allah çok daha iyi biliyor.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 78, 'Onlar, Yûsuf ’a: “Ey Aziz! Onun çok yaşlı bir babası var. Onun yerine bizden birini alıkoy. Şüphesiz biz senin iyilik edenlerden olduğunu görüyoruz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 79, 'Yûsuf : “Malımızı yanında bulduğumuz kimseden başkasını tutmaktan Allah’a sığınırız. Şüphesiz biz o takdirde zulmetmiş oluruz.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 80, 'Ondan ümitlerini kesince, kendi aralarında konuşmak üzere bir kenara çekildiler. Büyükleri dedi ki: “Babanızın Allah adına sizden söz aldığını, daha önce de Yûsuf hakkında işlediğiniz kusuru bilmiyor musunuz? Artık babam bana izin verinceye veya Allah, hakkımda hükmedinceye kadar buradan asla ayrılmayacağım. O, hükmedenlerin en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (12, 81, '“Siz babanıza dönün ve deyin ki: “Ey babamız! Şüphesiz oğlun hırsızlık etti, biz ancak bildiğimize şahitlik ettik. (Sana söz verdiğimiz zaman) gaybı (oğlunun hırsızlık edeceğini) bilemezdik.');
INSERT INTO verses (sura, aya, text) VALUES (12, 82, 'Bulunduğumuz kasaba halkına ve aralarında olduğumuz kervana da sor. Biz gerçekten doğru söyleyenleriz.');
INSERT INTO verses (sura, aya, text) VALUES (12, 83, 'Ya''kûp , “Nefisleriniz sizi bir iş yapmaya sürükledi. Artık bana düşen, güzel bir sabırdır. Umulur ki, Allah onların hepsini bana getirir. Çünkü O, hakkıyla bilendir, hüküm ve hikmet sahibidir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 84, 'Onlardan yüz çevirdi ve, “Vah! Yûsuf’a vah!” dedi ve üzüntüden iki gözüne ak düştü. O artık acısını içinde saklıyordu.');
INSERT INTO verses (sura, aya, text) VALUES (12, 85, 'Oğulları: “Allah’a yemin ederiz ki, sen hâlâ Yûsuf’u anıp duruyorsun. Sonunda üzüntüden eriyip gideceksin veya helâk olacaksın.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 86, 'Ya''kûb, “Ben tasa ve üzüntümü ancak Allah’a arz ederim. Ben, Allah tarafından sizin bilmediğiniz şeyleri bilirim” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 87, 'Oğullarım! Gidin, Yûsuf’u ve kardeşini arayın, araştırın; Allah’ın rahmetinden de ümit kesmeyin. Çünkü kâfirler topluluğundan başkası Allah’ın rahmetinden ümit kesmez.');
INSERT INTO verses (sura, aya, text) VALUES (12, 88, 'Bunun üzerine (Mısır’a dönüp) Yûsuf’un yanına girdiklerinde: “Ey Aziz! Bize ve ailemize darlık ve sıkıntı dokundu. Değersiz bir sermaye ile geldik. Yiyeceğimizi tam ölç, ayrıca bize sadaka ver. Şüphesiz Allah, sadaka verenleri mükâfatlandırır” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 89, 'Yûsuf dedi ki: Siz (henüz) cahil kimseler iken Yûsuf ve kardeşine neler yaptığınızı hatırlıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (12, 90, 'Kardeşleri: “Yoksa sen, sen Yûsuf musun?” dediler. O da, “Ben Yûsuf’um, bu da kardeşim. Allah, bize lütufta bulundu. Çünkü, kim kötülükten sakınır ve sabrederse, şüphesiz Allah iyilik yapanların mükâfatını zayi etmez.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 91, 'Dediler ki: Allah’a andolsun, gerçekten Allah seni bize üstün kıldı. Gerçekten biz suç işlemiştik.');
INSERT INTO verses (sura, aya, text) VALUES (12, 92, 'Yûsuf dedi ki: "Bugün size kınama yok. Allah sizi bağışlasın. O, merhametlilerin en merhametlisidir."');
INSERT INTO verses (sura, aya, text) VALUES (12, 93, 'Bu gömleğimi götürün de babamın yüzüne sürün ki, gözleri açılsın ve bütün ailenizi bana getirin” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 94, 'Kafile (Mısır’dan) ayrılınca babaları (etrafındakilere) dedi ki: "Bana bunak demeyecekseniz, inanın ki Yûsuf’un kokusunu alıyorum."');
INSERT INTO verses (sura, aya, text) VALUES (12, 95, 'Onlar da: “Allah’a yemin ederiz ki sen hâlâ eski şaşkınlığındasın” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 96, 'Müjdeci gelip gömleği Ya''kûb’un yüzüne bırakınca gözleri açılıverdi. Ya''kûb, “Ben size, Allah tarafından, sizin bilemeyeceğiniz şeyleri bilirim demedim mi?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 97, 'Oğulları: “Ey babamız, günahlarımızın bağışlanmasını dile. Biz gerçekten suçlu idik” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 98, 'Ya''kûb: “Rabbimden sizin bağışlanmanızı dileyeceğim. Şüphesiz O, çok bağışlayandır, çok merhamet edendir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 99, 'Yûsuf’un huzuruna girdiklerinde; Yûsuf ana babasını bağrına bastı ve “Allah’ın iradesi ile güven içinde Mısır’a girin” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (12, 100, 'Babasını ve annesini tahtın üzerine çıkartıp oturttu. Hepsi onun için secde ettiler. Yûsuf dedi ki: “Babacığım! İşte bu, daha önce gördüğüm rüyanın yorumudur. Rabbim onu gerçekleştirdi. Şeytan benimle kardeşlerimin arasını bozduktan sonra Rabbim beni zindandan çıkararak ve sizi çölden getirerek bana çok iyilikte bulundu. Şüphesiz Rabbim, dilediği şeyde nice incelikler sergileyendir. Şüphesiz O, hakkıyla bilendir, hüküm ve hikmet sahibidir."');
INSERT INTO verses (sura, aya, text) VALUES (12, 101, 'Rabbim! Gerçekten bana mülk verdin ve bana sözlerin yorumunu öğrettin. Ey gökleri ve yeri yaratan! Dünyada ve ahirette sen benim velimsin. Benim canımı Müslüman olarak al ve beni iyilere kat.');
INSERT INTO verses (sura, aya, text) VALUES (12, 102, '(Ey Muhammed!) İşte bu, sana vahyettiğimiz gayb haberlerindendir. Yoksa onlar (Yûsuf’un kardeşleri) hile yaparak işlerini kararlaştırdıkları zaman sen yanlarında değildin.');
INSERT INTO verses (sura, aya, text) VALUES (12, 103, 'Sen ne kadar şiddetle arzu etsen de insanların çoğu iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 104, 'Hâlbuki sen buna karşılık onlardan bir ücret de istemiyorsun. O (Kur’an) âlemler içinde ancak bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (12, 105, 'Göklerde ve yerde nice ayetler/deliller vardır ki yanlarına uğrarlar da onlardan yüzlerini çevirerek geçerler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 106, 'Onların çoğu Allah’a ancak şirk koşarak iman ederler.');
INSERT INTO verses (sura, aya, text) VALUES (12, 107, 'Yoksa Allah tarafından kendilerini kuşatacak bir azabın gelmeyeceğinden veya onlar farkında olmadan kıyametin ansızın gelip çatmayacağından emin mi oldular?');
INSERT INTO verses (sura, aya, text) VALUES (12, 108, 'De ki: Bu, benim yolumdur, ben ve bana uyanlar basiretle Allah’a davet ederiz. Allah’ı tenzih ederim. Ben müşriklerden değilim.');
INSERT INTO verses (sura, aya, text) VALUES (12, 109, 'Biz senden önce de, şehirler halkından ancak kendilerine vahyettiğimiz birtakım erkekleri peygamber olarak gönderdik. Yeryüzünde dolaşıp da, kendilerinden önce gelenlerin akıbetlerinin nasıl olduğuna bakmadılar mı? Elbette ahiret yurdu Allah’a karşı gelmekten sakınanlar için daha iyidir. Hâlâ aklınızı kullanmıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (12, 110, 'Nihayet peygamberler (kendilerini yalanlayanların imanlarından) ümitlerini kesip de yalanlandıklarını düşündükleri sırada, onlara yardımımız geldi de, böylece dilediğimiz kimseler kurtuluşa erdirildi. Azabımız ise suçlular topluluğundan geri çevrilemez.');
INSERT INTO verses (sura, aya, text) VALUES (12, 111, 'Andolsun ki, onların kıssalarında akıl sahipleri için ibret vardır. Kur’an, uydurulabilecek bir söz değildir. Fakat kendinden öncekileri tasdik eden, her şeyi ayrı ayrı açıklayan ve iman eden bir toplum için de bir yol gösterici ve bir rahmettir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 1, 'Elif Lâm Mîm Râ.[1] İşte bunlar kitabın ayetleridir. Sana Rabbinden indirilen (bu Kur''an) haktır, fakat insanların çoğu iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (13, 2, 'Allah, gökleri gördüğünüz gibi herhangi bir direk olmadan yükselten, sonra Arş’a istiva eden, Güneş''e de Ay''a da emrine boyun eğdirendir. Bunların hepsi belli bir zamana kadar akıp gitmektedir. O, her işi yerli yerince düzenler, ayetleri ayrı ayrı açıklar ki, Rabbinize kavuşacağınıza kesin olarak iman edesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (13, 3, 'O, yeryüzünü yayıp döşeyen, orada sabit dağlar, nehirler var eden, orada her türlü meyveden (erkekli-dişili) iki eş yaratan gündüzü geceyle bürüyendir. Şüphesiz bunlarda, düşünen bir kavim için deliller vardır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 4, 'Yeryüzünde birbirine komşu kara parçaları, üzüm bağları, ekinler; bir kökten çıkan çok gövdeli ve tek gövdeli hurma ağaçları vardır ki hepsi aynı su ile sulanır. Ama biz ürünleri konusunda bir kısmını bir kısmına üstün kılıyoruz. Şüphesiz bunda aklını kullanan bir kavim için (Allah’ın varlığını gösteren) deliller vardır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 5, 'Eğer şaşacaksan, asıl şaşılacak olan onların, “Biz toprak olunca yeniden mi yaratılacakmışız?” demeleridir. İşte bunlar Rablerini inkâr edenlerdir. İşte onlar boyunlarına demir halkalar vurulanlardır ve işte onlar cehennemliklerdir. Onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 6, 'Bir de senden, iyilikten önce kötülüğün acele gelmesini istiyorlar. Hâlbuki onlardan önce nice örnekler gelip geçmiştir. Şüphesiz Rabbin, zulümlerine rağmen insanlara yine de mağfiret edendir. Bununla beraber Rabbinin azabı pek şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 7, 'Küfre sapanlar, “Ona Rabbinden bir mucize indirilseydi ya!” diyorlar. Sen ancak bir uyarıcısın. Her kavim için de bir yol gösteren vardır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 8, 'Allah, her dişinin neye gebe olduğunu, rahimlerin arttırdığı şeyi ve eksilttiği şeyi bilir. O’nun katında her şey bir ölçü iledir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 9, 'O, görünmeyeni de görüneni de bilendir. O çok büyüktür, yüksektir, yüceler yücesidir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 10, '(O’na göre) içinizden sözü gizleyen ile açığa vuran, geceleyin gizlenenle gündüz ortaya çıkan birdir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 11, 'İnsanı önünden ve ardından takip eden melekler vardır. Allah’ın emriyle onu koruyup gözetirler. Şüphesiz ki, bir kavim kendi durumunu değiştirmedikçe Allah onların durumunu değiştirmez. Allah, bir kavme kötülük diledi mi, artık o geri çevrilemez. Onlar için Allah’tan başka hiçbir yardımcı da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (13, 12, 'O, korku ve ümit vermek için size şimşeği gösteren, yağmur yüklü bulutları meydana getirendir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 13, 'Gök gürültüsü O’na hamd ederek tesbih eder, Melekler de O’nun korkusundan tesbih ederler. O, yıldırımlar gönderir de onlarla dilediğini çarpar. Onlar ise Allah hakkında mücadele ediyorlar. Hâlbuki O, azabı çok şiddetli olandır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 14, 'Gerçek dua/ibadet yalnızca O’nadır. O’ndan başka dua ettikleri, kendilerine hiçbir şekilde karşılık veremezler. Onların durumu; ağzına gelsin diye suya doğru iki avucunu (uzaktan) açan kimse gibidir. Halbuki su (ağzına) ulaşacak değildir. İşte kâfirlerin duası delalet içinde olmaktan başka birşey değildir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 15, 'Hâlbuki göklerde ve yerde bulunanlar da onların gölgeleri de sabah akşam ister istemez sadece Allah''a secde ederler.');
INSERT INTO verses (sura, aya, text) VALUES (13, 16, 'De ki: “Göklerin ve yerin Rabbi kimdir?” “Allah’tır” de. De ki: “O''nu bırakıp da kendilerine (bile) bir faydası ve zararı olmayan dostlar (mabutlar) mı edindiniz?” De ki: “Kör ile gören bir olur mu? Ya da karanlıklarla aydınlık bir olur mu? Yoksa Allah’a, O’nun yarattığı gibi yaratan ortaklar buldular da bu yaratma ile Allah’ın yaratması onlara göre birbirine mi benzedi?” De ki: “Her şeyin yaratıcısı Allah’tır. O, birdir, Kahhâr''dır/mutlak galiptir.''''');
INSERT INTO verses (sura, aya, text) VALUES (13, 17, 'O, gökten su indirdi de dereler kendi ölçülerince dolup aktı ve sel, üste çıkan köpüğü aldı götürdü. Süs eşyası veya yararlanılacak bir şey elde etmek için ateşte erittikleri şeylerden de böyle köpük olur. İşte Allah, hak ile batıla böyle misal getirir. Köpüğe gelince sönüp gider. İnsanlara yararlı olan ise yerde kalır. İşte Allah, böyle misaller verir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 18, 'Rablerinin çağrısına uyanlara mükâfatın en güzeli (Cennet) vardır. O’nun çağrısına uymayanlar ise, yeryüzünde olan her şey ve onun yanında bir katı daha kendilerinin olsa, kurtulmak için hepsini fidye olarak verirlerdi. İşte hesabın kötüsü bunlar içindir. Varacakları yer de Cehennem''dir. O ne kötü yataktır!');
INSERT INTO verses (sura, aya, text) VALUES (13, 19, 'Rabbinden sana indirilenin hak olduğunu bilen kimse, (O''na iman etmeyen) kör kimse gibi midir? (Bunu) ancak akıl sahipleri anlar.');
INSERT INTO verses (sura, aya, text) VALUES (13, 20, 'Onlar, Allah’a verdikleri sözü eksiksiz yerine getirir ve anlaşmayı bozmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (13, 21, 'Onlar Allah’ın birleştirmesini emrettiği şeyi bitiştirirler. Rablerinden korkarlar ve kötü hesaptan endişe ederler.');
INSERT INTO verses (sura, aya, text) VALUES (13, 22, 'Onlar, Rablerinin rızasına ermek için sabreder, namazı dosdoğru kılar, kendilerine verdiğimiz rızıklardan gizli olarak ve açıktan Allah için harcar ve kötülüğü iyilikle savarlar. İşte bunlar için dünya yurdunun iyi sonucu vardır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 23, '(Bu güzel sonuç da) Adn Cennetleridir. Atalarından, eşlerinden ve çocuklarından iyi olanlarla beraber oraya girerler. Melekler de her bir kapıdan yanlarına girerler (ve şöyle derler):');
INSERT INTO verses (sura, aya, text) VALUES (13, 24, '''Sabretmenize karşılık selâm sizlere. Dünya yurdunun sonucu (olan Cennet) ne güzeldir!''''');
INSERT INTO verses (sura, aya, text) VALUES (13, 25, 'Allah''a verdikleri sözü kuvvetle sağlamlaştırdıktan sonra bozanlar, Allah''ın birleştirilmesini emrettiği şeyleri ayıranlar ve yeryüzünde fesat çıkaranlar; işte lanet onlar içindir. Ve kötü yurt (Cehennem) onlarındır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 26, 'Allah, rızkı dilediğine bol verir, (dilediğine de) kısar. Onlar ise dünya hayatı ile sevinmektedirler. Hâlbuki dünya hayatı, ahiretin yanında çok az bir geçimliktir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 27, 'Kâfir olanlar: “Kendisine Rabbinden bir âyet (mûcize) indirilmeli değil miydi?” derler. De ki: “Şüphesiz Allah dilediğini saptırır ve kendisine yönelenleri de doğru yola iletir.”');
INSERT INTO verses (sura, aya, text) VALUES (13, 28, 'Bunlar, iman edenler ve gönülleri Allah''ın zikriyle sükûnete erenlerdir. Bilesiniz ki, kalpler ancak Allah''ı zikretmekle huzur bulur.');
INSERT INTO verses (sura, aya, text) VALUES (13, 29, 'İman edip salih amellerde bulunanlar için, güzel bir hayat vardır ve güzel dönüş yeri de onlarındır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 30, '(Ey Muhammed!) Böylece seni, kendilerinden önce nice ümmetlerin gelip geçtiği bir ümmete gönderdik ki; sana vahyettiklerimizi onlara okuyasın. Halbuki onlar Rahman’ı inkâr ediyorlar. De ki: O (Rahman) benim Rabbimdir, O’ndan başka (hak) ilah yoktur. Ben yalnız O’na tevekkül ettim, dönüşüm de yalnız O’nadır!');
INSERT INTO verses (sura, aya, text) VALUES (13, 31, 'Kendisiyle dağların yürütüleceği veya yeryüzünün parçalanacağı ya da ölülerin konuşturulacağı bir Kur’an olacak olsaydı (o yine bu kitap olurdu). Fakat bütün emirler yalnız Allah’ındır. İman edenler bilmiyorlar mı ki, Allah dileseydi bütün insanlara hidayet ederdi. Allah’ın vaadi yerine gelinceye kadar devamlı olarak yaptıkları işler sebebiyle kâfirlere ya ansızın büyük bir bela gelecek veya o bela evlerinin yakınına inecektir. Şüphesiz Allah, vaadinden asla dönmez.');
INSERT INTO verses (sura, aya, text) VALUES (13, 32, 'Andolsun, senden önce de nice peygamberler alaya alındı da ben inkâr edenlere bir süre (mühlet) verdim, sonra da onları yakalayıverdim. Benim cezalandırmam nasılmış!');
INSERT INTO verses (sura, aya, text) VALUES (13, 33, 'Herkesin kazandığını görüp gözeten Allah''a (ortak koşulur mu?). Onlar, Allah’a ortaklar koştular. De ki: “Söyleyin bakalım onların isimlerini Yoksa siz (bununla) O’na yeryüzünde bilmediği bir şeyi mi haber veriyorsunuz, Yoksa siz üstün körü bir söz mü söylüyorsunuz?” Hayır, bilakis o kâfirlere tuzakları süslü gösterildi ve onlar doğru yoldan alıkondular. Allah, kimi saptırırsa, artık ona hidâyet verecek hiçbir kimse yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (13, 34, 'Onlara dünya hayatında bir azap vardır. Ahiret azabı ise daha ağırdır ve onları Allah’ın azabından koruyacak kimse de yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (13, 35, 'Allah’a karşı gelmekten sakınanlara va’dolunan Cennet''in durumu şudur: Onun içinden ırmaklar akar, yemişleri ve gölgeleri devamlıdır. İşte bu, Allah’a karşı gelmekten sakınanların sonudur. Kâfirlerin sonu ise ateştir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 36, 'Kendilerine kitap verdiklerimiz, sana indirilene (Kur''an''a) sevinirler; fakat (İslam aleyhinde birleşen) gruplardan, onun (sana indirilenin) bazısını inkâr edenler vardır. De ki: “Ben, yalnızca Allah''a ibadet etmek ve O''na ortak koşmamakla emrolundum. Ben ancak O''na davet ederim ve dönüşüm O''nadır.”');
INSERT INTO verses (sura, aya, text) VALUES (13, 37, 'Böylece biz onu (Kur’an’ı) Arapça bir hüküm olarak indirdik. Andolsun ki sana gelen bu ilimden sonra onların heva ve heveslerine uyarsan, Allah tarafından senin için ne bir dost, ne de bir koruyucu vardır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 38, 'Andolsun, senden önce de peygamberler gönderdik. Onlara da eşler ve çocuklar verdik. Allah’ın izni olmadan hiçbir peygamber bir mucize getiremez. Her ecelin (vadenin) bir yazısı vardır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 39, 'Allah, dilediğini siler, dilediğini de sabit kılıp bırakır. Ana kitap (Levh-i Mahfuz) O’nun katındadır.');
INSERT INTO verses (sura, aya, text) VALUES (13, 40, 'Onlara vadettiğimiz azabın bir kısmını sana göstersek de, (göstermeden) senin ruhunu alsak da senin görevin sadece tebliğ etmektir. Hesap görmek ise bize aittir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 41, 'Görmediler mi ki biz nasıl yeryüzüne gelip onu etrafından eksiltiyoruz? Allah, hükmeder. O’nun hükmünü bozacak hiçbir kimse yoktur. O, hesabı çabuk görendir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 42, 'Onlardan öncekiler de tuzak kurmuşlardı. Oysa tuzak tümüyle Allah''a aittir. O, her nefsin kazandığını bilir. Kâfirler de dünya yurdunun sonunun kime ait olduğunu bileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (13, 43, 'O kâfir olanlar: “Sen gönderilmiş bir peygamber değilsin” derler. De ki: “Benimle sizin aranızda şahit olarak Allah ve yanında kitabın (Kur''an''ın) bilgisi bulunanlar yeter.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 1, 'Elif, Lâm, Râ.[1] Bu, Rabbinin izniyle insanları karanlıklardan nura, O güçlü ve övgüye layık olanın yoluna çıkarmak için sana indirdiğimiz bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (14, 2, 'O Allah ki, göklerde ve yerde ne varsa O''nundur. Uğrayacakları şiddetli azaptan dolayı vay o kâfirlerin haline!');
INSERT INTO verses (sura, aya, text) VALUES (14, 3, 'Onlar, o kimselerdir ki, dünya hayatını ahiret üzerine tercih edip severler; Allah yolundan alıkoyarlar ve onun eğriliğini isterler. İşte bunlar, hakdan çok uzak bir sapıklık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (14, 4, 'Biz her peygamberi, ancak kendi kavminin diliyle gönderdik ki, onlara (Allah’ın emirlerini) iyice açıklasın. Allah, dilediğini saptırır, dilediğini de doğru yola iletir. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 5, 'Andolsun, Mûsâ’yı da, “Kavmini karanlıklardan aydınlığa çıkar ve onlara Allah’ın günlerini hatırlatarak öğüt ver" diye ayetlerimizle gönderdik. Şüphesiz bunda çok sabreden, çok şükreden herkes için ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (14, 6, 'Hani Mûsâ kavmine, “Allah’ın size olan nimetini anın. Hani o sizi, Firavun ailesinden kurtarmıştı. Onlar sizi işkencenin en ağırına uğratıyorlar, oğullarınızı boğazlayıp kadınlarınızı sağ bırakıyorlardı. İşte bunda size Rabbinizden büyük bir imtihan vardır” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (14, 7, 'Hani Rabbiniz şöyle duyurmuştu: “Andolsun, eğer şükrederseniz elbette size nimetimi artırırım. Eğer nankörlük ederseniz, hiç şüphesiz azabım çok şiddetlidir.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 8, 'Mûsâ, şöyle dedi: "Siz ve yeryüzünde bulunanların hepsi nankörlük etseniz de gerçek şu ki, Allah çok zengindir, övgüye lâyık olandır."');
INSERT INTO verses (sura, aya, text) VALUES (14, 9, 'Sizden önceki Nûh, Âd ve Semûd kavimlerinin ve onlardan sonrakilerin –ki onları Allah’tan başkası bilmez- haberi size gelmedi mi? Onlara peygamberleri mucizeler getirdiler de onlar (öfkeden parmaklarını ısırmak için) ellerini ağızlarına götürüp; “Biz sizinle gönderileni inkâr ediyoruz. Bizi çağırdığınız şeyden de derin bir şüphe içindeyiz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (14, 10, 'Peygamberleri dedi ki: “Gökleri ve yeri yaratan Allah hakkında mı şüphe ediyorsunuz? (Hâlbuki) O, günahlarınızı bağışlamak ve sizi belli bir zamana kadar ertelemek için sizi (imana) çağırıyor. Onlar, “Siz de bizim gibi sadece birer insansınız. Bizi, babalarımızın ibadet ettiği (ilahlardan) alıkoymak istiyorsunuz. Öyleyse bize apaçık bir delil getirin” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (14, 11, 'Peygamberleri, onlara dedi ki: “Biz ancak sizin gibi birer insanız. Fakat Allah, kullarından dilediğine (peygamberlik) nimetini bahşeder. Allah’ın izni olmadıkça, bizim size bir delil getirmemiz haddimize değil. Müminler ancak Allah’a tevekkül etsinler.”');
INSERT INTO verses (sura, aya, text) VALUES (14, 12, '“Allah, bize yollarımızı dosdoğru göstermişken, biz ne diye O’na tevekkül etmeyelim? Bize yaptığınız eziyete elbette katlanacağız. Tevekkül edenler, yalnız Allah’a tevekkül etsinler.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 13, 'Kâfîr olanlar peygamberlerine; “Andolsun, ya sizi yurdumuzdan çıkaracağız, ya da bizim dinimize dönersiniz” dediler. Rableri de onlara şöyle vahyetti: “Biz zalimleri mutlaka yok edeceğiz.”');
INSERT INTO verses (sura, aya, text) VALUES (14, 14, '“Onlardan sonra sizi elbette o yere yerleştireceğiz. Bu, makamımdan korkan ve tehdidimden sakınan kimseler içindir.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 15, '(Rasûller) Fetih istediler, (sonunda) her zorba inatçı, ümitsizce hüsrana uğradı.');
INSERT INTO verses (sura, aya, text) VALUES (14, 16, 'Hüsranın ardından da Cehennem vardır. Orada kendisine irinli su içirilecektir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 17, 'Onu yudumlamaya çalışacak, fakat boğazından bir türlü geçmeyecektir. Ölüm kendisini her yandan gelip saracak, fakat bir türlü ölemeyecektir. Arkasından da şiddetli bir azap gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 18, 'Rablerini inkâr edenlerin durumu; amelleri, aynen fırtınalı bir günde rüzgârın şiddetle savurduğu bir küle benzer. (Dünyada) kazandıkları hiçbir şeyin (ahirette) yararını görmezler. İşte bu, derin sapıklıktır.');
INSERT INTO verses (sura, aya, text) VALUES (14, 19, 'Görmez misin ki, Allah gökleri ve yeri hak ile yaratmıştır? Eğer dilerse sizi yok eder ve yerinize yeniden başkalarını yaratır.');
INSERT INTO verses (sura, aya, text) VALUES (14, 20, 'Bu da Allah’a göre zor bir iş değildir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 21, 'Onların tümü (kıyamette) Allah''ın huzuruna çıkarlar. Zayıf bırakılmışlar, büyüklük taslayanlara der ki: “Şüphesiz biz size tâbi idik; şimdi siz, bizden Allah''ın azabından herhangi bir şeyi savabilir misiniz?” Derler ki: “Eğer Allah bize hidayet etseydi, biz de sizleri hidayete eriştirirdik. Şimdi yakınsak da sabretsek de fark etmez, bizim için kaçacak hiç bir yer yoktur.”');
INSERT INTO verses (sura, aya, text) VALUES (14, 22, '"İş hükme bağlanıp bitince şeytan der ki: “Doğrusu Allah, size gerçek olan sözü vaat etti, ben de size vaatte bulundum, ama sözümden caydım. Benim size karşı zorlayıcı bir gücüm yoktu; yalnızca sizi çağırdım, siz de bana icabet ettiniz. Öyleyse beni kınamayın, siz kendinizi kınayın. Ben sizi kurtarıcı değilim, siz de beni kurtarıcı değilsiniz. Doğrusu daha önce beni ortak koşmanızı da tanımamıştım. Şüphesiz zalimlere acıklı bir azap vardır."');
INSERT INTO verses (sura, aya, text) VALUES (14, 23, 'İman eden ve salih ameller işleyenler, Rablerinin izniyle, ebedî kalacakları ve içlerinden ırmaklar akan Cennetlere sokulacaklar. Oradaki esenlik dilekleri “selâm”dır.');
INSERT INTO verses (sura, aya, text) VALUES (14, 24, 'Görmedin mi, Allah güzel bir sözü nasıl misal getirdi? (Güzel bir söz), kökü sağlam, dalları göğe yükselen bir ağaç gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 25, 'Bu ağaç, Rabbinin izniyle her zaman meyvesini verir. Allah insanlara düşünüp ibret alsınlar diye (böyle) misaller verir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 26, 'Kötü bir sözün durumu da; yerden koparılmış, ayakta durma imkânı olmayan kötü bir ağacın durumu gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 27, 'Allah, iman edenleri hem dünya hayatında hem de ahirette sapasağlam bir söz ile sabit kılar, zalimleri ise saptırır. Ve Allah dilediğini yapar.');
INSERT INTO verses (sura, aya, text) VALUES (14, 28, 'Allah''ın nimetini küfür (ve nankörlükle) değiştirenleri ve kavimlerini helak yurduna sürükleyenleri görmedin mi?');
INSERT INTO verses (sura, aya, text) VALUES (14, 29, 'Onlar Cehennem''e girecekler. Orası ne kötü bir karargahtır.');
INSERT INTO verses (sura, aya, text) VALUES (14, 30, 'Onlar Allah’a, O’nun yolundan saptırmak için, ortaklar koştular De ki: “Bir süre daha faydalanın. Çünkü varışınız ateşedir.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 31, 'İman eden kullarıma de ki: "Namazı dosdoğru kılsınlar. Hiçbir alışveriş ve dostluğun bulunmadığı bir gün gelmeden önce kendilerine rızık olarak verdiğimiz şeylerden Allah yolunda gizlice ve açıktan infâk etsinler."');
INSERT INTO verses (sura, aya, text) VALUES (14, 32, 'Allah; gökleri ve yeri yaratan, gökten yağmur indiren ve onunla size rızık olarak türlü meyveler çıkaran, emri gereğince denizde yüzmek üzere gemileri emrinize veren, nehirleri de hizmetinize sunandır.');
INSERT INTO verses (sura, aya, text) VALUES (14, 33, 'O, düzenli seyredip hareket eden Güneş''i ve Ay''ı sizin hizmetinize sunan, gece ve gündüzü sizin emrinize verendir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 34, 'O, size kendisinden istediğiniz şeylerin hepsini verdi. Eğer Allah’ın nimetlerini saymaya kalkışsanız sayamazsınız. Şüphesiz insan çok zalimdir, çok nankördür.');
INSERT INTO verses (sura, aya, text) VALUES (14, 35, 'Hani İbrahim demişti ki: “Rabbim! Bu şehri güvenli kıl! Beni ve oğullarımı putlara ibadet etmekten uzak tut.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 36, '“Rabbim! Çünkü o putlar insanlardan birçoğunu saptırdılar. Artık kim bana uyarsa, o bendendir. Kim de bana karşı gelirse, şüphesiz sen çok bağışlayan, çok merhamet edensin.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 37, '''Rabbimiz! Ben çocuklarımdan bazısını, senin kutsal evinin (Kâbe’nin) yanında ekin bitmez bir vadiye yerleştirdim. Rabbimiz! Namazı dosdoğru kılmaları için (böyle yaptım). Sen de insanlardan bir kısmının gönüllerini onlara meylettir, onları ürünlerden rızıklandır, umulur ki şükrederler.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 38, '''Rabbimiz! Şüphesiz sen, gizlediğimizi de, açığa vurduğumuzu da bilirsin. Yerde ve gökte hiçbir şey Allah’a gizli kalmaz.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 39, '''Hamt, iyice yaşlanmış iken bana İsmail’i ve İshak’ı veren Allah’a mahsustur. Şüphesiz Rabbim duayı işitendir.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 40, '''Rabbim! Beni ve soyumu namazı ikame edenlerden eyle. Rabbimiz! Duamı kabul buyur.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 41, '''Rabbimiz! Hesap görülecek günde; beni, ana babamı ve inananları bağışla.''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 42, 'Sakın, Allah’ı zalimlerin yaptıklarından habersiz sanma! Allah, onları ancak gözlerin dehşetle yerinden fırlayacağı bir güne erteliyor.');
INSERT INTO verses (sura, aya, text) VALUES (14, 43, 'O gün başlarını dikerek (çağırıldıkları yere doğru) koşarlar. Gözleri kendilerine bile dönmez, kalpleri de bomboştur.');
INSERT INTO verses (sura, aya, text) VALUES (14, 44, '(Ey Muhammed!) İnsanları, kendilerine azabın geleceği gün ile uyar. Zira o gün zalimler, “Ey Rabbimiz! Yakın bir süreye kadar bizi ertele de senin çağrına uyalım ve peygamberlerin izinden gidelim” diyecekler. Onlara şöyle denilecek: “Daha önce siz, sonunuzun gelmeyeceğine yemin etmemiş miydiniz?''''');
INSERT INTO verses (sura, aya, text) VALUES (14, 45, 'Hatta siz, kendilerine zulmedenlerin yurtlarında yerleştiniz. Onlara neler yaptığımız da sizin için apaçık ortaya çıktı. Size birçok misaller de gösterdik.');
INSERT INTO verses (sura, aya, text) VALUES (14, 46, 'Onlar tuzaklar kurdular, ama Allah katında da onlara tuzak vardır. İsterse onların tuzakları dağları yerinden oynatacak olsun.');
INSERT INTO verses (sura, aya, text) VALUES (14, 47, 'Sakın Allah’ın, peygamberlerine verdiği sözden döneceğini sanma! Şüphesiz Allah, mutlak güç sahibidir, intikam sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 48, 'O gün yer, başka bir yere, gökler de başka göklere dönüştürülür ve insanlar tek ve Kahhar (her şeyin üzerinde yegâne hâkim) olan Allah’ın huzuruna çıkarlar.');
INSERT INTO verses (sura, aya, text) VALUES (14, 49, 'O gün, suçluları zincirlere vurulmuş olarak görürsün.');
INSERT INTO verses (sura, aya, text) VALUES (14, 50, 'Gömlekleri katrandandır. Yüzlerini de ateş bürüyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 51, 'Allah, herkese kazandığının karşılığını vermek için böyle yapar. Şüphesiz Allah, hesabı çabuk görendir.');
INSERT INTO verses (sura, aya, text) VALUES (14, 52, 'Bu Kur’an; kendisiyle uyarılsınlar, Allah’ın ancak tek ilâh olduğunu bilsinler ve akıl sahipleri düşünüp öğüt alsınlar diye insanlara bir bildiridir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 1, 'Elif, Lâm, Râ.[1] İşte bunlar kitabın, apaçık Kur''an''ın ayetleridir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 2, 'Kâfirler (kıyamet günü) keşke Müslüman olsaydık diye temenni ederler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 3, 'Onları bırak da yesinler, eğlensinler, beklentileri onları oyalasın. Nasıl olsa öğrenecekler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 4, 'Biz, bilinen bir yazgısı olmadan hiçbir ülkeyi yok etmedik.');
INSERT INTO verses (sura, aya, text) VALUES (15, 5, 'Hiçbir toplum ecelini geçemez ve ondan geri de kalamaz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 6, 'Dediler ki: "Ey kendisine Kur''an indirilen! Sen mutlaka bir delisin!"');
INSERT INTO verses (sura, aya, text) VALUES (15, 7, '“Eğer doğru söyleyenlerden isen bize melekleri getirsene!”');
INSERT INTO verses (sura, aya, text) VALUES (15, 8, 'Biz, melekleri ancak hakikatle indiririz. O zaman da o kâfirlere hiç mühlet verilmez.');
INSERT INTO verses (sura, aya, text) VALUES (15, 9, 'Kur’an’ı şüphesiz biz indirdik. O’nu koruyacak olan da şüphesiz biziz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 10, 'Kesinlikle senden önce de, geçmiş toplumlara rasûller göndermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (15, 11, 'Onlara kendilerine gelen her rasûlle alay ediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (15, 12, 'İşte böylece biz onu, (yalanlamayı) suçluların (Mekkeli müşriklerin) kalplerine sokarız.');
INSERT INTO verses (sura, aya, text) VALUES (15, 13, 'Onlar ona (indirilen kitaba) iman etmezler, oysaki evvelkilerin sünneti de böyle olup gitmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 14, 'Onlara gökten bir kapı açsak da onlar oradan yukarı çıksalar bile...');
INSERT INTO verses (sura, aya, text) VALUES (15, 15, 'Yine de: “Gözlerimiz perdelendi, belki de hepimiz büyülendik” derler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 16, 'Gökte burçlar (yıldızlar) var ettik ve onları bakanlar için süsledik.');
INSERT INTO verses (sura, aya, text) VALUES (15, 17, 'Onu (göğü) kovulmuş şeytanlardan koruduk.');
INSERT INTO verses (sura, aya, text) VALUES (15, 18, 'Ancak kulak hırsızlığı eden müstesna. Onun da ardına açık (yakıcı) bir alev düşer.');
INSERT INTO verses (sura, aya, text) VALUES (15, 19, 'Yeri de yaydık. Oraya sabit dağlar yerleştirdik. Orada her şeyden ölçüsü bilinen şeyler bitirdik.');
INSERT INTO verses (sura, aya, text) VALUES (15, 20, 'Ve orda sizler için ve kendisine rızık vericiler olmadığınız canlılar için geçimlikler kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (15, 21, 'Hazineleri bizim katımızda olmayan hiçbir şey yoktur. Ancak biz onu belirlenmiş bir miktar olarak indiririz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 22, 'Rüzgârları da (bulutlara yağmur) aşılayıcılar olarak gönderdik. Sonra gökten (buluttan) su indirdik de onunla sizleri suladık ve onu toplayıp depolayan da siz değilsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 23, 'Doğrusu ancak biz, hayat verir ve de öldürürüz. Hepsinin sonrasında (herşeye )varis olanlar da bizleriz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 24, 'Sizden önce geçenleri bildiğimiz gibi sizden sonra gelecekleri de biliriz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 25, 'Şüphesiz yalnızca senin Rabbin onların hepsini bir araya toplayacak. Muhakkak O, hikmet sahibidir, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 26, 'İnsanı kuru bir çamurdan, kara ve (rengi, kokusu değişmiş) bir balçıktan yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (15, 27, 'Daha önce de cinleri yakıp kavuran bir ateşten yaratmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (15, 28, 'Rabbin, meleklere şöyle demişti: "Ben, kuru bir çamurdan, kara ve (rengi, kokusu değişmiş) balçıktan bir beşer yaratacağım."');
INSERT INTO verses (sura, aya, text) VALUES (15, 29, 'Onu bir şekle sokup, ruhumdan üflediğim zaman onun için hemen secdeye kapanın.');
INSERT INTO verses (sura, aya, text) VALUES (15, 30, 'Meleklerin hepsi de topluca ona secde etmişti.');
INSERT INTO verses (sura, aya, text) VALUES (15, 31, 'Bundan bir tek İblis müstesnaydı. O, secde edenlerle birlikte olmaktan kaçındı.');
INSERT INTO verses (sura, aya, text) VALUES (15, 32, 'Allah: "Ey İblis, senin secde edenlerle beraber olmanı engelleyen nedir?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 33, '"(İblis) Ben, kuru bir çamurdan, kara ve (rengi, kokusu değişmiş) bir balçıktan yarattığın bir beşere secde edecek değilim" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 34, 'Allah dedi ki: Öyleyse ''''Cennet''ten çık git. Sen artık kovuldun!.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 35, '"Şüphesiz hesap gününe kadar lânet senin üzerinedir.”');
INSERT INTO verses (sura, aya, text) VALUES (15, 36, 'İblis: “Rabbim! Öyle ise onların tekrar diriltilecekleri güne kadar bana mühlet ver!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 37, 'Allah dedi ki: “O halde sen, kendisine mühlet verilenlerdensin.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 38, 'Vakti bilinen bir güne kadar.');
INSERT INTO verses (sura, aya, text) VALUES (15, 39, 'İblis: “Rabbim! Beni azdırmana karşılık, andolsun ki yeryüzünde kötülükleri onlara güzel göstereceğim, hepsini saptıracağım.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 40, 'Ancak, içlerinde ihlas sahibi kulların hariç.');
INSERT INTO verses (sura, aya, text) VALUES (15, 41, '(Allah Teâlâ:) "Bu benim gösterdiğim dosdoğru yoldur." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 42, 'Senin, kullarım üzerinde hiçbir gücün yoktur, sana uyan azgınlar dışında.');
INSERT INTO verses (sura, aya, text) VALUES (15, 43, 'Onların hepsine vadolunan yer Cehennem''dir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 44, 'Onun yedi kapısı vardır ve her kapıya onlardan ayrılmış belli bir pay vardır.');
INSERT INTO verses (sura, aya, text) VALUES (15, 45, 'Takva sahibi olanlar ise, Cennetlerde ve pınarlardadır.');
INSERT INTO verses (sura, aya, text) VALUES (15, 46, 'Selametle ve güvenle girin oraya!');
INSERT INTO verses (sura, aya, text) VALUES (15, 47, 'Biz, onların kalplerindeki tüm kini söküp attık. Onlar, kardeşler olarak karşılıklı koltuklarda otururlar.');
INSERT INTO verses (sura, aya, text) VALUES (15, 48, 'Onlara, orada hiçbir yorgunluk yoktur. Ve onlar oradan çıkarılacak da değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 49, 'Kullarıma benim, çok mağfiret edici, çok merhametli olduğumu haber ver.');
INSERT INTO verses (sura, aya, text) VALUES (15, 50, 'Azabıma gelince de o, çok acı veren bir azaptır.');
INSERT INTO verses (sura, aya, text) VALUES (15, 51, 'Onlara İbrahim’in misafirlerinden (meleklerden) de haber ver.');
INSERT INTO verses (sura, aya, text) VALUES (15, 52, 'Onun yanına girdikleri zaman ona: "Selam!" dediklerinde, o da onlara: “Biz, sizden korkuyoruz.” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (15, 53, 'Onlar: "Endişelenme, biz sana bilgin bir erkek evlat müjdeliyoruz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 54, 'İbrahim: “Bana yaşlılık gelip çatmış iken beni mi müjdeliyorsunuz? Bana neyi müjdeliyorsunuz?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 55, '"Sana gerçeği müjdeliyoruz. Ümitsizliğe düşenlerden olma!" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 56, 'O da: “Yoldan çıkmışlardan başka, Rabbinin rahmetinden kim ümidini keser ki?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 57, 'İbrahim, “Ey elçiler! O halde göreviniz nedir?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 58, '"Biz, günahkâr bir topluma gönderildik.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 59, '“Ancak Lût ailesi hariç (Onlar suçlu değillerdir). Kesinlikle onların hepsini bundan kurtaracağız.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 60, '"Yalnız onun karısını kurtarmayacağız. Onun geri kalanlardan olmasını takdir ettik.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 61, 'Elçiler (melekler) Lût’un ailesine gelince...');
INSERT INTO verses (sura, aya, text) VALUES (15, 62, 'Lût onlara: "Doğrusu siz, hiç tanınmayan kimselersiniz" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 63, 'Dediler ki: “Evet, fakat biz sana (kavminin) şüphe etmekte olduğu azabı getirdik.”');
INSERT INTO verses (sura, aya, text) VALUES (15, 64, '“Biz, sana gerçeği getirdik. Şüphesiz biz doğru söyleyenleriz.”');
INSERT INTO verses (sura, aya, text) VALUES (15, 65, '''Gecenin bir bölümünde aile fertlerini yola çıkar, sen de arkalarından git. Hiçbiriniz arkaya bakmasın. Emrolunduğunuz yere (doğru) geçin gidin.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 66, 'Ona şu durumu kesin olarak bildirdik: ''''Sabaha çıkarken onların arkası/kökü kesilmiş olacak.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 67, 'Şehir halkı sevinerek geldiler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 68, 'Lût, dedi ki: “Şüphesiz bunlar benim misafirlerimdir. Sakın beni rezil etmeyin.”');
INSERT INTO verses (sura, aya, text) VALUES (15, 69, '"Allah’tan korkun da, beni utandırmayın!''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 70, 'Onlar: "Biz sana insanları misafir etmeni yasaklamadık mı?" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 71, 'Lût: "Eğer evlilik yapacaksanız, işte kızlarım!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 72, '(Ey Muhammed!) Hayatına yemin olsun ki onlar sarhoşlukları içerisinde bocalayıp duruyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (15, 73, 'Derken Güneşin doğuşu sırasında, o korkunç uğultulu ses onları yakalayıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 74, 'Böylece (şehrin) üstünü altına getirdik. Üzerlerine de balçıktan pişirilmiş taşlar yağdırdık.');
INSERT INTO verses (sura, aya, text) VALUES (15, 75, 'Şüphesiz bunda düşünüp görebilen kimseler için ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (15, 76, 'O (şehir, herkesin gelip geçtiği) bir yol üzerinde durmaktadır.');
INSERT INTO verses (sura, aya, text) VALUES (15, 77, 'Şüphesiz bunda, Müminler için de bir işaret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (15, 78, '(Şuayb''ın kavmi olan) Eyke halkı zalimlik etti.');
INSERT INTO verses (sura, aya, text) VALUES (15, 79, 'Onlardan da intikam aldık. Her ikisi de hala görülüp, tanınan bir yol üzerindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 80, 'Şüphesiz Hicr (Semud) halkı da peygamberleri yalanlamışlardı.');
INSERT INTO verses (sura, aya, text) VALUES (15, 81, 'Onlara ayetlerimizi gönderdik ama onlardan yüz çevirmişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 82, 'Onlar, dağları oyarak evler yapıyorlardı. Güven içindeydiler.');
INSERT INTO verses (sura, aya, text) VALUES (15, 83, 'Derken sabaha girdiklerinde onları da bir çığlık yakalayıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (15, 84, 'Kazandıkları onlara bir fayda sağlamadı.');
INSERT INTO verses (sura, aya, text) VALUES (15, 85, 'Biz, gökleri, yeri ve arasındakileri ancak hak ile yarattık. Kıyamet elbette gelecektir. Sen (Ey Muhammed!) güzel bir şekilde affederek muamele et.');
INSERT INTO verses (sura, aya, text) VALUES (15, 86, 'Elbette Rabbin, her şeyi yaratandır, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 87, 'Sana, tekrarlanan yedi ayeti (Fâtiha Suresi''ni) ve Kur’an-ı Azîm''i verdik.');
INSERT INTO verses (sura, aya, text) VALUES (15, 88, 'Kâfirlerden bir kısmını faydalandırdığımız şeylerde sakın gözün kalmasın. Onlara karşı mahzun olma ve Müminlere (şefkat) kanadını indir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 89, 'De ki: ''''Gerçekten ben, apaçık bir uyarıcıyım.''''');
INSERT INTO verses (sura, aya, text) VALUES (15, 90, 'Nitekim biz, (Kur''an''ı) kısımlara ayıranlara azabı indirmişizdir.');
INSERT INTO verses (sura, aya, text) VALUES (15, 91, 'Onlar, Kur''an''ı kısım kısım ayırdılar. (Bir kısmına sihir, bir kısmına yalan dediler)');
INSERT INTO verses (sura, aya, text) VALUES (15, 92, 'Rabbine andolsun ki, onların hepsini yaptıklarından dolayı sorguya çekeceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 93, 'Bu yaptıklarından ötürü...');
INSERT INTO verses (sura, aya, text) VALUES (15, 94, 'Ey Muhammed! Şimdi sen, sana emrolunanı açıkça ortaya koy ve Allah’a ortak koşanlara aldırış etme.');
INSERT INTO verses (sura, aya, text) VALUES (15, 95, 'Elbette o alay edenlere karşı biz sana yeteriz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 96, 'Onlar Allah ile beraber başka bir ilah edinenlerdir. İleride öğrenecekler!');
INSERT INTO verses (sura, aya, text) VALUES (15, 97, 'Onların söyledikleri şeyler sebebiyle göğsünün daraldığını bilmekteyiz.');
INSERT INTO verses (sura, aya, text) VALUES (15, 98, 'Öyleyse hamt ile Rabbini tesbih et ve secde edenlerden ol!');
INSERT INTO verses (sura, aya, text) VALUES (15, 99, 'Sana yakin/ölüm gelene kadar Rabbine ibadet et!');
INSERT INTO verses (sura, aya, text) VALUES (16, 1, 'Allah’ın emri geldi. Artık onun vaktinden önce gelmesini istemeyin. Allah, onların şirk koştuklarından çok yücedir ve münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 2, 'O kendi emri ile kullarından dilediği kimseler üzerine vahiy ile melekleri: ‘Benden başka hiçbir ilah olmadığını bildirin. O halde benden korkun’ desinler diye indirir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 3, 'Gökleri ve yeri hak ile yarattı ve müşriklerin şirk koşmalarından çok yücedir/yüksektedir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 4, 'İnsanı bir nutfeden (meniden) yarattı. Buna rağmen insan apaçık bir hasım kesildi.');
INSERT INTO verses (sura, aya, text) VALUES (16, 5, 'Ve O, hayvanları (Deve, inek, koyun, keçi) yarattı. Onlarda sizin için ısıtıcı (şeyler) ve birçok faydalar vardır. Hem de onlardan yemektesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (16, 6, 'Ayrıca onları ağıllarına sokarken ve otlamaya salarken de sizin için ayrı bir güzellik vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 7, 'Kendisine ancak ağır sıkıntıya katlanarak varabileceğiniz uzaklıktaki beldelere, yüklerinizi taşırlar. Hiç kuşkusuz Rabbiniz pek şefkatlidir, merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 8, 'Hem binesiniz diye, hem de süs olarak atları, katırları ve merkepleri de yarattı. Bilemeyeceğiniz daha nice şeyleri de yaratır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 9, 'Doğru yolu göstermek Allah’a aittir ama o yollardan bazısı da eğridir. (Allah) dileseydi elbette hepinizi toptan hidayete erdirirdi.');
INSERT INTO verses (sura, aya, text) VALUES (16, 10, 'Sizin için gökten bir su indiren O''dur. O sudan içersiniz ve hayvanları otlatacağınız bitkileri de onunla yetiştirirsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (16, 11, 'Allah, onunla size ekinler, zeytin ve hurma ağaçları, üzüm ve her türlü ürünü yetiştirir. Düşünen bir toplum için bunda ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 12, 'Geceyi, gündüzü, Güneşi ve Ay''ı sizin hizmetinize vermiştir. Yıldızlar da O’nun emri ile size boyun eğmiştir. Bunların her birinde düşünen bir toplum için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 13, 'Yeryüzünde sizin için rengârenk yarattıklarında da öğüt alan bir toplum için gerçek bir ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 14, 'Yine taze bir et yiyesiniz ve içinden giyeceğiniz ziynet eşyasını çıkarasınız diye denizi emrinize veren O''dur. Gemilerin denizde suları yara yara akıp gittiklerini görürsün. (Bütün bunlar) O''nun fazlından aramanız ve şükretmeniz içindir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 15, 'Sizi sarsmaması için yeryüzünde sağlam dağları koydu, nehirler (yarattı) ve yolunuzu bulmanız içinde yollar kıldı.');
INSERT INTO verses (sura, aya, text) VALUES (16, 16, 'Daha (başka) işaretler (de yarattı) yıldızlar ile de onlar yollarını bulurlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 17, 'Şu halde yaratan, yaratamayan gibi olur mu? Artık siz düşünmez misiniz?');
INSERT INTO verses (sura, aya, text) VALUES (16, 18, 'Hâlbuki Allah’ın nimetini saymaya kalksanız onu sayamazsınız. Şüphesiz Allah, çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 19, 'Allah, sizin gizlediklerinizi de, açığa vurduklarınızı da bilir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 20, 'Allah''tan başka dua (ibadet) ettikleri (ilahlar), hiçbir şey yaratamazlar. Çünkü onlar kendileri yaratılmışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 21, 'Onlar, diri olmayan cansız varlıklardır! Ne zaman dirileceklerinin de şuuruna varamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 22, 'Sizin ilâhınız tek bir ilâhtır. Ahirete iman etmeyenlerin kalpleri bunu inkâr etmekte, kendileri de büyüklük taslamaktadırlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 23, 'Muhakkak, Allah onların içlerinde gizlediklerini de açığa koyduklarını da elbette bilir. O, büyüklenenleri hiç sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (16, 24, 'Onlara “Rabbiniz ne indirdi?” denildiği zaman, “Öncekilerin masalları” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 25, 'Böylece kıyamet gününde kendi günahlarını tam olarak, bilgisizce saptırdıkları kimselerin günahlarının da bir kısmını yüklenirler. Bak ki yüklenecekleri şey ne kötüdür!');
INSERT INTO verses (sura, aya, text) VALUES (16, 26, 'Onlardan öncekiler de tuzak kurmuşlardı. Allah’ın azabı binalarını, temelinden gelip yıktı da tavanları başlarına çöküverdi ve azap kendilerine fark edemedikleri yerden geldi.');
INSERT INTO verses (sura, aya, text) VALUES (16, 27, 'Sonra (Allah) kıyamet günü onları aşağılık kılacak ve diyecek ki: “Haklarında (Müminlere) düşman kesildiğiniz ortaklarım hani nerede?” Kendilerine ilim verilenler derler ki: “Bugün, gerçekten aşağılanma ve kötülük, kâfirlerin üstünedir.”');
INSERT INTO verses (sura, aya, text) VALUES (16, 28, 'O kâfirler, nefislerine zulmederlerken melekler onların canlarını alır da onlar teslim olup, ''''Biz hiçbir kötülük yapmıyorduk” derler. (Melekler de şöyle diyecekler:) ''''Hayır! Allah sizin yapmakta olduklarınızı hakkıyla bilmektedir.''''');
INSERT INTO verses (sura, aya, text) VALUES (16, 29, '“Haydi, içinde ebedî kalacağınız Cehennem''in kapılarından girin. Büyüklük taslayanların yeri ne kötüdür!”');
INSERT INTO verses (sura, aya, text) VALUES (16, 30, 'Allah’tan sakınan/takvalı olan kimselere; “Rabbiniz size ne indirdi?” denildiğinde, “İyilik/hayır!” diye karşılık verirler. Bu dünyada güzel amel işleyenlere “iyilik” vardır. Ahiret yurdu ise daha iyidir. Allah’tan sakınanların/takvalı olanların yurdu ne güzeldir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 31, 'İçinden nehirler akan Adn Cennetleri''ne gireceklerdir. Kendileri için orada diledikleri her şey vardır. Allah, kendine karşı gelmekten sakınanları böyle mükâfatlandırır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 32, 'Melekler, tertemiz ve hoş olarak canlarını aldığı o kimselere: “Selam olsun size! Yaptığınız amelleriniz sebebiyle girin Cennet''e!” derler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 33, '(Kâfirler) kendilerine o meleklerin gelmesinden yahut Rabbinin emrinin gelip çatmasından başkasını mı beklerler? Onlardan öncekiler de böyle yapmıştı. Allah onlara zulmetmedi, fakat onlar kendilerine zulmediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (16, 34, 'Onlara, yapmış oldukları amellerin kötülüğü dokunup, isabet etti ve alay ettikleri şey onları çepeçevre kuşattı.');
INSERT INTO verses (sura, aya, text) VALUES (16, 35, 'Allah’a ortak koşanlar, dediler ki: “Allah dileseydi ne biz, ne de atalarımız O’ndan başka hiçbir şeye ibadet etmezdik, O’nun emri olmadan hiçbir şeyi de haram kılmazdık.” Kendilerinden öncekiler de böyle yapmıştı. Peygamberlere düşen sadece apaçık bir tebliğdir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 36, 'Andolsun biz, her ümmete, “Yalnızca Allah’a ibadet edin, tâğûttan kaçının” diye peygamber gönderdik. Allah, onlardan kimini doğru yola iletti; onlardan kimine de sapıklık hak oldu. Şimdi yeryüzünde dolaşın da peygamberleri yalanlayanların sonunun ne olduğunu görün.');
INSERT INTO verses (sura, aya, text) VALUES (16, 37, 'Sen, onların doğru yola erişmelerini ne kadar çok istesen de Allah saptırdığı kimselere hidayet etmez. Onların hiçbir yardımcıları da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (16, 38, 'Onlar, “Allah, ölen bir kimseyi diriltmez” diye var güçleriyle Allah’a yemin ettiler. Hayır, diriltecek! Bu, yerine getirilmesini Allah’ın üzerine aldığı bir vaaddir. Fakat insanların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 39, '(Bu diriliş,) Hakkında ayrılığa düştükleri şeyleri onlara açıklasın, inkâr edenler de kendilerinin gerçekten yalancı kimseler olduklarını bilsinler diyedir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 40, 'Biz, bir şeyi dilediğimiz zaman, sözümüz sadece ona “Ol!” demektir. O da hemen oluverir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 41, 'Zulme uğradıktan sonra, Allah için hicret edenleri elbette dünyada güzel bir şekilde barındıracağız. Ahiretteki mükâfatları ise çok daha büyüktür, eğer bunu bilselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (16, 42, 'Onlar, sabreder ve Rablerine tevekkül ederler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 43, 'Biz, senden önce de yalnızca kendilerine vahyettiğimiz bir takım erkekleri peygamber olarak gönderdik. Eğer bilmiyorsanız ilim ehline sorun.');
INSERT INTO verses (sura, aya, text) VALUES (16, 44, '(Onları) apaçık belgelerle ve kitaplarla (gönderdik). İnsanlara kendilerine ne indirildiğini açıklayasın ve onlar da iyice düşünsünler diye sana da bu Zikri indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (16, 45, 'Kötülük tuzakları kuranlar, Allah’ın kendilerini yerin dibine batırmayacağından veyahut farkında olmadıkları bir yerden başlarına azabın gelmeyeceğinden emin mi oldular?');
INSERT INTO verses (sura, aya, text) VALUES (16, 46, 'Yahut onlar dönüp dolaşırken Allah’ın kendilerini yakalayıvermesinden emin mi oldular? Onlar, Allah’ı âciz bırakacak değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 47, 'Yahut da, onları korku üzere iken yakalamayacağından güven içinde midirler? Şüphesiz Rabbiniz çok esirgeyicidir, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 48, 'Allah’ın yarattığı şeylerin gölgelerinin zillet ve tevazu ile boyun eğerek durmadan sağa sola dönüp Allah’a secde ettiklerini görmüyorlar mı?');
INSERT INTO verses (sura, aya, text) VALUES (16, 49, 'Göklerde ve yerde olan tüm canlılar ve melekler hiç büyüklenmeden Allah’a secde ederler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 50, 'Yukarılarında olan Rablerinden korkarlar ve yalnızca kendilerine emredileni yaparlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 51, 'Allah: İki ilah edinmeyin! dedi. O, ancak tek ilahtır. Öyleyse benden korkun!');
INSERT INTO verses (sura, aya, text) VALUES (16, 52, 'Göklerdeki her şey, yerdeki her şey O’nundur. İtaat de daima O’na olmalıdır. Öyle iken siz Allah’tan başkasından mı korkuyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (16, 53, 'Size ulaşan her nimet Allah’tandır. Sonra size bir sıkıntı ve zarar dokunduğu zaman yalnız O’na yalvarır yakarırsınız.');
INSERT INTO verses (sura, aya, text) VALUES (16, 54, 'Sonra, sıkıntıyı sizden giderdiği zaman içinizden bir grup hemen Rablerine şirk koşarlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 55, 'Kendilerine verdiğimiz nimetlere karşı nankörlük etmek için böyle yaparlar. Bir süre daha faydalanın bakalım! Yakında bileceksiniz!');
INSERT INTO verses (sura, aya, text) VALUES (16, 56, 'Kendilerine verdiğimiz rızıklardan o hiç bir şey bilmeyenlere pay ayırıyorlar. Allah’a andolsun ki uydura geldiğiniz şeylerden elbette sorguya çekileceksiniz');
INSERT INTO verses (sura, aya, text) VALUES (16, 57, 'Bir de onlar Allah’a kızlar isnat ederler. O, bundan münezzehtir. Hâlbuki candan arzuladıklarını da kendileri için isterler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 58, 'Onlardan biri, kız ile müjdelendiği zaman içi öfke ile dolarak yüzü simsiyah kesilir!');
INSERT INTO verses (sura, aya, text) VALUES (16, 59, 'Kendisine verilen kötü müjde yüzünden halktan gizlenir. Şimdi onu, aşağılanmış olarak yanında tutacak mı, yoksa toprağa mı gömecek? Dikkat et, verdikleri hüküm ne kötüdür!');
INSERT INTO verses (sura, aya, text) VALUES (16, 60, 'Kötü sıfatlar ahirete iman etmeyenlere aittir. En yüce sıfatlar ise Allah’ındır. O, mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 61, 'Eğer Allah, insanları zulümleri yüzünden hemen cezalandırsaydı, yeryüzünde hiçbir canlı bırakmazdı. Fakat onları belirli bir süreye kadar erteler. Ecelleri geldiği zaman ise ne bir an geri kalabilirler, ne de öne geçebilirler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 62, 'Onlar hoşlanmadıkları şeyleri Allah’a isnad ederler. Dilleri de yalan yere en güzel akıbetin kendilerinin olduğunu söyler. Şüphesiz ateş onlaradır ve onlar (cehenneme) önden gönderilecek olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 63, 'Allah’a andolsun ki, biz senden önceki ümmetlere de peygamberler gönderdik. Şeytan onların yaptıklarını kendilerine süsleyip, hoş göstermiştir. İşte o bugün de onların velisidir. Onlara çok acıklı bir azap da vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 64, 'Sana kitabı, ancak ayrılığa düştükleri şeyleri onlara açıklaman için ve iman eden bir topluma doğru yolu gösterici ve rahmet olarak indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (16, 65, 'Allah, gökten su indirdi de onunla yeryüzünü ölümünden sonra diriltti. Şüphesiz bunda dinleyecek bir toplum için bir ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 66, 'Şüphesiz (sağmal) hayvanlarda da sizin için bir ibret vardır. Onların karınlarındaki işkembe ile kan arasından (süzülen) içenlere halis ve içimi kolay süt içiririz.');
INSERT INTO verses (sura, aya, text) VALUES (16, 67, 'Hurma ağaçlarının meyvelerinden ve üzümlerden hem içki, hem de güzel bir rızık edinirsiniz. Elbette bunda aklını kullanan bir toplum için bir ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 68, 'Rabbin, bal arısına şunu vahyetti: ''''Dağlardan, ağaçlardan ve insanların yaptıkları çardaklardan (kovanlardan) kendine evler edin.''''');
INSERT INTO verses (sura, aya, text) VALUES (16, 69, '''Sonra meyvelerin hepsinden ye de Rabbinin sana kolaylaştırdığı (yaylım) yollarına gir.'''' Onların karınlarından çeşitli renklerde bal çıkar. Onda insanlar için şifa vardır. Şüphesiz bunda düşünen bir (toplum) için bir ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 70, 'Allah sizi yaratmıştır, sonra öldürecektir. İçinizden kimi ömrünün en kötü çağına kadar geri çevrilir. Bildikten sonra hiçbir şey bilmez olsun diye. Şüphesiz Allah, her şeyi bilendir, her şeye gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 71, 'Allah, rızık konusunda kiminizi kiminizden üstün kıldı. Üstün kılınanlar, rızıklarını ellerinin altındakilere (köle ve cariyelerine) vermezler ki rızıkta hep eşit olsunlar. Şimdi Allah’ın nimetini mi inkâr ediyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (16, 72, 'Allah, size kendi cinsinizden eşler var etti. Eşlerinizden de oğullar ve torunlar verdi ve sizi temiz şeylerden rızıklandırdı. Öyle iken, onlar batıla iman edip de Allah’ın nimetini inkâr mı ediyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (16, 73, 'Allah''tan başka kendilerine göklerden ve yerden rızık olarak bir şey vermeye güç yetiremeyen ve bunu yapamayacak olan şeylere taparlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 74, 'Allah''a benzerler koşup durmayın. Çünkü Allah bilir, siz bilmezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (16, 75, 'Allah hiçbir şeye gücü yetmeyen, başkasının mülkiyetinde bulunan bir kul ile kendisine tarafımızdan güzel bir rızık verip de ondan gizli ve açık verip, duran kişiyi örnek verir. Bunlar hiç eşit olur mu? Hamt Allah’a mahsustur, fakat onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 76, 'Allah, şu iki adamı da örnek verir: Birisi hiçbir şeye gücü yetmeyen, efendisine yük olan bir dilsiz. Onu nereye yönlendirse bir hayır elde edemez. Hiç onunla adaleti emredip dosdoğru bir yol üzerine olan kimse eşit olur mu?');
INSERT INTO verses (sura, aya, text) VALUES (16, 77, 'Göklerin ve yerin gaybı Allah’a aittir. Kıyamet’in kopması, bir göz kırpması gibi veya daha az bir zamandır. Şüphesiz Allah, her şeye hakkıyla gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 78, 'Allah, sizi analarınızın karnından, siz hiçbir şey bilmez durumda iken çıkardı. Şükredesiniz diye size kulaklar, gözler ve kalpler verdi.');
INSERT INTO verses (sura, aya, text) VALUES (16, 79, 'Gök boşluğunda, boyun eğdirilmiş kuşları görmüyorlar mı? Onları, Allah’tan başka kimse tutmuyor. İşte bunda da iman eden bir toplum için ayetler/işaretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 80, 'Allah, size evlerinizi huzur ve dinlenme yeri yaptı. Hayvanların derilerinden gerek göç gününüzde, gerek ikamet gününüzde kolayca taşıyacağınız evler; onların yünlerinden, yapağılarından ve kıllarından bir süreye kadar yararlanacağınız ev eşyası ve geçimlikler meydana getirdi.');
INSERT INTO verses (sura, aya, text) VALUES (16, 81, 'Allah yarattığı şeylerden sizin için gölgeler yaydı ve dağlarda da sizin için barınaklar var etti. Sizi sıcaktan koruyacak elbiseler ve savaşta sizi koruyacak zırhlar verdi. Böylece Allah, itaat ederek teslim olasınız diye üzerinizde olan nimetini tamamlıyor.');
INSERT INTO verses (sura, aya, text) VALUES (16, 82, 'Ey Muhammed! Eğer yüz çevirirlerse, artık sana düşen açık bir tebliğden ibarettir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 83, 'Onlar, Allah’ın nimetini bilirler, sonra da inkâr ederler. Onların çoğu kâfirlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 84, 'Kıyamet günü her ümmetten bir şahit göndereceğiz; sonra o kâfirlere ne (özür dilemeleri için) izin verilecek, ne de Allah’ın rızasını kazandıracak amelleri işleme istekleri kabul edilecek.');
INSERT INTO verses (sura, aya, text) VALUES (16, 85, 'O zalimler, azabı gördükleri zaman artık onlardan azap hafifletilmez ve kendilerine mühlet de verilmez.');
INSERT INTO verses (sura, aya, text) VALUES (16, 86, 'Şirk koşanlar koştukları ortaklarını görünce diyecekler ki: “Rabbimiz! Bunlar, seni bırakıp kendilerine tapmış olduğumuz ortaklarımızdır.” Koştukları ortaklar da onlara: “Siz elbette yalancılarsınız” diye söz atarlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 87, 'Onlar o gün Allah’a teslim olurlar ve uydurdukları şeyler de onları yüzüstü bırakıp kaybolur.');
INSERT INTO verses (sura, aya, text) VALUES (16, 88, 'Kâfir olup da Allah’ın yolundan alıkoyanların işledikleri bozgunculuklara karşılık azaplarına azap katarız.');
INSERT INTO verses (sura, aya, text) VALUES (16, 89, 'Her ümmetin üzerine kendi içlerinden bir şahit getirdiğimiz gün seni de onların üzerlerine şahit getiririz. Sana Kitab''ı her şeyi açıklayıcı, bir yol gösterici, bir rahmet ve Müslümanlar için bir müjde olarak gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (16, 90, 'Şüphesiz Allah; adaleti, iyilik yapmayı, yakınlara yardım etmeyi emreder; hayâsızlığı, fenalık ve azgınlığı da yasaklar. O, düşünüp tutasınız diye size öğüt veriyor.');
INSERT INTO verses (sura, aya, text) VALUES (16, 91, 'Ahitleştiğiniz zaman Allah''ın ahdini yerine getirin ve pekiştirdikten sonra yeminlerinizi bozmayın. Çünkü Allah''ı üzerinize kefil gösterdiniz. Şüphesiz Allah, tüm yaptıklarınızı bilir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 92, 'Bir topluluğun diğer bir topluluktan daha çok olmasından dolayı yeminlerinizi hile aracı yaparak ipliğini sağlamca büktükten sonra söküp bozan kadın gibi olmayın. Allah, bununla sizi ancak imtihan eder. Hakkında ayrılığa düştüğünüz şeyleri kıyamet günü size elbette açıklayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 93, 'Eğer Allah dileseydi, sizi tek bir ümmet yapardı. Fakat O, dilediğini saptırır, dilediğini de doğru yola iletir. Yapmakta olduğunuz şeylerden mutlaka sorguya çekileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (16, 94, 'Yeminlerinizi aranızda hile ve fesat sebebi yapmayın. Sonra sağlamca bastıktan sonra ayaklarınız kayar da Allah yolundan sapmanız sebebiyle kötülüğü tadarsınız. (Ahirette de) sizin için büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 95, 'Allah’a verdiğiniz sözü az pahaya satmayın. Eğer bilirseniz, şüphesiz Allah katında olan sizin için daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 96, 'Sizin yanınızdaki tükenir, Allah katında olan ise kalıcıdır. Elbette sabredenlere, yapmakta olduklarının en güzeliyle mükâfatlarını vereceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (16, 97, 'Erkek veya kadın, kim Mümin olarak salih amel işlerse, elbette ona hoş bir hayat yaşatacağız ve onların mükâfatlarını yapmakta olduklarının en güzeli ile vereceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (16, 98, 'Kur’an okuduğun zaman, kovulmuş Şeytan''dan Allah’a sığın.');
INSERT INTO verses (sura, aya, text) VALUES (16, 99, 'Gerçek şu ki; Şeytan''ın, iman eden ve yalnız Rablerine tevekkül eden kimseler üzerinde bir hâkimiyeti yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (16, 100, 'Şeytan''ın hâkimiyeti, sadece onu dost edinenler ve Allah’a şirk koşanlar üzerindedir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 101, 'Biz bir ayeti değiştirip yerine başka bir ayet getirdiğimiz zaman -ki Allah, neyi indireceğini gayet iyi bilir- onlar Peygamber’e, “Sen ancak uyduruyorsun” derler. Hayır! Onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 102, 'Ey Muhammed! De ki: ''''Rûhu’l-Kudüs (Cebrâîl), iman edenleri sağlamlaştırmak, Müslümanlara doğru yolu göstermek ve onlara bir müjde olmak üzere Kur’an’ı Rabbinden hak olarak indirdi.''''');
INSERT INTO verses (sura, aya, text) VALUES (16, 103, 'Andolsun ki biz onların, “Kur’an’ı ona bir insan öğretiyor” dediklerini biliyoruz. Kendisine nisbet ettikleri şahsın dili yabancıdır. Bu Kur’an ise gayet açık bir Arapça’dır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 104, 'Allah’ın ayetlerine iman etmeyenleri, Allah elbette doğru yola iletmez. Onlar için elem dolu bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 105, 'Yalanı, ancak Allah’ın ayetlerine iman etmeyenler uydurur. İşte onlar, yalancıların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 106, 'Kalbi imanla dolu olduğu halde, zorlanan kimse müstesna, iman ettikten sonra Allah''ı inkâr edip, gönlünü küfre açanlara Allah katından bir gazap vardır ve büyük azap da onlar içindir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 107, 'Bunun sebebi, onların dünya hayatını âhiretten daha çok sevmeleri ve Allah’ın hiç şüphesiz kâfirler topluluğuna hidayet vermemesidir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 108, 'İşte onlar; Allah’ın kalplerini, kulaklarını ve gözlerini mühürlediği kimselerdir. İşte onlar gafillerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 109, 'Kuşkusuz onlar, ahirette hüsrana uğrayanların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 110, 'Ayrıca Rabbin işkencelere uğratıldıktan sonra hicret edenlere, sonra da cihad edenlere ve sabredenlere; Evet, Rabbin muhakkak bundan sonra çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 111, 'O gün, herkes kendi nefsi adına mücadele eder ve herkese yaptığının karşılığı eksiksiz ödenir. Onlar zulme uğratılmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (16, 112, 'Allah şöyle bir kasabayı örnek olarak verir: Orası güven ve huzur içinde idi. Oraya her taraftan bolca rızık gelirdi. Fakat Allah’ın nimetlerine nankörlük ettiler; bu yüzden yaptıklarına karşılık, Allah onlara şiddetli açlık ve korku ızdırabını tattırdı.');
INSERT INTO verses (sura, aya, text) VALUES (16, 113, 'Andolsun, onlara içlerinden bir peygamber geldi de onu yalanladılar. Böylece zulmederlerken azap onları yakalayıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (16, 114, 'Artık Allah’ın size helâl ve temiz olarak verdiği rızıklardan yiyin ve eğer yalnızca Ona ibadet ediyorsanız Allah’ın nimetine şükredin.');
INSERT INTO verses (sura, aya, text) VALUES (16, 115, 'Allah size, ölmüş hayvanı-leşi, kanı, domuz etini, Allah''tan başkası adına kesilen hayvanı haram kıldı. Kim bu haram kılınan şeylerden yemeye mecbur kalırsa, helâl saymayarak, zarurî ihtiyaç sınırını aşmadan yiyebilir. Şüphesiz ki Allah çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 116, 'Dillerinizin yalan yere nitelendirmesi dolayısıyla, “Şuna helal, buna haram” demeyin. Çünkü Allah''a karşı yalan uydurmuş olursunuz. Şüphesiz Allah''a karşı yalan uyduranlar kurtuluşa eremezler.');
INSERT INTO verses (sura, aya, text) VALUES (16, 117, '(Dünyada elde ettikleri) az bir yararlanmadır. Hâlbuki (ahirette) onlara acıklı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 118, 'Sana anlattıklarımızı daha önce Yahudilere de haram kılmıştık. Biz onlara zulmetmemiştik, ama onlar kendilerine zulmediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (16, 119, 'Sonra, şüphesiz ki Rabbin; bir cahillikle kötülük yapan, sonra bunun ardından tövbe eden ve durumunu düzeltenlerden yanadır. Şüphesiz ki Rabbin bundan sonra elbette çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 120, 'Gerçekten İbrahim başlı başına bir ümmetti. Allah’a itaatkârdı, hanifdi, o müşriklerden olmamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 121, 'O, (Allah’ın) nimetlerine şükredendi. Allah, onu seçmiş ve doğru yola iletmişti.');
INSERT INTO verses (sura, aya, text) VALUES (16, 122, 'Ona dünyada iyilik verdik. Şüphesiz o, ahirette de salihlerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 123, 'Sonra biz sana: “Hanif olarak İbrahim’in dinine uy. O müşriklerden de olmadı” diye vahyettik.');
INSERT INTO verses (sura, aya, text) VALUES (16, 124, 'Cumartesi ancak hakkında ihtilafa düşenlere farz kılınmıştı. Şüphesiz Rabbin, ayrılığa düşmekte oldukları şeyler konusunda kıyamet günü aralarında hüküm verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 125, '(Ey Muhammed!) Rabbinin yoluna hikmetle, güzel öğütle çağır ve onlarla en güzel şekilde mücadele et. Şüphesiz senin Rabbin, kendi yolundan sapanları en iyi bilendir. O, doğru yolda olanları da en iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (16, 126, 'Eğer ceza verecekseniz, size yapılanın misliyle cezalandırın. Eğer sabrederseniz; elbette bu, sabredenler için daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (16, 127, 'Sabret! Senin sabrın ancak Allah’ın yardımı iledir. Onlardan yana üzülme. Tuzak kurmalarından dolayı da sıkıntıya düşme.');
INSERT INTO verses (sura, aya, text) VALUES (16, 128, 'Şüphesiz Allah, korkup, sakınanlar ve iyilik yapanlarla beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 1, 'Bir gece kulunu, Mescid-i Haram’dan, çevresini mübarek kıldığımız Mescid-i Aksa’ya ayetlerimizi ona göstermek için götüren (Allah her türlü noksanlıktan) münezzehtir. Şüphesiz O, her şeyi işitendir, görendir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 2, 'Mûsâ’ya kitap verdik. O kitabı, İsrailoğulları için, "Benden başkasını vekil edinmeyin!" diye hidayet (rehberi) kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (17, 3, 'Ey Nûh’la birlikte taşıdığımız kimselerin soyu/torunları! Doğrusu Nûh, çok şükreden bir kuldu.');
INSERT INTO verses (sura, aya, text) VALUES (17, 4, 'Kitapta, İsrailoğulları''na: “Yeryüzünde iki defa bozgunculuk çıkaracaksınız, büyük bir azgınlıkla kibirlenip taşkınlık yapacaksınız” diye bildirmiştik.');
INSERT INTO verses (sura, aya, text) VALUES (17, 5, 'Birincisinin zamanı gelince, üzerinize güç kuvvet sahibi kullarımızı gönderdik de ülkeyi baştan başa dolaşarak (sizi) aradılar. Bu, gerçekleşmiş bir vaad idi.');
INSERT INTO verses (sura, aya, text) VALUES (17, 6, 'Sonra size bunlara karşı tekrar üstünlük verdik. Mallarla, oğullarla yardımınıza yetiştik, sayınızı da çoğalttıkça çoğalttık.');
INSERT INTO verses (sura, aya, text) VALUES (17, 7, 'Eğer iyilik ederseniz kendinize, kötülük ederseniz yine kendinize etmiş olursunuz. İkincinin zamanı geldiğinde de yüzünüzü kötü bir duruma soksunlar, birincisinde mescide girsinler ve ellerine geçirdikleri her şeyi büsbütün tahrip etsinler (diye düşmanlar gönderdik).');
INSERT INTO verses (sura, aya, text) VALUES (17, 8, 'Rabbinizin size merhamet edeceğini umabilirsiniz, ama dönerseniz Biz de döneriz. Öyle ya Biz cehennemi kâfirlere bir zindan yaptık.');
INSERT INTO verses (sura, aya, text) VALUES (17, 9, 'Şüphesiz bu Kur’an, en doğru yolu gösterir. Salih amel işleyen Müminlere, büyük mükâfat olduğunu müjdeler.');
INSERT INTO verses (sura, aya, text) VALUES (17, 10, 'Ahirete iman etmeyenlere de acı veren bir azap hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (17, 11, 'İnsan hayra dua ediyormuş gibi, (kendisi için) şerre de dua eder. İnsan pek acelecidir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 12, 'Biz geceyi ve gündüzü iki ayet kıldık. Gece ayetini görünmez (karanlık) ve Rabbinizin bol nimetini aramanız ve de yılların sayısını ve hesabı öğrenmeniz için; gündüz ayetini ise aydınlık kıldık. Biz her şeyi yeterince açıkladık.');
INSERT INTO verses (sura, aya, text) VALUES (17, 13, 'Her insanın boynuna amelini dolarız. Kıyamet günü kendisine, açılmış olarak karşılaşacağı bir kitap çıkaracağız.');
INSERT INTO verses (sura, aya, text) VALUES (17, 14, 'Kitabını oku! Bugün hesabını görücü olarak kendi kendine yetersin.');
INSERT INTO verses (sura, aya, text) VALUES (17, 15, 'Hidayet yoluna giren kimse ancak kendisi için girmiş olur. Sapan kimsenin de sapıklığı ancak kendi aleyhinedir. Hiçbir günahkâr bir başkasının günahını yüklenmez. Biz, rasûl göndermedikçe azap etmeyiz.');
INSERT INTO verses (sura, aya, text) VALUES (17, 16, 'Biz bir ülkeyi helak etmek istediğimiz zaman, oranın ileri gelenlerine (itaat etmelerini) emrederiz ama onlar yoldan çıkarlar. Artık onun üzerine söz (azap) kesinleşir de onu tümüyle helak ederiz.');
INSERT INTO verses (sura, aya, text) VALUES (17, 17, 'Nûh’tan sonra nice nesilleri helak ettik. Rabbinin kullarının bütün günahlarından hakkıyla haberdar ve görücü olması yeter.');
INSERT INTO verses (sura, aya, text) VALUES (17, 18, 'Kim, çarçabuk olanı/dünyayı isterse, orada dilediğimiz kimseye acele isteğini veririz. Sonra onu Cehennem''e koyarız. O burayı kınanmış ve kovulmuş olarak boylar.');
INSERT INTO verses (sura, aya, text) VALUES (17, 19, 'Kim de ahireti ister ve bir Mümin olarak tüm çabasıyla onun için gayret ederse, işte bunların gayretleri makbuldür.');
INSERT INTO verses (sura, aya, text) VALUES (17, 20, 'Her birine, onlara da, bunlara da Rabbinin nimetinden ardarda veririz. Rabbinin ihsanı kimseye yasak kılınmış değildir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 21, 'Onları birbirlerinden nasıl üstün kıldığımıza bir bak! Şüphesiz ahiret, derece ve üstünlük bakımından daha büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (17, 22, 'Allah ile birlikte bir başka ilah edinme! Yoksa, kınanmış ve terkedilmiş olursun.');
INSERT INTO verses (sura, aya, text) VALUES (17, 23, 'Rabbin, kendisinden başkasına ibadet etmemenizi ve ana babaya iyilik etmenizi emretmiştir. Eğer, onlardan biri veya her ikisi de senin yanında ihtiyarlayacak olurlarsa, onlara “Öf!” bile deme! Onları azarlama. Onlara güzel söz söyle.');
INSERT INTO verses (sura, aya, text) VALUES (17, 24, 'Onlara merhamet ile tevazu kanadını indir ve şöyle dua et: “Rabbim! Küçüklüğümde onlar beni nasıl yetiştirmişlerse, şimdi de sen onlara merhamet et.''''');
INSERT INTO verses (sura, aya, text) VALUES (17, 25, 'İçinizdekini en iyi Rabbiniz bilir. Eğer salih kimseler olursanız, şüphesiz O, kendisine dönenlere çok mağfiret edendir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 26, 'Akrabaya, düşküne ve yolda kalmışa hakkını ver. Fakat, saçıp savurma!');
INSERT INTO verses (sura, aya, text) VALUES (17, 27, 'Çünkü saçıp savuranlar, şeytanların kardeşleridir. Şeytan ise Rabbine karşı pek nankördür.');
INSERT INTO verses (sura, aya, text) VALUES (17, 28, 'Eğer Rabbinden umduğun bir rahmeti istemek için onlardan yüz çevirecek olursan, o zaman onlara yumuşak bir söz söyle.');
INSERT INTO verses (sura, aya, text) VALUES (17, 29, 'Elini boynuna asıp bağlama (cimri olma), büsbütün eli açık da olma (israf etme); yoksa kınanmış olarak, pişmanlık içinde kalakalırsın.');
INSERT INTO verses (sura, aya, text) VALUES (17, 30, 'Rabbin dilediği kimsenin rızkını genişletir ve (dilediği kimsenin de) daraltır. Şüphesiz ki O, kullarından haberdardır, (onları) çok iyi görür.');
INSERT INTO verses (sura, aya, text) VALUES (17, 31, 'Yoksulluk korkusu ile sakın çocuklarınızı öldürmeyin. Biz onları da rızıklandırırız sizi de. Onları öldürmek büyük günahtır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 32, 'Zinaya asla yaklaşmayın! Çünkü o, çirkin bir iştir, kötü bir yoldur.');
INSERT INTO verses (sura, aya, text) VALUES (17, 33, 'Allah’ın haram kıldığı bir cana, hak ile olmadıkça asla kıymayın! Kim, haksız yere öldürülürse, onun velisine (katil hakkında) bir yetki verdik. Fakat, o da öldürme/kısas konusunda aşırıya gitmesin. Çünkü ona/veliye yardım edilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 34, 'Ergenlik çağına gelinceye kadar, en güzel şekilde olması müstesnâ yetimin malına yaklaşmayın. Bir de ahde vefa gösterin. Çünkü ahitten sorumluluk vardır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 35, 'Bir şeyi tarttığınız zaman, tam tartın. Doğru terazi ile tartın. Bu hayırlıdır ve sonuç itibariyle de en iyisidir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 36, 'Bilmediğin bir şeyin ardına düşme! Zira kulak, göz ve kalp, bunların hepsi ondan sorumludur.');
INSERT INTO verses (sura, aya, text) VALUES (17, 37, 'Yeryüzünde böbürlenerek yürüme! Sen, ne yeri yarabilirsin ne de boyca dağlara erişebilirsin.');
INSERT INTO verses (sura, aya, text) VALUES (17, 38, 'Bunların hepsi de Rabbinin katında kötü olan şeylerdir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 39, 'İşte bu, Rabbinin sana hikmet olarak vahyettiği şeylerdir. Allah ile birlikte bir başka ilah edinme! Yoksa, kınanmış ve kovulmuş olarak Cehennem''e atılırsın.');
INSERT INTO verses (sura, aya, text) VALUES (17, 40, 'Rabbiniz, size erkekleri seçti de, meleklerden kız mı edindi? Siz, çok büyük söz söylüyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (17, 41, 'Bu Kur’an’da, öğüt alsınlar diye ayrıntılı olarak açıklamalar yaptık. Fakat, bu onların sadece kaçışlarını artırdı.');
INSERT INTO verses (sura, aya, text) VALUES (17, 42, 'De ki: Eğer O’nunla birlikte, dedikleri gibi başka bir ilah olsaydı, o zaman Arş''ın sahibine (galip gelmek için) bir yol ararlardı.');
INSERT INTO verses (sura, aya, text) VALUES (17, 43, 'Allah, bunların söylediklerinden münezzehtir, pek yücedir/yüksektedir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 44, 'Yedi gök, yer ve onların içinde kim varsa O’nu tesbih eder. O’na hamt ederek, tesbih etmeyen hiçbir şey yoktur. Fakat, siz onların tesbihini anlayamazsınız. Şüphesiz O, Halim''dir, çokça mağfiret edendir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 45, 'Sen Kur’an okuduğun zaman seninle, ahirete iman etmeyenlerin arasına örtücü bir perde çekeriz.');
INSERT INTO verses (sura, aya, text) VALUES (17, 46, 'Onu anlarlar diye kalplerine örtüler, kulaklarına da ağırlık koyduk. Kur’an’da Rabbini bir tek olarak andığın zaman kaçarak ardlarına dönüp giderler.');
INSERT INTO verses (sura, aya, text) VALUES (17, 47, 'Biz, onların seni dinlerken ne maksatla dinlediklerini ve gizli konuşmalarında zalimlerin; "Siz ancak büyülenmiş bir adama uyuyorsunuz.” dediklerini de çok iyi biliyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (17, 48, 'Senin için nasıl misaller verip, dalâlete düştüklerine bir bak! Artık onlar bir daha yol bulamayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 49, '“Biz kemik ve (toprak olup) ufalandığımız zaman yeni bir yaratılışla mı diriltileceğiz?“ derler.');
INSERT INTO verses (sura, aya, text) VALUES (17, 50, 'De ki: İster taş olun, ister demir!');
INSERT INTO verses (sura, aya, text) VALUES (17, 51, 'İsterse kalplerinizde büyüksediğiniz bir yaratık olun! Diyecekler ki: "Bizi tekrar kim diriltecek?" De ki: "Sizi ilk defa yaratan!" Bunun üzerine sana başlarını sallayarak: "O, ne zaman olacak?" diyecekler. De ki: "Yakın olsa gerek!"');
INSERT INTO verses (sura, aya, text) VALUES (17, 52, 'Sizi çağırdığı gün, O’na hamt ederek çağrısına uyup, geleceksiniz ve ancak pek az bir süre kaldığınızı zannedeceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (17, 53, 'Kullarıma de ki: En güzel olanı söylesinler. Çünkü şeytan aralarına ayrılık sokar. Gerçekten şeytan insanın apaçık bir düşmanıdır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 54, 'Rabbiniz sizi daha iyi bilir. Dilerse size merhamet eder veya dilerse azap eder. Biz seni onlara vekil olarak göndermedik.');
INSERT INTO verses (sura, aya, text) VALUES (17, 55, 'Rabbin, göklerde ve yerde olan kimseleri en iyi bilendir. Bazı peygamberleri de diğerlerinden üstün kılmışızdır. Davud’a Zebûr''u verdik.');
INSERT INTO verses (sura, aya, text) VALUES (17, 56, 'De ki: Allah’tan başka (ibadet edilen ilah olduğunu) ileri sürdüklerinize dua edin bakalım, sizin sıkıntınızı ne giderebilirler ne de değiştirebilirler.');
INSERT INTO verses (sura, aya, text) VALUES (17, 57, 'Onların dua ettikleri de Rablerine daha yakın olmak için vesile ararlar. O’nun rahmetini dilerler, azabından korkarlar. Çünkü Rabbinin azabı, sakınılacak bir azaptır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 58, 'Bizim kıyamet gününden önce helak etmeyeceğimiz veya şiddetli bir azabla azaplandırmayacağımız hiç bir ülke (memleket) yoktur. İşte bu, kitapta (Levh-i Mahfuz’da) yazılıdır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 59, 'Bizi mucizeler göndermekten, öncekilerin onu yalanlamasından başka bir şey alıkoymadı. Semûd kavmine açık bir mucize olarak dişi deveyi vermiştik. Ama ona zulmettiler. Oysa biz mucizeyi sadece korkutmak için göndeririz.');
INSERT INTO verses (sura, aya, text) VALUES (17, 60, 'Hani sana: "Muhakkak Rabbin insanları çepeçevre kuşatmıştır" demiştik. Sana gösterdiğimiz rüyayı ve Kur''an''da lanetlenmiş ağacı ancak insanlar için bir imtihan kıldık. Biz onları korkutuyoruz ama bu onlarda büyük bir azgınlıktan başka bir şeyi artırmıyor.');
INSERT INTO verses (sura, aya, text) VALUES (17, 61, 'Hani meleklere: "Âdem''e secde edin" demiştik de İblis dışında hepsi secde etmişti. O: "Ben bir çamur olarak yarattığına mı secde edeyim?" demişti.');
INSERT INTO verses (sura, aya, text) VALUES (17, 62, 'Şu benden üstün kıldığını görüyor musun? Yemin ederim ki, eğer beni kıyamete kadar yaşatırsan, pek azı dışında onun soyunu kendi buyruğum altına alacağım" demişti.');
INSERT INTO verses (sura, aya, text) VALUES (17, 63, 'Allah: "(Haydi) git, onlardan kim sana tabi olursa, sizin cezanız Cehennem''dir. Eksiksiz ve tam bir cezadır!"');
INSERT INTO verses (sura, aya, text) VALUES (17, 64, 'İnsanlardan gücünün yettiklerini sesinle davet et. Atlı ve yayalarınla onların üzerine yürü! Onların mallarına ve evlatlarına ortak ol, onlara vaadde bulun! Şeytan onlara aldatmadan başka bir şey vadetmez.');
INSERT INTO verses (sura, aya, text) VALUES (17, 65, 'Şüphesiz kullarımın üzerinde senin bir gücün yoktur. Vekil olarak Rabbin yeter.');
INSERT INTO verses (sura, aya, text) VALUES (17, 66, 'Denizde lütfunu arayasınız diye gemileri sizin için yürüten Rabbinizdir. Çünkü O, size çok merhamet eder.');
INSERT INTO verses (sura, aya, text) VALUES (17, 67, 'Denizde başınıza bir sıkıntı gelse O’ndan başka dua ettikleriniz kaybolur. Fakat sizi kurtarıp karaya çıkarınca hemen yüz çevirirsiniz. Zaten insan çok nankördür.');
INSERT INTO verses (sura, aya, text) VALUES (17, 68, 'Karada sizi yerin dibine geçirmeyeceğinden veya başınıza taş yağdırmasından güvende misiniz? O zaman bir koruyucu da bulamazsınız.');
INSERT INTO verses (sura, aya, text) VALUES (17, 69, 'Yoksa sizi, bir başka sefer için denize döndürdüğümüzde, üzerinize kırıp geçiren bir fırtına gönderip, küfrünüzden dolayı sizi suda boğmayacağından güvende misiniz? (Böyle olduktan sonra) bize karşı size arka çıkıp, öç alacak birini bulamazsınız.');
INSERT INTO verses (sura, aya, text) VALUES (17, 70, 'Andolsun ki Âdemoğullarını şereflendirdik. Onları karada ve denizde taşıdık. Onları temiz rızıklarla rızıklandırdık. Yarattığımız şeylerin çoğuna onları üstün kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (17, 71, 'Bütün insanları, önderleriyle birlikte çağırdığımız gün, kimin kitabı sağından verilirse, işte onlar kitaplarını okurlar ve onlar hurma çekirdeği üzerindeki iplikçik kadar bile zulme uğratılmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (17, 72, 'Kim burada kör ise o âhirette de kördür ve yol bakımından daha sapıktır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 73, 'Onlar neredeyse sana vahyettiğimizden başkasını bize karşı dizip uydurman için seni fitneye düşüreceklerdi. İşte o zaman seni dost edineceklerdi.');
INSERT INTO verses (sura, aya, text) VALUES (17, 74, 'Eğer sana sebat vermiş olmasaydık, neredeyse onlara az da olsa meyledecektin.');
INSERT INTO verses (sura, aya, text) VALUES (17, 75, 'O zaman ise, sana hayatın da ve ölümün de azabını kat kat tattırırdık. Hem de bize karşı bir yardımcı da bulamazdın.');
INSERT INTO verses (sura, aya, text) VALUES (17, 76, 'Neredeyse seni (bu) yerden (yurdundan) çıkarmak için tedirgin edeceklerdi; bu durumda kendileri de senden sonra az bir süreden başka kalamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (17, 77, '(Bu) senden önce gönderdiğimiz peygamberlerimiz için de uyguladığımız sünnettir. Sen bizim sünnetimizde hiçbir değişiklik bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (17, 78, 'Güneşin zevalinden/batıya yönelmesinden, gecenin karanlığına kadar namaz kıl, bir de sabah namazını da (kıl). Zira sabah namazı (meleklerce) şahit olunandır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 79, 'Gecenin bir kısmında uyanarak, sana mahsus ziyade olarak namaz kıl. Umulur ki Rabbin seni övgüye layık bir mevkiye yükseltir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 80, 'De ki: “Rabbim! Beni (gireceğim yere) doğrulukla/hoşnutlukla girdir ve beni (çıkacağım yerden) doğrulukla/hoşnutlukla çıkar ve bana katından yardımcı bir hüccet/kuvvet ver.''''');
INSERT INTO verses (sura, aya, text) VALUES (17, 81, 'De ki: ''''Hak geldi, batıl zail oldu. Zaten batıl zail olandır.''''');
INSERT INTO verses (sura, aya, text) VALUES (17, 82, 'Kur’an’dan Müminler için şifa ve rahmet olan şeyleri indiriyoruz. Zalimlerin ise yalnızca ziyanını artırır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 83, 'İnsana bir nimet verdiğimiz zaman yüz çevirir ve uzaklaşır. Başına bir bela gelince de ümitsiz olur.');
INSERT INTO verses (sura, aya, text) VALUES (17, 84, 'De ki: "Herkes kendi haline göre amel/iş yapar. Rabbiniz, en doğru yolda olanı daha iyi bilir.''''');
INSERT INTO verses (sura, aya, text) VALUES (17, 85, 'Sana ruhtan soruyorlar. De ki: Ruh, Rabbimin emrindendir. Size ancak az bir ilim verilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 86, 'Andolsun, dileseydik biz sana vahyettiğimizi tamamen ortadan kaldırırdık; sonra bu konuda bize karşı kendine hiçbir yardımcı da bulamazdın.');
INSERT INTO verses (sura, aya, text) VALUES (17, 87, 'Ancak Rabbinden bir rahmet olarak böyle yapmadık. Gerçekten onun sana lütfu pek büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (17, 88, 'Andolsun bu Kur’ân’ın bir benzerini getirmek için insanlar ve cinler bir araya toplansalar birbirine yardımcı olsalar dahi yine benzerini getiremezler.”');
INSERT INTO verses (sura, aya, text) VALUES (17, 89, 'Andolsun Biz bu Kur’ân’da insanlara her örnekten türlü türlü açıklamalar yapmışızdır. Yine insanlardan pek çoğu küfürden başkasını kabul etmediler.');
INSERT INTO verses (sura, aya, text) VALUES (17, 90, 'Yerden bize bir pınar fışkırtmadıkça asla sana iman etmeyeceğiz, demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (17, 91, '"Veya senin hurma bahçen ya da üzüm bağın olmadıkça ve de aralarından ırmaklar fışkırtmadıkça!"');
INSERT INTO verses (sura, aya, text) VALUES (17, 92, 'Yahut iddia ettiğin gibi göğü üzerimize parça parça düşürmeli ya da karşımıza Allah’ı ve melekleri getirmelisin.');
INSERT INTO verses (sura, aya, text) VALUES (17, 93, 'Yahut da altından bir evin olsun veya göğe yükselesin. Oradan bize okuyacağımız bir kitap indirmediğin sürece, senin (göğe) yükselmene de inanmayacağız. De ki: Rabbimi tenzih ederim. Ben, peygamber olarak gönderilmiş bir beşerden başkası değilim.');
INSERT INTO verses (sura, aya, text) VALUES (17, 94, 'İnsanlara hidayet geldiği halde, onların iman etmesine engel olan şey “Allah, rasûl olarak bir insan mı gönderdi?” demelerinden başkası değildir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 95, 'De ki: "Şayet yeryüzünde yerleşmiş, yürüyen melekler olsaydı Biz onlara gökten melek bir peygamber gönderirdik."');
INSERT INTO verses (sura, aya, text) VALUES (17, 96, 'De ki: Benimle sizin aranızda şahit olarak Allah yeter. Zira O, kullarını hakikaten bilip görendir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 97, 'Allah kimi doğru yola iletirse, işte o doğru yolu bulmuştur. Kimi de saptırırsa, artık onlar için Allah’tan başka veli bulamazsın. Biz onları kıyamet günü yüzleri üzeri, kör, sağır ve dilsiz olarak haşrederiz. Varacakları sığınakları Cehennem''dir. Sönmeye yüz tuttukça onun alevini artırırız.');
INSERT INTO verses (sura, aya, text) VALUES (17, 98, 'Cezaları işte budur. Çünkü onlar, ayetlerimizi inkâr etmişler ve sahi bizler, bir kemik yığını ve ufalanmış toprak olduktan sonra yeni bir yaratılışla dirilmiş mi olacağız? demişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 99, 'Gökleri ve yeri yaratan Allah’ın, onların benzerlerini de yaratmaya ve onlara hiç şüphesiz bir ecel tayin etmeye gücünün yettiğini görmüyorlar mı? Buna rağmen zalimler yine de küfürde direnmektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (17, 100, 'De ki: "Eğer siz, Rabbimin rahmet hazinelerine sahip olsaydınız. O zaman tükenir korkusuyla muhakkak cimrilik ederdiniz." Zaten insan çok cimridir.');
INSERT INTO verses (sura, aya, text) VALUES (17, 101, 'Andolsun ki Mûsâ’ya apaçık dokuz ayet verdik. İsrailoğulları''na sor! Mûsâ onlara geldiğinde Firavun kendisine: "Ey Mûsâ! Ben senin kesinlikle büyülenmiş olduğunu zannediyorum" demişti.');
INSERT INTO verses (sura, aya, text) VALUES (17, 102, 'Mûsâ ise, “İyi biliyorsun ki, bunları ancak, göklerin ve yerin Rabbi apaçık deliller olarak indirmiştir. Ey Firavun! Ben de seni kesinlikle helâk olmuş bir kişi olarak görüyorum." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (17, 103, 'Bunun üzerine onları o yerden çıkarmak istedi. Biz de onu beraberindekilerle birlikte suda boğuverdik.');
INSERT INTO verses (sura, aya, text) VALUES (17, 104, 'Bunun ardından İsrailoğulları''na şöyle dedik: ''''Bu topraklarda oturun, ahiret vaadi (kıyamet) gelince hepinizi toplayıp bir araya getireceğiz.''''');
INSERT INTO verses (sura, aya, text) VALUES (17, 105, 'Biz onu hak olarak indirdik. O da hak olarak indi. Seni de ancak bir müjdeci ve bir uyarıcı olarak gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (17, 106, 'Kuran''ı, insanlara ağır ağır okuman için, bölüm bölüm indirdik ve onu peyderpey indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (17, 107, 'De ki: İster iman edin; ister iman etmeyin. Daha önce kendilerine ilim verilenlere o okunduğu zaman çeneleri üzerine yüzüstü secdeye kapanırlar.');
INSERT INTO verses (sura, aya, text) VALUES (17, 108, 'Ve: “Rabbimizi tenzih ederiz. Gerçekten Rabbimizin vaadi kesin olarak gerçekleşir” derler.');
INSERT INTO verses (sura, aya, text) VALUES (17, 109, 'Ve ağlayarak çeneleri üstü (secdeye) kapanırlar ve bu onların kalplerini daha da yumuşatır.');
INSERT INTO verses (sura, aya, text) VALUES (17, 110, 'De ki: İster Allah diyerek dua edin, ister Rahman diyerek. Hangisiyle dua ederseniz edin, çünkü en güzel isimler O’nundur. Namazında (okurken) sesini pek yükseltme, çok da kısma! İkisinin arasında bir yol tut.');
INSERT INTO verses (sura, aya, text) VALUES (17, 111, 'De ki: "Hamt, çocuk edinmeyen, mülkünde ortağı olmayan ve düşkünlükten dolayı bir veliye de (ihtiyacı) bulunmayan Allah''a mahsustur.” “Allahu Ekber” diyerek O''nu tazim et.');
INSERT INTO verses (sura, aya, text) VALUES (18, 1, 'Hamt olsun Allah''a ki, kuluna kitabı indirdi ve onda hiçbir eğrilik koymadı.');
INSERT INTO verses (sura, aya, text) VALUES (18, 2, 'Dosdoğru (bir kitap olarak), katından (gelecek) şiddetli bir azapla korkutmak ve salih amellerde bulunan Müminlere güzel bir ecir olduğunu müjde vermek için (indirdi).');
INSERT INTO verses (sura, aya, text) VALUES (18, 3, 'Onlar onda ebedî olarak kalıcıdırlar.');
INSERT INTO verses (sura, aya, text) VALUES (18, 4, 'Ve; “Allah çocuk edinmiştir.” diyen kimseleri uyarması için indirmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 5, 'Onların da atalarının da o konu hakkında bir bilgisi yoktur. Ağızlarından çıkan bu söz pek büyüktür. Onlar yalandan başkasını söylemiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (18, 6, 'Belki de sen, bu kitaba iman etmiyorlar diye onların arkasından üzüntüden kendini helâk edeceksin.');
INSERT INTO verses (sura, aya, text) VALUES (18, 7, 'İnsanların hangisi daha güzel amel işleyecek diye imtihan etmek için yeryüzünde bulunanları, oranın süsü yaptık.');
INSERT INTO verses (sura, aya, text) VALUES (18, 8, 'Bununla beraber Biz bunun üstünde olan şeyleri elbet kupkuru bir toprak yaparız.');
INSERT INTO verses (sura, aya, text) VALUES (18, 9, 'Sen, yoksa Kehf ve Rakim ehlini bizim (tek) şaşılacak ayetlerimizden mi sandın?');
INSERT INTO verses (sura, aya, text) VALUES (18, 10, 'Hani bir kaç genç mağaraya sığınmıştı ve şöyle demişlerdi: "Rabbimiz, bize katından bir rahmet ver ve bu işimizde doğruyu bize nasip et!"');
INSERT INTO verses (sura, aya, text) VALUES (18, 11, 'Bunun üzerine Biz de nice yıllar onların kulaklarına perde koyduk (onları uyuttuk).');
INSERT INTO verses (sura, aya, text) VALUES (18, 12, 'Sonra da iki gruptan hangisinin (mağarada) bekledikleri süreyi daha iyi hesap ettiğini ortaya çıkarmak için onları uyandırdık.');
INSERT INTO verses (sura, aya, text) VALUES (18, 13, 'Biz sana onların haberlerini hak/gerçek olarak anlatıyoruz. Onlar, Rablerine iman etmiş gençlerdi. Biz de onların hidayetini arttırmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (18, 14, 'Ayağa kalkarak: "Bizim Rabbimiz göklerin ve yerin Rabbidir. Ondan başka bir ilaha dua etmeyeceğiz" O takdirde gerçekten son derece batıl bir söz söylemiş oluruz” dediklerinde Biz onların kalplerini sağlamlaştırdık.');
INSERT INTO verses (sura, aya, text) VALUES (18, 15, 'Şu bizim kavmimiz Allah''tan başka ilahlar edindiler. Onlar hakkında açık bir delil getirselerdi ya! Allah hakkında yalan uydurandan daha zalimi kimdir?');
INSERT INTO verses (sura, aya, text) VALUES (18, 16, '(Madem ki) Onlardan ve onların Allah’tan başka ibadet ettiklerinden ayrıldınız. O halde mağaraya çekilin ki Rabbiniz size rahmetini yaysın ve işlerinizde kolaylık sağlasın.');
INSERT INTO verses (sura, aya, text) VALUES (18, 17, '(Orada olsaydın) Güneş doğduğunda; mağaralarının sağ tarafına kaydığını, battığında da sol yandan kayıp gittiğini görürdün. Kendileri ise mağaranın geniş bir yerinde idiler. Bu, Allah’ın âyetlerindendir. Allah, kime hidayet ederse işte o, doğru yolu bulandır. Kimi de şaşırtırsa, artık ona doğru yolu gösterecek bir dost bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (18, 18, 'Uykuda oldukları halde, sen onları uyanık sanırsın. Biz onları sağa sola çeviriyorduk. Köpekleri de mağaranın girişinde ön ayaklarını uzatmış (yatmakta idi.) Onları görseydin, mutlaka onlardan yüz çevirip kaçardın ve gördüklerin yüzünden için korku ile dolardı.');
INSERT INTO verses (sura, aya, text) VALUES (18, 19, 'Böylece biz, birbirlerine sorsunlar diye onları uyandırdık. İçlerinden biri: “Ne kadar kaldınız?" dedi. (Bir kısmı) “Bir gün, ya da bir günden az”, dediler. (Diğerleri de) şöyle dediler: “Ne kadar kaldığınızı Rabbiniz daha iyi bilir. Şimdi siz birinizi şu gümüş para ile kente gönderin de baksın; (şehir halkından) hangisinin yiyeceği daha temiz ve lezzetli ise ondan size bir rızık getirsin. Ayrıca, çok nazik davransın (da dikkat çekmesin) ve sizi hiçbir kimseye sakın sezdirmesin.''''');
INSERT INTO verses (sura, aya, text) VALUES (18, 20, '''Eğer onlar sizi ele geçirirlerse ya taşlayarak öldürürler, yahut kendi dinlerine döndürürler. O zaman da bir daha asla kurtuluşa eremezsiniz.''''');
INSERT INTO verses (sura, aya, text) VALUES (18, 21, 'Böylece (insanları) onlardan haberdar ettik ki, Allah''ın vâdinin hak olduğunu, kıyametin şüphe götürmez olduğunu bilsinler. Hani onlar kendi meselelerini aralarında tartışıyorlardı. Bunun üzerine: “Üzerlerine bir bina yapın” demişlerdi. Rableri onları daha iyi bilendir. Fakat onların işine galip gelenler ise, “Mutlaka onların üstüne bir Mescid edineceğiz” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (18, 22, '"Onlar üç kişidir; dördüncüleri de köpekleridir" diyecekler. Yine: "Beş kişidir; altıncıları köpekleridir" diyecekler. (Bunlar) gayb hakkında taş atmaktır. "Yedi kişidirler, sekizincileri köpekleridir. De ki: Onların sayısını en iyi Rabbim bilir. Onları çok az kimseden başkası bilmez. O halde, onlar hakkında açık olarak ortaya konandan başka bir şeyi tartışma. Onlar hakkında (Ehl-i Kitap''tan hiçbir) kimseye bir şey sorma!');
INSERT INTO verses (sura, aya, text) VALUES (18, 23, 'Hiç bir şey için “Ben onu yarın mutlaka yapacağım.” deme!');
INSERT INTO verses (sura, aya, text) VALUES (18, 24, 'Ancak, “Allah dilerse yapacağım.” de. Unuttuğun zaman Rabbini an ve “Umarım Rabbim beni, bundan daha doğru olana ulaştırır.” de.');
INSERT INTO verses (sura, aya, text) VALUES (18, 25, 'Onlar mağaralarında üç yüz yıl kaldılar. Buna dokuz daha kattılar.');
INSERT INTO verses (sura, aya, text) VALUES (18, 26, 'De ki: “Kaldıkları süreyi Allah daha iyi bilir. Göklerin ve yerin gaybını bilmek O’na aittir. O, ne güzel görür; O, ne güzel işitir! Onların, O’ndan başka hiçbir dostu da yoktur. O, hükmüne hiçbir kimseyi ortak etmez.”');
INSERT INTO verses (sura, aya, text) VALUES (18, 27, 'Rabbinin kitabından sana vahyedileni oku. O’nun kelimelerini değiştirecek hiçbir kimse yoktur. O’ndan başka asla bir sığınak da bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (18, 28, 'Sabah, akşam Rablerinin yüzünü dileyerek O’na dua edenlerle beraber sen de sabret. Dünya hayatının süslerini arzulayarak, gözünü onlardan ayırma. Kalbini zikrimizden gafil kıldığımız, heva/arzularına uymuş ve işi taşkınlık olan kimseye itaat etme!');
INSERT INTO verses (sura, aya, text) VALUES (18, 29, 'De ki: “Hak, Rabbinizdendir. Artık dileyen iman etsin, dileyen kâfir olsun.” Biz zalimlere öyle bir ateş hazırladık ki, onun alevden duvarları kendilerini çepeçevre kuşatmıştır. (Susuzluktan) feryat edip yardım dilediklerinde, erimiş maden gibi yüzleri yakıp kavuran bir su ile kendilerine yardım edilir. O ne kötü bir içecektir! Cehennem ne korkunç bir sığınaktır.');
INSERT INTO verses (sura, aya, text) VALUES (18, 30, 'Gerçek şu ki, iman edip salih ameller yapanlara gelince, elbette biz iyi iş yapanların ecrini zayi etmeyiz.');
INSERT INTO verses (sura, aya, text) VALUES (18, 31, 'Onlara, altlarından ırmaklar akan Adn Cennetleri vardır. Orada altın bilezikler takarlar, ince ve kalın ipekten yeşil elbiseler giyerler. Orada koltuklarına yaslanırlar. Ne güzel mükâfat! (Cennet) Ne güzel bir konak!');
INSERT INTO verses (sura, aya, text) VALUES (18, 32, 'Onlara iki adamı örnek ver: Onlardan birisine iki üzüm bağı vermiştik. Çevresini de hurmalıklarla çevirmiş, bu ikisinin arasında da ekinler bitirmiştik.');
INSERT INTO verses (sura, aya, text) VALUES (18, 33, 'Her iki bahçe de ürünlerini vermiş, hiçbir şeyi eksik bırakmamışlardı. İkisinin arasından da bir ırmak akıtmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (18, 34, 'Onun başka ürünleri de vardı. İşte böyle bir halde arkadaşıyla konuşurken: "Ben malca senden zenginim, sayıca da senden güçlüyüm." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 35, 'Derken kendine zulmederek bağına girdi. Şöyle dedi: “Bunun sonsuza değin yok olacağını sanmıyorum.”');
INSERT INTO verses (sura, aya, text) VALUES (18, 36, '"Kıyametin kopacağına da hiç inanmıyorum. Eğer Rabbime döndürülecek olursam, elbette bundan daha iyi bir dönüş yeri bulurum." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 37, 'Kendisiyle konuşmakta olan arkadaşı ona dedi ki: “Seni topraktan, sonra bir damla sudan yaratan, sonra da seni (eksiksiz) bir insan şeklinde yaratan Allah’a (iman etmeyerek) küfre mi düşüyorsun?”');
INSERT INTO verses (sura, aya, text) VALUES (18, 38, 'Oysa, O Allah benim Rabbimdir ve ben, Rabbime hiç kimseyi şirk koşmam.');
INSERT INTO verses (sura, aya, text) VALUES (18, 39, 'Bağına girdiğinde Mâşallah (Allah neyi dilerse o olur)! Allah''tan başka kuvvet yoktur, demen lazım değil miydi? Eğer beni mal ve çocuk bakımından senden daha az (güçte) görüyorsan.');
INSERT INTO verses (sura, aya, text) VALUES (18, 40, 'Belki Rabbim bana senin bağından daha hayırlısını verir. Seninkinin üzerine ise gökten felaket indiriverir de kupkuru çorak bir toprak oluverir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 41, 'Yahut suyu yerin dibine çekiliverir de bir daha onu aramaya gücün yetmez.');
INSERT INTO verses (sura, aya, text) VALUES (18, 42, '(Birden) Onun ürünleri (afetle) kuşatılıverdi. Orası için harcadıklarına karşı avuçlarını (esefle) ovuşturup duruyordu. Bahçenin çardakları yere çökmüştü. "Ah, keşke Rabbime hiçbir şirk koşmamış olsaydım!" diyordu.');
INSERT INTO verses (sura, aya, text) VALUES (18, 43, 'Onun, Allah’tan başka kendisine yardım edebilecek kimseleri yoktu. Kendi kendini kurtaracak güçte de değildi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 44, 'İşte bu durumda velayet (yardım etmek) yalnızca hak olan Allah’a mahsustur. O’nun mükâfatı da daha hayırlıdır, vereceği sonuç da daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (18, 45, 'Onlara dünya hayatının örneğini ver: (Dünya hayatı), gökten indirdiğimiz yağmur gibidir ki, onun sebebiyle yeryüzünün bitkileri boy verip birbirine karışırlar. Fakat bütün bu canlılık sonunda rüzgârın savurduğu kuru bir çer çöpe döner. Allah, her şey üzerinde kudret sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 46, 'Mallar ve evlatlar, dünya hayatının süsüdür. Baki kalacak salih ameller ise, Rabbinin katında sevap olarak da, ümit olarak da daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (18, 47, 'Dağları yürüteceğimiz ve senin yeryüzünü dümdüz göreceğin günü bir hatırla. Biz onları mahşerde toplarız da içlerinden hiçbirini bırakmayız.');
INSERT INTO verses (sura, aya, text) VALUES (18, 48, 'Hepsi saf saf Rabbinin huzuruna çıkarılırlar. Onlara: “Andolsun, sizi ilk önce yarattığımız gibi bize geldiniz. Oysa siz, sizin için hesaba çekileceğiniz bir zaman belirlemediğimizi sanmıştınız.” denir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 49, 'Kitap ortaya konur. Günahkârları, kitabın içindekilerden korkuya kapılmış görürsün. “Eyvah bize! Bu nasıl bir kitaptır ki; küçük, büyük hiçbir şey bırakmadan hepsini sayıp dökmüş!” derler. Onlar bütün yaptıklarını karşılarında bulurlar. Senin Rabbin hiç kimseye zulmetmez.');
INSERT INTO verses (sura, aya, text) VALUES (18, 50, 'Hani biz meleklere: “Âdem için (selamlamak için) secde edin!” demiştik de İblis’ten başka hepsi secde etmişlerdi. İblis ise cinlerdendi de Rabbinin emri dışına çıktı. Şimdi siz, beni bırakıp da İblis’i ve neslini, kendinize dostlar mı ediniyorsunuz? Hâlbuki onlar, sizin için birer düşmandırlar. Bu, zalimler için ne kötü bir bedeldir!');
INSERT INTO verses (sura, aya, text) VALUES (18, 51, 'Onları, göklerin ve yerin yaratılmasına veya kendilerinin yaratılışına şahit tutmadım. Saptıranları da yardımcı edinecek değilim.');
INSERT INTO verses (sura, aya, text) VALUES (18, 52, 'O gün: "Benim ortaklarım olduklarını sandıklarınızı çağırın" diye buyurur. Onları çağırırlar ama cevap vermezler. Biz aralarına bir uçurum koyarız.');
INSERT INTO verses (sura, aya, text) VALUES (18, 53, 'Suçlular (o gün) ateşi görünce, onun içine düşeceklerini iyice anlayacaklar ve ondan kurtuluş yolu da bulamayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (18, 54, 'And olsun ki, Biz bu Kuran''da insanlara her türlü misali gösterip açıkladık. Fakat tartışmaya en çok düşkün (varlık) insandır.');
INSERT INTO verses (sura, aya, text) VALUES (18, 55, 'İnsanlara hidayet geldikten sonra onların iman etmelerine ve Rablerinden mağfiret dilemelerine alıkoyan tek şey; ancak öncekilerin başına gelen sünnetin kendilerine de gelip çatmasını yahut onlara gözleri önünde azabın gelmesini beklemeleridir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 56, 'Peygamberleri ancak müjdeci ve uyarıcı olarak göndeririz. Kâfirler, batıl ile hakkı ortadan kaldırmak için mücadele ederler. Ayetlerimizi ve kendilerine yapılan uyarıları alay konusu yaparlar.');
INSERT INTO verses (sura, aya, text) VALUES (18, 57, 'Kim, kendisine Rabbinin âyetleri hatırlatılıp da onlardan yüz çeviren ve elleriyle yapıp, işlediklerini unutandan daha zalimdir? Şüphesiz biz, onu anlamamaları için kalplerine perdeler gerdik, kulaklarına da ağırlıklar koyduk. Sen onları hidayete davet etsen de artık ebediyen hidayet bulamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (18, 58, 'Rabbin; çok bağışlayıcıdır, merhamet sahibidir. Eğer yaptıkları yüzünden onları (dünyada) cezaya çarptırsaydı, elbette azaplarını çarçabuk verirdi. Fakat, onlar için belirlenmiş bir gün vardır ki (o gün gelince) hiçbir kurtuluş çaresi bulamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (18, 59, 'İşte şu ülkeler; zulmettikleri zaman onları helâk ettik. Onları helâk etmek için de belli bir zaman tayin etmiştik.');
INSERT INTO verses (sura, aya, text) VALUES (18, 60, 'Hani Mûsâ, genç arkadaşına: "İki denizin birleştiği yere ulaşmaya veya yıllarca yürümeye kararlıyım." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (18, 61, 'Onlar, iki denizin birleştiği yere ulaştıklarında balıklarını unuttular. O da denizde bir yol tutup gitti.');
INSERT INTO verses (sura, aya, text) VALUES (18, 62, 'O yeri geçtikleri zaman genç arkadaşına: "Kahvaltımızı getir, bu yolculuğumuzda bir hayli yorgun düştük." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 63, 'Genç, “Gördün mü! Kayaya sığındığımız sırada balığı unutmuşum. –Doğrusu onu sana söylememi bana ancak Şeytan unutturdu- Balık şaşılacak bir şekilde denizde yolunu tutup gitmişti.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 64, 'Mûsâ: "İşte, aradığımız buydu." dedi. Hemen izlerini takip ederek gerisin geriye döndüler.');
INSERT INTO verses (sura, aya, text) VALUES (18, 65, 'Orada kendisine tarafımızdan bir rahmet vermiş ve nezdimizden bir ilim öğretmiş olduğumuz kullarımızdan bir kul buldular.');
INSERT INTO verses (sura, aya, text) VALUES (18, 66, 'Mûsâ ona: “Sana öğretilen bilgilerden bana, doğruya iletici bir bilgi öğretmen için sana tabi olayım mı?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 67, 'Adam, şöyle dedi: “Doğrusu sen benimle beraber olmaya asla sabredemezsin.”');
INSERT INTO verses (sura, aya, text) VALUES (18, 68, '“İç yüzünü kavrayamadığın bir şeye nasıl sabredebilirsin?”');
INSERT INTO verses (sura, aya, text) VALUES (18, 69, '"İnşallah, beni sabırlı olarak bulacaksın ve senin emrine karşı gelmeyeceğim." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 70, 'O da şöyle dedi: “O hâlde, eğer bana tabi olacaksan, ben sana söylemedikçe hiçbir şey hakkında bana soru sormayacaksın.”');
INSERT INTO verses (sura, aya, text) VALUES (18, 71, 'Derken yola koyuldular. Nihayet bir gemiye bindiklerinde (adam) gemiyi deldi. Mûsâ: “Sen onu içindekileri boğmak için mi deldin? Doğrusu, sen büyük bir iş yaptın.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 72, 'Adam: “Sen benimle beraberliğe asla sabredemezsin, demedim mi?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 73, 'Mûsâ: “Unuttuğum için beni sorgulama ve bu işimde bana güçlük çıkarma!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 74, 'Yine yola koyuldular. Nihayet bir erkek çocukla karşılaştıklarında, adam (hemen) onu öldürdü. Mûsâ: “Bir cana karşılık olmaksızın masum bir cana mı kıydın? Andolsun çok kötü bir iş yaptın!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 75, '“Ben sana benimle beraberliğe asla sabredemezsin, demedim mi?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 76, '“Eğer bundan sonra sana bir şey soracak olursam artık benimle arkadaşlık etme; o takdirde tarafımdan mazur sayılırsın.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 77, 'Yine yola koyuldular, sonunda ulaştıkları kasaba halkından kendilerine yiyecek istediler. Kasaba halkı onları misafir etmek istemedi. Onlar da orada yıkılmaya yüz tutmuş bir duvar buldular. O (Hızır), bunu doğrulttu. Mûsâ: "Eğer isteseydin buna karşılık bir ücret alabilirdin." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 78, 'İşte bu benimle senin aranda ayrılış (vaktidir). Şimdi sana sabredemediğin şeylerin açıklamasını haber vereceğim dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 79, '"O gemi, denizde çalışan birtakım yoksul kimselere ait idi. Onu kusurlu kılmak istedim. (Çünkü) onların önünde, her (sağlam) gemiyi gasbetmekte olan bir kral vardı.''''');
INSERT INTO verses (sura, aya, text) VALUES (18, 80, 'Gence gelince, onun anne ve babası Mümin idi. Gencin onları azgınlık ve küfre sürüklemesinden korktuk.');
INSERT INTO verses (sura, aya, text) VALUES (18, 81, '''Böylece Rablerinin onlara, bu çocuğun yerine daha hayırlı ve daha merhametli bir çocuk vermesini diledik.''''');
INSERT INTO verses (sura, aya, text) VALUES (18, 82, 'Duvar ise şehirdeki iki yetim gence aitti. Altında da onlara ait bir hazine vardı. Babaları salih insandı. Rabbin, onların olgunluk çağına ulaşmasını ve Rabbinden bir rahmet olarak hazinelerini çıkarmalarını istedi. Ben, bunları kendiliğimden yapmadım. İşte bu sabredemediğin şeylerin açıklamasıdır.');
INSERT INTO verses (sura, aya, text) VALUES (18, 83, 'Sana Zülkarneyn’i soruyorlar. De ki: Ona dair size bir haber okuyacağım.');
INSERT INTO verses (sura, aya, text) VALUES (18, 84, 'Biz onu yeryüzünde kudret sahibi kıldık ve kendisine her konuda (amacına ulaşabileceği) bir yol verdik.');
INSERT INTO verses (sura, aya, text) VALUES (18, 85, 'O da bir yol tuttu.');
INSERT INTO verses (sura, aya, text) VALUES (18, 86, 'Nihayet Güneşin battığı yere ulaşınca onu kara çamurlu bir pınarda batıyor gördü. Onun yanında da bir kavim buldu. Dedik ki: “Ey Zülkarneyn! Onları istersen azaplandırabilirsin yahut onlara güzel muamelede de bulunabilirsin.''''');
INSERT INTO verses (sura, aya, text) VALUES (18, 87, 'Dedi ki: “Kim zulmederse onu azaplandıracağız. Sonra o Rabbine döndürülecek, Rabbi de onu şiddetli bir azap ile azaplandıracak.');
INSERT INTO verses (sura, aya, text) VALUES (18, 88, 'Fakat, kim de iman eder ve salih amel işlerse, ona da iyi bir mükâfat vardır. Ona emrimizden kolay olanı söyleriz.');
INSERT INTO verses (sura, aya, text) VALUES (18, 89, 'Sonra yine (doğuya doğru) bir yol tuttu.');
INSERT INTO verses (sura, aya, text) VALUES (18, 90, 'Güneşin doğduğu yere ulaşınca, onu kendileriyle Güneş arasına örtü koymadığımız bir millet üzerine doğar buldu.');
INSERT INTO verses (sura, aya, text) VALUES (18, 91, 'İşte böyle. Onun yanında olan her şeyi büsbütün kuşatmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (18, 92, 'Sonra bir yol tuttu.');
INSERT INTO verses (sura, aya, text) VALUES (18, 93, 'Nihayet iki dağ arasına ulaştığı zaman, önlerinde hemen hemen hiçbir söz anlamayan bir kavme rastladı.');
INSERT INTO verses (sura, aya, text) VALUES (18, 94, 'Dediler ki: “Ey Zülkarneyn! Ye’cüc ve Me’cüc (adlı kavimler) yeryüzünde bozgunculuk yapmaktadırlar. Onlarla bizim aramıza bir engel yapman karşılığında sana bir vergi verelim mi?”');
INSERT INTO verses (sura, aya, text) VALUES (18, 95, '“Rabbimin bana verdiği imkân ve kudret, (sizin vereceğiniz vergiden) daha hayırlıdır. Şimdi siz bana gücünüzle yardım edin de, sizinle onların arasına sağlam bir set yapayım” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 96, '“Bana (yeterince) demir madeni getirin” dedi. İki yamacın arasındaki boşluğu (dağlarla) bir hizaya getirince; “Körükleyin!” dedi. Demiri eritip kor (gibi) yapınca da; “Bana erimiş bakır getirin, bunun üzerine boşaltayım.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 97, 'Artık onu ne aşabildiler, ne de delebildiler.');
INSERT INTO verses (sura, aya, text) VALUES (18, 98, '“İşte bu, Rabbimden bir rahmettir. Rabbimin vaadi gelince onu dümdüz eder, Rabbimin vaadi haktır.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 99, 'Günü gelince biz onları bırakırız, dalga dalga birbirlerine karışırlar. Sûr’a üflendiği zaman da hepsini bir araya toplarız.');
INSERT INTO verses (sura, aya, text) VALUES (18, 100, 'O gün Cehennem''i kâfirlerin karşısına getirir, sunarız.');
INSERT INTO verses (sura, aya, text) VALUES (18, 101, 'Onlar, gözleri beni anmaktan perdeli olan ve dinleyecek güçleri de olmayan kimselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (18, 102, 'Kâfirler, beni bırakıp da kullarımı veliler/ilahlar edineceklerini mi sandılar? Biz, Cehennem''i kâfirler için konak olarak hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (18, 103, '(Ey Muhammed!) De ki: Amelleri bakımından hüsranda olan kimseleri size haber verelim mi?');
INSERT INTO verses (sura, aya, text) VALUES (18, 104, 'Onlar, dünya hayatındaki bütün amelleri boşa gitmişken, kendilerini gerçekte güzel iş yapmakta sanan kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 105, 'İşte onlar, rablerinin ayetlerini ve O’na kavuşmayı inkâr eden, bu yüzden amelleri boşa gitmiş olanlardır. Bu sebeple biz kıyamet gününde onların (dünyadaki) amellerine değer vermeyiz.');
INSERT INTO verses (sura, aya, text) VALUES (18, 106, 'İşte; kâfir oldukları, âyetlerimi ve rasûllerimi alaya aldıkları için onların cezası Cehennem''dir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 107, 'Gerçekten iman edip salih ameller işleyenlerin ise konakları Firdevs Cennetleri''dir.');
INSERT INTO verses (sura, aya, text) VALUES (18, 108, 'Onlar orada ebedî kalıcıdırlar. Oradan ayrılmak da istemezler.');
INSERT INTO verses (sura, aya, text) VALUES (18, 109, 'De ki: “Rabbimin sözleri için deniz(ler) mürekkep olsa, buna destek olarak bir o kadar daha katsak Rabbimin sözleri tükenmeden o deniz(ler) tükenir.”');
INSERT INTO verses (sura, aya, text) VALUES (18, 110, 'De ki: "Ben de ancak sizin gibi bir insanım! Bana ilahınızın sadece tek ilah olduğu vahyediliyor. Kim Rabbine kavuşmayı umuyorsa, salih amel işlesin ve Rabbine ibadetinde kimseyi ortak koşmasın!"');
INSERT INTO verses (sura, aya, text) VALUES (19, 1, 'Kâf, Hâ, Yâ, Ayn, Sâd.[1]');
INSERT INTO verses (sura, aya, text) VALUES (19, 2, 'Bu, Rabbinin Zekeriya kuluna olan merhametinin zikredilmesidir.');
INSERT INTO verses (sura, aya, text) VALUES (19, 3, 'Hani o, Rabbine gizlice yalvarmıştı.');
INSERT INTO verses (sura, aya, text) VALUES (19, 4, 'O, şöyle demişti: "Rabbim! Şüphesiz kemiklerim zayıflayıp gevşedi ve ağarmış saçıyla başım yaşlılık aleviyle tutuştu. Sana dua etmekle de ey Rabbim, hiç bir zaman bedbaht olmadım."');
INSERT INTO verses (sura, aya, text) VALUES (19, 5, '"Ben arkamdan gelecek yakınlarım için endişeliyim. Karım ise kısırdır, bana katından bir evlat bağışla."');
INSERT INTO verses (sura, aya, text) VALUES (19, 6, '"Bana da Yakupoğulları''na mirasçı olsun. Rabbim onu razı olacağın bir kimse kıl."');
INSERT INTO verses (sura, aya, text) VALUES (19, 7, '“Ey Zekeriya! Gerçekten biz sana Yahya adında bir oğul müjdeleriz. Bundan önce kimseye bu adı vermemiştik.”');
INSERT INTO verses (sura, aya, text) VALUES (19, 8, '“Rabbim! Hanımım kısır ve ben de son derece kocamışken nasıl oğlum olur ki?”dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 9, '(Melek) Dedi ki: “Öyle. (Ama) Rabbin buyurdu ki: Bu, benim için pek kolaydır. Çünkü sen daha önce bir şey değilken seni yarattım.”');
INSERT INTO verses (sura, aya, text) VALUES (19, 10, 'Zekeriyya: “Rabbim, öyleyse bana (çocuğumun olacağına) bir işaret ver.” dedi. Allah da: “Senin işaretin, sapasağlam olduğun halde insanlarla (üç gün) üç gece konuşamamandır.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 11, 'Derken Zekeriya mabedden halkının karşısına çıktı ve onlara “Sabah akşam (Allah’ı) tesbih edin!” diye işaret etti.');
INSERT INTO verses (sura, aya, text) VALUES (19, 12, '“Ey Yahya! Kitabı tam bir kuvvetle tut.” Biz ona daha çocukken hikmeti verdik.');
INSERT INTO verses (sura, aya, text) VALUES (19, 13, 'Katımızdan bir merhamet ve arınmışlık vermiştik. O takva sahibiydi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 14, 'Ana babasına karşı itaatkârdı. Büyüklük taslayan ve isyankâr bir kimse değildi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 15, 'Doğduğu gün, öldüğü gün ve yeniden dirileceği gün ona selam olsun.');
INSERT INTO verses (sura, aya, text) VALUES (19, 16, 'Kitapta Meryem’i de an! Hani o, ailesinden ayrılarak doğu tarafında inzivaya çekilmişti.');
INSERT INTO verses (sura, aya, text) VALUES (19, 17, 'Sonra onlarla kendi arasında bir perde germişti. Derken biz ona ruhumuzu (Cebrâil’i) gönderdik. Ona tam bir insan suretinde göründü.');
INSERT INTO verses (sura, aya, text) VALUES (19, 18, 'Meryem: “Senden Rahman’a sığınırım, eğer takvâ sahibi bir kimse isen” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 19, 'Cebrail: “Ben ancak Rabbinin elçisiyim. Sana tertemiz bir çocuk bağışlamak için gönderildim.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 20, 'Meryem: “Bana hiçbir insan dokunmadığı ve iffetsiz bir kadın olmadığım hâlde, benim nasıl çocuğum olabilir?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 21, 'Cebrâil: “Evet, öyle! Rabbin diyor ki: O benim için çok kolaydır. Onu insanlara bir mucize, katımızdan bir rahmet kılmak için böyle takdir ettik. Bu, zaten (ezelde) hükme bağlanmış bir iştir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 22, 'Böylelikle ona gebe kaldı da böylece onunla ıssız bir yere çekildi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 23, 'Doğum sancısı onu bir hurma ağacına yöneltti. “Keşke bundan önce ölseydim de büsbütün unutulup gitmiş olsaydım!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 24, 'Bunun üzerine (İsâ) Onun (Meryem''in) altından şöyle seslendi: “Üzülme, Rabbin senin alt tarafından bir su arkı kılmıştır.”');
INSERT INTO verses (sura, aya, text) VALUES (19, 25, '''Hurma ağacını kendine doğru silkele ki, sana taze hurma dökülsün.''''');
INSERT INTO verses (sura, aya, text) VALUES (19, 26, 'Ye, iç, gözün aydın olsun. İnsanlardan birini görecek olursan; “Şüphesiz ben Rahmân’a susmayı adadım. Bugün hiçbir insan ile konuşmayacağım.” de!');
INSERT INTO verses (sura, aya, text) VALUES (19, 27, 'Onu taşıyarak kavmine götürdü: “Ey Meryem! Gerçekten sen görülmedik bir iş yaptın” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 28, '"Ey Hârûn’un kızkardeşi! Baban kötü birisi değildi, annen de iffetsiz değildi." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 29, 'Bunun üzerine (çocuğu) işaret etti. "Onlar da biz, beşikteki bir çocukla nasıl konuşabiliriz?" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 30, 'Dedi ki: "Muhakkak ben Allah’ın kuluyum. Bana o kitabı vermiş ve beni nebî kılmıştır."');
INSERT INTO verses (sura, aya, text) VALUES (19, 31, '"Nerede olursam olayım beni mübarek kıldı ve yaşadığım müddetçe namaz kılmamı ve zekât vermemi emretti."');
INSERT INTO verses (sura, aya, text) VALUES (19, 32, '“Beni anama saygılı kıldı. Beni azgın bir zorba kılmadı.”');
INSERT INTO verses (sura, aya, text) VALUES (19, 33, '“Doğduğum gün, öleceğim gün ve diriltileceğim gün bana selâm olsun.”');
INSERT INTO verses (sura, aya, text) VALUES (19, 34, 'İşte hakkında şüpheye düştükleri Meryem oğlu İsâ hak söze göre budur.');
INSERT INTO verses (sura, aya, text) VALUES (19, 35, 'Allah’ın çocuk edinmesi olacak bir şey değildir. O, bundan münezzehtir. Bir işe hükmettiğinde ona yalnızca “Ol!” der, o da oluverir.');
INSERT INTO verses (sura, aya, text) VALUES (19, 36, 'Şüphesiz Allah, benim de sizin de Rabbinizdir. Öyleyse (sadece) O’na ibadet edin. Dosdoğru yol budur.');
INSERT INTO verses (sura, aya, text) VALUES (19, 37, 'Fırkalar, kendi aralarında anlaşmazlığa düştüler. Büyük bir günü görüp yaşayacakları için kâfirlerin vay haline.');
INSERT INTO verses (sura, aya, text) VALUES (19, 38, 'Bize gelecekleri gün, ne kadar iyi işitecek, ne kadar da iyi görecekler! Ama bugün o zalimler apaçık bir sapıklık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 39, 'Onları işin hükme bağlanacağı hasret günüyle uyar! Onlar (dünyada bu hususta) gaflet içindedirler ve onlar iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 40, 'Arza ve üzerindekilere elbet biz mirasçı oluruz ve yalnız bize döndürülürler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 41, 'Kitapta İbrahim’i de an. O son derece doğru sözlü bir peygamberdi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 42, '"Babacığım! İşitmeyen, görmeyen ve sana hiçbir faydası olmayan şeylere niçin ibadet ediyorsun?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 43, '"Babacığım! Gerçekten sana gelmeyen ilim bana gelmiştir. Hadi bana uy da seni dosdoğru bir yola ileteyim."');
INSERT INTO verses (sura, aya, text) VALUES (19, 44, '"Babacığım! Şeytan''a ibadet etme! Çünkü Şeytan Rahman’a asi olmuştur."');
INSERT INTO verses (sura, aya, text) VALUES (19, 45, '“Babacığım, doğrusu Rahman’ın azabı sana dokunur da şeytanın velisi olursun, diye korkarım.”');
INSERT INTO verses (sura, aya, text) VALUES (19, 46, '"Ey İbrahim! Benim ilahlarımdan yüz mü çeviriyorsun? Eğer bundan vazgeçmezsen seni elbette taşlarım. Uzun bir müddet benden uzak dur." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 47, 'İbrahim: "Selam olsun sana!" dedi. "Senin için Rabbimden mağfiret dileyeceğim. Zira o bana çok merhamet edip lütfeder."');
INSERT INTO verses (sura, aya, text) VALUES (19, 48, '“Ben sizi de, sizin Allah’tan başka taptıklarınızı da terk ediyorum. Yalnız Rabbime dua ediyorum. Rabbime dua etmekle bedbaht olmayacağımı ümit ederim.''''');
INSERT INTO verses (sura, aya, text) VALUES (19, 49, 'Onlardan ve Allah’tan başka ibadet ettikleri (ilahlardan) uzaklaşınca, O’na İshak’ı ve Ya''kûb ’u bahşettik. Hepsini de peygamber yaptık.');
INSERT INTO verses (sura, aya, text) VALUES (19, 50, 'Onlara rahmetimizden bağışta bulunduk. Onlar için yüce bir doğruluk dili var ettik (güzel bir söz ile anılmalarını temin ettik).');
INSERT INTO verses (sura, aya, text) VALUES (19, 51, 'Kitapta Mûsâ''yı da an. Şüphesiz o, ihlâsa erdirilmiş bir rasul ve bir peygamberdi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 52, 'Ona, Tûr dağının sağ tarafından seslendik ve kendisi ile konuşmak için kendimize yaklaştırdık.');
INSERT INTO verses (sura, aya, text) VALUES (19, 53, 'O’na rahmetimizden kardeşi Hârûn’u peygamber olarak bağışlamıştık.');
INSERT INTO verses (sura, aya, text) VALUES (19, 54, 'Kitapta İsmail’i de an. O, sözüne sadıktı ve rasûl bir peygamber idi .');
INSERT INTO verses (sura, aya, text) VALUES (19, 55, 'Ailesine namazı ve zekâtı emrederdi. Rabbinin yanında razı olunan birisiydi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 56, 'Kitapta İdris''i de an. Gerçekten o çok doğru sözlü bir peygamberdi.');
INSERT INTO verses (sura, aya, text) VALUES (19, 57, 'Biz onu yüce bir makama yükselttik.');
INSERT INTO verses (sura, aya, text) VALUES (19, 58, 'İşte onlar, Âdem’in ve Nûh ile birlikte taşıdıklarımızın soyundan gelen, Allah’ın kendilerine nimet verdiği peygamberlerden ve İbrahim’in, İsrail''in/Ya''kûb''un soyundan, doğruya ulaştırdığımız ve seçkin kıldığımız kimselerdendir. Onlara Rahman’ın ayetleri okunduğu zaman ağlayarak secdeye kapanırlardı.');
INSERT INTO verses (sura, aya, text) VALUES (19, 59, 'Ama onların ardından namazı zayi eden ve şehvetlerine uyan bir nesil geldi. İşte onlar gayy ile karşılaşacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (19, 60, 'Ancak tevbe edip, iman ederek salih amel işleyenler, işte bunlar Cennet''e girecekler ve hiçbir şekilde haksızlığa uğramayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (19, 61, 'Rahman’ın kullarına gayb ile vaat ettiği Adn cennetlerine (gireceklerdir). Onun vaadi şüphesiz yerine gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (19, 62, 'Orada boş söz işitmezler. Ancak selam (işitirler). Ve orada, sabah akşam kendilerine ait rızıkları vardır.');
INSERT INTO verses (sura, aya, text) VALUES (19, 63, 'İşte kullarımızdan takvâ sahibi olanlara miras olarak vereceğimiz cennet budur.');
INSERT INTO verses (sura, aya, text) VALUES (19, 64, 'Biz ancak Rabbinin emriyle ineriz. Önümüzdeki, arkamızdaki ve bunların arasındaki her şey O’na aittir. Rabbin unutmuş değildir.');
INSERT INTO verses (sura, aya, text) VALUES (19, 65, 'O; göklerin, yerin ve ikisi arasındakilerin Rabbidir. O halde sadece O’na ibadet et ve ibadet etmede sabırlı, sebatkâr ol. O’nun hiç adaşının/benzerinin olduğunu biliyor musun?');
INSERT INTO verses (sura, aya, text) VALUES (19, 66, 'İnsan: “Ben öldükten sonra mı diriltilip çıkarılacakmışım?” der.');
INSERT INTO verses (sura, aya, text) VALUES (19, 67, 'İnsan, daha önce hiçbir şey değilken kendisini yarattığımızı hiç düşünmüyor mu?');
INSERT INTO verses (sura, aya, text) VALUES (19, 68, 'Rabbine andolsun ki, onları ve Şeytanları bir araya toplayacağız ve sonra onları diz üstü çökmüş vaziyette Cehennem''in çevresinde hazır bulunduracağız.');
INSERT INTO verses (sura, aya, text) VALUES (19, 69, 'Sonra her bir topluluktan, Rahman’a karşı en isyankâr olanları mutlaka çekip çıkaracağız.');
INSERT INTO verses (sura, aya, text) VALUES (19, 70, 'Sonra biz ona (Cehennem''e) girmeye kimlerin en layık olduğunu daha iyi bilmekteyiz.');
INSERT INTO verses (sura, aya, text) VALUES (19, 71, 'Sizden ona uğramayacak kimse yoktur. Bu Rabbinin yapmayı üzerine aldığı kesin bir hükmüdür.');
INSERT INTO verses (sura, aya, text) VALUES (19, 72, 'Sonra, takva sahiplerini kurtaracağız, zalimleri de orada dizüstü çökmüş olarak bırakacağız.');
INSERT INTO verses (sura, aya, text) VALUES (19, 73, 'Ayetlerimiz kendilerine apaçık bir şekilde okunduğu zaman, kâfir olanlar, iman edenlere; "İki gruptan hangisi makam bakımından daha iyi ve topluluk bakımından daha güzeldir?" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 74, 'Biz onlardan önce mal, mülk ve görünüm bakımından daha güzel olan nice nesilleri helâk ettik.');
INSERT INTO verses (sura, aya, text) VALUES (19, 75, 'De ki: “Kim sapıklıkta ise Rahman ona verdiği mühleti uzattıkça uzatır. Nihayet kendilerine vaat olunanı, ya azabı yahut kıyameti göreceklerinde hangisinin makamca daha kötü ve askerce daha zayıf olduğunu bileceklerdir."');
INSERT INTO verses (sura, aya, text) VALUES (19, 76, 'Allah hidayete erenlerin hidayetini arttırır. Kalıcı olan salih ameller ise sevap bakımından da Rabbin yanında hayırlıdır, âkıbetçe de daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (19, 77, '(Rasûlüm) Ayetlerimizi inkâr eden ve muhakkak; “Bana elbette mal ve evlat verilecek!” diyen kimseyi gördün mü?');
INSERT INTO verses (sura, aya, text) VALUES (19, 78, 'O gaybı mı tanık oldu, yoksa Rahman’dan bir söz mü almış?');
INSERT INTO verses (sura, aya, text) VALUES (19, 79, 'Hayır! Biz, onun söylediklerini yazacağız ve azabını arttırdıkça arttıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (19, 80, 'Onun söylemekte olduğuna (mal ve çocuklarına) biz mirasçı olacağız. O tek başına bize gelecek.');
INSERT INTO verses (sura, aya, text) VALUES (19, 81, 'Kendilerine güç (izzet) sağlasınlar diye, Allah''tan başka ilahlar edindiler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 82, 'Hayır! O ilahlar, onların kendilerine yaptığı ibadeti inkâr edecekler ve onlara karşı olacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (19, 83, 'Bilmez misin ki biz şeytanları kâfirler üzerine salarız da onları alabildiğine (isyana) kışkırtırlar.');
INSERT INTO verses (sura, aya, text) VALUES (19, 84, 'O halde onlar için acele etme. Biz onların günlerini sayıp duruyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (19, 85, 'O gün, muttakileri konuk olarak Rahman’ın huzurunda toplarız.');
INSERT INTO verses (sura, aya, text) VALUES (19, 86, 'Günahkârları ise susuz olarak Cehennem''e süreriz.');
INSERT INTO verses (sura, aya, text) VALUES (19, 87, 'Rahman’ın katında söz almış olanlardan başka hiçbir kimse şefaat edemez.');
INSERT INTO verses (sura, aya, text) VALUES (19, 88, 'Onlar: "Rahman, bir çocuk edindi." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (19, 89, 'Andolsun ki siz, pek çirkin bir şey söylediniz.');
INSERT INTO verses (sura, aya, text) VALUES (19, 90, 'Bu söz yüzünden neredeyse gökler parçalanacak, yer yarılacak ve dağlar yıkılıp yerle bir olacaktı.');
INSERT INTO verses (sura, aya, text) VALUES (19, 91, 'Rahman’a çocuk iddiasında bulundular.');
INSERT INTO verses (sura, aya, text) VALUES (19, 92, 'Hâlbuki Rahman’a bir çocuk edinmek yakışmaz.');
INSERT INTO verses (sura, aya, text) VALUES (19, 93, 'Göklerde ve yerde kim varsa hepsi Rahman’ın huzuruna ancak kul olarak gelir.');
INSERT INTO verses (sura, aya, text) VALUES (19, 94, 'O, onların hepsini (ilmi ile kuşatmış) ve onları bir bir saymıştır.');
INSERT INTO verses (sura, aya, text) VALUES (19, 95, 'Hepsi de ona kıyamet günü tek olarak gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (19, 96, 'Muhakkak iman edip, salih amel işleyenlere Rahman bir sevgi verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (19, 97, 'Muttakileri müjdelemen ve inatçı bir kavmi uyarman için, bu Kur’an’ı senin dilin ile kolaylaştırdık.');
INSERT INTO verses (sura, aya, text) VALUES (19, 98, 'Onlardan önce nice nesilleri yok ettik. Onlardan hiçbirini hissediyor veya onlara ait en küçük bir ses işitiyor musun?');
INSERT INTO verses (sura, aya, text) VALUES (20, 1, 'Tâ-hâ [1]');
INSERT INTO verses (sura, aya, text) VALUES (20, 2, 'Biz sana Kur’ân’ı güçlük çekmen için indirmedik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 3, 'Ancak Allah''tan korkanlara bir öğüt olsun diye indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 4, 'O, yeri ve yüksek gökleri yaratan Allah tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (20, 5, 'Rahman Arş''a istivâ etmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (20, 6, 'Göklerde, yerde ve ikisinin arasında ve toprağın altında olan her şey O’nundur.');
INSERT INTO verses (sura, aya, text) VALUES (20, 7, 'Sen sözünü açığa vursan bile muhakkak O saklı olanı da gizli olanı da bilir.');
INSERT INTO verses (sura, aya, text) VALUES (20, 8, 'Allah odur ki Ondan başka (hak) ilâh yoktur. En güzel isimler yalnız Onundur.');
INSERT INTO verses (sura, aya, text) VALUES (20, 9, 'Mûsâ’nın haberi sana geldi mi?');
INSERT INTO verses (sura, aya, text) VALUES (20, 10, 'Hani bir ateş görmüştü de ailesine: "Siz durun, ben bir ateş gördüm. Belki size ondan bir kor getiririm veya ateşin yanında bir yol gösteren bulurum." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (20, 11, 'Ateşin yanına geldiği zaman: "Ey Mûsâ!" diye seslenildi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 12, '"Ben senin Rabbinim! Ayakkabılarını çıkar. Sen mukaddes Tûvâ Vadisi''ndesin."');
INSERT INTO verses (sura, aya, text) VALUES (20, 13, 'Ben seni seçtim. Şimdi sana vahyolunanı dinle.');
INSERT INTO verses (sura, aya, text) VALUES (20, 14, '"Şüphesiz ben, Allah’ım. Benden başka (hak) ilah yok! Bana ibadet et, beni anmak için namazı ikame et."');
INSERT INTO verses (sura, aya, text) VALUES (20, 15, '"Muhakkak kıyamet saati gelecektir. Her nefis yaptığının karşılığını görsün diye vaktini neredeyse büsbütün gizli tutacağım."');
INSERT INTO verses (sura, aya, text) VALUES (20, 16, '“Ona iman etmeyen ve hevâsına uyan kimse ondan seni alıkoymasın. O takdirde helâk olursun.”');
INSERT INTO verses (sura, aya, text) VALUES (20, 17, 'Şu sağ elindeki nedir Ey Mûsâ?');
INSERT INTO verses (sura, aya, text) VALUES (20, 18, '"O asamdır. Ona dayanırım. Onunla koyunlarıma yaprak silkerim ve ondan başka işlerimde de yararlanırım." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 19, '"Onu at, ey Mûsâ!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 20, 'Mûsâ da onu attı. O bir anda hızla hareket eden bir yılan oluverdi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 21, '"Onu al ve korkma!" dedi. "Onu ilk haline döndüreceğiz."');
INSERT INTO verses (sura, aya, text) VALUES (20, 22, '"Başka bir alâmet olmak üzere de elini koltuğunun altına götür. Kusursuz, hastalıksız, bembeyaz olarak çıkacaktır."');
INSERT INTO verses (sura, aya, text) VALUES (20, 23, 'Böylece sana büyük mucizelerimizden gösterelim.');
INSERT INTO verses (sura, aya, text) VALUES (20, 24, 'Firavun’a git, çünkü o iyice azdı.');
INSERT INTO verses (sura, aya, text) VALUES (20, 25, '"Rabbim gönlüme ferahlık ver!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 26, 'İşimi kolaylaştır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 27, 'Dilimdeki düğümü çöz.');
INSERT INTO verses (sura, aya, text) VALUES (20, 28, 'Sözümü iyi anlasınlar.');
INSERT INTO verses (sura, aya, text) VALUES (20, 29, 'Bana ailemden bir yardımcı ver.');
INSERT INTO verses (sura, aya, text) VALUES (20, 30, 'Kardeşim Hârûn’u.');
INSERT INTO verses (sura, aya, text) VALUES (20, 31, 'Onunla arkamı güçlendir.');
INSERT INTO verses (sura, aya, text) VALUES (20, 32, 'Ve onu işimde ortak yap ki');
INSERT INTO verses (sura, aya, text) VALUES (20, 33, 'Seni çokça tesbih edebilelim.');
INSERT INTO verses (sura, aya, text) VALUES (20, 34, 'Ve seni çokça zikredelim.');
INSERT INTO verses (sura, aya, text) VALUES (20, 35, 'Çünkü sen bizi hakkıyla görensin.');
INSERT INTO verses (sura, aya, text) VALUES (20, 36, '"Ey Mûsâ! İstediklerin sana verilmiştir." diye buyurdu.');
INSERT INTO verses (sura, aya, text) VALUES (20, 37, '"Andolsun ki sana başka bir sefer daha lütufta bulunmuştuk.''''');
INSERT INTO verses (sura, aya, text) VALUES (20, 38, '"Bir zaman, annene ilham edilmesi gerekeni şeyi ilham etmiştik."');
INSERT INTO verses (sura, aya, text) VALUES (20, 39, 'Mûsâ''yı bir sandığa koy ve nehre (Nil''e) bırak. Nehir onu kıyıya atsın da, onu benim ve onun bir düşmanı alsın. Sana da ey Mûsâ! Gözümün önünde yetiştirilmen için tarafımdan sana bir sevgi bıraktım."');
INSERT INTO verses (sura, aya, text) VALUES (20, 40, 'Kız kardeşin gitmiş ve: "O’na bakacak birini size göstereyim mi?" demişti. Böylece seni, gözü aydın olsun ve üzülmesin diye annene geri döndürdük. Sen bir adam öldürmüştün de, seni yine üzüntüden kurtarmıştık. Bu şekilde seni (önceden de) imtihan etmiştik. Senelerce Medyen halkı arasında kalmıştın. Sonra da bir takdir üzere geldin ey Mûsâ!');
INSERT INTO verses (sura, aya, text) VALUES (20, 41, 'Ve seni kendim için (rasûl olarak) seçtim.');
INSERT INTO verses (sura, aya, text) VALUES (20, 42, 'Sen ve kardeşin âyetlerimle gidin. Beni anmakta gevşeklik göstermeyin.');
INSERT INTO verses (sura, aya, text) VALUES (20, 43, 'İkiniz Firavun’a gidin. Çünkü o haddini aşmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 44, 'Ona yumuşak söz söyleyin, umulur ki öğüt alır ve korkar.');
INSERT INTO verses (sura, aya, text) VALUES (20, 45, '“Rabbimiz, biz, bize karşı aşırı gitmesinden yahut azgınlığını arttırmasından korkarız” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (20, 46, '"Korkmayın! Ben sizinle beraberim. İşitir ve görürüm." diye buyurdu.');
INSERT INTO verses (sura, aya, text) VALUES (20, 47, 'Haydi gidin ona ve deyin ki: "Biz, Rabbinin rasûlleriyiz. İsrailoğulları''nı bizimle gönder, onlara eziyet etme. Biz sana Rabbinden bir ayet getirdik. Selam hidayete uyanlarındır."');
INSERT INTO verses (sura, aya, text) VALUES (20, 48, '"Bize vahyolundu ki, kim yalanlar ve yüz çevirirse ona azap vardır."');
INSERT INTO verses (sura, aya, text) VALUES (20, 49, '"Sizin Rabbiniz kim ey Mûsâ?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 50, '"Bizim Rabbimiz, her şeye yaratılışını veren ve sonra da doğru yolu gösterendir." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 51, '"Önceki nesillerin durumu ne olacak?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 52, '"Onlarla ilgili bilgi Rabbimin katında bir kitaptadır." dedi. "Rabbim, şaşırmaz ve unutmaz."');
INSERT INTO verses (sura, aya, text) VALUES (20, 53, 'O yeryüzünü size bir döşek yapan, sizin için orada yollar açan ve gökten yağmur yağdırandır. Biz onunla çeşitli bitkilerden çifter çifter çıkardık.');
INSERT INTO verses (sura, aya, text) VALUES (20, 54, 'Hem siz yiyin; hem de hayvanlarınızı otlatın. Şüphesiz bunda akıl sahipleri için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 55, 'Sizi topraktan yarattık, sizi oraya döndüreceğiz ve sizi bir kere daha oradan çıkaracağız.');
INSERT INTO verses (sura, aya, text) VALUES (20, 56, 'Ona ayetlerimizin hepsini göstermiştik. Fakat o yalanladı ve diretti.');
INSERT INTO verses (sura, aya, text) VALUES (20, 57, 'Ve dedi ki: "Sihrinle bizi yurdumuzdan çıkarmaya mı geldin Ey Mûsâ?"');
INSERT INTO verses (sura, aya, text) VALUES (20, 58, '"Biz de mutlaka sana karşı onun gibi bir sihir yapacağız. Bunun için seninle bizim aramızda; uygun bir yerde, senin de, bizim de gelebileceğimiz bir buluşma vakti belirle."');
INSERT INTO verses (sura, aya, text) VALUES (20, 59, 'Mûsâ da: "Buluşma zamanımız bayram günü ve insanların bir araya toplandığı kuşluk vaktidir." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 60, 'Firavun dönüp hilesini topladı, sonra geldi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 61, 'Mûsâ onlara: "Yazıklar olsun size! Allah’a karşı yalan uydurmayın. Sonra bir azapla sizi helâk eder. Allah’a karşı yalan uyduran mutlaka hüsrana uğramıştır." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 62, 'Sihirbazlar durumlarını aralarında tartışarak gizlice fısıldaştılar.');
INSERT INTO verses (sura, aya, text) VALUES (20, 63, '"Bu iki sihirbaz sihirleriyle sizi yurdunuzdan çıkarmak ve üstün olan (sihir) yolunuzu da yok etmek istiyor." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (20, 64, '“O bakımdan bütün hilelerinizi bir araya getirip saf saf gelin. Çünkü bugün kim üstün gelirse umduğunu elde eder.”');
INSERT INTO verses (sura, aya, text) VALUES (20, 65, 'Sihirbazlar: “Ey Mûsâ! Ya önce sen at ya da ilk atan biz olalım.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (20, 66, '"Hayır! Siz atın!" dedi. Bunun üzerine ipleri ve değnekleri sihirlerinden ötürü kendisine sanki yürüyorlarmış gibi göründü.');
INSERT INTO verses (sura, aya, text) VALUES (20, 67, 'Mûsâ, içten içe bir korkuya kapıldı.');
INSERT INTO verses (sura, aya, text) VALUES (20, 68, '"Korkma! Şüphesiz sen daha üstünsün." dedik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 69, '"Sağ elindekini (âsânı) at!" Onların yaptığını yutsun. Onların yaptıkları ancak bir büyücü hilesidir. Büyücü nerede olursa olsun kesinlikle kurtuluşa eremez.');
INSERT INTO verses (sura, aya, text) VALUES (20, 70, 'Derken büyücüler secdeye kapandılar. “Hârûn ve Mûsâ ’nın Rabbine iman ettik.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (20, 71, '(Firavun) dedi ki: "Ben size izin vermeden önce ona iman mı ettiniz? Demek ki o, size sihri öğreten büyüğünüzdür. Ben de sizin ellerinizi ve ayaklarınızı çaprazlama kestireceğim ve sizi hurma dalına asacağım. O zaman göreceksiniz hangimizin azabı daha şiddetli ve kalıcı imiş."');
INSERT INTO verses (sura, aya, text) VALUES (20, 72, '"Seni, bize gelen apaçık mucizelere ve bizi yaratana üstün tutmayacağız. Ne hüküm verirsen ver. Sen ancak bu dünya hayatında hüküm verebilirsin." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (20, 73, '"Gerçekten biz, günahlarımızı ve bizi işlemeye zorladığın büyüyü bağışlayarak bizi affetsin diye Rabbimize iman ettik. Allah’ın vereceği mükâfat daha hayırlı ve daha kalıcıdır."');
INSERT INTO verses (sura, aya, text) VALUES (20, 74, 'Gerçek şu ki, kim Rabbine günahkâr olarak gelirse onun için cehennem vardır. Orada ne ölür, ne de (güzel bir hayat) yaşar.');
INSERT INTO verses (sura, aya, text) VALUES (20, 75, 'Kim de Mümin ve salih amel işlemiş olarak gelirse, işte onlar için de en yüksek dereceler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 76, 'İçinde temelli kalacakları, alt kısmından ırmakların aktığı Adn Cennetleri vardır. İşte bu arınanların mükâfatıdır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 77, 'Şüphesiz Mûsâ''ya, yetişilmesinden korkmadan ve (boğulmaktan) endişe duymaksızın kullarımı geceleyin yürüyüşe geçir ve onlara denizde kuru bir yol aç diye vahyettik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 78, 'Firavun askerleriyle onları takip etti. Denizden onları kaplayacak olan su kaplayıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 79, 'Firavun; halkını saptırdı, hidayet yolunu göstermedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 80, 'Ey İsrailoğulları! Sizi düşmanlarınızdan kurtardık. Tûr’un sağ tarafını size vadettik. Size kudret helvası ve bıldırcın indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 81, 'Size rızık olarak verdiklerimizin temiz olanlarından yiyiniz, bu hususta taşkınlık ve nankörlük de etmeyiniz; sonra size gazabım iner. Gazabıma uğrayan yıkılıp yok olur gider.');
INSERT INTO verses (sura, aya, text) VALUES (20, 82, 'Ben elbette, tevbe edeni ve iman edip salih amel işleyen sonra da hidayete erişen kimseyi bağışlarım.');
INSERT INTO verses (sura, aya, text) VALUES (20, 83, '"Mûsâ! Seni milletinden daha çabuk gelmeye sevkeden nedir?" dedik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 84, '“Onlar da arkamdan geliyorlar. Rabbim! Razı olasın diye ben sana (gelmekte) acele ettim.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 85, 'Buyurdu ki: "Senden sonra biz kavmini imtihan ettik. Sonra Sâmirî de onları saptırdı."');
INSERT INTO verses (sura, aya, text) VALUES (20, 86, 'Mûsâ kızgın ve kederli bir şekilde kavmine döndü. Dedi ki: “Ey kavmim, Rabbiniz size güzel bir vaatte bulunmadı mı? Yoksa aradan geçen süre size uzun mu geldi, yahut üzerinize Rabbinizden bir gazabın gelmesini mi istediniz de bana olan vaadinizde durmadınız?”');
INSERT INTO verses (sura, aya, text) VALUES (20, 87, 'Dediler ki, “Sana verdiğimiz sözden kendi isteğimizle caymış değiliz. Fakat biz Mısır halkının mücevheratından yüklü miktarlarda takınmıştık. İşte onları ateşe attık. Sâmirî de aynı şekilde attı.”');
INSERT INTO verses (sura, aya, text) VALUES (20, 88, 'Böylece o, kendilerine böğüren bir buzağı heykeli çıkardı ve: "Bu, sizin ilahınızdır, Mûsâ’nın da ilahıdır. Fakat o unuttu." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (20, 89, 'Onun kendilerine bir sözle cevap vermediğini ve onlara bir zarar veya fayda sağlamaya gücü olmadığını görmüyorlar mı?');
INSERT INTO verses (sura, aya, text) VALUES (20, 90, 'Andolsun ki daha önce Hârûn onlara şöyle demişti: “Kavmim siz bununla ancak sınandınız. Muhakkak sizin Rabbiniz Rahman’dır. O halde bana uyun, emrime itaat edin.”');
INSERT INTO verses (sura, aya, text) VALUES (20, 91, 'Onlar ise: "Mûsâ bize geri dönünceye kadar başında dikilip buna ibadet etmeye devam edeceğiz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (20, 92, '“Ey Hârûn ” dedi. “Onların sapıttıklarını görünce seni alıkoyan ne oldu?');
INSERT INTO verses (sura, aya, text) VALUES (20, 93, '"Bana tabi olmadın, emrime karşı mı geldin?"');
INSERT INTO verses (sura, aya, text) VALUES (20, 94, 'Dedi ki: “Anamın oğlu! Sakalıma, başıma yapışma. Ben, bana: İsrailoğulları arasında tefrika çıkardın ve benim sözüme (neden) uymadın, diyeceğinden korktum.”');
INSERT INTO verses (sura, aya, text) VALUES (20, 95, 'Senin bu yaptığın nedir ey Sâmirî?');
INSERT INTO verses (sura, aya, text) VALUES (20, 96, 'O da: "Onların görmedikleri bir şey gördüm ve elçinin (Cebrâil -aleyhisselam-''ın) izinden bir avuç (toprak) avuçladım ve onu (erimiş mücevheratın içine) attım. İşte nefsim bunu bana hoş gösterdi." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 97, 'Mûsâ: "Haydi git. Artık (ceza olarak) hayatın boyunca bana dokunmayın diyeceksin. Bir de senin için hiç kaçamayacağın bir azap günü var. Üzerine sarılıp ibadet ettiğin ilahına bir bak, şimdi onu yakacağız. Sonra parça parça edip denize savuracağız." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 98, 'Sizin ilahınız ancak, kendisinden başka (hak) ilah olmayan Allah’tır. O her şeyi ilmiyle kuşatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 99, 'İşte geçmiş olanların haberlerinden sana böylece anlatıyoruz. Şüphe yok ki sana katımızdan bir zikir (öğüt) verdik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 100, 'Kim ondan yüz çevirirse şüphesiz ki o, kıyamet gününde ağır bir günah yükü yüklenecektir.');
INSERT INTO verses (sura, aya, text) VALUES (20, 101, 'O kimseler onda ebediyen kalacaklardır. Kıyamet gününde o onlar için ne kötü bir yük olacaktır!');
INSERT INTO verses (sura, aya, text) VALUES (20, 102, 'Sûr’a üflendiği gün, işte o gün suçluların gözleri (korkudan) mavi halde haşrederiz.');
INSERT INTO verses (sura, aya, text) VALUES (20, 103, '"Kendi aralarında gizlice siz ancak on gün kaldınız diye fısıldaşırlar."');
INSERT INTO verses (sura, aya, text) VALUES (20, 104, 'Biz, onların söylediklerini daha iyi biliriz. En tutarlı görüş sahibi olanı “Sadece bir gün kaldınız." der.');
INSERT INTO verses (sura, aya, text) VALUES (20, 105, 'Sana dağlardan soruyorlar. De ki: "Rabbim onları un ufak edecektir."');
INSERT INTO verses (sura, aya, text) VALUES (20, 106, 'Yerlerini de dümdüz edecektir.');
INSERT INTO verses (sura, aya, text) VALUES (20, 107, 'Artık orada ne bir çukur, ne de bir tümsek görebilirsin?');
INSERT INTO verses (sura, aya, text) VALUES (20, 108, 'O günde davetçiye uyarlar. Hiçbir tarafa sapmayarak giderler. Rahman’ın huzurunda sesler kısılmış olacak. Kıpırdayan dudakların fısıltısından başkasını duyamayacaksın.');
INSERT INTO verses (sura, aya, text) VALUES (20, 109, 'O gün, Rahman’ın izin verdiği ve sözünden razı olduğu kimselerden başkasına şefaat fayda vermez.');
INSERT INTO verses (sura, aya, text) VALUES (20, 110, 'Allah; önlerindekini de, arkalarındakini de bilir. Onların hiçbirinin ilmi O''nu kuşatamaz.');
INSERT INTO verses (sura, aya, text) VALUES (20, 111, 'Ve yüzler Hayy ve Kayyum olan Allah için eğilip boyun bükmüştür. Zulüm yüklenen hüsrana uğramıştır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 112, 'Mümin olarak salih amel işleyen kimse, zulme uğratılmaktan da korkmaz, (hakkının) eksiltilmesinden de.');
INSERT INTO verses (sura, aya, text) VALUES (20, 113, 'Böylece onu Arapça bir Kur’ân olarak indirdik ve onda tehditlerimizi tekrar ettik. Olur ki korkarlar yahut o onlara bir ibret ve öğüt olur.');
INSERT INTO verses (sura, aya, text) VALUES (20, 114, 'Gerçek Melik/Hükümran olan Allah yücedir. Sana vahyedilmesi tamamlanmadan önce Kur’an’ı okumakta acele etme ve: “Rabbim! İlmimi arttır.” de.');
INSERT INTO verses (sura, aya, text) VALUES (20, 115, 'Andolsun ki biz daha önce Adem’e vahyetmiştik. Fakat o unuttu, biz onu azimli bulmadık.');
INSERT INTO verses (sura, aya, text) VALUES (20, 116, 'Hani meleklere: Âdem''e secde edin demiştik de, hemen secde ettiler. İblis ise kaçındı.');
INSERT INTO verses (sura, aya, text) VALUES (20, 117, '"Ey Âdem! Bu senin ve eşinin düşmanıdır. Sakın sizi cennetten çıkarmasın; sonra bedbaht, mutsuz olursun." dedik.');
INSERT INTO verses (sura, aya, text) VALUES (20, 118, 'Oysa Cennet''te ne acıkırsın, ne de açık/çıplak kalırsın.');
INSERT INTO verses (sura, aya, text) VALUES (20, 119, 'Ne susuzluk hissedersin, ne de Güneşin sıcağında kalırsın.');
INSERT INTO verses (sura, aya, text) VALUES (20, 120, 'Sonunda Şeytan ona vesvese verdi: "Ey Âdem!" dedi. "Sana ebedilik/sonsuzluk ağacını ve yok olmayacak bir saltanatı göstereyim mi?"');
INSERT INTO verses (sura, aya, text) VALUES (20, 121, 'Nihayet ondan yediler. Bunun üzerine kendilerine ayıp yerleri göründü. Üstlerini cennet yaprağı ile örtmeye çalıştılar. (Bu suretle) Âdem Rabbine âsi olup yolunu şaşırdı');
INSERT INTO verses (sura, aya, text) VALUES (20, 122, 'Sonra Rabbi; onu seçti, tevbesini kabul etti ve hidayete erdirdi.');
INSERT INTO verses (sura, aya, text) VALUES (20, 123, 'Birbirinize düşman olarak hepiniz oradan inin. Benden size bir hidayet gelir de, kim benim hidayetime uyarsa o sapmaz ve bedbaht da olmaz.');
INSERT INTO verses (sura, aya, text) VALUES (20, 124, 'Kim de benim zikrimden yüz çevirirse, gerçekten onun için dar,sıkıntılı bir hayat vardır ve biz onu kıyamet günü kör olarak haşredeceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (20, 125, 'O da şöyle der: "Rabbim beni niçin kör olarak haşrettin? Ben, gören birisiydim."');
INSERT INTO verses (sura, aya, text) VALUES (20, 126, '(Allah da) der ki: "İşte böyle, sana ayetlerimiz gelmişti de sen onları unutmuş idin. Bugün sen de unutulacaksın."');
INSERT INTO verses (sura, aya, text) VALUES (20, 127, 'Haddi aşıp, Rabbinin ayetlerine iman etmeyenleri de böylece cezalandırırız. Ahiret azabı ise elbette daha şiddetli ve daha kalıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 128, 'Kendilerinden önceki nice nesilleri helâk etmiş olmamız, onları hidayete erdirmedi mi? (Oysa) Onların kaldıkları yerlerde gezinip durmaktadırlar. Şüphesiz bunda akıl sahipleri için ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 129, 'Eğer Rabbinden geçmiş bir söz ve belirlenmiş bir süre/ecel olmasaydı, kuşkusuz (azap) kaçınılmaz olurdu.');
INSERT INTO verses (sura, aya, text) VALUES (20, 130, 'Söyledikleri sözlere sabret, Güneş doğmadan önce ve batmadan önce ve gece saatlerinde de Rabbini hamt ederek tesbit et. Gün boyunca da tesbih et ki, hoşnutluğa eresin.');
INSERT INTO verses (sura, aya, text) VALUES (20, 131, 'Onlardan bir kısmına bunlarla kendilerini imtihan edelim diye dünya hayatının süsü olarak verip, faydalandırdığımız şeylere gözlerini dikme. Rabbinin rızkı ise daha hayırlı ve daha kalıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (20, 132, 'Sen aile halkına namazı emret, kendin de sabırla ona devam et. Senden rızık istemiyoruz. Biz seni rızıklandırıyoruz. Güzel akıbet ise takva sahiplerinindir.');
INSERT INTO verses (sura, aya, text) VALUES (20, 133, '"Bize, Rabbinden bir mucize getirmeli değil miydi?" dediler. Önceki kitaplarda olanların apaçık delili (olan Kur’an) onlara gelmedi mi?');
INSERT INTO verses (sura, aya, text) VALUES (20, 134, 'Biz onları bundan önce bir azap ile helâk etmiş olsaydık; elbette şöyle diyeceklerdi: “Rabbimiz, bize bir peygamber gönderseydin de alçalmadan, rezil olmadan önce ayetlerine uysaydık."');
INSERT INTO verses (sura, aya, text) VALUES (20, 135, 'De ki: "Herkes beklemektedir. Siz de bekleyedurun. Yakında kimin doğru yolun sahipleri ve kimin doğru yolu bulmuş olduğunu göreceksiniz."');
INSERT INTO verses (sura, aya, text) VALUES (21, 1, 'İnsanların hesaba çekilmeleri yaklaştı. Hâlbuki onlar gaflet içinde yüz çevirmekteler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 2, 'Rablerinden kendilerine her yeni öğüt geldiğinde, onlar mutlaka onu alay ederek dinlerler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 3, 'Kalpleri başka şeylerle meşguldür. Zulmedenler, aralarında gizlice danışıp: "Bu sizin benzeriniz olan bir beşer değil mi? Öyleyken, siz şimdi gözünüz göre göre büyüye mi geleceksiniz?”');
INSERT INTO verses (sura, aya, text) VALUES (21, 4, 'Peygamber, (onlara) dedi ki: “Rabbim yerdeki ve gökteki her sözü bilir. O, hakkıyla işitendir, hakkıyla bilendir.''''');
INSERT INTO verses (sura, aya, text) VALUES (21, 5, 'Onlar, “Hayır, bunlar (Kur''an) anlamsız rüyalardır. Üstelik, onu kendisi uydurdu; dahası, o bir şairdir. Eğer böyle değilse, önceki peygamberlerin (mucizelerle) gönderildikleri gibi o da bize bir mucize getirsin.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 6, 'Onlardan önce helâk ettiğimiz hiçbir memleket halkı iman etmedi de şimdi bunlar mı iman edecekler?');
INSERT INTO verses (sura, aya, text) VALUES (21, 7, 'Senden önce de ancak kendilerine vahyettiğimiz birtakım erkekleri peygamber gönderdik. Eğer bilmiyorsanız ilim sahiplerine sorun.');
INSERT INTO verses (sura, aya, text) VALUES (21, 8, 'Biz onları yemek yemez birer ceset kılmadık. Onlar ölümsüz de değillerdi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 9, 'Sonra onlara verdiğimiz sözümüzde durup, onları ve dilediğimiz kimseleri kurtarıp, haddi aşanları da helâk ettik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 10, 'Andolsun, size öyle bir kitap indirdik ki sizin bütün şeref ve şanınız ondadır. Hâlâ aklınızı kullanmayacak mısınız?');
INSERT INTO verses (sura, aya, text) VALUES (21, 11, 'Biz zulmetmekte olan nice memleketleri kırıp geçirdik ve onlardan sonra başka kavimler yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (21, 12, 'Onlar azabımızı hissedince, hemen oradan süratle kaçıyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (21, 13, '(Onlara): “Kaçışmayın. İçinde bulunduğunuz refaha ve evlerinize dönün. Çünkü siz sorguya çekileceksiniz” (denildi.)');
INSERT INTO verses (sura, aya, text) VALUES (21, 14, '“Eyvah bizlere! Bizler gerçekten zalim kimseler idik.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 15, 'Biz onları biçilmiş ekin, sönmüş ateş gibi yapıncaya kadar bu feryatları devam etti.');
INSERT INTO verses (sura, aya, text) VALUES (21, 16, 'Biz yeri, göğü ve arasındakileri oyun olsun diye yaratmadık.');
INSERT INTO verses (sura, aya, text) VALUES (21, 17, 'Eğer biz eğlence edinmek isteseydik, elbette onu kendi katımızdan edinirdik. Fakat biz (bunu) yapanlar değiliz.');
INSERT INTO verses (sura, aya, text) VALUES (21, 18, 'Bilâkis, biz hakkı batılın üstüne bırakırız. O da o, batılın işini bitirir. Bir de bakarsın ki batıl, yok olup gitmiştir. (Allah’ı) vasfettiğiniz sıfatlardan dolayı yazıklar olsun size!');
INSERT INTO verses (sura, aya, text) VALUES (21, 19, 'Göklerde ve yerde kim varsa Allah''ındır. O’nun katındakiler, O''na ibadet hususunda kibirlenmez ve yorulmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (21, 20, 'Gece ve gündüz durmaksızın O’nu tesbih ederler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 21, 'Yoksa onlar, yeryüzünde ilahlar edindiler de onlar mı ölüyü diriltecekler?');
INSERT INTO verses (sura, aya, text) VALUES (21, 22, 'Eğer yerde ve gökte Allah’tan başka ilâhlar olsaydı, kesinlikle ikisinin de düzeni bozulurdu. Demek ki, Arş’ın Rabbi Allah, onların vasfettiği sıfatlardan münezzeh ve yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (21, 23, 'O, yaptıklarından sorulmaz, oysa onlar sorguya çekilirler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 24, 'Yoksa O''ndan başka ilahlar mı edindiler? De ki: “Delilinizi getirin. İşte bu, benimle birlikte olanların zikri (kitabı) ve (bu da) benden öncekilerin zikri (kitabı)!” Hayır, onların çoğu hakkı bilmezler; bu yüzden de yüz çevirirler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 25, 'Senden önce gönderdiğimiz bütün peygamberlere: “Şüphesiz, benden başka (hak) ilâh yoktur. Öyleyse yalnız bana ibadet edin!” diye vahyetmişizdir.');
INSERT INTO verses (sura, aya, text) VALUES (21, 26, '(Böyle iken) “Rahmân, çocuk edindi” dediler. O bundan münezzehtir, yücedir. Hayır! (Evlat diye niteledikleri) o melekler ikram edilmiş kullardır.');
INSERT INTO verses (sura, aya, text) VALUES (21, 27, 'Onun sözünün önüne geçmezler ve O''nun emri gereğince iş görürler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 28, 'Allah, onların önlerindekini de arkalarındakini de (yaptıklarını da yapacaklarını da) bilir. Onlar, O’nun razı olduğu kimselerden başkasına şefaat etmezler ve hepsi O’nun korkusuyla titrerler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 29, 'İçlerinden her kim; “Allah’tan başka ben de şüphesiz bir ilâhım” derse, böylesini Cehennem''le cezalandırırız. İşte biz zalimleri böyle cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (21, 30, 'Kâfirler, görmez mi ki gökler ve yer birleşik iken onları (biz) ayırdık ve her şeye sudan hayat verdik. Hâlâ iman etmezler mi?');
INSERT INTO verses (sura, aya, text) VALUES (21, 31, 'Sarsılmasınlar diye yeryüzünde sabit dağlar kıldık, yol bulmaları için orada geniş geniş yollar var ettik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 32, 'Gökyüzünü de korunmuş bir tavan yaptık. Buna rağmen onlar, bundaki ayetlerden yüz çevirmektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 33, 'O, geceyi ve gündüzü, Güneş''i ve Ay''ı yaratandır. Her biri bir yörüngede yüzmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (21, 34, 'Biz, senden önce de hiçbir beşere ölümsüzlük vermedik. Şimdi sen ölürsen, onlar ebedî mi kalacaklar?');
INSERT INTO verses (sura, aya, text) VALUES (21, 35, 'Her nefis ölümü tadıcıdır. Biz sizi şer ve hayırla imtihan olmak üzere deneriz. Sonunda bize döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (21, 36, 'Kâfirler seni gördükleri zaman ancak alaya alırlar. “Bu mu ilâhlarınızı diline dolayan?” derler. Hâlbuki kendileri Rahman’ın kitabını inkâr ediyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (21, 37, 'İnsan çok aceleci (tez canlı) yaratılmıştır. Size yakında âyetlerimi göstereceğim. Şimdi acele etmeyin.');
INSERT INTO verses (sura, aya, text) VALUES (21, 38, 'Bir de; “Eğer doğru söyleyenler iseniz, bu tehdit ne zaman gerçekleşecek?” diyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (21, 39, 'O kâfirler, yüzlerinden ve sırtlarından ateşi savamayacakları ve hiçbir yardım da görmeyecekleri vakti bir bilseler!');
INSERT INTO verses (sura, aya, text) VALUES (21, 40, 'Şüphesiz o (tehdit edildikleri azap) onlara ansızın gelecek de kendilerini şaşkınlıktan dondurup bırakacak. Artık ne onu geri çevirmeye güçleri yetecek, ne de kendilerine göz açtırılacak.');
INSERT INTO verses (sura, aya, text) VALUES (21, 41, 'Andolsun, senden önce de birçok peygamberle alay edildi de içlerinden alay edenleri, o alaya aldıkları şey kuşatıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 42, '(Ey Muhammed!) De ki: “(Size azap edecek olsa) gece ve gündüz Rahmân’ın azabından sizi kim koruyacak?” Öyle iken onlar Rablerinin zikrinden yüz çevirmekteler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 43, 'Yoksa bizim dışımızda onları koruyacak ilâhları mı var? O ilâh edindikleri nesneler kendilerine bile yardım edemezler. Zaten onlar bizden de yardım görmezler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 44, 'Evet, biz onları da atalarını da faydalandırdık. Öyle ki uzun süre yaşadılar. Ama, artık görmüyorlar mı ki, biz yeryüzünü çevresinden eksiltiyoruz? O halde onlar mı galip gelecekler?');
INSERT INTO verses (sura, aya, text) VALUES (21, 45, 'De ki: “Ben sizi ancak vahiy ile uyarıyorum.” Ama sağırlar uyarıldıkları vakit çağrıyı işitmezler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 46, 'Onlara Rabbinin azabından hafif bir şey dokunsa, muhakkak “Eyvah bize! Gerçekten biz zalim kimselerdik” diyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (21, 47, 'Kıyamet günü için adalet terazileri kuracağız. Öyle ki hiçbir kimseye zerre kadar zulmedilmeyecek. (Yapılan iş) bir hardal tanesi ağırlığınca da olsa, onu getirip ortaya koyacağız. Hesap görücü olarak biz yeteriz.');
INSERT INTO verses (sura, aya, text) VALUES (21, 48, 'Andolsun ki biz Mûsâ ile Hârûn’a Furkan’ı takvâ sahiplerine bir ışık ve bir öğüt olarak verdik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 49, 'Onlar, görmedikleri halde Rablerinden korkan ve kıyamet saatinden de çekinen kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (21, 50, 'İşte bu (Kur’an) da bizim indirdiğimiz mübarek bir zikirdir. Şimdi siz bunu mu inkâr ediyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (21, 51, 'Andolsun, daha önce de İbrahim’e rüşdünü/doğruyu yanlıştan ayırma yeteneğini verdik. Biz zaten onu biliyorduk.');
INSERT INTO verses (sura, aya, text) VALUES (21, 52, 'Hani o, babasına ve kavmine: "Kendilerine ibadet edip, durduğunuz bu putlar nedir?" demişti.');
INSERT INTO verses (sura, aya, text) VALUES (21, 53, '"Atalarımızı bunlara ibadet ediyor bulduk.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 54, 'İbrahim: “Andolsun siz de, atalarınız da apaçık bir sapıklık içindesiniz.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 55, '“Sen bize hakkı mı getirdin, yoksa bizimle alay mı ediyorsun?” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 56, 'Dedi ki: "Hayır! Rabbiniz, göklerin ve yerin Rabbidir. O, bunları yaratandır ve ben de buna şahitlik edenlerdenim."');
INSERT INTO verses (sura, aya, text) VALUES (21, 57, '“Allah''a yemin ederim ki, siz arkanızı dönüp gittikten sonra ben bu putlarınıza mutlaka bir tuzak kuracağım.”');
INSERT INTO verses (sura, aya, text) VALUES (21, 58, 'Derken (İbrahim) belki kendisine başvururlar diye içlerinden bir büyüğü bırakarak onları (putları) paramparça etti.');
INSERT INTO verses (sura, aya, text) VALUES (21, 59, 'Onlar: “Bunu putlarımıza kim yaptıysa şüphesiz ki o zalimlerdendir” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 60, '(İçlerinden bazıları), “İbrahim denilen bir gencin onları diline doladığını duyduk” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 61, '(Bir kısmı da) “O halde haydi, onu insanların gözü önüne getirin. Belki (bu konuda) şahitlik ederler” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 62, '(İbrahim gelince) “Sen mi yaptın bunu ilâhlarımıza ey İbrahim!” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 63, '“Hayır! Bunu şu büyükleri yapmıştır. Konuşabiliyorlarsa, onlara sorun bakalım!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 64, 'Bunun üzerine birbirlerine dönüp, “Hiç şüphesiz asıl zalimler sizsiniz siz!” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 65, 'Sonra eski inanç ve inatlarına döndüler ve: “Andolsun, bunların konuşmayacağını sen de bilirsin” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 66, 'İbrahim: "O halde Allah’ı bırakıp da size hiç bir şekilde fayda ya da zarar vermeyen şeylere mi ibadet ediyorsunuz?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 67, '''Yazıklar olsun! Size de, Allah’ı bırakıp tapmakta olduklarınıza da! Hâlâ aklınızı başınıza almayacak mısınız?''''');
INSERT INTO verses (sura, aya, text) VALUES (21, 68, '(İçlerinden bazıları), “Eğer (bir şey) yapacaksanız, onu yakın da ilâhlarınıza yardım edin” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 69, '“Ey ateş! İbrahim’e karşı serin ve esenlik ol!” dedik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 70, 'Ona böyle bir tuzak kurmak istediler. Fakat biz onları en çok zarar edenler durumuna düşürdük.');
INSERT INTO verses (sura, aya, text) VALUES (21, 71, 'Onu Lût ile beraber kurtarıp, içinde âlemler için bereketler kıldığımız yere ulaştırdık.');
INSERT INTO verses (sura, aya, text) VALUES (21, 72, 'Ve ona İshak’ı, üstelik bir de Ya''kûb’u bağışladık. Her ikisini de salih kimseler kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (21, 73, 'Onları emrimizle doğru yolu gösteren önderler kıldık ve kendilerine hayırlar işlemeyi, namazı dosdoğru kılmayı, zekâtı vermeyi vahyettik. Onlar yalnızca bize ibadet eden kimselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 74, 'Biz, Lût’a da bir hikmet ve bir ilim verdik ve onu çirkin işler yapan memleketten kurtardık. Gerçekten onlar kötü bir toplum idiler, fasık (Allah’ın emrinden çıkan kimseler) idiler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 75, 'Ve biz onu rahmetimizin içine aldık. Çünkü o, gerçekten salih kimselerdendi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 76, '(Ey Muhammed!) Nûh’u da an. Hani o daha önce dua etmişti de biz onun duasını kabul ederek, kendisini ve ailesini o büyük sıkıntıdan (tufandan) kurtarmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (21, 77, 'Ayetlerimizi yalanlayanlara karşı ona yardım etmiştik. Çünkü onlar kötü bir toplum idiler. Bu yüzden biz de onları topyekûn suda boğduk.');
INSERT INTO verses (sura, aya, text) VALUES (21, 78, 'Davûd ile Süleyman’ı da hatırla. Hani bir ekin tarlası hakkında hüküm veriyorlardı. Çünkü halkın koyunları o ekine girmişti. Biz de hükümlerine şahit olmuştuk.');
INSERT INTO verses (sura, aya, text) VALUES (21, 79, 'Biz hüküm vermeyi Süleyman’a kavratmıştık. Zaten her birine hükümranlık ve ilim vermiştik. Davûd ile birlikte, Allah’ı tespih etmeleri için dağları ve kuşları onun emrine verdik. Bunları yapan biz idik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 80, 'Bir de Davûd’a, sizin için, zırh yapma sanatını öğrettik ki, savaşlarınızda sizi korusun. Şimdi siz şükrediyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (21, 81, 'Süleyman’ın hizmetine de güçlü esen rüzgârı verdik. Rüzgâr onun emriyle, bereketlendirdiğimiz yere doğru eserdi. Biz, her şeyi hakkıyla bileniz.');
INSERT INTO verses (sura, aya, text) VALUES (21, 82, 'Şeytanlardan onun için denize dalan ve bundan başka işler görenleri de (emrine vermiştik). Onları gözetenler bizlerdik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 83, 'Eyyûb’u da an. Hani o Rabbine: “Şüphesiz ki ben derde uğradım, sen ise merhametlilerin en merhametlisisin” diye niyaz etmişti.');
INSERT INTO verses (sura, aya, text) VALUES (21, 84, 'Biz onun duasını kabul ettik ve başındaki sıkıntıyı açıp giderdik. Ayrıca ona hem katımızdan bir rahmet, hem de iyi kullukta bulunanlara bir ibret olmak üzere aile ve çocuklarını ve onlarla birlikte bir o kadarını da verdik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 85, 'İsmail’i, İdris’i ve Zülkifl’i de an. Bunların hepsi sabredenlerdendi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 86, 'Ve onları rahmetimizin içine soktuk. Gerçekten onlar salih kimselerdendi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 87, 'Zünnûn’u da an. Hani öfkelenerek (halkından ayrılıp) gitmişti de kendisini asla darda koymayacağımızı, sanmıştı. Derken karanlıklar içinde, “Senden başka hak ilâh yoktur. Seni eksikliklerden uzak tutarım. Ben gerçekten (nefsine) zulmedenlerden oldum.” diye dua etti.');
INSERT INTO verses (sura, aya, text) VALUES (21, 88, 'Biz de duasını kabul ettik ve kendisini kederden kurtardık. İşte biz Müminleri böyle kurtarırız.');
INSERT INTO verses (sura, aya, text) VALUES (21, 89, 'Zekeriya’yı da an. Hani o, Rabbine, “Rabbim! Beni tek başıma bırakma. Sen varislerin en hayırlısısın.” diye dua etmişti.');
INSERT INTO verses (sura, aya, text) VALUES (21, 90, 'Biz de onun duasını kabul ettik ve kendisine Yahya’yı bağışladık. Eşini de kendisi için, (doğurmaya) elverişli kıldık. Onlar gerçekten hayır işlerinde yarışırlar, (rahmetimizi) umarak ve (azabımızdan) korkarak bize dua ederlerdi. Onlar bize derin saygı duyan kimselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (21, 91, 'Irzını korumuş olan kadını da (Meryem’i de) hatırla. Ona ruhumuzdan üflemiştik. Kendisini de, oğlunu da âlemlere (kudretimizi gösteren) birer delil yapmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (21, 92, 'Şüphe yok ki bu sizin ümmetiniz, tek bir ümmettir. Sizin Rabbiniz de benim. O halde yalnız bana ibadet edin.');
INSERT INTO verses (sura, aya, text) VALUES (21, 93, '(İnsanlar) (din) işlerinde aralarında bölüklere ayrıldılar. Hepsi de ancak bize dönecekler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 94, 'Şu hâlde, kim Mümin olarak salih ameller işlerse, çalışması asla inkâr edilmez. Şüphesiz biz onu yazmaktayız.');
INSERT INTO verses (sura, aya, text) VALUES (21, 95, 'Helâk ettiğimiz bir ülke halkının (dünya hayatına geri) dönmeleri imkânsızdır.');
INSERT INTO verses (sura, aya, text) VALUES (21, 96, 'Nihayet Ye’cüc ve Me’cüc’ün (seddi) açıldığı zaman her tepeden akın ederler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 97, 'Gerçek vaad (kıyametin kopması) yaklaşır, bir de bakarsın kâfirlerin gözleri açılıp donakalmıştır. “Eyvah bizlere! Doğrusu biz bundan gafildik. Hatta biz zalim kimselermişiz.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 98, 'Hiç şüphesiz siz de, Allah’tan başka ibadet etiikleriniz de Cehennem''in odunusunuz. Siz oraya gireceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (21, 99, 'Eğer onlar (hak) ilâh olsalardı buraya girmezlerdi. Hâlbuki hepsi orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (21, 100, 'Onların orada ah edip, derin bir iç çekişleri vardır! Onlar orada hiçbir şey işitmezler.');
INSERT INTO verses (sura, aya, text) VALUES (21, 101, 'Şüphesiz kendileri için tarafımızdan en güzel mükâfat hazırlanmış olanlar var ya; işte bunlar Cehennem''den uzaklaştırılmışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (21, 102, 'Onlar Cehennem''in uğultusunu dahi duymazlar. Nefislerinin arzu ettiği şeyler içinde ebedî kalırlar.');
INSERT INTO verses (sura, aya, text) VALUES (21, 103, 'En büyük korku bile onları tasalandırmaz ve melekler onları: “İşte bu, size vadedilen (mutlu) gününüzdür.” diyerek karşılarlar.');
INSERT INTO verses (sura, aya, text) VALUES (21, 104, 'Gökleri kitap sayfalarının katlandığı gibi katlayacağımız günü düşün. Başlangıçta ilk yaratmayı nasıl yaptıysak, -üzerimize aldığımız bir vaad olarak- onu yine yapacağız. Biz bunu muhakkak yapacağız.');
INSERT INTO verses (sura, aya, text) VALUES (21, 105, 'Andolsun, Zikir’den (Tevrat’tan) sonra Zebûr’da da, “Arza muhakkak benim salih kullarım mirasçı olacaktır.” diye yazmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (21, 106, 'Şüphesiz bunda Allah’a kulluk eden bir toplum için yeterli bir bildiri/öğüt vardır.');
INSERT INTO verses (sura, aya, text) VALUES (21, 107, '(Ey Muhammed!) Seni ancak âlemlere rahmet olarak gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (21, 108, 'De ki: “Bana ancak, ilâhınızın yalnızca bir tek ilâh olduğu vahyolunuyor. Artık Müslüman oluyor musunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (21, 109, 'Eğer yüz çevirirlerse De ki: “Ben size eşit şekilde bildirip, açıkladım. Size vaat olunan yakın mıdır, uzak mıdır bilemiyorum.');
INSERT INTO verses (sura, aya, text) VALUES (21, 110, '''Şüphesiz, Allah sözün açığa vurulanını da bilir, gizlediğinizi de bilir.''''');
INSERT INTO verses (sura, aya, text) VALUES (21, 111, '“Bilmiyorum, belki de o sizin için bir imtihandır. Bir süreye kadar bir faydalanmadır.''''');
INSERT INTO verses (sura, aya, text) VALUES (21, 112, '(Peygamber): “Ey Rabbim! Hak ile hüküm ver. Bizim Rabbimiz, sizin türlü nitelemelerinize karşı yardımı istenecek olan Rahman’dır.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (22, 1, 'Ey insanlar! Rabbinizden sakının. Çünkü kıyametin sarsıntısı büyük bir şeydir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 2, 'Onu göreceğiniz gün, her emzikli kadın emzirmekte olduğu çocuğundan geçer ve her hamile kadın da karnındaki çocuğunu düşürür. İnsanları sarhoş görürsün; hâlbuki onlar sarhoş değillerdir. Ne var ki, Allah’ın azabı çok şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 3, 'İnsanlardan kimi vardır ki, hiçbir bilgisi olmadığı hâlde, Allah hakkında tartışmaya girer ve her azgın Şeytan''ın ardına düşer.');
INSERT INTO verses (sura, aya, text) VALUES (22, 4, 'Şeytan hakkında şöyle yazılmıştır: "Her kim onu dost edinirse, mutlaka o kimseyi saptırır ve onu Cehennem azabına sürükler."');
INSERT INTO verses (sura, aya, text) VALUES (22, 5, 'Ey insanlar! Eğer tekrar dirilmekten şüphede iseniz; şunu bilin ki, biz sizi topraktan, sonra nutfeden (meniden), sonra alakadan (embriyodan), sonra (cesedi) biçimlenen ve biçimlenmeyen bir çiğnem et parçasından yarattık ki, size (kudretimizi) açıkça gösterelim. Dilediğimizi adı konmuş bir süreye kadar rahimlerde tutar ve sizi bebek olarak çıkarırız. Sonra siz yetişip, güçlü çağınıza gelirsiniz. Kiminiz vefat eder, kiminiz de bilen bir kimse olduktan sonra bir şey bilmez hale gelsin diye ömrünün en düşkün dönemine ulaştırılır. Yeryüzünü kupkuru görürsün de biz ona su indirince harekete geçer, kabarır ve her çeşit güzel bitkiyi çift çift bitirir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 6, 'Bu böyledir. Çünkü Allah, hakkın ta kendisidir. Şüphesiz O, ölüleri diriltir ve O, her şeye hakkıyla kadirdir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 7, 'Çünkü kıyamet muhakkak gelecektir. Onda hiçbir şüphe yoktur ve şüphesiz Allah, kabirlerdeki kimseleri diriltecektir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 8, 'İnsanlardan kimisi Allah hakkında bilgisiz, delilsiz ve aydınlatıcı bir kitabı olmaksızın tartışır durur.');
INSERT INTO verses (sura, aya, text) VALUES (22, 9, 'İnsanları Allah’ın yolundan saptırmak için büyüklenerek yüz çevirir. Dünyada onun için rüsvalık vardır, kıyamet günü de biz ona yakıcı ateş azabını tattırırız.');
INSERT INTO verses (sura, aya, text) VALUES (22, 10, '(Ona): “İşte bu kendi ellerinin önceden işledikleri yüzündendir. Allah, kesinlikle kullara zulmedici değildir.” (denir.)');
INSERT INTO verses (sura, aya, text) VALUES (22, 11, 'İnsanlardan öylesi de vardır ki, Allah’a kıyıdan kenardan kulluk eder. Eğer kendisine bir hayır dokunursa, gönlü onunla hoş olur. Şâyet başına bir kötülük gelirse, gerisin geri (küfre) dönüverir. O dünyayı da kaybetmiştir, ahireti de. İşte bu apaçık ziyanın ta kendisidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 12, 'O, Allah’ı bırakır da kendine ne zarar, ne de fayda veren şeylere ibadet eder. İşte bu uzak sapıklığın ta kendisidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 13, 'O, zarar vermesi, fayda vermesinden daha yakın olana ibadet eder. Ne kötü bir yardımcı, ne kötü bir arkadaştır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 14, 'Muhakkak ki Allah, iman edip salih ameller işleyenleri içinden ırmaklar akan cennetlere koyacaktır. Şüphesiz Allah, dilediğini yapar.');
INSERT INTO verses (sura, aya, text) VALUES (22, 15, 'Her kim ona (Muhammed’e) Allah’ın dünyada ve ahirette asla yardım etmeyeceğini zannediyorsa hemen tavana bir ip çeksin, sonra kendini assın da bir baksın. Başvurduğu (bu yöntem), öfkelendiği şeyi giderecek mi?');
INSERT INTO verses (sura, aya, text) VALUES (22, 16, 'Nitekim, biz onu (Kur''an''ı) apaçık ayetler olarak indirdik. Şüphesiz Allah, dilediğini doğru yola iletir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 17, 'Şüphesiz iman edenler, Yahudiler, Sâbiîler, Hristiyanlar, Mecûsiler ve Allah’a ortak koşanlar var ya; Allah, kıyamet günü onların aralarında mutlaka hüküm verecektir. Çünkü Allah, her şeye şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 18, 'Göklerde ve yerde olanlar, Güneş, Ay, yıldızlar, dağlar, ağaçlar, canlılar ve bir çok insanın Allah’a secde ettiklerini görmüyor musun? Birçoğunun üzerine de azap hak olmuştur. Allah kimi alçaltırsa onu değerli kılacak yoktur. Allah, dilediğini yapar.');
INSERT INTO verses (sura, aya, text) VALUES (22, 19, 'İşte bunlar Rableri hakkında tartışan iki hasımdır. Kâfir olanlar için ateşten elbiseler biçilir. Başları üzerinden gayet kaynar su dökülür.');
INSERT INTO verses (sura, aya, text) VALUES (22, 20, 'Onunla karınlarında ne varsa eritilir, derileri de.');
INSERT INTO verses (sura, aya, text) VALUES (22, 21, 'Onlar için bir de demirden topuzlar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 22, 'Her ne zaman Cehennem''den, o ızdıraptan çıkmak isteseler, oraya geri döndürülürler ve onlara: “Yakıcı ateşin azabını tadın!” denilir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 23, 'Şüphesiz Allah, iman edip salih ameller işleyenleri içlerinden ırmaklar akan Cennetlere sokacak, orada altından bileziklerle, incilerle süsleneceklerdir. Oradaki giysileri ise ipektir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 24, 'Onlar hem sözün hoş olanına ulaştırılmışlar, hem de övgüye lâyık olan Allah’ın yoluna iletilmişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 25, 'Muhakkak kâfirlere, Allah''ın yolundan, yerli ve yolcu bütün insanlar için eşit kılınan Mescid-i Haram''dan alıkoyanlara ve de orada zulüm ile haktan sapmak isteyenlere, elim bir azaptan tattırırız.');
INSERT INTO verses (sura, aya, text) VALUES (22, 26, 'Hani biz İbrahim’e Beytin yerini belirtip şöyle demiştik: “Bana hiçbir şeyi ortak koşma, tavaf edenler, orada ikamet edenler, rükû ve secde edenler için Beytimi temizle.');
INSERT INTO verses (sura, aya, text) VALUES (22, 27, 'İnsanlar arasında haccı ilan et ki, gerek yaya olarak, gerek uzak yollardan gelen yorgun develer üzerinde sana gelsinler.');
INSERT INTO verses (sura, aya, text) VALUES (22, 28, 'Gelsinler ki, kendilerine ait birtakım menfaatlere şahit olsunlar ve Allah’ın kendilerine rızık olarak verdiği (kurbanlık) hayvanlar üzerine belli günlerde (onları kurban ederken) Allah’ın adını ansınlar. Artık onlardan siz de yiyin; yoksula, fakire de yedirin.');
INSERT INTO verses (sura, aya, text) VALUES (22, 29, '(Hacılar) Sonra da kirlerini gidersinler (saç ve tırnaklarını kessinler), adaklarını yerine getirsinler ve Beyt-i Atik''i (Kâbe’yi) tavaf etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (22, 30, 'Bu böyle. Kim Allah’ın hürmet edilmesini emrettiği şeyleri tazim ederse bu, Rabbi katında kendisi için bir hayırdır. (Haram olduğu) size okunanların dışında kalan hayvanlar size helâl kılındı. Şu halde pisliğin ta kendisi olan putlardan uzak durun ve yalan söylemekten de kaçının.');
INSERT INTO verses (sura, aya, text) VALUES (22, 31, 'Allah’a yönelen, O’na ortak koşmayan kimseler (olun). Kim Allah’a şirk koşarsa, o sanki gökyüzünden düşüp, kuşların kaptığı yahut rüzgârın kendisini uzak bir yere attığı kimseye benzer.');
INSERT INTO verses (sura, aya, text) VALUES (22, 32, 'Bu böyle. Her kim de Allah’ın şeairini/nişanelerini yüceltirse, şüphesiz ki bu kalplerin takvasından (Allah’a karşı gelmekten sakınmasından)dır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 33, 'Onlarda sizin için belirli bir süreye kadar faydalar vardır. Sonra onların varacakları yer Beyt-i Atik (Kâbe)dir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 34, 'Biz, kendilerine rızık olarak verdiğimiz kurbanlık hayvanlar üzerine Allah’ın adını ansınlar diye her ümmete kurban kesmeyi meşru kıldık. İlahınız bir tek ilahtır. O halde ona teslim olun. İtaatkâr ve alçak gönüllü olanları müjdele.');
INSERT INTO verses (sura, aya, text) VALUES (22, 35, 'Onlar, Allah anıldığı zaman kalpleri ürperen, başlarına gelen musibetlere sabreden, namazı dosdoğru kılan ve kendilerine rızık olarak verdiklerimizden Allah yolunda harcayan kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 36, 'Kurbanlık develeri, sizin için Allah’ın nişanelerinden kıldık. Sizin için onlarda hayır vardır. Onlar ayakları üzere iken kendilerine Allah’ın adını anın. Yanları üzerlerine düşüp canları çıkınca onlardan siz de yiyin; istemeyen fakire de, istemek zorunda kalan fakire de yedirin. Şükredesiniz diye onları böylece sizin hizmetinize verdik.');
INSERT INTO verses (sura, aya, text) VALUES (22, 37, 'Onların etleri de, kanları da Allah’a asla ulaşmaz. Fakat sizden ona takvâ ulaşır. Size hidayet ettiği için Allah''ı tekbir edin diye O, bunları sizin emrinize vermiştir. İhsan sahiplerine müjde ver.');
INSERT INTO verses (sura, aya, text) VALUES (22, 38, 'Hiç şüphesiz Allah, iman edenleri savunur. Gerçekten Allah, hain ve nankör olan kimseyi sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (22, 39, 'Kendilerine savaş açılan Müslümanlara, zulme uğramaları sebebiyle cihad için izin verildi. Şüphe yok ki Allah’ın onlara yardım etmeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (22, 40, 'Onlar sadece; “Rabbimiz Allah’tır” dedikleri için haksız yere yurtlarından çıkartılmışlardır. Eğer Allah’ın insanların bir kısmını, bir kısmıyla bertaraf etmesi olmasaydı manastırlar, kiliseler, havralar ve içinde Allah’ın isminin çokça anıldığı mescitler yıkılıp giderdi. Allah kendi (dini)ne yardım edene elbette yardım eder. Muhakkak Allah güçlüdür, Azizdir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 41, 'Onlar öyle kimselerdir ki, şâyet kendilerine yeryüzünde imkân ve iktidar versek; namazı dosdoğru kılar, zekâtı verir, iyiliği emreder ve kötülüğü yasaklarlar. Bütün işlerin âkıbeti Allah’a aittir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 42, 'Ey Muhammed! Eğer seni yalanlarlarsa bil ki, onlardan önce Nûh, Âd ve Semûd kavimleri de (peygamberlerini) yalanlamışlardı.');
INSERT INTO verses (sura, aya, text) VALUES (22, 43, 'İbrahim’in kavmi ile Lût’un kavmi ve Medyen halkı da (yalanlamışlardı).');
INSERT INTO verses (sura, aya, text) VALUES (22, 44, 'Medyen halkı da (Şuayb''ı yalanladı). Mûsâ da yalanlandı. Kâfirlere mühlet verdim, sonra da onları yakaladım. Benim cezalandırmam nasılmış?');
INSERT INTO verses (sura, aya, text) VALUES (22, 45, '(Ahalisi) zalim iken kendilerini helâk ettiğimiz bu yüzden çökmüş çatıları üzerine duvarları yıkılmış, kuyuları sahipsiz, yüksek köşkleri (ıssız) kalmış nice şehirler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 46, 'Acaba onlar kendileri ile akledecekleri kalplerinin, kendileri ile işitecekleri kulaklarının olması için yeryüzünde neden gezip dolaşmazlar? Çünkü gerçekte gözler değil, göğüslerdeki kalpler kör olur.');
INSERT INTO verses (sura, aya, text) VALUES (22, 47, 'Senden azabı çabucak getirmeni isterler. Allah sözünden asla caymaz. Gerçek şu ki, Rabbinin yanında bir gün, sayacağınız bin yıl gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 48, 'Zalim oldukları halde kendilerine mühlet verdiğim nice memleketler vardır. Sonra onları (azap ile) yakaladım, dönüş yalnız banadır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 49, 'De ki: “Ey insanlar! Ben sizin için ancak apaçık bir uyarıcıyım.''''');
INSERT INTO verses (sura, aya, text) VALUES (22, 50, 'Artık iman edip salih ameller işleyenler var ya; işte onlar için bir bağışlama, güzel bir nimet (Cennet) vardır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 51, 'Ayetlerimiz konusunda acze düşürücü çabalar harcayanlara gelince, işte onlar Cehennem ehlidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 52, 'Senden önce hiçbir peygamber göndermedik ki, o temenni ettiği (Kur''an okuduğu) zaman, Şeytan onun temennisine (okuyuşuna) bir vesvese atmış olmasın. Ama Allah, Şeytan''ın attığını iptal eder, sonra kendi ayetlerini sağlamlaştırıp pekiştirir. Allah her şeyi bilendir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 53, 'Allah, Şeytan''ın attığı o vesveseyi kalplerinde hastalık bulunan ve kalpleri kaskatı olan kimseler için bir fitne kılmıştır. Muhakkak zalimler uzak bir ayrılık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (22, 54, 'Bir de kendilerine ilim verilmiş olanlar onun, Rabbinden gelen hak olduğunu bilsinler, böylece ona iman etsinler ve sonuçta da kalpleri ona saygı duyup, boyun eğsin diye Allah böyle yapar. Hiç şüphe yok ki Allah, iman edenleri doğru yola iletir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 55, 'Kâfirler, kendilerine kıyamet ansızın gelinceye, yahut da onlara kısır bir günün azabı gelip çatıncaya dek o Kur’an’dan bir şüphe içinde kalırlar.');
INSERT INTO verses (sura, aya, text) VALUES (22, 56, 'İşte o gün mülk Allah’ındır. O, insanların arasında hükmünü verir. Artık iman edip salih ameller işlemiş olanlar Naîm Cennetleri’ndedirler.');
INSERT INTO verses (sura, aya, text) VALUES (22, 57, 'Kâfir olup ayetlerimizi yalanlayanlara gelince, onlar için alçaltıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 58, 'Allah yolunda hicret edip de sonra öldürülmüş veya ölmüş olanlara gelince, Allah onlara muhakkak güzel bir rızık verecektir. Şüphe yok ki Allah, rızık verenlerin en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 59, 'Elbette onları, hoşnut olacakları bir yere (Cennete) sokacaktır. Şüphesiz Allah hakkıyla bilendir, Halîm''dir. (Hemen cezalandırmaz, mühlet verir.)');
INSERT INTO verses (sura, aya, text) VALUES (22, 60, 'İşte böyle; kim kendisine yapılan bir eziyete o ölçüde karşılık verir, sonra yine kendisine zulmedilirse, elbette Allah ona yardım eder. Şüphesiz Allah; çok affedicidir, çok mağfiret edicidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 61, 'Bu (böyledir). Çünkü Allah geceyi gündüze katar, gündüzü de geceye katar. Şüphesiz Allah, her şeyi işitendir, her şeyi görendir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 62, 'İşte bu böyledir. Çünkü hak olan ancak Allah''tır. Ondan başka taptıkları ise bizatihi batıldır. Allah; üstündür/yüksektedir, büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (22, 63, 'Allah’ın gökten su indirmesiyle yeryüzünün yemyeşil olduğunu görmedin mi? Allah; Latif''tir, her şeyden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 64, 'Göklerdeki her şey, yerdeki her şey O’nundur. Şüphesiz Allah, hiç bir şeye ihtiyacı olmayandır, elbette övgüye lâyıktır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 65, 'Görmedin mi Allah, yerdeki her şeyi ve emri ile denizde yüzen gemileri sizin hizmetinize verdi. Göğü de kendi izni olmadıkça yer üzerine düşmemesi için tutar. Allah, insanlara karşı gerçekten çok şefkatli ve merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 66, 'O, size hayat veren, sonra sizi öldürecek, daha sonra da diriltecek olandır. Şüphesiz, insan çok nankördür.');
INSERT INTO verses (sura, aya, text) VALUES (22, 67, 'Her ümmete uygulamakta oldukları bir ibadet yolu belirledik. Öyleyse, bu iş/din hususunda seninle tartışmasınlar. Rabbine davet et. Hiç kuşkusuz sen, dosdoğru bir yol üzerindesin.');
INSERT INTO verses (sura, aya, text) VALUES (22, 68, 'Eğer seninle mücadele ederlerse, de ki: “Allah, yapmakta olduğunuzu daha iyi bilmektedir.”');
INSERT INTO verses (sura, aya, text) VALUES (22, 69, 'Hakkında ayrılığa düşüp durduğunuz şeyler konusunda, kıyamet günü Allah aranızda hüküm verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 70, 'Bilmez misin ki Allah, gökte ve yerde olan her şeyi bilir. Şüphesiz ki bütün bunlar bir kitaptadır. Gerçekten bu Allah’a çok kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 71, 'Onlar; Allah’ı bırakıp, hakkında Allah’ın hiçbir delil indirmediği, kendilerinin de hakkında hiçbir bilgilerinin bulunmadığı şeylere ibadet ederler. Zalimlerin hiçbir yardımcısı yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (22, 72, 'Onlara apaçık ayetlerimiz okunduğu zaman, o kâfirlerin yüzlerinden inkârı anlarsın. Neredeyse, kendilerine ayetlerimizi okuyanlara saldıracaklar. De ki: Size bundan daha kötüsünü haber vereyim mi? Ateş! Allah onu kâfirlere vadetti. O, ne kötü sondur.');
INSERT INTO verses (sura, aya, text) VALUES (22, 73, '-Ey insanlar!- Bir örnek veriliyor, onu iyice dinleyin! Sizin Allah’ın dışında dua ettikleriniz (ilahlar) bir araya gelseler bile bir sinek dahi yaratamazlar. Sinek onlardan bir şey kapsa, onu ondan kurtaramazlar. İsteyen de, istenen de zayıftır.');
INSERT INTO verses (sura, aya, text) VALUES (22, 74, 'Allah’ın kadrini gereği gibi bilemediler. Şüphesiz Allah kuvvetlidir, mutlak güç sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 75, 'Allah, meleklerden de rasûller seçer, insanlardan da. Şüphesiz Allah, hakkıyla işitendir, hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (22, 76, 'Onların önceden yaptıklarını da, yapacaklarını da bilir. Bütün işler ancak Allah’a döndürülür.');
INSERT INTO verses (sura, aya, text) VALUES (22, 77, 'Ey iman edenler! Rüku edin, secde edin, Rabbinize ibadet edin, hayır işleyin ki kurtuluşa eresiniz.');
INSERT INTO verses (sura, aya, text) VALUES (22, 78, 'Allah uğrunda hakkıyla cihad edin. O, sizi seçti, dinde üzerinize bir zorluk yüklemedi. (Bu) Babanız İbrahim’in dinidir. Allah, bundan önce ve bunda (Kur’an’da) size "Müslüman" ismini vermiştir. (Hesap günü) Rasûl size şahit olsun, siz de insanlığa şahit olun diye. Öyleyse namazı ikame edin, zekâtı verin, Allah’a sımsıkı bağlanın. O, ne güzel mevlâ ve ne güzel yardımcıdır!');
INSERT INTO verses (sura, aya, text) VALUES (23, 1, 'Gerçekten Mü''minler kurtuluşa ermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 2, 'Onlar namazlarında huşû içinde olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 3, 'Onlar, boş ve yararsız şeylerden yüz çevirirler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 4, 'Onlar zekâtı verirler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 5, 'Onlar, ırzlarını/iffetlerini korurlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 6, 'Ancak kendi eşleri ve ellerinin altındaki (cariyeleri) hariç. Şüphesiz onlar (bunlarla ilişkilerinden dolayı) kınanmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 7, 'Artık her kim bundan başkasını isterse işte onlar sınırı aşan kimseler olurlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 8, 'Onlar, emanetlerine ve verdikleri sözlere riâyet ederler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 9, 'Onlar, namazlarını eda ederler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 10, 'İşte bunlar varis olanların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 11, 'Onlar, Firdevs’e varis olacaklardır ve onlar orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 12, 'Andolsun biz insanı, (süzülmüş) bir çamurdan yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (23, 13, 'Sonra onu bir su damlası/nutfe olarak, sağlam bir yere (rahme) yerleştirdik.');
INSERT INTO verses (sura, aya, text) VALUES (23, 14, 'Sonra nutfeyi/spermi, alaka/embriyo haline getirdik. Embriyoyu bir çiğnem et parçası yaptık. Et parçasından kemik yarattık. Kemiğe et giydirdik. Sonra onu (ruh vererek) bambaşka bir varlık olarak yarattık. Yaratanların en güzeli olan Allah pek yücedir!');
INSERT INTO verses (sura, aya, text) VALUES (23, 15, 'Sonra siz, bunun arkasından elbette öleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 16, 'Sonra şüphesiz sizler, kıyamet günü yeniden diriltileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 17, 'Andolsun, biz sizin üzerinizde yedi yol yarattık. Biz yarattıklarımızdan gâfil değiliz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 18, 'Biz, gökten belli bir ölçüde su indirdik de (faydalanmanız için) onu yeryüzünde tuttuk. Bizim onu tamamen gidermeye de muhakkak gücümüz yeter.');
INSERT INTO verses (sura, aya, text) VALUES (23, 19, 'O suyla, sizin için hurma ve üzüm bağları yetiştirdik ki, oralarda sizin için birçok meyveler vardır. Siz de onlardan yersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 20, 'Tûri Sînâ''da da yetişen bir ağaç daha meydana getirdik ki, bu ağaç hem yağ hem de yiyenlerin ekmeğine katık edecekleri (zeytin) verir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 21, 'Şüphesiz hayvanlarda da sizin için ibret vardır. Onların karınlarında olanlardan size içiririz. Onlarda sizin için çok yararlar vardır ve onlardan yersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 22, 'Bir de hem onların üzerinde, hem gemilerin üzerinde taşınıyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 23, 'Şüphesiz biz Nûh’u kavmine peygamber olarak gönderdik. Kavmine dedi ki: “Ey kavmim! Allah’a ibadet edin. Sizin O''ndan başka bir ilahınız yoktur. Hiç sakınmaz mısınız?"');
INSERT INTO verses (sura, aya, text) VALUES (23, 24, 'Kavminden ileri gelen kâfirler: "Bu, sizin gibi bir insandan başka bir şey değildir. Sizden üstün olmak istiyor. Eğer Allah dileseydi melekleri gönderirdi. Biz, daha önceki atalarımızdan da bunu duymadık." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 25, 'O ancak, cinlenmiş (kendisine delilik isabet eden) bir adam, öyleyse bir müddet onu (bırakıp) bekleyin.');
INSERT INTO verses (sura, aya, text) VALUES (23, 26, 'Nûh: "Rabbim! Beni yalanlamalarına karşılık bana yardım et." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (23, 27, 'Bunun üzerine Nûh’a: “Gözlerimizin önünde, vahyimize göre gemiyi yap!” diye vahyettik. Bizim emrimiz gelip de tandır kaynamaya başlayınca, (sular coşup taştığında Nûh’a) dedik ki: “Her cins canlıdan (erkekli dişili) birer çift, bir de aleyhine hüküm verilmiş olanın dışında kalan aileni gemiye al ve zulmeden kimseler hakkında bana hiç yalvarma! Şüphesiz onlar suda boğulacaklardır.”');
INSERT INTO verses (sura, aya, text) VALUES (23, 28, 'Sen ve beraberindekiler gemiye yerleşince: "Bizi zalim kavimden kurtaran Allah’a hamdolsun." de!');
INSERT INTO verses (sura, aya, text) VALUES (23, 29, 'Ve yine şöyle de: "Rabbim! Beni mübarek bir yere indir. İndirenlerin en hayırlısı sensin!"');
INSERT INTO verses (sura, aya, text) VALUES (23, 30, 'Şüphesiz bunda (Nûh ve kavminin başından geçenlerde) birtakım ibretler vardır. Hakikaten biz (kullarımızı böyle) sınarız.');
INSERT INTO verses (sura, aya, text) VALUES (23, 31, 'Sonra onların ardından bir başka nesil meydana getirdik.');
INSERT INTO verses (sura, aya, text) VALUES (23, 32, 'Onlara kendilerinden; “Allah’a kulluk edin, sizin O’ndan başka hiçbir ilahınız yoktur. Hâlâ O’na karşı gelmekten sakınmaz mısınız?” diye öğüt veren bir peygamber gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (23, 33, 'O peygamberin kavminden, Allah’a kâfir olan, ahireti yalanlayan ve bizim dünya hayatında kendilerine bol bol nimet verdiğimiz ileri gelenleri şöyle dediler: “O da ancak sizin gibi bir insandır. Sizin yediğiniz şeylerden yiyor, içtiğiniz şeylerden içiyor.”');
INSERT INTO verses (sura, aya, text) VALUES (23, 34, 'Eğer, sizin gibi bir insana itaat ederseniz; işte o zaman hüsrana uğrarsınız.');
INSERT INTO verses (sura, aya, text) VALUES (23, 35, 'Siz ölüp, toprak ve kemik olduğunuz zaman tekrar (kabirlerinizden) çıkarılacağınızı mı vadediyor?');
INSERT INTO verses (sura, aya, text) VALUES (23, 36, '“Hâlbuki bu size vaadolunan (öldükten sonra tekrar dirilme olayı gerçek olmaktan) ne kadar da uzak!”');
INSERT INTO verses (sura, aya, text) VALUES (23, 37, 'Onlar; "Hayatımız, ancak dünya hayatıdır. Ölürüz ve yaşarız. Bizler tekrar diriltilecek değiliz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 38, 'Bu adam, sadece Allah hakkında yalan uyduran bir kimsedir; biz ona iman etmiyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 39, 'O peygamber: "Rabbim, beni yalanlamalarına karşılık bana yardım et!" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (23, 40, 'Allah şöyle buyurdu: "Pek yakında onlar mutlaka pişman olacaklar!"');
INSERT INTO verses (sura, aya, text) VALUES (23, 41, 'Derken onları, gerçekleşmesi hak/kaçınılmaz olan bir çığlık yakaladı ve onları bir (sel) süprüntüsü haline getirdik. Uzak olsun öyle zâlim bir kavim!');
INSERT INTO verses (sura, aya, text) VALUES (23, 42, 'Sonra onların ardından başka nesiller meydana getirdik.');
INSERT INTO verses (sura, aya, text) VALUES (23, 43, 'Hiçbir ümmet, ecelinin önüne geçemez ve onu geciktiremez.');
INSERT INTO verses (sura, aya, text) VALUES (23, 44, 'Sonra birbiri ardınca peygamberlerimizi gönderdik. Her ümmete peygamberi geldikçe onu yalanladılar. (Biz de) onları birbiri ardından helâk edip, (ibretlik) konuşulan (olaylar) haline getirdik. Yok olsun iman etmeyen böyle bir toplum!');
INSERT INTO verses (sura, aya, text) VALUES (23, 45, 'Sonra Mûsâ''yı ve kardeşi Hârûn''u ayetlerimizle ve apaçık delillerle gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (23, 46, 'Firavun’a ve ileri gelenlerine. Ama onlar büyüklük tasladılar. Zaten onlar kendilerini üstün sayan bir topluluktu.');
INSERT INTO verses (sura, aya, text) VALUES (23, 47, 'Bu yüzden: "Kavimleri bize kölelik edip dururken, bizim gibi iki insana mı iman edeceğiz?" demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (23, 48, 'Böylece o ikisini yalanladılar ve helâk edilenlerden oldular.');
INSERT INTO verses (sura, aya, text) VALUES (23, 49, 'Andolsun biz Mûsâ''ya, belki onlar hidayeti bulurlar diye kitabı verdik.');
INSERT INTO verses (sura, aya, text) VALUES (23, 50, 'Andolsun ki biz Meryem oğlunu da, anasını da birer ayet kıldık ve onları yüksek ve akarsuyu olan rahat bir yerde barındırdık.');
INSERT INTO verses (sura, aya, text) VALUES (23, 51, 'Ey rasûller! Temiz şeylerden yiyin ve salih ameller işleyin. Çünkü ben yaptığınız bütün amelleri çok iyi bilirim.');
INSERT INTO verses (sura, aya, text) VALUES (23, 52, 'Ve gerçekten sizin bu ümmetiniz tek bir ümmettir. Ben de sizin Rabbinizim. O halde yalnız benden korkun.');
INSERT INTO verses (sura, aya, text) VALUES (23, 53, 'Ne var ki (insanlar) işlerini (dinlerini) aralarında bölük pörçük etmişlerdir. Bu sebeple her grup kendi yanındakiyle sevinip böbürlenmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 54, 'Bir süreye kadar onları kendi sapıklıklarıyla başbaşa bırak.');
INSERT INTO verses (sura, aya, text) VALUES (23, 55, 'Zannediyorlar mı ki kendilerine mal ve oğullar sunduk diye?');
INSERT INTO verses (sura, aya, text) VALUES (23, 56, 'İyiliklerinde acele ediyoruz. Asla! Fakat onlar anlamıyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 57, 'Şüphesiz ki Rablerinin korkusundan titreyenler,');
INSERT INTO verses (sura, aya, text) VALUES (23, 58, 'Rablerinin ayetlerine iman edenler,');
INSERT INTO verses (sura, aya, text) VALUES (23, 59, 'Ve Rablerine şirk koşmayanlar,');
INSERT INTO verses (sura, aya, text) VALUES (23, 60, 'Rabblerine dönecekleri için verdiklerini kalpleri ürpererek verenler,');
INSERT INTO verses (sura, aya, text) VALUES (23, 61, 'İşte, iyilik hususunda yarışanlar ve (iyilikte) öne geçenler bunlardır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 62, 'Biz, hiç kimseyi gücünün yettiğinden başkası ile yükümlü kılmayız. Nezdimizde hakkı söyleyen bir kitap vardır ve onlar haksızlığa uğratılmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 63, 'Hayır, onların (o inkârcıların) kalpleri bu hususta cehalet içindedir. Ayrıca onların bundan (bu şirk ve inkârcılıklarından) öte birtakım (kötü) işleri vardır ki, onlar bu işleri yapar dururlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 64, 'Nihayet refah ve bolluk içinde olanlarını azapla kıskıvrak yakaladığımız zaman, bakmışsın ki hemen feryadı basarlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 65, 'Bugün feryat etmeyin, çünkü tarafımızdan size yardım olunmaz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 66, 'Ayetlerim size okunuyordu da topuklarınızın üstünde gerisin geri dönüyordunuz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 67, 'Bununla büyüklük taslar, geceleyin toplanıp hezeyanlar savururdunuz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 68, 'Onlar bu sözü (Kur''an''ı) hiç düşünmediler mi? Yoksa kendilerine, daha önce geçmişteki atalarına gelmeyen bir şey mi geldi?');
INSERT INTO verses (sura, aya, text) VALUES (23, 69, 'Yahut onlar rasûllerini tanımıyorlardı da bunun için mi şimdi onu inkâr ediyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (23, 70, 'Yahut onun cinlenip, delilik isabet ettiğini mi söylüyorlar? Bilakis o kendilerine hakkı getirmiştir. Hâlbuki onların çoğunluğu haktan hoşlanmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 71, 'Eğer hak, onların hevâ ve heveslerine tâbi olsaydı, gökler, yer ve içindeki herkes, mutlaka bozguna uğrardı. Oysa biz onlara, şan ve şereflerini ihtiva eden Kur''an''ı getirdik. Fakat onlar, bundan yüz çevirmektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 72, 'Yoksa sen onlardan bir karşılık mı istiyorsun? Rabbinin vereceği daha hayırlıdır. O, rızık verenlerin en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 73, 'Sen onları şüphesiz ki dosdoğru yola davet edersin.');
INSERT INTO verses (sura, aya, text) VALUES (23, 74, 'Muhakkak ki âhirete iman etmeyenler doğru yoldan sapanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 75, 'Eğer onlara rahmet edip, başlarındaki sıkıntıyı gidermiş olsaydık bile yine de onlar; azgınlıkları içinde bocalayıp dururlardı.');
INSERT INTO verses (sura, aya, text) VALUES (23, 76, 'Andolsun ki onları azap ile aldığımız halde yine de Rablerine itaatle boyun eğmediler. Yalvarıp, yakarmadılar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 77, 'Nihayet üzerlerine şiddetli bir azap kapısı açtığımızda o zaman azabın içinde şaşkın ve ümitsiz kalıverirler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 78, 'Sizin için kulaklar, gözler ve kalpler var eden O’dur. Ne kadar az şükrediyorsunuz!');
INSERT INTO verses (sura, aya, text) VALUES (23, 79, 'Sizi yeryüzünde yaratıp yayan da O''dur. Ve yine O''nun huzurunda toplanacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (23, 80, 'Dirilten de öldüren de O’dur. Gece ve gündüzün art arda gelmesi de O’na aittir. Hâlâ akletmiyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (23, 81, 'Aksine bunlar da öncekilerin dedikleri gibi dediler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 82, '"Ölüp, toprak ve kemik haline geldiğimiz zaman, biz yeniden mi diriltileceğiz?" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 83, 'Bu, bize ve atalarımıza daha önce de vadedilmişti. Bu, öncekilerin masallarından başka bir şey değildir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 84, 'De ki: "Eğer biliyorsanız (söyleyin bakalım), yeryüzü ve onda bulunanlar kime aittir?"');
INSERT INTO verses (sura, aya, text) VALUES (23, 85, '“Allah’ındır.” diyecekler. “Öyle ise siz hiç düşünüp öğüt almaz mısınız?” de.');
INSERT INTO verses (sura, aya, text) VALUES (23, 86, '"Yedi göğün Rabbi ve yüce arşın Rabbi kimdir?" de!');
INSERT INTO verses (sura, aya, text) VALUES (23, 87, '"Allah’ındır." diyecekler. (Onlara:) Hâlâ düşünüp öğüt almaz mısınız? de!');
INSERT INTO verses (sura, aya, text) VALUES (23, 88, 'De ki: "Eğer biliyorsanız (söyleyin): Her şeyin hükümranlığı elinde olan, koruyup kollayan ama kendisi korunmaya (muhtaç olmayan) kimdir?"');
INSERT INTO verses (sura, aya, text) VALUES (23, 89, '"Allah’ındır." diyecekler. “Öyle ise nasıl aldanıyorsunuz?” de.');
INSERT INTO verses (sura, aya, text) VALUES (23, 90, 'Doğrusu biz onlara hakkı (gerçeği) getirdik. Onlar ise hakikaten yalancılardır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 91, 'Allah, bir çocuk edinmemiştir ve O''nunla beraber hiçbir ilah yoktur. Eğer öyle olsaydı, her ilah kendi yarattığını alır, elbette onlardan biri diğerine galebe çalardı. Allah onların niteleye geldiklerinden münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 92, 'Allah, gizliyi ve açığı bilendir. O, (müşriklerin) ortak koştukları şeylerden yüksektir, çok yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 93, 'De ki: “Rabbim! Eğer onların tehdit olundukları şeyi bana göstereceksen;"');
INSERT INTO verses (sura, aya, text) VALUES (23, 94, '“Rabbim! O halde beni o zalimler topluluğu arasında kılma!”');
INSERT INTO verses (sura, aya, text) VALUES (23, 95, 'Bizim onlara yönelttiğimiz tehditleri sana göstermeye elbette gücümüz yeter.');
INSERT INTO verses (sura, aya, text) VALUES (23, 96, 'Sen, kötülüğü en güzel bir tutumla sav. Biz onların yakıştırmakta oldukları şeyi çok iyi bilmekteyiz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 97, 'Ve de ki: "Rabbim! Şeytanların vesveselerinden sana sığınırım!');
INSERT INTO verses (sura, aya, text) VALUES (23, 98, '“Rabbim yanımda hazır olmalarından da sana sığınırım.”');
INSERT INTO verses (sura, aya, text) VALUES (23, 99, 'Nihayet onlardan (müşriklerden) birine ölüm gelip çattığında şöyle der: "Rabbim! Beni geri gönder."');
INSERT INTO verses (sura, aya, text) VALUES (23, 100, '“Belki geride bıraktıklarımla salih amel işlerim.” Asla, bu onun söylemiş olduğu bir sözden ibarettir. Onların önlerinde de diriltilecekleri güne kadar bir berzah vardır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 101, 'Sûr’a üflendiği zaman, işte o gün aralarında soy bağı kalmaz, birbirlerine bir şey de soramazlar.');
INSERT INTO verses (sura, aya, text) VALUES (23, 102, 'Artık kimin tartıları ağır gelirse, işte onlar kurtuluşa erenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 103, 'Kimlerin de tartıları hafif gelirse, artık bunlar da kendilerine yazık etmişlerdir. (Çünkü onlar) ebedî Cehennem''dedirler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 104, 'Ateş onların yüzlerini bürüyüp, yakar ve (dudakları da yanar da) dişleri sırıtıp öylece kalır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 105, '"Ayetlerim size okunuyordu da siz onları yalanlıyordunuz, değil mi?"');
INSERT INTO verses (sura, aya, text) VALUES (23, 106, 'Onlar şöyle derler: "Rabbimiz! Azgınlığımız bizi yenmişti ve sapık bir kavim olmuştuk."');
INSERT INTO verses (sura, aya, text) VALUES (23, 107, 'Rabbimiz! "Bizi ateşten çıkar. Eğer (sapıklığa) tekrar dönersek, biz gerçekten kendimize zulmetmiş oluruz." derler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 108, '(Allah) "Aşağılık içinde kalın orada, artık benimle konuşmayın!" der.');
INSERT INTO verses (sura, aya, text) VALUES (23, 109, 'Gerçek şu ki kullarımdan: “Rabbimiz, iman ettik, bize mağfiret ve rahmet buyur. Sen rahmet edenlerin hayırlısısın, diyen bir topluluk vardı.');
INSERT INTO verses (sura, aya, text) VALUES (23, 110, 'Siz ise onları alaya almıştınız. O kadar ki, onlar size beni anmayı unutturdu. Onlara hep gülüyordunuz.');
INSERT INTO verses (sura, aya, text) VALUES (23, 111, 'Bugün sabrettikleri için onları ödüllendirdim. İşte, asıl kurtuluşa ermiş olanlar onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (23, 112, '“Siz yeryüzünde kaç yıl kaldınız” diyecek.');
INSERT INTO verses (sura, aya, text) VALUES (23, 113, 'Onlar: “Bir gün yahut bir günün bir bölümü kadar eğlendik. Haydi sayanlara sor” diyecekler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 114, 'Buyurdu ki: “Siz ancak az bir süre eğlendiniz. Eğer gerçekten bilmiş olsaydınız.');
INSERT INTO verses (sura, aya, text) VALUES (23, 115, 'Sizi, boşuna yarattığımızı ve bize döndürülmeyeceğinizi mi sandınız?');
INSERT INTO verses (sura, aya, text) VALUES (23, 116, 'Gerçek hükümdar olan Allah yüksektedir, yücedir. O’ndan başka hiç (hak) ilah yoktur. O, şerefli ve yüce Arş’ın Rabbidir.');
INSERT INTO verses (sura, aya, text) VALUES (23, 117, 'Kim hakkında hiçbir delili bulunmaksızın Allah ile birlikte başka bir ilaha ibadet ederse onun hesabı ancak Rabbinin katındadır. Kâfirler –hiç şüphesiz- kurtuluşa eremezler.');
INSERT INTO verses (sura, aya, text) VALUES (23, 118, 'De ki: “Rabbim! Bağışla, merhamet et. Çünkü sen merhamet edenlerin en hayırlısısın!”');
INSERT INTO verses (sura, aya, text) VALUES (24, 1, 'Bu, indirdiğimiz ve (hükümlerini) farz kıldığımız bir sûredir. Düşünüp öğüt alasınız diye, bu sûre içinde apaçık ayetler indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (24, 2, 'Zina eden kadın ve zina eden erkekten her birine yüz değnek vurun. Allah''a ve ahiret gününe iman ediyorsanız, Allah''ın dini hususunda onlara karşı acıma duygusu sizi (uygulayacağınız cezadan) engellemesin. Müminlerden bir grup da onlara uygulanan cezaya şahit olsun.');
INSERT INTO verses (sura, aya, text) VALUES (24, 3, 'Zina eden erkek, ancak zina eden veya Allah’a ortak koşan bir kadınla evlenir. Zina eden bir kadınla da ancak zina eden veya Allah’a ortak koşan bir erkek evlenir. Bu, Müminlere haram kılınmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 4, 'İffetli kadınlara iftira atan, sonra da dört şahit getiremeyen kimselere seksen değnek vurun ve bir daha onların şahitliklerini ebedî olarak kabul etmeyin. İşte onlar fasıkların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 5, 'Ancak bundan sonra tevbe edenler ve (amellerini) ıslah edenler müstesnadır. Allah çok bağışlayıcı ve merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 6, 'Eşlerine zina isnadında bulunup da kendilerinden başka şahitleri olmayanlara gelince; her birinin şahitliği, Allah adına dört defa kendisinin hiç şüphesiz doğru söyleyenlerden olduğuna dair şahitlik etmesidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 7, 'Beşincisi, eğer yalan söyleyenlerden ise Allah’ın lanetinin kendi üzerine olmasını dilemesidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 8, 'Kadının; kocasının yalan söylediğine dair dört defa Allah’ı şahit tutması kadından cezayı kaldırır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 9, 'Beşincisinde; eğer o (kocası) doğru söyleyenlerdense Allah''ın lanetinin muhakkak kendi üzerine olmasını (diler).');
INSERT INTO verses (sura, aya, text) VALUES (24, 10, 'Allah’ın size lütfu ve merhameti olmasaydı ve Allah tevbeleri kabul eden, hüküm ve hikmet sahibi olmasaydı hâliniz nice olurdu?');
INSERT INTO verses (sura, aya, text) VALUES (24, 11, 'O ağır iftirayı uyduranlar, sizin içinizden bir güruhtur. Bu iftirayı kendiniz için kötü bir şey sanmayın. Aksine o sizin için bir hayırdır. Onlardan her biri için işledikleri günahın cezası vardır. İçlerinden (elebaşılık ederek) o günahın büyüğünü üstlenen için ise ağır bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 12, 'Onu işittiğiniz zaman, Mümin erkek ve Mümin kadınların kendi vicdanlarında hüsnü zanda bulunup; “Bu, apaçık bir iftiradır.” demeleri gerekmez miydi?');
INSERT INTO verses (sura, aya, text) VALUES (24, 13, 'Onların (iftiracıların) da bu konuda dört şahit getirmeleri gerekmez miydi? Mademki şahitler getiremediler, öyle ise onlar Allah nezdinde yalancıların ta kendileridirler.');
INSERT INTO verses (sura, aya, text) VALUES (24, 14, 'Eğer size dünyada ve ahirette Allah''ın lütuf ve merhameti olmasaydı, içine daldığınız bu iftiradan dolayı size mutlaka büyük bir azap isabet ederdi.');
INSERT INTO verses (sura, aya, text) VALUES (24, 15, 'O zaman siz o sözü birbirinizin dilinden alıp duruyordunuz. Hakkında hiçbir bilginizin olmadığı bir şeyi ağızlarınızla söylüyordunuz. Bunu basit bir şey sanıyordunuz. Hâlbuki o Allah katında çok büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (24, 16, 'Bu iftirayı işittiğiniz vakit; “Bu konuda konuşmak bize yakışmaz. Seni tenzih ederiz. Bu büyük bir iftiradır.” demeniz gerekmez miydi?');
INSERT INTO verses (sura, aya, text) VALUES (24, 17, 'Eğer Mümin iseniz, böyle bir şeye bir daha asla dönmemeniz için Allah size öğüt veriyor.');
INSERT INTO verses (sura, aya, text) VALUES (24, 18, 'Ve Allah size ayetleri böyle açıklıyor. Allah Alîm''dir (herşeyi hakkıyla bilendir), Hakîm''dir. (Çok hikmet sahibidir.)');
INSERT INTO verses (sura, aya, text) VALUES (24, 19, 'İman edenler arasında fuhşun (kötülüklerin) yayılmasını arzu edenlere, dünya ve ahirette acı bir azap vardır. Allah bilir, siz bilmezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (24, 20, 'Eğer üzerinizde Allah''ın lütuf ve merhameti olmasaydı ve Allah çok şefkatli ve merhametli olmasaydı (haliniz nice olurdu)!');
INSERT INTO verses (sura, aya, text) VALUES (24, 21, 'Ey iman edenler! Şeytanın adımlarını izlemeyin. Kim şeytanın adımlarını izlerse şunu bilsin ki, o çirkin işleri ve münkeri emreder. Eğer Allah’ın üzerinizde lütuf ve rahmeti olmasaydı, sizden hiçbir kimse ebediyen temize çıkamazdı, fakat Allah dilediğini temize çıkarır. Allah her şeyi işitendir, çok iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 22, 'İçinizden faziletli ve servet sahibi kimseler akrabaya, yoksullara, Allah yolunda göç edenlere (mallarından) vermeyeceklerine dair yemin etmesinler, bağışlasınlar, feragat göstersinler. Allah’ın sizi bağışlamasını arzulamaz mısınız? Allah çok bağışlayandır, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 23, 'Namuslu, (kötülükten) habersiz Mümin kadınlara iftira atanlar, dünya ve ahirette lanetlenmişlerdir. Onlara büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 24, 'O gün, (onların) dilleri, elleri ve ayakları yapmış oldukları şeylere, aleyhlerinde şahitlik eder.');
INSERT INTO verses (sura, aya, text) VALUES (24, 25, 'O günde, Allah onlara hak ettikleri cezalarını bütünüyle verecektir ve Allah’ın apaçık hakkın ta kendisi olduğunu da bileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 26, 'Kötü kadınlar kötü erkeklere, kötü erkekler kötü kadınlara, temiz kadınlar temiz erkeklere, temiz erkekler de temiz kadınlara yaraşır. Bunlar (temiz kadınlar ve erkekler), (iftiracıların) söylediklerinden çok uzaktırlar ve onlar için bir bağışlanma ve güzel bir rızık vardır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 27, 'Ey iman edenler! Kendi evlerinizden başka evlere izin almadan ve ev halkına selâm vermeden girmeyin. Eğer düşünecek olursanız, bu sizin için daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 28, 'Eğer evde kimseyi bulamazsanız, size izin verilinceye kadar oraya girmeyin. Eğer size; “Geri dönün!” denirse, hemen dönün. Çünkü bu, sizin için daha nezih bir davranıştır. Allah, yaptıklarınızı hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 29, 'İçinde kendinize ait eşyanın bulunduğu oturulmayan evlere girmenizde herhangi bir sakınca yoktur. Allah; açığa vurduklarınızı da, gizlediklerinizi de bilir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 30, 'Mümin erkeklere söyle, gözlerini haramdan sakınsınlar, ırzlarını korusunlar. Bu davranış onlar için daha nezihtir. Şüphe yok ki, Allah onların yaptıklarından hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 31, 'Mümin kadınlara da söyle, gözlerini haramdan sakınsınlar, ırzlarını korusunlar. Açıkta olup, gözüken kısmı hariç ziynetlerini göstermesinler. Başörtüleri ile yakalarının (boyun, göğüs) üzerini de kapatsınlar. Süslerini; kocaları, babaları, kocalarının babaları, oğulları, kocalarının oğulları, kendi kardeşleri, kardeşlerinin oğulları, kız kardeşlerinin oğulları, kendi (gibi iman etmiş) kadınlar, sahip oldukları köleler, kadınlara ihtiyacı kalmamış hizmetçiler, kadınların mahrem yerlerini henüz bilmeyen çocuklardan başkasına göstermesinler. Gizledikleri süslerinin bilinmesi için ayaklarını yere vurmasınlar. Ey Müminler! Kurtuluşa ermek için hep birden Allah’a tevbe edin!');
INSERT INTO verses (sura, aya, text) VALUES (24, 32, 'İçinizden bekârları, köle ve cariyelerinizden salih olanları evlendirin. Eğer fakir iseler, Allah onları lütfu ile zenginleştirir. Allah, (hayrı, ihsanı) geniş/boldur, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 33, 'Evlenmeye güçleri yetmeyenler de, Allah kendilerini lütfuyla zengin edinceye kadar iffetlerini korusunlar. Sahip olduğunuz kölelerden “mükatebe” yapmak isteyenlere gelince, eğer onlarda bir hayır görürseniz onlarla mükatebe yapın. Allah’ın size verdiği maldan onlara verin. Dünya hayatının geçici menfaatlerini elde etmek için iffetli olmak isteyen cariyelerinizi fuhşa zorlamayın. Her kim onları zorlarsa; şüphesiz Allah, onların zorlanmalarından sonra onlara karşı çok bağışlayıcı, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 34, 'Andolsun ki biz size açıklayıcı ayetler, sizden önce geçmiş olanlardan misaller ve takva sahiplerine de bir öğüt indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (24, 35, 'Allah, göklerin ve yerin nurudur. O''nun nûrunun misali, içinde kandil bulunan bir kandillik gibidir. O kandil, kristal bir fanus içindedir. O, doğuya da batıya da ait olmayan mübarek bir zeytin ağacından tutuşturulan, parıltısı inciyi andıran bir yıldız gibidir. Onun yağı, neredeyse, kendisine ateş değmese dahi ışık verir. (Bu,) nûr üstüne nûrdur. Allah dilediği kimseyi nûruna eriştirir. Allah insanlara (işte böyle) misaller getirir. Allah her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 36, '(Bu nur) Allah''ın, yükseltilmesine ve içlerinde adının zikredilmesine izin verdiği evlerdedir. Oralarda sabah akşam O''nu tesbih ederler.');
INSERT INTO verses (sura, aya, text) VALUES (24, 37, 'Kendilerini ticaretin de, alışverişin de Allah’ı zikretmekten, namazdan ve zekâtı vermekten alıkoymadığı erlerdir. Onlar, kalplerin ve gözlerin ters döneceği bir günden korkarlar.');
INSERT INTO verses (sura, aya, text) VALUES (24, 38, '(Bütün bunlar) Allah''ın, onları yaptıklarına karşılık en iyi şekilde mükâfatlandırması ve lütfundan onlara daha da arttırması içindir. Allah, dilediklerine hesapsız rızık verir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 39, 'Kâfir olanların amelleri ise susuz kimselerin su sandığı dümdüz çöldeki bir serap gibidir. Nihayet ona yaklaşınca onun bir şey olmadığını görür. Ancak yanına geldiğinde hiçbir şey bulamaz ve yanında Allah''ı bulur. O da, kendisinin hesabını tam görür. Allah hesabı çabuk görendir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 40, 'Yahut derin bir denizdeki karanlıklar gibidir. Onu bir dalga örter, onu da üstünden (başka) bir dalga kaplar. Onların üzerinde ise bulutlar vardır. Birbiri üstünde karanlıklar. Elini çıkarsa neredeyse onu dahi göremeyecektir. Allah kime nur vermemişse onun nuru olmaz.');
INSERT INTO verses (sura, aya, text) VALUES (24, 41, 'Göklerde ve yerde bulunanlarla dizi dizi kuşların Allah''ı tesbih ettiklerini görmez misin? Her biri kendi duasını ve tesbihini (öğrenmiş) bilmiştir. Allah, onların yapmakta olduklarını hakkıyla bilir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 42, 'Göklerin ve yerin mülkü Allah''ındır, dönüş de ancak O''nadır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 43, 'Görmüyor musun ki Allah bulutları sürüyor, sonra onları bir araya getirip üst üste yığıyor? İşte o zaman aralarından yağmurun çıktığını görürsün. Gökten, içinde dolu bulunan dağlar gibi bulutlar indirir de, bu doluyu dilediğine isabet ettirir ve dilediğinden de uzak tutar. Şimşeğin parıltısı ise neredeyse gözleri alır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 44, 'Allah, gece ve gündüzü çevirip birbirinin ardından getirir. Doğrusu basiret sahibi olanlar için bunda ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 45, 'Allah, her canlıyı sudan (nutfeden) yarattı. İşte bunlardan kimi karnı üstünde sürünür, kimi iki ayağı üstünde yürür, kimi dört ayağı üstünde yürür. Allah dilediğini yaratır. Şüphesiz Allah, her şeye kadirdir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 46, 'Andolsun, biz apaçık ayetler indirdik. Allah, dilediği kimseyi dosdoğru yola hidayet eder (yöneltir).');
INSERT INTO verses (sura, aya, text) VALUES (24, 47, '(Münafıklar:) "Allah’a ve Rasûlüne iman ettik, itaat ettik." diyorlar. Sonra içlerinden bir grup bundan sonra yüz çeviriyor. Bunlar, Mümin değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 48, 'Aralarında hüküm vermesi için Allah’a ve Rasûlüne çağrıldıkları zaman, onlardan bir grup hemen yüz çevirirler.');
INSERT INTO verses (sura, aya, text) VALUES (24, 49, 'Eğer hak kendilerinin ise ona sürat ve itaatle gelirler.');
INSERT INTO verses (sura, aya, text) VALUES (24, 50, 'Acaba kalplerinde hastalık mı vardır bunların, yoksa şüpheye mi düştüler yahut Allah ve Rasulü kendilerine haksızlık eder diye mi korkarlar? Hayır, onlar zulmedenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 51, 'Aralarında hüküm verilmek üzere Allah’a ve Rasûlüne çağrılan Müminlerin sözü sadece; “İşittik ve itaat ettik”dir. İşte asıl bunlar kurtuluşa erenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 52, 'Kim Allah’a ve Rasûlüne itaat eder, Allah''tan korkar ve O''na karşı gelmekten sakınırsa; işte onlar kurtuluşa erenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 53, 'Münâfıklar, sen kendilerine emrettiğin takdirde mutlaka savaşa çıkacaklarına dair en ağır bir şekilde Allah’a yemin ettiler. Onlara de ki: "Yemin etmeyin. Sizden istenen güzelce itaat etmektir. Allah, elbette yaptıklarınızdan hakkıyla haberdardır."');
INSERT INTO verses (sura, aya, text) VALUES (24, 54, 'Yine de ki: "Allah''a itaat edin ve Peygamber''e itaat edin. Eğer yüz çevirirseniz, bilin ki ona yüklenen sorumluluğu ancak ona ait; size yüklenen görevin sorumluluğu da yalnızca size aittir. Eğer ona itaat ederseniz, hidayete erersiniz. Rasûle düşen apaçık beyan etmekten başka bir şey değildir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 55, 'Allah, içinizden iman edenlere ve salih ameller işleyenlere, kendilerinden öncekileri hükümran kıldığı gibi, onları da yeryüzünde hükümran kılacağını, kendileri için seçip beğendiği dinlerini onlar için güçlendirip yerleştireceğini ve korkulu hallerini güvene çevireceğini vadetmiştir. Bana hiçbir şeyi ortak koşmaksızın ibadet ederler. Bundan sonra artık kim kâfir olursa onlar fasıkların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 56, 'Namazı dosdoğru kılın, zekâtı verin ve Rasûle itaat edin ki size merhamet edilsin.');
INSERT INTO verses (sura, aya, text) VALUES (24, 57, 'Küfredenlerin yeryüzünde (Allah''ı) aciz bırakacaklarını sanma. Onların barınakları ateştir. Ne kötü dönüş yeri!');
INSERT INTO verses (sura, aya, text) VALUES (24, 58, 'Ey İman edenler! Ellerinizin altında bulunan (köle ve cariyeleriniz) ve içinizden henüz ergenlik çağına girmemiş olanlar, sabah namazından önce, öğleyin elbiselerinizi çıkardığınız vakit ve yatsı namazından sonra (yanınıza gireceklerinde) sizden üç defa izin istesinler. Bu üçü, avret vaktidir (sizden sakınmaları gereken zamandır). Bu vakitlerin dışında sizin için de onlar için de bir günah yoktur. Birbirinizin yanına girip çıkabilirsiniz. İşte Allah ayetleri size böyle açıklar. Allah, (her şeyi) hakkıyla bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 59, 'Çocuklarınız ergenlik çağına girdiklerinde, kendilerinden öncekilerin (büyüklerin) izin istedikleri gibi onlar da izin istesinler. İşte Allah, ayetlerini size böyle açıklar. Allah, (her şeyi) hakkıyla bilendir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 60, 'Evlenme arzusu kalmayıp, oturan yaşlı kadınların, süslerini açığa vurmaksızın (dış) elbiselerini çıkarmalarında kendileri için bir günah/sakınca yoktur. İffetli olmaları/örtülerini giymeleri kendileri için daha hayırlıdır. Allah her şeyi hakkıyla işitendir, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 61, 'Köre bir günah yoktur, topala veya hastaya da bir günah yoktur. Aynı şekilde size de evlerinizde, babalarınızın evlerinde, annelerinizin evlerinde, erkek kardeşlerinizin evlerinde, kız kardeşlerinizin evlerinde, amcalarınızın evlerinde, halalarınızın evlerinde, dayılarınızın evlerinde, teyzelerinizin evlerinde, anahtarları sizde olan evlerde veya arkadaşlarınızın evlerinde topluca ya da ayrı ayrı yemek yemenizde bir günah yoktur. Evlere girdiğiniz vakit, Allah tarafından mübarek ve temiz bir selam ile kendinize (birbirinize) selam verin. Allah, akledesiniz diye size ayetlerini işte böyle apaçık bir şekilde açıklamaktadır.');
INSERT INTO verses (sura, aya, text) VALUES (24, 62, 'Müminler, ancak Allah’a ve Rasûlüne iman ederler, onunla birlikte toplu bir iş için bir araya geldikleri zaman, ondan izin almadan (oradan) ayrılmazlar. Senden izin isteyenler, Allah’a ve Rasûlüne iman edenlerdir. Bazı işleri dolayısıyla senden izin istedikleri zaman onlardan dilediğine izin ver. Onlar için Allah’tan mağfiret dile. Şüphesiz Allah, çok mağfiret edendir, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (24, 63, '(Ey Müminler!) Peygamber''i, kendi aranızda birbirinizi çağırır gibi çağırmayın. Aranızda birbirinizin arkasına gizlenerek gizlice sıvışıp gidenlerinizi muhakkak Allah bilir. Bu sebeple, onun emrine aykırı davrananlar, başlarına bir bela gelmesinden veya kendilerine çok elemli bir azap isabet etmesinden sakınsınlar.');
INSERT INTO verses (sura, aya, text) VALUES (24, 64, 'Bilmiş olun ki, göklerde ve yerde ne varsa Allah''ındır. O, sizin ne yolda olduğunuzu çok iyi bilir. İnsanlar O''nun huzuruna döndürüldükleri gün yapmış olduklarını onlara haber verecektir. Allah, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 1, 'Âlemlere bir uyarıcı olsun diye kuluna Furkân’ı indiren Allah ne yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 2, 'Göklerin ve yerin hükümranlığı O''na mahsustur. Hiçbir oğul edinmemiştir ve hükümranlıkta hiçbir ortağı yoktur. Her şeyi o yaratmış ve bir düzen içinde O takdir etmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 3, '(Kâfirler) O’nu (Allah''ı) bırakıp, hiçbir şey yaratamayan, bilâkis kendileri yaratılmış olan, kendilerine bile bir zarar veya yarar sağlayamayan, öldürmeye de, yaşatmaya da, yeniden diriltmeye de güçleri olmayan ilahlar edindiler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 4, 'Kâfirler dediler ki: “Bu ancak onun uydurduğu bir yalandır. Ona başka bir topluluk da bunun için yardım etmiştir.” Muhakkak onlar zulmettiler, asılsız bir iddiada bulundular.');
INSERT INTO verses (sura, aya, text) VALUES (25, 5, 'Ve dediler ki: “(Bu) öncekilerin masallarıdır. Onu başkalarından alıp yazmıştır. Onlar sabah akşam kendisine okunmaktadır.”');
INSERT INTO verses (sura, aya, text) VALUES (25, 6, '(Rasûlüm!) De ki: ''Onu, göklerde ve yerde gizli olanı bilen (Allah) indirmiştir. Doğrusu O, çok bağışlayandır, çok esirgeyendir.''');
INSERT INTO verses (sura, aya, text) VALUES (25, 7, '"Bu nasıl bir peygamber?" dediler. "Yemek yiyor, pazarda dolaşıyor. Ona bir melek indirilseydi de onun yanında uyarıcı olsaydı ya!"');
INSERT INTO verses (sura, aya, text) VALUES (25, 8, '“Yahut ona bir hazine verilmeli ya da mahsullerinden yiyeceği bir bahçesi olmalı değil miydi?” Zalimler: “Siz ancak büyülenmiş bir adama uyuyorsunuz” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 9, 'Bir bak, onlar sana nasıl misaller getirip sapıklığa düştüler? Artık onlar hiçbir yol bulamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (25, 10, 'Dilerse sana bunlardan daha iyisini, altlarından ırmaklar akan Cennetleri verecek ve sana saraylar ihsan edecek olan Allah çok yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 11, 'Onlar zaten (kıyamet) saatini yalanlamışlardı. Kıyameti yalanlayanlar için alevli bir ateş hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (25, 12, 'O ateş onları uzaktan görünce onun büyük bir öfke ile çıkaracağı şiddetli uğultusunu işiteceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 13, 'Onlar elleri boyunlarında bağlanıp, onun dar bir yerine atıldıklarında orada: “Ölüm” diye feryat ederler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 14, '“Bugün ölümü bir kere değil, birçok kere temenni edin!” (denilecek).');
INSERT INTO verses (sura, aya, text) VALUES (25, 15, 'De ki: "Bu mu daha iyi, yoksa takvâ sahiplerine vadedilen Ebedilik Cenneti mi? Orası, onlar için bir mükâfat ve (huzura kavuşacakları) bir varış yeridir."');
INSERT INTO verses (sura, aya, text) VALUES (25, 16, 'Onlara orada istedikleri vardır ve (orada) ebedi kalırlar. Bu Rabbinin üzerine, (yerine getirilmesi) istenen bir vaaddir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 17, 'O gün Rabbin, onları ve Allah’tan başka ibadet ettiklerini bir araya toplar ve şöyle der: "Şu kullarımı siz mi saptırdınız yoksa kendileri mi yoldan saptılar?"');
INSERT INTO verses (sura, aya, text) VALUES (25, 18, 'Derler ki: “Seni tenzih ederiz. Senden başkalarını veliler edinmek bize yaraşmaz. Fakat sen onları ve babalarını faydalandırdın. Sonunda zikri unuttular ve helâk olan bir kavim oldular.”');
INSERT INTO verses (sura, aya, text) VALUES (25, 19, 'İşte söylediklerinizde sizi yalanladılar. Artık ne üzerinizdeki azabı def edebilirsiniz, ne de bir yardıma güç yetirirsiniz. Sizden kim zulmederse ona büyük bir azabı tattırırız.');
INSERT INTO verses (sura, aya, text) VALUES (25, 20, '(Rasûlüm!) Senden önce gönderdiğimiz bütün peygamberler de hiç şüphesiz yemek yerler, çarşılarda dolaşırlardı. (Ey insanlar!) Sizin bir kısmınızı diğer bir kısmınıza imtihan (vesilesi) kıldık. (Bakalım) sabredecek misiniz? Rabbin her şeyi hakkıyla görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 21, 'Bizimle karşılaşmayı ummayanlar; "Bize ya melekler indirilmeliydi ya da Rabbimizi görmeliydik." dediler. Şüphesiz onlar, kendi nefislerinde büyüklüğe kapıldılar ve büyük bir taşkınlık gösterdiler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 22, 'Melekleri gördükleri gün, işte o gün günahkârlara müjde yoktur. Melekler onlara: "Sizin için (müjde) yasak edilmiştir, yasak! diyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 23, 'Onların yaptıkları bütün amellere yöneldik ve saçılmış toz zerreleri haline getirdik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 24, 'O gün cennetliklerin kalacakları yer daha hayırlı, dinlenecekleri yer daha güzeldir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 25, 'O gün gök bulutlarla yarılıp parçalanacak ve melekler bölük bölük indirilecektir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 26, 'O gün gerçek hükümranlık Rahman’ındır ve kâfirlere zorlu bir gün olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (25, 27, 'O gün zalim kimse, (çaresizlik içinde) ellerini ısırıp şöyle diyecektir: “Ne olurdu; ben de peygamberle beraber aynı yolu tutsaydım!”');
INSERT INTO verses (sura, aya, text) VALUES (25, 28, '“Yazıklar olsun bana, keşke falanı dost edinmeseydim!”');
INSERT INTO verses (sura, aya, text) VALUES (25, 29, '“Andolsun, Kur’an bana geldikten sonra beni ondan o saptırdı. Zaten Şeytan, insanı yardımcısız bırakıverir.”');
INSERT INTO verses (sura, aya, text) VALUES (25, 30, 'Rasul: “Ya Rabb! Gerçekten benim kavmim bu Kur’an’ı terk etti” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (25, 31, 'Biz, işte böyle her peygamber için suçlulardan bir düşman yarattık. Yol gösterici ve yardım edici olarak Rabbin yeter.');
INSERT INTO verses (sura, aya, text) VALUES (25, 32, 'Kâfirler: “Kur’an ona bir defada toptan indirilseydi ya!” dediler. Biz onunla kalbine sebat verelim diye yaptık ve onu ağır ağır okuduk.');
INSERT INTO verses (sura, aya, text) VALUES (25, 33, 'Onlar sana her ne misal getirseler (buna karşılık) mutlaka biz de sana hakkı ve daha güzel açıklamayı getiririz.');
INSERT INTO verses (sura, aya, text) VALUES (25, 34, 'Yüzükoyun cehenneme (sürülüp) toplanacak olanlar; işte onlar, yerleri en kötü, yolları en sapık olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (25, 35, 'Andolsun, biz, Mûsâ''ya ’ya Kitabı (Tevrat’ı) verdik ve kardeşi Harun’u da ona yardımcı kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (25, 36, 'Onlara: “Ayetlerimizi yalanlayan topluluğa gidin.” dedik. Nihayet o kavmi yerle bir ettik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 37, 'Nûh kavmini de, peygamberleri yalanladıkları vakit suda boğduk. Onları insanlara bir ibret yaptık ve zalimlere elem dolu bir azap hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (25, 38, 'Âd ve Semûd kavimlerini, Ress halkını ve bunların arasında pek çok nesilleri de helâk ettik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 39, 'Bunların her birine misaller getirdik, (öğüt almadıkları için) hepsini kırıp geçirdik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 40, 'Muhakkak onlar belâ yağmuruna tutulan beldeye uğramışlardır. Acaba bunlar orayı görmediler miydi? Hayır! onlar tekrar dirilmeyi ummuyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (25, 41, 'Seni gördükleri zaman: "Bu mu Allah’ın gönderdiği elçi?" diye alay etmekten başka bir şey yapmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (25, 42, '“Eğer ilâhlarımıza sebat göstermeseydik az kalsın bizi ilâhlarımızdan saptıracaktı.” Yakında azabı gördüklerinde yolca kimin sapık olduğunu bileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 43, 'Hevâ ve hevesini kendine ilâh edinen kimseyi gördün mü? O kimseye sen mi vekil olacaksın?');
INSERT INTO verses (sura, aya, text) VALUES (25, 44, 'Sen onların çoğunu dinler ve akıl erdirirler mi sanırsın? Onlar ancak hayvanlar gibidir. Hatta onlar yolca daha da sapıklıktadırlar.');
INSERT INTO verses (sura, aya, text) VALUES (25, 45, 'Rabbinin gölgeyi nasıl uzattığına görmez misin? Dileseydi onu hareketsiz kılardı, sonra Güneşi ona delil kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (25, 46, 'Sonra onu yavaş yavaş kendimize çektik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 47, 'Geceyi sizin için elbise, uykuyu da rahatlık kılan odur. O gündüzü de yeni bir hayata başlangıç yaptı.');
INSERT INTO verses (sura, aya, text) VALUES (25, 48, 'Rahmetinin öncesinde rüzgarları bir müjdeci olarak gönderen de O''dur. Biz gökten tertemiz su indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 49, 'Onunla ölü bir şehri diriltelim ve onunla yarattığımız birçok hayvanı ve insanı sulayalım diye.');
INSERT INTO verses (sura, aya, text) VALUES (25, 50, 'Andolsun, biz bunu insanlar arasında, düşünüp ibret alsınlar diye tekrar tekrar açıkladık. Fakat insanların çoğu nankörlükte direttiler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 51, 'Eğer dileseydik her bir beldeye elbette bir uyarıcı gönderirdik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 52, 'O halde kâfirlere itaat etme ve onlara karşı Kur’an’la büyük bir mücadele ver.');
INSERT INTO verses (sura, aya, text) VALUES (25, 53, 'İki denizi birbirine salan O''dur. Bu tatlı ve lezzetli, bu da tuzlu ve acıdır. O ikisinin arasına bir perde ve aşılamayan bir sınır koymuştur.');
INSERT INTO verses (sura, aya, text) VALUES (25, 54, 'Ve o sudan insanı yaratan, onu soy ve hısımlık sahibi kılan O''dur. Rabbin, her şeye güç yetirendir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 55, 'Hâlbuki onlar Allah’tan başka kendilerine fayda da, zarar da veremeyen şeylere ibadet ederler. Kâfir, Rabbine karşı (Şeytan''a) arka çıkandır.');
INSERT INTO verses (sura, aya, text) VALUES (25, 56, 'Biz, seni ancak bir müjdeci ve bir uyarıcı olarak gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (25, 57, 'De ki: "Ben, buna karşı sizden bir ücret değil, ancak Rabbine doğru bir yol tutmayı dileyen kimseler (olmanızı) istiyorum."');
INSERT INTO verses (sura, aya, text) VALUES (25, 58, 'Ölümsüz daima diri olan Allah''a dayanıp, tevekkül et ve O''nu hamt ile tesbih et. Kullarının günahlarından hakkıyla haberdar olarak O yeter.');
INSERT INTO verses (sura, aya, text) VALUES (25, 59, 'Gökleri yeri ve bunların arasındakileri altı günde yaratan, sonra arşa istivâ eden Rahman’dır. O''nu her şeyden haberi olan (Allah''a) sor.');
INSERT INTO verses (sura, aya, text) VALUES (25, 60, 'Onlara: "Rahman''a secde edin!" denildiği zaman, “Rahman da neymiş? Biz senin bize emrettiğine mi secde edecekmişiz?" derler ve (bu) onların (haktan) kaçıp uzaklaşmalarını arttırıverir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 61, 'Gökte yıldızlar/gezegenler yaratan ve orada bir kandil (Güneş) ve aydınlatıcı bir Ay var eden (Allah) çok yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 62, 'İbret almak veya şükretmek isteyenler için gece ile gündüzü birbiri ardına getiren de O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (25, 63, 'Rahman’ın kulları, yeryüzünde vakarlı ve alçak gönüllü olarak yürürler. Cahiller kendilerine hitap ettiklerinde onlar: “Selam!” deyip geçerler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 64, 'Onlar, Rablerine secde ederek ve kıyama durarak gecelerler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 65, 'Onlar: "Rabbimiz, Cehennem azabını bizden uzaklaştır. Çünkü onun azabı süreklidir." derler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 66, 'Orası ne kötü bir karar kılma/durak ve yerleşme yeridir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 67, 'Ve onlar ki mallarını infak ettiklerinde israf da etmezler, cimrilik de etmezler. Bunun arasında orta bir yol tutarlar.');
INSERT INTO verses (sura, aya, text) VALUES (25, 68, 'Onlar ki, Allah ile birlikte başka bir ilâha dua/ibadet etmezler. Hak ile olması dışında, Allah’ın öldürülmesini haram kıldığı nefsi de öldürmezler. Zina da etmezler. Kim bunları işlerse cezaları ile karşılaşır.');
INSERT INTO verses (sura, aya, text) VALUES (25, 69, 'Kıyamet günü onun azabı kat kat artırılır ve horlanmış olarak orada ebedî kalır.');
INSERT INTO verses (sura, aya, text) VALUES (25, 70, 'Ancak tevbe edip iman eden ve salih amel işleyenler, Allah bunların günahlarını sevaba/iyiliğe çevirir. Allah, çok bağışlayan ve çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 71, 'Kim de tevbe eder ve salih amel işlerse; işte o, Allah’a tevbesi kabul edilmiş olarak döner.');
INSERT INTO verses (sura, aya, text) VALUES (25, 72, 'Onlar yalancı şahitlik etmezler ve yararsız bir şeye rastladıklarında onurlu bir şekilde (yüz çevirip) geçerler.');
INSERT INTO verses (sura, aya, text) VALUES (25, 73, 'Onlar ki, Rablerinin âyetleriyle kendilerine öğüt verildiği zaman buna karşı sağır ve kör kimseler olarak yüzleri üzere yıkılıp yatmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (25, 74, 'Onlar: “Ey Rabbimiz! Eşlerimizi ve çocuklarımızı bize göz aydınlığı kıl ve bizi Allah’a karşı gelmekten sakınanlara önder eyle!” diyenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (25, 75, 'İşte onlar, sabretmelerine karşılık Cennet''in yüksek makamlarıyla mükâfatlandırılacaklar ve orada esenlik dileği ve selamla karşılanacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (25, 76, 'Orada ebedî kalırlar. Orası ne güzel bir durak ve ne güzel bir konaktır!');
INSERT INTO verses (sura, aya, text) VALUES (25, 77, 'Ey Muhammed!) De ki: “Duanız (kulluğunuz ve yalvarmanız) olmasa, Rabbim size ne diye değer versin? (Ey inkârcılar! Size Rasûlün bildirdiklerini) yalanladınız. Öyle ise azap, yakanızı bırakmayacak.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 1, 'Tâ, Sîn, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (26, 2, 'Bunlar apaçık kitabın ayetleridir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 3, '(Ey Muhammed!) İman etmiyorlar diye adeta kendini helâk edeceksin!');
INSERT INTO verses (sura, aya, text) VALUES (26, 4, 'Dilersek, üzerlerine gökten bir ayet/mucize indiririz de boyunları öne eğilip kalır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 5, 'Rahman’dan kendilerine gelen her yeni öğütten mutlaka yüz çevirirler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 6, 'Onlar (Allah’ın ayetlerini) yalanladılar. Fakat alay edegeldikleri şeylerin haberleri başlarına gelecek.');
INSERT INTO verses (sura, aya, text) VALUES (26, 7, 'Yeryüzüne bakmazlar mı ki biz orada her güzel çiftten nice bitkiler bitirdik.');
INSERT INTO verses (sura, aya, text) VALUES (26, 8, 'Şüphesiz bunlarda (Allah’ın varlığına) bir delil vardır, ancak onların çoğu iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 9, 'Muhakkak Rabbin Azîz, Rahîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 10, 'Hani Rabbin, Mûsâ''ya ’ya: "Zalim kavme git!" diye seslenmişti.');
INSERT INTO verses (sura, aya, text) VALUES (26, 11, 'Firavun’un kavmine. Onlar hâlâ sakınmayacaklar mı?');
INSERT INTO verses (sura, aya, text) VALUES (26, 12, 'Mûsâ, şöyle dedi: “Ey Rabbim! Muhakkak ki ben, beni yalanlamalarından korkuyorum.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 13, '“Ve göğsüm daralır, dilim çözülmez; bunun için Hârûn da (vahiy) gönder.');
INSERT INTO verses (sura, aya, text) VALUES (26, 14, '“Bir de onların benim aleyhimde bir suç (davaları) var. Dolayısıyla beni öldürmelerinden korkuyorum.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 15, 'Allah dedi ki: “Hayır, korkma! İkiniz ayetlerimizle gidin. Muhakkak biz sizinle birlikteyiz, işitenleriz.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 16, 'İkiniz Firavun’a gidin ve deyin ki: "Gerçekten biz âlemlerin Rabbinin rasulleriyiz."');
INSERT INTO verses (sura, aya, text) VALUES (26, 17, 'İsrailoğulları''nı bizimle beraber gönder.');
INSERT INTO verses (sura, aya, text) VALUES (26, 18, 'Firavun, şöyle dedi: “Seni biz küçük bir çocuk olarak alıp aramızda büyütüp, yetiştirmedik mi? Sen ömrünün nice yıllarını aramızda geçirdin.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 19, '“(Böyle iken) sen o yaptığın işi yaptın (adam öldürdün). Sen nankörlerdensin.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 20, 'Mûsâ, şöyle dedi: “Ben onu yaptığım zaman ne yaptığını bilmezlerdendim.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 21, '“Sizden korktuğum için de hemen aranızdan kaçtım. Derken, Rabbim bana hüküm ve hikmet bahşetti de beni peygamberlerden kıldı.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 22, '"Benim başıma o nimeti kakmaktasın. (Halbuki) Sen İsariloğullarını kendine köle edindin."');
INSERT INTO verses (sura, aya, text) VALUES (26, 23, 'Firavun: “Âlemlerin Rabbi de nedir?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 24, 'Dedi ki: “Eğer yakin sahibi iseniz, (biliniz ki) O, göklerin, yerin ve ikisi arasında bulunan her şeyin Rabbidir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 25, '(Firavun) Etrafında bulunanlara: “İşitmiyor musunuz” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 26, 'Mûsâ: “O; sizin de Rabbiniz, geçmiş atalarınızın da Rabbidir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 27, '(Firavun): “Size gönderilen bu elçiniz mutlaka delidir” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 28, '(Mûsâ): “Doğunun, batının ve onların etrafında olanların Rabbidir. Eğer akıl ederseniz” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 29, '“Eğer benden başka ilâh edinirsen elbette seni zindana atılanlar arasına katarım” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 30, 'Mûsâ: “Sana apaçık bir delil getirmiş olsam da mı?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 31, 'Firavun: “Doğru söyleyenlerden isen haydi getir onu!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 32, '(Mûsâ) bunun üzerine asasını bıraktı. O da hemen apaçık bir yılan oluverdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 33, 'Elini koynundan çıkardı. Bir de ne görsünler, bakanlara bembeyaz olmuş.');
INSERT INTO verses (sura, aya, text) VALUES (26, 34, 'Firavun, çevresindeki ileri gelenlere: “Şüphesiz bu, bilgin bir sihirbazdır.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 35, '“Sizi sihri ile yerinizden çıkarmak istiyor; ya siz ne buyurursunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 36, 'Dediler ki: "Onu ve kardeşini alıkoy. Şehirlere de toplayıcı adamlar gönder.''''');
INSERT INTO verses (sura, aya, text) VALUES (26, 37, '“Sana bütün usta sihirbazları getirsinler.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 38, 'Böylece sihirbazlar, belli bir günün belirlenen bir vaktinde bir araya getirildiler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 39, 'İnsanlara da; “Siz de toplanır mısınız?” denildi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 40, '“Umarız ki sihirbazlar galip gelirlerse biz de onlara uyarız.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 41, 'Sihirbazlar gelince, Firavun’a: “Eğer biz üstün gelirsek, gerçekten bize bir mükâfat var mı?” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 42, 'Firavun: “Evet! Hem o takdirde mutlaka bana yakın kimselerden olacaksınız.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 43, 'Mûsâ onlara: “Hadi ortaya atacağınız şeyi atın!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 44, 'Bunun üzerine onlar iplerini ve asalarını attılar ve; “Firavun’un gücüyle elbette bizler üstün geleceğiz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 45, 'Mûsâ asasını bırakır bırakmaz onların hile ile yaptıklarını yutuverdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 46, 'Bunun üzerine sihirbazlar derhal secdeye kapandılar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 47, '"Âlemlerin Rabbine iman ettik." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 48, 'Mûsâ’nın ve Hârûn’un Rabbine iman ettik dediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 49, 'Dedi ki: “Ben size izin vermeden önce mi ona iman ettiniz? Demek ki o, size sihri öğreten büyüğünüzmüş. Yakında bileceksiniz. Mutlaka el ve ayaklarınızı çaprazlama keseceğim ve hepinizi toptan asacağım.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 50, '"Hiç zararı yok. Biz muhakkak Rabbimize döneceğiz."');
INSERT INTO verses (sura, aya, text) VALUES (26, 51, '“Doğrusu biz, iman edenlerin ilki olduğumuzdan dolayı Rabbimizin bizim hatalarımızı bağışlayacağını ummaktayız.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 52, 'Biz Mûsâ’ya; “Kullarımı geceleyin yola çıkar. Muhakkak ki takip edileceksiniz.” diye vahyettik.');
INSERT INTO verses (sura, aya, text) VALUES (26, 53, 'Firavun da şehirlere (asker) toplayıcılar gönderdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 54, '“Şüphesiz bunlar azınlık olan bir topluluktur (dediler).”');
INSERT INTO verses (sura, aya, text) VALUES (26, 55, '"Ve onlar bizi kızdırmaktadırlar."');
INSERT INTO verses (sura, aya, text) VALUES (26, 56, 'Biz ise şüphesiz uyanık, ihtiyatlı bir topluluğuz."');
INSERT INTO verses (sura, aya, text) VALUES (26, 57, '(Allah Teâlâ buyurdu ki): Böylece onları bahçelerden ve pınarlardan çıkardık.');
INSERT INTO verses (sura, aya, text) VALUES (26, 58, 'Hazinelerden ve değerli yerlerden.');
INSERT INTO verses (sura, aya, text) VALUES (26, 59, 'İşte böyle yaptık ve onlara İsrailoğulları''nı mirasçı kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (26, 60, 'Firavun ve adamları gün doğarken onları takibe koyuldular.');
INSERT INTO verses (sura, aya, text) VALUES (26, 61, 'İki topluluk birbirini görünce, Mûsâ’nın adamları: "İşte yakalandık." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 62, 'Mûsâ: “Hayır! Rabbim şüphesiz benimledir, bana yol gösterecektir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 63, 'İşte o sırada, Mûsâ’ya: "Asanı denize vur!" diye vahyettik. O, hemen yarıldı ve (on iki yol açıldı) her parçası koca bir dağ gibi oluverdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 64, 'Ötekileri de oraya yaklaştırdık.');
INSERT INTO verses (sura, aya, text) VALUES (26, 65, 'Mûsâ’yı ve beraberindekilerin hepsini kurtardık.');
INSERT INTO verses (sura, aya, text) VALUES (26, 66, 'Sonra ötekileri suda boğduk.');
INSERT INTO verses (sura, aya, text) VALUES (26, 67, 'Bunda şüphesiz bir ibret vardır. Ama pek çokları iman etmiş değillerdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 68, 'Şüphesiz ki senin Rabbin elbette mutlak güç sahibidir, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 69, 'Ey Muhammed! Onlara İbrahim’in haberini de oku.');
INSERT INTO verses (sura, aya, text) VALUES (26, 70, 'Hani o, babasına ve kavmine; “Neye ibadet ediyorsunuz?” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (26, 71, '“Putlara ibadet ediyoruz ve onlara ibadet etmeye devam edeceğiz.” demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 72, 'İbrahim, dedi ki: “Onlara dua ettiğinizde sizi işitiyorlar mı?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 73, '“Yahut size fayda veya zararları dokunur mu?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 74, '“Hayır! Ama biz babalarımızı böyle yaparken bulduk.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 75, 'İbrahim, şöyle dedi: “Gördünüz mü şu sizin (ve önceki atalarınızın) neye ibadet ettiklerini?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 76, 'Siz ve çok daha önce gelip geçen atalarınız.');
INSERT INTO verses (sura, aya, text) VALUES (26, 77, '"İşte onlar benim düşmanlarımdır. Yalnız alemlerin Rabbi hariç."');
INSERT INTO verses (sura, aya, text) VALUES (26, 78, '“O, beni yaratan ve bana doğru yolu gösterendir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 79, '"Beni yediren ve içiren O''dur.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 80, '"Hastalandığımda da O bana şifa verir."');
INSERT INTO verses (sura, aya, text) VALUES (26, 81, '“O, benim canımı alacak ve sonra diriltecek olandır.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 82, '“O, hesap gününde hatalarımı bağışlayacağını umduğumdur.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 83, '“Ey Rabbim! Bana bir hikmet bahşet ve beni salih kimseler arasına kat.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 84, '“Sonra gelecekler arasında beni doğrulukla anılanlardan kıl.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 85, '“Beni Naîm Cenneti''nin varislerinden eyle.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 86, '"Babamı da bağışla. Şüphesiz o sapıklardandır."');
INSERT INTO verses (sura, aya, text) VALUES (26, 87, '“(Kulların yeniden) diriltilecekleri gün beni utandırma!”');
INSERT INTO verses (sura, aya, text) VALUES (26, 88, '“O gün ki ne mal fayda verir, ne oğullar!”');
INSERT INTO verses (sura, aya, text) VALUES (26, 89, '“Allah’a arınmış bir kalp ile gelen başka.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 90, 'O gün cennet takva sahiplerine yaklaştırılır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 91, 'Cehennem de azgınlar için ortaya çıkarılıverir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 92, 'Ve onlara; "İbadet etmekte olduklarınız nerede?" denilir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 93, 'Allah''ın dışında (edindiğiniz ilahların), size yardımları dokunuyor mu veya kendilerine yardımları oluyor mu?');
INSERT INTO verses (sura, aya, text) VALUES (26, 94, 'Onlar ve azgınlar hep birlikte oraya atılırlar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 95, 'Ve İblis''in bütün orduları da.');
INSERT INTO verses (sura, aya, text) VALUES (26, 96, 'Orada birbirleriyle çekişerek, şöyle derler:');
INSERT INTO verses (sura, aya, text) VALUES (26, 97, '“Allah’a andolsun, biz gerçekten apaçık bir sapıklık içindeymişiz.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 98, '“Çünkü sizi, âlemlerin Rabbi ile bir tutuyorduk.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 99, 'Bizi o suçlulardan başkası saptırmadı.');
INSERT INTO verses (sura, aya, text) VALUES (26, 100, '“Artık bize şefaat edecek bir kimse de yoktur.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 101, '"Samimi bir dost da yok."');
INSERT INTO verses (sura, aya, text) VALUES (26, 102, '"Ah! Keşke bizim için (dünyaya) bir dönüş daha olsa da Müminlerden olsak!"');
INSERT INTO verses (sura, aya, text) VALUES (26, 103, 'Şüphesiz bunda bir ayet vardır, ama onların çoğu iman etmiş değildirler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 104, 'Şüphesiz senin Rabbin mutlak güç sahibi ve çok merhametli olandır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 105, 'Nûh kavmi rasûlleri yalanladılar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 106, 'Hani kardeşleri Nûh onlara demişti ki: "Siz sakınmıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (26, 107, '“Şüphesiz ben size gönderilmiş güvenilir bir rasûlüm.''''');
INSERT INTO verses (sura, aya, text) VALUES (26, 108, 'Artık Allah''tan sakının ve bana itaat edin.');
INSERT INTO verses (sura, aya, text) VALUES (26, 109, '“Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 110, '“O halde, Allah’a karşı gelmekten sakının ve bana itaat edin!”');
INSERT INTO verses (sura, aya, text) VALUES (26, 111, 'Dediler ki: “Sana, sıradan aşağılık insanlar uymuşken(biz) sana iman eder miyiz?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 112, 'Nûh, şöyle dedi: “Onların yaptıklarına dair benim ne bilgim olabilir?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 113, '“Onların hesaplarını görmek ancak Rabbime aittir. Bir anlayabilseniz!”');
INSERT INTO verses (sura, aya, text) VALUES (26, 114, '"Ben, Müminleri kovacak değilim."');
INSERT INTO verses (sura, aya, text) VALUES (26, 115, '"Ben, ancak apaçık bir uyarıcıyım."');
INSERT INTO verses (sura, aya, text) VALUES (26, 116, 'Dediler ki: “Ey Nûh! (Bu işten) vazgeçmezsen mutlaka taşlananlardan olacaksın!”');
INSERT INTO verses (sura, aya, text) VALUES (26, 117, 'Nûh, şöyle dedi: “Ey Rabbim! Kavmim beni yalanladı.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 118, 'Artık benimle onların aralarında hüküm ver ve beni ve benimle beraber olan Müminleri kurtar."');
INSERT INTO verses (sura, aya, text) VALUES (26, 119, 'Biz de onu ve onunla birlikte olanları dopdolu o gemi içerisinde kurtardık.');
INSERT INTO verses (sura, aya, text) VALUES (26, 120, 'Sonra geride kalanları suda boğduk.');
INSERT INTO verses (sura, aya, text) VALUES (26, 121, 'Muhakkak bunda bir ayet vardır. Onların çoğu iman etmediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 122, 'Muhakkak Rabbin Azîz olandır, Rahîm olandır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 123, 'Âd kavmi de peygamberleri yalanlamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (26, 124, 'Hani onlara kardeşleri Hûd, “Sakınmaz mısınız?” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (26, 125, '“Şüphesiz ben, size gönderilmiş güvenilir bir rasûlüm.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 126, '"Öyle ise Allah''tan sakının ve bana itaat edin."');
INSERT INTO verses (sura, aya, text) VALUES (26, 127, '“Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 128, '"Siz her yüksek yerde eğlenmek için koca bir bina mı inşa edip durursunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (26, 129, '"Ve ebedi kalırsınız ümidi ile sapasağlam kaleler mi yapar durursunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (26, 130, '"Yakaladığınız zaman da zorbaca mı davranırsınız?"');
INSERT INTO verses (sura, aya, text) VALUES (26, 131, '"Artık Allah’tan korkun ve bana itaat edin."');
INSERT INTO verses (sura, aya, text) VALUES (26, 132, '"Bilmekte olduğunuz şeylerle size yardım edenden korkup sakının."');
INSERT INTO verses (sura, aya, text) VALUES (26, 133, '"Size hayvanlar ve çocuklar (vererek) yardım etti."');
INSERT INTO verses (sura, aya, text) VALUES (26, 134, 'Hem de bahçeler ve pınarlar da (vermiştir).');
INSERT INTO verses (sura, aya, text) VALUES (26, 135, '"Gerçekten sizin için büyük bir günün azabından korkarım."');
INSERT INTO verses (sura, aya, text) VALUES (26, 136, 'Onlar dediler ki: "Sen öğüt versen de, öğüt verenlerden olmasan da bizim için birdir."');
INSERT INTO verses (sura, aya, text) VALUES (26, 137, '"Bu öncekilerin adetlerinden başka bir şey değildir."');
INSERT INTO verses (sura, aya, text) VALUES (26, 138, '"Biz azap olunacaklardan da değiliz."');
INSERT INTO verses (sura, aya, text) VALUES (26, 139, '"Böylece onu yalanladılar. Biz de onları helâk ettik. Muhakkak bunda bir ayet vardır. Onların çoğu da iman etmiş değildi."');
INSERT INTO verses (sura, aya, text) VALUES (26, 140, 'Muhakkak Rabbin Azîz olandır, Rahîm olandır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 141, 'Semûd da rasulleri yalanladılar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 142, 'Hani kardeşleri Salih onlara demişti ki: "Sakınmaz mısınız?"');
INSERT INTO verses (sura, aya, text) VALUES (26, 143, '“Ben size gönderilmiş güvenilir bir rasûlüm.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 144, '"O halde Allah’tan korkun ve bana itaat edin."');
INSERT INTO verses (sura, aya, text) VALUES (26, 145, '“Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 146, '"Siz burada güven içinde bırakılacağınızı mı sanıyorsunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (26, 147, 'Bahçelerde ve akarsular arasında,');
INSERT INTO verses (sura, aya, text) VALUES (26, 148, 'Ekinler ve meyveleri olgunlaşmış güzel hurma ağaçları arasında,');
INSERT INTO verses (sura, aya, text) VALUES (26, 149, '“Dağları maharetle oyup alımlı köşkler yapıyorsunuz?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 150, '"Artık Allah’tan korkun ve bana itaat edin."');
INSERT INTO verses (sura, aya, text) VALUES (26, 151, '"Aşırı olanların emrine uymayın!"');
INSERT INTO verses (sura, aya, text) VALUES (26, 152, '"Ki onlar, yeryüzünde bozgunculuk çıkarır ve (hiçbir şeyi) ıslah etmezler."');
INSERT INTO verses (sura, aya, text) VALUES (26, 153, 'Dediler ki: “Sen muhakkak aşırı bir şekilde büyülenmişlerdensin.');
INSERT INTO verses (sura, aya, text) VALUES (26, 154, '“Sen de ancak bizim gibi bir beşersin. Eğer doğru söyleyenlerden isen haydi bize bir mucize getir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 155, 'Salih, şöyle dedi: “İşte bir dişi deve! Onun (belli bir gün) su içme hakkı var, sizin de belli bir gün su içme hakkınız vardır.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 156, '“Sakın ona bir kötülükle dokunmayın. Yoksa büyük bir günün azabı sizi yakalar.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 157, 'Derken onu kestiler de pişman oluverdiler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 158, 'Bunun üzerine azap onları yakaladı. Muhakkak bunda bir ayet vardır ama onların çoğu iman etmediler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 159, 'Muhakkak senin Rabbin Azîz olandır, Rahîm olandır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 160, 'Lût’un kavmi de rasûlleri yalanlamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (26, 161, 'Hani kardeşleri Lût, onlara şöyle demişti: "Sakınmaz mısınız?”');
INSERT INTO verses (sura, aya, text) VALUES (26, 162, '“Şüphesiz ben size gönderilmiş güvenilir bir rasûlüm.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 163, '“Artık Allah’tan korkun ve bana itaat edin.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 164, '“Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 165, '"İnsanların içinde erkeklere mi yanaşıyorsunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (26, 166, '“Rabbinizin sizin için yarattığı eşlerinizi terk edersiniz demek? Hayır, siz haddi aşan bir kavimsiniz.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 167, 'Dediler ki: "Ey Lut! Eğer sen (bu işe) son vermezsen muhakkak ki (buradan) çıkarılanlardan olacaksın."');
INSERT INTO verses (sura, aya, text) VALUES (26, 168, '(Lût) dedi ki: "Doğrusu ben sizin yaptığınıza çok kızanlardanım. "');
INSERT INTO verses (sura, aya, text) VALUES (26, 169, '“Ey Rabbim! Beni ve ailemi onların yaptıkları çirkin işten kurtar.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 170, 'Bunun üzerine onu ve bütün ailesini kurtardık.');
INSERT INTO verses (sura, aya, text) VALUES (26, 171, 'Ancak o yaşlı kadın müstesna. O, geride kalanlardan oldu.');
INSERT INTO verses (sura, aya, text) VALUES (26, 172, 'Sonra diğerlerini helâk ettik.');
INSERT INTO verses (sura, aya, text) VALUES (26, 173, 'Onların üzerine bir yağmur (gibi taş) yağdırdık. (Başlarına gelecekler konusunda) uyarılanların yağmuru ne kadar da kötü idi!');
INSERT INTO verses (sura, aya, text) VALUES (26, 174, 'Şüphesiz bunda büyük bir ibret vardır. Onların çoğu ise iman etmiş değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 175, 'Muhakkak işte o, mutlak galip ve engin merhamet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 176, 'Eyke halkı da peygamberleri (Şuayb''ı) yalanlamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (26, 177, 'Hani Şu’ayb, onlara şöyle demişti: "Siz sakınmıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (26, 178, '"Şüphesiz ben size gönderilmiş güvenilir bir rasûlüm."');
INSERT INTO verses (sura, aya, text) VALUES (26, 179, '"Artık, Allah''tan sakının ve bana itaat edin."');
INSERT INTO verses (sura, aya, text) VALUES (26, 180, '“Buna karşılık sizden hiçbir ücret istemiyorum. Benim ücretim ancak âlemlerin Rabbi olan Allah’a aittir.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 181, '“Ölçüyü tam yapın. Eksik verenlerden olmayın.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 182, '"Doğru terazi ile tartın."');
INSERT INTO verses (sura, aya, text) VALUES (26, 183, '“İnsanların mal ve haklarını eksiltmeyin. Yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 184, '"Sizi ve önceki nesilleri yaratandan sakının."');
INSERT INTO verses (sura, aya, text) VALUES (26, 185, 'Dediler ki: "Sen ancak aşırı bir şekilde büyülenmişlerdensin."');
INSERT INTO verses (sura, aya, text) VALUES (26, 186, '"Sen ancak bizim gibi bir beşersin ve muhakkak biz seni yalancılardan sanıyoruz."');
INSERT INTO verses (sura, aya, text) VALUES (26, 187, '"Eğer doğru söyleyenlerden isen haydi üzerimize gökten parçalar indir."');
INSERT INTO verses (sura, aya, text) VALUES (26, 188, 'Şuayb: “Rabbim, yaptıklarınızı en iyi bilendir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 189, 'Onlar Şuayb’ı yalanladılar. Derken gölge gününün azabı onları yakaladı. Şüphesiz o, büyük bir günün azabı idi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 190, 'Şüphesiz bunda bir ibret vardır. Onların çoğu ise iman etmiş değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 191, 'Muhakkak Rabbin Azîz olandır, Rahîm olandır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 192, '"Muhakkak ki bu (Kur''an) alemlerin Rabbinin indirmesidir."');
INSERT INTO verses (sura, aya, text) VALUES (26, 193, 'O''nu Rûhu''l-Emîn/Cebrâil indirdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 194, 'Uyaranlardan olman için senin kalbine (indirdi).');
INSERT INTO verses (sura, aya, text) VALUES (26, 195, 'Apaçık Arapça bir dille.');
INSERT INTO verses (sura, aya, text) VALUES (26, 196, 'Şüphesiz bu (Kur’an) öncekilerin kitaplarında da vardı.');
INSERT INTO verses (sura, aya, text) VALUES (26, 197, 'İsrail oğulları bilginlerinin onu bilmesi, onlar için ispatlayıcı bir delil (ayet) değil midir?');
INSERT INTO verses (sura, aya, text) VALUES (26, 198, 'Eğer onu Arapça bilmeyen birine de indirmiş olsaydık.');
INSERT INTO verses (sura, aya, text) VALUES (26, 199, 'O da onlara (Kur''an''ı Arapça) okusaydı, yine de ona iman edecek değillerdi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 200, 'İşte böylece biz onu günahkârların kalbine soktuk.');
INSERT INTO verses (sura, aya, text) VALUES (26, 201, 'Acıklı azabı görünceye kadar ona iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 202, 'İşte (bu azap) onlara ansızın gelecek ve farkında bile olmayacaklar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 203, 'Ardından: “Acaba bize mühlet verilir mi” derler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 204, 'Onlar yine de azabımızın çarçabuk gelmesini mi istiyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (26, 205, '(Ey Muhammed!) Ne dersin? Biz onları yıllarca (dünya nimetlerinden) yararlandırsak...');
INSERT INTO verses (sura, aya, text) VALUES (26, 206, 'Sonra kendilerine vaadedilen başlarına gelse, (halleri nice olurdu?)');
INSERT INTO verses (sura, aya, text) VALUES (26, 207, '(Dünyada) yararlandırıldıkları şeyler onlara fayda sağlamayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 208, 'Biz uyarıcıları olmaksızın hiçbir memleketi helâk etmiş değiliz.');
INSERT INTO verses (sura, aya, text) VALUES (26, 209, '"Bu, bir hatırlatmadır. Biz zalimler değiliz."');
INSERT INTO verses (sura, aya, text) VALUES (26, 210, 'Kur’an’ı Şeytanlar indirmedi.');
INSERT INTO verses (sura, aya, text) VALUES (26, 211, 'Zaten bu onların harcı değildir, buna güçleri de yetmez.');
INSERT INTO verses (sura, aya, text) VALUES (26, 212, 'Çünkü onlar (vahyedileni) duymaktan kesinlikle uzak tutulmuşlardır.');
INSERT INTO verses (sura, aya, text) VALUES (26, 213, 'O halde Allah ile birlikte başka bir ilaha dua etme. O takdirde azap edilenlerden olursun.');
INSERT INTO verses (sura, aya, text) VALUES (26, 214, 'Önce en yakın akrabalarını uyar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 215, 'Müminlerden sana tabi olanlara kanatlarını indir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 216, 'Eğer sana karşı gelirlerse, de ki; “Şüphesiz ben sizin yaptığınız şeylerden uzağım.”');
INSERT INTO verses (sura, aya, text) VALUES (26, 217, 'Sen, Azîz ve Rahîm olana tevekkül et.');
INSERT INTO verses (sura, aya, text) VALUES (26, 218, 'O ki, (gece namaza) kalktığın zaman seni görüyor.');
INSERT INTO verses (sura, aya, text) VALUES (26, 219, 'Secde edenler ile (secdeye) yatıp kalktığın zaman da görür.');
INSERT INTO verses (sura, aya, text) VALUES (26, 220, 'Şüphesiz O; hakkıyla işitendir, hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (26, 221, 'Şeytanların kime ineceğini size haber vereyim mi?');
INSERT INTO verses (sura, aya, text) VALUES (26, 222, 'Her yalancı günahkâr üzerine inerler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 223, 'Bunlar, (şeytanlara) kulak verirler ve onların çoğu yalancıdırlar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 224, 'Şairlere de azgınlar uyar.');
INSERT INTO verses (sura, aya, text) VALUES (26, 225, 'Onlar her vadide şaşkın şaşkın dolaşmakta olduklarını görmedin mi?');
INSERT INTO verses (sura, aya, text) VALUES (26, 226, 'Ve gerçekten onlar yapmadıkları şeyi söylerler.');
INSERT INTO verses (sura, aya, text) VALUES (26, 227, 'Ancak iman edip, salih amel işleyen, Allah’ı çokça zikreden ve kendilerine zulmedildikten sonra öçlerini alanlar müstesna. Zulmedenler de yakında nasıl bir yere devrileceklerini bileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 1, 'Tâ, Sîn.[1] Bunlar, Kur’an’ın ve apaçık kitabın ayetleridir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 2, 'Müminler için bir hidayet ve bir müjdedir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 3, 'Onlar, namazı ikame ederler, zekâtı verirler ve ahirete de kesin olarak iman ederler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 4, 'Şüphesiz, ahirete iman etmeyenlerin amellerini kendilerine süslü göstermişizdir. Bu yüzden onlar körü körüne bocalayıp dururlar.');
INSERT INTO verses (sura, aya, text) VALUES (27, 5, 'İşte en kötü azap onlarındır ve onlar ahirette de en çok hüsrana uğrayanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (27, 6, 'Muhakkak sen Kur’ân’ı Hakîm, Alîm olan (Allah katından) almaktasın.');
INSERT INTO verses (sura, aya, text) VALUES (27, 7, 'Hani Mûsâ aile halkına demişti ki: "Ben gerçekten bir ateş gördüm. Size ondan bir haber getirir yahut ısınmanız için size bir kor ateş getiririm."');
INSERT INTO verses (sura, aya, text) VALUES (27, 8, 'Oraya geldiğinde kendisine şöyle seslenildi: "Ateşin yanında bulunan ve çevresinde olanlar bereketli kılınmışlardır. Âlemlerin Rabbi olan Allah her türlü noksanlıktan uzaktır."');
INSERT INTO verses (sura, aya, text) VALUES (27, 9, '"Ey Mûsâ, şüphesiz ki ben Azîz ve Hakîm olan Allah’ım."');
INSERT INTO verses (sura, aya, text) VALUES (27, 10, '“Asanı bırak.” Onun ince yılanmış gibi hareket ettiğini görünce arkasına bakmaksızın dönüp gitti. “Korkma ey Mûsâ, çünkü benim katımda rasûller korkmaz.');
INSERT INTO verses (sura, aya, text) VALUES (27, 11, '“Ancak kim zulmeder de sonra (yaptığı) kötülüğün yerine iyilik yaparsa; bilsin ki şüphesiz ben çok bağışlayıcıyım, çok merhamet edenim.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 12, '“Elini koynuna sok. Firavun’a ve onun kavmine gönderilen dokuz mucizeden biri olarak, kusursuz bembeyaz olarak çıksın. Şüphesiz onlar fasık bir kavimdir.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 13, 'Nitekim ayetlerimiz kendilerine gerçeği gösterecek biçimde gelince; “Bu apaçık bir sihirdir.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 14, 'Kendileri de bunlara yakînen inandıkları halde, zulüm ve kibirlerinden ötürü onları inkâr ettiler. Bozguncuların sonunun nasıl olduğuna bir bak!');
INSERT INTO verses (sura, aya, text) VALUES (27, 15, 'Andolsun biz Dâvud’a ve Süleyman’a bir ilim verdik. İkisi de: “Bizi mümin kullarının pek çoğuna üstün kılan Allah’a hamdolsun” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 16, 'Süleyman, Dâvud’a mirasçı olmuş; "Ey insanlar! Bize kuşların dili öğretildi ve bize her şey verildi." demişti. İşte bu apaçık bir lütuftur.');
INSERT INTO verses (sura, aya, text) VALUES (27, 17, 'Süleyman''a cinlerden, insanlardan ve kuşlardan orduları toplandı. Hepsi birlikte sevkediliyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (27, 18, 'Nihayet karınca vadisine geldikleri vakit bir karınca; “Ey karıncalar! Yuvalarınıza girin. Süleyman ve ordusu farkına varmadan sizi ezmesinler.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (27, 19, 'Süleyman, onun bu sözüne tebessüm ile gülerek dedi ki: “Ey Rabbim! Beni, bana ve ana babama verdiğin nimetlere şükretmeye ve razı olacağın salih ameller işlemeye sevk et ve beni rahmetinle salih kullarının arasına kat!”');
INSERT INTO verses (sura, aya, text) VALUES (27, 20, 'Kuşları denetledi ve: "Neden Hüdhüd''ü göremiyorum? Yoksa kayıplardan mı oldu? dedi.');
INSERT INTO verses (sura, aya, text) VALUES (27, 21, '“Bana (mazeretini gösteren) apaçık bir delil getirmedikçe kesinlikle onu ağır bir şekilde cezalandıracağım ya da keseceğim.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 22, 'Derken hüdhüd çok geçmeden geldi ve (Süleyman’a) şöyle dedi: “Senin bilmediğin bir şey öğrendim. Sebe’den sana sağlam bir haber getirdim.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 23, 'Ben, onlara hükmeden, kendisine her şeyden (bolca) verilmiş ve büyük bir tahtı olan bir kadın buldum.');
INSERT INTO verses (sura, aya, text) VALUES (27, 24, '"Onu ve kavmini Allah’tan başka Güneşe secde eder buldum. Şeytan onlara amellerini süslü göstermiş ve onları doğru yoldan alıkoymuş. Onun için onlar doğru yola gelemiyorlar."');
INSERT INTO verses (sura, aya, text) VALUES (27, 25, '“Göklerde ve yerde gizli olanı ortaya çıkaran, sizin gizlediğiniz ve açığa vurduğunuz şeyleri bilen Allah’a secde etmesinler diye (Şeytan onları yoldan çıkarmış.)”');
INSERT INTO verses (sura, aya, text) VALUES (27, 26, '“Allah odur ki, ondan başka (hak) ilâh yoktur. Azîm olan Arş’ın Rabbidir.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 27, 'Süleyman, Hüdhüd''e şöyle dedi: “Doğru mu söylüyorsun, yoksa yalancılardan mısın, göreceğiz.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 28, '"Şu mektubumu götür, onlara at, sonra da onlardan bir tarafa çekil; böylelikle bir bakıver, neye başvuracaklar?"');
INSERT INTO verses (sura, aya, text) VALUES (27, 29, 'Sebe kraliçesi Belkıs dedi ki: “Ey ileri gelenler! Bana çok önemli bir mektup bırakıldı.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 30, 'O; Süleyman’dan, Rahman ve Rahim olan Allah’ın adıyla (başlıyor).');
INSERT INTO verses (sura, aya, text) VALUES (27, 31, '"Bana baş kaldırmayın, teslimiyet gösterip bana gelin." diye (yazmaktadır).');
INSERT INTO verses (sura, aya, text) VALUES (27, 32, '“Ey ileri gelenler! Durumum hakkında bana görüş bildirin. Sizler yanımda bulunmadıkça hiçbir işe kesin olarak karar vermem.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 33, 'Dediler ki: "Biz güçlü ve çetin savaşçı kimseleriz. Emir ise senindir. Artık neyi emredeceğine bak."');
INSERT INTO verses (sura, aya, text) VALUES (27, 34, '"Şüphesiz hükümdarlar bir şehre girdiklerinde onu harap ederler. Ahalisinin şereflilerini zelil kılarlar. Gerçekten de onlar böyle yaparlar."');
INSERT INTO verses (sura, aya, text) VALUES (27, 35, '“Ben onlara bir hediye gönderip, elçilerin ne haber ile döneceklerine bakacağım.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 36, '"(Elçi) Süleyman''a geldiğinde (Süleyman ona) şöyle dedi: "Bana mal ile yardım mı etmek istiyorsunuz? Allah''ın bana verdiği size verdiğinden daha hayırlıdır. Belki kendi hediyenizle siz sevinirsiniz."');
INSERT INTO verses (sura, aya, text) VALUES (27, 37, '“Dön onlara! Andolsun üzerlerine karşı duramayacakları ordularla geleceğiz ve onları –andolsun- oradan zelil ve küçük düşmüşler olarak çıkartacağız.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 38, 'Süleyman: “Ey ileri gelenler! Onlar bana teslim olmadan önce hanginiz bana onun (kraliçenin) tahtını getirebilir?”');
INSERT INTO verses (sura, aya, text) VALUES (27, 39, 'Cinlerden bir ifrit; ”Sen yerinden kalkmadan ben onu sana getiririm ve şüphesiz ben, buna güç yetirecek güvenilir biriyim.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (27, 40, 'Kitaptan bilgisi olan biri; “Ben onu, gözünü kapayıp açmadan önce sana getiririm.” dedi. Süleyman, tahtı yanında yerleşmiş hâlde görünce şöyle dedi: “Bu, şükür mü yoksa nankörlük mü edeceğim diye beni sınamak için, Rabbimin bana bir lütfudur. Kim şükrederse ancak kendisi için şükretmiş olur. Kim de nankörlük ederse (bilsin ki) Rabbim Ğanîdir, Kerîmdir.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 41, 'Dedi ki: “Onun tahtını değişikliğe uğratın, bir bakalım (kendi tahtı olduğunu) bulabilecek mi, yoksa bulamayanlardan mı olacak?”');
INSERT INTO verses (sura, aya, text) VALUES (27, 42, 'Belkıs gelince; “Senin tahtın böyle mi?” denildi. “O da: “Sanki bu odur” bize bundan önce ilim verilmiş olup, biz teslim olanlardan olmuştuk.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (27, 43, '"Daha önce Allah’tan başka ibadet ettiği şeyler ona engel olmuştu. Çünkü o kâfir bir kavimden idi."');
INSERT INTO verses (sura, aya, text) VALUES (27, 44, 'Ona; “Köşke gir!” denildi. Köşkü görünce onu (zeminini) derin bir su sandı ve eteklerini topladı. Süleyman ona; “Bu, (zemini) billurdan döşenmiş bir köşktür.” dedi. Belkıs: “Ey Rabbim! Şüphesiz ben nefsime zulmetmiştim. Şimdi ise Süleyman ile birlikte âlemlerin Rabbi olan Allah’a teslim oldum.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (27, 45, 'Andolsun biz, “Allah’a ibadet edin!” diye (uyarması için) Semûd kavmine, kardeşleri Salih’i, peygamber olarak göndermiştik. Bir de ne görsün?Onlar birbiriyle çekişen iki grup olmuşlar.');
INSERT INTO verses (sura, aya, text) VALUES (27, 46, 'Dedi ki: “Kavmim, iyilikten önce ne diye kötülüğün çabuk gelmesini istersiniz?Allah’tan mağfiret dilemelisiniz değil mi? Belki size merhamet olunur.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 47, 'Dediler ki: “Sen ve sana uyanlar bize uğursuzluk getirdiniz.” Dedi ki: Sizin uğursuzluğunuz Allah nezdindedir. Aslında siz imtihan edilmekte olan bir kavimsiniz.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (27, 48, 'O şehirde yeryüzünde bozgunculuk yapan fakat ıslah etmeyen dokuz kişi vardı.');
INSERT INTO verses (sura, aya, text) VALUES (27, 49, 'Onlar kendi aralarında Allah adına yemin ederek dediler ki: “Ona ve aile halkına gece baskın yapalım. Sonra da velisine: Biz aile halkının helak edildikleri yere bile tanık olmadık. Biz gerçekten doğru söyleyenlerdeniz, diyelim.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 50, 'Onlar tuzak kurdular. Biz de –onlar fark etmeksizin- bir tuzak kurduk.');
INSERT INTO verses (sura, aya, text) VALUES (27, 51, 'Bak, onların tuzaklarının sonucu nasıl oldu. Biz, onları ve kavimlerini topyekûn helâk ettik.');
INSERT INTO verses (sura, aya, text) VALUES (27, 52, 'İşte zulümleri yüzünden harabeye dönmüş evleri! Şüphesiz bunda bilen bir kavim için ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (27, 53, 'İman edip Allah’a karşı gelmekten sakınmakta olanları ise kurtardık.');
INSERT INTO verses (sura, aya, text) VALUES (27, 54, 'Lût''u da (an). Hani o kavmine şöyle demişti: "Siz göre göre bu çirkin kötülüğü yapıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (27, 55, '“Siz kadınları bırakıp şehvetle erkeklere mi yanaşıyorsunuz? Doğrusu siz cahillik eden bir kavimsiniz.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 56, 'Kavminin cevabı, ancak şöyle demek oldu: "Lût ailesini memleketinizden çıkarın. Çünkü onlar pek temiz kalan insanlardır."');
INSERT INTO verses (sura, aya, text) VALUES (27, 57, 'O’nu ve ailesini kurtardık. Yalnız, geride kalanlardan olmasını takdir ettiğimiz karısı hariç.');
INSERT INTO verses (sura, aya, text) VALUES (27, 58, 'Üzerlerine de bir yağmur yağdırdık. Uyarılanların yağmuru ne kötü.');
INSERT INTO verses (sura, aya, text) VALUES (27, 59, 'De ki: “Allah’a hamdolsun ve selam olsun seçkin kullarına. Allah mı hayırlıdır; yoksa onların ortak koştukları mı?”');
INSERT INTO verses (sura, aya, text) VALUES (27, 60, '(Ortak koştuklarınız mı hayırlı) Yoksa gökleri ve yeri yaratan, size gökten su indiren (Allah) mı? Onunla sizin bir ağacını bile bitiremeyeceğiniz güzel görünüşlü bahçeler bitirdik. Allah ile birlikte bir ilah mı var? Hayır, onlar yoldan sapan bir topluluktur.');
INSERT INTO verses (sura, aya, text) VALUES (27, 61, '(Ortak koştuklarınız mı hayırlı) Yoksa yeryüzünü yerleşim yeri yapan, aralarında ırmaklar akıtan, orada sabit dağlar yerleştiren, iki deniz arasına engel koyan (Allah) mı? Allah ile birlikte başka bir ilah mı var? Hayır! Onların çoğu bilmiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (27, 62, '(Ortak koştuklarınız mı hayırlı) Yoksa darda kalana kendisine dua ettiği zaman icabet eden, sıkıntıyı gideren ve sizi yeryüzünün halifeleri kılan mı? Allah ile birlikte başka bir ilah mı var? Ne kadar da az düşünüyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (27, 63, '(Ortak koştuklarınız mı hayırlı) Yoksa karanın ve denizin karanlıkları içinde size yol gösteren, rüzgârları rahmetinin öncesinde müjdeleyici olarak gönderen mi? Allah ile birlikte başka bir ilah mı var? Ne kadar da az düşünüyorsunuz. Allah, sizin şirk koştuklarınızdan çok münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 64, '(Onlar mı hayırlı) Yoksa, yaratılışı başlatan, sonra onu yaratmayı tekrar eden ve size gökten ve yerden rızık veren mi? Allah ile birlikte başka bir ilah mı var? De ki: “Eğer doğru söyleyenler iseniz haydi delilinizi getirin.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 65, 'Yine de ki: Göklerde ve yerde Allah’tan başka hiç kimse gaybı bilemez. Ve onlar, ne zaman diriltileceklerini de bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 66, 'Hayır, onların ahiret hakkındaki bilgileri yetersiz kalmıştır. Dahası, bu hususta şüphe içindedirler. Bunun da ötesinde, onlar ahiretten yana kördürler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 67, 'Kâfirler: "Biz ve atalarımız, toprak olduktan sonra (mezarlarımızdan) mı çıkarılacağız?" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 68, 'And olsun, bize de, daha önceki atalarımıza da bu vadedilmişti. Ama bu, öncekilerin masallarından başka birşey değildir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 69, 'De ki: “Yeryüzünde gezip, günahkârların sonunun nasıl olduğunu bir görün.”');
INSERT INTO verses (sura, aya, text) VALUES (27, 70, 'Onlar için üzülme, kurdukları tuzaklardan da sıkıntıya düşme!');
INSERT INTO verses (sura, aya, text) VALUES (27, 71, '"Eğer, doğru söylüyorsanız bu vaat/tehdit ne zaman?" derler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 72, 'De ki: "(Kim bilir?) Belki de çabucak istemekte olduğunuzun (azabın) bir kısmı size pek de yakındır!"');
INSERT INTO verses (sura, aya, text) VALUES (27, 73, 'Şüphesiz Rabbin, insanlara karşı lütuf sahibidir. Fakat, onların çoğu şükretmezler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 74, 'Şüphesiz Rabbin, onların içlerinde gizlediklerini de, açığa vurduklarını da elbette bilir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 75, 'Gökte ve yerde gizli hiçbir şey yoktur ki apaçık bir kitapta olmasın.');
INSERT INTO verses (sura, aya, text) VALUES (27, 76, 'Doğrusu bu Kur''an İsrailoğullarına hakkında ayrılığa düştüklerinin çoğunu anlatmaktadır.');
INSERT INTO verses (sura, aya, text) VALUES (27, 77, 'Ve o, Müminler için bir hidayet ve rahmettir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 78, 'Şüphesiz Rabbin, onların arasında hükmünü verecektir. O çok güçlüdür, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 79, 'Sen artık Allah''a tevekkül et. Şüphesiz sen apaçık olan hak üzeresin.');
INSERT INTO verses (sura, aya, text) VALUES (27, 80, 'Sen, ölülere duyuramazsın, arkalarını dönüp gitmekte olan sağırlara da daveti duyuramazsın.');
INSERT INTO verses (sura, aya, text) VALUES (27, 81, 'Sen, körleri sapıklıklarından doğru yola hidayet edici de değilsin. Ancak ayetlerimize iman edenlere duyurabilirsin. Onlar teslim olan kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (27, 82, 'O söz başlarına gelip çattığı zaman, yerden bir dabbe (canlı bir yaratık) çıkarırız da onlara konuşarak, insanların ayetlerimize kesin olarak iman etmediklerini söyler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 83, 'O gün her ümmetten, ayetlerimizi yalanlayanlardan bir grubu toplarız. Onlar toplu olarak (hesap yerine) sevkedilirler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 84, 'Nihayet geldikleri zaman: "Ayetlerimi iyice kavramadığınız halde yalanladınız mı? Yoksa ne yapıyordunuz?" der.');
INSERT INTO verses (sura, aya, text) VALUES (27, 85, 'Zulmetmelerinden dolayı aleyhlerinde söz (azap) gerçekleşmiş olur ve onlar artık konuşamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (27, 86, 'Bizim geceyi o vakitte dinlensinler diye yarattığımızı, gündüzü de aydınlık kıldığımızı görmediler mi? İşte bunda iman eden bir toplum için ayetler/deliller vardır.');
INSERT INTO verses (sura, aya, text) VALUES (27, 87, 'Sur''a üflendiği gün Allah''ın diledikleri dışında göklerde ve yerde kim varsa korkuya kapılır. Hepsi boyun bükmüş olarak O''na gelirler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 88, 'Dağları görürsün de yerlerinde durduğunu sanırsın. Oysa onlar bulutlar gibi geçip giderler. Bu, her şeyi sapasağlam/noksansız yapan Allah’ın işidir. Muhakkak O, yaptıklarınızdan haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (27, 89, 'Kim iyilik getirirse ona ondan daha hayırlısı vardır. Ve onlar o gün, korkudan güvendedirler.');
INSERT INTO verses (sura, aya, text) VALUES (27, 90, 'Kim de kötülük getirirse onlar, yüz üstü Cehennem''e atılır. Yapmış olduklarınızdan başka bir şeyle mi karşılık göreceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (27, 91, '(De ki:) "Ben ancak, haram kıldığı bu şehrin Rabbine ibadet etmekle emrolundum. Her şey O’nundur. Müslümanlardan olmakla emrolundum."');
INSERT INTO verses (sura, aya, text) VALUES (27, 92, 'Ve Kur''an''ı okumam da (emrolundu). Kim hidayet bulursa ancak kendi lehine hidayet bulur. Kim de sapıklığa düşerse De ki: “Ben ancak uyarıcılardanım."');
INSERT INTO verses (sura, aya, text) VALUES (27, 93, 'Ve de ki: "Hamt Allah’a aittir. O, size ayetlerini gösterecek; siz de onları bilip tanıyacaksınız. Rabbin, yaptıklarınızdan gafil değildir."');
INSERT INTO verses (sura, aya, text) VALUES (28, 1, 'Tâ, Sîn, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (28, 2, 'Bunlar apaçık kitabın ayetleridir.');
INSERT INTO verses (sura, aya, text) VALUES (28, 3, 'İman eden bir toplum için, Mûsâ ve Firavun''un haberlerinden bir kısmını sana hak olarak okuyacağız.');
INSERT INTO verses (sura, aya, text) VALUES (28, 4, 'Firavun, yeryüzünde üstünlük/büyüklük taslayıp, oranın halkını fırkalara/gruplara ayırdı. Onlardan bir grubu zayıf ve güçsüz bırakıyor, erkek çocuklarını boğazlıyor, kadınlarını sağ bırakıyordu. Çünkü o, bozgunculardan idi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 5, 'Biz ise, ülkede güçsüz bırakılanlara ihsanda bulunmak ve onları önderler yapmak ve onları (oraya) mirasçı kılmak istiyorduk.');
INSERT INTO verses (sura, aya, text) VALUES (28, 6, 'Onları ülkede güç sahibi kılmak, Firavun ile Hâmân''a ve ordularına, onlardan (İsrailoğulları''ndan gelecek diye) korktukları şeyi göstermek (istiyorduk).');
INSERT INTO verses (sura, aya, text) VALUES (28, 7, 'Mûsâ’nın anasına: ‘Onu emzir, onun adına bir tehlikeden korkarsan onu hemen denize bırak. Korkma ve üzülme. Şüphesiz biz onu sana döndürecek ve onu peygamberlerden kılacağız’ diye ilham ettik.');
INSERT INTO verses (sura, aya, text) VALUES (28, 8, 'Firavun hanedanı onu bulup aldılar. Sonunda onlara düşman ve başlarına dert olacaktı. Çünkü Firavun, Hâmân ve orduları suçlu idiler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 9, 'Firavun’un karısı: "Benim ve senin için göz aydınlığıdır! Onu öldürmeyin, belki bize faydası dokunur ya da onu evlat ediniriz." dedi. Oysa onlar farkında değillerdi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 10, 'Mûsâ’nın annesi kalbi bomboş olarak sabah etti. Eğer biz, (vaadimize) iman edenlerden olması için onun kalbini pekiştirmemiş olsaydık, neredeyse işi açığa vuracaktı.');
INSERT INTO verses (sura, aya, text) VALUES (28, 11, '(Annesi) Mûsâ’nın kız kardeşine; “Onu takip et!” dedi. O da uzaktan gözetledi. Onlar ise farkında değillerdi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 12, 'Biz daha önceden (annesine geri verilinceye kadar) ona sütanalarını haram etmiştik. Bunun üzerine (kız kardeşi) dedi ki: “Sizin için ona bakacak, hem de ona iyilikte bulunacak bir aile göstereyim mi?”');
INSERT INTO verses (sura, aya, text) VALUES (28, 13, 'Böylece onu; gözü aydın olsun, üzülmesin ve Allah’ın vaadinin hak olduğunu bilsin diye annesine geri döndürdük. Fakat, onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 14, 'Mûsâ kemal/olgunluk çağına ulaşınca ona, hüküm ve ilim verdik. İyileri işte böyle ödüllendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (28, 15, 'O halkın haberi olmadığı bir sırada şehre girdi ve kavga eden iki adam gördü. Birisi kendi tarafından, diğeri düşmanlarından idi. Kendi tarafından olan, düşmanına karşı yardım istedi. Mûsâ da ona bir yumruk vurdu, adamı öldürdü. Bu, Şeytan''ın işindendir. O, apaçık yoldan saptıran bir düşmandır, dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 16, '"Rabbim! Ben kendime zulmettim, beni bağışla!" dedi. Allah da onu bağışladı. Nitekim O, çokça bağışlayandır, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (28, 17, '“Rabbim! Bana verdiğin nimetle, artık asla günahkârlara destek olmayacağım.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 18, 'Şehirde korku içinde, etrafı gözetleyerek sabahladı. Bir de ne görsün; dün kendisinden yardım isteyen adam yine feryat edip yardım istiyordu. Mûsâ ona: "Sen, besbelli azgının/sapkının birisin." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 19, 'Mûsâ, ikisinin de düşmanı olan kimseyi tutup yakalamak isteyince: "Ey Mûsâ! Dün birisini öldürdüğün gibi beni de öldürmek mi istiyorsun?" dedi. "Sen, ıslah edenlerden olmayı değil, ülkede bir zorba olmayı istiyorsun." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 20, 'Şehrin öteki ucundan bir adam koşarak geldi: "Mûsâ!" dedi. "İleri gelenler seni öldürmek için hakkında görüşüyorlar. Hemen çık git! Ben, senin (iyiliğin) için nasihat edenlerdenim."');
INSERT INTO verses (sura, aya, text) VALUES (28, 21, 'Bunun üzerine korku içinde etrafını gözetleyerek oradan çıkıp gitti. "Rabbim!" dedi. "Beni zalim kavimden kurtar."');
INSERT INTO verses (sura, aya, text) VALUES (28, 22, 'Medyen’e doğru yönelince: “Umarım Rabbim beni doğru yola iletir” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 23, 'Medyen suyuna varınca üst tarafında (davarlarını) sulayan bir grup insan buldu. Onların berisinde ise karışmasın diye (koyunlarını) kollayan iki hanım buldu. “Haliniz nedir” dedi. “Çobanlar gidinceye kadar biz sulamayız. Babamız ise çok yaşlı bir ihtiyardır” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 24, 'Bunun üzerine Mûsâ, onların (davarlarını) sulayıp bir gölgeye çekilerek: “Rabbim doğrusu bana indireceğin hayra muhtacım” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 25, 'İki kadından biri utana utana Mûsâ’nın yanına gelerek: “Babam bizim hayvanlarımızı sulamana karşılık ücret vermek için seni çağırıyor.” dedi. Mûsâ -aleyhisselam- onun yanına varınca başından geçen olayları anlattı. O da: “Artık korkma, o zalim kavimden kurtuldun.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 26, 'İkisinden biri dedi ki: “Babacığım onu ücretle tut. Çünkü senin ücretle tuttuklarının en iyisi kudretli ve emin bir kişidir.”');
INSERT INTO verses (sura, aya, text) VALUES (28, 27, '“Ben, sekiz yıl bana ücretle çalışman karşılığında şu iki kızımdan birini sana nikâhlamak istiyorum. Eğer bunu on yıla tamamlarsan da, bu sendendir. Sana zorluk çıkarmak istemem. İnşallah beni, salih kimselerden bulacaksın.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 28, '(Mûsâ) "Bu (sekiz ya da on sene), benimle senin arandadır. Bu iki süreden hangisini yerine getirirsem, bana bir haksızlık edilmesin. Allah, söylediklerimize vekildir." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 29, 'Mûsâ süreyi tamamlayıp ailesi ile yola çıkınca Tûr’un yan tarafından bir ateş gördü. Ailesine: Siz durun, çünkü ben bir ateş gördüm. Belki ateşten size bir haber yahut ısınmanız için size ateşten bir parça getiririm, dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 30, 'Oraya varınca o mübarek yerdeki vadinin sağ kıyısından o ağaçtan ona şöyle seslenildi: “Ey Mûsâ, muhakkak ben âlemlerin Rabbi olan Allah’ım.');
INSERT INTO verses (sura, aya, text) VALUES (28, 31, '“Ve asanı da yere bırak.” Onu ufak bir yılan gibi hareket ediyor görünce arkasına bakmadan dönüp kaçtı. Ey Mûsâ, geri gel ve korkma, çünkü sen güven altında olanlardansın.');
INSERT INTO verses (sura, aya, text) VALUES (28, 32, 'Elini koynuna sok, kusursuz bembeyaz çıksın. Korkudan dolayı kollarını kendine çek ki (korkun gitsin.) İşte bunlar, Firavun ve çevresine karşı Rabbinin iki delilidir. Onlar, fasık bir toplumdur.');
INSERT INTO verses (sura, aya, text) VALUES (28, 33, '“Rabbim! Ben onlardan bir kişiyi öldürdüm. Bu yüzden beni öldürmelerinden korkuyorum.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 34, '"Kardeşim Hârûn’un dili benden daha açıktır. Onu da benimle gönder, bana destek olsun ve beni tasdik etsin. Çünkü ben, onların beni yalanlamalarından korkuyorum.''''');
INSERT INTO verses (sura, aya, text) VALUES (28, 35, 'Buyurdu ki: “Gücünü kardeşinle pekiştireceğiz ve size öyle bir güç vereceğiz ki ayetlerimiz sayesinde size ulaşamayacaklar. Siz ve size uyanlar galiplersiniz.”');
INSERT INTO verses (sura, aya, text) VALUES (28, 36, 'Mûsâ onlara apaçık ayetlerimizle gelince dediler ki: “Bu ancak düzmece bir büyüdür. Biz önceki atalarımız arasında da böylesini işitmemişiz.”');
INSERT INTO verses (sura, aya, text) VALUES (28, 37, 'Mûsâ dedi ki: “Rabbim kimin nezdinden hidayet geldiğini ve yurdun akıbetinin de kimin olacağını bilir. Doğrusu zulmedenler kurtulamazlar.”');
INSERT INTO verses (sura, aya, text) VALUES (28, 38, 'Firavun da: "Ey ileri gelenler! Sizin için benden başka ilah tanımıyorum. Ey Hâman! Çamur üzerine benim için bir ateş yak ve bana bir kule yap. Belki Mûsâ’nın ilahına ulaşabilirim. Çünkü ben onun yalancılardan olduğunu sanıyorum." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 39, 'Firavun ve askerleri, bize döndürülmeyeceklerini sanarak yeryüzünde haksız yere büyüklük tasladılar.');
INSERT INTO verses (sura, aya, text) VALUES (28, 40, 'Bu sebeple biz de onu ve askerlerini yakalayıp denize atıverdik. Zalimlerin sonunun nasıl olduğuna bir bak.');
INSERT INTO verses (sura, aya, text) VALUES (28, 41, 'Biz onları, ateşe çağıran öncüler kıldık. Kıyamet günü de kendilerine yardım edilmeyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (28, 42, 'Bu dünyada da peşlerine lanet taktık. Kıyamet günü de onlar, kötülenmiş/uzaklaştırılmış kimselerden olacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (28, 43, 'Şüphesiz önceki nesilleri helâk ettikten sonra, belki hatırlayıp öğüt alırlar diye Mûsâ''ya, insanlar için basiretler, hidayet ve rahmet olmak üzere kitap verdik.');
INSERT INTO verses (sura, aya, text) VALUES (28, 44, 'Mûsâ’ya emir verdiğimizde sen, Tûr Dağı''nın batı tarafında bulunmuyordun. Sen buna şahit olanlardan da değildin.');
INSERT INTO verses (sura, aya, text) VALUES (28, 45, 'Fakat biz (Mûsâ’dan sonra) birçok nesiller meydana getirdik. Üzerlerinden uzun zaman geçti. Sen Medyen halkı arasında yaşıyor değildin, ayetlerimizi onlardan okuyup öğreniyor da değildin. Fakat (seni peygamber olarak) gönderenler gerçekten bizleriz.');
INSERT INTO verses (sura, aya, text) VALUES (28, 46, 'Biz, Mûsâ''ya seslendiğimiz zamanda sen Tûr Dağı''nın yanında değildin. Fakat bu, kendilerine senden önce bir uyarıcı gelmemiş olan bir toplumu belki düşünürler diye uyarman için Rabbinden bir rahmettir.');
INSERT INTO verses (sura, aya, text) VALUES (28, 47, 'Kendi elleriyle yaptıklarından dolayı başlarına bir musibet geldiğinde: “Rabbimiz, bize bir peygamber gönderseydin de senin ayetlerine tâbi olup Müminlerden olsaydık.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 48, 'Onlara katımızdan hak gelince, “Mûsâ''ya verilen mucizelerin benzeri niçin buna da verilmedi?” dediler. Onlar daha önce Mûsâ’ya verilen mucizeleri inkâr etmemişler miydi? Onlar: “İki sihirbaz birbirlerine destek oluyor.” dediler. “Doğrusu biz hepsini (inkâr edici) kâfirleriz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 49, 'De ki: "Eğer doğrulardan iseniz, Allah katından bu iki kitaptan daha doğru bir kitap getirin de, ben de ona tabi olayım."');
INSERT INTO verses (sura, aya, text) VALUES (28, 50, 'Eğer sana cevap veremezlerse, bil ki onlar ancak arzularına tabi oluyorlar. Allah''tan bir hidayet olmaksızın kendi hevesine/arzusuna uyandan daha sapık kim olabilir? Şüphesiz Allah, zalim topluma hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (28, 51, 'Andolsun, düşünüp öğüt alsınlar diye o sözü (Kur’an ayetlerini) onlara peş peşe ulaştırdık.');
INSERT INTO verses (sura, aya, text) VALUES (28, 52, 'Daha önce kendilerine kitap verdiklerimiz, buna da (Kur''an''a) iman ederler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 53, 'Onlara okunduğu zaman derler ki: "Ona iman ettik. Şüphesiz o, Rabbimizden gelen haktır. Şüphesiz biz, bundan öncede Müslümandık."');
INSERT INTO verses (sura, aya, text) VALUES (28, 54, 'İşte onlar; sabrettikleri şeylerden ötürü, iki defa mükâfatlandırılırlar, kötülüğü iyilikle savarlar ve kendilerine verdiğimiz rızıklardan da infak ederler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 55, 'Onlar, boş söz işittiklerinde ondan yüz çevirir: “Bizim yaptıklarımız bize, sizin yaptıklarınız ise sizedir. Size selam olsun! Biz cahilleri (dost olarak) istemeyiz.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 56, 'Şüphesiz sen, sevdiklerine hidayet edemezsin. Fakat Allah, dilediğine hidayet eder. Hidayete erecek olanları en iyi O bilir.');
INSERT INTO verses (sura, aya, text) VALUES (28, 57, '"Eğer seninle birlikte doğru yolu tutacak olursak, kendi yurdumuzdan çekilip çıkarılırız." dediler. Oysa biz onları, kendi katımızdan bir rızık olarak her şeyin ürünlerinin toplanıp getirildiği; emin, harem kıldığımız bir yere (Mekke''ye) yerleştirmedik mi? Fakat onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 58, 'Biz geçimlerinde şımarmış nice ülkeleri helâk ettik. İşte onlardan sonra –çok kısa bir süre dışında- kimsenin oturmadığı meskenleri. Mirasçı olanlar biz olduk biz.');
INSERT INTO verses (sura, aya, text) VALUES (28, 59, 'Rabbin, kendilerine ayetlerimizi okuyan bir rasûlü memleketlerin anasına (Mekke''ye) göndermedikçe, o memleketleri helâk edici değildir. Biz, halkı zalim olan beldelerden başkasını helâk edici değiliz.');
INSERT INTO verses (sura, aya, text) VALUES (28, 60, 'Size verilen her şey dünya hayatının geçimliği ve süsüdür. Allah’ın yanında olanlar ise daha iyi ve kalıcıdır. Hala düşünmez misiniz?');
INSERT INTO verses (sura, aya, text) VALUES (28, 61, 'Kendisine güzel bir vaadde bulunduğumuz ve dolayısıyla ona kavuşan kimse, kendisini dünya hayatının geçimliğinden yararlandırdığımız sonra kıyamet günü (azaba atılmak üzere) getirileceklerden olanla bir midir?');
INSERT INTO verses (sura, aya, text) VALUES (28, 62, 'O gün, onlara seslenerek: “İddia ettiğiniz ortaklarım hani nerede?” der.');
INSERT INTO verses (sura, aya, text) VALUES (28, 63, 'Haklarında azap sözü gerçekleşmiş olanlar; “Rabbimiz! İşte azdırdıklarımız onlardır. Kendimiz azdığımız gibi, onları da azdırdık. Şimdi ise onlardan uzaklaşarak sana geldik. Zaten onlar, bize de ibadet etmiyorlardı.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (28, 64, '"Ortaklarınızı çağırın." denir. Onları çağırırlar. Fakat onlara cevap veremezler ve azabı görürler. Ne olurdu (dünyada) hidayete girselerdi!');
INSERT INTO verses (sura, aya, text) VALUES (28, 65, 'O gün Allah, onlara seslenerek: “Peygamberlere ne cevap verdiniz?” der.');
INSERT INTO verses (sura, aya, text) VALUES (28, 66, 'O gün (onları azaptan kurtaracak) haberler/mazeretler onlara kapanacaktır. Birbirlerine bir şey de soramayacaklar.');
INSERT INTO verses (sura, aya, text) VALUES (28, 67, 'Tevbe ederek iman eden ve salih amel işleyen kimseye gelince, umulur ki o kurtuluşa erenlerden olur.');
INSERT INTO verses (sura, aya, text) VALUES (28, 68, 'Rabbin, dilediğini yaratır ve dilediğini de seçer. Onların ise seçme hakkı yoktur. Allah, onların ortak koştuklarından münezzeh ve yüksektedir/yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (28, 69, 'Şüphesiz Rabbin; onların içlerinde gizlediklerini de, açığa vurduklarını da bilir.');
INSERT INTO verses (sura, aya, text) VALUES (28, 70, 'O, kendisinden başka (hak) ilah olmayan Allah’tır. Dünyada da ahirette de hamt O''na mahsustur. Hüküm de O''nundur ve nihayetinde O''na döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (28, 71, 'De ki: "Allah, kıyamet gününe kadar geceyi üzerinizde devamlı kılsaydı; Allah’tan başka size bir ışık getirecek ilah kimdir? Hâlâ işitmeyecek misiniz?"');
INSERT INTO verses (sura, aya, text) VALUES (28, 72, 'De ki: "Allah, kıyamet gününe kadar gündüzü üzerinizde devamlı kılsaydı; Allah’tan başka, size dinleneceğiniz bir geceyi getirecek ilah kimdir? Hâlâ görmüyor musunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (28, 73, 'Geceyi ve gündüzü sizin için onda sükûn bulasınız ve lütfundan arayısınız diye yaratmış olması onun rahmetindendir. Olur ki şükredersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (28, 74, 'O gün, onlara seslenerek: “İddia ettiğiniz ortaklarım nerede?” der.');
INSERT INTO verses (sura, aya, text) VALUES (28, 75, 'Her toplumdan bir şahit çıkarırız ve: "Haydi! Delillerinizi getirin!" deriz. İşte o zaman hakikatin Allah’a ait olduğunu bilirler. Uydurmuş oldukları şeyler onlardan kaybolup gider.');
INSERT INTO verses (sura, aya, text) VALUES (28, 76, 'Gerçekte Kârûn Mûsâ ’nın kavminden idi, fakat onlara karşı azgınlık etti. Biz ona öyle hazineler vermiştik ki, onların anahtarları(nı taşımak) dahi güç sahibi bir topluluğa ağır gelirdi. Hani Kavmi ona şöyle demişti: "Şımarma/böbürlenme! Çünkü Allah, şımarıkları/böbürlenenleri sevmez."');
INSERT INTO verses (sura, aya, text) VALUES (28, 77, 'Allah’ın sana verdikleriyle ahiret yurdunu kazanmayı arzula. Fakat dünyadaki nasibini de unutma. Allah sana nasıl ihsanda bulunduysa, sen de başkalarına ihsanda bulun. Sakın yeryüzünde fesat çıkarmaya kalkışma! Çünkü Allah, bozguncuları sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (28, 78, 'O da: “Kuşkusuz bunlar bana, sahip olduğum bilgim sayesinde verilmiştir.” dedi. Allah’ın, ondan daha önce kendisinden daha güçlü ve daha çok biriktirmiş olan nice nesilleri helâk ettiğini bilmiyor mu? Günahkârlara suçları sorulmaz.');
INSERT INTO verses (sura, aya, text) VALUES (28, 79, 'Kavminin karşısına süslü takılarıyla çıkmıştı. Dünya hayatını isteyenler: "Keşke Kârûn’a verilen gibi bize de verilseydi. O, gerçekten büyük bir pay sahibidir." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 80, 'Kendilerine ilim verilenler ise: "Yazıklar olsun size! İman eden ve salih amel işleyenler için Allah’ın sevabı çok daha hayırlıdır. Ona da ancak sabredenler kavuşur." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 81, 'Sonunda onu da, sarayını da yerin dibine geçirdik. Artık Allah''a karşı ona yardım edecek bir topluluğu olmadı, kendi kendine yardım edebileceklerden de değildi.');
INSERT INTO verses (sura, aya, text) VALUES (28, 82, 'Daha dün onun yerinde olmayı arzu edenler; “Vay! Demek ki Allah, kullarından dilediği kimselere rızkı bol verir ve (dilediğine) kısarmış. Allah, bize lütfetmiş olmasaydı, bizi de yerin dibine geçirirdi. Demek ki kâfirler iflah olmayacak.” demeye başladılar.');
INSERT INTO verses (sura, aya, text) VALUES (28, 83, 'İşte ahiret yurdu. Biz, onu yeryüzünde büyüklük taslamayan ve bozgunculuk çıkarmayanlara has kılarız. Sonuç, Allah’a karşı gelmekten sakınanlarındır.');
INSERT INTO verses (sura, aya, text) VALUES (28, 84, 'Kim bir iyilik getirirse, ona bundan daha hayırlısı vardır. Kim de bir kötülük getirirse; bilsin ki kötülük işleyenler ancak yapmakta olduklarının cezasına çarptırılırlar.');
INSERT INTO verses (sura, aya, text) VALUES (28, 85, 'Kur’an’ı sana farz kılan Allah, şüphesiz seni dönülecek bir yere döndürecektir. De ki: “Rabbim hidayetle geleni ve apaçık bir sapıklık içinde olanı daha iyi bilir.”');
INSERT INTO verses (sura, aya, text) VALUES (28, 86, 'Sen, bu kitabın sana verileceğini ummuyordun. Ancak o, Rabbinden bir rahmet olarak sana verildi. Öyle ise kâfirlere sakın arka çıkma.');
INSERT INTO verses (sura, aya, text) VALUES (28, 87, 'Sana indirildikten sonra, sakın seni Allah''ın ayetlerinden alıkoymasınlar. Sen Rabbine çağır ve sakın müşriklerden olma.');
INSERT INTO verses (sura, aya, text) VALUES (28, 88, 'Sen Allah ile beraber başka bir ilâha ibadet etme. O’ndan başka hiçbir (hak) ilâh yoktur. O''nun yüzünden (zatından) başka her şey yok olacaktır. Hüküm O''nundur ve O''na döndürülürsünüz.');
INSERT INTO verses (sura, aya, text) VALUES (29, 1, 'Elif, Lâm, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (29, 2, 'İnsanlar; “İman ettik.” demekle, bir imtihana tabi tutulmadan bırakılacaklarını mı sanıyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (29, 3, 'Biz, onlardan öncekilerini de imtihan etmiştik. Allah; elbette doğru söyleyenleri de, yalan söyleyenleri de bilir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 4, 'Yoksa kötülük yapanlar bizden kaçabileceklerini mi/kurtulacaklarını mı sanıyorlar? Ne kötü hüküm veriyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (29, 5, 'Kim Allah’a kavuşmayı umarsa, şüphesiz Allah’ın belirlediği süre gelecektir. O her şeyi işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 6, 'Kim cihad ederse, yalnızca kendi nefsi için cihad etmiş olur. Şüphesiz Allah, âlemlerden müstağnidir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 7, 'İman edip salih amel işleyenlerin kötülüklerini elbette örteceğiz. Onları işlediklerinin daha güzeliyle mükâfatlandıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (29, 8, 'Biz insana ana babasına iyi davranmasını tavsiye (emr) ettik. Eğer onlar hakkında bilgin olmayan bir şeyi bana ortak koşman için seni zorlarlarsa onlara itaat etme. Dönüşünüz yalnız banadır, yaptıklarınızı size haber vereceğim.');
INSERT INTO verses (sura, aya, text) VALUES (29, 9, 'İman edip de salih amel işleyenler var ya, biz onları mutlaka salihler (iyiler) arasına sokacağız.');
INSERT INTO verses (sura, aya, text) VALUES (29, 10, 'İnsanlardan öyleleri vardır ki; “Allah’a iman ettik.” derler. Ama Allah uğrunda bir ezaya uğratılınca, insanlardan gördükleri baskı ve işkenceyi Allah’ın azabı gibi tutar. Andolsun, Rabbinden bir yardım gelecek olsa mutlaka; “Biz de sizinle beraberdik.” derler. Allah, herkesin kalbinde olanı en iyi bilen değil midir?');
INSERT INTO verses (sura, aya, text) VALUES (29, 11, 'Allah, elbette kendisine iman edenleri de bilir ve elbette münafıkları da bilir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 12, 'Kâfirler, iman edenlere; “Yolumuza uyun da sizin günahlarınızı yüklenelim.” derler. Hâlbuki onların günahlarından hiçbir şey yüklenecek değillerdir. Şüphesiz onlar kesinlikle yalancılardır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 13, 'Andolsun, onlar mutlaka kendi yüklerini ve kendi yükleriyle beraber nice ağır yükleri yükleneceklerdir. Uydurmakta oldukları şeylerden de kıyamet günü şüphesiz sorguya çekileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 14, 'Andolsun biz, Nûh’u kendi kavmine peygamber olarak gönderdik. O da dokuz yüz elli yıl onların arasında kaldı. Neticede onlar zulümlerini sürdürürlerken tûfan kendilerini yakalayıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (29, 15, 'Sonra onu ve gemide bulunanları kurtardık ve bunu âlemlere bir ibret kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (29, 16, 'İbrahim de hani kavmine şöyle demişti: "Allah’a ibadet edin ve O’ndan sakının! Eğer bilirseniz bu sizin için daha hayırlıdır."');
INSERT INTO verses (sura, aya, text) VALUES (29, 17, '“Siz, Allah’ı bırakarak ancak putlara tapıyorsunuz ve yalan uyduruyorsunuz. Allah’ı bırakarak taptıklarınızın size hiçbir rızık vermeye güçleri yetmez. Öyle ise rızkı Allah’ın katında arayın. O’na ibadet edin ve O’na şükredin. Siz yalnız O’na döndürüleceksiniz.”');
INSERT INTO verses (sura, aya, text) VALUES (29, 18, '“Eğer siz yalanlarsanız bilin ki, sizden önce geçen birtakım ümmetler de yalanlamışlardı. Peygambere düşen apaçık tebliğden başka bir şey değildir.”');
INSERT INTO verses (sura, aya, text) VALUES (29, 19, 'Allah''ın yaratmayı nasıl başlattığını sonra onu yeniden nasıl gerçekleştirdiğini görmediler mi? Şüphesiz bu, Allah''a göre kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 20, 'De ki: “Yeryüzünde gezip dolaşın da yaratmaya nasıl başladığına bir bakın. Bundan sonra Allah ahiret hayatını tekrar yaratacaktır çünkü Allah her şeye kadirdir.”');
INSERT INTO verses (sura, aya, text) VALUES (29, 21, 'O, dilediğine azap eder, dilediğine de merhamet eder. Yalnız O’na döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (29, 22, 'Siz, yerde de gökte de (Allah’ı) aciz bırakacak değilsiniz. Sizin Allah’tan başka ne bir dostunuz, ne de bir yardımcınız vardır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 23, 'Allah’ın ayetlerine ve O’na kavuşmaya (iman etmeyip) kâfir olanlar var ya; işte onlar benim rahmetimden ümit kesmişlerdir. İşte onlar için elem dolu bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 24, '(İbrahim’in) kavminin cevabı, “Onu öldürün veya yakın!” demekten başka bir şey olmadı. Allah onu ateşten kurtardı. Muhakkak bunda iman eden bir topluluk için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 25, 'İbrahim, onlara dedi ki: “Sırf aranızda dünya hayatına mahsus bir sevgi (ve çıkar) uğruna Allah’ı bırakıp birtakım putlar edindiniz. Sonra kıyamet gününde kiminiz kiminizi inkâr edip tanımayacak; kiminiz kiminize lânet edecektir. Barınağınız Cehennem olacaktır. Yardımcılarınız da olmayacaktır.”');
INSERT INTO verses (sura, aya, text) VALUES (29, 26, 'Sonra Lût ona iman etti. (İbrahim):“Doğrusu ben Rabbime hicret edeceğim.” Şüphesiz O, mutlak güç sahibidir, hüküm ve hikmet sahibidir.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (29, 27, 'Ona (İbrahim’e) İshak’ı ve Ya''kûb’u bahşettik. Onun soyundan gelenlere peygamberlik ve kitap verdik. Ayrıca ona dünyada mükâfatını da verdik. Şüphesiz o, ahirette de salih kimselerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 28, 'Lût’u da peygamber olarak gönderdik. Hani o, kavmine şöyle demişti: “Gerçekten siz, sizden önce dünyada hiçbir toplumun yapmadığı bir hayâsızlığı işliyorsunuz.”');
INSERT INTO verses (sura, aya, text) VALUES (29, 29, 'Siz erkeklere yanaşıyor, yolu kesiyor ve toplantı yerlerinizde çirkin işler mi yapıyorsunuz?" Kavminin cevabı ancak: "Eğer doğru sözlülerden isen bize Allah''ın azabını getir haydi!" demeleri oldu.');
INSERT INTO verses (sura, aya, text) VALUES (29, 30, 'O da(Lût): "Rabbim! Şu bozguncu kavme karşı bana yardım et" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (29, 31, 'Elçilerimiz (melekler) İbrahim’e müjdeyi getirdiklerinde; “Biz, bu memleket halkını helâk edeceğiz, çünkü oranın ahalisi zalim kimselerdir.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (29, 32, '“Ama orada Lût da var” dedi. “Biz orada olanları daha iyi biliriz. Biz onu ve –karısı dışında- aile halkını elbette kurtaracağız çünkü o kadın geride kalacaklardandır” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (29, 33, 'Elçilerimiz Lût’a geldiklerinde; Lût onlar için tasalandı ve göğsüne bir sıkıntı bastı. Elçiler ona; “Korkma, üzülme. Biz, seni ve aileni kurtaracağız. Ancak karın başka. Çünkü o kadın geride kalacaklardandır” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (29, 34, 'Şüphesiz biz, bu memleket halkı üzerine fasıklık ettiklerinden dolayı gökten bir azap indireceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (29, 35, 'Andolsun ki, akıl eden bir topluluk için oradan (geriye) apaçık bir ayet bıraktık.');
INSERT INTO verses (sura, aya, text) VALUES (29, 36, 'Medyen’e de kardeşleri Şuayb’ı peygamber olarak gönderdik. Şuayb: “Ey kavmim! Allah’a ibadet edin. Ahiret gününü ümit edin ve yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (29, 37, 'Kavmi, onu yalanladı. Bunun üzerine kendilerini o malum sarsıntı yakaladı da yurtlarında diz üstü çökekaldılar.');
INSERT INTO verses (sura, aya, text) VALUES (29, 38, 'Âd ve Semûd kavmini de (helak ettik). Onların meskenlerinden bu size belli olmaktadır. Şeytan onlara amellerini süsledi de onları (doğru) yoldan alıkoydu. Hâlbuki onlar akılları ile bunu kavrayacak durumda idiler.');
INSERT INTO verses (sura, aya, text) VALUES (29, 39, 'Kârûn’u, Firavun’u ve Hâmân’ı da helâk ettik. Andolsun, Mûsâ kendilerine apaçık mucizeler getirmişti de yeryüzünde büyüklük taslamışlardı. Oysa bizi geçip (azabımızdan) kurtulamazlardı.');
INSERT INTO verses (sura, aya, text) VALUES (29, 40, 'Derken biz her birini günahı ile aldık. Kimilerinin üzerine taş yağdıran kasırga gönderdik, kimilerini o çığlık yakaladı. Onlardan kimisini yere geçirdik, kimilerini de suda boğduk. Allah onlara zulmetmiyordu fakat onlar kendi nefislerine zulmediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (29, 41, 'Allah’tan başka veliler edinenlerin durumu kendine yuva yapan örümceğin durumuna benzer. Evlerin en dayanıksızı ise şüphesiz örümcek evidir. Keşke bilselerdi!');
INSERT INTO verses (sura, aya, text) VALUES (29, 42, 'Allah, kendi dışında hangi şeye tapmakta olduklarını şüphesiz bilmektedir. O; mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 43, 'İşte bunlar, insanlar için verdiğimiz örneklerdir. Fakat onlara âlimlerden başkası akıl erdiremez.');
INSERT INTO verses (sura, aya, text) VALUES (29, 44, 'Allah, gökleri ve yeri hak olarak yarattı. Şüphesiz bunda iman etmekte olanlar için bir ayet vardır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 45, '(Ey Muhammed!) Kitaptan sana vahyolunanı oku, namazı da dosdoğru kıl. Çünkü namaz, insanı hayâsızlıktan ve kötülükten alıkor. Allah’ı zikretmek elbette herşeyden büyüktür. Allah, yaptıklarınızı bilir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 46, 'İçlerinden zulmedenler hariç, Ehli Kitap ile ancak en güzel bir yolla mücadele edin ve (onlara) şöyle deyin: "Bize indirilene de, size indirilene de iman ettik. Bizim ilahımız da sizin ilahınız da birdir. Biz ona teslim olanlarız."');
INSERT INTO verses (sura, aya, text) VALUES (29, 47, 'İşte sana böyle bir kitap indirdik. Kendilerine kitap verilenler ona iman ederler. Bunlardan (Araplar''dan) da ona iman edenler vardır. Ayetlerimizi ancak kâfirler inatla inkâr ederler.');
INSERT INTO verses (sura, aya, text) VALUES (29, 48, 'Daha önce sen, hiçbir kitap okumuş değildin. Onu sağ elinle de yazmıyordun. Öyle olsaydı, batıl peşinde koşanlar şüphe ederlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (29, 49, 'Hayır! O (Kur''an), bilgi verilen kimselerin gönüllerinde olan apaçık belgelerdir. Ayetlerimizi ancak zalimler bile bile inkâr eder.');
INSERT INTO verses (sura, aya, text) VALUES (29, 50, 'Dediler ki: “Ona Rabbinden mucizeler indirilseydi ya!” De ki: “Mucizeler ancak Allah katındadır ve ben ancak apaçık bir uyarıcıyım."');
INSERT INTO verses (sura, aya, text) VALUES (29, 51, 'Kendilerine okunmakta olan kitabı sana indirmiş olmamız onlara yeterli değil mi? Çünkü onda iman eden bir toplum için rahmet ve öğüt vardır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 52, 'De ki: "Benimle sizin aranızda şahit olarak Allah yeter. O, göklerde ve yerde olanı bilir. Batıla iman edenler ve Allah’ı inkâr edenler ise, işte onlar hüsrana uğrayacak olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 53, 'Senden azabın çabucak gelmesini istiyorlar. Eğer belirlenmiş bir süre olmasaydı, azap onlara mutlaka gelirdi. Azap onlara haberleri olmadıkları bir sırada ansızın gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 54, 'Senden azabın acele gelmesini istiyorlar. Oysa, Cehennem kâfirleri çepeçevre kuşatacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (29, 55, 'Azap onları, üstlerinden ve ayaklarının altından bürüdüğü gün; "(Yüce Allah) yaptığınız amellerin (cezasını) tadın!" der.');
INSERT INTO verses (sura, aya, text) VALUES (29, 56, 'Ey iman eden kullarım! Şüphesiz ki benim arzım (yeryüzü) geniştir. O halde, ancak bana ibadet edin.');
INSERT INTO verses (sura, aya, text) VALUES (29, 57, 'Her nefis ölümü tadacaktır. Sonra da bize döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (29, 58, 'İman edip, salih amel işleyenleri elbette biz onları cennette altlarından ırmaklar akan köşklere yerleştiririz. Onlar orada ebedidirler. (İyi) amel işleyenlerin ecri ne güzel olur!');
INSERT INTO verses (sura, aya, text) VALUES (29, 59, 'Onlar, sabreden ve yalnız Rablerine tevekkül eden kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 60, 'Kendi rızkını taşımayan nice canlı vardır. Allah onlara da rızkı verir, size de. O işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 61, 'Andolsun, eğer onlara; “Gökleri ve yeri kim yarattı? Güneşi ve Ay''ı hizmetinize kim verdi?” diye soracak olsan mutlaka, “Allah” diyeceklerdir. O hâlde nasıl (haktan) döndürülüyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (29, 62, 'Allah, kullarından dilediğine bol verir ve (dilediğine) kısar. Şüphesiz Allah, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (29, 63, 'Andolsun, eğer onlara: “Gökten yağmuru kim indirip de onunla yeryüzünü ölümünden sonra diriltti?” diye soracak olsan, mutlaka, “Allah” diyeceklerdir. De ki: “Hamt Allah’a mahsustur.” Hayır onların çoğu akıl etmiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (29, 64, 'Bu dünya hayatı bir eğlence ve oyundan başka bir şey değildir. Ahiret yurdu ise işte asıl hayat odur. Keşke bilselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (29, 65, 'Gemiye bindiklerinde dini yalnız Allah''a has kılarak yalnız O''na dua ederler. Sonuçta onları karaya çıkarıp kurtarınca hemen ortak koşarlar.');
INSERT INTO verses (sura, aya, text) VALUES (29, 66, 'Kendilerine verdiğimiz nimetlere nankörlük etsinler ve bir süre daha faydalansınlar bakalım! İleride bilecekler.');
INSERT INTO verses (sura, aya, text) VALUES (29, 67, 'Çevrelerindeki insanlar kapılıp götürülürken bizim, onların yurtlarını saygın ve güvenli bir yer kıldığımızı görmediler mi? Hala batıla inanıp da Allah''ın nimetini inkar mı ediyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (29, 68, 'Allah’a karşı yalan uyduran veya kendisine hak gelince onu yalanlayan kimseden daha zalim kim olabilir? Kâfirler için Cehennem''de barınacak yer mi yok?');
INSERT INTO verses (sura, aya, text) VALUES (29, 69, 'Bizim uğrumuzda cihad edenleri biz elbette yollarımıza iletiriz. Muhakkak ki Allah iyilik edenlerle beraberdir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 1, 'Elif, Lâm, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (30, 2, 'Rumlar yenilgiye uğradılar.');
INSERT INTO verses (sura, aya, text) VALUES (30, 3, 'En yakın yerde. Ancak onlar bu yenilgilerinden sonra yeneceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 4, 'Birkaç yıl (üç ila dokuz sene) içinde. Öncesinde de, sonrasında da emir Allah’ındır. O günde Müminler sevineceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 5, 'Allah’ın yardımıyla, Allah dilediğine yardım eder. O; Aziz''dir, Rahim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 6, '(Bu) Allah''ın vaadidir. Allah vaadinden dönmez. Fakat insanların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 7, 'Onlar dünya hayatından sadece dış görünüşü bilirler. Ahiretten ise gaflettedirler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 8, 'Kendi nefisleri konusunda düşünmüyorlar mı? Allah gökleri, yeri ve aralarındaki şeyleri ancak hak ile ve belirli bir süre için yaratmıştır. İnsanların çoğu Rablerine kavuşmayı inkâr ederler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 9, 'Yeryüzünde dolaşmıyorlar mı ki, kendilerinden önceki kimselerin akibetinin nasıl olduğuna bir baksınlar? Onlardan daha güçlü idiler, toprağı yeri sürüp alt üst etmişler ve bunların (Mekke halkının) imar ettiğinden daha çok imar etmişlerdi. Onlara peygamberleri apaçık delillerle gelmişlerdi. Allah, onlara zulmetmiş değildir. Fakat onlar kendilerine zulmediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (30, 10, 'Sonra, Allah’ın ayetlerini yalanladıkları ve onlarla alay etmekte oldukları için, kötülük işleyenin sonu daha da kötü oldu.');
INSERT INTO verses (sura, aya, text) VALUES (30, 11, 'Allah yaratmayı ilk olarak başlatır, sonra onu yeniden gerçekleştirir. Sonra O''na döndürülürsünüz.');
INSERT INTO verses (sura, aya, text) VALUES (30, 12, 'Kıyametin kopacağı gün, günahkârlar umutsuz kesilirler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 13, 'Onların, Allah’a koştukları ortaklardan kendileri için şefaatçılar da olmayacaktır. Artık onlar, ortak koştuklarını da inkâr edeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 14, 'Kıyametin kopacağı gün, işte o gün Müminler ve kâfirler birbirinden ayrılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 15, 'İman edip salih ameller işleyenler; işte onlar bir bahçede sevinç içinde ağırlanırlar.');
INSERT INTO verses (sura, aya, text) VALUES (30, 16, 'Kâfir olup, ayetlerimizi ve ahirete kavuşmayı yalanlayanlara gelince, işte onlar daima azapta tutulurlar.');
INSERT INTO verses (sura, aya, text) VALUES (30, 17, 'O halde akşama girerken ve sabaha ererken Allah''ı tesbih edin.');
INSERT INTO verses (sura, aya, text) VALUES (30, 18, 'Göklerde ve yerde hamt O’na mahsustur. Gündüzün sonunda ve öğle vaktine girdiğinizde Allah’ı tesbih edin.');
INSERT INTO verses (sura, aya, text) VALUES (30, 19, 'Allah, diriyi ölüden çıkarır, ölüyü de diriden çıkarır. Ölümünden sonra yeryüzünü diriltir. Siz de (mezarlarınızdan) işte böyle çıkarılacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (30, 20, 'Sizi topraktan yaratması, O’nun (varlığının ve kudretinin) delillerindendir. Sonra bir de gördünüz ki, siz beşer olmuş (çoğalıp) yayılıyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (30, 21, 'Sizin için nefislerinizden kendileri ile sükûn/huzur bulacağınız ve aranızda muhabbet ve merhamet kıldığı eşler yaratmış olması da onun ayetlerindendir. Muhakkak bunlarda düşünen bir topluluk için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 22, 'Göklerin ve yerin yaratılması, dillerinizin ve renklerinizin farklı olması da O’nun ayetlerindendir. Şüphesiz bunda bilenler için elbette ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 23, 'Geceleyin ve gündüzün uyumanız ve O''nun lütfundan (nasip) aramanız da O''nun ayetlerindendir. Şüphesiz bunda işiten bir toplum için ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 24, 'Korku ve ümit vermek üzere size şimşeği göstermesi, gökten yağmur indirip onunla yeryüzünü ölümünden sonra diriltmesi, O’nun ayetlerindendir. Şüphesiz bunda aklını kullanan bir toplum için elbette ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 25, 'Emriyle göğün ve yerin (kendi düzenlerinde) durması da O’nun ayetlerindendir. Sonra sizi yerden (kalkmaya) bir çağırdı mı, bir de bakarsınız ki (dirilmiş olarak) çıkıyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (30, 26, 'Göklerde ve yerde ne varsa O''nundur. Hepsi O''na boyun eğmişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 27, 'Yaratmayı ilk başlatan, sonra onu yeniden gerçekleştirecek olan O''dur. Bu, O’na göre (ilk yaratmadan) daha kolaydır. Göklerde ve yerde en yüce ve eşsiz sıfatlar O’nundur. O; Azîzdir, Hakîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 28, '(Allah) size kendi nefislerinizden bir misal getirdi. Size rızık olarak verdiklerimizde elinizin altındaki kölelerinizin size ortak olup o rızıkta hep birlikte eşit olmayı ve kendiniz (gibi) hür olan diğer ortaklarınızdan çekindiğiniz gibi onlardan da çekinmeyi kabul eder misiniz? İşte akıllarını kullanan bir topluluk için ayetleri böyle açıklarız.');
INSERT INTO verses (sura, aya, text) VALUES (30, 29, 'Fakat, zulmedenler bilgisizce nefislerinin arzularına uydular. Allah’ın (bu şekilde) saptırdığı kimseleri kim doğru yola iletir? Onların hiçbir yardımcıları yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (30, 30, 'Sen yüzünü hanif olarak dine, Allah’ın insanları üzerinde yarattığı fıtratına dosdoğru çevir. Allah’ın yaratmasında hiçbir değiştirme yoktur. İşte bu dosdoğru dindir. Fakat insanların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 31, 'O’na ihlasla yönelin. O’ndan sakının ve namazı ikame edin ve asla müşriklerden olmayın.');
INSERT INTO verses (sura, aya, text) VALUES (30, 32, 'O dinlerini parça parça eden ve fırkalara/cemaatlere ayrılanlardan (olmayın). Her grup/cemaat kendi yanında olanla sevinmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 33, 'İnsanlara bir zarar dokunduğu zaman, Rablerine yönelerek O’na dua ederler. Sonra Allah, onlara kendinden bir rahmet tattırınca da, bir bakarsın ki içlerinden bir grup, Rablerine ortak koşuyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (30, 34, 'Kendilerine verdiğimiz nimetleri inkâr etsinler bakalım! Haydi (şimdilik) yararlanın, ama yakında bileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (30, 35, 'Yoksa onlara kesin bir delil indirdik de o mu onlara ortak koşmalarını söylüyor?');
INSERT INTO verses (sura, aya, text) VALUES (30, 36, 'İnsanlara bir rahmet tattırdığımız zaman ona sevinirler. Eğer kendi işledikleri şeyler sebebiyle başlarına bir kötülük gelirse, bir de bakarsın ki ümitsizliğe düşerler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 37, 'Onlar, Allah''ın, dilediğine rızkı yayıp genişlettiğini ve kıstığını görmüyorlar mı? Şüphesiz bunda, iman etmekte olan bir kavim için gerçekten ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 38, 'Akrabaya, yoksula ve yolculara haklarını ver. Bu Allah’ın rızasını isteyenler için daha hayırlıdır. İşte onlar kurtuluşa erenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 39, 'İnsanların mallarında artış olsun diye verdiğiniz herhangi bir faiz, Allah katında artmaz. Ama Allah''ın yüzünü isteyerek vermekte olduğunuz zekâta gelince, işte (bu amel sahipleri, sevaplarını) kat kat arttıranlardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 40, 'Allah sizi yaratan sonra size rızık veren sonra sizi öldüren sonra da sizi diriltecek olandır. Sizin ortaklarınızdan bu işlerden birisini olsun yapabilen var mıdır? O koştukları ortaklardan yüce ve münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 41, 'İnsanların ellerinin kazandıklarından dolayı karada ve denizde fesat çıktı. Umulur ki dönerler diye, (Allah) yaptıklarının bazılarını böylece onlara tattırmaktadır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 42, 'De ki: "Yeryüzünde dolaşın da daha öncekilerin sonları nasıl olmuş bir bakın!" Onların çoğu müşriklerdi.');
INSERT INTO verses (sura, aya, text) VALUES (30, 43, 'Allah tarafından (gelecek ve) geri çevirilmesi mümkün olmayan bir gün gelmeden yüzünü o dosdoğru dine çevir. O gün onlar bölük bölük ayrılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 44, 'Kim küfre saparsa, artık onun küfrü kendi aleyhinedir; kim de salih bir amelde bulunursa, ancak kendileri için (Cennet''te yer) hazırlarlar.');
INSERT INTO verses (sura, aya, text) VALUES (30, 45, 'Bu, (Allah''ın) iman edip salih amel işleyenleri kendi lütfundan mükâfatlandırması içindir. Şüphesiz O, kâfirleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (30, 46, 'Rüzgârları müjdeciler olarak göndermesi, size rahmetini tattırması, buyruğu ile gemilerin yürümesi, lütfundan rızık istemeniz, O''nun ayetlerindendir (varlığının ve kudretinin) delillerindendir.) Belki şükredersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (30, 47, 'Andolsun ki biz senden önce nice rasulleri kavimlerine gönderdik. Onlar da kendilerine açık açık delillerle geldiler. Biz de günahkârlardan intikam aldık. Müminlere yardım etmek ise zaten üzerimize bir haktır.');
INSERT INTO verses (sura, aya, text) VALUES (30, 48, 'Allah, rüzgârları gönderendir. Onlar da bulutları harekete geçirir. Allah, onları dilediği gibi, (bazen) yayar ve (bazen) yoğunlaştırır. Nihayet yağmurun onların arasından çıktığını görürsün. Onu kullarından dilediklerine uğrattığı zaman bir de bakarsın sevinirler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 49, 'Hâlbuki onlar daha önce kendilerine yağmur yağdırılmadan evvel kesin bir ümitsizliğe kapılmışlardı.');
INSERT INTO verses (sura, aya, text) VALUES (30, 50, 'Allah’ın rahmetinin eserlerine bak! Yeryüzünü ölümünden sonra nasıl diriltiyor. Şüphe yok ki O, ölüleri de elbette diriltecektir. O, her şeye hakkıyla gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 51, 'Andolsun, eğer biz bir rüzgâr göndersek, onlar da ardından onu sararmış görürlerse bundan sonra onlar muhakkak inkâra saparlar.');
INSERT INTO verses (sura, aya, text) VALUES (30, 52, 'Şüphesiz, sen ölülere işittiremezsin. Dönüp gittikleri zaman çağrıyı sağırlara da işittiremezsin.');
INSERT INTO verses (sura, aya, text) VALUES (30, 53, 'Sen kör olanları sapıklıktan hidayete iletecek de değilsin. Sen ancak ayetlerimize iman edip, teslim olanlara işittirirsin.');
INSERT INTO verses (sura, aya, text) VALUES (30, 54, 'Allah; sizi güçsüz olarak yaratan, sonra güçsüzlüğün ardından bir güç veren, sonra gücün ardından bir güçsüzlük ve yaşlılık verendir. O, dilediğini yaratır. O; hakkıyla bilendir, hakkıyla kudret sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (30, 55, 'Kıyametin kopacağı gün günahkârlar, bir saatten fazla kalmadıklarına yemin ederler. Onlar (dünyada haktan) işte böyle döndürülüyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (30, 56, 'Kendilerine ilim ve iman verilmiş olanlar ise onlara şöyle diyeceklerdir: “Andolsun ki Allah''ın kitabında (yazılı) olana göre siz yeniden diriliş gününe kadar kaldınız. İşte bu yeniden dirilme günüdür. Fakat siz bilmiyordunuz.”');
INSERT INTO verses (sura, aya, text) VALUES (30, 57, 'O gün zulmedenlere özürleri bir yarar sağlamaz, onlardan artık (Allah''ı) razı edecek bir şey yapmaları da istenmez.');
INSERT INTO verses (sura, aya, text) VALUES (30, 58, 'Andolsun, biz bu Kur’an’da insanlara her türlü misali verdik. Andolsun, eğer sen onlara bir ayet getirsen, o kâfirler elbette; “Siz ancak batıl şeyler uyduranlarsınız” derler.');
INSERT INTO verses (sura, aya, text) VALUES (30, 59, 'İşte bilmeyenlerin kalpleri üzerine Allah böyle mühür vurur.');
INSERT INTO verses (sura, aya, text) VALUES (30, 60, 'O halde sabret muhakkak ki Allah’ın vaadi haktır. Kesin imana sahip olmayanlar sakın seni gevşekliğe sevk etmesin.');
INSERT INTO verses (sura, aya, text) VALUES (31, 1, 'Elif, Lâm, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (31, 2, 'Bunlar hikmetli Kitab''ın ayetleridir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 3, 'İhsan sahiplerine bir hidayet ve bir rahmettir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 4, 'Onlar ki namazı dosdoğru kılarlar, zekâtı verirler ve onlar âhirete kesin olarak iman edenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 5, 'İşte onlar, Rablerinden gelen bir hidayet üzeredirler ve işte onlar kurtuluşa erenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 6, 'İnsanlardan kimisi bilgisizce Allah’ın yolundan saptırmak ve o ayetleri bir eğlence edinmek için boş sözleri satın alırlar. İşte onlar için aşağılayıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (31, 7, 'Ona ayetlerimiz okunduğunda, sanki onları işitmiyormuş ve kulaklarında bir ağırlık varmış gibi büyüklük taslayarak sırtını çevirir. Ona, elem dolu bir azabı müjdele.');
INSERT INTO verses (sura, aya, text) VALUES (31, 8, 'Gerçekten iman edip salih ameller işleyenler için Naim Cennetleri vardır.');
INSERT INTO verses (sura, aya, text) VALUES (31, 9, 'Onlar oralarda ebedi kalıcıdırlar. Bu Allah’ın hak vaadidir. O, Azîzdir, Hakîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 10, 'O, gökleri görebildiğiniz bir direk olmaksızın yarattı. Yeryüzüne de, sizi sarsmasın diye sabit dağlar yerleştirdi ve orada her türlü canlıyı yaydı. Biz gökyüzünden su indirip, orada her faydalı nebattan çift çift bitirdik.');
INSERT INTO verses (sura, aya, text) VALUES (31, 11, 'İşte bu Allah''ın yaratmasıdır. Ondan başkasının ne yarattığını bana gösterin! Hayır! Zalimler, açık bir sapıklık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (31, 12, 'Andolsun, biz Lokman’a “Allah’a şükret!” diye hikmet verdik. Kim şükrederse, ancak kendisi için şükretmiş olur. Kim de nankörlük ederse, bilsin ki Allah her bakımdan zengindir, övülmeye layıktır.');
INSERT INTO verses (sura, aya, text) VALUES (31, 13, 'Lokman, oğluna öğüt vererek demişti ki: "Yavrucuğum! Allah’a şirk koşma! Muhakkak, şirk koşmak çok büyük bir zulümdür."');
INSERT INTO verses (sura, aya, text) VALUES (31, 14, 'Biz insana anne ve babasını tavsiye ettik. Anası onu zayıflık üstüne zayıflığa düşerek taşımıştır. Onun sütten kesilmesi de iki yılda olur. "Bana ve ana babana şükret, dönüş yalnız banadır."');
INSERT INTO verses (sura, aya, text) VALUES (31, 15, 'Eğer onlar bilmediğin şeyi bana ortak koşman için seni zorlarlarsa; sen sakın onlara itaat etme! Bununla beraber dünyada onlarla iyi geçin ve sen bana dönenlerin yoluna uy. Sonra dönüşünüz yine banadır. Ben de size yaptıklarınızı haber vereceğim.');
INSERT INTO verses (sura, aya, text) VALUES (31, 16, '(Lokman, öğütlerine şöyle devam etti:) “Yavrum! Şüphesiz yapılan iş, bir hardal tanesi ağırlığında olsa ve bir kayanın içinde yahut göklerde ya da yerin içinde bile olsa, Allah onu çıkarır getirir. Şüphesiz Allah Latîf''tir/en gizli şeyleri bilendir, (her şeyden) hakkıyla haberdar olandır.”');
INSERT INTO verses (sura, aya, text) VALUES (31, 17, '“Yavrum! Namazı dosdoğru kıl. İyiliği emret. Kötülükten alıkoy. Başına gelen musibetlere karşı sabırlı ol. Çünkü bunlar kesin olarak emredilmiş işlerdendir.”');
INSERT INTO verses (sura, aya, text) VALUES (31, 18, 'İnsanlara yüzünü çevirme ve yeryüzünde böbürlenerek yürüme. Çünkü Allah kendini beğenip böbürlenen hiçbir kimseyi sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (31, 19, 'Yürüyüşünde orta bir yol tut, sesini kıs! Çünkü seslerin en çirkini eşeklerin sesidir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 20, 'Allah''ın, göklerde ve yerdeki (nice varlık ve imkânları) sizin emrinize verdiğini, nimetlerini açık ve gizli olarak size bolca ihsan ettiğini görmediniz mi? Yine de insanlar arasında hiçbir bilgisi, yol göstericisi ve aydınlatıcı bir kitabı olmadan Allah hakkında tartışıp duranlar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (31, 21, 'Kendilerine; “Allah’ın indirdiğine tabi olun!” denildiği zaman, “Hayır, biz babalarımızı üzerinde bulduğumuz şeye uyarız.” derler. Şeytan, kendilerini Cehennem azabına çağırıyor olsa da mı?');
INSERT INTO verses (sura, aya, text) VALUES (31, 22, 'Kim, ihsan sahibi olarak yüzünü Allah’a (ihlasla) teslim ederse, sağlam bir kulpa yapışmış olur. Her işin sonu Allah’a varır.');
INSERT INTO verses (sura, aya, text) VALUES (31, 23, 'Kim de küfre saparsa, artık onun küfre sapması seni üzmesin. Onların dönüşü bizedir, artık biz de onlara yapmakta olduklarını haber vereceğiz. Allah, göğüslerin içindekini (kalplerde olanı) hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 24, 'Biz onları azıcık faydalandırırız, sonra da onları şiddetli bir azaba uğratırız.');
INSERT INTO verses (sura, aya, text) VALUES (31, 25, 'Andolsun ki, onlara: "Gökleri ve yeri kim yarattı?" diye sorsan muhakkak: "Allah" diyeceklerdir.De ki: "Hamt Allah''adır." Hayır, onların çoğu bilmiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (31, 26, 'Göklerlerde ve yerde olanlar Allah’ındır. Muhakkak Allah Ganî''dir, Hamîd''dir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 27, 'Eğer yeryüzündeki ağaçlar kalem, deniz de mürekkep olsa, arkasından yedi deniz daha ona katılsa, Allah’ın sözleri (yazmakla) yine de tükenmez. Muhakkak Allah Azîzdir, Hakîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 28, 'Sizin yaratılmanız ve diriltilmeniz ancak bir tek kişi(nin yaratılması ve diriltilmesi) gibidir. Şüphesiz Allah; hakkıyla işitendir, hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (31, 29, 'Görmedin mi ki, Allah geceyi gündüze, gündüzü de geceye katıyor? Güneş''i ve Ay''ı sizin hizmetinize sunmuştur. Her biri belli bir süreye (kadar) akıp gider. Allah, yaptığınız her şeyden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (31, 30, 'Bu böyledir. Çünkü Allah hakkın ta kendisidir. O''nu bırakıp da taptıkları ise batıldır. Şüphesiz Allah; yüksektir/uludur, büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (31, 31, '- Size ayetlerinden bir kısmını göstermek için Allah’ın nimeti ile gemilerin denizde akıp gittiğini görmez misin? İşte bunda çok sabreden ve çok şükreden herkes için muhakkak ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (31, 32, 'Onları dağlar gibi bir dalga kapladığında dinlerini yalnız Allah’a halis kılarak O''na dua ederler. Allah; onları kurtarıp karaya çıkarınca, onlardan bir kısmı orta yolu tutar. Ayetlerimizi hain ve çokça nankörlük edenden başkası bilerek inkâr etmez.');
INSERT INTO verses (sura, aya, text) VALUES (31, 33, 'Ey insanlar! Rabbinizden sakının. Hiçbir babanın çocuğuna hiçbir yarar sağlayamayacağı, hiçbir çocuğun da babasına hiçbir yarar sağlayamayacağı günden korkun! Şüphesiz Allah’ın vaadi gerçektir. Sakın dünya hayatı sizi aldatmasın. O aldatıcı Şeytan da Allah hakkında sizi aldatmasın.');
INSERT INTO verses (sura, aya, text) VALUES (31, 34, 'Kıyametin ne zaman kopacağı bilgisi şüphesiz yalnızca Allah katındadır. O; yağmuru indirir, rahimlerdekini bilir. Hiç kimse yarın ne kazanacağını bilemez. Hiç kimse nerede öleceğini de bilemez. Şüphesiz Allah hakkıyla bilendir, (her şeyden) hakkıyla haberdar olandır.');
INSERT INTO verses (sura, aya, text) VALUES (32, 1, 'Elif, Lâm, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (32, 2, 'Kitabın indirilmesi –ki onda şüphe yoktur- âlemlerin Rabbindendir.');
INSERT INTO verses (sura, aya, text) VALUES (32, 3, 'Yoksa; “Onu Muhammed uydurdu mu?" diyorlar. Hayır! O, kendilerine senden önce hiçbir uyarıcı gelmemiş olan bir kavmi uyarman için, doğru yolu bulsunlar diye Rabbinden gelen haktır.');
INSERT INTO verses (sura, aya, text) VALUES (32, 4, 'Allah; gökleri ve yeri, ikisi arasındakileri altı günde yaratmış, sonra da arşa istivâ etmiştir. Sizin O’ndan başka bir veliniz de şefaatçiniz de yoktur. Hâlâ düşünüp öğüt almayacak mısınız?');
INSERT INTO verses (sura, aya, text) VALUES (32, 5, 'Gökten yere kadar bütün işleri Allah yürütür. Sonra bu işler, süresi sizin hesabınızla bin yıl olan bir günde O’na yükselir.');
INSERT INTO verses (sura, aya, text) VALUES (32, 6, 'İşte O, gaybı da görüneni de bilendir, mutlak güç sahibidir, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (32, 7, 'O ki yarattığı her şeyi güzel yapmıştır. İnsanı yaratmaya da çamurdan başlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (32, 8, 'Sonra onun soyunu bayağı bir sudan olan bir özden (nutfeden) yarattı.');
INSERT INTO verses (sura, aya, text) VALUES (32, 9, 'Sonra onu düzenli bir şekle soktu ve ona ruhundan üfledi. Size kulak, gözler ve gönüller verdi. Ne kadar az şükrediyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (32, 10, '(Kâfirler dediler ki:) “Biz toprakta yok olduktan sonra mı, biz mi yeniden yaratılacakmışız?" Hayır! Onlar Rablerine kavuşmayı inkâr etmektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (32, 11, 'De ki: “Sizin için görevlendirilen ölüm meleği canınızı alacak, sonra Rabbinize döndürüleceksiniz.''''');
INSERT INTO verses (sura, aya, text) VALUES (32, 12, 'Günahkârları Rablerinin huzurunda başlarını eğip: “Rabbimiz gördük, işittik. Artık bizi geri döndür. Salih amel işleyelim. Gerçekten biz inandık” diyecekleri vakit bir görsen.');
INSERT INTO verses (sura, aya, text) VALUES (32, 13, 'Eğer biz dileseydik her nefse elbette hidayetini verirdik, fakat benden sadır olan: “Cehennemi bütünü ile cinlerden ve insanlardan elbette dolduracağım” sözü hak olmuştur.');
INSERT INTO verses (sura, aya, text) VALUES (32, 14, 'O halde siz bugününüze kavuşmayı unuttuğunuz için tadın. Gerçekten biz de sizi unuttuk. .Şimdi yaptıklarınıza karşılık ebedi azabı tadın" deriz.');
INSERT INTO verses (sura, aya, text) VALUES (32, 15, 'Bizim ayetlerimize ancak, kendilerine bu ayetlerle öğüt verildiği zaman secdeye kapanan, kibirlenmeksizin Rablerine hamt ederek tespih edenler iman ederler.');
INSERT INTO verses (sura, aya, text) VALUES (32, 16, 'Yanları yataklarından uzak kalır. Rablerine korkarak ve ümit ederek dua ederler. Onlara verdiğimiz rızıktan infak da ederler.');
INSERT INTO verses (sura, aya, text) VALUES (32, 17, 'Hiç kimse yapmakta olduklarına karşılık olarak, onlar için saklanan göz aydınlıklarını bilemez.');
INSERT INTO verses (sura, aya, text) VALUES (32, 18, 'Hiç Mümin, fasık gibi olur mu? Bunlar asla bir olmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (32, 19, 'İman edip salih amel işleyenlere gelince, onlar için yaptıklarına karşılık konak olarak içinde barınacakları Cennetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (32, 20, 'Fasıklık edenlere gelince, onların barınağı ateştir. Oradan her çıkmak istediklerinde, oraya döndürülürler ve onlara; “Yalanlamakta olduğunuz ateş azabını tadın!” denir.');
INSERT INTO verses (sura, aya, text) VALUES (32, 21, 'Andolsun ki biz onlara –belki dönerler diye- en büyük azaptan önce yakın azaptan mutlaka tattıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (32, 22, 'Kendisine Rabbinin ayetleri hatırlatıldıktan sonra onlardan yüz çevirenden daha zalim kim olabilir? Şüphesiz ki biz, günahkârlardan intikam alıcıyız.');
INSERT INTO verses (sura, aya, text) VALUES (32, 23, 'Andolsun biz Mûsâ''ya Kitab''ı vermiştik, şimdi sen ona kavuşmaktan kuşku içinde olma. Onu (Tevrat''ı) İsrailoğullarına yol gösterici kılmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (32, 24, 'Sabredip ayetlerimize kesin olarak inanmalarından ötürü, aralarından, onları buyruğumuzla doğru yola götüren önderler yaptık.');
INSERT INTO verses (sura, aya, text) VALUES (32, 25, 'Şüphesiz Rabbin, kıyamet günü üzerinde ayrılığa düşmekte oldukları şeyler konusunda onlar arasında hüküm verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (32, 26, 'Şimdi yurtlarında gezip dolaştıkları, kendilerinden önceki nice nesilleri yok etmiş olmamız onları doğru yola sevketmez mi? Bunlarda şüphesiz ibretler vardır. Dinlemezler mi?');
INSERT INTO verses (sura, aya, text) VALUES (32, 27, 'Görmediler mi ki, biz yağmuru kupkuru yere gönderip onunla hayvanlarının ve kendilerinin yiyeceği ekinler çıkarırız. Hâlâ görmeyecekler mi?');
INSERT INTO verses (sura, aya, text) VALUES (32, 28, 'Derler ki: “Bu fetih ne zaman olur, eğer doğru söyleyenler iseniz?”');
INSERT INTO verses (sura, aya, text) VALUES (32, 29, 'De ki: “Fetih (kıyamet) günü, kâfirlere iman etmeleri fayda vermeyecektir. Onlara göz de açtırılmayacaktır.”');
INSERT INTO verses (sura, aya, text) VALUES (32, 30, 'Şimdi sen onlardan yüz çevir ve bekle. Şüphesiz onlar da bekliyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (33, 1, 'Ey Nebi! Allah’tan kork, kâfirlere ve münafıklara itaat etme. Muhakkak Allah Alîmdir, Hakîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 2, 'Rabbinden sana vahyolunana uy. Şüphesiz Allah, yaptıklarınızdan hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 3, 'Allah’a tevekkül et. Vekil olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (33, 4, 'Allah, hiçbir adamın içine iki kalp yaratmamıştır. Zihâr yaptığınız ("Sen bana anamın sırtı gibisin" diyerek kendinize haram kıldığınız) eşlerinizi analarınız kılmamıştır. Evlat edindiğiniz kimseleri de öz oğullarınız kılmamıştır. Bunlar ağızlarınızla söylediğiniz sözlerinizden ibarettir. Allah hak olanı söyler, doğru yola ileten de odur.');
INSERT INTO verses (sura, aya, text) VALUES (33, 5, 'Evlatlıkları, babalarına nispet ederek çağırın. Bu, Allah katında daha adaletlidir. Eğer onların babalarını bilmiyorsanız, artık onlar sizin din kardeşleriniz ve dostlarınızdır. Hata ile yaptığınız bir işte size hiçbir günah yoktur. Fakat kasten yaptığınız şeylerde size günah vardır. Allah; çokça bağışlayandır, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 6, 'Peygamber, Müminlere kendi canlarından daha önce gelir. Onun eşleri de Müminlerin analarıdır. Aralarında akrabalık bağı olanlar, Allah’ın kitabına göre, (miras konusunda) birbirileri için (diğer) Müminlerden ve muhacirlerden daha önceliklidirler. Ancak dostlarınıza bir iyilik yapmanız başka. Bu (hüküm) kitapta yazılıdır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 7, 'Hani biz peygamberlerden sağlam söz almıştık. Senden, Nûh’tan, İbrahim, Mûsâ ve Meryem oğlu İsâ’dan da. Evet biz, onlardan sapasağlam bir söz almıştık.');
INSERT INTO verses (sura, aya, text) VALUES (33, 8, '(Allah, bunu) doğru kimseleri doğruluklarından hesaba çekmek için (yapmıştır.) Kâfirlere de elem dolu bir azap hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 9, 'Ey iman edenler! Allah’ın size olan nimetini hatırlayın. Hani (düşman) orduları üzerinize gelmişti de biz onların üzerine bir rüzgâr ve göremediğiniz ordular göndermiştik. Allah, yaptıklarınızı hakkıyla görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 10, 'Hani onlar, size hem üst tarafınızdan, hem alt tarafınızdan gelmişlerdi. Hani gözler kaymış ve yürekler ağızlara gelmişti. Allah hakkında bir takım zanlarda bulunuyordunuz.');
INSERT INTO verses (sura, aya, text) VALUES (33, 11, 'İşte orada Müminler denendiler ve şiddetli bir şekilde sarsıldılar.');
INSERT INTO verses (sura, aya, text) VALUES (33, 12, 'O zaman münafıklar ve kalplerinde hastalık bulunanlar: “Allah ve Rasulü bize bir aldatıştan başka bir şey vaat etmemiştir” diyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (33, 13, 'Hani onlardan bir grup: “Ey Yesrib (Medine) halkı! Sizin burada durma imkânınız yok. Haydi geri dönün.” demişti. Onlardan bir başka grup da; “Evlerimiz açık (korumasız)” diyerek Peygamber''den izin istiyorlardı. Oysa evleri açık (korumasız) değildi. Onlar sadece kaçmak istiyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (33, 14, 'Eğer Medine’nin her tarafından üzerilerine gelinse ve kendilerinden fitne (şirk koşup, dinden dönmeleri) istenmiş olsaydı, onu mutlaka yaparlardı ve pek fazla gecikmezlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (33, 15, 'Andolsun ki, onlar daha önce geri dönüp kaçmayacaklarına dair Allah’a söz vermişlerdi. Allah’a verilen söz mesuliyeti gerektirir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 16, 'De ki: “Eğer siz ölümden ya da öldürülmekten kaçıyorsanız, kaçmak size asla fayda vermeyecektir. O takdirde bile (hayatın zevklerinden) pek az yararlandırılırsınız.”');
INSERT INTO verses (sura, aya, text) VALUES (33, 17, 'De ki: “Eğer Allah size bir kötülük dilese, sizi Allah’tan koruyacak kimdir? Yahut size bir rahmet dilese, buna engel olacak kimdir?” Onlar kendilerine Allah’tan başka hiçbir dost ve hiçbir yardımcı bulamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (33, 18, 'Allah, aranızdan savaştan alıkoymaya çalışanları ve kardeşlerine “Bize gelin.” diyenleri elbette bilir. Bunlar, pek azı hariç zora/savaşa gelemezler.');
INSERT INTO verses (sura, aya, text) VALUES (33, 19, '(Gelseler de) Size karşı cimri ve bencildirler. Korkuya kapılınca, ölüm baygınlığı geçiren kimse gibi gözleri dönmüş olarak sana baktıklarını görürsün. Korku geçince keskin dillerini uzatıp sizi incitirler, hayra/ganimete karşı çok cimridirler. Bunlar, iman etmemişlerdir. Allah da onların amellerini boşa çıkarmıştır. Bu, Allah için çok kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 20, 'Düşman birliklerinin gitmediğini sanıyorlar. Düşman birlikleri (bir daha) gelecek olsa, isterler ki (çölde) Bedeviler''in arasında bulunsunlar da size dair haberleri (gidip gelenlerden) sorsunlar. İçinizde bulunsalardı da pek az savaşırlardı.');
INSERT INTO verses (sura, aya, text) VALUES (33, 21, 'Andolsun Allah’ın Rasûlünde; Allah’a ve ahiret gününe kavuşmayı uman, Allah’ı çokça zikreden kimseler için güzel bir örnek vardır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 22, 'Müminler, düşman birliklerini görünce; “İşte bu, Allah’ın ve Rasûlünün bize vadettiği şeydir. Allah ve Rasûlü doğru söylemiştir.” dediler. Bu, onların ancak imanlarını ve teslimiyetlerini artırmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 23, 'Müminlerden öyle adamlar vardır ki, Allah’a verdikleri söze sadık kaldılar. İçlerinden bir kısmı verdikleri sözü yerine getirmiştir. (Şehit olmuştur.) Bir kısmı da (şehit olmayı) beklemektedir. Verdikleri sözü asla değiştirmemişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 24, 'Bunun böyle olması Allah’ın; doğruları, doğrulukları sebebiyle mükâfatlandırması, dilerse münafıklara azap etmesi yahut onların tevbesini kabul etmesi içindir. Şüphesiz Allah; çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 25, 'Allah kâfirleri hiçbir hayır elde etmeksizin öfkeleri ile geri çevirdi. Allah, savaşta Müminlere kâfi geldi. Allah; kuvvetlidir, mutlak güç sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 26, 'Allah, kitap ehlinden olup müşriklere yardım edenleri kalelerinden indirdi ve kalplerine büyük bir korku saldı. Siz onların bir kısmını öldürüyor, bir kısmını da esir ediyordunuz.');
INSERT INTO verses (sura, aya, text) VALUES (33, 27, 'Allah; sizi onların topraklarına, yurtlarına, mallarına ve henüz ayak basmadığınız topraklara varis kıldı. Allah, her şeye hakkıyla gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 28, 'Ey Peygamber! Eşlerine de ki: "Eğer, dünya hayatını ve süsünü diliyorsanız, gelin size boşanma bedellerinizi vereyim ve sizi güzellikle salıvereyim."');
INSERT INTO verses (sura, aya, text) VALUES (33, 29, '"Eğer Allah’ı, Rasûlünü ve ahiret yurdunu istiyorsanız; bilin ki Allah, içinizden iyilik yapanlara büyük bir mükâfat hazırlamıştır.''''');
INSERT INTO verses (sura, aya, text) VALUES (33, 30, 'Ey Peygamber’in hanımları! Sizden kim apaçık bir hayasızlık işlerse, onun için azap iki kat artırılır. Bu, Allah için çok kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 31, 'Sizden kim, Allah’a ve Rasûlüne itaat eder ve salih amel işlerse; ona mükâfatını iki kat veririz. Ona (Cennet''te) bol rızık hazırlamışızdır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 32, 'Ey Peygamber hanımları! Siz, kadınlardan herhangi biri gibi değilsiniz. Eğer takvalı kimseler iseniz, (yabancı erkeklere karşı) çekici bir eda ile konuşmayın; sonra kalbinde hastalık bulunan kimse ümide kapılır. Siz hep uygun söz söyleyin.');
INSERT INTO verses (sura, aya, text) VALUES (33, 33, 'Evlerinizde oturun, eski cahiliye âdetinde olduğu gibi açılıp saçılmayın. Namazı dosdoğru kılın, zekâtı verin, Allah''a ve Rasûlüne itaat edin. Ey ehli beyt (Ev halkı)! Allah sizden, sadece günahı gidermek ve sizi tertemiz yapmak istiyor.');
INSERT INTO verses (sura, aya, text) VALUES (33, 34, 'Evlerinizde okunan Allah’ın ayetlerini ve hikmeti anın. Şüphesiz Allah her şeyin inceliklerini bilir (Latîftir), her şeyden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 35, 'Şüphesiz Müslüman erkeklerle Müslüman kadınlar, Mümin erkeklerle Mümin kadınlar, itaatkâr erkeklerle itaatkâr kadınlar, sadık olan erkeklerle sadık olan kadınlar, sabreden erkeklerle sabreden kadınlar, Allah’a zilletle boyun eğen erkeklerle boyun eğen kadınlar, sadaka veren erkeklerle sadaka veren kadınlar, oruç tutan erkeklerle oruç tutan kadınlar, iffetlerini koruyan erkeklerle iffetlerini koruyan kadınlar, Allah’ı çok zikreden erkeklerle çok zikreden kadınlar var ya; işte Allah, onlar için mağfiret ve büyük bir mükâfat hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 36, 'Allah ve Rasûlü bir iş hakkında hüküm verdikleri zaman, hiçbir Mümin erkek ve hiçbir Mümin kadına o işi kendi isteklerine göre seçme hakkı yoktur. Her kim, Allah''a ve Rasûlüne karşı gelirse apaçık bir sapıklığa düşmüş olur.');
INSERT INTO verses (sura, aya, text) VALUES (33, 37, '(Rasûlüm!) Hani, Allah''ın nimet verdiği, senin de kendisine iyilik ettiğin kimseye: "Eşini yanında tut, Allah''tan sakın/kork!" diyordun. Allah''ın açığa vuracağı şeyi, insanlardan çekinerek içinde gizliyordun. Oysa asıl korkmana lâyık olan Allah''tır. Zeyd, o kadından ilişiğini kesince biz onu sana nikahladık ki evlâtlıkları, karılarıyla ilişkilerini kestiklerinde (o kadınlarla evlenmek isterlerse) Müminlere bir güçlük olmasın. Allah''ın emri yerine getirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 38, 'Allah''ın, peygambere farz kıldığı şeylerde ona bir güçlük yoktur. Bu, Allah''ın önceden geçmişler hakkındaki sünnetidir. Allah’ın emri, kesinleşmiş bir takdirdir/hükümdür.');
INSERT INTO verses (sura, aya, text) VALUES (33, 39, 'Onlar (peygamberler), Allah''ın gönderdiklerini tebliğ ederler, O''ndan korkarlar ve O''ndan başka kimseden korkmazlar. Hesap görücü olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (33, 40, 'Muhammed, sizin adamlarınızdan kimsenin babası değildir fakat o Allah’ın Rasulü ve nebilerin sonuncusudur. Allah, her şeyi hakkıyla bilir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 41, 'Ey iman edenler! Allah’ı çok çok zikredin.');
INSERT INTO verses (sura, aya, text) VALUES (33, 42, 'O’nu, sabah ve akşam tesbih edin.');
INSERT INTO verses (sura, aya, text) VALUES (33, 43, 'Sizi karanlıklardan aydınlığa çıkarmak için üzerinize rahmetini gönderen (ve sizi öven) O''dur. Melekleri ise sizin için bağışlanma diler. Allah, Müminlere karşı çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 44, 'Allah’a kavuşacakları gün Müminlere yönelik esenlik dileği “Selâm”dır. Allah, onlara bol bir mükâfat hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 45, 'Ey peygamber! Gerçekten biz seni; bir şahit, bir müjdeci ve bir uyarıcı olarak gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (33, 46, 'Allah’ın izniyle kendi yoluna çağıran bir davetçi ve aydınlatıcı bir kandil olarak gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (33, 47, 'Müminlere, kendileri için Allah’tan büyük bir lütuf olduğunu müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (33, 48, 'Kâfirlere ve münafıklara itaat etme! Eziyetlerine aldırma ve Allah''a tevekkül et. Vekil olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (33, 49, 'Ey iman edenler! Mümin kadınları nikahlayıp da, henüz zifafa girmeden önce onları boşarsanız, sizin için üzerlerine sayacağınız bir iddet yoktur. Kendilerine bağışta bulunarak onları güzellikle serbest bırakın.');
INSERT INTO verses (sura, aya, text) VALUES (33, 50, 'Ey Peygamber! Mehirlerini verdiğin hanımlarını, Allah’ın sana ganimet olarak verdiği ve elinin altında bulunan cariyeleri; amcanın, halanın, dayının ve teyzenin seninle beraber hicret eden kızlarını sana helâl kıldık. Bir de Peygamber kendisiyle evlenmek istediği takdirde, kendisini Peygamber''e hibe eden Mümine kadını, diğer Müminlere değil, sırf sana mahsus olmak üzere (helâl kıldık). Kuşkusuz biz, hanımları ve ellerinin altında bulunan cariyeleri hakkında Müminlere neyi farz kıldığımızı biliriz. (Bu hususta ne yapmaları gerektiğini onlara açıkladık) ki, sana bir zorluk olmasın. Allah; çok bağışlayıcıdır, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 51, 'Ey Peygamber! Onlardan dilediğini geriye bırakır, dilediğini de yanına alırsın. Bıraktığın hanımlarından arzu ettiğini tekrar yanına almanda, senin üzerine bir günah yoktur. Onların gözlerinin aydın olması, üzülmemeleri ve kendilerine verdiğinle hepsinin hoşnut olmaları için bu daha uygundur. Allah, kalplerinizde olan her şeyi bilir. Allah; hakkıyla bilendir, Halîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 52, 'Bundan sonra artık başka kadınlarla evlenmen, elinin altında bulunan cariyeler hariç güzellikleri hoşuna gitse bile bunların yerine başka hanımlar alman sana helâl değildir. Allah, her şeyi görür gözetir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 53, 'Ey iman edenler! Nebinin evlerine sizin için yemeğe izin verilmeden girmeyin. Yemek vaktini de beklemeye kalkışmayın, fakat davet olunduğunuzda girin. Yemek yediniz mi dağılın, söze dalmak için beklemeyin çünkü bu Nebiyi rahatsız etmekte ama o sizden utanmaktadır. Allah ise haktan utanmaz. Hanımlarından ihtiyacınız olan bir şey istediğinizde onlardan hicap/perde arkasından isteyin. Bu sizin kalbiniz için de, onların kalpleri için de daha temizdir. Sizin Allah’ın Rasulüne eziyet vermeniz de, ondan sonra zevcelerini nikâhlamanız da ebediyen olacak bir şey değildir. Çünkü bu Allah’ın yanında çok büyük bir iştir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 54, 'Bir şeyi açığa vursanız da gizleseniz de şüphesiz Allah, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 55, 'Onlara (Peygamber''in hanımlarına) babalarının, oğullarının, kardeşlerinin, kardeşlerinin oğullarının, kız kardeşlerinin oğullarının, kadınlarının (iman eden kadınların) ve ellerinin altında bulunan cariyelerinin yanında (örtüyü terk etmelerinde) bir günah yoktur. (Ey Peygamber hanımları!) Allah’tan sakının. Şüphesiz Allah, her şeye şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 56, 'Şüphesiz Allah ve melekleri Nebi’ye salat ederler. Ey Müminler siz de ona salat ve selam edin.');
INSERT INTO verses (sura, aya, text) VALUES (33, 57, 'Allah ve Peygamber’ine eza verenleri Allah, dünyada ve ahirette lanetlemiş ve onlara alçaltıcı bir azap hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 58, 'Mümin erkeklere ve Mümin kadınlara yapmadıkları bir şeyden dolayı eziyet edenler, şüphesiz bir iftira ve apaçık bir günah yüklenmişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 59, 'Ey Nebi zevcelerine, kızlarına ve Müminlerin hanımlarına de ki: “Cilbâblarını üzerlerine giysinler.” Bu onların tanınıp, incitilmemeleri için daha uygundur. Allah; çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 60, 'Münafıklar, kalplerinde hastalık olanlar ve Medine’de bozgunculuk yapıp asılsız haber yayanlar; eğer buna son vermezlerse, seni onlara musallat ederiz de sonra çevrende az bir zamandan fazla kalamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (33, 61, 'Lanete uğramış kimselerdir. Onlar nerede bulunurlarsa yakalanırlar ve oracıkta öldürülürler.');
INSERT INTO verses (sura, aya, text) VALUES (33, 62, '(Bu,) Daha önceden gelip geçenler hakkında Allah''ın sünnetidir. Allah''ın sünnetinde bir değişiklik bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (33, 63, 'İnsanlar senden kıyamet vaktini soruyorlar. De ki: "Onun ilmi Allah katındadır. Nereden bileceksin? Belki de kıyamet çok yakındır."');
INSERT INTO verses (sura, aya, text) VALUES (33, 64, 'Şüphesiz ki Allah, kâfirlere lanet etmiş ve onlar için alevli bir ateş hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 65, '(Onlar) orada ebedî olarak kalacaklar, (kendilerini koruyacak) ne bir dost ne de bir yardımcı bulacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (33, 66, 'Yüzleri ateşte evrilip çevrildiği gün: "Eyvah bize! Keşke Allah''a ve Rasûle itaat etseydik!" derler.');
INSERT INTO verses (sura, aya, text) VALUES (33, 67, '"Rabbimiz! Biz önderlerimize ve büyüklerimize itaat ettik (uyduk), onlar da bizi yoldan saptırdılar." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (33, 68, '"Rabbimiz! Onlara iki kat azap ver ve onları büyük bir lanete uğrat.”');
INSERT INTO verses (sura, aya, text) VALUES (33, 69, 'Ey iman edenler! Mûsâ’ya eziyet edenler gibi olmayın. Nihayet Allah; onu, onların söylediklerinden temize çıkardı. O, Allah katında itibarlı ve değerli bir kimseydi.');
INSERT INTO verses (sura, aya, text) VALUES (33, 70, 'Ey iman edenler! Allah’tan sakının ve doğru söz söyleyin.');
INSERT INTO verses (sura, aya, text) VALUES (33, 71, '(Böyle davranırsanız Allah) İşlerinizi düzeltir ve günahlarınızı bağışlar. Kim Allah ve Rasûlüne itaat ederse büyük bir kurtuluşa ermiş olur.');
INSERT INTO verses (sura, aya, text) VALUES (33, 72, 'Biz emaneti göklere, yere ve dağlara sunduk. Onu taşımaktan kaçındılar, ondan korktular. Onu insan yüklendi. Doğrusu o çok zalim ve çok cahildir.');
INSERT INTO verses (sura, aya, text) VALUES (33, 73, '(Allah bu emaneti insana vermek suretiyle) münafık erkeklere ve münafık kadınlara; Allah’a ortak koşan erkeklere ve Allah’a ortak koşan kadınlara azap edecek, Mümin erkeklerin ve Mümin kadınların da tövbelerini kabul buyuracaktır. Allah çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (34, 1, 'Hamt, göklerde ve yerde bulunanların hepsinin sahibi olan Allah’a mahsustur. Ahirette de hamt O’na mahsustur. O, hikmet sahibidir, (her şeyden) haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 2, 'Allah; yere gireni, yerden çıkanı; gökten ineni ve oraya yükseleni bilir. O; çok merhametlidir, çok bağışlayıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 3, 'Kâfirler: "Kıyamet bize gelmeyecek." dediler. De ki: "Hayır! Gaybı bilen Rabbim''e yemin olsun, o mutlaka size gelecektir. Göklerde ve yerde zerre miktarı bir şey bile O’ndan gizli değildir. Bundan daha küçük ve daha büyüğü de şüphesiz apaçık kitaptadır (yazılıdır)."');
INSERT INTO verses (sura, aya, text) VALUES (34, 4, 'Bu, iman edip salih amel işleyenleri mükâfatlandırması içindir. İşte Onlar için büyük bir mağfiret ve güzel bir rızık vardır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 5, 'Ayetlerimiz konusunda acze düşürmek için koşuşturanlar ise işte onlar için de en kötüsünden, pek acıklı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 6, 'Kendilerine ilim verilenler, Rabbinden sana indirilenin (Kur''an''ın) gerçek olduğunu bilir. O''nun, mutlak galip ve övgüye lâyık olan (Allah''ın) yoluna ilettiğini görürler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 7, 'Kâfir olanlar dediler ki: "Çürüyüp paramparça olduğunuz vakit yeniden dirileceğinizi söyleyerek haber veren kişiyi gösterelim mi?"');
INSERT INTO verses (sura, aya, text) VALUES (34, 8, '"Acaba o, yalan yere Allah''a iftira mı etmiştir? Yoksa onda delilik mi var?" (dediler). Hayır! Öyle değil! Ahirete iman etmeyenler azap içinde ve uzak bir sapıklıktadır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 9, 'Onlar önlerindeki ve arkalarındaki göğe ve yeryüzüne bakmıyorlar mı? Dilersek onları yere batırır veya gökten üzerlerine parçalar düşürürüz. İşte bunda, (Rabbine) ihlasla yönelen her kul için bir ayet/delil vardır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 10, 'Dâvud’a katımızdan bir lütuf verdik. "Ey dağlar ve kuşlar! Dâvud’la tespih edin." Onun için demiri de yumuşattık.');
INSERT INTO verses (sura, aya, text) VALUES (34, 11, '"Geniş zırhlar imal et, dokumasını ölçülü yap. (Ey Dâvud hanedanı!) Salih ameller işleyin! Kuşkusuz ben, yaptıklarınızı hakkıyla görmekteyim." diye (vahyettik).');
INSERT INTO verses (sura, aya, text) VALUES (34, 12, 'Süleyman''a da sabah gidişi bir ay, akşam dönüşü bir ay(lık mesafe) olan rüzgârı (boyun eğdirdik). Onun için erimiş bakır madenini sel gibi akıttık. Cinlerden de, Rabbinin izniyle onun emrinde çalışanlar vardı. Onlardan kim emrimizden sapacak olsa ona şiddetli azaptan tattırırdık.');
INSERT INTO verses (sura, aya, text) VALUES (34, 13, 'Cinler, Süleyman için dilediği biçimde kaleler, heykeller, havuz gibi çanaklar ve sabit kazanlar yapıyorlardı. Ey Dâvud ailesi! Şükür için çalışın. Kullarımdan şükredenler pek azdır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 14, 'Süleyman''ın ölümüne hükmettiğimiz zaman, onun öldüğünü ancak değneğini yiyen bir ağaç kurdu gösterdi. (Sonunda yere) yıkılınca, anlaşıldı ki cinler gaybı bilselerdi o küçük düşürücü azap içinde kalmazlardı.');
INSERT INTO verses (sura, aya, text) VALUES (34, 15, 'Andolsun, Sebe kavmi için oturduğu yerlerde büyük bir ibret vardır. Biri sağda, diğeri solda iki bahçeleri vardı. (Onlara:) "Rabbinizin rızkından yiyin ve O''na şükredin. İşte güzel bir memleket ve çok bağışlayan bir Rab!"');
INSERT INTO verses (sura, aya, text) VALUES (34, 16, 'Ancak onlar yüz çevirdiler, böylece biz de onlara Arîm (her şeyi yıkıp süpüren azap) selini gönderdik ve onların iki bahçelerini, buruk yemişli, acı ılgınlı ve içinde az sayıda Sedir ağacı bulunan iki bahçeye dönüştürdük.');
INSERT INTO verses (sura, aya, text) VALUES (34, 17, 'İşte nankörlük etmeleri sebebi ile biz onları böyle cezalandırdık. Biz (bu şekilde) ancak nankörleri cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (34, 18, 'Kendileri (Sebe) ile içlerinde bereketler kıldığımız memleketler (Şam) arasında (birbirine yakın) görünebilen memleketler var ettik. İçlerinde yolculuğu ölçülü kıldık/konaklara ayırdık ve; “Oralarda geceleri ve gündüzleri güvenlik içinde gezip dolaşın." (dedik).');
INSERT INTO verses (sura, aya, text) VALUES (34, 19, '“Rabbimiz yolculuklarımız arasını uzaklaştır” diye dua ettiler ve kendi nefislerine zulmettiler. Biz de onları, ibret kıssaları haline getirdik ve onları büsbütün parçaladık. Şüphesiz bunda, çok sabreden ve çok şükreden herkes için ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 20, 'Andolsun ki İblis onlar hakkındaki zannını doğru çıkardı. Böylece Müminlerden bir grup dışında (hepsi) ona uydular.');
INSERT INTO verses (sura, aya, text) VALUES (34, 21, 'Oysa Şeytan''ın onlar üzerinde hiçbir hâkimiyeti yoktu. Ancak ahirete iman edenleri, onun hakkında şüphe içinde bulunanlardan ayırt edelim diye (ona bu fırsatı verdik). Rabbin; her şeyi koruyandır, muhafaza edendir.');
INSERT INTO verses (sura, aya, text) VALUES (34, 22, '(Ey Muhammed!) De ki: “Allah’ı bırakıp da ilah olduklarını iddia ettiklerinize dua edin. Onlar ne göklerde ne de yerde bir zerre ağırlığınca bir şeye sahiptirler. Onların yerde ve gökte hiçbir ortaklıkları yoktur. Allah’ın onlardan bir yardımcısı da yoktur."');
INSERT INTO verses (sura, aya, text) VALUES (34, 23, 'Allah’ın huzurunda, kendisinin izin verdiği kimselerden başkasının şefaati fayda vermez. Nihayet onların yüreklerinden korku giderilince: "Rabbiniz ne buyurdu?" derler. Onlar da: "Hak olanı buyurdu." derler. O; yüksektir/yücedir, büyüktür.');
INSERT INTO verses (sura, aya, text) VALUES (34, 24, 'De ki: "Göklerden ve yerden size rızık veren kimdir?" De ki: "Allah! O halde biz veya siz, ikimizden biri ya doğru yol üzerinde veya açık bir sapıklık içindedir."');
INSERT INTO verses (sura, aya, text) VALUES (34, 25, 'De ki: "Siz, bizim işlemiş bulunduğumuz suçtan sorulacak değilsiniz ve biz de sizin yapmakta olduklarınızdan sorulacak değiliz."');
INSERT INTO verses (sura, aya, text) VALUES (34, 26, 'De ki: "Rabbimiz hepimizi bir araya toplayacak, sonra aramızda hak ile hükmedecektir. O, hüküm veren, (her şeyi) hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (34, 27, 'De ki: O’na ortak koştuklarınızı bana gösterin. Asla gösteremezsiniz. Bilâkis yegâne galip ve her şeyi hikmetle idare eden ancak Allah''tır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 28, 'Biz, seni bütün insanlara ancak müjdeleyici ve uyarıcı olarak gönderdik. Fakat insanların çoğu bunu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 29, '"Eğer, doğru söylüyorsanız bu vaat/tehdit ne zaman gerçekleşecek?" derler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 30, 'De ki: “Sizin vaat olunan bir gününüz vardır. Ondan ne bir an geri kalırsınız, ne de ileri geçersiniz.”');
INSERT INTO verses (sura, aya, text) VALUES (34, 31, 'Kâfir olanlar dediler ki: “Biz bu Kur’ân’a da, bundan önce gelen kitaplara da iman etmeyiz.” Sen o zalimleri Rableri huzurunda durdurulmuş, sözü birbirlerine döndürürlerken bir görsen. Güçsüz bırakılan tabiler, büyüklük taslayanlara: “Siz olmasaydınız, biz elbette iman edenler olurduk” derler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 32, 'Büyüklük taslayanlar da zayıflara: "Size, hidayet geldikten sonra biz mi engel olduk? Hayır, siz zaten günahkârlar idiniz." derler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 33, 'Zayıf düşürülenler de büyüklenenlere: "Hayır gece gündüz hileler kuruyor; bize Allah''ı inkâr etmemizi ve O''na eşler koşmamızı emrediyordunuz" derler. Azabı gördüklerinde pişmanlıklarını açığa vururlar. Biz de kâfirlerin boyunlarına halkalar dolarız. Onlar işlediklerinden başka bir şeyle mi cezalandırılırlar?');
INSERT INTO verses (sura, aya, text) VALUES (34, 34, 'Biz hangi ülkeye bir uyarıcı göndermişsek mutlaka oranın varlıklı ve şımarık kişileri: "Biz size gönderilmiş olan şeyi inkâr ediyoruz." demişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (34, 35, 'Yine; “Bizim mallarımız ve çocuklarımız daha çoktur. Bize azap edilmeyecektir.” demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (34, 36, 'De ki: “Şüphesiz Rabbim, rızkı dilediğine bol verir ve (dilediğine) kısar. Fakat insanların çoğu bilmezler.”');
INSERT INTO verses (sura, aya, text) VALUES (34, 37, 'Bizim katımızda sizi (bize) yaklaştıracak olan ne mallarınız, ne de evlatlarınızdır. Ancak iman edip salih amellerde bulunanlar başka. İşte onlar için işlediklerine karşılık kat kat mükâfat vardır. Onlar Cennet köşklerinde güven içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 38, 'Ayetlerimiz konusunda acze düşürmek için koşuşturanlara gelince işte onlar da azabın içine getirilirler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 39, 'De ki: "Rabbim, kullarından dilediğine bol rızık verir ve (dilediğinden de) kısar. Allah yolunda her ne harcarsanız, Allah onun yerine başkasını verir. O, rızık verenlerin en hayırlısıdır."');
INSERT INTO verses (sura, aya, text) VALUES (34, 40, 'O gün onların hepsini biraraya toplar sonra meleklere: "Bunlar size mi tapıyorlardı?" der.');
INSERT INTO verses (sura, aya, text) VALUES (34, 41, 'Melekler diyecekler ki: “Tenzih ederiz seni! Bizim velimiz onlar değil, sensin. Aksine onlar cinlere ibadet ediyorlardı. Bunların çoğu onlara iman ediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (34, 42, 'Bugün birbirinize ne fayda, ne de zarar vermeye gücünüz yeter. Biz zalim olanlara; "Yalanlamakta olduğunuz ateş azabını tadın!" deriz.');
INSERT INTO verses (sura, aya, text) VALUES (34, 43, 'Ayetlerimiz açık açık onlara okunduğunda dediler ki: “Bu ancak atalarınızın ibadet ede geldiği şeylerden sizi alıkoymak isteyen bir adamdır.” Yine dediler ki: “Bu uydurulmuş bir yalandan başka bir şey değildir.” Kâfir olanlar hakka kendilerine geldiğinde: “Bu ancak apaçık bir büyüdür” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (34, 44, 'Hâlbuki biz onlara okuyacakları kitaplar göndermemiştik. Senden önce onlara bir uyarıcı da göndermemiştik.');
INSERT INTO verses (sura, aya, text) VALUES (34, 45, 'Onlardan öncekiler de (ilâhî bildirimleri) yalan saymışlardı. Bunlar (şimdikiler) onlara verdiklerimizin onda birine bile ulaşamadılar. Buna rağmen onlar peygamberlerimi yalancılıkla itham etmişlerdi. Ben de bilseniz onları nasıl cezalandırdım!');
INSERT INTO verses (sura, aya, text) VALUES (34, 46, 'De ki: “Ben size ancak bir öğüt veriyorum: Yalnızca Allah için ikişer ikişer, birer birer kalkınız. Sonra bu arkadaşınızda bir delilik olmadığını düşününüz. O ancak şiddetli bir azabın öncesinde sizi uyaran bir peygamberdir”');
INSERT INTO verses (sura, aya, text) VALUES (34, 47, 'De ki: "Ben sizden bir ücret istemiyorum. O, sizin olsun. Benim ecrim ancak her şeye şahid olan Allah’a aittir."');
INSERT INTO verses (sura, aya, text) VALUES (34, 48, 'De ki: "Rabbim; hak olanı (batılın üzerine) bırakır, bütün gaybleri tamamıyla bilendir."');
INSERT INTO verses (sura, aya, text) VALUES (34, 49, 'De ki: "Hak geldi, batıl ne bir şey ortaya çıkarabilir, ne de geri getirebilir."');
INSERT INTO verses (sura, aya, text) VALUES (34, 50, 'De ki: "Eğer yoldan saparsam, kendi aleyhime sapmış olurum. Eğer hidayete erersem, bu ise Rabbimin bana vahyetmesi sebebiyledir. Şüphesiz O; hakkıyla işitendir, pek yakındır."');
INSERT INTO verses (sura, aya, text) VALUES (34, 51, '(Rasûlüm!) Korkuya düştükleri zaman, onları bir görsen! Artık kurtuluş yoktur, yakın bir yerden yakalanmışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (34, 52, '(İş işten geçtikten sonra:) “Ona iman ettik” diyecekler ama uzak yerden (dünya hayatı gelip geçtikten sonra) imana ulaşıp, kavuşmaları ne mümkün?');
INSERT INTO verses (sura, aya, text) VALUES (34, 53, 'Hâlbuki daha önce onu (hakkı) inkâr etmişlerdi. Uzak bir yerden gayp hakkında atıp tutuyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (34, 54, 'Artık, bundan önce benzerlerine yapıldığı gibi, kendileriyle arzu ettikleri şey arasına perde çekilmiştir. Şüphesiz onlar (dünyada iken), kendilerini endişeye düşüren bir şüphe içindeydiler.');
INSERT INTO verses (sura, aya, text) VALUES (35, 1, 'Hamt, göklerin ve yerin yaratıcısı ve melekleri ikişer, üçer ve dörder kanatlı elçiler yapan Allah’a mahsustur. O, yaratmada dilediğini arttırır. Şüphesiz, Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (35, 2, 'Allah''ın insanlara açtığı rahmeti tutacak yoktur. O''nun tuttuğunu da ondan sonra salacak yoktur. O; mutlak güç sahibidir, hüküm ve hikmet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 3, 'Ey insanlar! Allah’ın üzerinizdeki nimetini hatırlayın. Allah’tan başka size gökten ve yerden rızık verecek bir yaratıcı var mı? O’ndan başka (hak) ilah yoktur. Nasıl oluyor da (tevhidden şirke) çevriliyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (35, 4, 'Eğer seni yalanlıyorlarsa doğrusu senden önce de nice rasuller yalanlanmıştır. Bütün işler ancak Allah’a döndürülür.');
INSERT INTO verses (sura, aya, text) VALUES (35, 5, 'Ey insanlar! Şüphe yok ki Allah’ın vaadi haktır. O halde sakın sizi dünya hayatı aldatmasın ve çok aldatıcı da sakın sizi Allah ile aldatmasın.');
INSERT INTO verses (sura, aya, text) VALUES (35, 6, 'Şüphe yok ki Şeytan; sizin düşmanınızdır, siz de onu düşman sayın. O, kendi taraftarlarını ancak ateş ehlinden olmaya çağırır.');
INSERT INTO verses (sura, aya, text) VALUES (35, 7, 'Kâfirler için şiddetli bir azap vardır. İman edenler ve salih amellerde bulunanlar için mağfiret ve büyük bir mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (35, 8, 'Kötü ameli kendine süslü gösterilen ve böylece onu güzel gören kimse (doğru yolda olanla bir midir)? Şüphesiz Allah dilediğini sapıklığa düşürür dilediğini de doğru yola eriştirir. Öyleyse nefsin onlara karşı hasretlere (üzüntülere) kapılmasın. Şüphesiz Allah onların yaptıklarını bilmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 9, 'Rüzgârları gönderip de bulutu harekete geçiren Allah’tır. Biz, onu ölü bir bölgeye göndeririz de ölümünden sonra toprağa onunla hayat veririz. Ölülerin yeniden dirilmesi de böyle olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (35, 10, 'Kim, izzet istiyorsa, bilsin ki izzet tümüyle Allah’ındır. Güzel söz O''na yükselir. Salih amel de onu yükseltir. Kötülüklerle tuzak kuranlar onlar için çok şiddetli bir azap vardır ve bizzat onların tuzağı boşa çıkar.');
INSERT INTO verses (sura, aya, text) VALUES (35, 11, 'Allah, sizi (önce) topraktan sonra nutfe/meniden yaratmıştır. Sonra sizi çiftler kıldı. Onun ilmi dışında hiçbir dişi ne hamile kalır, ne de doğurur. Bir canlıya ömür verilmesi de, onun ömründen azaltılması da mutlaka bir kitaptadır. Şüphesiz ki bu Allah’a göre pek kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (35, 12, 'İki deniz birbirine eşit olmaz. Bu tatlıdır, susuzluğu keser, içilmesi kolaydır. Şu da tuzludur, acıdır. Hepsinden de taze et yersiniz ve giyeceğiniz süs eşyası çıkarırsınız. Allah''ın lütfuyla rızık aramanız için gemilerin onu yararak gittiğini görürsün. Belki artık şükredersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (35, 13, 'Geceyi gündüze katar, gündüzü de geceye katar. Güneş''i ve Ay''ı emri altına almıştır. Her biri belirli bir süreye kadar akıp giderler. İşte sizin Rabbiniz Allah’tır. Mülk O’nundur. O’ndan başka dua ettikleriniz, bir çekirdeğin zarına bile sahip değillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 14, 'Onlara dua etseniz bile sizin duanızı duymazlar, duysalar da size cevap veremezler. Kıyamet günü sizin ortak koşmanızı inkâr ederler. (Bu gerçeği) sana, her şeyden haberi olan (Allah) gibi hiç kimse haber veremez.');
INSERT INTO verses (sura, aya, text) VALUES (35, 15, 'Ey insanlar! Allah''a muhtaç olanlar sizlersiniz. Allah zengin ve övülmeye lâyık olandır.');
INSERT INTO verses (sura, aya, text) VALUES (35, 16, 'Allah dilerse sizi yok eder ve yerinize yeni bir halk getirir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 17, 'Bu Allah’a zor değildir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 18, 'Hiçbir günahkâr başkasının günahını yüklenmez. Yükü (günahı) ağır gelen kimse onu taşımak için (başkasını) çağırsa, bu çağırdığı akrabası da olsa onun yükünden bir şey yüklenmez. Sen ancak, görmeden Rablerinden korkanları ve namazı dosdoğru kılanları uyarırsın. Kim günâh kirinden arınırsa, kendisi için arınmış olur. Dönüş ancak Allah''adır.');
INSERT INTO verses (sura, aya, text) VALUES (35, 19, 'Körle gören bir değildir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 20, 'Ve karanlık ile aydınlık da bir değildir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 21, 'Ve gölge ile sıcaklık da bir değildir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 22, 'Dirilerle ölüler de bir değildir. Allah dilediğine işittirir. Sen kabirlerde olanlara işittiremezsin.');
INSERT INTO verses (sura, aya, text) VALUES (35, 23, 'Sen sadece bir uyarıcısın.');
INSERT INTO verses (sura, aya, text) VALUES (35, 24, 'Biz seni hak üzere müjdeleyici ve korkutucu olarak gönderdik. Hiç bir ümmet yoktur ki içinde bir uyarıcı geçmiş olmasın.');
INSERT INTO verses (sura, aya, text) VALUES (35, 25, 'Eğer seni yalanlıyorlarsa onlardan öncekiler de yalanlamışlardı. Rasulleri onlara apaçık delillerle, sahifelerle ve nur saçan kitaplarla gelmişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (35, 26, 'Sonra kâfir olanları yakaladım. Şimdi onlara inkârım nasılmış?');
INSERT INTO verses (sura, aya, text) VALUES (35, 27, 'Allah’ın gökten su indirdiğini ve onunla çeşitli renklerde ürünler çıkardığımızı görmüyor musun? Dağlardan (geçen) beyaz, kırmızı, değişik renklerde ve simsiyah yollar (yaptık).');
INSERT INTO verses (sura, aya, text) VALUES (35, 28, 'İnsanlardan, hayvanlardan ve davarlardan da yine böyle türlü renkte olanlar var. Kulları içinden ancak âlimler, Allah''tan (gereğince) korkar. Şüphesiz Allah Azîzdir, Gafûrdur.');
INSERT INTO verses (sura, aya, text) VALUES (35, 29, 'Allah''ın kitabını okuyanlar, namazı dosdoğru kılanlar ve bizim kendilerine rızık olarak verdiklerimizden Allah yolunda gizli ve açık sarfedenler asla zarar etmeyecek bir ticaret umarlar.');
INSERT INTO verses (sura, aya, text) VALUES (35, 30, 'Çünkü Allah, onların mükâfatlarını tam öder ve lütfundan onlara fazlasını da verir. Şüphesiz O; çok bağışlayan Şekûr''dur. (Karşılığı bol bol verendir.)');
INSERT INTO verses (sura, aya, text) VALUES (35, 31, 'Sana vahyettiğimiz kitap (Kur’an), kendinden öncekini tasdik eden hak kitaptır. Şüphesiz Allah, (kullarından) hakkıyla haberdardır. Onları hakkıyla görür.');
INSERT INTO verses (sura, aya, text) VALUES (35, 32, 'Sonra bu kitaba, kullarımızdan seçtiğimizi mirasçı kılarız. Onlardan (insanlardan) kimi kendisine zulmeder, kimi ortadadır, kimi de Allah’ın izniyle hayırlarda öne geçmek için yarışır. İşte büyük fazilet budur.');
INSERT INTO verses (sura, aya, text) VALUES (35, 33, '(Onların mükâfatı), içine girecekleri Adn Cennetleri''dir. Orada altın bilezikler ve incilerle süslenirler. Orada giyecekleri elbiseleri de ipektir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 34, '"Hamdolsun bizden korkuyu gideren Allah’a!" derler. Şüphesiz Rabbimiz çok bağışlayıcı Şekûr''dur (Karşılıkları bol bol verir).');
INSERT INTO verses (sura, aya, text) VALUES (35, 35, 'Çünkü lütfu ile bizi kalıcı yurda (Cennet''e) yerleştirdi. Bize orada ne bir yorgunluk ne de bir bıkkınlık dokunur.');
INSERT INTO verses (sura, aya, text) VALUES (35, 36, 'O kâfirlere gelince, onlar için Cehennem ateşi vardır. Orada canları alınmaz ki ölsünler. Kendilerinden onun azabı da hafifletilmez. İşte biz, küfürde ileri giden her nankörü böyle cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (35, 37, 'Onlar orada: "Rabbimiz! Bizi çıkar, (önce) yaptığımızın yerine salih ameller işleyelim!" diye feryad ederler. Size düşünecek kimsenin düşünebileceği kadar bir ömür vermedik mi? Size uyarıcı da gelmedi mi? Şimdi tadın (azabı)! Zalimlerin yardımcısı yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (35, 38, 'Allah, göklerin ve yerin gaybını bilendir. O, kalplerin içinde ne varsa onu da hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 39, 'O sizi yeryüzünde halifeler yapandır. Artık kim kâfir olursa kâfir olması kendi aleyhinedir. Kâfirlere kâfirlikleri Rablerinin nezdinde aşırı bir gazaptan başka bir şey arttırmaz. Kâfirlere kâfirlikleri zarardan başka birşey arttırmaz.');
INSERT INTO verses (sura, aya, text) VALUES (35, 40, 'De ki: "Allah''ı bırakıp da dua ettiğiniz ortaklarınızı gördünüz mü? Gösterin bana! Onlar yerdeki hangi şeyi yaratmışlardır? Yoksa onların göklerde mi bir ortaklıkları var? Yoksa onlara bir kitap verildi de, ondan bir delile mi dayanıyorlar?" Hayır! Zalimler birbirlerini aldatmaktan başka bir vaadde bulunmuyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (35, 41, 'Yok olmaması için gökleri ve yeri Allah tutar. Göklerin ve yerin sonu gelirse, O’ndan başka onları kimse tutamaz. Allah; Halim''dir, çokça bağışlayandır.');
INSERT INTO verses (sura, aya, text) VALUES (35, 42, 'Kendilerine bir uyarıcı (peygamber) gelirse, ümmetler içinde en doğru yolda olacaklarına, dair bütün güçleriyle Allah’a yemin ettiler. Fakat onlara uyarıcı (Muhammed -sallallahu aleyhi ve sellem-) gelince; bu, onların haktan uzaklaşmalarından başka bir şeyi arttırmadı.');
INSERT INTO verses (sura, aya, text) VALUES (35, 43, 'Çünkü onlar yeryüzünde büyüklük taslıyor ve kötü tuzaklar kuruyorlardı. Kötü tuzak ise ancak sahibine dolanır. Onlar ancak öncekilere uygulanan sünneti bekliyorlar. Sen Allah’ın sünnetinde hiçbir değişiklik bulamazsın. Allah''ın sünnetinde kesinlikle bir sapma da bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (35, 44, 'Onlar, yeryüzünde gezip de kendilerinden öncekilerin sonunun nasıl olduğunu görmediler mi? Hâlbuki onlar, bunlardan daha güçlü idiler. Allah’ı göklerde ve yerde aciz bırakacak hiçbir şey yoktur. O, her şeyi hakkıyla bilendir, her şeye hakkıyla kâdirdir.');
INSERT INTO verses (sura, aya, text) VALUES (35, 45, 'Eğer Allah insanları işlediklerinden dolayı hemen yakalayıp cezalandırsaydı onun (yerin) üzerinde bir tek canlı bırakmazdı. Fakat onları belirli bir süreye kadar ertelemektedir. Ecelleri geldiğinde artık muhakkak ki Allah kullarını görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 1, 'Yâ Sîn.[1]');
INSERT INTO verses (sura, aya, text) VALUES (36, 2, 'Hakîm olan Kur''an''a yemin olsun!');
INSERT INTO verses (sura, aya, text) VALUES (36, 3, 'Şüphesiz sen elbette gönderilen rasûllerdensin.');
INSERT INTO verses (sura, aya, text) VALUES (36, 4, 'Dosdoğru bir yol üzerinesin.');
INSERT INTO verses (sura, aya, text) VALUES (36, 5, '(Bu Kur''an) üstün, güçlü ve çok merhametli olan (Allah) tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 6, 'Ataları uyarılmamış, bu yüzden kendileri de gaflet içinde kalmış bir toplumu uyarman için (bu kitap indirilmiştir.)');
INSERT INTO verses (sura, aya, text) VALUES (36, 7, 'Andolsun, onların çoğu üzerine o söz (azap) hak olmuştur. Artık onlar iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 8, 'Biz, onların boyunlarına halkalar geçirdik. O halkalar çenelere kadar dayanmaktadır. Bu yüzden başları yukarı kalkıktır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 9, 'Biz onların önlerine bir set, arkalarına da bir set çektik. Böylelikle onları örtüverdik, artık görmezler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 10, 'Kâfirlere gelince; onları uyarsan da uyarmasan da birdir, iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 11, 'Sen, ancak zikre (Kur''an''a) uyan ve görmeden Rahman''dan korkan kimseyi uyarabilirsin. İşte böylesini bir mağfiret ve güzel bir mükâfatla müjdele.');
INSERT INTO verses (sura, aya, text) VALUES (36, 12, 'Muhakkak biz ölüleri diriltiriz. Onların ileri gönderdiklerini de, geride bıraktıklarını (izlerini) da yazarız. Biz, her şeyi apaçık bir kitapta (Levh-i Mahfûz''da) sayıp yazmışızdır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 13, 'Onlara, şu şehir halkını misal getir: Hani onlara elçiler gelmişti.');
INSERT INTO verses (sura, aya, text) VALUES (36, 14, 'Hani onlara iki elçi göndermiştik de onları yalanlamışlardı. Bir üçüncüsü ile onlara destek vermiştik. (Onlar:) "Biz, size gönderilen elçileriz." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (36, 15, 'Elçilere dediler ki: Siz de ancak bizim gibi birer insansınız. Rahman, herhangi bir şey indirmedi. Siz sadece yalan söylüyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (36, 16, 'Elçiler ise: "Rabbimiz biliyor ki biz, size gönderilen elçileriz." diye karşılık verdiler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 17, '"Bizim görevimiz apaçık tebliğden başka bir şey değildir."');
INSERT INTO verses (sura, aya, text) VALUES (36, 18, 'Onlar dediler ki: "Doğrusu siz, bize uğursuz geldiniz. Eğer bu işe bir son vermezseniz, sizi taşlarız ve bizden size acı bir azap dokunur."');
INSERT INTO verses (sura, aya, text) VALUES (36, 19, '(Elçiler) dediler ki: "Sizin uğursuzluğunuz kendinizdendir. Size öğüt verildi diye mi (uğursuzluğa uğradınız)? Doğrusu siz çok ileri giden bir topluluksunuz".');
INSERT INTO verses (sura, aya, text) VALUES (36, 20, 'Derken beldenin öbür ucundan bir adam koşarak geldi ve; "Ey kavmim! Bu elçilere uyunuz." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (36, 21, 'Sizden herhangi bir ücret istemeyen bu kimselere tabi olun. Çünkü onlar hidayete ermiş kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 22, 'Ben, beni yaratana ne diye ibadet etmeyecekmişim? Üstelik siz yalnız ona döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (36, 23, '“O’nu bırakıp da başka ilahlar mı edineyim? Eğer Rahman; bana bir zarar vermek istese, onların şefaati bana hiçbir fayda sağlamaz ve beni kurtaramazlar.”');
INSERT INTO verses (sura, aya, text) VALUES (36, 24, 'Bu takdirde ben muhakkak apaçık bir sapıklık içinde olurum.');
INSERT INTO verses (sura, aya, text) VALUES (36, 25, '"Şüphesiz ben; Rabbinize iman ettim. Beni dinleyin!"');
INSERT INTO verses (sura, aya, text) VALUES (36, 26, 'Ona: "Cennet''e gir!" denildi. O da: "Keşke kavmim bilseydi." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (36, 27, '"Rabbimin beni bağışladığını ve beni ikrama layık kimselerden kıldığını."');
INSERT INTO verses (sura, aya, text) VALUES (36, 28, 'Kendisinden sonra kavmi üzerine (onları cezalandırmak için) gökten hiçbir ordu indirmedik. İndirecek de değildik.');
INSERT INTO verses (sura, aya, text) VALUES (36, 29, '(Onları helâk eden) Korkunç sesten başka bir şey değildi. Bir anda sönüp gittiler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 30, 'Yazıklar olsun o kullara! Ne zaman kendilerine bir peygamber gelse muhakkak onunla alay ederlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (36, 31, 'Kendilerinden önce nice nesilleri helâk ettiğimizi görmüyorlar mı? Onların artık kendilerine dönmeyeceklerini görmediler mi?');
INSERT INTO verses (sura, aya, text) VALUES (36, 32, 'Ve hepsi toplanıp huzurumuza çıkarılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 33, 'Ölü toprak onlar için bir delildir. Biz, onu diriltir ve ondan taneler çıkarırız da onlardan yerler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 34, 'Biz, yeryüzünde nice hurma bahçeleri, üzüm bağları yarattık ve oralarda birçok pınarlar fışkırttık.');
INSERT INTO verses (sura, aya, text) VALUES (36, 35, 'Ürünlerinden ve yetiştirdiklerinden yesinler diye. Hâlâ şükretmiyorlar mı?');
INSERT INTO verses (sura, aya, text) VALUES (36, 36, 'Yerin bitirdiklerinden, kendi nefislerinden ve daha bilmedikleri şeylerden bütün çiftleri yaratan (Allah) çok münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 37, 'Gece de kendileri için bir delildir. Gündüzü ondan sıyırarak çekip alırız. Bir de bakarsın ki karanlık içinde kalmışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 38, 'Güneş de kendi yörüngesinde akıp gitmektedir. İşte bu, Azîz ve Alîm olan Allah''ın takdiridir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 39, 'Ay için de birtakım menziller (yörüngeler) tayin ettik. Nihayet o, eğri hurma dalı gibi (hilâl) olur da geri döner.');
INSERT INTO verses (sura, aya, text) VALUES (36, 40, 'Ne Güneş Ay''a yetişebilir, ne de gece gündüzü geçebilir. Her biri bir yörüngede yüzmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 41, 'Onların soylarını dolu gemide taşımamız da onlar için bir delildir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 42, 'Ve onlar için bindikleri daha başka taşıtlar da yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (36, 43, 'Eğer dilersek, onları suda boğarız da kimse de yardımlarına gelemez. İşte o zaman onlar için bir kurtuluş da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (36, 44, 'Ancak bizim tarafımızdan bir rahmet ve belli bir zamana kadar dünyadan faydalandırmamız müstesnadır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 45, 'Önünüzdekinden ve arkanızdakinden (dünya ve ahiret azabından) sakının. Umulur ki, size merhamet olunur denildiğinde (yüz çevirirler).');
INSERT INTO verses (sura, aya, text) VALUES (36, 46, 'Onlara, ne zaman Rablerinin ayetlerinden bir ayet gelse mutlaka ondan yüz çevirirler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 47, 'Kendilerine; "Allah’ın size verdiği rızıklardan infak edin!" denildiği zaman kâfirler, iman edenlere derler ki; "Allah''ın dilediği takdirde yedirip doyuracağı kişiyi acaba biz mi doyuracağız? Gerçekten siz apaçık bir sapıklık içindesiniz.”');
INSERT INTO verses (sura, aya, text) VALUES (36, 48, '"Eğer, doğru söylüyorsanız bu vaat/tehdit ne zaman?" derler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 49, 'Onlar, birbirleriyle çekişip dururken kendilerini ansızın yakalayacak korkunç bir sesi bekliyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (36, 50, 'İşte o anda onlar; ne bir vasiyette bulunabilirler, ne de ailelerine dönebilirler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 51, 'Sur''a üflenince, hemen kabirlerinden Rablerine doğru koşarak çıkarlar.');
INSERT INTO verses (sura, aya, text) VALUES (36, 52, '"Eyvah bize! Mezarımızdan bizi kim kaldırdı? Bu, Rahman''ın vadettiğidir. Peygamberler, gerçekten doğru söylemiştir." derler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 53, 'Sadece korkunç bir ses olur. Bunun üzerine onların hepsi hemen huzurumuzda hazır bulunurlar.');
INSERT INTO verses (sura, aya, text) VALUES (36, 54, 'O günde hiçbir kimseye en ufak bir zulüm yapılmaz. Siz işlediğinizin ancak karşılığını görürsünüz.');
INSERT INTO verses (sura, aya, text) VALUES (36, 55, 'Doğrusu bugün, cennetlikler eğlenceyle meşguldürler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 56, 'Kendileri ve eşleri gölgeliklerde, tahtlar üzerine yaslanmışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 57, 'Orada, onlar için meyveler vardır. Canlarının istediği her şey onlarındır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 58, 'Rahim olan Rabden sözlü bir selam vardır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 59, 'Ey günahkârlar! Bugün siz (bir tarafa) ayrılın!');
INSERT INTO verses (sura, aya, text) VALUES (36, 60, '"Ey Ademoğulları! Size, Şeytan''a ibadet etmeyin. Çünkü o, sizin apaçık düşmanınızdır." deyip söz almadım mı?');
INSERT INTO verses (sura, aya, text) VALUES (36, 61, 'Bana ibadet edin. Dosdoğru yol budur, demedim mi?');
INSERT INTO verses (sura, aya, text) VALUES (36, 62, 'O, sizden çoğu toplumları saptırmıştı. Hiç mi akıl erdirmiyordunuz?');
INSERT INTO verses (sura, aya, text) VALUES (36, 63, 'İşte bu, size vadedilen Cehennem''dir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 64, 'Küfrünüz (İnkârınız) sebebiyle bugün girin oraya!');
INSERT INTO verses (sura, aya, text) VALUES (36, 65, 'O gün onların ağızlarını mühürleriz. Yaptıklarını bizlere elleri anlatır, ayakları da şahitlik eder.');
INSERT INTO verses (sura, aya, text) VALUES (36, 66, 'Dileseydik; gözlerini silme kör ederdik de, o zaman doğru yolu bulmaya koşuşurlardı. Fakat nasıl görecekler ki?');
INSERT INTO verses (sura, aya, text) VALUES (36, 67, 'Eğer dilesek; oldukları yerde onların şekillerini değiştirirdik de, ne ileriye gitmeye güçleri yeterdi, ne de geri gelmeye.');
INSERT INTO verses (sura, aya, text) VALUES (36, 68, 'Kime uzun ömür verirsek onu yaratılışında tersine döndürürüz. Hâlâ akletmiyorlar mı?');
INSERT INTO verses (sura, aya, text) VALUES (36, 69, 'Ona şiir öğretmedik, ona yakışmaz da. Bu, yalnızca bir öğüt ve apaçık Kur’an’dır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 70, '(Kur''an,) Diri olanları uyarıp korkutmak ve küfre sapanların üzerine sözün hak olması için (indirilmiştir).');
INSERT INTO verses (sura, aya, text) VALUES (36, 71, 'Kendi elimizle onlar için yarattığımız hayvanları görmüyorlar mı? (Bu sayede) Onlar bunlara sahip olmuşlardır.');
INSERT INTO verses (sura, aya, text) VALUES (36, 72, 'O hayvanları, onların emrine verdik. Onlardan kimine biniyorlar, kiminin de etini yiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (36, 73, 'O hayvanlarda, insanlar için daha başka faydalar ve içecekler vardır. Hâlâ şükretmiyorlar mı?');
INSERT INTO verses (sura, aya, text) VALUES (36, 74, 'Belki yardım görürler diye Allah''tan başka ilahlar edindiler.');
INSERT INTO verses (sura, aya, text) VALUES (36, 75, 'Onlar, kendilerine yardımda bulunmaya güç yetiremezler. Aksine kendileri onlar için hazırlanmış askerlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 76, 'Artık onların sözleri seni üzmesin. Biz onların gizlediklerini de açıkladıklarını da elbette biliyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (36, 77, 'İnsan, kendisini bir nutfeden yarattığımızı görmüyor mu? Derken, o apaçık bir düşman kesiliverir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 78, 'Kendi yaratılışını unutup, bize örnek veriyor: "Bu çürümüş kemikleri kim diriltebilir?" diyor.');
INSERT INTO verses (sura, aya, text) VALUES (36, 79, 'De ki: "Onları ilk defa yaratan diriltecek. O, her yaratılmışı hakkıyla bilendir."');
INSERT INTO verses (sura, aya, text) VALUES (36, 80, 'Yeşil ağaçtan sizin için ateş çıkaran O’dur. İşte siz ateşi ondan yakıyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (36, 81, 'Gökleri ve yeri yaratan onların bir benzerini yaratmaya güç yetiremez mi? Evet, elbette kadirdir. O hakkıyla yaratıcıdır ve her şeyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 82, 'Bir şeyi dilediği zaman, O''nun emri yalnızca: ''Ol!'' demesidir. O da hemen oluverir.');
INSERT INTO verses (sura, aya, text) VALUES (36, 83, 'Her şeyin mülkü elinde olan ve sizin de kendisine döneceğiniz Allah (noksanlıklardan) münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 1, 'Andolsun saf saf dizilenlere.');
INSERT INTO verses (sura, aya, text) VALUES (37, 2, 'Sürüp sevk edenlere.');
INSERT INTO verses (sura, aya, text) VALUES (37, 3, 'Zikri okuyanlara.');
INSERT INTO verses (sura, aya, text) VALUES (37, 4, 'Sizin ilahınız tek bir ilahtır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 5, 'O, göklerin, yerin ve bu ikisi arasında bulunanların Rabbidir. O, doğuların da Rabbidir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 6, 'Biz, en yakın göğü yıldızlarla süsledik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 7, 'Ve onu (göğü) kovulmuş Şeytanlar''dan koruduk.');
INSERT INTO verses (sura, aya, text) VALUES (37, 8, 'Onlar, artık mele-i a''la''ya (yüce topluluğa) kulak veremezler. Her taraftan taşlanırlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 9, 'Kovularak uzaklaştırılmış (olurlar) ve onlar için elem dolu bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 10, 'Ancak bir (söz) çalıp kapan olursa onu da parlak bir ateş izler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 11, 'Şimdi onlara sor: “Yaratılış bakımından onlar mı daha zorlu, yoksa bizim yarattıklarımız mı?” Doğrusu biz onları, yapışkan bir çamurdan yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 12, 'Hayır, sen şaşırdın kaldın; onlar ise alay edip duruyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 13, 'Kendilerine öğüt verildiğinde öğüt almazlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 14, 'Bir ayet (mucize) gördüklerinde alaya alırlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 15, '"Bu, ancak apaçık bir büyüdür." derler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 16, '"Öldüğümüz, toprak ve kemik haline geldiğimiz zaman mı gerçekten biz mi diriltileceğiz?');
INSERT INTO verses (sura, aya, text) VALUES (37, 17, '“Önceden gelip geçmiş atalarımız da mı?”');
INSERT INTO verses (sura, aya, text) VALUES (37, 18, 'De ki: “Evet! Hem de siz aşağılanmış kimseler olarak (diriltileceksiniz).”');
INSERT INTO verses (sura, aya, text) VALUES (37, 19, 'Çünkü o, korkunç bir sesten ibarettir. O zaman etrafa bakıp dururlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 20, '"Eyvah bize! İşte bu, hesap günüdür." derler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 21, '“İşte bu, yalanlamakta olduğunuz hüküm ve ayırım günüdür.” denilir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 22, 'Zalimleri, onların eşlerini ve tapmakta olduklarını toplayın.');
INSERT INTO verses (sura, aya, text) VALUES (37, 23, 'Allah''tan başka (ibadet etmiş olduklarını) Cehennem yoluna iletin!');
INSERT INTO verses (sura, aya, text) VALUES (37, 24, 'Durdurun onları; çünkü onlar sorguya çekileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 25, 'Size ne oldu da birbirinize yardım etmiyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (37, 26, 'Hayır! Onlar, bugün tamamen teslim olmuşlardır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 27, '(İşte bu duruma düştükleri vakit) onlardan bir kısmı, diğerlerine yönelir, birbirlerini sorumlu tutmaya çalışırlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 28, '"Siz, bize sağdan geliyordunuz." derler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 29, 'Diğerleri de derler ki: "Hayır! Siz iman eden kimseler değildiniz."');
INSERT INTO verses (sura, aya, text) VALUES (37, 30, 'Bizim sizin üzerinizde zorlayıcı bir gücümüz yoktu. Fakat siz, zaten azgın bir toplum idiniz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 31, 'Artık Rabbimizin hakkımızdaki sözü gerçekleşti. Kesinlikle biz onu (azabı) tadacağız.');
INSERT INTO verses (sura, aya, text) VALUES (37, 32, 'Evet! Sizi saptırdık. Çünkü biz de sapkın kimseler idik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 33, 'Hiç şüphe yok ki, o gün onlar azapta ortaktırlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 34, 'Biz, günahkârlara işte böyle yaparız.');
INSERT INTO verses (sura, aya, text) VALUES (37, 35, 'Çünkü onlar, kendilerine; "Allah’tan başka (hak) ilah yoktur." denildiği zaman büyüklenirlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 36, '"Bir mecnun şair için ilahlarımızı terk mi edeceğiz?" derlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 37, 'Hayır! O, hakkı getirdi ve peygamberleri doğruladı.');
INSERT INTO verses (sura, aya, text) VALUES (37, 38, 'Kuşkusuz siz acı azabı tadacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (37, 39, 'Siz ancak işlediklerinizin karşılığı ile cezalandırılırsınız.');
INSERT INTO verses (sura, aya, text) VALUES (37, 40, 'Ancak, Allah’ın ihlaslı kulları müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (37, 41, 'Onlar için bilinen rızıklar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 42, 'Çeşitli meyveler. Onlar ikram edilenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 43, 'Onlar, Nimet Cennetleri''ndedir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 44, 'Tahtlar üzerinde karşılıklı otururlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 45, 'Etraflarında pınardan (doldurulmuş) kadehler dolaştırılır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 46, 'Bembeyazdır, içenlere lezzet verir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 47, 'Onda ne baş dönmesi vardır, ne de ondan dolayı sarhoş olurlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 48, 'Yanlarında bakışlarını yalnız kendilerine çevirmiş iri gözlü eşler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 49, 'Sanki onlar örtülü yumurtalar gibi bembeyazdır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 50, 'Birbirlerine dönüp sorarlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 51, 'İçlerinden biri; "Benim bir arkadaşım vardı." der.');
INSERT INTO verses (sura, aya, text) VALUES (37, 52, 'Bana derdi ki: "Sen gerçekten tasdik edenlerden misin?"');
INSERT INTO verses (sura, aya, text) VALUES (37, 53, '"Ölüp toprak ve kemik haline geldiğimiz zaman yeniden mi diriltileceğiz?"');
INSERT INTO verses (sura, aya, text) VALUES (37, 54, '(Cennet''e giren) Ona; "Ne olduğunu görüyor musunuz?" der.');
INSERT INTO verses (sura, aya, text) VALUES (37, 55, 'Bakar ve onu cehennemin ortasında görür.');
INSERT INTO verses (sura, aya, text) VALUES (37, 56, '"Allah’a yemin ederim ki, sen neredeyse beni de helâk edecektin!" der.');
INSERT INTO verses (sura, aya, text) VALUES (37, 57, '"Eğer Rabbimin nimeti olmasaydı, şimdi ben de (Cehennem''e) getirilenlerden olurdum."');
INSERT INTO verses (sura, aya, text) VALUES (37, 58, '"Şimdi, artık biz ölmeyeceğiz değil mi?"');
INSERT INTO verses (sura, aya, text) VALUES (37, 59, '"Nasıl, ilk ölümümüzden başka ölmeyecek miymişiz?Bize azap edilmeyecek miymiş?"');
INSERT INTO verses (sura, aya, text) VALUES (37, 60, 'İşte bu, en büyük kurtuluştur.');
INSERT INTO verses (sura, aya, text) VALUES (37, 61, 'Çalışıp amel edenler, böylesi için çalışsınlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 62, '(Nimet olarak) Bu mu daha hayırlı, yoksa zakkum ağacı mı?');
INSERT INTO verses (sura, aya, text) VALUES (37, 63, 'Biz onu zalimler için bir fitne kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 64, 'O, Cehennem''in dibinden çıkan bir ağaçtır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 65, 'Tomurcukları (ürünleri) sanki Şeytanlar''ın başları gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 66, 'İşte onlar, bundan yerler ve karınlarını onunla doldururlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 67, 'Sonra, onlar için üzerine kaynar su katılmış içki vardır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 68, 'Sonra da onların dönüşü yine Cehennem''edir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 69, 'Onlar; babalarını, atalarını sapık kimseler olarak bulmuşlardı.');
INSERT INTO verses (sura, aya, text) VALUES (37, 70, 'Kendileri de onların izlerinden koşturuluyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (37, 71, 'Andolsun ki, onlardan önce eski milletlerin çoğu dalâlete düştü.');
INSERT INTO verses (sura, aya, text) VALUES (37, 72, 'Andolsun ki, onlar arasında uyarıp, korkutanlar göndermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 73, 'Uyarılanların sonlarının nasıl olduğuna bir bak!');
INSERT INTO verses (sura, aya, text) VALUES (37, 74, 'Allah’ın ihlaslı kulları müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (37, 75, 'Andolsun, Nuh bize seslenmişti de ne güzel icâbet etmiştik!');
INSERT INTO verses (sura, aya, text) VALUES (37, 76, 'Onu ve ailesini o büyük sıkıntıdan kurtarmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 77, 'Yalnız onun soyunu sürekli kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 78, 'Sonradan gelenler arasında onun için (güzel bir) nam bıraktık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 79, 'Âlemler içinde Nûh’a selam olsun!');
INSERT INTO verses (sura, aya, text) VALUES (37, 80, 'Biz, iyilik yapan ihsan sahiplerini işte böyle ödüllendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 81, 'Çünkü o, Mümin kullarımızdan idi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 82, 'Sonra ötekilerini suda boğduk.');
INSERT INTO verses (sura, aya, text) VALUES (37, 83, 'Şüphesiz İbrahim de onun yolunda olanlardan idi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 84, 'Hani O, Rabbine (şirkten) selamette olan bir kalp ile gelmişti.');
INSERT INTO verses (sura, aya, text) VALUES (37, 85, 'Hani o, babasına ve kavmine; “Neye ibadet ediyorsunuz?” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (37, 86, '"Allah’tan başka uydurma ilahlar mı istiyorsunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (37, 87, '“Âlemlerin Rabbi hakkında zannınız nedir?”');
INSERT INTO verses (sura, aya, text) VALUES (37, 88, 'Derken yıldızlara bir göz attı.');
INSERT INTO verses (sura, aya, text) VALUES (37, 89, '“Ben hastayım.” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 90, 'Arkalarını dönüp gittiler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 91, 'Bunun üzerine gizlice onların ilahlarına varıp; “Yemek yemiyor musunuz?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 92, '"Size ne oldu da konuşmuyorsunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (37, 93, 'Sonra üzerlerine gelip sağ eliyle (kuvvetle) vurdu.');
INSERT INTO verses (sura, aya, text) VALUES (37, 94, 'Bunun üzerine hemen koşarak kendisine geldiler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 95, 'İbrahim onlara: "Ellerinizle yonttuğunuz şeylere mi ibadet ediyorsunuz?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 96, 'Oysa sizi de, yapmakta olduklarınızı da Allah yaratmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 97, '"Onun için bir bina yapın, onu alevli ateşin içine atın!" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 98, 'Böylece ona bir tuzak kurmak istediler. Biz de onları en aşağılık kimseler kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 99, 'Dedi ki: "Ben Rabbime gideceğim. O, beni doğru yola iletecektir."');
INSERT INTO verses (sura, aya, text) VALUES (37, 100, '"Rabbim, bana salihlerden bir evlat bağışla."');
INSERT INTO verses (sura, aya, text) VALUES (37, 101, 'Biz de ona yumuşak huylu bir erkek çocuk müjdeledik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 102, 'Ne zaman ki o babasının yanı sıra yürümeye başlayınca dedi ki: “Oğulcağızım, gerçekten ben rüyamda seni boğazladığımı görüyorum. Bak, artık sen ne düşünürsün?” Dedi ki: “Babacığım, emrolunduğun şeyi yap. İnşallah beni sabredenlerden bulacaksın.”');
INSERT INTO verses (sura, aya, text) VALUES (37, 103, 'Böylece her ikisi de (Allah’ın emrine) boyun eğip, İbrahim de onu (boğazlamak için) alnı üstü yere yatırdı.');
INSERT INTO verses (sura, aya, text) VALUES (37, 104, 'Biz ona: “Ey İbrahim!” diye seslendik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 105, 'Sen rüyanı gerçekten tasdik ettin. Biz, iyileri böyle mükâfatlandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (37, 106, 'Doğrusu bu, apaçık bir imtihandı.');
INSERT INTO verses (sura, aya, text) VALUES (37, 107, 'Biz ona fidye olarak büyük bir kurbanlık verdik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 108, 'Sonradan gelenler arasında onun için (güzel bir) nam bıraktık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 109, 'İbrahim’e selam olsun!');
INSERT INTO verses (sura, aya, text) VALUES (37, 110, 'Biz, iyilik yapan ihsan sahiplerini işte böyle ödüllendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 111, 'Çünkü o, Mümin kullarımızdan idi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 112, 'Biz ona, salihlerden bir peygamber olarak İshak''ı müjdeledik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 113, 'Onu ve İshak’ı mübarek kıldık. İkisinin soyundan iyi davranan da var, açıkça kendi nefsine zulmetmekte olan da.');
INSERT INTO verses (sura, aya, text) VALUES (37, 114, 'Andolsun ki, biz Mûsâ''ya ve Hârûn''a da lütufta bulunduk.');
INSERT INTO verses (sura, aya, text) VALUES (37, 115, 'Onları ve kavimlerini, o büyük sıkıntıdan kurtardık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 116, 'Onlara yardım ettik. Böylece üstün gelenler onlar oldular.');
INSERT INTO verses (sura, aya, text) VALUES (37, 117, 'O ikisine apaçık olan kitabı verdik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 118, 'Her ikisini de doğru yola ilettik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 119, 'Sonradan gelenler arasında o ikisi için (güzel bir) nam bıraktık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 120, 'Mûsâ ve Hârûn’a selam olsun!');
INSERT INTO verses (sura, aya, text) VALUES (37, 121, 'Biz, iyilik yapanları işte böyle ödüllendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 122, 'Çünkü o ikisi, Mümin kullarımızdan idi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 123, 'Muhakkak İlyas da gönderilmiş rasullerdendi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 124, 'Halkına şöyle demişti: “Siz korkup sakınmaz mısınız?”');
INSERT INTO verses (sura, aya, text) VALUES (37, 125, '"Yaratıcıların en iyisini bırakıp Ba’l (adlı puta) mi ibadet ediyorsunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (37, 126, 'Sizin Rabbiniz de, geçmiş atalarınızın da Rabbi Allah''tır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 127, 'Onu yalanladılar, bundan dolayı gerçekten onlar, (azap için getirilip) hazır bulundurulacak olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (37, 128, 'Allah’ın ihlaslı kulları müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (37, 129, 'Sonradan gelenler arasında (güzel bir) nam bıraktık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 130, 'İlyas’a selam olsun!');
INSERT INTO verses (sura, aya, text) VALUES (37, 131, 'Biz, iyilik yapanları işte böyle ödüllendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 132, 'Çünkü o, Mümin kullarımızdan idi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 133, 'Şüphesiz Lût da gönderilmiş rasullerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 134, 'Hani biz onu ve aile halkını birlikte kurtarmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 135, 'Ancak bir kocakarı müstesna. O, geride kalanlardan oldu.');
INSERT INTO verses (sura, aya, text) VALUES (37, 136, 'Sonra diğerlerini helâk ettik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 137, 'Siz, sabah vakti onların (diyarından) muhakkak geçip gidiyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 138, 'Ve geceleyin (de onlara uğruyorsunuz). Yine de akıllanmayacak mısınız?');
INSERT INTO verses (sura, aya, text) VALUES (37, 139, 'Muhakkak Yûnus da gönderilmiş rasullerdendi.');
INSERT INTO verses (sura, aya, text) VALUES (37, 140, 'Hani o, kaçıp yüklü bir gemiye binmişti.');
INSERT INTO verses (sura, aya, text) VALUES (37, 141, 'Kura çekmişler ve kaybedenlerden olmuştu.');
INSERT INTO verses (sura, aya, text) VALUES (37, 142, 'Derken onu balık yutmuştu, o kınanır bir davranışta bulunmuştu.');
INSERT INTO verses (sura, aya, text) VALUES (37, 143, 'Eğer o gerçekten tesbih edenlerden olmasaydı,');
INSERT INTO verses (sura, aya, text) VALUES (37, 144, 'İnsanların tekrar diriltilecekleri güne kadar onun karnında kalırdı.');
INSERT INTO verses (sura, aya, text) VALUES (37, 145, 'Biz de onu, hasta bir halde boş bir alana/sahile attık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 146, 'Üzerine kabak türünden (gölge yapması için) bir ağaç bitirdik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 147, 'Sonra da onu, yüz bin kişiye hatta daha fazlasına gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (37, 148, 'Sonunda ona iman ettiler. Biz de onları bir süreye kadar yararlandırdık.');
INSERT INTO verses (sura, aya, text) VALUES (37, 149, 'Şimdi onlara sor: “Kız çocukları Rabbinin, erkek çocukları da kendilerinin midir?”');
INSERT INTO verses (sura, aya, text) VALUES (37, 150, 'Yoksa biz melekleri dişi olarak yarattık da onlar buna şahit mi oldular?');
INSERT INTO verses (sura, aya, text) VALUES (37, 151, 'İyi bilin ki onlar iftiralarından dolayı derler ki:');
INSERT INTO verses (sura, aya, text) VALUES (37, 152, '“Allah doğurdu.” (diyorlar) Şüphesiz onlar elbette yalancıdırlar.');
INSERT INTO verses (sura, aya, text) VALUES (37, 153, 'Allah kızları, oğullara tercih mi etmiş?');
INSERT INTO verses (sura, aya, text) VALUES (37, 154, 'Size ne oluyor? Nasıl hüküm veriyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (37, 155, 'Düşünüp öğüt almaz mısınız?');
INSERT INTO verses (sura, aya, text) VALUES (37, 156, 'Yoksa sizin çok açık bir deliliniz mi var?');
INSERT INTO verses (sura, aya, text) VALUES (37, 157, 'Eğer doğru söylüyorsanız, haydi kitabınızı getirin.');
INSERT INTO verses (sura, aya, text) VALUES (37, 158, 'Onlar, kendisiyle (Allah ile) cinler arasında bir soy-bağı kurdular. Andolsun ki, melekler de (bunu söyleyenlerin) hesap yerine götürüleceklerini bilirler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 159, 'Allah; onların yakıştırdıkları şeylerden münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 160, 'Allah’ın ihlaslı kulları müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (37, 161, 'Artık ne siz ne de ibadet ettikleriniz;');
INSERT INTO verses (sura, aya, text) VALUES (37, 162, 'O''na karşı hiç kimseyi fitneye düşüremezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 163, 'Ancak Cehennem''e girecek olanlar müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (37, 164, '(Melekler der ki:) “Bizden her birimiz için belli bir makam vardır.”');
INSERT INTO verses (sura, aya, text) VALUES (37, 165, 'Muhakkak biz saf saf duranlarız.');
INSERT INTO verses (sura, aya, text) VALUES (37, 166, 'Ve şüphesiz biz tesbih edenleriz.');
INSERT INTO verses (sura, aya, text) VALUES (37, 167, 'Muhakkak onlar şöyle diyorlardı:');
INSERT INTO verses (sura, aya, text) VALUES (37, 168, '“Eğer yanımızda öncekilerden bir zikir (kitap) bulunmuş olsaydı.”');
INSERT INTO verses (sura, aya, text) VALUES (37, 169, '“Gerçekten bizler de, Allah''ın muhlis olan kullarından olurduk.”');
INSERT INTO verses (sura, aya, text) VALUES (37, 170, 'Fakat ona (iman etmeyip) kâfir oldular, ileride (küfürlerinin akıbetini) bilecekler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 171, 'Andolsun, peygamber olarak gönderilen kullarımız hakkında şu sözümüz geçmişti:');
INSERT INTO verses (sura, aya, text) VALUES (37, 172, '“Onlara mutlaka yardım edilecektir.”');
INSERT INTO verses (sura, aya, text) VALUES (37, 173, 'Ve galip gelecek olanlar, mutlaka bizim ordumuzdur.');
INSERT INTO verses (sura, aya, text) VALUES (37, 174, 'Öyleyse sen, bir süreye kadar onlardan yüz çevir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 175, '(Başlarına geleceğini) gözetle. Nitekim onlar da yakında görecekler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 176, 'Yoksa azabımızın çabuk gelmesini mi istiyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (37, 177, 'Fakat (azap) onların sahasına indiği zaman, uyarılıp korkutulanların sabahı pek de kötü olacak!');
INSERT INTO verses (sura, aya, text) VALUES (37, 178, 'Bir süreye kadar onlardan yüz çevir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 179, 'Ve (başlarına geleceği) gözetle. Nitekim onlar da yakında görecekler.');
INSERT INTO verses (sura, aya, text) VALUES (37, 180, 'Üstünlük (izzet) sahibi Rabbin onların nitelemelerinden münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (37, 181, 'Gönderilmiş resûllere selam olsun.');
INSERT INTO verses (sura, aya, text) VALUES (37, 182, 'Hamt, âlemlerin Rabbi olan Allah''a mahsustur.');
INSERT INTO verses (sura, aya, text) VALUES (38, 1, 'Sâd.[1] Öğüt dolu Kur’an’a yemin olsun ki!');
INSERT INTO verses (sura, aya, text) VALUES (38, 2, 'Hayır. O inkâr edenler bir büyüklenme ve ayrılık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 3, 'Onlardan önce nice nesiller helâk ettik, onlar da feryat ettiler. Hâlbuki kurtulma vakti değildi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 4, 'Aralarından bir uyarıcının gelmesine şaşırdılar. Kâfirler dedi ki: "Bu, yalancı bir sihirbazdır!"');
INSERT INTO verses (sura, aya, text) VALUES (38, 5, 'İlahları tek bir ilah mı yaptı? Bu, hayret edilecek bir şeydir.');
INSERT INTO verses (sura, aya, text) VALUES (38, 6, 'Onların ileri gelenleri: "Yürüyün! İlahlarınız üzerinde sebat/kararlılık gösterin. Sizden istenen şey budur." diye harekete geçtiler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 7, 'Biz bunu diğer dinde de işitmedik. Bu sadece bir uydurmadır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 8, 'Kur’an, aramızdan ona mı indirilmiş? Hayır! Onlar zikrimden şüphe ediyorlar. Çünkü henüz azabımı tatmadılar.');
INSERT INTO verses (sura, aya, text) VALUES (38, 9, 'Yoksa, güçlü ve çok ihsan sahibi olan Rabbinin rahmet hazineleri onların yanında mıdır?');
INSERT INTO verses (sura, aya, text) VALUES (38, 10, 'Yoksa göklerin, yerin ve ikisi arasında bulunanların mülkü onlara mı ait? Öyle ise (göklerin) yollarına yükselsinler (görelim)!');
INSERT INTO verses (sura, aya, text) VALUES (38, 11, 'Onlar burada takım takım bozguna uğramış perişan bir ordudur.');
INSERT INTO verses (sura, aya, text) VALUES (38, 12, 'Onlardan önce Nûh kavmi, Âd (kavmi) ve kazıklar sahibi Firavun da yalanlamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (38, 13, 'Semûd ve Lût’un kavmi de, Eyke halkı da. İşte onlar da birer grup idiler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 14, 'Onların her biri rasûlleri yalanladılar da azabımı hak ettiler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 15, 'Onlar geri dönüşü olmayan bir tek çığlıktan başka bir şey beklemiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (38, 16, '"Rabbimiz! Hesap gününden önce bizim payımızı çabucak ver." derler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 17, 'Onların söylediklerine sabırlı ol. O kuvvet sahibi kulumuz Dâvud''u hatırla. O, her zaman Allah''a yönelirdi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 18, 'Doğrusu biz dağlara boyun eğdirdik. Akşam ve sabah onlar kendisiyle (Dâvud ile) birlikte (Allah''ı) tesbih ederlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 19, 'Toplanmış kuşlarda (onunla birlikte tesbih ettiler) Hepsi de ona yönelip, uydular.');
INSERT INTO verses (sura, aya, text) VALUES (38, 20, 'Onun hükümranlığını kuvvetlendirmiştik. Ona hikmet ve kesin hüküm kabiliyeti vermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (38, 21, 'Sana davacıların haberi geldi mi? Hani onlar duvarı aşarak mabede girmişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 22, 'Dâvud’un yanına gitmişlerdi de, Dâvud onlardan korkmuştu. "Korkma! Biz birbirine hasım iki davacıyız. Aramızda adaletle hükmet, haksızlık etme; bize doğru yolu göster." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 23, 'Bu benim kardeşimdir, onun doksan dokuz koyunu, benim ise tek bir koyunum var. "Onu da bana ver.” Dedi ve tartışmada beni bastırdı."');
INSERT INTO verses (sura, aya, text) VALUES (38, 24, 'Dâvud: "Koyununu kendi koyunları arasına katmak istemekle sana haksızlık etmiş. Zaten ortakların çoğu, birbirlerine zulmeder. Ancak iman eden salih amellerde bulunanlar müstesna. Bunlar da ne kadar azdır!" dedi. Dâvud, kendisini imtihan ettiğimizi anlamış ve Rabbinden bağışlanma dileyerek secdeye kapanmış ve O’na yönelmişti.');
INSERT INTO verses (sura, aya, text) VALUES (38, 25, 'Böylece onu bağışladık. Şüphesiz onun bizim katımızda gerçekten bir yakınlığı ve varılacak güzel bir yeri vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 26, 'Ey Dâvud! Seni yeryüzünde bir halife kıldık. O halde insanlar arasında hak/adaletle hüküm ver. Heva ve hevese uyma, yoksa seni Allah’ın yolundan saptırır. Allah’ın yolundan sapanlara ise hesap gününü unutmalarından dolayı şiddetli bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 27, 'Biz göğü, yeri ve ikisi arasındakileri boş yere yaratmadık. Bu, kâfirlerin zannıdır. Vay o kâfirlerin ateşteki haline!');
INSERT INTO verses (sura, aya, text) VALUES (38, 28, 'Yoksa iman edip salih amellerde bulunanları, yeryüzünde bozgunculuk yapanlar gibi mi tutacağız? Yoksa takva sahiplerini facirler gibi mi tutacağız?');
INSERT INTO verses (sura, aya, text) VALUES (38, 29, '(Bu), ayetlerini düşünsünler ve akıl sahipleri öğüt alsınlar diye sana indirdiğimiz mübarek bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 30, 'Dâvud’a Süleyman’ı bağışladık. O, ne güzel bir kuldu. Doğrusu o, daima Allah’a yönelirdi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 31, 'Hani akşama doğru kendisine, üç ayağının üzerinde durup bir ayağını tırnağının üzerine diken (çalımlı ve safkan) atlar sunulmuştu.');
INSERT INTO verses (sura, aya, text) VALUES (38, 32, 'O da şöyle demişti: "Hayrı sevmek beni, Rabbimin zikrinden alıkoydu. Nihayet (Güneş) perdenin arkasına gizlendi."');
INSERT INTO verses (sura, aya, text) VALUES (38, 33, '“Onları bana geri getirin.” (dedi). Sonra da (onların) bacaklarını ve boyunlarını vurmaya başladı.');
INSERT INTO verses (sura, aya, text) VALUES (38, 34, 'Andolsun biz Süleyman''ı imtihan ettik. Tahtının üstüne bir ceset bırakıverdik. Sonra tevbe edip bize yöneldi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 35, 'Dedi ki: “Rabbim, bana mağfiret buyur ve benden sonra hiç kimseye nasip olmayacak bir mülk ver. Şüphesiz, sen çok ihsan sahibisin."');
INSERT INTO verses (sura, aya, text) VALUES (38, 36, 'Böylece biz de rüzgârı onun buyruğuna verdik. Onun emriyle dilediği tarafa yumuşak bir şekilde akıp gidiyordu.');
INSERT INTO verses (sura, aya, text) VALUES (38, 37, 'Bütün bina ustası ve dalgıç Şeytanları da (onun emrine verdik).');
INSERT INTO verses (sura, aya, text) VALUES (38, 38, 'Bukağılara vurulmuş halde birbirlerine yaklaştırılmış olan daha başkalarını da (onun hizmetine verdik).');
INSERT INTO verses (sura, aya, text) VALUES (38, 39, '“İşte bu, bizim hesapsız ihsanımızdır. Artık dilersen (başkalarına) ihsan et, dilersen de (elinde) tut.”');
INSERT INTO verses (sura, aya, text) VALUES (38, 40, 'Şüphesiz onun bizim katımızda bir yakınlığı ve varılacak güzel bir yeri vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 41, 'Kulumuz Eyyûb’u da an. Hani Rabbine: “Şeytan bana bir yorgunluk ve azap verdi." diye seslenmişti.');
INSERT INTO verses (sura, aya, text) VALUES (38, 42, '“Ayağını yere vur! İşte yıkanacak ve içilecek soğuk bir su (dedik).”');
INSERT INTO verses (sura, aya, text) VALUES (38, 43, 'Ona katımızdan bir rahmet ve akıl sahiplerine bir öğüt olması üzere ailesini ve onlarla birlikte bir o kadarını daha bahşettik.');
INSERT INTO verses (sura, aya, text) VALUES (38, 44, '"Eline bir demet sap al da onunla vur, yemini böyle yerine getir." Gerçekten Eyyûb sabırlı (bir kul) idi. O, ne iyi kuldu daima Allah’a yönelirdi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 45, 'Güç ve basiret sahibi kullarımız İbrahim''i, İshak''ı ve Ya''kûb''u da an.');
INSERT INTO verses (sura, aya, text) VALUES (38, 46, 'Biz onları, özellikle ahiret yurdunu düşünen ihlaslı kimseler kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (38, 47, 'Çünkü onlar, katımızda seçilmiş ve hayırlı kimselerden idiler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 48, 'İsmail’i, Elyasa’yı ve Zülkifl’i de an. Hepsi de hayırlı kimselerden idiler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 49, 'Bu bir anmadır. Doğrusu Allah''tan korkanlar için varılacak güzel bir yer vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 50, 'Kapıları yalnızca kendilerine açılmış Adn Cennetleri vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 51, 'Orada koltuklarına kurulmuşlar, birçok meyve ve içecek isterler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 52, 'Yanlarında bakışlarını yalnız kendilerine dikmiş yaşıt eşler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 53, 'İşte hesap günü için size vadedilen budur.');
INSERT INTO verses (sura, aya, text) VALUES (38, 54, 'Şüphesiz bu, bizim (ihsan ettiğimiz) rızkımızdır, bitip tükenmesi de yok.');
INSERT INTO verses (sura, aya, text) VALUES (38, 55, 'Bu (takva sahipleri içindi; ama) azgınlar içinse muhakkak varılacak kötü bir yer vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 56, 'Cehennem. Onlar oraya girerler. Orası ne kötü bir yataktır!');
INSERT INTO verses (sura, aya, text) VALUES (38, 57, 'İşte bu kaynar su ve irindir, artık onu tatsınlar.');
INSERT INTO verses (sura, aya, text) VALUES (38, 58, 'O türden başka çeşit çeşit (azap) daha vardır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 59, '(Kendi aralarında şöyle derler:) “İşte şunlar sizinle beraber (elim ateşe) girecek olanlardır.” (Zalimler ise der ki:) “Onlar rahat yüzü görmesinler! Onlar (da bizim gibi) ateşe gireceklerdir.”');
INSERT INTO verses (sura, aya, text) VALUES (38, 60, '(Zalimlere uyanlar ise:) “Hayır, asıl siz rahat yüzü görmeyin. Onu bize siz sundunuz. Ne kötü bir yerdir.” diyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (38, 61, '“Rabbimiz! Kim bunu bizim önümüze sürdüyse, onun ateşteki azabını kat kat arttır.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (38, 62, 'Derler ki: "Ne oluyor da, kendilerini kötülerden saydığımız adamları göremiyoruz?"');
INSERT INTO verses (sura, aya, text) VALUES (38, 63, 'Biz onlarla alay ederdik. Yoksa gözler mi onlardan kaydı (da göremiyoruz)?”');
INSERT INTO verses (sura, aya, text) VALUES (38, 64, 'İşte cehennem halkının birbiriyle olan bu tartışması kesin gerçektir.');
INSERT INTO verses (sura, aya, text) VALUES (38, 65, 'De ki: "Ben sadece bir uyarıcıyım. Tek ve Kahhâr olan Allah’tan başka bir (hak) ilah yoktur."');
INSERT INTO verses (sura, aya, text) VALUES (38, 66, '(O) göklerin, yerin ve bu ikisi arasındakilerin Rabbidir, çok güçlüdür, çok bağışlayandır.');
INSERT INTO verses (sura, aya, text) VALUES (38, 67, 'De ki: "Bu (Kur''an), büyük bir haberdir."');
INSERT INTO verses (sura, aya, text) VALUES (38, 68, 'Siz ise ondan yüz çeviriyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (38, 69, 'Yüce topluluk (mele-i a''la) aralarında tartışırlarken benim hiçbir bilgim yoktu.');
INSERT INTO verses (sura, aya, text) VALUES (38, 70, '“Ben, ancak apaçık bir uyarıcı olduğum için bana vahyolunuyor.”');
INSERT INTO verses (sura, aya, text) VALUES (38, 71, 'Hani Rabbin meleklere; “Gerçekten ben çamurdan bir beşer yaratacağım.” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (38, 72, 'Ben şeklini verip, ona ruhumdan üflediğim zaman hemen ona secdeye kapanın.”');
INSERT INTO verses (sura, aya, text) VALUES (38, 73, 'Meleklerin tümü hep birlikte secdeye kapandılar.');
INSERT INTO verses (sura, aya, text) VALUES (38, 74, 'İblis müstesnâ. Büyüklük tasladı ve kâfirlerden oldu.');
INSERT INTO verses (sura, aya, text) VALUES (38, 75, '(Allah) Buyurdu ki: "Ey İblis! İki elimle yarattığıma seni secde etmekten alıkoyan nedir? Büyüklük mü tasladın yoksa yücelerden mi oldun?"');
INSERT INTO verses (sura, aya, text) VALUES (38, 76, 'Dedi ki: “Ben ondan daha hayırlıyım. Sen beni ateşten yarattın, onu ise çamurdan yarattın.”');
INSERT INTO verses (sura, aya, text) VALUES (38, 77, '(Allah) buyurdu ki: "Öyleyse çık oradan. Sen artık kovulmuş birisin."');
INSERT INTO verses (sura, aya, text) VALUES (38, 78, '“Ve şüphesiz ceza gününe kadar benim lanetim senin üzerindedir.”');
INSERT INTO verses (sura, aya, text) VALUES (38, 79, '(İblis): “Rabbim! Öyle ise onların tekrar diriltilecekleri güne kadar bana mühlet ver!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 80, '(Allah) buyurdu ki: “O halde sen, kendisine mühlet verilenlerdensin.''''');
INSERT INTO verses (sura, aya, text) VALUES (38, 81, 'Vakti bilinen bir güne kadar.');
INSERT INTO verses (sura, aya, text) VALUES (38, 82, '"Senin izzetin adına yemin ederim ki, onların hepsini aldatıp saptıracağım." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (38, 83, 'Ancak, içlerinde ihlas sahibi kulların müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (38, 84, '(Allah) Buyurdu ki: “İşte bu haktır ve ben hakkı söylerim.”');
INSERT INTO verses (sura, aya, text) VALUES (38, 85, 'Cehennem''i tamamen senden olanlar ve sana uyanlarla dolduracağım.');
INSERT INTO verses (sura, aya, text) VALUES (38, 86, 'De ki: "Ben sizden bir ücret istemiyorum. Kendiliğimden bir yükümlülük getirenlerden de değilim."');
INSERT INTO verses (sura, aya, text) VALUES (38, 87, 'O, yalnızca bütün âlemler için bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (38, 88, 'Onun haberini bir süre sonra bileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (39, 1, 'Bu kitap; Azîz ve Hakîm olan Allah tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 2, 'Şüphesiz biz sana kitabı hak olarak indirdik. O halde dini yalnız O''na halis kılarak Allah''a ibadet et.');
INSERT INTO verses (sura, aya, text) VALUES (39, 3, 'İyi bilin ki, halis din yalnız Allah’ındır. O’ndan başka veliler edinenler, : “Biz bunlara ancak bizleri Allah’a yaklaştırsınlar diye ibadet ediyoruz” (derler.) Şüphesiz Allah, ayrılığa düştükleri şeyler konusunda aralarında hüküm verecektir. Şüphesiz Allah, yalancı ve nankör olanları doğru yola iletmez.');
INSERT INTO verses (sura, aya, text) VALUES (39, 4, 'Eğer Allah bir evlat edinmek istese idi, elbette yarattıklarından dilediğini seçerdi. O bundan münezzehtir, O Allah’tır, birdir, Kahhâr''dır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 5, 'O, gökleri ve yeri hak ile yaratmıştır. Geceyi gündüze dolayıp örter, gündüzü de geceye örter, Güneşe ve Ay''a da boyun eğdirmiştir. Hepsi de belli bir süreye kadar akar/gider. Bilin ki O; çok güçlüdür, çok bağışlayıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 6, 'Sizi tek bir nefisten yarattı, sonra da ondan kendi eşini var etti ve sizin için hayvanlardan sekiz çift indirdi. Sizi annelerinizin karınlarından üç karanlık içinde, bir yaratılıştan sonra öbür yaratılışa geçirerek yaratmaktadır. İşte Rabbiniz olan Allah budur; mülk de O''nundur. Ondan başka (hak) ilah yoktur. Buna rağmen nereye çevriliyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (39, 7, 'Eğer küfrederseniz, şüphesiz ki Allah size muhtaç değildir. Ama kulları için küfre razı olmaz. Eğer şükrederseniz sizin için buna razı olur. Hiçbir günahkâr başka bir günahkârın yükünü yüklenmez. Sonra dönüşünüz ancak Rabbinizedir. O da size yaptıklarınızı haber verir. Çünkü O, kalplerde olan her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 8, 'İnsana bir zarar dokunduğu zaman, gönülden Rabbine yönelerek, O''na dua eder. Sonra ona, kendisinden bir nimet verdiği zaman, daha önce O''na dua ettiğini unutur da O''nun yolundan saptırmak amacıyla Allah''a ortaklar koşar. De ki: "Küfrünle biraz faydalanıp, eğlene dur. Kuşkusuz sen ateş ehlindensin!"');
INSERT INTO verses (sura, aya, text) VALUES (39, 9, '(Küfre sapan kimse,) Gece saatlerinde kalkıp da secde ederek ve kıyama durarak gönülden itaat (ibadet) eden, ahiretten sakınan ve Rabbinin rahmetini umut eden (kimse gibi) midir? De ki: “Hiç bilenlerle bilmeyenler bir olur mu? Ancak akıl sahipleri düşünüp öğüt alır."');
INSERT INTO verses (sura, aya, text) VALUES (39, 10, 'De ki: “Ey iman eden kullarım! Rabbinizden korkup sakının. Bu dünyada iyilik etmekte olanlar için bir iyilik vardır. Allah''ın arzı geniştir. Ancak sabredenlere ecirleri hesapsızca ödenir.”');
INSERT INTO verses (sura, aya, text) VALUES (39, 11, 'De ki: “Ben, dini yalnızca Allah''a halis kılarak O''na ibadet etmekle emrolundum.”');
INSERT INTO verses (sura, aya, text) VALUES (39, 12, '“Ve ben, Müslümanların ilki olmakla da emrolundum.”');
INSERT INTO verses (sura, aya, text) VALUES (39, 13, 'De ki: "Eğer Rabbime isyan edersem, elbette ben büyük bir günün azabından korkarım!"');
INSERT INTO verses (sura, aya, text) VALUES (39, 14, 'De ki: “Ben dinimi yalnızca Allah''a halis kılarak O''na ibadet ederim.”');
INSERT INTO verses (sura, aya, text) VALUES (39, 15, 'Siz de, ondan başka dilediğinize ibadet edin. De ki: "Hüsrana uğrayacaklar, kıyamet günü hem kendilerini hem de ailelerini hüsrana uğratanlardır. Dikkat edin! Apaçık hüsran işte budur."');
INSERT INTO verses (sura, aya, text) VALUES (39, 16, 'Onların üstlerinde ateşten tabakalar, altlarında da tabakalar vardır. Allah, kullarını işte bununla korkutuyor. Ey kullarım! Benden sakının.');
INSERT INTO verses (sura, aya, text) VALUES (39, 17, 'Tağuta ibadet etmekten kaçınıp Allah''a yönelenlere müjde vardır. Kullarımı müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (39, 18, 'Onlar, sözü dinleyip en güzeline uyarlar. Onlar, Allah’ın kendilerine hidayet ettiği kimselerdir. Onlar, akıl sahibi kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 19, 'Üzerine azap kelimesi hak olmuş kimseye (hidayet edemezsin), ateşte olanı da sen mi kurtaracaksın?');
INSERT INTO verses (sura, aya, text) VALUES (39, 20, 'Fakat Rabbine karşı gelmekten sakınanlar için (cennette) üst üste yapılmış ve altlarından ırmaklar akan köşkler vardır. Allah, gerçek bir vaadde bulunmuştur. Allah, va’dinden dönmez.');
INSERT INTO verses (sura, aya, text) VALUES (39, 21, 'Allah''ın gökten su indirdiğini, onu yerden kaynaklara geçirdiğini, sonra onunla değişik renklerde ekinler çıkardığını görmedin mi? Sonra kurur ve sen onu sararmış halde görürsün. Sonra onu bir çöp haline getirir. Şüphesiz bunda akıl sahipleri için bir öğüt vardır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 22, 'Allah''ın kalbini İslâm''a açtığı kimse Rabbinden bir nur üzere değil midir? Allah''ın zikrine karşı kalpleri kaskatı olanların vay hallerine! İşte onlar apaçık bir sapıklık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (39, 23, 'Allah, ayetleri birbirine benzeyen ve yer yer tekrar eden kitabı, sözlerin en güzeli olarak indirmiştir. Rablerinden korkanların bu kitaptan tüyleri ürperir, sonra hem derileri ve hem de kalpleri Allah''ın zikrine ısınıp yumuşar. İşte bu kitap Allah''ın hidayetidir. Onunla istediğini doğru yola hidayet eder. Allah kimi de saptırırsa artık ona yol gösteren bulunmaz.');
INSERT INTO verses (sura, aya, text) VALUES (39, 24, 'Kıyamet günü azabın en kötüsünden yüzünü korumaya çalışan kimse(nin durumu) ne olur? Zalimlere: "Kazanmakta olduklarınızı tadın!" denir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 25, 'Onlardan öncekiler de yalanlamışlardı da hiç farkında olmadıkları bir yerden azap onlara geliverdi.');
INSERT INTO verses (sura, aya, text) VALUES (39, 26, 'Allah, onlara dünya hayatında da rezilliği tattırdı. Ahiret azabı ise çok daha büyüktür. Keşke bunu bilselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (39, 27, 'Andolsun biz, belki öğüt alırlar diye bu Kur''an''da insanlara her türlü misali verdik.');
INSERT INTO verses (sura, aya, text) VALUES (39, 28, 'Sakınıp takvalı olsunlar diye hiçbir eğriliği bulunmayan Arapça bir Kur''an. (indirdik)');
INSERT INTO verses (sura, aya, text) VALUES (39, 29, 'Allah, birbiriyle çekişen bir çok ortağa bağlı olan bir adamla, yalnız bir kişiye bağlı bir adamı örnek olarak vermiştir. Bu ikisinin durumu eşit midir? Hamt, Allah’a mahsustur. Fakat onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (39, 30, '(Ey Muhammed!) Şüphesiz sen öleceksin ve şüphesiz onlar da ölecekler.');
INSERT INTO verses (sura, aya, text) VALUES (39, 31, 'Sonra siz kıyamet günü Rabbinizin huzurunda davalaşacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (39, 32, 'Allah’a karşı yalan uyduran veya kendisine hak gelince onu yalanlayan kimseden daha zalim kim olabilir? Kâfirler için Cehennem''de barınacak yer mi yok?');
INSERT INTO verses (sura, aya, text) VALUES (39, 33, 'Doğruyu getiren ve doğrulayanlar (var ya), işte onlar takva sahibi olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 34, 'Onlar için Rableri katında diledikleri her şey vardır. İşte bu ihsan edenlerin mükâfatıdır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 35, 'Çünkü Allah onların yaptıklarının en kötülerini örtecek ve kendilerine yapmakta olduklarının en güzeliyle karşılık verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 36, 'Allah, kuluna yetmez mi? Seni O’ndan (Allah’tan) başkalarıyla korkutmaya çalışıyorlar. Allah, kimi saptırırsa artık onun için bir yol gösterici yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (39, 37, 'Allah kime de hidayet ederse, artık onu da saptıracak yoktur. Allah Aziz ve intikam sahibi değil midir?');
INSERT INTO verses (sura, aya, text) VALUES (39, 38, 'Andolsun eğer onlara; “Gökleri ve yeri kim yarattı?” diye sorsan, elbette “Allah”, derler. De ki: “Peki söyleyin bakalım? Allah’ı bırakıp da ibadet ettikleriniz var ya; eğer Allah bana herhangi bir zarar dokundurmak isterse, onlar Allah’ın dokundurduğu zararı kaldırabilirler mi? Yahut Allah bana bir rahmet dilese, onlar O’nun rahmetini engelleyebilirler mi?” De ki: “Allah bana yeter. Tevekkül edenler ancak O’na tevekkül ederler.”');
INSERT INTO verses (sura, aya, text) VALUES (39, 39, 'De ki: "Ey milletim! Durumunuzun gerektirdiğini yapın; doğrusu ben de yapacağım. Elbette yakında bileceksiniz."');
INSERT INTO verses (sura, aya, text) VALUES (39, 40, 'Kime rezil edici bir azabın geleceğini, kalıcı azabın kimin üzerine ineceğini ileride bileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (39, 41, 'Şüphesiz biz bu kitabı sana, insanlar için hak olarak indirdik. Artık kim doğru yolu seçerse kendi lehinedir. Kim de saparsa ancak kendi aleyhine sapmış olur. Sen onların üzerinde vekil değilsin.');
INSERT INTO verses (sura, aya, text) VALUES (39, 42, 'Allah ölümleri vaktinde ruhları alır, ölmeyeninkini de uykusunda (alır). Hakkında ölüm hükmünü verdiğini alıkor, diğerini ise belirli bir süreye kadar salıverir. Muhakkak bunda iyice düşünen bir topluluk için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 43, 'Yoksa Allah’tan başka şefaatçiler mi edindiler? De ki: “Hiçbir şeye güçleri yetmese ve düşünemiyor olsalar da mı?”');
INSERT INTO verses (sura, aya, text) VALUES (39, 44, '“Şefaat, tümüyle Allah’a aittir. Göklerin ve yerin mülkü O’nundur. Sonra O’na döndürüleceksiniz.''''');
INSERT INTO verses (sura, aya, text) VALUES (39, 45, 'Allah, bir tek (ilah) olarak anıldığında ahirete iman etmeyenlerin kalpleri daralır. Allah’tan başkaları (ilahları) anıldığında ise hemen sevince kapılırlar.');
INSERT INTO verses (sura, aya, text) VALUES (39, 46, 'De ki: “Ey göklerin ve yerin yaratıcısı olan, gaybı da görünen âlemi de bilen Allah’ım! Ayrılığa düştükleri şeyler konusunda kulların arasında Sen hükmedersin.”');
INSERT INTO verses (sura, aya, text) VALUES (39, 47, 'Eğer yeryüzünde bulunan her şey tümüyle ve onlarla beraber bir o kadarı da zulmedenlerin olsa, kıyamet günü kötü azaptan kurtulmak için elbette onları verirlerdi. Artık hiç hesap etmedikleri şeyler, Allah tarafından karşılarına çıkmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 48, '(Dünyada) kazandıkları şeylerin kötülükleri karşılarına çıkmış, alay etmekte oldukları şey onları kuşatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 49, 'İnsana bir zarar dokunduğunda bize yalvarır. Sonra ona tarafımızdan bir nimet verdiğimizde; “Bu, bana ancak bilgim sayesinde verilmiştir.” der. Hayır! O bir imtihandır. Fakat onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (39, 50, 'Kendilerinden önce gelenler de böyle söylemişti. Fakat kazandıkları kendilerine fayda sağlamamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (39, 51, 'Sonunda da kazandıkları o amellerin kötülükleri kendilerine gelip çattı. Bunlardan zulmedenleri de kazandıklarının kötülükleri yakında gelip bulacaktır ve onlar (Allah''ı) aciz bırakacak değildir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 52, 'Allah’ın, rızkı dilediğine bol verdiğini ve (dilediğine) kıstığını bilmezler mi? Bunda iman eden bir toplum için elbette ibretler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (39, 53, 'De ki: “Ey nefisleri aleyhine ileri giden kullarım. Allah’ın rahmetinden ümit kesmeyin, çünkü Allah bütün günahları mağfiret eder.” Muhakkak O, çok çok mağfiret edendir, rahmet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 54, 'Azap size gelmeden önce Rabbinize yönelin ve O’na teslim olun. Sonra size yardım olunmaz.');
INSERT INTO verses (sura, aya, text) VALUES (39, 55, 'Farkında olmadan ansızın azap size gelmezden önce Rabbinizden size indirilenin en güzeline uyun.');
INSERT INTO verses (sura, aya, text) VALUES (39, 56, 'Ki sonra hiç kimse, “Allah’a itaat hususunda gerekeni yapmadığım için yazıklar olsun bana! Ben gerçekten de (İslâm ile) alay edenler arasında yer almıştım” diyerek (kendi kendini kınamasın);');
INSERT INTO verses (sura, aya, text) VALUES (39, 57, 'Yahut “Eğer Allah bana hidayet nasip etseydi günahtan sakınanlardan olurdum” diyerek;');
INSERT INTO verses (sura, aya, text) VALUES (39, 58, 'Ya da azabı gördüğünde, “Keşke bana bir fırsat daha tanınsa da iyilerden biri olsam!” diyerek hayıflanmasın.');
INSERT INTO verses (sura, aya, text) VALUES (39, 59, '(Allah Teâlâ da, şöyle diyecek:) “Hayır, sana ayetlerim gerçekten gelmiş idi. Sen ise onları yalanlamış, büyüklenmiş ve kâfirlerden olmuş idin.”');
INSERT INTO verses (sura, aya, text) VALUES (39, 60, 'Kıyamet günü, Allah''a karşı yalan söyleyenleri, yüzleri simsiyah halde görürsün. Büyüklenenler için cehennemde barınacak yer mi yok?');
INSERT INTO verses (sura, aya, text) VALUES (39, 61, 'Allah, takva sahiplerini kurtuluşa erdirir. Onlara hiçbir fenalık dokunmaz. Onlar mahzun da olmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (39, 62, 'Allah her şeyin yaratıcısıdır. O her şeye vekildir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 63, 'Göklerin ve yerin anahtarları O’nundur. Allah’ın ayetlerini inkâr edenler var ya, işte onlar ziyana uğrayanların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 64, 'De ki: “Ey cahiller! Siz bana Allah’tan başkasına ibadet etmemi mi emrediyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (39, 65, 'Andolsun, sana ve senden önceki peygamberlere şöyle vahyedildi: “Eğer şirk koşarsan, yaptıkların boşa gider ve elbette hüsrana uğrayanlardan olursun."');
INSERT INTO verses (sura, aya, text) VALUES (39, 66, 'Öyleyse, yalnızca Allah’a ibadet et ve şükredenlerden ol.');
INSERT INTO verses (sura, aya, text) VALUES (39, 67, 'Allah’ı hakkıyla takdir edemediler. Yer tümüyle onun avucundadır, kıyamet günü gökler de sağ elinde dürülmüş olacaktır. O şirk koştuklarından münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 68, 'Sur''a üflenir, böylece Allah''ın dilediklerinden başka göklerde ve yerde kim varsa hepsi düşüp ölür. Sonra ona bir daha üflenir, bir de bakarsın onlar kalkmış bekliyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (39, 69, 'Yeryüzü, Rabbinin nuruyla aydınlanır. Kitap (amel defterleri) ortaya konur. Peygamberler ve şahitler getirilir ve zulme uğratılmaksızın aralarında adaletle hüküm verilir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 70, 'Herkes ne yaptıysa, karşılığı tastamam verilir. Allah, onların yaptıklarını en iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 71, 'Kâfirler bölük bölük Cehennem''e sürülür. Oraya geldikleri zaman kapıları açılmış ve oranın bekçileri onlara: “Size aranızdan Rabbinizin ayetlerini üzerinize okuyan ve bugününüze kavuşmakla sizi korkutan peygamberler gelmedi mi?” Onlar: “Evet, fakat azap sözü kâfirler üzerine hak olmuştur” diyecekler.');
INSERT INTO verses (sura, aya, text) VALUES (39, 72, '“Haydi! İçinde ebedî kalacağınız Cehennem''in kapılarından girin. Büyüklük taslayanların yeri ne kötüdür!” denilir.');
INSERT INTO verses (sura, aya, text) VALUES (39, 73, 'Rablerine karşı gelmekten sakınanlar ise, bölük bölük Cennet''e sevkedilir. Oraya varıp da kapıları açıldığında bekçileri onlara; "Selam size! Tertemiz geldiniz. Artık ebedî kalmak üzere girin buraya!" derler.');
INSERT INTO verses (sura, aya, text) VALUES (39, 74, '(Onlar da) Derler ki: "Bize verdiği vaadi gerçekleştiren ve bizi bu yere mirasçı kılan Allah''a hamt olsun. Salih amel işleyenlerin mükâfatı ne güzelmiş!"');
INSERT INTO verses (sura, aya, text) VALUES (39, 75, 'Melekleri de, Rablerini hamt ile tesbih edip yücelterek Arş’ın etrafını kuşatmış halde görürsün. Artık kulların arasında adaletle hüküm verilmiş ve; “Hamt âlemlerin Rabbi olan Allah’a mahsustur.” denilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 1, 'Hâ, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (40, 2, 'Bu kitap Azîz ve Alîm olan Allah tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 3, 'O günahları bağışlayan, tevbeleri kabul eden, azabı çetin ve nimeti pek bol olandır. Ondan başka ilâh yoktur, dönüş yalnız Onadır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 4, 'Allah’ın ayetleri hakkında ancak kâfirler tartışır. O halde onların şehirlerde dönüp dolaşması seni aldatmasın.');
INSERT INTO verses (sura, aya, text) VALUES (40, 5, 'Onlardan önce Nûh’un kavmi ve onlardan sonra gelen topluluklar da yalanlamıştı. Her ümmet kendi peygamberini yakalayıp cezalandırmaya azmetmişti. Hakkı yok etmek için batıl şeyler ileri sürerek tartışmışlardı. Bu yüzden onları kıskıvrak yakaladım. İşte cezalandırmamın nasıl olduğunu gör.');
INSERT INTO verses (sura, aya, text) VALUES (40, 6, 'Böylece kâfirler hakkında Rabbinin azap sözü “elbette onlar cehennemliklerdir” diye hak olmuştur.');
INSERT INTO verses (sura, aya, text) VALUES (40, 7, 'Şu Arşı yüklenenler ve etrafında bulunanlar Rablerini hamt ile tesbih ederler. Ona iman ederler, Müminlere de mağfiret dilerler. “Rabbimiz rahmetin ve ilmin her şeyi kuşatmıştır. Tevbe edenlere ve senin yolunu izleyenlere mağfiret buyur ve onları cehennem azabından koru.');
INSERT INTO verses (sura, aya, text) VALUES (40, 8, '“Ey Rabbimiz! Onları da, onların babalarından, eşlerinden ve soylarından iyi olanları da, kendilerine vadettiğin Adn Cennetleri''ne koy. Şüphesiz sen mutlak güç sahibisin, hüküm ve hikmet sahibisin.”');
INSERT INTO verses (sura, aya, text) VALUES (40, 9, 'Ve onları kötülüklerden koru. O gün, kimi kötülüklerden korursan ona rahmet etmişsindir. İşte bu, büyük kurtuluştur."');
INSERT INTO verses (sura, aya, text) VALUES (40, 10, 'Şüphesiz kâfirlere şöyle seslenilir: "Allah’ın (size) buğzu, sizin kendinize olan buğzunuzdan daha büyüktür, çünkü siz imana çağrılıyordunuz da küfürde direniyordunuz."');
INSERT INTO verses (sura, aya, text) VALUES (40, 11, 'Onlar da şöyle derler: “Ey Rabbimiz! Bizi iki defa öldürdün, iki defa da dirilttin. Günahlarımızı kabulleniyoruz. Şimdi (bu ateşten) bir çıkış yolu var mı?''''');
INSERT INTO verses (sura, aya, text) VALUES (40, 12, '"Bu (azap), bir olan Allah''a çağırıldığınız zaman küfre sapmanız ve O''na şirk koşulduğunda da (şirke) iman etmeniz sebebiyledir. Artık hüküm, yüce ve büyük olan Allah''ındır."');
INSERT INTO verses (sura, aya, text) VALUES (40, 13, 'O; size ayetlerini gösteren, sizin için gökten bir rızık indirendir. Ancak O’na yönelen, düşünüp ibret alır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 14, 'O halde kâfirlerin hoşuna gitmese de, siz dini Allah’a has kılarak O’na ibadet edin.');
INSERT INTO verses (sura, aya, text) VALUES (40, 15, 'Dereceleri yükselten, Arş''ın sahibi Allah, kavuşma günüyle korkutmak için kullarından dilediğine emriyle vahyi indirir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 16, 'O gün onlar ortaya çıkarlar. Onlardan hiçbir şey Allah''a gizli kalmaz. Bugün mülk (hükümranlık) kimindir? Kahhar olan tek Allah’ındır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 17, 'Bugün herkese kazandığının karşılığı verilir. Bugün haksızlık yoktur. Şüphesiz Allah, hesabı çarçabuk görendir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 18, 'Onları, yaklaşmakta olan güne karşı uyarıp korkut; o zaman yürekler gırtlaklara dayanır, yutkunur dururlar. Zalimler için ne koruyucu bir dost, ne de sözü dinlenir bir şefaatçi vardır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 19, 'Allah, gözlerin hain bakışını ve kalplerin gizlediğini bilir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 20, 'Allah, hak ve adaletle hükmeder. Allah’tan başka taptıkları ise hiçbir hükümde bulunamazlar. Şüphesiz Allah; hakkıyla işitendir, hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 21, 'Onlar yeryüzünde dolaşıp, kendilerinden öncekilerin akıbetlerinin nasıl olduğuna bakmadılar mı? Onlar, kendilerinden daha güçlü ve yeryüzündeki eserleri daha üstündü. Böyle iken Allah, günahları sebebiyle onları yakaladı. Onları Allah’ın azabından koruyacak hiç kimse olmadı.');
INSERT INTO verses (sura, aya, text) VALUES (40, 22, 'Bunun sebebi şu idi: Peygamberleri onlara apaçık mucizeler getiriyorlardı da onlar inkâr ediyorlardı. Bu yüzden Allah da onları yakalayıverdi. Şüphesiz O, güçlüdür, cezası da çok şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 23, 'Mûsâ’yı da ayetlerimizle ve açık bir delil ile göndermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (40, 24, 'Firavun’a, Hâmân’a ve Kârûn’a gönderdik. Dediler ki: "O bir sihirbazdır, bir yalancıdır."');
INSERT INTO verses (sura, aya, text) VALUES (40, 25, 'Böylece o, kendilerine tarafımızdan hakkı getirince; "Onunla beraber iman edenlerin oğullarını öldürün, kadınlarını sağ bırakın." dediler. Fakat kâfirlerin tuzağı hep boşa çıkmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 26, 'Firavun dedi ki: "Beni bırakın Mûsâ''yı öldüreyim de o Rabbine yalvarsın! Çünkü ben onun sizin dininizi değiştireceğinden yahut yeryüzünde bozgunculuk çıkaracağından korkuyorum."');
INSERT INTO verses (sura, aya, text) VALUES (40, 27, 'Mûsâ dedi ki: "Ben, hesap gününe inanmayan her kibirliden benim de Rabbim sizin de Rabbiniz olan (Allah)''a sığındım."');
INSERT INTO verses (sura, aya, text) VALUES (40, 28, 'Firavun ailesinden, imanını gizlemekte olan Mümin bir adam şöyle dedi: “Rabbim Allah’tır, dediği için bir adamı öldürecek misiniz? Hâlbuki o, size Rabbinizden apaçık mucizeler getirdi. Eğer yalancı ise yalanı kendi aleyhinedir. Eğer doğru söylüyorsa sizi tehdit ettiği şeylerin bir kısmı başınıza gelecektir. Şüphesiz Allah; aşırı giden, yalancılık eden kimseyi doğru yola eriştirmez.''''');
INSERT INTO verses (sura, aya, text) VALUES (40, 29, 'Ey kavmim! Bugün (bu) yerde hükümranlık sizindir; hakim olanlar sizsiniz. Fakat Allah''ın şiddetli azabı bize gelirse ona karşı bize kim yardımcı olur?" Firavun: "Ben size kendi görüşümü söylüyorum ve yine size ancak doğru yolu gösteriyorum." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (40, 30, 'İman eden kimse şöyle dedi: "Ey halkım! Doğrusu ben üzerinize önceki toplulukların günü gibi bir günün gelmesinden korkuyorum."');
INSERT INTO verses (sura, aya, text) VALUES (40, 31, '"Nûh Âd, Semûd kavminin ve ondan sonraki toplumların durumu gibi. Oysa Allah, kullarına zulmetmek istemez."');
INSERT INTO verses (sura, aya, text) VALUES (40, 32, '"Ey halkım! Ben sizin için feryat gününden korkuyorum."');
INSERT INTO verses (sura, aya, text) VALUES (40, 33, 'O gün arkanızı döner, kaçarsınız. Fakat, sizi Allah’tan koruyacak hiçbir şey yoktur. Allah kimi saptırırsa, artık onu doğru yola iletecek de yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (40, 34, 'Andolsun, daha önce Yusuf da size apaçık deliller getirmişti de, onun size getirdikleri hakkında şüphe edip durmuştunuz. Daha sonra o ölünce de, “Allah, ondan sonra asla peygamber göndermez.” demiştiniz. İşte Allah, aşırı giden şüpheci kimseleri böyle saptırır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 35, 'Bu kimseler, Allah’ın ayetleri hakkında, kendilerine gelen bir delil olmadığı halde tartışır dururlar. Bu; Allah katında da, iman edenlerin yanında da büyük bir gazap sebebidir. Allah, büyüklük taslayan her zorbanın kalbini işte böyle mühürler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 36, 'Firavun dedi ki: "Ey Hâman! Benim için bir kule yap, belki ki o yollara ulaşırım."');
INSERT INTO verses (sura, aya, text) VALUES (40, 37, '"Firavun dedi ki: "Ey Hâmân! Bana yüksek bir kule yap, belki yollara, göklerin yollarına erişirim de Mûsâ’nın ilâhını görürüm. Doğrusu şu ki, ben onu yalancı sayıyorum." Firavun''a kötü işleri işte böyle süslü gösterildi ve yoldan saptırıldı. Firavun''un tuzağı hüsrandan başka bir şey değildir."');
INSERT INTO verses (sura, aya, text) VALUES (40, 38, 'İman eden kişi şöyle dedi: "Ey halkım! Bana uyun ki, size doğru yolu göstereyim."');
INSERT INTO verses (sura, aya, text) VALUES (40, 39, '"Ey halkım! Şüphesiz bu dünya hayatı geçicidir, ama ahiret, doğrusu işte o, kalınacak yurttur."');
INSERT INTO verses (sura, aya, text) VALUES (40, 40, 'Kim bir kötülük işlerse sadece onun benzeriyle cezalandırılır. Erkek olsun, kadın olsun kim de Mümin olarak bir salih amel işlerse işte onlar cennete girerler; orada hesapsızca rızıklandırılırlar.');
INSERT INTO verses (sura, aya, text) VALUES (40, 41, 'Ey kavmim! Nedir bu hal? Ben sizi kurtuluşa çağırıyorum, siz beni ateşe çağırıyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (40, 42, 'Siz bana Allah’ı inkâr etmem ve hakkında hiçbir bilgiye sahip olmadığım şeyleri O’na ortak koşmam için çağrıda bulunuyorsunuz; ben ise sizi izzet sahibi, çok bağışlayıcı olan Allah’a davet ediyorum.');
INSERT INTO verses (sura, aya, text) VALUES (40, 43, 'Elbette beni kendisine davet ettiğiniz şeylerin dünyada ve ahrette herhangi bir daveti yoktur. Dönüşümüz muhakkak Allah’adır. Şüphesiz, aşırı gidenler cehennemliklerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 44, 'Size söylediklerimi hatırlayacaksınız. Ben işimi Allah’a havale ediyorum. Şüphesiz Allah, kullarını çok iyi görendir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 45, 'Sonunda Allah kurdukları tuzakların kötülüklerinden korudu onu, Firavun hanedanını ise kötü azap kuşattı.');
INSERT INTO verses (sura, aya, text) VALUES (40, 46, 'Onlar sabah akşam o ateşe sunulurlar. Kıyametin kopacağı gün de: Firavun ailesini azabın en çetinine sokun (denilecek)!');
INSERT INTO verses (sura, aya, text) VALUES (40, 47, 'Ateşin içinde birbirleriyle tartışırlarken zayıf olanlar büyüklük taslayanlara; “Biz size uymuş kimselerdik. Şimdi şu ateşin bir kısmını üzerimizden kaldırabilir misiniz?” derler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 48, 'Büyüklük taslayanlar da şöyle derler: "Biz hepimiz bunun içindeyiz. Şüphesiz Allah kullar arasında hüküm vermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 49, 'Ateşte olanlar Cehennem bekçilerine; “Rabbinize yalvarın da (hiç değilse) bir gün bizden azabı hafifletsin.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 50, '(Cehennem bekçileri) "Rasulleriniz size apaçık deliller getirmediler mi?” diyecekler. Onlar da: "Evet" diyecekler. (Bunun üzerine) onlar: "Öyleyse (kendiniz) dua edin." derler. Hâlbuki kâfirlerin duası hep boşunadır."');
INSERT INTO verses (sura, aya, text) VALUES (40, 51, 'Şüphesiz peygamberlerimize ve iman edenlere hem dünya hayatında, hem şahitlerin şahitlik edecekleri günde yardım ederiz.');
INSERT INTO verses (sura, aya, text) VALUES (40, 52, 'O gün zalimlere, özür dilemeleri hiçbir fayda sağlamaz. Artık lanet de onlarındır. Kötü yurt da onlarındır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 53, 'Mûsâ''ya hidayet vermiş ve İsrailoğulları''nı kitaba mirasçı kılmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (40, 54, 'O, akıl sahipleri için bir öğüt ve hidayet rehberidir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 55, '(Rasûlüm!) Şimdi sen sabret. Çünkü Allah’ın vaadi gerçektir. Günahının bağışlanmasını iste. Akşam ve sabah Rabbini hamt ile tesbih et.');
INSERT INTO verses (sura, aya, text) VALUES (40, 56, 'Kendilerine gelmiş açık bir delil olmaksızın Allah''ın ayetleri hakkında mücadele edenler var ya, onların göğüslerinde erişemeyecekleri bir büyüklükten başka bir şey yok. Artık sen Allah''a sığın. Şüphesiz O hakkıyla işiten, hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 57, 'Elbette göklerin ve yerin yaratılması insanların yaratılmasından daha büyüktür. Ancak insanların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 58, 'Kör ile gören, iman edip salih ameller işleyenler ile kötüler de bir değildir. Ne kadar az düşünüyorsunuz!');
INSERT INTO verses (sura, aya, text) VALUES (40, 59, 'Elbette kıyamet mutlaka gelecektir. Bunda hiç şüphe yoktur ama insanların çoğu iman etmezler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 60, 'Rabbiniz şöyle dedi: "Bana dua edin, size icabet edeyim. Bana ibadet etmekten büyüklenenler, aşağılanmış olarak Cehennem''e gireceklerdir."');
INSERT INTO verses (sura, aya, text) VALUES (40, 61, 'Allah Odur ki, içinde rahat bulasınız diye geceyi yaratandır. Gündüzü de aydınlık (kılan)dır. Muhakkak Allah insanlara lütufkârdır fakat insanların çoğu şükretmezler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 62, 'İşte her şeyin yaratıcısı olan Rabbiniz Allah! O’ndan başka hiçbir ilâh yoktur. Durum bu iken, nasıl oluyor da (haktan) döndürülüyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (40, 63, 'Allah’ın ayetlerini bilerek inkâr edegelenler işte böyle döndürülür.');
INSERT INTO verses (sura, aya, text) VALUES (40, 64, 'Allah, sizin için yeri bir karargâh, göğü de bir bina yapan, sizi şekillendiren ve şekillerinizi güzel yapan ve temiz şeylerle sizi rızıklandırandır. Âlemlerin Rabbi Allah pek yücedir!');
INSERT INTO verses (sura, aya, text) VALUES (40, 65, 'O, hayat sahibidir. Ondan başka (hak) ilah yoktur. Dini ona halis kılarak, yalnızca O''na dua edin. Hamt, âlemlerin Rabbi Allah’a mahsustur.');
INSERT INTO verses (sura, aya, text) VALUES (40, 66, 'De ki: "Rabbimden bana apaçık deliller gelince, Allah’tan başka dua ettiklerinize ibadet etmek bana yasak kılındı ve âlemlerin Rabbine teslim olmakla emrolundum."');
INSERT INTO verses (sura, aya, text) VALUES (40, 67, 'Sizi topraktan, sonra meniden, sonra kan pıhtısından yaratan, sonra sizi analarınızın karnından bebek olarak çıkaran, sonra sizi güçlü kuvvetli bir çağa eriştiren, derken ihtiyarlığa varacak kadar yaşatan da O''dur. Kiminiz daha önce vefat ettirilir, kiminiz de belirtilmiş bir süreye ulaşırsınız. Belki artık akledersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (40, 68, 'O, hem dirilten hem de öldürendir. O; herhangi bir işin olmasını dilediği zaman yalnız ol der, o da oluverir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 69, 'Allah’ın ayetleri hakkında tartışanları görmedin mi? Nasıl da döndürülüyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (40, 70, 'Kitabı ve rasullerimizle gönderdiklerimizi yalanlayanlar, onlar yakında bileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (40, 71, 'O zaman, boyunlarında demir halkalar ve zincirlerle sürülecekler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 72, 'Kaynar suda, sonra ateşte yakılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 73, 'Sonra onlara denilecek ki: "Ortak koştuklarınız hani nerede?"');
INSERT INTO verses (sura, aya, text) VALUES (40, 74, '“Allah’tan başka (taptıklarınız, putlarınız nerede?) Onlar: “Önümüzden kaybolup gittiler. Hayır, biz zaten önceden hiçbir şeye ibadet etmiyorduk” diyecekler. Allah kâfirleri işte böyle şaşırtır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 75, 'Bu, sizin yeryüzünde haksız yere şımarmanızdan ve böbürlenmenizden ötürüdür.');
INSERT INTO verses (sura, aya, text) VALUES (40, 76, 'Onlara: “Ebedî kalmak üzere Cehennem kapılarından girin. Büyüklük taslayanların yeri ne kötüdür!” (denir).');
INSERT INTO verses (sura, aya, text) VALUES (40, 77, 'Şu halde sen sabret. Şüphesiz Allah''ın vaadi gerçektir. Onlara vaadettiklerimizin bir kısmını sana göstersek de senin dünya hayatını sona erdirsek de, sonuçta bize döndürülürler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 78, 'Andolsun biz senden önce de rasuller gönderdik. Onlardan kimilerinin kıssalarını sana anlattık, kimilerinin de kıssalarını sana anlatmadık. Allah’ın izni olmadıkça hiçbir peygamberin kendiliğinden bir ayet getirmesi mümkün olmaz. Allah’ın emri geldiğinde hak ile hükmolunur. İşte batılcılar orada hüsrana uğrayıverirler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 79, 'Allah; kimine binesiniz, kimini yiyesiniz diye sizin için hayvanları yaratandır.');
INSERT INTO verses (sura, aya, text) VALUES (40, 80, 'Sizin için onlarda birtakım yararlar vardır. Onların üzerlerinde gönüllerinizdeki bir ihtiyaca ulaşmanız için (onlara binersiniz). Onların ve gemilerin üzerinde taşınırsınız.');
INSERT INTO verses (sura, aya, text) VALUES (40, 81, 'Allah size ayetlerini gösteriyor. Şimdi, Allah''ın ayetlerinden hangisini inkâr edersiniz?');
INSERT INTO verses (sura, aya, text) VALUES (40, 82, 'Kendilerinden öncekilerin akıbetlerinin nasıl olduğuna bakmaları için yeryüzünde gezip dolaşmadılar mı? Onlar bunlardan daha çok, kuvvetçe de, yerlerinde eserleri itibari ile de daha güçlü ve daha çetin idiler ama kazanageldikleri şeyler onlara fayda vermedi.');
INSERT INTO verses (sura, aya, text) VALUES (40, 83, 'Rasulleri onlara apaçık deliller ile geldiğinde onlar yanlarındaki ilim dolayısı ile şımardılar ve alay edegeldikleri şey onları kuşatıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (40, 84, 'Onlar bizim azabımızı gördüklerinde: "Yalnız Allah''a iman ettik ve O''na ortak koştuğumuz şeyleri inkâr ettik" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (40, 85, 'Ama bizim azabımızı gördüklerinde iman etmeleri kendilerine fayda vermedi. Bu Allah’ın kulları hakkında geçerli olagelen sünnetidir (adetidir) ve kâfirler işte burada hüsrana uğradı.');
INSERT INTO verses (sura, aya, text) VALUES (41, 1, 'Hâ, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (41, 2, 'Bu Kur’an, Rahman ve Rahîm olan Allah tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 3, '(Bu,) Bilen bir toplum için ayetleri Arapça okunarak açıklanmış bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (41, 4, 'Bu kitap, müjdeleyici ve uyarıcıdır. Fakat onların çoğu yüz çevirmiştir. Artık dinlemezler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 5, '"Bizi çağırdığın şeye karşı kalplerimizde örtüler, kulaklarımızda ağırlık vardır. Seninle bizim aramızda da bir perde vardır. O halde sen yapacağını yap. Şüphesiz biz de yapanlarız." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 6, 'De ki: "Ben de ancak sizin gibi bir insanım. Bana yalnızca, sizin ilahınızın bir tek ilah olduğu vahyolunuyor. Öyleyse ona (giden doğru yola) yönelin, ondan bağışlanma dileyin. Şirk koşanların vay haline!"');
INSERT INTO verses (sura, aya, text) VALUES (41, 7, 'Onlar ki hem zekâtı vermezler, hem de onlar Âhireti inkâr edenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 8, 'Şüphesiz iman edip salih ameller işleyenler için ise kesintisiz bir mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (41, 9, 'De ki: "Gerçekten siz, yeri iki günde yaratanı inkâr edip, O’na ortaklar mı koşuyorsunuz? O, âlemlerin Rabbidir."');
INSERT INTO verses (sura, aya, text) VALUES (41, 10, 'Orada, üstünden sabit dağlar var etti; onu bereketli kıldı ve onda soranlar (rızıklarını arayanlar) için eşit olarak gıdalarını dört günde takdir etti.');
INSERT INTO verses (sura, aya, text) VALUES (41, 11, 'Sonra duman halinde bulunan göğe yöneldi. Ona ve yere: "İsteyerek ya da istemeyerek gelin!" dedi. Onlar da: "İsteyerek geldik." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 12, 'Böylece onları yedi gök olarak iki günde varedip, her bir göğe kendi işini bildirdi. Dünya göğünü ise kandillerle/yıldızlarla süsledik ve koruduk. İşte bu; Hakim, Aziz olan (Allah''ın) takdiridir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 13, 'Eğer yüz çevirirlerse de ki: "Ben sizi Âd ve Semûd''un yıldırımları gibi bir yıldırımla uyarırım."');
INSERT INTO verses (sura, aya, text) VALUES (41, 14, 'Hani onlara rasûlleri önlerinden ve arkalarından gelip: “Allah’tan başkasına ibadet etmeyin” dediklerinde onlar: “Eğer Rabbimiz dileseydi elbette melekler indirirdi. Bu sebepten muhakkak biz sizinle gönderilenlere kâfir olanlarız” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 15, 'Âd kavmine gelince, yeryüzünde haksız yere büyüklük tasladılar ve; "Bizden daha kuvvetli kim var?" dediler. Onlar kendilerini yaratan Allah’ın, onlardan daha kuvvetli olduğunu görmediler mi? Onlar bizim ayetlerimizi (mucizelerimizi) inkâr ediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (41, 16, 'Biz de onlara, dünya hayatında aşağılayıcı azabı tattırmak için o uğursuz günlerde üzerlerine dondurucu bir kasırga gönderdik. Ahiret azabı ise daha da aşağılayıcıdır. Onlar yardım da görmezler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 17, 'Semûd''a gelince; biz onları doğru yola ilettik. Ama onlar körlüğü hidayete tercih ettiler. Bu yüzden onları kazanmakta olduklarına karşılık alçaltıcı azabın yıldırımı çarptı.');
INSERT INTO verses (sura, aya, text) VALUES (41, 18, 'İman edip sakınanları kurtardık.');
INSERT INTO verses (sura, aya, text) VALUES (41, 19, 'Allah''ın düşmanlarının toplanıp ateşe götürüldükleri gün hepsi biraraya getirilirler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 20, 'Nihayet onlar oraya geldiklerinde kulakları, gözleri, derileri işlediklerini bildirerek aleyhlerine şahitlik edecektir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 21, 'Derilerine: “Niçin aleyhimize şahitlik ettiniz” diyecekler. Onlar da: Her şeyi konuşturan Allah bizi de konuşturdu, diyecekler. Sizi ilk defa yaratan Odur. İşte yalnız Ona döndürülüyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (41, 22, '“Siz (günahları işlerken) kulaklarınızın, gözlerinizin ve derilerinizin aleyhinize şahitlik etmesinden sakınmıyordunuz. Lâkin, yaptıklarınızın çoğunu Allah’ın bilmediğini sanıyordunuz.''''');
INSERT INTO verses (sura, aya, text) VALUES (41, 23, 'İşte Rabbiniz hakkındaki bu zannınız sizi helâk etti de, hüsrana uğrayanlardan oldunuz.');
INSERT INTO verses (sura, aya, text) VALUES (41, 24, 'Şimdi eğer dayanabilirlerse, artık Cehennem onların yeridir. Eğer Allah’ın rızasını kazandıracak amelleri işlemeye izin isteseler, onlara izin verilmez.');
INSERT INTO verses (sura, aya, text) VALUES (41, 25, 'Biz onlara yakın arkadaşlar kıldık. Onlar da önlerinde ve arkalarında olanı kendilerine süslediler. Onlardan önce gelen cinlerden ve insanlardan ümmetler arasında onlar üzerine söz hak olmuştur. Şüphesiz onlar zarar edenlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (41, 26, 'O kâfirler: "Bu Kur''an''ı dinlemeyin, okunurken gürültü yapın, belki baskın çıkarsınız." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (41, 27, 'Kâfirlere elbette şiddetli bir azap tattıracağız. Onları, yaptıklarının en kötüsüyle cezalandıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (41, 28, 'İşte bu, Allah düşmanlarının cezası ateştir. Ayetlerimizi inkâr etmelerinden dolayı, orada onlara ceza olarak ebedî kalacakları yurt (Cehennem) vardır.');
INSERT INTO verses (sura, aya, text) VALUES (41, 29, 'Kâfirler derler ki: "Rabbimiz! Bizi saptıran cinleri ve insanları bize göster de onları ayaklarımızın altına alalım da en aşağılıklardan olsunlar!"');
INSERT INTO verses (sura, aya, text) VALUES (41, 30, 'Muhakkak: “Rabbimiz Allah’tır” deyip sonra dosdoğru olanların üzerine melekler: “Korkmayın, üzülmeyin ve size vaat olunan cennetle sevinin” diye inerler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 31, 'Dünya hayatında da, Âhirette de sizin velileriniz biziz. Orada canlarınız neyi arzu ediyorsa, orada neyi istiyorsanız sizin için vardır.');
INSERT INTO verses (sura, aya, text) VALUES (41, 32, 'Çokça bağışlayan, merhamet eden Allah’tan bir ikram olarak.');
INSERT INTO verses (sura, aya, text) VALUES (41, 33, 'Allah’a davet eden, salih amel işleyen ve: “Şüphesiz ki ben Müslümanlardanım” diyen kimseden daha güzel sözlü kim olabilir?');
INSERT INTO verses (sura, aya, text) VALUES (41, 34, 'İyilikle kötülük bir değildir. Kötülüğü en güzel şekilde sav. O zaman seninle aranızda düşmanlık bulunan kimse, sanki candan bir dost gibi olur.');
INSERT INTO verses (sura, aya, text) VALUES (41, 35, 'Buna ancak sabredenler kavuşturulur, buna ancak büyük bir pay sahibi olanlar kavuşturulur.');
INSERT INTO verses (sura, aya, text) VALUES (41, 36, 'Şeytan''dan sana bir vesvese gelirse, hemen Allah’a sığın. Allah her şeyi işitendir. Her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 37, 'O’nun ayetlerinden bir kısmı da gece ile gündüz, Güneş ve Aydır. Güneşe de secde etmeyin, Ay''a da. Eğer yalnız Allah’a ibadet ediyorsanız onları yaratan Allah’a secde edin.');
INSERT INTO verses (sura, aya, text) VALUES (41, 38, 'Şayet büyüklenmek isterlerse Rabbinin yanında bulunanlar hiç usanmadan onu gece ve gündüz tesbih eder dururlar.');
INSERT INTO verses (sura, aya, text) VALUES (41, 39, 'Onun ayetlerinden biri de yeri kupkuru görmendir. Biz üzerine suyu indirdiğimizde sarsılır ve kabarır. Onu dirilten şüphesiz ki ölüleri de dirilticidir. Çünkü O, her şeye kadirdir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 40, 'Ayetlerimiz hakkında doğru yoldan sapanlar muhakkak onlar bize gizli kalmazlar. O halde ateşe atılacak kimse mi hayırlıdır yoksa kıyamet gününde emin olarak gelen kimse mi? Dilediğinizi yapın, çünkü o ne yaptığınızı çok iyi görendir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 41, 'Kendilerine kitap geldiğinde onu inkâr ettiler. Hâlbuki o, aziz bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (41, 42, 'Önünden de, arkasından da batıl ona erişemez. O, hüküm ve hikmet sahibi, övülmeye lâyık olan Allah tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 43, 'Sana söylenenler, senden önceki rasûllere söylenenlerden başka bir şey değildir. Süphesiz Rabbin, hem mağfiret sahibidir, hem de elem verici bir azap sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 44, 'Eğer biz onu başka dilde bir Kur’an yapsaydık onlar mutlaka, “Onun âyetleri genişçe açıklanmalı değil miydi? Başka dilde bir kitap ve Arap bir peygamber öyle mi?” derlerdi. De ki: "Bu Kur''an, iman edenler için bir hidayet ve bir şifadır. İman etmeyenlerin kulaklarında bir ağırlık vardır ve o, onlar için bir körlüktür.” İşte onlar (sanki kendilerine) uzak bir yerden seslenilmekte (de duymuyor gibiler).');
INSERT INTO verses (sura, aya, text) VALUES (41, 45, 'Andolsun biz Mûsâ’ya o kitabı verdik de, hakkında ayrılığa düşüldü. Daha önce Rabbin tarafından verilmiş bir söz olmasaydı, aralarında hüküm verilmiş olurdu. Onlar, hâlâ bundan şek ve şüphe içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (41, 46, 'Kim salih amel işlerse kendisi içindir. Kim de kötülük yaparsa kendi aleyhinedir. Rabbin, kullara asla zulmedici değildir.');
INSERT INTO verses (sura, aya, text) VALUES (41, 47, '(Kıyamet) Saatinin ilmi sadece Allah’a aittir. Onun bilgisi dışında hiçbir meyve tomurcuğundan çıkmaz, hiçbir dişi de ne gebe kalır, ne de doğurur. Allah; onlara: "Nerede ortaklarım?" diye seslendiği gün derler ki: (Ortağın olduğuna dair) Bizden hiç bir şahidin olmadığını sana bildiririz."');
INSERT INTO verses (sura, aya, text) VALUES (41, 48, 'Daha önce dua/ibadet ettikleri şeyler onlardan kaybolup gitmiştir. Bir kaçış yolu olmadığını anlamışlardır.');
INSERT INTO verses (sura, aya, text) VALUES (41, 49, 'İnsan, iyilik istemekten usanmaz da, kendisine bir kötülük gelince umutsuzluğa düşer, karamsar olur.');
INSERT INTO verses (sura, aya, text) VALUES (41, 50, 'Andolsun ki kendisine dokunan bir darlıktan sonra ona rahmetimizden tattırsak o elbette şöyle der: “Bu benimdir. Ben kıyametin kopacağını da sanmıyorum. Eğer Rabbime döndürülsem de şüphesiz benim için onun yanında iyilik vardır. Andolsun biz kâfir olanlara ne yaptıklarını haber vereceğiz ve andolsun onlara çok şiddetli azaptan tattıracağızdır.”');
INSERT INTO verses (sura, aya, text) VALUES (41, 51, 'Biz insana nimet verdiğimizde yüz çevirir, yan çizip uzaklaşır. Eğer ona kötülük isabet ederse bu sefer de uzun uzun dua eder.');
INSERT INTO verses (sura, aya, text) VALUES (41, 52, 'De ki: "Kur''an Allah katından gelmiş olup da siz de onu inkar etmişseniz, söyleyin bana, derin/uzak bir çıkmazda bulunan kimseden daha sapık kim vardır?"');
INSERT INTO verses (sura, aya, text) VALUES (41, 53, 'İnsanlara ufuklarda ve kendi nefislerinde ayetlerimizi göstereceğiz ki onun (Kur''an''ın) gerçek olduğu, onlara iyice belli olsun. Rabbinin her şeye şahit olması yetmez mi?');
INSERT INTO verses (sura, aya, text) VALUES (41, 54, 'İyi bilin ki, onlar Rablerine kavuşma konusunda şüphe içindedirler. İyi bilin ki, O, her şeyi kuşatandır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 1, 'Hâ, Mîm.');
INSERT INTO verses (sura, aya, text) VALUES (42, 2, 'Ayn, Sîn, Kâf.[1]');
INSERT INTO verses (sura, aya, text) VALUES (42, 3, 'Azîz ve Hakîm olan Allah, sana ve senden öncekilere işte böyle vahyediyor.');
INSERT INTO verses (sura, aya, text) VALUES (42, 4, 'Göklerde ve yerde ne varsa O’nundur. O; üstündür/en üsttedir, çok Azîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 5, 'Neredeyse yukarılarından gökler çatlayacak! Melekler, Rablerini hamt ederek tesbih ederler. Yeryüzündekiler için bağışlanma dilerler. İyi bilin ki Allah; çok bağışlayıcıdır, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 6, 'Allah’tan başka dostlar edinenlere gelince, Allah onları daima gözetlemektedir. Sen onlara vekil değilsin.');
INSERT INTO verses (sura, aya, text) VALUES (42, 7, 'Böylece biz sana Arapça bir Kur’an vahyettik ki, şehirlerin anası Mekke’de ve çevresinde bulunanları uyarasın. Hakkında asla şüphe olmayan toplanma günüyle onları uyarasın. Bir grup Cennet''te, bir grup ise Cehennem''dedir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 8, 'Eğer Allah dileseydi onları tek bir ümmet kılardı. Fakat dilediği kimseyi rahmetine alır. O zalimlerin ise hiçbir dost ve hiçbir yardımcıları yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 9, 'Yoksa onlar, O’ndan başka veliler mi edindiler? Oysa Allah, veli O’dur. Ölüleri dirilten O’dur. Her şeye gücü yeten O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 10, 'Hakkında anlaşmazlığa düştüğünüz konuda hüküm Allah’a aittir. İşte o Allah, benim Rabbimdir. O’na tevekkül ettim ve O’na yöneldim.');
INSERT INTO verses (sura, aya, text) VALUES (42, 11, 'Gökleri ve yeri yaratandır. Size kendi nefislerinizden eşler ve davarlardan da çiftler yaratmıştır. Sizi de bu şekilde yaratıp çoğaltmaktadır. O’nun benzeri hiçbir şey yoktur. Her şeyi işiten ve gören O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 12, 'Göklerin ve yerin anahtarları O’nundur. O, dilediğine rızkını bol bol verir ve dilediğine de daraltır. Çünkü O, her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 13, 'O “dini dosdoğru tutun, onda ayrılığa düşmeyin” diye dinden Nûh’a tavsiye ettiğini, sana vahyettiğimizi, İbrahim, Mûsâ ve İsa’ya tavsiye ettiğimizi size de şeriat yaptı. Senin onları kendisine davet ettiğin şey, müşriklere büyük geldi. Allah dilediği kimseyi buna seçer ve döneni buna hidayet eder.');
INSERT INTO verses (sura, aya, text) VALUES (42, 14, 'Onlar kendilerine ilim geldikten sonra, sadece aralarındaki düşmanlık yüzünden ayrılığa düştüler. Eğer Rabbinden belirlenmiş bir süreye kadar bir söz geçmiş olmasaydı, derhal aralarında hüküm verilmiş olurdu. Onların ardından kitaba mirasçı olanlar da elbette ondan bir şüphe ve tereddüt içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (42, 15, 'O halde davet et ve emrolunduğun gibi dosdoğru ol, onların arzularına uyma ve de ki: “Ben Allah’ın indirdiği bütün kitaplara iman ettim. Aranızda adalet yapmakla emrolundum. Allah bizim de Rabbimizdir, sizin de Rabbinizdir. Bizim amellerimiz bizim, sizin amelleriniz de sizindir. Bizimle sizin aranızda artık bir delile gerek yoktur. Allah hepimizi bir arada toplayacaktır ve dönüş yalnız Onadır.”');
INSERT INTO verses (sura, aya, text) VALUES (42, 16, '(Bu dine) icabet olunduktan sonra, Allah hakkında tartışmaya girenlerin delilleri, Rableri katında boştur. Onlar için bir gazap, yine onlar için çetin bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 17, 'Allah hak ile kitabı ve mizanı indirendir. Ne bilirsin, saat/kıyamet belki de yakındır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 18, 'Ona iman etmeyenler, onun çabucak gelmesini istiyorlar. İman edenler ise ondan korkarlar ve onun hak olduğunu bilirler. Bilin ki kıyamet hakkında tartışanlar uzak/derin bir sapıklık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (42, 19, 'Allah, kullarına karşı çok lütufkârdır. Dilediğini rızıklandırır. Çok kuvvetli ve güçlü olan O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 20, 'Kim ahiret ekinini/sevabını isterse, onun ekinini/sevabını artırırız. Kim dünya ekinini isterse ona da ondan veririz. Onun ahirette bir nasibi/payı yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 21, 'Yoksa, Allah’ın izin vermediği bir dini kendilerine bir din kılan ortakları mı var? Eğer (azabın ertelenmesine dair) kesin bir hüküm olmasaydı, aralarında hemen hükmedilirdi. Gerçekten zalimler için acı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 22, 'O başlarına geldiği zaman, kazandıkları yüzünden zalimlerin korku içinde olduklarını görürsün. İman edip salih amel yapanlar ise Cennet bahçelerindedirler. Onlar için Rableri katında ne isterlerse vardır. İşte büyük lütuf budur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 23, 'İşte bu Allah''ın, iman edip salih ameller işleyen kullarını müjdelediği şeydir. De ki: "Ben buna karşılık sizden akrabalık sevgisinden başka bir ücret istemiyorum." Kim bir iyilik işlerse, ona iyiliği artırırız. Gerçekten Allah, çokça mağfiret edendir, Şekûr''dur (karşılıklarını bol bol verir).');
INSERT INTO verses (sura, aya, text) VALUES (42, 24, 'Yoksa onlar: "(Senin hakkında) Allah''a karşı yalan uyduruyor mu?” diyorlar. Eğer Allah dilerse, kalbini mühürler. Allah batılı yok eder, hakkı sözleriyle gerçekleştirir. Çünkü O, kalplerde olanı çok iyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 25, 'Kullarından tevbeyi kabul eden, günahları affeden ve yaptıklarınızı bilen O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 26, 'İman eden ve salih amel yapanlara icabet eder ve onlara lütfunu artırır. Kâfirlere gelince, onlara şiddetli bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 27, 'Şayet Allah; kullarına rızkı yaymış olsaydı, elbette yeryüzünde azgınlık ederlerdi. Fakat O, dilediği miktarda indirir. Çünkü O, kullarının her şeyinden haberdardır, görendir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 28, '(Kulları) umutlarını kestikten sonra yağmur indirip rahmetini yayan O’dur. O''dur gerçek veli (ve) hamde layık olan.');
INSERT INTO verses (sura, aya, text) VALUES (42, 29, 'Göklerin ve yerin yaratılması ve oralarda canlıların yayılması da O’nun ayetlerindendir. Dilediği zaman onları toplamaya kadir olan da O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 30, 'Size isabet eden her musibet, ellerinizle kazandıklarınız sebebiyledir. (Bununla beraber Allah) Çoğunu affeder.');
INSERT INTO verses (sura, aya, text) VALUES (42, 31, 'Yeryüzünde (O''nu) aciz bırakamazsınız. Sizin Allah’tan başka bir veliniz de, yardımcınız da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 32, 'Deniz de dağlar gibi gemilerin akıp gitmesi onun ayetlerindendir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 33, 'Dilerse O, rüzgârı durdurur da onun (denizin) üstünde kalakalırlar. İşte bunda da çok sabreden ve şükreden herkes için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 34, 'Veya işledikleri sebebiyle onları helâk eder, bir çoğunu da affeder.');
INSERT INTO verses (sura, aya, text) VALUES (42, 35, 'Ayetlerimiz hakkında mücadele edenler bilsinler ki onların kaçıp kurtulacağı bir yer yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 36, 'Size verilen herhangi bir şey dünya hayatının bir geçimliğidir/metaıdır. Allah katında olanlar ise, iman edenler ve yalnızca Rablerine tevekkül edenler için daha hayırlı ve daha kalıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 37, 'Günahın büyüğünden ve fuhşiyattan kaçınanlar, öfkelendikleri zaman bağışlarlar.');
INSERT INTO verses (sura, aya, text) VALUES (42, 38, 'Rablerinin (tevhid davetine) icabet ederler, namazlarını ikame ederler. Onların işleri aralarındaki şûrâ iledir. Kendilerine verdiğimiz rızıklardan da infak ederler.');
INSERT INTO verses (sura, aya, text) VALUES (42, 39, 'Bir haksızlığa uğradıkları zaman, yardımlaşırlar.');
INSERT INTO verses (sura, aya, text) VALUES (42, 40, 'Bir kötülüğün cezası, onun benzeri/denk bir kötülüktür. Kim de affeder ve ıslah ederse, onun mükâfatı Allah’a aittir. Allah, zalimleri sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (42, 41, 'Zulme uğradıktan sonra hakkını alan kimse için, artık onların aleyhine bir yol/sorumluluk yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 42, 'Ceza yolu ancak insanlara zulmedenler ve yeryüzünde haksız yere taşkınlık edenler içindir. İşte onlar için elem dolu bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (42, 43, 'Kim de sabreder ve bağışlarsa, işte bu azim gerektiren işlerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 44, 'Allah kimi saptırırsa, artık bundan sonra onun hiçbir velisi yoktur. Azabı gördükleri zaman, zalimlerin şöyle dediğini göreceksin: "Geri dönmeye bir yol var mı?"');
INSERT INTO verses (sura, aya, text) VALUES (42, 45, 'Ateşe arz olunurlarken onların, zilletten başlarını öne eğerek göz ucuyla gizli gizli baktıklarını göreceksin. İman edenler şöyle der: "Hüsrana uğrayanlar, kıyamet günü hem kendilerini, hem de ailelerini hüsrana uğratmışlardır." Şunu iyi bilin ki, zalimler kalıcı bir azap içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (42, 46, 'Onların, Allah’tan başka kendilerine yardım edecek hiçbir velileri yoktur. Allah’ın saptırdığı kimse için bir yol yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (42, 47, 'Allah’tan, geri çevrilmesi imkânsız olan bir gün gelmeden önce Rabbinizin çağrısına uyun. O gün sizin için ne sığınacak bir yer vardır, ne de (günahlarınızı) inkâr edebilirsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (42, 48, 'Eğer yüz çevirirlerse, seni onlar üzerine gözetleyici olarak göndermedik. Sana düşen ancak tebliğ etmektir. Biz insana kendimizden bir rahmet tattırdığımız zaman ona sevinir. Eğer kendi eliyle işledikleri sebebiyle bir kötülük dokunursa, insan hemen nankör kesilir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 49, 'Göklerin ve yerin mülkü (hükümranlığı) Allah’a aittir. Dilediğini yaratır, dilediğine kız çocukları dilediğine erkek çocukları bağışlar.');
INSERT INTO verses (sura, aya, text) VALUES (42, 50, 'Yahut onları erkekler ve dişiler olarak çift kılar. Dilediğini de kısır yapar. Şüphesiz O, her şeyi bilen ve güç yetirendir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 51, 'Bir insanın, vahiy dışında veya perde arkasından ya da bir elçi gönderilmeksizin Allah ile konuşması mümkün değildir. İşte bu şekilde O, dilediğine kendi izni ile vahyeder. O; çok üstündür, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (42, 52, 'İşte bu şekilde sana da emrimizden bir ruhu/Kur''an''ı vahyettik. Sen kitap nedir, iman nedir bilmezdin. Fakat biz onu kullarımızdan dilediğimizi kendisiyle doğru yola eriştirdiğimiz bir nur kıldık. Şüphesiz sen, dosdoğru bir yolu göstermektesin.');
INSERT INTO verses (sura, aya, text) VALUES (42, 53, 'Göklerdeki ve yerdeki her şeyin sahibi olan Allah’ın yoluna. İyi bilin ki, bütün işler sonunda Allah’a döner.');
INSERT INTO verses (sura, aya, text) VALUES (43, 1, 'Hâ, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (43, 2, 'Apaçık kitaba andolsun ki.');
INSERT INTO verses (sura, aya, text) VALUES (43, 3, 'Biz onu anlayasınız diye Arapça Kur’an kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (43, 4, 'O, katımızdaki ana kitaptadır/Levh-i Mahfuz''dadır. Pek yüce ve hikmet doludur.');
INSERT INTO verses (sura, aya, text) VALUES (43, 5, 'Siz azgınlık eden bir toplumsunuz diye şimdi o zikri (uyarı dolu Kur''an''ı) bir yana mı bırakalım?');
INSERT INTO verses (sura, aya, text) VALUES (43, 6, 'Biz, öncekiler arasında nice peygamberler gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (43, 7, 'Onlara bir nebi geldikçe muhakkak onunla alay ederlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (43, 8, 'Biz onlardan kuvvet itibarı ile daha çetin olanları helak ettik. Öncekilerin misali daha önce geçmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 9, 'Onlara: "Gökleri ve yeri kim yarattı?" diye sorsan: "Onları, Azîz ve Alîm olan (Allah) yarattı." derler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 10, 'O, yeryüzünü size beşik yapan ve gideceğiniz yere ulaşasınız diye sizin için orada yollar var edendir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 11, 'O, gökten bir ölçüyle su indirendir. Onunla ölü bir beldeyi canlandırdık. Siz de işte böyle çıkarılacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (43, 12, 'O bütün çiftleri yaratmış ve sizin için gemilerden ve hayvanlardan bineceğiniz şeyleri var etmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 13, 'Ta ki onların üstüne binerken Rabbinizin nimetini hatırlayasınız ve şöyle diyesiniz: "Emrine boyun eğdirerek bunları, bizim hizmetimize veren (Allah''ı) tesbih ve takdis ederiz. Yoksa biz bunlara güç yetiremezdik."');
INSERT INTO verses (sura, aya, text) VALUES (43, 14, 'Ve biz elbette Rabbimize döneceğiz."
(diyesiniz)');
INSERT INTO verses (sura, aya, text) VALUES (43, 15, '(Böyleyken) kullarından O''na bir kısım (kız çocuk) isnat ettiler. Doğrusu insan apaçık bir nankördür.');
INSERT INTO verses (sura, aya, text) VALUES (43, 16, 'Yoksa (Allah) yarattıklarından kendine kızlar edindi de oğulları size mi seçti?');
INSERT INTO verses (sura, aya, text) VALUES (43, 17, 'Oysa onlardan birine Rahman''a isnat ettiği (kız çocuk) müjdelendiği zaman içi öfkeyle dolarak yüzü simsiyah kesilir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 18, 'Süs içinde yetiştirilip mücadelede açık olmayanı mı (Allah''a yakıştırıyorlar)?');
INSERT INTO verses (sura, aya, text) VALUES (43, 19, 'Rahman’ın kulları olan melekleri dişi saydılar. Onların yaratılışlarına mı şahit oldular? Onların bu şahitlikleri yazılacak ve onlara sorulacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (43, 20, '"Eğer Rahman dilemiş olsaydı, biz onlara ibadet etmezdik." dediler. Onların bu hususta bir bilgileri yoktur. Onlar, sadece yalan söylemektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 21, 'Yoksa daha önceden onlara bir kitap verdik de, onlar o kitaba mı tutunuyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (43, 22, 'Bilâkis şöyle dediler: "Biz, atalarımızı bir din üzerinde bulduk ve onların izinde dosdoğru gitmekteyiz."');
INSERT INTO verses (sura, aya, text) VALUES (43, 23, 'Senden önce de hangi kasabaya bir uyarıcı gönderdiysek mutlaka oranın şımarık varlıklıları böylece: “Biz atalarımızı bir din üzere bulduk ve muhakkak bizler onların izlerine uyanlarız” demişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 24, '“Ya ben size atalarınızı üzerinde bulduğunuz dinden daha doğrusunu getirdi isem de mi” dedi. Onlar: "Biz, sizinle gönderilene kâfir kimseleriz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 25, 'Bunun üzerine biz de onlardan intikam aldık. Bir bak! Yalanlayanların akıbeti nasıl oldu?');
INSERT INTO verses (sura, aya, text) VALUES (43, 26, 'Hani İbrahim babasına ve kavmine demişti ki: "Ben sizin ibadet ettiklerinizden beriyim/uzağım."');
INSERT INTO verses (sura, aya, text) VALUES (43, 27, '"Ancak beni yaratan müstesna. Muhakkak O, bana hidayet edecektir."');
INSERT INTO verses (sura, aya, text) VALUES (43, 28, 'Bunu, ardından geleceklere devamlı kalıcı bir söz olarak bıraktı ki, insanlar (tevhid dinine) dönsünler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 29, 'Evet! Onları ve atalarını, kendilerine hak/Kur''an ve (her şeyi) apaçık (açıklayan) bir rasûl gelinceye kadar nimetlendirdim.');
INSERT INTO verses (sura, aya, text) VALUES (43, 30, 'Onlara hak geldiği zaman: "Bu bir sihirdir, biz ona küfreden kimseleriz." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 31, '"Bu Kur’an, iki şehrin büyüklerinden bir adama indirilmeli değil miydi?" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 32, 'Rabbinin rahmetini onlar mı taksim ediyor? Dünya hayatında onların geçimliklerini aralarında biz paylaştırdık. Birbirlerine iş gördürmeleri için kimini ötekine derecelerle üstün kıldık. Rabbinin rahmeti onların (dünyada) topladıklarından daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (43, 33, 'Eğer insanlar (küfürde birleşen) tek bir ümmet olacak olmasaydı, Rahman''a küfredenlerin evlerinin tavanlarını ve çıkacakları merdivenleri gümüşten yapardık.');
INSERT INTO verses (sura, aya, text) VALUES (43, 34, 'Kapılarını ve arkalarına yaslandıkları koltukları da.');
INSERT INTO verses (sura, aya, text) VALUES (43, 35, 'Ve (daha nice) çekici süsler de (verirdik). Bütün bunlar, yalnızca dünya hayatının geçimliğidir. Ahiret ise, senin Rabbinin katında takva sahipleri içindir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 36, 'Kim Rahman''ın zikrinden yüz çevirirse, ona bir Şeytan sararız da o Şeytan artık onun yakın dostu olur.');
INSERT INTO verses (sura, aya, text) VALUES (43, 37, 'Şüphesiz bu Şeytanlar; onları doğru yoldan alıkoyarlar da onlar, kendilerinin doğru yolda olduklarını sanırlar.');
INSERT INTO verses (sura, aya, text) VALUES (43, 38, 'Nihayet, o bize geldiği zaman: "Keşke benimle senin aranda doğu ve batı kadar uzaklık olsaydı. Ne kötü bir dostmuşsun!" derler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 39, 'O gün bu (pişmanlık) size bir fayda sağlamayacaktır. Çünkü siz, zulmettiniz. Azapta da artık ortaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (43, 40, 'Şimdi, sağıra sen mi işittireceksin veya kör olan ve apaçık sapıklıkta bulunan kimseye sen mi hidayete ileteceksin?');
INSERT INTO verses (sura, aya, text) VALUES (43, 41, 'Biz, seni alıp götürsek de onlardan yine intikam alacağız.');
INSERT INTO verses (sura, aya, text) VALUES (43, 42, 'Yahut onları tehdit ettiğimiz azabı sana gösteririz, çünkü biz onlara güç yetirenleriz.');
INSERT INTO verses (sura, aya, text) VALUES (43, 43, 'Sen, sana vahyolunana sımsıkı tutun. Çünkü sen, dosdoğru bir yol üzerindesin!');
INSERT INTO verses (sura, aya, text) VALUES (43, 44, 'Şüphesiz bu Kur’an; sana ve kavmine bir şereftir, ondan sorguya çekileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (43, 45, 'Senden önce gönderdiğimiz peygamberlerimize sor. Rahman’dan başka ibadet edilecek ilâhlar kılmış mıyız?');
INSERT INTO verses (sura, aya, text) VALUES (43, 46, 'Mûsâ''yı ayetlerimizle Firavun’a ve kavminin ileri gelenlerine göndermiştik: "Şüphesiz ben, âlemlerin Rabbinin rasûlüyüm." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (43, 47, 'Onlara ayetlerle geldiği zaman bunlara gülüp geçmişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (43, 48, 'Onlara gösterdiğimiz her ayet, bir evvelkinden daha büyük idi. Belki dönerler diye onları azabımızla yakalamıştık.');
INSERT INTO verses (sura, aya, text) VALUES (43, 49, 'Bunun üzerine dediler ki: "Ey büyücü! Sana verdiği ahde göre bizim için Rabbine dua et. Çünkü biz artık hidayeti kabul edeceğiz."');
INSERT INTO verses (sura, aya, text) VALUES (43, 50, 'Fakat biz azabı üzerlerinden kaldırınca hemen verdikleri sözü bozdular.');
INSERT INTO verses (sura, aya, text) VALUES (43, 51, 'Firavun kavmine seslenerek: "Ey kavmim! Mısır’ın ve altımda akan şu ırmakların mülkü bana ait değil mi? Bunu görmüyor musunuz?"');
INSERT INTO verses (sura, aya, text) VALUES (43, 52, '"Yoksa ben, şu hakir ve neredeyse konuşamayan adamdan daha iyi değil miyim?"');
INSERT INTO verses (sura, aya, text) VALUES (43, 53, 'Ona altın bilezikler verilmeli veya onunla birlikte yakınında yer alan (yardımcı) melekler gelmeli değil miydi?');
INSERT INTO verses (sura, aya, text) VALUES (43, 54, 'O kavmini küçümsedi onlar da ona boyun eğdiler. Çünkü onlar yoldan çıkmış bir kavimdi.');
INSERT INTO verses (sura, aya, text) VALUES (43, 55, 'Onlar bizi öfkelendirdikleri zaman, onların hepsini suda boğarak onlardan intikam aldık.');
INSERT INTO verses (sura, aya, text) VALUES (43, 56, 'Böylece onları sonradan geleceklere (ibret olarak) selef ve örnek kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (43, 57, 'Meryem oğlu bir misal olarak verilince hemen senin kavmin bundan dolayı bağrışıp çağrışmaya koyuldu.');
INSERT INTO verses (sura, aya, text) VALUES (43, 58, '"Bizim ilahlarımız mı daha iyidir; yoksa o mu?" dediler. Bunu sana sadece tartışmak için söylüyorlar. Zaten onlar, kavgacı bir toplumdur.');
INSERT INTO verses (sura, aya, text) VALUES (43, 59, 'O, yalnızca kendisine nimet verdiğimiz ve İsrailoğulları’na örnek kıldığımız bir kuldur.');
INSERT INTO verses (sura, aya, text) VALUES (43, 60, 'Eğer dileseydik, yeryüzünde sizin yerinize geçecek melekler var ederdik.');
INSERT INTO verses (sura, aya, text) VALUES (43, 61, 'Şüphesiz o (İsa), kıyamet için bir ilimdir/delildir. O halde, kıyametten yana bir şüpheniz olmasın. Bana uyun. Dosdoğru yol budur.');
INSERT INTO verses (sura, aya, text) VALUES (43, 62, 'Şeytan sakın sizi saptırmasın. Çünkü o, sizin için apaçık bir düşmandır.');
INSERT INTO verses (sura, aya, text) VALUES (43, 63, 'İsa, apaçık delillerle geldiği zaman şöyle demişti: "Ben size hikmeti getirdim ve hakkında ayrılığa düştüğünüz şeylerden bir kısmını size açıklamak için geldim. Allah’tan sakının ve bana itaat edin."');
INSERT INTO verses (sura, aya, text) VALUES (43, 64, '"Şüphesiz Allah; benim de Rabbim, sizin de Rabbinizdir. O’na ibadet edin! Doğru yol budur."');
INSERT INTO verses (sura, aya, text) VALUES (43, 65, 'Fırkalar/gruplar, aralarında (İsa hakkında) anlaşmazlığa düştüler. O acı günün azabına uğrayacak zalimlerin vay haline.');
INSERT INTO verses (sura, aya, text) VALUES (43, 66, 'Onlar, farkında olmadıkları bir anda ansızın kendilerine gelecek kıyametten başka bir şey mi bekliyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (43, 67, 'O gün, takva sahibi olan kimselerden başka bütün dostlar birbirine düşmandır.');
INSERT INTO verses (sura, aya, text) VALUES (43, 68, 'Ey kullarım, bugün size bir korku yoktur, siz üzülmezsiniz de.');
INSERT INTO verses (sura, aya, text) VALUES (43, 69, 'Onlar ki, ayetlerimize iman etmişler ve teslim olmuşlardır.');
INSERT INTO verses (sura, aya, text) VALUES (43, 70, 'Siz ve eşleriniz ağırlanmış olarak sevinç içinde girin Cennet''e!');
INSERT INTO verses (sura, aya, text) VALUES (43, 71, 'Etraflarında altın tepsiler ve kadehler dolaştırılır. Orada canların çektiği ve gözlerin zevk aldığı her şey vardır. Siz, orada ebedî kalacak olanlarsınız.');
INSERT INTO verses (sura, aya, text) VALUES (43, 72, 'Yapmakta olduklarınız dolayısıyla sizin varis olduğunuz Cennet işte budur!');
INSERT INTO verses (sura, aya, text) VALUES (43, 73, 'Orada sizin için bir çok meyveler vardır, onlardan yersiniz.');
INSERT INTO verses (sura, aya, text) VALUES (43, 74, 'Suçlular/günahkârlar ise Cehennem azabında ebedîdirler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 75, 'Onlardan (azap) hafifletilmeyecek ve orada onlar ümitlerini kaybetmiş kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 76, 'Onlara biz zulmetmedik, fakat onlar kendi kendilerine zulmettiler.');
INSERT INTO verses (sura, aya, text) VALUES (43, 77, '"Ey Malik! Rabbin işimizi bitirsin." diye haykırırlar. O da: "Siz, kalıcısınız!" der.');
INSERT INTO verses (sura, aya, text) VALUES (43, 78, 'Size hakkı getirmiştik. Fakat çoğunuz haktan hoşlanmamıştınız.');
INSERT INTO verses (sura, aya, text) VALUES (43, 79, 'Onlar (size hile kurmakta) işi sağlama aldıklarını mı düşünüyorlar? İşte biz de işi sağlam tutuyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (43, 80, 'Yoksa onlar, bizim kendilerinin sırlarını ve gizli konuşmalarını işitmediğimizi mi sanıyorlar? Hayır! Elçilerimiz de onların yanında yazıyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (43, 81, 'De ki: "Eğer Rahman’ın bir oğlu olsaydı, ona ibadet edenlerin ilki ben olurdum."');
INSERT INTO verses (sura, aya, text) VALUES (43, 82, 'Göklerin ve yerin Rabbi, arşın Rabbi onların vasıflandırmalarından münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 83, 'Bırak onları, kendilerine vadedilen güne kavuşuncaya kadar dalsınlar ve oynaya dursunlar.');
INSERT INTO verses (sura, aya, text) VALUES (43, 84, 'O gökte de ilâh olandır/ibadet olunandır, yerde de ilâhtır/ibadet olunandır. O Hakîmdir, Alîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (43, 85, 'Göklerin, yerin ve ikisi arasındakilerin mülkü kendisine ait olan ne yücedir. Kıyamet saatinin ilmi O’nun katındadır ve O’na döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (43, 86, 'Allah''ı bırakıp da dua/ibadet ettikleri (ilahlar) şefaat edemezler. Ancak bilerek hakka şahitlik edenler bunun dışındadır.');
INSERT INTO verses (sura, aya, text) VALUES (43, 87, 'Onlara kendilerini kimin yarattığını sorsan, elbette “Allah” derler. Buna rağmen (haktan) nasıl çeviriliyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (43, 88, '(Rasûlullah''ın:) "Ya Rabbi! Bunlar, iman etmeyen bir kavimdir." demesini de (Allah biliyor).');
INSERT INTO verses (sura, aya, text) VALUES (43, 89, 'Şimdilik sen onlara aldırma/yüz çevir ve selam de. Yakında bilecekler.');
INSERT INTO verses (sura, aya, text) VALUES (44, 1, 'Hâ, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (44, 2, 'Apaçık kitaba andolsun ki.');
INSERT INTO verses (sura, aya, text) VALUES (44, 3, 'Biz onu, mübarek bir gecede indirdik. Biz, uyaranlarız.');
INSERT INTO verses (sura, aya, text) VALUES (44, 4, 'O gecede hikmetli her bir iş tarafımızdan bir emir ile ayrılır.');
INSERT INTO verses (sura, aya, text) VALUES (44, 5, 'Tarafımızdan bir emir olarak. Doğrusu biz, (rasûller) gönderenleriz.');
INSERT INTO verses (sura, aya, text) VALUES (44, 6, 'Rabbinden bir rahmet olarak. Şüphesiz O; her şeyi işitendir, bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (44, 7, 'Göklerin, yerin ve arasındakilerin Rabbidir. Eğer gerçekten bilenler iseniz.');
INSERT INTO verses (sura, aya, text) VALUES (44, 8, 'O’ndan başka (hak) ilah yoktur. Diriltir ve öldürür. Sizin de Rabbiniz, sizden önceki atalarınızın da Rabbidir.');
INSERT INTO verses (sura, aya, text) VALUES (44, 9, 'Fakat, onlar şüphe içinde oynayıp eğlenirler.');
INSERT INTO verses (sura, aya, text) VALUES (44, 10, 'Göğün apaçık bir duman getireceği günü gözle!');
INSERT INTO verses (sura, aya, text) VALUES (44, 11, 'O insanları bürür. Bu, acı bir azaptır.');
INSERT INTO verses (sura, aya, text) VALUES (44, 12, '"Rabbimiz! Azabı bizden kaldır. Doğrusu biz iman eden kimseleriz. (derler)"');
INSERT INTO verses (sura, aya, text) VALUES (44, 13, 'Nerede onlarda öğüt almak? Hâlbuki kendilerine apaçık bir rasûl gelmişti.');
INSERT INTO verses (sura, aya, text) VALUES (44, 14, 'Sonra ondan yüz çevirmişler ve: "Öğretilmiş bir mecnun/deli." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (44, 15, 'Biz, bu azabı kısa bir süre kaldıracağız, siz de yine eski hâlinize döneceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (44, 16, 'Büyük bir şiddetle yakalayacağımız gün, elbette intikam alacağız.');
INSERT INTO verses (sura, aya, text) VALUES (44, 17, 'Onlardan önce Firavun kavmini de imtihan etmiştik. Onlara şerefli bir elçi gelmişti.');
INSERT INTO verses (sura, aya, text) VALUES (44, 18, '"Allah’ın kullarını (İsrailoğulları''nı) bana verin/teslim edin. Ben güvenilir bir peygamberim." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (44, 19, 'Allah’a karşı üstünlük taslamayın. Ben size apaçık bir delil getiriyorum.');
INSERT INTO verses (sura, aya, text) VALUES (44, 20, 'Ve ben, beni taşlamanızdan sizin de Rabbiniz olan Rabbime sığındım.');
INSERT INTO verses (sura, aya, text) VALUES (44, 21, 'Eğer bana iman etmediyseniz, benden uzak durun.');
INSERT INTO verses (sura, aya, text) VALUES (44, 22, 'Mûsâ: "Bunlar, günahkâr bir toplumdur." diyerek Rabbine dua etmişti.');
INSERT INTO verses (sura, aya, text) VALUES (44, 23, 'Kullarımı geceleyin yola çıkar, siz takip olunacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (44, 24, 'Denizi sakın olarak bırak! Şüphesiz onlar, suda boğulacak bir ordudur.');
INSERT INTO verses (sura, aya, text) VALUES (44, 25, 'Onlar, nice bahçeleri ve pınarları terk ettiler.');
INSERT INTO verses (sura, aya, text) VALUES (44, 26, 'Ekinleri, güzel konakları.');
INSERT INTO verses (sura, aya, text) VALUES (44, 27, 'İçinde eğlenip durdukları nimetleri.');
INSERT INTO verses (sura, aya, text) VALUES (44, 28, 'İşte böyle! Biz onları başka bir kavme miras verdik.');
INSERT INTO verses (sura, aya, text) VALUES (44, 29, 'Onlara ne gök ağladı, ne de yer! Onlar mühlet verilenler de olmadı.');
INSERT INTO verses (sura, aya, text) VALUES (44, 30, 'Andolsun ki biz İsrailoğullarını o aşağılayıcı azaptan kurtardık.');
INSERT INTO verses (sura, aya, text) VALUES (44, 31, 'Firavun''dan. Çünkü o, haddi aşanlardan bir zorba idi.');
INSERT INTO verses (sura, aya, text) VALUES (44, 32, 'Şüphesiz biz onları bir ilim üzere âlemlere karşı üstün kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (44, 33, 'Onlara, içinde açık bir imtihan bulunan mûcizeler verdik.');
INSERT INTO verses (sura, aya, text) VALUES (44, 34, 'Şüphesiz bunlar elbette şöyle diyorlar:');
INSERT INTO verses (sura, aya, text) VALUES (44, 35, '"Bir defa öldükten sonra başka bir şey yoktur. Biz, yeniden diriltilecek de değiliz."');
INSERT INTO verses (sura, aya, text) VALUES (44, 36, 'Eğer doğru söylüyorsanız, haydi atalarımızı getirin.');
INSERT INTO verses (sura, aya, text) VALUES (44, 37, 'Onlar mı hayırlı; yoksa Tubba halkı ve onlardan öncekiler mi? Biz, onları helâk ettik. Çünkü onlar suçlu/günahkâr idiler.');
INSERT INTO verses (sura, aya, text) VALUES (44, 38, 'Biz yeri, göğü ve arasındakileri oyun olsun diye yaratmadık.');
INSERT INTO verses (sura, aya, text) VALUES (44, 39, 'Onları ancak hak ile yarattık. Fakat onların çoğu bilmez.');
INSERT INTO verses (sura, aya, text) VALUES (44, 40, 'Muhakkak ki hüküm/ayırt etme günü onların hepsi için tayin edilmiş bir vakittir.');
INSERT INTO verses (sura, aya, text) VALUES (44, 41, 'O gün, dostun dosta hiçbir şekilde faydası olmaz. Onlara yardım da olunmaz.');
INSERT INTO verses (sura, aya, text) VALUES (44, 42, 'Allah’ın rahmet ettikleri müstesnâ. Şüphesiz ki o Azîzdir, Rahîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (44, 43, 'Zakkum ağacı.');
INSERT INTO verses (sura, aya, text) VALUES (44, 44, 'Günahkârın yemeğidir.');
INSERT INTO verses (sura, aya, text) VALUES (44, 45, 'Erimiş maden gibidir, karınlarda kaynar.');
INSERT INTO verses (sura, aya, text) VALUES (44, 46, 'Kaynar suyun kaynaması gibi.');
INSERT INTO verses (sura, aya, text) VALUES (44, 47, '"Onu şiddetle tutun, Cehennem''in ortasına atın."');
INSERT INTO verses (sura, aya, text) VALUES (44, 48, '"Sonra kaynar suyun azabından başının üstüne dökün."');
INSERT INTO verses (sura, aya, text) VALUES (44, 49, '"Tat bakalım! Hani sen güçlü ve şerefliydin."');
INSERT INTO verses (sura, aya, text) VALUES (44, 50, 'İşte bu sizin hakkında şüphe ettiğiniz şeydir.');
INSERT INTO verses (sura, aya, text) VALUES (44, 51, 'Takva sahibi olanlar ise, onlar güvenli bir makamdadırlar.');
INSERT INTO verses (sura, aya, text) VALUES (44, 52, 'Cennetlerde ve pınarlardadırlar.');
INSERT INTO verses (sura, aya, text) VALUES (44, 53, 'Halis ipek ve parlak atlastan elbiseler giyerek karşılıklı otururlar.');
INSERT INTO verses (sura, aya, text) VALUES (44, 54, 'İşte böyle! Onları iri gözlü hurilerle evlendirmişizdir.');
INSERT INTO verses (sura, aya, text) VALUES (44, 55, 'Orada güven içinde her meyveyi isterler.');
INSERT INTO verses (sura, aya, text) VALUES (44, 56, 'İlk ölümden başka bir ölüm tatmazlar. Onlar Cehennem azabından korunmuştur.');
INSERT INTO verses (sura, aya, text) VALUES (44, 57, 'Rabbinden bir lütuf olarak. İşte büyük kurtuluş budur.');
INSERT INTO verses (sura, aya, text) VALUES (44, 58, 'Öğüt alsınlar diye onu senin dilin ile kolaylaştırdık.');
INSERT INTO verses (sura, aya, text) VALUES (44, 59, 'O halde bekle! Zaten onlar da bekliyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (45, 1, 'Hâ, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (45, 2, 'Bu kitap; Azîz ve Hakîm olan Allah tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (45, 3, 'Şüphesiz göklerde ve yerde iman edenler için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 4, 'Sizin yaratılışınızda da yeryüzünde yaydığı canlılarda da iyice bilen bir toplum için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 5, 'Gece ve gündüzün değişip durmasında, Allah’ın gökten bir rızık indirip onunla yeri ölümünden sonra diriltmesinde ve rüzgârları evirip çevirmesinde de aklını kullanan bir topluluk için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 6, 'İşte bunlar, sana hak olarak okuduğumuz Allah’ın ayetleridir. Artık Allah’tan ve onun ayetlerinden sonra hangi söze inanacaklar?');
INSERT INTO verses (sura, aya, text) VALUES (45, 7, 'Yazıklar olsun yalancı günahkâra!');
INSERT INTO verses (sura, aya, text) VALUES (45, 8, 'O Allah’ın ayetleri kendisine okunurken işitir de sonra onları işitmemiş gibi büyüklük taslayarak ısrar eder. İşte ona çok acıklı bir azabı müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (45, 9, 'Ayetlerimizden bir şey öğrendiğinde de o, onları alaya alır. İşte onlara alçaltıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 10, 'Önlerinden Cehennem (beklemektedir)! Kazandıkları hiçbir şey, Allah’ın dışında edindikleri evliyalar onlara fayda vermez. Onlar için büyük bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 11, 'Bu (kitap), bir hidayettir. Rablerinin ayetlerine kâfirlik edenlere acı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 12, 'İçinde emri ile gemiler akıp gitsin, O’nun lütfunu arayasınız ve şükredesiniz diye Allah denizleri sizin hizmetinize vermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (45, 13, 'Göklerde bulunan şeyleri de, yerde bulunan şeylerin hepsini de (kendi katından) sizin hizmetinize sunmuştur. İşte bunda da düşünen bir toplum için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 14, 'İman edenlere söyle. Allah''ın (azap) günlerinin geleceğini ummayanları bağışlasınlar. Çünkü Allah, her kavmi kazandıklarıyla cezalandıracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 15, 'Kim salih amel yaparsa kendisi içindir. Kim de kötülük yaparsa o da kendi aleyhinedir. Sonunda Rabbinize döndürüleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (45, 16, 'İsrailoğulları''na da kitap, hüküm ve peygamberlik vermiştik. Onları temiz şeylerle rızıklandırmış ve âlemlere üstün kılmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (45, 17, 'Din konusunda onlara apaçık deliller vermiştik. Kendilerine ilim geldikten sonra, aralarındaki bağy/zulüm yüzünden anlaşmazlığa düşmüşlerdi. Şüphesiz Rabbin, kıyamet günü aralarında anlaşmazlığa düştükleri konuda hüküm verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (45, 18, 'Sonra sana da emrimiz ile bir şeriat/yol gösterdik. Ona uy, bilmeyenlerin heveslerine uyma.');
INSERT INTO verses (sura, aya, text) VALUES (45, 19, 'Zira onlar Allah’tan gelecek bir şeyi senden savamazlar. Zalimler, birbirlerinin velisidir. Allah da takva sahiplerinin velisidir.');
INSERT INTO verses (sura, aya, text) VALUES (45, 20, 'Bu (Kur’an), insanlar için basiret ve iyice bilen bir toplum için hidayet ve rahmettir.');
INSERT INTO verses (sura, aya, text) VALUES (45, 21, 'Yoksa kötülük işleyenler, ölümlerinde ve hayatlarında kendilerini iman edip salih amel yapanlarla bir tutacağımızı mı sanıyorlar. Ne kötü hüküm veriyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (45, 22, 'Allah, her nefis kazanmakta olduklarıyla karşılık görsün diye gökleri ve yeri hak olarak yarattı. Onlara zulmedilmez.');
INSERT INTO verses (sura, aya, text) VALUES (45, 23, 'Sen, kendi hevasını ilah edinen ve Allah''ın bir ilim üzere kendisini saptırdığı, kulağı ve kalbi üzerine mühür vurduğu ve gözü üstüne de bir perde çektiği kimseyi gördün mü? Artık Allah''tan sonra ona kim hidayet verecektir? Hâlâ ibret almayacak mısınız?');
INSERT INTO verses (sura, aya, text) VALUES (45, 24, '"Dünya hayatımızdan başka hayat yoktur. Ölürüz ve yaşarız. Bizi zamandan başka bir şey yok etmez." derler. Onların bu konuda bir bilgileri yoktur. Onlar, yalnızca zannederler.');
INSERT INTO verses (sura, aya, text) VALUES (45, 25, 'Kendilerine ayetlerimiz apaçık okunduğunda onların bütün delilleri: “Eğer doğru söyleyenler iseniz haydi babalarınızı getiriniz” demekten ibaretti.');
INSERT INTO verses (sura, aya, text) VALUES (45, 26, 'De ki: "Size hayat veren sonra öldürecek olan sonra da hakkında şüphe olmayan kıyamet gününde bir araya getirecek olan Allah’tır." Fakat insanların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (45, 27, 'Göklerle yerin mülkü Allah’ındır. Kıyametin kopacağı günde, işte o günde batıl peşinde gidenler zarara uğrayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 28, 'O gün, her ümmeti diz üstü çökmüş görürsün. Her ümmet, kendi kitabına çağrılır: "Bugün, yaptıklarınızın karşılığını göreceksiniz!" denir.');
INSERT INTO verses (sura, aya, text) VALUES (45, 29, '"İşte bu, size karşı hakkı söyleyen kitabımızdır. Esasen biz sizin işlediklerinizi yazdırıyorduk"(denilecek).');
INSERT INTO verses (sura, aya, text) VALUES (45, 30, 'İman edip, salih amelleri işleyenlere gelince; Rableri onları rahmetine/Cennet''ine sokacaktır. İşte bu, apaçık kurtuluştur.');
INSERT INTO verses (sura, aya, text) VALUES (45, 31, 'Kâfir olanlara gelince: “Ayetlerim sizlere okunmadı mı? Siz de büyüklük taslayıp, günahkâr kimseler olmadınız mı?”');
INSERT INTO verses (sura, aya, text) VALUES (45, 32, '"Allah’ın verdiği söz haktır ve kıyametin kopacağında şüphe yoktur." denildiği zaman: "Kıyametin ne olduğunu bilmiyoruz. Yalnız onun hakkında (gerçekten olacağını) sadece zannediyoruz. Bu konuda kesin bir bilgi sahibi değiliz" derdiniz.');
INSERT INTO verses (sura, aya, text) VALUES (45, 33, 'Yaptıklarının kötülükleri onlara görünmüş, alay edip durdukları şey onları kuşatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (45, 34, '(Kendilerine) şöyle denir: "Siz bu gününüzle karşılaşmayı unuttuğunuz gibi biz de bugün sizi unuturuz. Barınağınız ateştir ve sizin için yardımcılar da yoktur."');
INSERT INTO verses (sura, aya, text) VALUES (45, 35, 'Bu, Allah''ın ayetlerini alaya aldığınız ve dünya hayatı sizi aldattığı içindir. Artık bugün ateşten çıkarılmazlar ve Allah’ın rızasını kazandıracak amelleri işleme istekleri kabul edilmez.');
INSERT INTO verses (sura, aya, text) VALUES (45, 36, 'Hamt, göklerin Rabbi, yerin Rabbi, âlemlerin Rabbi olan Allah’a mahsustur.');
INSERT INTO verses (sura, aya, text) VALUES (45, 37, 'Büyüklük ve azamet göklerde ve yerde yalnız Onundur. O, Azîzdir, Hakîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (46, 1, 'Hâ, Mîm.[1]');
INSERT INTO verses (sura, aya, text) VALUES (46, 2, 'Bu kitap; Azîz ve Hakîm olan Allah tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (46, 3, 'Biz; gökleri, yeri ve ikisi arasında bulunanları ancak hak ile ve belli bir süre için yarattık. Buna rağmen kâfirler yine de uyarıldıkları şeylerden yüz çevirmektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (46, 4, 'De ki: "Allah''tan başka taptıklarınızı gördünüz mü? Onların yerden neyi yarattıklarını bana gösterin. Yoksa onların göklerde bir ortaklıkları mı var? Eğer doğru sözlü iseniz bana bundan başka bir kitap veya bir ilim kalıntısı getirin.');
INSERT INTO verses (sura, aya, text) VALUES (46, 5, 'Allah''ı bırakıp da kıyamet gününe kadar kendisine cevap veremeyecek şeylere dua/ibadet edenden daha sapık kim olabilir? (Oysa) onlar, bunların dualarından/ibadetlerinden habersizdirler.');
INSERT INTO verses (sura, aya, text) VALUES (46, 6, 'İnsanlar (kıyamet günü) toplandığında, o taptıkları kendilerine düşman oluverir, onların ibadetlerini de inkâr ederler.');
INSERT INTO verses (sura, aya, text) VALUES (46, 7, 'Onlara açık belgeler olarak ayetlerimiz okunduğu zaman, o küfre sapanlar kendilerine gelmiş olan hak için, “Bu, apaçık bir büyüdür” derler.');
INSERT INTO verses (sura, aya, text) VALUES (46, 8, 'Yoksa; “Onu uydurdu mu?” diyorlar. De ki: "Eğer onu uydurmuşsam, Allah''tan bana (gelecek) olan hiç bir şeye (karşı) malik olamazsınız. O, sizin onun hakkında söylediklerinizi çok daha iyi bilir. Benimle sizin aranızda şahit olarak o yeter. O; çok bağışlayıcıdır, çok merhametlidir."');
INSERT INTO verses (sura, aya, text) VALUES (46, 9, 'De ki: "Ben, rasullerin ilki değilim. Bana ve size neler yapılacak bilmiyorum. Ben, ancak bana vahyedilene tabi oluyorum. Ben, apaçık bir uyarıcıdan başka bir şey değilim."');
INSERT INTO verses (sura, aya, text) VALUES (46, 10, 'De ki: “Söyleyin bakalım; eğer (bu Kur''an) Allah katından ise, siz de onu inkâr etmişseniz, İsrailoğulları''ndan bir şahit de bunun bir benzerine şahitlik edip iman etmişse ve siz de (iman etmeyerek) büyüklük taslamışsanız (o zaman bu büyük zulüm ve küfür değil midir?) Şüphesiz Allah, zalim topluma hidayet etmez."');
INSERT INTO verses (sura, aya, text) VALUES (46, 11, 'Kâfirler, iman edenler hakkında; "Bu iş bir hayır olsaydı, (bu hayra uymakta) onlar bizi geçemezlerdi. Oysa onlar, onunla hidayete eremediklerinden dolayı bu, eski bir yalandır." derler.');
INSERT INTO verses (sura, aya, text) VALUES (46, 12, 'Ondan önce, öncü/örnek ve rahmet olan Mûsâ’nın kitabı vardı. Bu (Kur''an) da, zulmedenleri uyarmak ve iyilik yapanlara müjde olmak üzere Arap lisanıyla indirilmiş, doğrulayıcı bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (46, 13, '“Rabbimiz Allah’tır” deyip sonra da dosdoğru istikamet üzere olanlara bir korku yoktur. Onlar üzülmeyeceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (46, 14, 'Onlar Cennet ehlidirler. Yapmakta olduklarına karşılık orada ebedî kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (46, 15, 'Biz; insana, anne ve babasına iyi davranmasını emrettik. Annesi onu güçlük içinde taşımış ve güçlükle doğurmuştur. Onun taşınması ve sütten kesilmesi otuz aydır. Ta ki bülûğ çağına ulaştığı ve kırk yaşına eriştiği zaman: "Rabbim! Bana, ana-babama verdiğin nimetine şükretmemi, razı olacağın salih amelleri yapmamı bana ilham et. Benim için soyumu da ıslah et. Ben, sana tevbe ettim ve ben sana teslim olanlardanım." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (46, 16, 'İşte onlar o kimselerdir ki, onlardan işlediklerinin (amellerinin) en güzelini kabul ederiz, onların günahlarını bağışlarız. Onlar Cennetlikler arasındadırlar. Kendilerine yapılan vaat, kendilerine yapılagelen doğru bir vaaddir.');
INSERT INTO verses (sura, aya, text) VALUES (46, 17, 'Anne ve babasına; "Öf be! Siz de, benden önce nice nesiller gelip geçmiş iken beni yeniden diriltip, (kabrimden) çıkartılmakla mı tehdit ediyorsunuz?" diyen kimseye, anne ve babası Allah''tan isteyerek; "Yazıklar olsun sana! İman et, şüphesiz Allah’ın vaadi haktır." (derler. O ise:) "Bu, öncekilerin masallarından başka bir şey değildir." diye cevap verir.');
INSERT INTO verses (sura, aya, text) VALUES (46, 18, 'İşte onlar; cinlerden ve insanlardan, kendilerinden önce gelip geçmiş toplumlar arasında haklarında (azap) sözü gerçekleşmiş olanlardır. Onlar, hüsrana uğrayanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (46, 19, 'Herkesin, yaptıklarına göre dereceleri vardır. Herkese işlediklerinin karşılığı ödenir ve kendilerine zulmedilmez.');
INSERT INTO verses (sura, aya, text) VALUES (46, 20, 'Kâfirler, ateşe sunulduğu gün: "Dünya hayatınızda bütün iyiliklerinizi yitirdiniz. Onlardan isteğiniz gibi faydalandınız. Bugün ise, dünyada haksız yere büyüklenmeniz ve fasıklık yapmanız sebebiyle alçaltıcı bir azap ile cezalandırılacaksınız." denir.');
INSERT INTO verses (sura, aya, text) VALUES (46, 21, 'Âd kavminin kardeşini (Hûd''u) an! Zira o, kendinden önce ve sonra uyarıcıların da gelip geçtiği Ahkâf bölgesindeki kavmine: "Allah''tan başkasına ibadet etmeyin. Ben sizin büyük bir günün azabına uğramanızdan korkuyorum." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (46, 22, 'Onlar da: "Bizi, ilahlarımızdan döndürmek için mi geldin? Eğer doğru sözlülerden isen bizi tehdit ettiğin şeyi haydi bize getir." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (46, 23, 'O da: "İlim ancak Allah’ın yanındadır. Ben size benimle gönderilenleri tebliğ ediyorum, fakat ben sizin cahillik eden bir topluluk olduğunuzu görüyorum." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (46, 24, 'Nihayet onu, vadilerine doğru yayılan bir bulut şeklinde görünce: "Bu bize yağmur yağdıracak yaygın bir buluttur." dediler. Hayır! O, sizin acele gelmesini istediğiniz şeydir. İçinde acı azap bulunan bir rüzgârdır!');
INSERT INTO verses (sura, aya, text) VALUES (46, 25, 'O (rüzgâr), Rabbinin emriyle her şeyi yıkar, mahveder. Nitekim (o kasırga gelince) onların evlerinden başka bir şey görülmez oldu. İşte biz, suç işleyen toplumu böyle cezalandırırız.');
INSERT INTO verses (sura, aya, text) VALUES (46, 26, 'Andolsun, size vermediğimiz imkânı/gücü onlara vermiştik. Kendilerine kulaklar, gözler ve kalpler vermiştik. Fakat kulakları, gözleri ve kalpleri kendilerine bir yarar sağlamadı. Çünkü Allah’ın ayetlerini inatla inkâr ediyorlardı. Alaya aldıkları şey onları kuşattı.');
INSERT INTO verses (sura, aya, text) VALUES (46, 27, 'Andolsun, biz çevrenizdeki memleketleri de yok ettik ve onlara ayetleri tekrar tekrar açıkladık. Belki dönerler diye.');
INSERT INTO verses (sura, aya, text) VALUES (46, 28, 'Allah''tan başka kendilerine yakınlık sağlamak için ilah edindikleri şeyler, kendilerine yardım etselerdi ya! Aksine onlardan uzaklaştılar. Çünkü o, onların uydurduğu kendi yalanlarıdır.');
INSERT INTO verses (sura, aya, text) VALUES (46, 29, 'Hani cinlerden bir grubu, Kur’an''ı dinlemeleri için sana yöneltmiştik. Kur’an''ı dinlemeye hazır olunca (birbirlerine); "Susup, dinleyin!" demişler, Kur''an''ın okunması bitince uyarıcılar olarak kavimlerine dönmüşlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (46, 30, 'Onlara şöyle demişlerdi: "Ey kavmimiz! Biz; Mûsâ’dan sonra indirilen, kendisinden öncekini tasdik eden, hakka ve dosdoğru yola hidayet eden bir kitap dinledik."');
INSERT INTO verses (sura, aya, text) VALUES (46, 31, 'Ey kavmimiz! Allah''ın davetçisine uyun. Ona iman edin ki, Allah da sizin günahlarınızı bağışlasın ve sizi acı bir azaptan korusun.');
INSERT INTO verses (sura, aya, text) VALUES (46, 32, '"Kim Allah''a davet edene icabet etmezse artık o, yeryüzünde (Allah''ı) aciz bırakıcı değildir ve onun O''ndan başka velileri de yoktur. İşte onlar, apaçık bir sapıklık içindedirler."');
INSERT INTO verses (sura, aya, text) VALUES (46, 33, 'Görmediler mi ki gökleri ve yeri yaratan ve bunları yaratmakla yorulmayan Allah, ölüleri diriltmeye de güç yetirir? Evet, şüphesiz O her şeye güç yetirendir.');
INSERT INTO verses (sura, aya, text) VALUES (46, 34, 'Küfre sapanlar ateşe sunuldukları gün; “Bu gerçek değil miymiş?” denir. Onlar; “Evet! Rabbimize andolsun ki gerçekmiş.” derler. Allah; “Öyle ise küfretmekte olduklarınızdan dolayı azabı tadın!” der.');
INSERT INTO verses (sura, aya, text) VALUES (46, 35, '(Ey Muhammed!) Rasullerden büyük azim sahiplerinin sabrettiği gibi sen de sabret ve hunlar için acele etme. Onlar tehdit edildikleri azabı gördükleri gün, sanki dünyada gündüzün bir anından başka kalmadıklarını sanırlar. Bu bir bildiridir. Ancak yoldan çıkmış olan topluluk helâk edilir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 1, 'Kâfir olup, Allah yolundan alıkoyanlar var ya; işte Allah onların bütün amellerini boşa çıkarmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 2, 'İman edip salih amel işleyenlerin ve Rableri tarafından hak olarak Muhammed''e indirilen kitaba iman edenlerin kötülüklerini Allah örter ve durumlarını ıslah eder.');
INSERT INTO verses (sura, aya, text) VALUES (47, 3, 'Bu, kâfirlerin batıla; iman edenlerin ise Rablerinden gelen hakka tabi olmalarından dolayıdır. İşte Allah, insanlara kendi örneklerini böyle verip göstermektedir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 4, 'Kâfirlerle, (savaşta) karşılaştığınız zaman boyunlarına vurun! Onları iyice bozguna uğratınca (esirleri) sımsıkı bağlayın. Sonra savaş, yüklerini atıp sona erince de onları ya karşılıksız olarak ya da fidye ile salıverin. İşte böyle! Eğer Allah dileseydi, (iman edenler, kâfirlere karşı savaş yapmadan da) galip gelirdi. Fakat bu, sizi birbirinizle denemek içindir. Allah yolunda öldürülenlerin amellerini Allah asla boşa çıkarmayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 5, 'Onlara hidayet edecek ve hallerini düzeltecektir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 6, 'Onları, kendilerine tanıttığı Cennet''e koyacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 7, 'Ey İman edenler! Eğer Allah’a yardım ederseniz, O da size yardım edecek ve ayaklarınızı sabit kılacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 8, 'Kâfirlere gelince, helâk onlaradır ve (Allah) onların amellerini boşa çıkaracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 9, 'Bu, Allah''ın indirdiğini hoşlanmamalarından ötürüdür. O da onların amellerini boşa çıkarmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 10, 'Yeryüzünde dolaşıp da, kendilerinden öncekilerin sonlarının nasıl olduğuna bakmadılar mı? Allah onları yerle bir etti. O kâfirler için de bunun bir benzeri vardır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 11, 'Bu, Allah''ın, iman edenlerin velisi olmasından dolayıdır. Küfre sapanlar (var ya), onların velisi yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (47, 12, 'Şüphesiz Allah, iman edip, salih ameller işleyenleri içinden ırmaklar akan Cennetlere koyacaktır. Kâfirler ise (dünya zevklerinden) yararlanırlar ve hayvanların yediği gibi yerler. Onların kalacakları yer ateştir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 13, '(Ey Muhammed!) Seni çıkaran kendi memleket halkından daha güçlü nice memleket halkları vardı ki, biz onları helâk ettik. Onların hiçbir yardımcısı da olmadı.');
INSERT INTO verses (sura, aya, text) VALUES (47, 14, 'Şimdi Rabbinden apaçık bir delil üzere bulunan kimse, kötü ameli kendisine süslü gösterilmiş ve kendi hevalarına uyan kimse gibi midir?');
INSERT INTO verses (sura, aya, text) VALUES (47, 15, 'Muttakilere vadedilen Cennet''in misali (şudur): İçinde bozulmayan su ırmakları, tadı bozulmayan süt ırmakları ve içenlere lezzet veren şarap ırmakları, süzme bal ırmakları... Onlara, orada her türlü meyve ve Rablerinden bağışlanma vardır. O; ebedi ateşte kalacak, kaynar su içirilip bağırsakları parça parça olacak kimseler gibi olur mu?');
INSERT INTO verses (sura, aya, text) VALUES (47, 16, 'Onlardan seni dinleyenler vardır. Fakat senin yanından çıktıkları zaman (alay ederek), kendilerine ilim verilmiş olanlara; “Az önce ne söyledi?” derler. İşte bunlar; Allah’ın, kalplerini mühürlediği ve nefislerinin arzularına uyan kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 17, 'Hidayete (doğru yola) erenler ise, (Allah) onların hidayetlerini artırmış ve onlara takvalarını vermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 18, 'Onlar, kendilerine ansızın gelecek kıyametten başka bir şey mi bekliyorlar? Oysa onun alametleri gelmiştir. Kendilerine geldiği zaman nasıl öğüt alacaklar?');
INSERT INTO verses (sura, aya, text) VALUES (47, 19, 'Öyleyse bil ki, Allah’tan başka (hak) ilah yoktur. Hem kendinin hem de Mümin erkeklerin ve Mümin kadınların günahlarının bağışlanmasını dile! Allah; sizin gezip dolaştığınız yeri de, duracağınız yeri de bilir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 20, 'İman edenler: “Bir sure indirilmeli değil miydi?” derler. Muhkem bir sure indirilip de içinde savaş emri verilince kalplerinde hastalık bulunanların üzerlerine ölüm baygınlığı gelmiş gibi sana baktıklarını görürsün. O onlara yakın olandır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 21, '(Onlar''a düşen) itaat edip güzel söz söylemektir. İş ciddileşince Allah’a verdikleri söze bağlı kalsalardı, elbette kendileri için daha iyi olurdu.');
INSERT INTO verses (sura, aya, text) VALUES (47, 22, 'Demek yüz çevirirseniz yeryüzünde bozgunculuk çıkaracak, akrabalık bağlarını keseceksiniz öyle mi?');
INSERT INTO verses (sura, aya, text) VALUES (47, 23, 'İşte onlar; Allah’ın kendilerine lanet ettiği ve bu sebeple kulaklarını sağır, gözlerini kör ettiği kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 24, 'Onlar, Kur’an’ı hiç düşünmüyorlar mı? Yoksa kalpleri üzerinde kilitler mi var?');
INSERT INTO verses (sura, aya, text) VALUES (47, 25, 'Kendilerine hidayet açıkça belli olduktan sonra, gerisin geriye (küfre) dönenlere, Şeytan (kendilerine kötü amellerini) süslemiş ve onları uzunca emellere düşürmüştür.');
INSERT INTO verses (sura, aya, text) VALUES (47, 26, 'Bu, onların Allah''ın indirdiklerinden hoşlanmayanlara: "Bazı işlerde size itaat edeceğiz" demelerinden dolayıdır. Oysa Allah onların gizlediklerini bilir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 27, 'Melekler, onların yüzlerine ve arkalarına vura vura canlarını aldıkları zaman (onların halleri) nasıl olacak?');
INSERT INTO verses (sura, aya, text) VALUES (47, 28, 'Bu, onların Allah''ı gazaplandıran şeylere uymaları ve O''nun rızasından hoşlanmamaları yüzündendir. Bu yüzden (Allah) amellerini boşa çıkardı.');
INSERT INTO verses (sura, aya, text) VALUES (47, 29, 'Yoksa kalplerinde hastalık olanlar, Allah’ın onların kinlerini ortaya çıkarmayacağını mı sandılar?');
INSERT INTO verses (sura, aya, text) VALUES (47, 30, 'Dileseydik onları sana elbette gösterirdik. Sen de onları simalarından tanırdın. Sen zaten onları konuşma uslûplarından da tanırsın. Allah, amellerinizi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 31, 'Andolsun ki, içinizden cihad edenlerle sabredenleri belirleyinceye ve haberlerinizi açıklayıncaya kadar sizi imtihan edeceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (47, 32, 'Şüphe yok ki kâfir olanlar, Allah’ın yolundan alıkoyanlar ve hidayet kendilerine apaçık göründükten sonra rasule karşı gelenler Allah’a asla hiçbir zarar veremezler ve o bunların amellerini boşa çıkaracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 33, 'Ey iman edenler! Allah’a itaat edin, Peygamber''e itaat edin ve amellerinizi boşa çıkarmayın.');
INSERT INTO verses (sura, aya, text) VALUES (47, 34, 'Hiç şüphesiz küfre sapanlar, Allah''ın yolundan alıkoyanlar, sonra da kâfir olarak ölenler (var ya), işte Allah onlara kesinlikle mağfiret etmeyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 35, 'Üstün durumda iken gevşeyip barışa çağırmayın. Allah sizinle beraberdir. O amellerinizi asla eksiltmeyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (47, 36, 'Dünya hayatı ancak bir oyun ve eğlencedir. Eğer iman eder ve takvalı olursanız size mükâfatınızı verir ve sizden mallarınızı istemez.');
INSERT INTO verses (sura, aya, text) VALUES (47, 37, 'Eğer o sizden onları istese ve bu hususta sizi zora koşsa o takdirde cimrilik edersiniz, bu da kinlerinizi açığa çıkarır.');
INSERT INTO verses (sura, aya, text) VALUES (47, 38, 'İşte siz, Allah yolunda harcamaya davet olunan kimselersiniz. Fakat, sizden cimrilik edenler vardır. Kim cimrilik ederse ancak kendi aleyhine cimrilik eder. Allah zengindir, siz ise fakirsiniz. Eğer O''ndan yüz çevirirseniz, yerinize sizden başka bir toplum getirir. Artık onlar sizin gibi de olmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (48, 1, 'Şüphesiz biz, sana apaçık bir fetih verdik.');
INSERT INTO verses (sura, aya, text) VALUES (48, 2, 'Böylece Allah, senin geçmiş ve gelecek günahını bağışlar. Sana olan nimetini tamamlar ve seni dosdoğru bir yola iletir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 3, 'Ve Allah, sana üstün bir zaferle yardım eder.');
INSERT INTO verses (sura, aya, text) VALUES (48, 4, 'İmanlarına iman katmaları için Müminlerin kalplerine huzur indiren O’dur. Göklerin ve yerin orduları Allah’ındır. Allah; Alîm''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 5, 'Bütün bunlar Allah’ın; iman eden erkek ve kadınları, altından ırmaklar akan, içinde ebedi kalacakları Cennetler''e koyması, onların kötülüklerini örtmesi içindir. İşte bu, Allah katında büyük bir kurtuluş/başarıdır.');
INSERT INTO verses (sura, aya, text) VALUES (48, 6, 'Allah hakkında kötü zanda bulunan münafık erkeklere ve münafık kadınlara, müşrik erkek ve müşrik kadınlara azap edecektir. Üzerlerine azap (iner). Allah onlara gazap etmiş, onları lanetlemiş ve onlara Cehennem''i hazırlamıştır. Varacakları yer ne kötüdür.');
INSERT INTO verses (sura, aya, text) VALUES (48, 7, 'Göklerin ve yerin orduları Allah’ındır. Allah; Azîz''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 8, 'Biz seni şahit, müjdeci ve uyarıcı olarak gönderdik .');
INSERT INTO verses (sura, aya, text) VALUES (48, 9, 'Ta ki (Ey Müminler!) Allah''a ve Rasûl''üne iman edesiniz, Rasûlüne yardım edesiniz, ona saygı gösteresiniz ve sabah akşam Allah''ı tesbih edesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (48, 10, 'Muhakkak ki sana bey’at edenler ancak Allah’a bey’at etmiş olurlar. Allah’ın eli onların ellerinin üzerindedir. Kim ahdini bozarsa kendi aleyhine bozmuş olur. Kim de Allah''a verdiği sözün gereğini yerine getirirse ona (Allah) büyük bir ecir verecektir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 11, 'Geride kalan bedeviler, sana: "Bizi mallarımız ve ailelerimiz meşgul etti. Bizim için bağışlanma dile!" diyeceklerdir. Kalplerinde olmayanı dilleri ile söylüyorlar. De ki: "Eğer Allah, size bir zarar veya fayda vermek isterse; kim sizin için bir şeye sahip olabilir? Oysa hayır! Allah yapmakta olduklarınızdan haberdardır."');
INSERT INTO verses (sura, aya, text) VALUES (48, 12, 'Aslında siz Peygamberin ve Müminlerin ailelerine bir daha dönmeyeceklerini sanmıştınız. Bu sizin gönüllerinize güzel göründü de kötü zanda bulundunuz ve helâkı hak etmiş bir topluluk oldunuz.');
INSERT INTO verses (sura, aya, text) VALUES (48, 13, 'Kim Allah’a ve Peygamberine iman etmezse, biz o kâfirlere alevli bir ateş hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (48, 14, 'Göklerin ve yerin mülkü Allah’a aittir. Dilediğini bağışlar, dilediğini cezalandırır. Allah çokça bağışlayıcıdır, çokça merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 15, 'Geride kalanlar, siz ganimetleri almaya giderken diyecekler ki: "Bizi bırakın da size uyalım/ardınızdan gelelim." Allah’ın sözünü değiştirmek istiyorlar. De ki: Asla bizim ardımızdan gelmeyeceksiniz. Daha önce Allah da böyle buyurmuştu. Hayır! Siz bizi çekemiyorsunuz/kıskanıyorsunuz, diyecekler. Hayır! Onlar pek az anlarlar.');
INSERT INTO verses (sura, aya, text) VALUES (48, 16, 'Bedevilerden (seferden) geri kalanlara de ki: "Çok güçlü bir kavme karşı savaşmak için çağrılacaksınız ya da onlar Müslüman olacaklar. Eğer itaat ederseniz, Allah size güzel bir mükâfat verir. Eğer daha önce yüz çevirdiğiniz gibi yüz çevirirseniz, sizi acı bir azapla cezalandırır."');
INSERT INTO verses (sura, aya, text) VALUES (48, 17, 'Kör olana güçlük (sorumluluk) yoktur, topal olana güçlük yoktur ve hasta olana da güçlük yoktur. Kim Allah''a ve resulüne itaat ederse, (Allah) onu, altından ırmaklar akan cennetlere sokar. Kim de yüz çevirirse onu da acı bir azapla cezalandırır.');
INSERT INTO verses (sura, aya, text) VALUES (48, 18, 'Muhakkak o ağacın altında sana biat ederlerken Allah, o Müminlerden razı olmuştur. Kalplerinde olanı bilmiş, üzerlerine huzur indirmiş ve onlara yakın bir fetih vermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 19, 'Ve alacakları birçok ganimetlerle de. Allah Azîzdir, Hakîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 20, 'Allah, size elde edeceğiniz bir çok ganimet vaadi vermiştir. Bunu sizin için çabuklaştırmış ve Müminlere bir işaret olması, sizin de doğru yolu bulmanız için insanların ellerini sizden çekmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 21, 'Henüz elde edemediğiniz başka ganimetler de vardır ki, onları Allah kuşatmıştır. Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (48, 22, 'Kâfirler sizinle savaşmış olsalardı, arkalarını dönüp kaçarlardı da bir dost ve yardımcı bulamazlardı.');
INSERT INTO verses (sura, aya, text) VALUES (48, 23, '(Bu,) Allah''ın öteden beri süregelen sünnetidir. Sen Allah''ın sünnetinde kesinlikle hiç bir değişiklik bulamazsın.');
INSERT INTO verses (sura, aya, text) VALUES (48, 24, 'Sizi onlara karşı zafere ulaştırdıktan sonra, Mekke’nin içinde (Hudeybiye''de) onların ellerini sizden, sizin elinizi de onlardan çeken O’dur. Allah, bütün işlediğiniz amelleri hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 25, 'Onlar, sizin Kâbe’yi ziyaret etmenize ve bekletilen kurbanların yerlerine ulaşmasına engel olan kâfirlerdir. Eğer, oradaki henüz tanımadığınız iman etmiş erkeklerle iman etmiş kadınları bilmeyerek ezmeniz ve böylece size bir vebal gelecek olmasaydı, (Allah, Mekke’ye girmenize izin verirdi). Allah, dilediğini rahmetine koymak için böyle yapmıştır. Eğer (Müminler) seçilip ayrılmış olsalardı elbette kâfirleri elem verici bir azaba çarptırırdık.');
INSERT INTO verses (sura, aya, text) VALUES (48, 26, 'Zira kâfirler, kalplerine taassubu/bağnazlığı, (hem de) cahiliye bağnazlığını yerleştirmişlerdi. Allah da Rasûlüne ve Müminlere sükûnet ve güvenini indirdi, onları takva sözüne (kelime-i tevhide) bağlı kıldı. Zaten onlar buna layık ve ehil kimselerdi. Allah her şeyi bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 27, 'Evet! Allah, elçisinin rüyasını hakkıyla doğruladı. Allah’ın dilemesiyle güven içinde, başlarınızı tıraş etmiş ve saçlarınızı kısaltmış olarak, korkusuzca Mescid-i Haram’a gireceksiniz. Allah, sizin bilmediğinizi bilir. Oraya girmeden önce de yakın bir fetih vermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (48, 28, 'Bütün dinlerden üstün kılmak üzere, Peygamberini hidayet ve hak din ile gönderen O''dur. Şahit olarak Allah yeter.');
INSERT INTO verses (sura, aya, text) VALUES (48, 29, 'Muhammed, Allah’ın Rasûlüdür. Onunla beraber olanlar; kâfirlere karşı şiddetli, kendi aralarında merhametlidirler. Onların rükû ve secde ederek Allah’ın lütuf ve rızasını arzuladıklarını görürsün. Onların işareti yüzlerindeki secde izleridir. İşte bu onların Tevrat’taki örneğidir. İncil''deki örneği ise filizini yarıp çıkarmış, gittikçe onu kuvvetlendirerek kalınlaşmış, gövdesi üzerine dikilmiş bir ekin gibidir ki, bu çiftçilerin de hoşuna gider. (Bu) Onunla kâfirleri öfkelendirmek içindir. Onlardan iman eden ve salih amellerde bulunanlara mağfiret ve büyük bir mükâfat vadetmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (49, 1, 'Ey iman edenler! (Hiçbir işte) Allah ve resulünden öne geçmeyin ve Allah''tan korkup sakının.Şüphesiz Allah; her şeyi işitendir, görendir.');
INSERT INTO verses (sura, aya, text) VALUES (49, 2, 'Ey iman edenler! Sesinizi, Peygamberin sesi üzerine yükseltmeyin. Birbirinize yüksek sesle konuştuğunuz gibi onunla da öyle yüksek sesle konuşmayın. Yoksa siz farkında olmadan amelleriniz boşa gider.');
INSERT INTO verses (sura, aya, text) VALUES (49, 3, 'Muhakkak ki Rasulullahın huzurunda seslerini alçaltanlar, Allah’ın kalplerini takva için seçtiği kimselerdir. Onlar için bir mağfiret ve büyük bir mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (49, 4, 'Muhakkak ki odaların arkasından sana seslenenlerin çoğunun akılları ermez.');
INSERT INTO verses (sura, aya, text) VALUES (49, 5, 'Eğer onlar sen yanlarına çıkana kadar sabretselerdi, kendileri için elbette daha hayırlı olurdu. Allah; çok bağışlayıcıdır, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (49, 6, 'Ey iman edenler! Eğer bir fasık size bir haber getirirse onun doğruluğunu araştırın. Yoksa bilmeden bir topluluğa kötülük edersiniz de sonra yaptığınıza pişman olursunuz.');
INSERT INTO verses (sura, aya, text) VALUES (49, 7, 'Aranızda Allah’ın Rasûlünün bulunduğunu bilin. Eğer O, birçok işte size uymuş olsaydı, siz sıkıntıya düşerdiniz. Fakat Allah, size imanı sevdirmiş ve onu kalplerinizde süslemiştir. Size küfrü, fasıklığı ve isyanı ise kötü göstermiştir. İşte onlar, doğru yolu bulmuş olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (49, 8, 'Bu, Allah''tan bir lütuf ve nimettir. Allah; Alîm''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (49, 9, 'Eğer Müminlerden iki grup savaşa tutuşurlarsa, aralarını düzeltin. Eğer biri diğerine saldırırsa, Allah’ın emrine dönünceye kadar saldırana karşı savaşın. Eğer dönerse, aralarını adaletle düzeltin ve adil davranın. Şüphesiz Allah, adaletli olanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (49, 10, 'Müminler ancak kardeştirler. Öyleyse kardeşlerinizin arasını düzeltin ve Allah’tan sakının ki, merhamet olunasınız.');
INSERT INTO verses (sura, aya, text) VALUES (49, 11, 'Ey iman edenler! Bir topluluk, diğer bir toplulukla alay etmesin. Belki de onlar (alay edilenler), alay edenlerden daha hayırlıdır. Kadınlar da başka kadınlarla alay etmesin. Belki de onlar, bunlardan daha hayırlıdır. Kendi kendinizi ayıplamayın ve birbirinizi kötü lakaplarla çağırmayın. İmandan sonra fasıklık ne kötü bir isimdir! Kim tevbe etmezse, işte zalimler onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (49, 12, 'Ey iman edenler! Zannın çoğundan kaçının. Çünkü zannın bir kısmı günahtır. Birbirinizin gizlisini araştırmayın. Birbirinizin gıybetini yapmayın. Biriniz, ölü kardeşinin etini yemeyi sever mi? Bundan tiksindiniz değil mi? Allah’tan sakının. Kuşkusuz Allah, tevbeleri çokça kabul edendir, çokça merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (49, 13, 'Ey insanlar! Biz, sizi bir erkek ve bir dişiden yarattık. Sizi tanışasınız diye kollara ve kabilelere ayırdık. Allah katında en değerliniz, ondan en çok sakınanınız/takvalı olanınızdır. Şüphesiz Allah; Alim''dir, her şeyden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (49, 14, 'Bedeviler; “İman ettik” dediler. De ki: "Siz iman etmediniz. Fakat teslim/İslam olduk, deyin. Çünkü iman, henüz kalplerinize girmedi. Eğer Allah’a ve Rasûlüne itaat ederseniz, (Allah) amellerinizden hiçbir şey eksiltmez. Nitekim Allah; çok bağışlayandır, çok merhamet edendir."');
INSERT INTO verses (sura, aya, text) VALUES (49, 15, 'Asıl Müminler, Allah’a ve Rasûlüne iman edip, sonra da hiç şüphe etmeyen ve Allah yolunda mallarıyla, canlarıyla cihad edenlerdir. İşte doğrular/sadıklar onlardır.');
INSERT INTO verses (sura, aya, text) VALUES (49, 16, 'De ki: "Siz dininizi Allah''a mı öğretiyorsunuz? Allah, göklerde ve yerde ne varsa bilir. Allah, her şeyi hakkıyla bilendir."');
INSERT INTO verses (sura, aya, text) VALUES (49, 17, 'Müslüman oldular diye seni minnet altında tutmak istiyorlar. De ki: "Müslüman olmanız sebebiyle beni minnet altında bırakmayın. Bilâkis size doğru yolu gösterdiği için Allah sizi minnet altında tutar, eğer samimi iseniz."');
INSERT INTO verses (sura, aya, text) VALUES (49, 18, 'Allah, şüphesiz göklerin ve yerin gaybını bilir. Allah, yapmakta olduğunuz amelleri hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 1, 'Kâf.[1] Çok şerefli Kur’an’a and olsun.');
INSERT INTO verses (sura, aya, text) VALUES (50, 2, 'Kendilerine içlerinden bir uyarıcının gelmesine şaşırdılar da, o kâfirler: "Bu, şaşılacak bir şeydir." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (50, 3, 'Biz öldükten ve toprak olduktan sonra mı? Bu ne uzak bir dönüştür.');
INSERT INTO verses (sura, aya, text) VALUES (50, 4, 'Yerin onlardan (cesetlerinden) ne eksilteceğini biliriz. Katımızda koruyup saklayan bir kitap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (50, 5, 'Hayır! Onlar, kendilerine hak gelince yalanladılar. Şimdi onlar şaşkınlık içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (50, 6, 'Üzerlerindeki göğe hiç bakmıyorlar mı? Onu nasıl bina ettik, nasıl süsledik? Onda bir çatlak da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (50, 7, 'Ve yeryüzünü nasıl yayıp, üzerinde sabit dağlar yerleştirdik. Orada her çeşit iç açıcı güzel bitkiler yetiştirdik.');
INSERT INTO verses (sura, aya, text) VALUES (50, 8, '(Bize) yönelen bütün kullar için (bunları) bir basiret ve öğüt kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (50, 9, 'Gökten bereketli bir su indirdik de onunla bahçeler ve biçilecek ekinler bitirdik.');
INSERT INTO verses (sura, aya, text) VALUES (50, 10, 'Ve uzunca boylu hurma ağaçları da yetiştirdik ki, onlar için birbiri üstüne konmuş muntazam salkımlar, tomurcuklar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (50, 11, 'Kullara rızık olarak. O su ile ölü beldeye hayat verdik. İşte (kabirden) çıkış da böyledir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 12, 'Onlardan önce Nûh’un kavmi, Ress halkı ve Semûd da yalanlamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (50, 13, 'Âd ve Firavun ile Lût’un kardeşleri de (yalanladılar).');
INSERT INTO verses (sura, aya, text) VALUES (50, 14, 'Eyke halkı, Tubba kavmi de. Hepsi de elçileri yalanladı ve böylece benim tehdidim (onların üzerine) hak oldu.');
INSERT INTO verses (sura, aya, text) VALUES (50, 15, 'İlk yaratmakta acizlik mi gösterdik? Hayır onlar yeni yaratıştan şüphe ve tereddüt içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (50, 16, 'Şüphesiz insanı biz yarattık ve nefsinin ona ne vesveseler vermekte olduğunu da biliriz. Biz ona şahdamarından daha yakınız.');
INSERT INTO verses (sura, aya, text) VALUES (50, 17, 'Sağ tarafta ve sol tarafta oturan iki alıcı (melek) oturmuş (kayıt yapmaktadır).');
INSERT INTO verses (sura, aya, text) VALUES (50, 18, 'İnsan hiçbir söz söylemez ki, yanında gözetleyen yazmaya hazır bir melek bulunmasın.');
INSERT INTO verses (sura, aya, text) VALUES (50, 19, 'Ölüm sarhoşluğu bir hakikat olarak insana gelir de ona; “İşte bu, senin öteden beri kaçıp durduğun şeydir.” denir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 20, 'Sûr’a üfürülmüştür. İşte bu, tehdidin gerçekleşeceği gündür.');
INSERT INTO verses (sura, aya, text) VALUES (50, 21, 'Her kişi yanında bir sevkedici/sürücü ve şahit ile gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 22, 'Sen, bundan gafil idin. Gözünden perdeyi kaldırdık. Artık bugün görüşün keskindir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 23, 'Beraberindeki (melek) şöyle der: “İşte bu yanımdaki hazırdır.”');
INSERT INTO verses (sura, aya, text) VALUES (50, 24, 'Her inatçı kâfiri Cehennem''e atın.');
INSERT INTO verses (sura, aya, text) VALUES (50, 25, 'Hayra bütün gücüyle engel olanı, azgın şüpheciyi.');
INSERT INTO verses (sura, aya, text) VALUES (50, 26, 'Allah ile birlikte başka bir ilah edineni atın şiddetli azaba.');
INSERT INTO verses (sura, aya, text) VALUES (50, 27, 'Arkadaşı (olan Şeytan) der ki: “Ey Rabbimiz! Onu ben azdırmadım, fakat kendisi derin bir sapıklık içinde idi.”');
INSERT INTO verses (sura, aya, text) VALUES (50, 28, 'O esnada (Allah) buyurur: Huzurumda çekişmeyin! Ben size daha önce uyarı göndermiştim!');
INSERT INTO verses (sura, aya, text) VALUES (50, 29, '“Benim yanımda söz değiştirilmez ve ben kullara asla zulmedici de değilim.”');
INSERT INTO verses (sura, aya, text) VALUES (50, 30, 'O gün, Cehennem''e: "Doldun mu?" deriz. O da: "Daha var mı?" der.');
INSERT INTO verses (sura, aya, text) VALUES (50, 31, 'Cennet ise takva sahiplerine uzak olmayıp, yakınlaştırılmış olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (50, 32, 'İşte size vaat edilen budur! yönelen ve (emirlerini) koruyan herkes içindir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 33, 'Görmediği halde Rahman’dan korkan ve (O''na) yönelmiş bir kalp ile gelen kimseler içindir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 34, 'Oraya esenlikle girin, bugün sonsuzluk günüdür.');
INSERT INTO verses (sura, aya, text) VALUES (50, 35, 'Orada kendileri için diledikleri her şey vardır. Katımızda dahası da vardır.');
INSERT INTO verses (sura, aya, text) VALUES (50, 36, 'Biz, onlardan önce kendilerinden daha güçlü olan, diyar diyar dolaşan nice nesilleri helâk etmişizdir. Kurtuluş var mı?');
INSERT INTO verses (sura, aya, text) VALUES (50, 37, 'Şüphesiz bunda, kalbi olana veya kulak verene ve şahit olana bir ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (50, 38, 'Gökleri, yeri ve ikisi arasındakileri altı günde yarattık. Hiçbir yorgunluk da dokunmadı.');
INSERT INTO verses (sura, aya, text) VALUES (50, 39, 'Onların dediklerine karşı sabret. Güneş doğmadan önce ve batmadan önce Rabbini hamdederek tesbih et!');
INSERT INTO verses (sura, aya, text) VALUES (50, 40, 'Gecenin bir kısmında ve secdelerin arkasından O''nu tesbih et.');
INSERT INTO verses (sura, aya, text) VALUES (50, 41, 'O gün yakın bir yerden seslenecek olanın çağrısına kulak ver.');
INSERT INTO verses (sura, aya, text) VALUES (50, 42, 'O gün, o çığlığı bir gerçek (hak) olarak işitirler. İşte o gün (kabirlerden) çıkış günüdür.');
INSERT INTO verses (sura, aya, text) VALUES (50, 43, 'Şüphesiz biz diriltir ve öldürürüz. Dönüş de ancak bizedir.');
INSERT INTO verses (sura, aya, text) VALUES (50, 44, 'O günde yer üzerlerinden yarılır, hızlıca çıkarlar. Bu bizim için kolay olan bir toplamadır.');
INSERT INTO verses (sura, aya, text) VALUES (50, 45, 'Onların söylediklerini biz daha iyi biliriz. Sen, onların üzerinde bir zorlayıcı değilsin. Tehdidimden korkanlara Kur''an''la öğüt ver.');
INSERT INTO verses (sura, aya, text) VALUES (51, 1, 'Savurup tozutan rüzgârlara andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (51, 2, 'Ağır yük taşıyan (bulut) lara.');
INSERT INTO verses (sura, aya, text) VALUES (51, 3, 'Kolayca akıp giden (gemi) lere.');
INSERT INTO verses (sura, aya, text) VALUES (51, 4, 'İşleri taksim edenlere (meleklere).');
INSERT INTO verses (sura, aya, text) VALUES (51, 5, 'Size vadedilen kesinlikle doğrudur.');
INSERT INTO verses (sura, aya, text) VALUES (51, 6, 'Ceza (karşılık) günü kuşkusuz vuku bulacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (51, 7, 'Güzel yolları (ve yörüngeleri) olan göğe andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (51, 8, 'Muhakkak siz çelişkili bir söz içindesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (51, 9, 'Ondan döndürülen kimseler döndürülür.');
INSERT INTO verses (sura, aya, text) VALUES (51, 10, 'Kahrolsun o yalancılar!');
INSERT INTO verses (sura, aya, text) VALUES (51, 11, 'Onlar koyu bir cehalet içerisinde kalmış gafillerdir.');
INSERT INTO verses (sura, aya, text) VALUES (51, 12, '"Ceza günü ne zaman diye sorarlar?"');
INSERT INTO verses (sura, aya, text) VALUES (51, 13, 'O gün, onların ateşte yakılarak azap görecekleri gündür.');
INSERT INTO verses (sura, aya, text) VALUES (51, 14, '(Görevli melekler onlara şöyle der): “Azabınızı tadın! İşte acele isteyip durduğunuz şey budur.”');
INSERT INTO verses (sura, aya, text) VALUES (51, 15, 'Takva sahibi olanlar ise, Cennetler''de ve pınarlardadır.');
INSERT INTO verses (sura, aya, text) VALUES (51, 16, 'Rablerinin kendilerine verdiklerini almışlardır. Çünkü onlar bundan önce iyi kimseler idiler.');
INSERT INTO verses (sura, aya, text) VALUES (51, 17, 'Geceleri pek az uyurlardı.');
INSERT INTO verses (sura, aya, text) VALUES (51, 18, 'Seher vakitlerinde istiğfar ederlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (51, 19, 'Mallarında, muhtaç ve yoksullar için bir hak vardır.');
INSERT INTO verses (sura, aya, text) VALUES (51, 20, 'Yeryüzünde gerçekten iman edecekler için ayetler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (51, 21, 'Ve kendi nefislerinizde de (ayetler vardır). Yine de görmüyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (51, 22, 'Gökte de sizin rızkınız ve size vadedilen şeyler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (51, 23, 'Göğün ve yerin Rabbi hakkı için o sizin konuştuğunuz gibi kesin bir gerçektir.');
INSERT INTO verses (sura, aya, text) VALUES (51, 24, 'İbrahim’in şerefli kılınmış konuklarının haberi sana geldi mi?');
INSERT INTO verses (sura, aya, text) VALUES (51, 25, 'Hani O’nun yanına girmişler: “Selam!” demişlerdi. O da: "Selam! (Sizin üzerinize). (Sizler) tanınmayan yabancı kimselersiniz.” demişti.');
INSERT INTO verses (sura, aya, text) VALUES (51, 26, 'Hemen ailesinin yanına gidip semiz bir buzağı getiriverdi.');
INSERT INTO verses (sura, aya, text) VALUES (51, 27, 'Bunu onların önüne yaklaştırdı ve: "Yemez misiniz?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (51, 28, 'Onlardan dolayı içine bir korku düştü. "Korkma!" dediler. Ona bilgin bir erkek çocuğu müjdelediler.');
INSERT INTO verses (sura, aya, text) VALUES (51, 29, 'Karısı bir çığlık içinde çıka gelip, (elleriyle) yüzüne vurarak: "Ben, kısır bir kocakarıyım." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (51, 30, 'Dediler ki: "Rabbin böyle buyurdu. Muhakkak ki O; Hakîm''dir, Alîm''dir."');
INSERT INTO verses (sura, aya, text) VALUES (51, 31, 'İbrahim, onlara: “O halde göreviniz nedir ey elçiler?” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (51, 32, 'Onlar: “Şüphe yok ki biz günahkâr bir topluluğa gönderildik” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (51, 33, '"Onların üzerilerine balçıktan yapılmış taşlar atacağız."');
INSERT INTO verses (sura, aya, text) VALUES (51, 34, '(Bu taşlar) Rabbinin katında haddi aşanlar için işaretlenmiş (taşlardır).');
INSERT INTO verses (sura, aya, text) VALUES (51, 35, 'Bunun üzerine orada bulunan Müminleri çıkardık.');
INSERT INTO verses (sura, aya, text) VALUES (51, 36, 'Zaten orada bir ev halkından başka Müslüman bulamadık.');
INSERT INTO verses (sura, aya, text) VALUES (51, 37, 'Orada, elem dolu azaptan korkacaklar için bir ibret bıraktık.');
INSERT INTO verses (sura, aya, text) VALUES (51, 38, 'Mûsâ (kıssasında da ibret vardır). Hani biz, onu açık bir delil ile Firavun’a göndermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (51, 39, 'Firavun, bütün (kişisel ve askeri) gücüyle yüz çevirmiş ve: "Bu, ya bir büyücü veya bir delidir." demişti.');
INSERT INTO verses (sura, aya, text) VALUES (51, 40, 'Nihayet onu da ordularını da yakalayıp denize attık. O (küfründen dolayı) kınanmış bir kimseydi.');
INSERT INTO verses (sura, aya, text) VALUES (51, 41, 'Âd kavminde de (ibretler vardır). Onlara kasıp kavuran rüzgârı göndermiştik.');
INSERT INTO verses (sura, aya, text) VALUES (51, 42, 'Üzerine uğradığı hiçbir şeyi bırakmıyor, mutlaka onu kül ediyordu.');
INSERT INTO verses (sura, aya, text) VALUES (51, 43, 'Semûd''da da (ibretler) vardır. Onlara: "Bir süreye kadar faydalanın." denmişti.');
INSERT INTO verses (sura, aya, text) VALUES (51, 44, 'Rablerinin emrine kibirlenip isyan ettiler. Bu yüzden bakıp dururken onları yıldırım çarpmıştı.');
INSERT INTO verses (sura, aya, text) VALUES (51, 45, 'Ayağa kalkacak güçleri kalmamış, yardım edenleri de olmamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (51, 46, 'Bunlardan önce de Nûh kavmini (helâk etmiştik). Çünkü onlar, fasık/yoldan çıkmış bir toplum idiler.');
INSERT INTO verses (sura, aya, text) VALUES (51, 47, 'Göğü kendi ellerimizle biz kurduk ve biz onu elbette genişleticiyiz.');
INSERT INTO verses (sura, aya, text) VALUES (51, 48, 'Yeryüzünü de yayıp döşedik. Ne güzel döşeyiciyiz.');
INSERT INTO verses (sura, aya, text) VALUES (51, 49, 'Düşünüp ibret alasınız diye her şeyden (erkekli dişili) iki eş yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (51, 50, 'O halde Allah’a kaçın. Çünkü ben, size Onun katından (gönderilmiş) açık bir uyarıcıyım.');
INSERT INTO verses (sura, aya, text) VALUES (51, 51, 'Allah ile beraber başkasını ilah edinmeyin. Zira ben, size O''nun tarafından (gönderilmiş) açık bir uyarıcıyım.');
INSERT INTO verses (sura, aya, text) VALUES (51, 52, 'İşte böylece, onlardan öncekilere herhangi bir peygamber geldiğinde hemen; "O, bir büyücüdür veya delidir." dediler.');
INSERT INTO verses (sura, aya, text) VALUES (51, 53, 'Bunu birbirlerine vasiyet mi ettiler? Doğrusu onlar, taşkın bir toplum idiler.');
INSERT INTO verses (sura, aya, text) VALUES (51, 54, 'Sen yüz çevir onlardan, artık kınanacak değilsin.');
INSERT INTO verses (sura, aya, text) VALUES (51, 55, 'Sen yine de öğüt ver. Çünkü öğüt, iman edenlere fayda verir.');
INSERT INTO verses (sura, aya, text) VALUES (51, 56, 'Ben cinleri de insanları da ancak bana ibadet etsinler, diye yarattım.');
INSERT INTO verses (sura, aya, text) VALUES (51, 57, 'Onlardan bir rızık istemiyorum, beni doyurmalarını da istemiyorum.');
INSERT INTO verses (sura, aya, text) VALUES (51, 58, 'Şüphesiz rızık veren, güç ve kuvvet sahibi olan ancak Allah’tır.');
INSERT INTO verses (sura, aya, text) VALUES (51, 59, 'Muhakkak (geçmişteki) arkadaşlarının azaptan payları olduğu gibi, zulmedenlerin de azaptan bir payları vardır. Artık acele etmesinler.');
INSERT INTO verses (sura, aya, text) VALUES (51, 60, 'Tehdit olundukları o (azap) günlerinden dolayı vay o kâfir olanlara!');
INSERT INTO verses (sura, aya, text) VALUES (52, 1, 'Tûr’a yemin olsun.');
INSERT INTO verses (sura, aya, text) VALUES (52, 2, 'Ve yazılmış kitaba.');
INSERT INTO verses (sura, aya, text) VALUES (52, 3, 'Yayılmış sahifeler içindeki.');
INSERT INTO verses (sura, aya, text) VALUES (52, 4, 'Beyt-i Ma''mur''a.');
INSERT INTO verses (sura, aya, text) VALUES (52, 5, 'Yükseltilmiş tavana (göğe).');
INSERT INTO verses (sura, aya, text) VALUES (52, 6, 'Taşkın denize.');
INSERT INTO verses (sura, aya, text) VALUES (52, 7, 'Rabbinin azabı elbette vuku bulacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (52, 8, 'Onu önleyebilecek yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (52, 9, 'O gün gök şiddetle sallanıp çalkalanır.');
INSERT INTO verses (sura, aya, text) VALUES (52, 10, 'Dağlar yürüdükçe yürür.');
INSERT INTO verses (sura, aya, text) VALUES (52, 11, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (52, 12, 'Ki onlar, daldıkları batıl içinde oyalanıp duranlardır.');
INSERT INTO verses (sura, aya, text) VALUES (52, 13, 'O gün itile kakıla Cehennem ateşine atılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (52, 14, 'İşte bu sizin yalan saydığınız ateştir (denilir).');
INSERT INTO verses (sura, aya, text) VALUES (52, 15, 'Bu da mı sihir? Yoksa siz mi görmüyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (52, 16, 'Girin oraya! Sabretseniz de sabretmeseniz de artık sizin için birdir. Siz ancak yaptıklarınızın karşılığına çarptırılacaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (52, 17, 'Muttakiler hiç şüphe yok ki, Cennetler ve nimetler içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (52, 18, 'Rablerinin kendilerine verdikleri ile sefa sürerler. Rableri, onları çılgın alevin azabından korumuştur.');
INSERT INTO verses (sura, aya, text) VALUES (52, 19, '"Yaptıklarınıza karşılık afiyetle yiyin, için!"');
INSERT INTO verses (sura, aya, text) VALUES (52, 20, 'Sıra sıra dizilmiş koltuklara yaslanmışlardır ve onları iri gözlü beyaz tenli huriler ile evlendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (52, 21, 'İman edip, soyları iman ile kendilerine uyanların biz evlatlarını da kendilerine katarız. Amellerinden de hiçbir şey eksiltmeyiz. Her kişi kendi kazandıkları karşılığında bir rehinedir.');
INSERT INTO verses (sura, aya, text) VALUES (52, 22, 'Onlara canlarının istediği meyve ve etten bol bol verdik.');
INSERT INTO verses (sura, aya, text) VALUES (52, 23, 'Orada birbirlerine kadeh sunarlar. Ama burada (içki yüzünden) ne saçmalama vardır, ne de günaha girmek.');
INSERT INTO verses (sura, aya, text) VALUES (52, 24, 'Etraflarında sedefleri içinde gizlenmiş incileri andıran delikanlı hizmetçiler dolaşır, durur.');
INSERT INTO verses (sura, aya, text) VALUES (52, 25, 'Birbirlerine dönüp karşılıklı olarak sorarlar.');
INSERT INTO verses (sura, aya, text) VALUES (52, 26, '"Biz, ailemizin yanında daha önce (Allah''ın azabı hakkında) korku içindeydik." derler.');
INSERT INTO verses (sura, aya, text) VALUES (52, 27, '"Allah bize lütfetti de, bizi o şiddetli ateşin azabından korudu."');
INSERT INTO verses (sura, aya, text) VALUES (52, 28, '"Hiç şüphesiz biz bundan önce O''na dua (ibadet) ederdik. Gerçekten O, çokça iyilik sahibidir, çokça merhametlidir."');
INSERT INTO verses (sura, aya, text) VALUES (52, 29, 'Sen öğüt ver. Rabbinin lütfuyla sen ne bir kâhinsin, ne de bir deli.');
INSERT INTO verses (sura, aya, text) VALUES (52, 30, 'Yoksa; o, bir şairdir, zaman (içinde) başına sıkıntılar ve ölümün gelmesini bekliyoruz mu diyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (52, 31, 'De ki: "Bekleyin, ben de sizinle beraber bekleyenlerdenim."');
INSERT INTO verses (sura, aya, text) VALUES (52, 32, 'Bunu kendilerine akılları mı emrediyor yoksa onlar azgın bir topluluk mudurlar?');
INSERT INTO verses (sura, aya, text) VALUES (52, 33, 'Yoksa; o Kur’an’ı kendisi uydurup söyledi mi diyorlar? Hayır! Onlar iman etmiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (52, 34, 'Eğer doğru söyleyenler iseler, haydi onun gibi bir söz getirsinler!');
INSERT INTO verses (sura, aya, text) VALUES (52, 35, 'Acaba onlar herhangi bir yaratıcı olmadan mı yaratıldılar? Yoksa kendileri mi yaratıcıdırlar?');
INSERT INTO verses (sura, aya, text) VALUES (52, 36, 'Yoksa, gökleri ve yeri onlar mı yarattılar? Hayır! Onlar kesin olarak inanmıyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (52, 37, 'Yoksa, Rabbinin hazineleri onların yanında mıdır? Ya da her şeye hâkim olan kendileri midir?');
INSERT INTO verses (sura, aya, text) VALUES (52, 38, 'Yoksa onların, kendisi vasıtasıyla (ilahî vahyi) dinleyecekleri bir merdivenleri mi var? (Eğer varsa) dinleyenleri, açık bir delil getirsin!');
INSERT INTO verses (sura, aya, text) VALUES (52, 39, 'Yoksa kızlar Allah''ın da, oğullar sizin mi?');
INSERT INTO verses (sura, aya, text) VALUES (52, 40, 'Yoksa sen kendilerinden bir ücret istiyorsun da, bu yüzden onlar ağır bir borç altında eziliyorlar mı?');
INSERT INTO verses (sura, aya, text) VALUES (52, 41, 'Yoksa gayp onların yanında da, onlar mı yazıyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (52, 42, 'Yoksa, bir tuzak mı kurmak istiyorlar? Tuzağa düşecek olanlar kâfir olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (52, 43, 'Yoksa, onların Allah’tan başka bir (hak) ilahları mı var? Allah, onların ortak koştuklarından münezzehtir/uzaktır.');
INSERT INTO verses (sura, aya, text) VALUES (52, 44, 'Gökten düşmekte olan parçalar görseler; “Bunlar, üst üste yığılmış bulutlardır.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (52, 45, 'Şimdi onları yıkılıp, helak olacakları günleri ile karşılaşana kadar bırak.');
INSERT INTO verses (sura, aya, text) VALUES (52, 46, 'O gün tuzakları kendilerine hiçbir fayda vermeyecektir ve kendilerine yardım da edilmeyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (52, 47, 'Zalimler için bundan başka da azap vardır. Fakat onların çoğu bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (52, 48, 'Rabbinin hükmüne sabret. Çünkü sen gözlerimizin önündesin. (Gece) kalktığında Rabbini hamt ile tespih et.');
INSERT INTO verses (sura, aya, text) VALUES (52, 49, 'Gecenin bir kısmında ve yıldızlar battıktan sonra da onu tespih et!');
INSERT INTO verses (sura, aya, text) VALUES (53, 1, 'Battığı zaman yıldıza andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (53, 2, 'Arkadaşınız (doğru yoldan) çıkmadı, sapıtmadı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 3, 'Kendi hevasından konuşmaz.');
INSERT INTO verses (sura, aya, text) VALUES (53, 4, '(Size okuduğu) Kur''an, ancak kendisine bildirilen bir vahiydir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 5, 'Bunu, ona çok güçlü biri öğretti.');
INSERT INTO verses (sura, aya, text) VALUES (53, 6, 'Güç sahibi ve güzel görünüşlüdür. (Derken en yüksek ufukta) yükseliverdi.');
INSERT INTO verses (sura, aya, text) VALUES (53, 7, 'O, en yüksek ufukta idi.');
INSERT INTO verses (sura, aya, text) VALUES (53, 8, 'Sonra (Muhammed’e) yaklaştı, derken daha da yaklaştı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 9, 'Böylece iki yay (boyu) kadar hatta daha da yaklaştı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 10, 'Cebrail, Allah''ın kuluna vahyettiğini vahyetti.');
INSERT INTO verses (sura, aya, text) VALUES (53, 11, '(Gözleriyle) gördüğünü kalbi yalanlamadı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 12, '(Şimdi siz) gördüğü şey hakkında onunla tartışıyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (53, 13, 'Andolsun ki o, Cebrâîl’i bir başka inişte daha görmüştü.');
INSERT INTO verses (sura, aya, text) VALUES (53, 14, 'Sidre-i Müntehâ’nın yanında.');
INSERT INTO verses (sura, aya, text) VALUES (53, 15, 'Cennetü''l-Me''va da onun yanındadır.');
INSERT INTO verses (sura, aya, text) VALUES (53, 16, 'O zaman Sidre’yi kaplayan kaplamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 17, 'Göz (gördüğünden) şaşmadı ve (onu) aşmadı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 18, 'Andolsun ki o Rabbinin en büyük âyetlerinden bir kısmını gördü.');
INSERT INTO verses (sura, aya, text) VALUES (53, 19, 'Gördünüz mü o Lât ve Uzzâ’yı?');
INSERT INTO verses (sura, aya, text) VALUES (53, 20, 'Ve üçüncüleri olan ötekini, Menât''ı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 21, 'Erkekler sizin; dişiler O’nun mu?');
INSERT INTO verses (sura, aya, text) VALUES (53, 22, 'Öyle ise bu çok insafsızca bir taksimdir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 23, 'Bunlar (putlar) sizin ve atalarınızın taktığı isimlerden başka bir şey değildir. Allah, onlar hakkında bir delil indirmemiştir. Onlar, ancak zanna ve nefislerinin arzusuna uyuyorlar. Oysa, onlara Rableri tarafından yol gösterici gelmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 24, 'Yoksa insan her arzu ettiği şeye sahip mi olacaktır?');
INSERT INTO verses (sura, aya, text) VALUES (53, 25, 'Ahiret de dünya da Allah’ındır.');
INSERT INTO verses (sura, aya, text) VALUES (53, 26, 'Göklerde nice melekler vardır ki, Allah dilediği ve razı olduğu kimseler için izin vermedikçe onların şefaatı hiçbir fayda vermez.');
INSERT INTO verses (sura, aya, text) VALUES (53, 27, 'Doğrusu ahirete iman etmeyenler, melekleri dişi isimlerle isimlendirirler.');
INSERT INTO verses (sura, aya, text) VALUES (53, 28, 'Hâlbuki onların buna dair bilgileri yoktur. Onlar ancak zanna uyarlar. Zan ise hiç şüphesiz hak adına hiçbir şey ifade etmez.');
INSERT INTO verses (sura, aya, text) VALUES (53, 29, 'Bu sebeple sen, zikrimizden/Kur''an''dan yüz çevirenden ve dünya hayatından başka bir şey istemeyenden uzak dur!');
INSERT INTO verses (sura, aya, text) VALUES (53, 30, 'İşte onların erişebilecekleri ilim budur. Şüphesiz Rabbin, kimin yolundan saptığını en iyi bilendir. Kimin hidayet üzere olduğunu da en iyi bilen O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 31, 'Göklerde olan da yerde olan da Allah’ındır. Kötülük edenleri yaptıkları sebebiyle cezalandıracak, iyilik edenleri de en iyisi ile ödüllendirecektir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 32, 'Onlar küçük kusurlar dışında günâhların büyüklerinden ve çirkin işlerden kaçınırlar. Şüphesiz Rabbin, mağfireti çok geniş olandır. Sizi topraktan meydana getirdiği zaman da ve siz, annelerinizin karnında cenin halinde iken de sizi en iyi O bilir. Öyleyse kendi kendinizi temize çıkarmayın. Kimin takvalı olduğunu en iyi O bilir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 33, 'Yüz çeviren kimseyi gördün mü?');
INSERT INTO verses (sura, aya, text) VALUES (53, 34, 'Ve az bir şey verip sımsıkı tutanı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 35, 'Gaybın ilmi onun yanında da, o mu görüyor?');
INSERT INTO verses (sura, aya, text) VALUES (53, 36, 'Yoksa ona Mûsâ''nın sahifelerinde olan haber verilmedi mi?');
INSERT INTO verses (sura, aya, text) VALUES (53, 37, 'Ve ahdine vefa gösteren İbrahim''in (sahifelerinde)');
INSERT INTO verses (sura, aya, text) VALUES (53, 38, 'Gerçekten hiçbir günahkâr, başkasının günah yükünü yüklenmez.');
INSERT INTO verses (sura, aya, text) VALUES (53, 39, 'İnsan için çalıştığından başkası yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 40, 'Şüphesiz onun çalışması ileride görülecektir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 41, 'Sonra da karşılığı eksiksiz tam olarak verilecektir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 42, 'Ve kuşkusuz en son varış Rabbinedir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 43, 'Güldüren de, ağlatan da O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 44, 'Öldüren de, dirilten de O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 45, 'Erkek ve dişi olarak iki cinsi yaratan O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 46, 'Bir nutfeden rahimlere döküldüğü zaman.');
INSERT INTO verses (sura, aya, text) VALUES (53, 47, 'Şüphesiz tekrar diriltmek de O’na aittir.');
INSERT INTO verses (sura, aya, text) VALUES (53, 48, 'Zengin kılan da, varlıklı eden de O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 49, 'Şi’râ (yıldızı)nın Rabbi de O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 50, 'Ve şüphesiz ki, önceki Âd Kavmi’ni O helâk etti.');
INSERT INTO verses (sura, aya, text) VALUES (53, 51, 'Semûd''u da (O helâk etti) ve geriye hiçbir şey bırakmadı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 52, 'Daha önce de Nûh’un kavmini helâk etmişti. Şüphesiz onlar daha zalim ve daha azgın kimselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (53, 53, 'O, (Lût kavminin) altüst olan şehirlerini de böyle yaptı');
INSERT INTO verses (sura, aya, text) VALUES (53, 54, 'Onlara bürüyen (şiddetli bir azap) bürüdü.');
INSERT INTO verses (sura, aya, text) VALUES (53, 55, 'O halde, Rabbinin hangi nimetinden şüphe ediyorsun?');
INSERT INTO verses (sura, aya, text) VALUES (53, 56, 'İşte bu, önceki uyarıcılar gibi bir uyarıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (53, 57, 'Yaklaşmakta olan (kıyamet iyice) yaklaştı.');
INSERT INTO verses (sura, aya, text) VALUES (53, 58, 'Onu (vaktini) Allah’tan başka açığa çıkaracak yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (53, 59, 'Şimdi siz bu söze mi şaşıyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (53, 60, 'Gülüyorsunuz da ağlamıyorsunuz!');
INSERT INTO verses (sura, aya, text) VALUES (53, 61, 'Ve siz gaflet içinde oyalanmaktasınız.');
INSERT INTO verses (sura, aya, text) VALUES (53, 62, 'Artık, (sadece) Allah’a secde edin. O’na ibadet edin.');
INSERT INTO verses (sura, aya, text) VALUES (54, 1, 'O saat/Kıyamet yaklaştı ve Ay yarıldı.');
INSERT INTO verses (sura, aya, text) VALUES (54, 2, 'Onlar, bir mucize görseler yüz çevirirler ve; “Süregelen bir sihirdir.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (54, 3, 'Yalanladılar ve kendi hevalarına uydular; hâlbuki her işin ulaşacağı bir yer vardır.');
INSERT INTO verses (sura, aya, text) VALUES (54, 4, 'Muhakkak (onları bu hallerinden) korkutup vazgeçirecek nice haberler gelmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (54, 5, '(Kur''an) büyük bir hikmettir. Fakat uyarılar bir yarar sağlamadı.');
INSERT INTO verses (sura, aya, text) VALUES (54, 6, 'Onlardan yüz çevir. O gün çağırıcı, onları korkunç olan bir şeye çağırır.');
INSERT INTO verses (sura, aya, text) VALUES (54, 7, 'Gözleri düşkün (zillet içinde), sanki yayılan çekirgeler gibi kabirlerinden çıkarlar.');
INSERT INTO verses (sura, aya, text) VALUES (54, 8, 'Davetçiye doğru koşarlarken kâfirler; “Bu zor bir gün!” derler.');
INSERT INTO verses (sura, aya, text) VALUES (54, 9, 'Onlardan önce Nûh kavmi de yalanladı. Kulumuzu yalanladılar da mecnun (cinlenmiş) dediler. Ve (Nûh, davetten vazgeçmeye) zorlandı.');
INSERT INTO verses (sura, aya, text) VALUES (54, 10, 'O da Rabbine; “Ey Rabbim! Ben yenilgiye uğradım, yardım et!” diye dua etti.');
INSERT INTO verses (sura, aya, text) VALUES (54, 11, 'Bunun üzerine biz de göğün kapılarını şiddetle boşanan sulara açtık.');
INSERT INTO verses (sura, aya, text) VALUES (54, 12, 'Yeryüzünü pınar pınar fışkırttık. Derken sular takdir edilmiş bir iş için birleşti.');
INSERT INTO verses (sura, aya, text) VALUES (54, 13, 'Onu levhaları ve çivileri olan (gemi) üzerinde taşıdık.');
INSERT INTO verses (sura, aya, text) VALUES (54, 14, 'İnkâr edilmiş olana (Nûh''a) bir mükâfat olmak üzere gemi, gözlerimizin önünde akıp gidiyordu.');
INSERT INTO verses (sura, aya, text) VALUES (54, 15, 'Andolsun, biz onu (tufan olayını) bir ibret olarak bıraktık. Var mı düşünüp öğüt alan?');
INSERT INTO verses (sura, aya, text) VALUES (54, 16, '(Bakın) benim azabım ve uyarılarım nasılmış?');
INSERT INTO verses (sura, aya, text) VALUES (54, 17, 'Andolsun ki, Kur''an''ı öğüt alınması için kolaylaştırdık. Fakat öğüt alan var mı?');
INSERT INTO verses (sura, aya, text) VALUES (54, 18, 'Âd (kavmi) de yalanladı. İşte (bakın) benim azabım ve uyarılarım nasılmış?');
INSERT INTO verses (sura, aya, text) VALUES (54, 19, 'Biz onların üstüne, uğursuzluğu devamlı bir günde dondurucu bir rüzgâr gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (54, 20, 'İnsanları koparıp atıyordu. Sanki onlar kökünden kopmuş hurma kütükleri idiler.');
INSERT INTO verses (sura, aya, text) VALUES (54, 21, '(Bakın) benim azabım ve uyarılarım nasılmış?');
INSERT INTO verses (sura, aya, text) VALUES (54, 22, 'Andolsun ki, Kur''an''ı öğüt alınması için kolaylaştırdık. Fakat öğüt alan var mı?');
INSERT INTO verses (sura, aya, text) VALUES (54, 23, 'Semûd kavmi de uyarıcıları yalanladı.');
INSERT INTO verses (sura, aya, text) VALUES (54, 24, '"İçimizden bir beşere mi uyacağız? O takdirde biz kesin bir sapıklık ve delilik içinde (kalmış) oluruz.');
INSERT INTO verses (sura, aya, text) VALUES (54, 25, '"Aramızdan vahiy ona mı gönderildi? Hayır, o kendini beğenmiş yalancının biridir."');
INSERT INTO verses (sura, aya, text) VALUES (54, 26, 'Yarın kimin kendini beğenmiş yalancı olduğunu bilecekler.');
INSERT INTO verses (sura, aya, text) VALUES (54, 27, 'Gerçekten onları imtihan etmek için dişi deveyi gönderen biziz. Sen onları gözetle ve sabret.');
INSERT INTO verses (sura, aya, text) VALUES (54, 28, 'Onlara suyun aralarında taksim edildiğini de haber ver. Her biri kendi içme sırasında gelsin.');
INSERT INTO verses (sura, aya, text) VALUES (54, 29, 'Arkadaşlarını çağırdılar, o da (kılıcı) alıp, deveyi kesti.');
INSERT INTO verses (sura, aya, text) VALUES (54, 30, '(Bakın) benim azabım ve uyarılarım nasılmış?');
INSERT INTO verses (sura, aya, text) VALUES (54, 31, 'Şüphesiz biz, onların üzerine tek bir korkunç ses gönderdik de onlar, ağıldaki (hayvanların çiğneyip ufaladıkları) kuru çöpler gibi oldular.');
INSERT INTO verses (sura, aya, text) VALUES (54, 32, 'Andolsun ki, Kur''an''ı öğüt alınması için kolaylaştırdık. Fakat öğüt alan var mı?');
INSERT INTO verses (sura, aya, text) VALUES (54, 33, 'Lût’un kavmi de uyarıldıkları şeyi yalanladılar.');
INSERT INTO verses (sura, aya, text) VALUES (54, 34, 'Biz de üzerlerine taş yağdıran fırtına gönderdik. Ancak Lût’un ailesini seher vakti kurtarmıştık.');
INSERT INTO verses (sura, aya, text) VALUES (54, 35, 'Katımızdan bir nimet olarak şükredenleri işte böyle ödüllendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (54, 36, 'Lût, and olsun ki, onları Bizim yakalamamızla uyarmıştı, ama onlar uyarmaları şüphe ile karşıladılar.');
INSERT INTO verses (sura, aya, text) VALUES (54, 37, 'Onlar Lût''un misafirlerini elde etmeye kalkıştılar. Hemen biz onların gözlerini silme kör ettik; "Haydi azabımı ve uyarılarımı tadın!" (dedik).');
INSERT INTO verses (sura, aya, text) VALUES (54, 38, 'Andolsun ki, bir sabah erkenden kalıcı bir azap üzerlerine çöküverdi.');
INSERT INTO verses (sura, aya, text) VALUES (54, 39, '"Tadın azabımı ve tehdidimi!"');
INSERT INTO verses (sura, aya, text) VALUES (54, 40, 'Andolsun ki, Kur''an''ı öğüt alınması için kolaylaştırdık. Fakat öğüt alan var mı?');
INSERT INTO verses (sura, aya, text) VALUES (54, 41, 'Şüphesiz Firavun’un kavmine de uyarıcılar gelmişti.');
INSERT INTO verses (sura, aya, text) VALUES (54, 42, 'Bütün ayetlerimizi yalanladılar. Biz de onları üstün ve güçlü olanın yakalamasıyla yakalayıverdik.');
INSERT INTO verses (sura, aya, text) VALUES (54, 43, 'Sizin kâfirleriniz onlardan daha hayırlı mıdırlar yoksa kitaplarda sizin için bir berat mı var?');
INSERT INTO verses (sura, aya, text) VALUES (54, 44, 'Yoksa onlar, “Biz yardımlaşan (güçlü) bir topluluğuz” mu diyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (54, 45, 'Yakında o topluluk yenilecek ve arkalarını dönerek kaçacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (54, 46, 'Asıl onlara vaat olunan vakit kıyamettir ve o kıyamet daha büyük bela ve daha acıdır.');
INSERT INTO verses (sura, aya, text) VALUES (54, 47, 'Şüphesiz günahkârlar sapıklık ve azap içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (54, 48, 'O gün yüzleri üstüne ateşe sürüklenecekler. "Cehennemin dokunuşunu tadın."');
INSERT INTO verses (sura, aya, text) VALUES (54, 49, 'Biz her şeyi bir kaderle yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (54, 50, 'Bizim buyruğumuz sadece bir tektir. Bir göz kırpmak gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (54, 51, 'Andolsun biz benzerlerinizi helak ettik. O halde var mı bir düşünen?');
INSERT INTO verses (sura, aya, text) VALUES (54, 52, 'Yaptıkları her şey kitaplarda (amel defterinde) mevcuttur.');
INSERT INTO verses (sura, aya, text) VALUES (54, 53, 'Ve küçük, büyük her şey satır satır yazılmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (54, 54, 'Takva sahibi olanlar, Cennetler''de ve pınarlardadır.');
INSERT INTO verses (sura, aya, text) VALUES (54, 55, 'Muktedir bir hükümdarın katında, doğruluk meclisindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (55, 1, 'Rahmân.');
INSERT INTO verses (sura, aya, text) VALUES (55, 2, 'Kur’an''ı öğretti.');
INSERT INTO verses (sura, aya, text) VALUES (55, 3, 'İnsanı yarattı.');
INSERT INTO verses (sura, aya, text) VALUES (55, 4, 'Ona beyanı öğretti.');
INSERT INTO verses (sura, aya, text) VALUES (55, 5, 'Güneş ve Ay belli bir hesapladır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 6, 'Bitkiler ve ağaçlar (Allah''a) secde etmektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (55, 7, 'Göğü yükseltti ve mizanı (adaleti) koydu.');
INSERT INTO verses (sura, aya, text) VALUES (55, 8, 'O halde ölçüde haddi aşmayın.');
INSERT INTO verses (sura, aya, text) VALUES (55, 9, 'Tartıyı adaletle tutup doğrultun ve tartıyı noksan tutmayın.');
INSERT INTO verses (sura, aya, text) VALUES (55, 10, 'Allah, yeri canlılar için döşedi.');
INSERT INTO verses (sura, aya, text) VALUES (55, 11, 'Orada meyveler ve tomurcuklu hurmalar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 12, 'Yapraklı taneler, hoş kokulu bitkiler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 13, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 14, 'O, insanı pişmiş çamur gibi kuru balçıktan yaratmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 15, 'Cinleri de yalın bir ateşten yarattı.');
INSERT INTO verses (sura, aya, text) VALUES (55, 16, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 17, 'O, iki doğunun Rabbidir, iki batının Rabbidir.');
INSERT INTO verses (sura, aya, text) VALUES (55, 18, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 19, 'İki denizi birbiriyle kavuşsun diye salıvermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (55, 20, 'Aralarında bir engel vardır, birbirine geçip karışmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (55, 21, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 22, 'O iki denizden inci ve mercan çıkar.');
INSERT INTO verses (sura, aya, text) VALUES (55, 23, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 24, 'Denizde yüce dağlar gibi yükselen gemiler de O''nundur.');
INSERT INTO verses (sura, aya, text) VALUES (55, 25, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 26, 'Onun üzerinde bulunan her şey yok olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 27, 'Azamet ve ikram sahibi olan Rabbinizin vechi/yüzü bakidir.');
INSERT INTO verses (sura, aya, text) VALUES (55, 28, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 29, 'Göklerde ve yerde kim varsa hepsi O’ndan ister. O, her gün bir iştedir.');
INSERT INTO verses (sura, aya, text) VALUES (55, 30, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 31, 'Ey insanlar ve cinler! Sizin de hesabınızı göreceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (55, 32, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 33, 'Ey cin ve insan toplulukları! Göklerin ve yerin çerçevesinden çıkıp gitmeye gücünüz yetiyorsa geçin. Ancak büyük bir güçle çıkıp gidebilirsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (55, 34, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 35, 'Ey insanlar ve cinler! Üzerinize dumansız bir alev ve ateşsiz bir duman gönderilir de kurtulamazsınız.');
INSERT INTO verses (sura, aya, text) VALUES (55, 36, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 37, 'Gök yarılıp da kızarmış yağ renginde gül gibi olduğu zaman.');
INSERT INTO verses (sura, aya, text) VALUES (55, 38, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 39, 'O gün hiçbir insana ve cine günahı sorulmaz.');
INSERT INTO verses (sura, aya, text) VALUES (55, 40, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 41, 'Günahkârlar simalarından tanınır, sonra da perçemlerinden ve ayaklarından yakalanır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 42, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 43, 'İşte bu o günahkârların yalan saydığı cehennemdir.');
INSERT INTO verses (sura, aya, text) VALUES (55, 44, 'Onlar, Cehennem ateşi ile kaynar su arasında gider gelirler.');
INSERT INTO verses (sura, aya, text) VALUES (55, 45, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 46, 'Rabbinin makamından korkanlara iki Cennet vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 47, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 48, 'Her ikisi de çeşit çeşit dallı ağaçlara sahiptir.');
INSERT INTO verses (sura, aya, text) VALUES (55, 49, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 50, 'Onların ikisinde de akan iki pınar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 51, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 52, 'İkisinde de her türlü meyveden çift çift vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 53, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 54, '(Orada) astarları kalın atlastan yataklara yaslanırlar. Her iki cennetten devşirilen meyveler de (oradakilere) yakındır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 55, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 56, 'Oralarda bakışlarını sadece eşlerine çevirmiş dilberler vardır. Onlara eşlerinden önce ne bir insan, ne de bir cin dokunmuştur.');
INSERT INTO verses (sura, aya, text) VALUES (55, 57, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 58, 'Sanki onlar yakut ve mercan gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (55, 59, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 60, 'İyiliğin karşılığı iyilikten başkası olabilir mi?');
INSERT INTO verses (sura, aya, text) VALUES (55, 61, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 62, 'Bu ikisinden başka iki Cennet daha vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 63, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 64, 'İkisi de yemyeşildirler.');
INSERT INTO verses (sura, aya, text) VALUES (55, 65, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 66, 'İkisinde de suları durmaksızın coşan iki pınar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 67, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 68, 'Her ikisinde de meyve, hurma ve nar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 69, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 70, 'Orada iyi huylu güzel yüzlü kadınlar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 71, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 72, 'Otağlar içerisinde sahiplerine tahsis edilmiş huriler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (55, 73, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 74, 'Onlara eşlerinden önce ne bir insan, ne de bir cin dokunmuştur.');
INSERT INTO verses (sura, aya, text) VALUES (55, 75, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 76, 'Yeşil yastıklara ve harikulâde güzel döşemelere yaslanırlar.');
INSERT INTO verses (sura, aya, text) VALUES (55, 77, 'Öyleyse Rabbinizin hangi nimetlerini yalanlayabilirsiniz?');
INSERT INTO verses (sura, aya, text) VALUES (55, 78, 'Azamet ve ikram sahibi Rabbinin adı ne yücedir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 1, 'Kıyamet koptuğu zaman.');
INSERT INTO verses (sura, aya, text) VALUES (56, 2, 'Onun gerçekleşmesine artık yalan diyecek yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (56, 3, 'O; alçaltıcı, yükselticidir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 4, 'Yer şiddetle sarsılınca.');
INSERT INTO verses (sura, aya, text) VALUES (56, 5, 'Dağlar paramparça olduğunda.');
INSERT INTO verses (sura, aya, text) VALUES (56, 6, 'Derken toz toprak halinde dağılıp savrulduğu zaman.');
INSERT INTO verses (sura, aya, text) VALUES (56, 7, 'Ve sizler de üç sınıf olduğunuz zaman.');
INSERT INTO verses (sura, aya, text) VALUES (56, 8, 'Sağdakiler, (ne mutlu) o sağdakilere!');
INSERT INTO verses (sura, aya, text) VALUES (56, 9, 'Soldakiler, ne bahtsızdır onlar!');
INSERT INTO verses (sura, aya, text) VALUES (56, 10, '(Hayırda) önde olanlar, öncülerdir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 11, 'İşte onlar, yakınlaştırılmış olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 12, 'Onlar Naim Cennetleri''ndedirler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 13, 'Bir çoğu öncekilerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 14, 'Birazı da sonrakilerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 15, '(Altın ile) işlenmiş tahtlar üzerindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 16, 'Karşılıklı olarak oturup yaslanırlar.');
INSERT INTO verses (sura, aya, text) VALUES (56, 17, 'Onların etrafında ölümsüz genç hizmetçiler dolaşır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 18, 'Kaynağından (doldurulmuş) testiler, ibrikler ve kadehler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 19, 'Ondan başları da ağrımaz ve akılları da giderilmez.');
INSERT INTO verses (sura, aya, text) VALUES (56, 20, 'Beğendikleri meyveler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 21, 'Canlarının çektiği kuş etleri.');
INSERT INTO verses (sura, aya, text) VALUES (56, 22, 'Ve iri gözlü huriler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 23, 'Saklı inciler gibi.');
INSERT INTO verses (sura, aya, text) VALUES (56, 24, 'İşledikleri amellere karşılık olarak (verilir.)');
INSERT INTO verses (sura, aya, text) VALUES (56, 25, 'Orada boş bir söz ve günaha sokan bir laf işitmezler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 26, 'Söylenen; yalnızca "Selâm, selâm!" dır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 27, 'Sağdakiler, (ne mutlu) o sağdakilere!');
INSERT INTO verses (sura, aya, text) VALUES (56, 28, 'Dikensiz sedir ağaçlarında.');
INSERT INTO verses (sura, aya, text) VALUES (56, 29, 'Salkım salkım muz ağaçlarında.');
INSERT INTO verses (sura, aya, text) VALUES (56, 30, 'Uzamış gölgeler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 31, 'Çağlayarak akan sular.');
INSERT INTO verses (sura, aya, text) VALUES (56, 32, 'Bir çok meyveler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 33, 'Bitip tükenmeyen ve yasaklanmayan.');
INSERT INTO verses (sura, aya, text) VALUES (56, 34, 'Ve yüksek döşekler içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (56, 35, 'Biz, o hurileri yeni bir yaratılışla yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (56, 36, 'Onları bakireler kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (56, 37, 'Eşlerine düşkün ve yaşıt.');
INSERT INTO verses (sura, aya, text) VALUES (56, 38, 'Sağ taraftakiler için.');
INSERT INTO verses (sura, aya, text) VALUES (56, 39, 'Bir çoğu öncekilerden.');
INSERT INTO verses (sura, aya, text) VALUES (56, 40, 'Bir çoğu da sonrakilerdendir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 41, 'Soldakiler, ne bahtsızdır onlar!');
INSERT INTO verses (sura, aya, text) VALUES (56, 42, 'İçlerine işleyen bir ateş ve kaynar su içinde.');
INSERT INTO verses (sura, aya, text) VALUES (56, 43, 'Simsiyah bir duman gölgesinde.');
INSERT INTO verses (sura, aya, text) VALUES (56, 44, 'Ne bir serinlik, ne de bir güzellik!');
INSERT INTO verses (sura, aya, text) VALUES (56, 45, 'Çünkü onlar, bundan önce (arzularının hoşuna giden şeyler içinde) şımarmış kimselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (56, 46, 'Büyük günah üzerinde ısrar ediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (56, 47, '"Biz ölüp, toprak ve kemik olduktan sonra tekrar mı dirileceğiz?" diyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (56, 48, '"Daha önceki atalarımız da mı?"');
INSERT INTO verses (sura, aya, text) VALUES (56, 49, 'De ki: "Hem öncekiler, hem sonrakiler."');
INSERT INTO verses (sura, aya, text) VALUES (56, 50, 'Belli bir günün, belli bir vaktinde bir araya getirileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 51, 'Sonra gerçekten sizler ey sapıklar, yalanlayıcılar!');
INSERT INTO verses (sura, aya, text) VALUES (56, 52, 'Elbette bir ağaçtan, zakkum ağacından yiyeceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 53, 'Karınlarınızı hep ondan dolduracaksınız.');
INSERT INTO verses (sura, aya, text) VALUES (56, 54, 'Üstüne de kaynar sudan içeceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 55, 'Susamış develerin içişi gibi içeceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 56, 'İşte ceza gününde onlara sunulacak ziyafet budur.');
INSERT INTO verses (sura, aya, text) VALUES (56, 57, 'Sizi biz yarattık. (Tekrardan yaratılışı) tasdik etmeniz gerekmez mi ?');
INSERT INTO verses (sura, aya, text) VALUES (56, 58, 'Akıttığınız meniyi gördünüz mü?');
INSERT INTO verses (sura, aya, text) VALUES (56, 59, 'Onu siz mi yaratıyorsunuz? Yoksa yaratan biz miyiz?');
INSERT INTO verses (sura, aya, text) VALUES (56, 60, 'Aranızda ölümü takdir eden biziz. Bizler aciz de değiliz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 61, 'Yerinize benzerlerinizi getirip, değiştirmek ve sizi bilemediğiniz bir şekilde yeniden yaratmak hususunda.');
INSERT INTO verses (sura, aya, text) VALUES (56, 62, 'Andolsun ki ilk yaratmayı bildiniz. O halde düşünüp öğüt almanız gerekmez mi?');
INSERT INTO verses (sura, aya, text) VALUES (56, 63, 'Ektiğiniz şeyleri gördünüz mü?');
INSERT INTO verses (sura, aya, text) VALUES (56, 64, 'Onu siz mi bitiriyorsunuz? Yoksa bitiren biz miyiz?');
INSERT INTO verses (sura, aya, text) VALUES (56, 65, 'Dileseydik onu kuru bir çöp yapardık; siz de şaşırıp kalırdınız.');
INSERT INTO verses (sura, aya, text) VALUES (56, 66, 'Doğrusu borç altına girdik.');
INSERT INTO verses (sura, aya, text) VALUES (56, 67, '"Daha doğrusu biz yoksul bırakıldık (dersiniz)."');
INSERT INTO verses (sura, aya, text) VALUES (56, 68, 'İçtiğiniz suyu gördünüz mü?');
INSERT INTO verses (sura, aya, text) VALUES (56, 69, 'Onu buluttan siz mi indirdiniz? Yoksa indiren biz miyiz?');
INSERT INTO verses (sura, aya, text) VALUES (56, 70, 'Dileseydik onu tuzlu yapardık. Şükretmeniz gerekmez mi?');
INSERT INTO verses (sura, aya, text) VALUES (56, 71, 'Tutuşturup, yakmakta olduğunuz ateşi gördünüz mü?');
INSERT INTO verses (sura, aya, text) VALUES (56, 72, 'Onun ağacını siz mi yarattınız? Yoksa yaratan biz miyiz?');
INSERT INTO verses (sura, aya, text) VALUES (56, 73, 'Biz onu, bir ibret ve gelip geçen yolcuların istifadesi için yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (56, 74, 'O halde sen, Yüce Rabbinin adını tesbih et!');
INSERT INTO verses (sura, aya, text) VALUES (56, 75, 'Yıldızların yerlerine yemin ederim ki!');
INSERT INTO verses (sura, aya, text) VALUES (56, 76, 'Eğer bilirseniz, gerçekten bu büyük bir yemindir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 77, 'Şüphesiz bu, değerli bir Kur''an''dır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 78, 'Gizli/korunmuş bir kitaptadır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 79, 'Ona ancak temizlenmiş olanlar dokunabilir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 80, 'Âlemlerin Rabbi tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (56, 81, 'Şimdi siz, bu sözü mü yalanlıyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (56, 82, 'Onu yalanlayarak mı size verilen nimete şükrediyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (56, 83, 'Hani can boğaza gelip dayandığında.');
INSERT INTO verses (sura, aya, text) VALUES (56, 84, 'O vakit siz bakıp durursunuz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 85, 'Biz; ona sizden daha yakınız, ama göremezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 86, 'Madem ki (tekrardan dirilip) ceza görmeyecekmişsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (56, 87, 'Eğer doğru söylüyor iseniz, onu (çıkmakta olan canı) geri çevirsenize!');
INSERT INTO verses (sura, aya, text) VALUES (56, 88, 'Eğer o (ölen kişi), yakın kılınanlardan ise.');
INSERT INTO verses (sura, aya, text) VALUES (56, 89, 'Ona rahatlık, güzel rızık ve Naim Cenneti vardır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 90, 'Eğer o, sağdakilerden ise.');
INSERT INTO verses (sura, aya, text) VALUES (56, 91, 'Ey sağdaki! Sana selam olsun!');
INSERT INTO verses (sura, aya, text) VALUES (56, 92, 'Eğer o, yalanlayan sapıklardan ise.');
INSERT INTO verses (sura, aya, text) VALUES (56, 93, 'İşte ona da kaynar sudan bir ziyafet vardır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 94, 'Ve (onun sonu) Cehennem''e atılmaktır.');
INSERT INTO verses (sura, aya, text) VALUES (56, 95, 'Şüphe yok ki, kesin gerçek işte budur.');
INSERT INTO verses (sura, aya, text) VALUES (56, 96, 'O halde sen, Yüce Rabbinin adını tesbih et!');
INSERT INTO verses (sura, aya, text) VALUES (57, 1, 'Göklerde ve yerde olanlar Allah’ı tesbih ederler. O; Aziz''dir, Hakim''dir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 2, 'Göklerin ve yerin mülkü O’nundur. O; diriltir, öldürür. O, her şeye gücü yetendir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 3, 'O; Evvel''dir, Âhir''dir, Zahir''dir, Bâtın''dır. O, her şeyi hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 4, 'Gökleri ve yeri altı günde yaratan sonra da Arş’a istivâ eden O’dur. Yere gireni, ondan çıkanı, gökten ineni, göğe yükseleni bilir. Her nerede iseniz, O sizinle beraberdir. Allah, yaptığınız her şeyi görendir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 5, 'Göklerin ve yerin mülkü O’nundur. Bütün işler Allah’a döner.');
INSERT INTO verses (sura, aya, text) VALUES (57, 6, 'Geceyi gündüze katar, gündüzü de geceye katar. O, kalplerde olan her şeyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 7, 'Allah''a ve Rasûlüne iman edin ve sizi üzerinde yetki sahibi kıldığı şeylerden (Allah yolunda) harcayın. Sizden iman eden ve (Allah yolunda) harcayanlar için büyük ecir vardır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 8, 'Size ne oluyor ki, Peygamber sizi Rabbinize iman etmeniz için çağırırken Allah''a iman etmiyorsunuz? Oysa (Allah) sizden kesin söz almıştı. Eğer iman edecekseniz.');
INSERT INTO verses (sura, aya, text) VALUES (57, 9, 'Sizi karanlıklardan aydınlığa çıkarmak için kuluna apaçık ayetler indiren O’dur. Şüphesiz Allah, size karşı çok şefkatli, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 10, 'Göklerin ve yerin mirası Allah’ın olduğu halde size ne oluyor ki, Allah yolunda infak etmiyorsunuz? İçinizden, fetihten önce infak edip savaşanlar (diğerleriyle) eşit değildir. Onların derecesi, daha sonra infak edip savaşanlardan daha büyüktür. Allah, her birine en güzelini vadetmiştir. Allah, yaptığınız her şeyden hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 11, 'Allah''a güzel bir borç verecek olan kimdir? Artık Allah, bunu kendisi için kat kat artırır. Onun için güzel bir ecir vardır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 12, 'O gün Mümin erkekler ile Mümin kadınları, nurları önlerinde ve sağlarında koşarken görürsün. Bugün sizin müjdeniz; altından ırmaklar akan, içinde sonsuza kadar kalacağınız Cennetlerdir. İşte büyük kurtuluş budur.');
INSERT INTO verses (sura, aya, text) VALUES (57, 13, 'O gün münafık erkeklerle münafık kadınlar iman edenlere derler ki: "Bize bakın da sizin nurunuzdan bir parça ışık alalım." (Onlara): "Arkanıza dönüp bir nur arayın." denir. Derken aralarına kapısı olan bir sur çekilir. Onun iç tarafında rahmet, dış tarafından ise azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 14, 'Münafıklar, Müminlere: "Sizinle beraber değil miydik?" diye seslenirler. (Müminler de): "Evet! Ancak siz kendi başınızı belaya soktunuz, (Müslümanların başına bela gelmesini) gözetip beklediniz, şüphe ettiniz. Sizleri kuruntular yanıltıp aldattı. Sonunda Allah''ın emri (olan ölüm) geliverdi ve o aldatıcı da sizi Allah ile aldatmış oldu.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (57, 15, 'Bugün artık ne sizden, ne de kâfirlerden bir fidye alınır. Barınağınız ateştir. Size yaraşan odur. Ne kötü bir dönüş yeridir!');
INSERT INTO verses (sura, aya, text) VALUES (57, 16, 'İman edenlerin Allah’ı zikretmekten ve inen haktan dolayı kalplerinin saygı ile ürpermesinin zamanı gelmedi mi? Daha önce kendilerine kitap verilip de üzerinden uzun zaman geçen, böylece kalpleri katılaşanlar gibi olmasınlar. Onlardan birçoğu fasık kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 17, 'Bilin ki Allah yeryüzünü ölümünden sonra diriltir. Belki akıl edersiniz diye size ayetleri açıkladık.');
INSERT INTO verses (sura, aya, text) VALUES (57, 18, 'Şüphesiz ki sadaka veren erkeklerle sadaka veren kadınlar ve Allah’a güzel bir borç verenler var ya, (verdikleri) onlara kat kat ödenir. Ayrıca onlara çok değerli bir mükâfat da vardır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 19, 'Allah’a ve rasullerine iman edenler işte onlar Rablerinin nezdinde sıddikler/dosdoğru olanlar ve şehitlerdir. Onlara ecirleri ve nurları verilecektir. Kâfir olup, ayetlerimizi yalanlayanlara gelince, işte onlar cehennemlik olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 20, 'Bilin ki dünya hayatı ancak bir oyun, bir eğlence, bir süs, aranızda karşılıklı bir övünme, çok mal ve evlat sahibi olma yarışından ibarettir. Tıpkı şöyle: Bir yağmur ki, bitirdiği bitki çiftçilerin hoşuna gider. Sonra kurumaya yüz tutar da sen onu sararmış olarak görürsün. Sonra da çerçöp olur ahirette şiddetli bir azap da vardır. Allah’tan bir mağfiret ve bir rıza da vardır. Dünya hayatı aldatıcı bir yararlanmadan başka bir şey değildir. Dünya hayatı, aldanış metaından başka bir şey değildir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 21, 'Rabbinizden bir mağfirete ve genişliği yerle gök kadar olan Cennet için yarışın! (Bu) Allah’a ve Rasûlüne iman edenler için hazırlanmıştır. İşte bu, Allah’ın lütfudur. Onu dilediğine verir. Allah, büyük lütuf sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 22, 'Yeryüzünde ve kendi nefislerinizde uğradığınız hiçbir musibet yoktur ki, biz onu yaratmadan önce bir kitapta (Levh-i Mahfuz’da) yazılmış olmasın. Şüphesiz bu, Allah’a göre kolaydır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 23, 'Elinizden çıkana üzülmeyesiniz ve Allah’ın size verdiği nimetlerle şımarmayasınız diye (böyle yaptık.) Çünkü Allah, kendini beğenip övünen hiçbir kimseyi sevmez.');
INSERT INTO verses (sura, aya, text) VALUES (57, 24, 'Onlar, cimrilik eder ve insanlara da cimriliği emrederler. Kim yüz çevirirse; şüphesiz Allah zengindir, hamde layık olandır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 25, 'Andolsun ki, elçilerimizi açık delillerle gönderdik ve insanlar adaleti ayakta tutsunlar diye onlarla birlikte kitabı ve ölçüyü indirdik. Ve Allah’ın kendisine ve elçilerine görmediği halde (gıyaben) kimin yardım edeceğini ortaya çıkarması için, kendisinde çetin bir sertlik ve insanlar için (çeşitli) yararlar bulunan demiri indirdik. Şüphesiz Allah güçlüdür, kuvvet sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 26, '-Andolsun ki biz, Nûh’u ve İbrahim’i gönderdik. Peygamberliği de kitabı da onların soyuna verdik. Onlardan hidayete erişen olduğu gibi, çoğu fâsıklardır/yoldan çıkmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (57, 27, 'Sonra onların izleri üzerinde rasûllerimizi birbiri ardınca gönderdik. Meryem oğlu Îsâ’yı da arkalarından gönderdik. Ona İncil’i verdik, ona tabi olanların kalplerine şefkat ve merhamet duygusu yerleştirdik. Onların uydurdukları ruhbanlığı ise biz farz kılmadık. Bunu Allah’ın rızasını kazanmak için yaptılar. Fakat ona da hakkıyla riayet etmediler. Biz de onlardan iman edenlere mükâfatlarını verdik. Onlardan çoğu fasıklardır/yoldan çıkmış kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 28, 'Ey iman edenler! Allah’a karşı gelmekten sakının ve Rasûlüne iman edin ki, size rahmetinden iki kat pay versin. Size kendisiyle yürüyeceğiniz bir nur versin ve sizi bağışlasın. Allah çok bağışlayıcıdır, çok merhamet edicidir.');
INSERT INTO verses (sura, aya, text) VALUES (57, 29, 'Böylece, kitap ehli Allah’ın lütfundan bir şeye güç yetiremediklerini, lütfun tamamen Allah’ın elinde olduğunu ve onu dilediğine verdiğini bilsinler. Allah büyük lütuf sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (58, 1, 'Allah, kocası hakkında seninle tartışan ve Allah''a şikâyette bulunan kadının sözünü duydu. Allah sizin karşılıklı konuşmanızı işitiyordu. Şüphesiz Allah; hakkıyla işitendir, hakkıyla görendir.');
INSERT INTO verses (sura, aya, text) VALUES (58, 2, 'Sizden zıhar yapanların karıları, onların anaları değildir. Onların anaları ancak kendilerini doğuran kadınlardır. Böyle yapanlar, münker/çirkin bir söz ve yalan söylüyorlar. Allah; şüphesiz çok affedicidir, çok bağışlayıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 3, 'Hanımlarına zihâr yapıp sonra da söylediklerinden dönenler, birbirleriyle temas etmeden önce bir köle azad etmeleri gerekir. İşte size böyle öğüt veriliyor. Allah, yaptığınız her şeyden hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 4, 'Kim (bu imkânı) bulamazsa, yine birbirleriyle temas etmeden önce peş peşe oruç tutmalıdır. Buna gücü yetmeyenin de altmış yoksulu doyurması gerekir. İşte bu, Allah''a ve Rasûlüne iman etmeniz içindir. İşte bunlar, Allah’ın sınırlarıdır. Kâfirler için acı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 5, 'Allah’a ve Rasûlüne muhalefet edenler, kendilerinden öncekilerin alçaltıldıkları gibi alçaltılacaklardır. Biz, apaçık ayetler indirmiştik. Kâfirler için alçaltıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 6, 'Allah, onların hepsini o gün diriltecek ve onlara yaptıklarını haber verecektir. Allah, onları bir bir saymıştır. Onlar ise unutmuşlardır. Allah, her şeye şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (58, 7, 'Göklerdeki ve yerdeki her şeyi Allah’ın bildiğini görmüyor musun? Üç kişi gizlice konuşmaz ki, dördüncüleri O olmasın. Beş kişi gizlice konuşmaz ki, altıncıları O olmasın. Bundan daha az yahut daha çok da olsalar, nerede olurlarsa olsunlar, O mutlaka onlarla beraberdir. Sonra onlara yaptıklarını kıyamet günü haber verecektir. Allah, her şeyi hakkıyla bilir.');
INSERT INTO verses (sura, aya, text) VALUES (58, 8, 'Gizlice konuşmaktan men edilip de, men edildikleri şeyi işleyen ve günah, düşmanlık ve Peygambere isyanı (aralarında) fısıldaşmakta olanları görmedin mi? Sana geldiklerinde Allah’ın seni selamlamadığı selamla selamlıyorlar. İçlerinden de; “Söylediklerimizden dolayı Allah bize azap etse ya!” diyorlar. Cehennem onlara yeter! Oraya girecekler. Ne kötü varış yeridir orası!');
INSERT INTO verses (sura, aya, text) VALUES (58, 9, 'Ey iman edenler! Aranızda gizli konuşurken günah, düşmanlık ve Peygambere karşı gelmek hususunda fısıldaşmayın, iyilik ve takva konusunda konuşun. Huzurunda toplanacağınız Allah’tan korkun!');
INSERT INTO verses (sura, aya, text) VALUES (58, 10, 'Gizli konuşmalar şeytandandır. Bu, iman edenleri üzmek içindir. Oysa şeytan, Allah''ın izni olmadıkça, Müminler''e hiçbir zarar veremez. Öyle ise Mü’minler ancak Allah’a tevekkül etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (58, 11, 'Ey iman edenler! Size, meclislerde yer açın denildiği zaman yer açın ki, Allah da size genişlik versin. “Kalkın!” Denildiği zaman kalkın ki, Allah da sizden iman edenlerin ve kendilerine ilim verilenlerin derecelerini yükseltsin. Allah, yaptığınız her şeyden hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 12, 'Ey iman edenler! Rasûlle gizli bir şey konuşacağınız zaman, bu konuşmanızdan önce bir sadaka veriniz. Bu sizin için daha hayırlı ve daha temizdir. Eğer bulamazsanız; şüphesiz Allah çok bağışlayandır, çok merhamet edendir.');
INSERT INTO verses (sura, aya, text) VALUES (58, 13, 'Gizli bir şey konuşmanızdan önce sadakalar verip (fakir olmaktan) çekindiniz mi? (Size emredileni) yapmadığınıza (göre), Allah da sizi affetti. Artık namazı ikame edin, zekâtı verin, Allah''a ve Rasûlüne itaat edin. Allah, yaptığınız her şeyden haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 14, 'Allah’ın gazap ettiği bir toplumu dost edinenleri gördün mü? Onlar sizden değil, onlardan da değil. Bile bile yalan yere yemin ediyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (58, 15, 'Allah, onlar için şiddetli bir azap hazırlamıştır. Yapmakta oldukları şey ne kötüdür.');
INSERT INTO verses (sura, aya, text) VALUES (58, 16, 'Yeminlerini kalkan edindiler de, Allah yolundan alıkoydular; onlara alçaltıcı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 17, 'Onların malları da evlatları da Allah katında onlara hiçbir yarar sağlamayacaktır. Onlar, ateş ehlidir. Onlar, orada ebedîdir.');
INSERT INTO verses (sura, aya, text) VALUES (58, 18, 'O gün Allah, onların tümünü diriltir, size yemin ettikleri gibi O''na da yemin ederler ve kendilerinin bir şey üzere olduklarını sanırlar. İyi bilin ki, onlar yalancıların tâ kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (58, 19, 'Şeytan onları kuşatmış ve kendilerine Allah''ı anmayı unutturmuştur. Onlar, Şeytan''ın hizbidir. Şunu bilin ki Şeytan''ın hizbi hüsrana uğrayanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (58, 20, 'Allah’a ve Rasûlüne muhalefet edenler, işte onlar en aşağı kimselerin arasındadırlar.');
INSERT INTO verses (sura, aya, text) VALUES (58, 21, 'Allah: “Andolsun ki ben ve rasullerim mutlaka galip geleceğim” diye yazmıştır. Şüphesiz Allah; çok kuvvetlidir, çok güçlüdür.');
INSERT INTO verses (sura, aya, text) VALUES (58, 22, 'Allah’a ve ahiret gününe iman eden hiçbir topluluğun babaları, oğulları, kardeşleri yahut akrabaları olsalar bile, Allah’a ve Peygamberine düşman olan kimselere sevgi beslediğini göremezsin. İşte Allah, onların kalplerine imanı yazmış ve onları kendi katından bir ruh ile desteklemiştir. Onları, içlerinden ırmaklar akan ve içlerinde ebedî kalacakları Cennetlere sokacaktır. Allah onlardan razı olmuş, onlar da Allah’tan razı olmuşlardır. İşte onlar, Allah’ın tarafında olanlardır. İyi bilin ki, Allah’ın tarafında olanlar kurtuluşa erenlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 1, 'Göklerde ve yerde olan her şey Allah’ı tesbih etmektedir. O; çok güçlüdür, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 2, 'Ehli Kitap''tan küfre sapanları ilk sürgünde (Arap Yarımadası''ndan), yurtlarından (Şam''a) çıkaran O''dur. Siz, onların çıkacaklarını sanmamıştınız. Onlar da kalelerinin kendilerini Allah’tan koruyacağını sanmışlardı. Böylece Allah da onlara hesaba katmadıkları bir yönden geldi de onların kalplerine korku salıverdi. Kendi elleriyle ve Müminlerin elleriyle evlerini yıktılar. Bundan ibret alın ey basiret sahipleri!');
INSERT INTO verses (sura, aya, text) VALUES (59, 3, 'Eğer Allah, onlara sürgünü yazmamış olsaydı, elbette onları dünyada cezalandıracaktı. Ahirette de onlar için Cehennem azabı vardır.');
INSERT INTO verses (sura, aya, text) VALUES (59, 4, 'İşte bu, onların Allah’a ve Rasûlüne muhalefet etmeleri sebebiyledir. Allah’a karşı muhalefet eden bilsin ki, Allah’ın azabı şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 5, 'Hurma ağaçlarından ne kestiyseniz veya neyi kökleri üzerinde ayakta bıraktıysanız, hep Allah’ın izni ile olmuştur ve (bu) fasıkları alçaltması içindir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 6, 'Allah’ın, onların mallarından Rasûle verdiği şeyler (fey) için siz ne at, ne de deve koşturdunuz. Fakat Allah, Rasûlünü dilediğine karşı üstün kılar. Allah’ın her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (59, 7, 'Allah’ın (fethedilen) kasaba halkından (alınarak) Peygamberine verdiği fey Allah''a, Rasûle, onunla yakınlarına, yetimlere, yoksullara ve yolda kalmışlara aittir. Böylece (bu mallar) sizden zengin olanlar arasında dönüp dolaşan bir (mal) olmasın. Rasûl size ne verdiyse, onu alın ve sizi neyden sakındırmışsa ondan kaçının. Allah’tan sakının. Şüphesiz Allah, azabı pek şiddetli olandır.');
INSERT INTO verses (sura, aya, text) VALUES (59, 8, '(Allah''ın verdiği bu savaş malları) yurtlarından ve mallarından uzaklaştırılmış olan, Allah''tan bir lütuf ve rıza dileyen, Allah''a ve Rasûlüne yardım eden fakir Muhacirler''indir. Ki onlar, sadıkların ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 9, 'Onlardan önce o diyarı yurt edinmiş ve (kalplerine) imanı (yerleştirmiş) olanlar, kendilerine hicret edenleri severler ve onlara verilenlerden dolayı içlerinde bir ihtiyaç (haset) duymazlar. Kendi ihtiyaçları olsa bile onları kendilerine tercih ederler. Kim nefsinin cimriliğinden korunursa, işte onlar kurtuluşa erenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 10, 'Onlardan sonra gelenler de: "Rabbimiz, bizi ve bizden önce iman eden kardeşlerimizi bağışla! Kalbimizde iman edenlere karşı bir kin bırakma! Rabbimiz! Sen çok şefkatli, çok merhametlisin." derler.');
INSERT INTO verses (sura, aya, text) VALUES (59, 11, 'Münafıklık edenleri gördün mü? Ehl-i Kitap''tan kâfir kardeşlerine: "Eğer siz yurdunuzdan çıkarılacak olursanız, biz de sizinle beraber çıkarız. Size karşı hiç kimseye itaat etmeyiz. Eğer sizinle savaşılırsa, mutlaka size yardım ederiz." derler. Allah da onların yalancı olduklarına şahitlik eder.');
INSERT INTO verses (sura, aya, text) VALUES (59, 12, 'Eğer onlar çıkarılırlarsa, onlarla çıkmazlar. Eğer onlara savaş açılırsa, onlara yardım etmezler. Onlara yardıma gitseler bile arkalarını dönüp kaçarlar. Sonra da kendileri yardım görmezler.');
INSERT INTO verses (sura, aya, text) VALUES (59, 13, 'Onların içlerinde size karşı duydukları korku, Allah''a olan korkularından daha şiddetlidir. Böyledir, çünkü onlar anlamayan bir topluluktur.');
INSERT INTO verses (sura, aya, text) VALUES (59, 14, 'Onlar, surlarla çevrili kasabalar veya duvarlar arkasında olmadıkça sizinle topluca savaşamazlar. Kendi aralarındaki savaşları ise şiddetlidir. Onları birlik sanırsın, oysa kalpleri dağınıktır. Böyledir, çünkü onlar akletmeyen bir topluluktur.');
INSERT INTO verses (sura, aya, text) VALUES (59, 15, '(Onların/Yahudilerin durumu) kendilerinden az önce geçmiş ve yaptıklarının cezasını (Bedir''de) tatmış olanların (Mekkeli müşriklerin) durumu gibidir. Onlar, yaptıklarının cezasını tadan kimseler gibidir. Onlar için acı bir azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (59, 16, '(Münafıklar) tıpkı Şeytan gibidirler. Hani o insana: "Küfret!" der. İnsan da küfredince: "Ben senden uzağım, ben âlemlerin Rabbinden korkarım!" der.');
INSERT INTO verses (sura, aya, text) VALUES (59, 17, 'Böylece her ikisinin de sonu, içinde ebedî kalacakları ateştir. İşte zalimlerin cezası budur.');
INSERT INTO verses (sura, aya, text) VALUES (59, 18, 'Ey iman edenler! Allah''tan korkup sakının. Herkes yarın için neyi takdim edip gönderdiğine baksın. Allah’tan sakının. Çünkü Allah, tüm yaptıklarınızdan haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (59, 19, 'Allah’ı unutan ve Allah’ın da onlara kendilerini unutturduğu kimseler gibi olmayın. İşte onlar, yoldan çıkmış olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (59, 20, 'Cehennem ehli ile Cennet ehli bir değildir. Cennet ehli; onlar, kurtulacak olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (59, 21, 'Biz bu Kur’an’ı bir dağın üzerine indirseydik, onun Allah korkusundan baş eğerek parça parça olduğunu görürdün. İşte biz, bu örnekleri insanlar düşünsünler diye veriyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (59, 22, 'O öyle Allah''tır ki, O''ndan başka (hakkıyla ibadete layık hiçbir) ilah yoktur. Görülmeyeni (gaybı) ve görüleni bilendir. O; çok bağışlayıcıdır, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 23, 'O Allah’tır ki ondan başka hiçbir ilah yoktur. Melik’tir, Kuddüs’tür, Selam’dır, Mümin’dir, Muheymin’dir, Aziz’dir, Cebbar’dır, Mütekkebbir’dir. Allah koştukları ortaklardan münezzehtir.');
INSERT INTO verses (sura, aya, text) VALUES (59, 24, 'O Allah; yaratan, yoktan var eden, şekil verendir. En güzel isimler O’nundur. Göklerde ve yerde ne varsa O’nu tesbih eder. O; çok güçlüdür, Hakîm’dir.');
INSERT INTO verses (sura, aya, text) VALUES (60, 1, 'Ey iman edenler! Benim de düşmanım, sizin de düşmanınız olanları veliler edinmeyin. Siz onlara karşı sevgi yöneltiyorsunuz; oysa onlar haktan size geleni inkâr etmişler, Rabbiniz olan Allah’a iman ediyorsunuz diye Peygamberi de sizi de yurdunuzdan çıkarıyorlar. Eğer benim yolumda cihat etmek ve benim razılığımı almak için çıktıysanız onlara gizlice sevgi beslemeyin. Ben gizlediğinizi de açıkladığınızı da bilirim. Sizden kim bunu yaparsa, doğru yoldan sapmış olur.');
INSERT INTO verses (sura, aya, text) VALUES (60, 2, 'Eğer onlar size üstün gelirlerse, size düşman olurlar. Kötülükle ellerini ve dillerini size uzatırlar. Sizin kâfir olmanızı arzu ederler.');
INSERT INTO verses (sura, aya, text) VALUES (60, 3, 'Ne akrabalarınız, ne de çocuklarınız size hiçbir fayda sağlamayacaktır. Kıyamet günü Allah, aranızı ayırır. Allah yaptıklarınızı görmektedir.');
INSERT INTO verses (sura, aya, text) VALUES (60, 4, 'İbrahim’de ve onunla beraber olanlarda sizin için gerçekten uyulacak, güzel bir örnek vardır. Hani onlar kavimlerine: “Muhakkak bizler sizden ve Allah’tan başka ibadet ettiğiniz şeylerden uzağız. Sizi inkâr ettik, yalnız Allah’a iman edinceye kadar bizimle sizin aranızda düşmanlık ve kin ebediyen baş göstermiştir” demişlerdi. İbrahim’in babasına söylediği: “Muhakkak senin için mağfiret isteyeceğim ama Allah’a karşı sana fayda sağlayamam” sözü müstesna: "Senin için bağışlanma dileyeceğim. Fakat Allah’tan sana gelecek hiçbir şeye gücüm yetmez. Rabbimiz! Sana dayandık, sana yöneldik ve dönüş sanadır."');
INSERT INTO verses (sura, aya, text) VALUES (60, 5, '“Rabbimiz! Küfre sapanlar için bizi deneme konusu kılma. Bizi bağışla! Rabbimiz, şüphesiz güçlü ve Hakim sensin!');
INSERT INTO verses (sura, aya, text) VALUES (60, 6, 'Andolsun ki onlarda sizin için ve Allah’ı ve ahireti umanlar için güzel bir örnek vardır. Allah çok zengindir. Bütün övgülere tek layık olandır.');
INSERT INTO verses (sura, aya, text) VALUES (60, 7, 'Olur ki Allah onlardan düşmanlık ettiklerinizle sizin aranızda yakın bir dostluk meydana getirir. Allah güçlüdür. Allah; bağışlar, merhamet eder.');
INSERT INTO verses (sura, aya, text) VALUES (60, 8, 'Allah; sizinle din hususunda savaşmayan, sizi yurdunuzdan çıkarmayan kimselere iyilik etmenizi, onlara adaletli davranmanızı yasaklamaz. Şüphesiz Allah, adil olanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (60, 9, 'Allah; ancak sizinle din hususunda savaşan, sizi yurtlarınızdan çıkaran ve çıkarılmanıza yardım edenlerle dost olmanızı yasaklar. Kim onları dost edinirse, işte onlar zalimlerin ta kendileridir.');
INSERT INTO verses (sura, aya, text) VALUES (60, 10, 'Ey iman edenler! Mümin kadınlar hicret edip size gelirlerse, onları imtihan edin. Allah, onların imanını daha iyi bilir. Eğer onların iman ettiğini anlarsanız onları kâfirlere iade etmeyin. O kadınlar onlara helal değildir, onlar da o kadınlara helal değildir. Onlara, kadınlar için harcadıklarını verin. Mehir vererek o kadınlarla evlenmenizde size bir günah yoktur. Kâfir kadınları da nikahınızda tutmayın. Onlara sarfettiğinizi isteyin. Onlar da sarfettiklerini istesinler. Bu, Allah’ın hükmüdür. Aranızda o hüküm verir. Allah; Alîm''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (60, 11, 'Eşlerinizden kâfirlere bir şey geçer de siz de onlara galip gelirseniz, eşleri gidenlere harcadıkları kadar verin. İman ettiğiniz Allah’tan korkun.');
INSERT INTO verses (sura, aya, text) VALUES (60, 12, 'Ey Peygamber! Mümin kadınlar, Allah’a hiçbir şeyi şirk koşmamak, hırsızlık etmemek, zina etmemek, çocuklarını öldürmemek, elleri ve ayakları arasında bir iftira düzüp getirmemeleri, iyi ve doğru işlerde sana isyan etmemek üzere sana beyat etmek için geldiklerinde onların beyatını al ve onlar için Allah’tan bağışlanma dile. Şüphesiz Allah, bağışlayıcı ve çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (60, 13, 'Ey iman edenler! Allah’ın kendilerine gazap ettiği bir toplumu dost edinmeyin. Onlar, kabirdeki kâfirlerden ümitlerini kestikleri gibi ahiretten ümitlerini kesmişlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (61, 1, 'Göklerde ve yerde ne varsa Allah’ı tesbih eder. O; Azîz''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (61, 2, 'Ey iman edenler! Yapmayacağınız şeyi ne diye söylersiniz?');
INSERT INTO verses (sura, aya, text) VALUES (61, 3, 'Yapmayacağınız şeyleri söylemeniz, Allah katında büyük gazap gerektiren bir iştir.');
INSERT INTO verses (sura, aya, text) VALUES (61, 4, 'Allah, kendi yolunda kenetlenmiş bir yapı gibi saf halinde savaşanları sever.');
INSERT INTO verses (sura, aya, text) VALUES (61, 5, 'Hani Mûsâ, kendi kavmine demişti ki: “Ey kavmim! Gerçekten benim sizin için Allah''tan gönderilmiş bir elçi olduğumu bildiğiniz halde, niçin bana eziyet ediyorsunuz?” demişti. Onlar (hak yoldan) sapınca, Allah da onların kalplerini saptırdı. Allah, fasık kavme hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (61, 6, 'Hani Meryem oğlu Îsâ: "Ey İsrailoğulları! Ben, benden önce gelen Tevrat''ı doğrulayıcı ve benden sonra gelecek Ahmed adında bir rasûlü de müjdeleyen Allah’ın size (gönderdiği) bir rasûlüm." demişti. Onlara, apaçık delillerle gelince: "Bu, apaçık bir büyüdür." demişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (61, 7, 'İslam''a davet edildiği halde, Allah hakkında yalan uydurandan daha zalim kim olabilir? Allah zalim topluma hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (61, 8, 'Ağızlarıyla Allah’ın nurunu söndürmek istiyorlar. Kâfirlerin hoşuna gitmese de Allah nurunu tamamlayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (61, 9, 'Müşriklerin hoşuna gitmese de, Rasûlünü hidayet ve hak din ile bütün dinlere üstün gelsin diye gönderen O''dur.');
INSERT INTO verses (sura, aya, text) VALUES (61, 10, 'Ey iman edenler! Sizi acı bir azaptan kurtaracak bir ticaret göstereyim mi?');
INSERT INTO verses (sura, aya, text) VALUES (61, 11, 'Allah’a ve Rasûlüne iman ederseniz, Allah yolunda mallarınızla ve canlarınızla cihat ederseniz. İşte bu, eğer bilirseniz sizin için daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (61, 12, 'İşte bu takdirde O, sizin günahlarınızı bağışlar, sizi altlarından ırmaklar akan Cennetler''e, Adn Cennetleri''ndeki güzel meskenlere koyar. İşte en büyük kurtuluş budur.');
INSERT INTO verses (sura, aya, text) VALUES (61, 13, 'Ve sevdiğiniz bir diğeri daha: Allah’tan bir zafer ve yakın bir fetih, Müminleri müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (61, 14, 'Ey iman edenler! Allah''ın (dininin) yardımcıları olun. Meryem oğlu Îsâ’nın Havariler''e dediği gibi: "Allah (yolunda) yardımcılarım kimdir?" Havariler dedi ki: "Biz, Allah''ın (dininin) yardımcılarıyız!" İsrailoğulları''ndan da bir grup iman etmiş, bir grup da küfretmişti. Biz de iman edenleri düşmanlarına karşı destekledik, onlar da üstün geldiler.');
INSERT INTO verses (sura, aya, text) VALUES (62, 1, 'Göklerde ve yerde ne varsa; Melik, Kuddüs, Azîz ve Hakîm olan Allah’ı tesbih ederler.');
INSERT INTO verses (sura, aya, text) VALUES (62, 2, 'O; ümmîlere içlerinden kendilerine ayetlerini okuyan, onları arındıran, onlara kitabı ve hikmeti öğreten bir peygamber gönderendir. Hâlbuki onlar, bundan önce apaçık bir sapıklık içinde idiler.');
INSERT INTO verses (sura, aya, text) VALUES (62, 3, 'Henüz, onlara katılmamış olan diğerlerine de (göndermiştir). Azîz ve Hakîm olan O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (62, 4, 'Bu, Allah’ın dilediğine verdiği bir lütuftur. Allah, büyük lütuf sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (62, 5, 'Tevrat''la yükümlü tutulup da daha sonra taşımayanların/amel etmeyenlerin örneği, kitap yüklü eşeğe benzer. Allah’ın ayetlerini yalanlayan bir toplumun hali ne kötüdür. Allah, zalim topluma hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (62, 6, 'De ki: "Ey Yahudiler! Bütün insanlar değil de, yalnız, kendinizin Allah''ın dostları olduğunuzu iddia ediyorsanız, bunda da samimi iseniz, haydi ölümü temenni edin (bakalım)!"');
INSERT INTO verses (sura, aya, text) VALUES (62, 7, 'Ama onlar elleriyle işledikleri yüzünden onu hiç temenni edemezler. Allah, zalimleri çok iyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (62, 8, 'De ki: "Kendisinden kaçtığınız ölüm, size mutlaka ulaşacaktır. Sonra da gaybın ve görüleni bilen Allah''a döndürüleceksiniz. O da size yapmakta olduklarınızı haber verecektir."');
INSERT INTO verses (sura, aya, text) VALUES (62, 9, 'Ey iman edenler! Cuma günü namaz için çağırıldığınız zaman, alışverişi bırakıp Allah’ın zikrine koşun! Eğer bilirseniz, bu sizin için çok daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (62, 10, 'Namaz kılındığı zaman da yeryüzüne dağılın ve Allah’ın lütfunu arayın. Allah’ı çok zikredin ki, kurtuluşa erebilesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (62, 11, 'Onlar bir ticaret ve eğlence gördükleri zaman hemen dağılıp ona giderler ve seni ayakta bırakırlar. Allah katındakiler, eğlenceden ve ticaretten daha hayırlıdır. Allah, rızık verenlerin en hayırlısıdır.');
INSERT INTO verses (sura, aya, text) VALUES (63, 1, 'Münâfıklar sana geldiklerinde: "Şahitlik ederiz ki, sen muhakkak Allah''ın Rasûlü''sün" derler. Allah senin muhakkak kendi peygamberi olduğunu bilir. Bununla beraber Allah münâfıkların kesin yalancı olduklarına şahitlik eder.');
INSERT INTO verses (sura, aya, text) VALUES (63, 2, 'Onlar, yeminlerini bir kalkan edinip Allah’ın yolundan alıkoydular. Onların yaptıkları şey ne kötüdür!');
INSERT INTO verses (sura, aya, text) VALUES (63, 3, 'Bunun sebebi, onların önce iman edip sonra inkâr etmeleridir. Bu yüzden kalpleri mühürlenmiştir. Artık onlar hiç anlamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (63, 4, 'Onları gördüğün zaman cüsseleri hoşuna gider. Konuşurlarsa sözlerini dinlersin. Onlar sanki duvara dayanmış kütükler gibidir. Her çığlığı kendi aleyhlerine sanırlar. Onlar düşmandır, onlardan uzak dur. Allah onları kahretsin! Nasıl da (haktan) çevriliyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (63, 5, 'Onlara: "Gelin, Allah''ın Rasûlü sizin için mağfiret dilesin." denildiği zaman başlarını çevirirler ve sen onların büyüklük taslayarak yüz çevirdiklerini görürsün.');
INSERT INTO verses (sura, aya, text) VALUES (63, 6, 'Onlar için bağışlanma dilesen de dilemesen de birdir. Allah, onları asla bağışlamayacaktır. Allah, fasıklar topluluğuna hidayet etmez.');
INSERT INTO verses (sura, aya, text) VALUES (63, 7, 'Onlar; "Allah’ın Rasûlünün yanındaki kimselere infakta bulunmayın ki dağılıp gitsinler." diyenlerdir. Oysa göklerin ve yerin hazineleri Allah’ındır. Fakat münafıklar anlayamazlar.');
INSERT INTO verses (sura, aya, text) VALUES (63, 8, '"Medine’ye dönersek güçlü olan, zayıf olanı oradan çıkaracaktır." diyorlar. Oysa izzet Allah''ın, O''nun Rasûlünün ve Müminlerindir. Ancak münafıklar bilmezler.');
INSERT INTO verses (sura, aya, text) VALUES (63, 9, 'Ey iman edenler! Mallarınız ve çocuklarınız sizi Allah’ın zikrinden alıkoymasın. Kim bunu yaparsa, işte onlar hüsrana uğrayacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (63, 10, 'Herhangi birinize ölüm gelip de: "Rabbim! Beni yakın bir süreye kadar geciktirsen de sadaka verip salih kimselerden olsaydım." demeden önce size verdiğimiz rızıktan infak edin.');
INSERT INTO verses (sura, aya, text) VALUES (63, 11, 'Allah, eceli geldiğinde hiç kimseyi (ölümünü) ertelemez. Allah, yaptıklarınızdan hakkıyla haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (64, 1, 'Göklerde ve yerde ne varsa Allah’ı tesbih ederler. Mülk O’nundur. Hamt ta O’nadır. O’nun her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (64, 2, 'Sizi yaratan O’dur. Sizden bir kısmınız kâfir, bir kısmınız Mümindir. Allah, tüm yaptıklarınızı görendir.');
INSERT INTO verses (sura, aya, text) VALUES (64, 3, 'O; gökleri ve yeri hak ile yaratmış, sizi de en güzel sûrette şekillendirmiştir. Dönüş de O’nadır.');
INSERT INTO verses (sura, aya, text) VALUES (64, 4, 'Göklerde ve yerde olanları bilir. Gizlediklerinizi ve açığa vurduklarınızı da bilir. Allah kalplerde olanı hakkıyla bilendir.');
INSERT INTO verses (sura, aya, text) VALUES (64, 5, 'Bundan önce kâfir olanların haberi size gelmedi mi? Onlar bu sebepten amellerinin cezasını tattılar. Onlar için çok acıklı bir azap da vardır.');
INSERT INTO verses (sura, aya, text) VALUES (64, 6, 'Bu, kendilerine apaçık belgelerle peygamberler geldiği halde onların, “Bizi bir beşer mi hidayete ulaştıracak?” demeleri ve bu yüzden küfre saparak yüz çevirmeleri nedeniyledir. Allah hiç bir şeye muhtaç değildir. Allah çok zengindir, hamde layıktır.');
INSERT INTO verses (sura, aya, text) VALUES (64, 7, 'Kâfirler, tekrar dirilmeyeceklerini iddia ettiler. De ki: "Evet! Rabbime andolsun ki, tekrar diriltileceksiniz. Sonra da yaptıklarınız size haber verilecek. Bu, Allah’a çok kolaydır."');
INSERT INTO verses (sura, aya, text) VALUES (64, 8, 'Allah’a, Rasûlüne ve indirdiğimiz nura iman edin. Allah, tüm yaptıklarınızdan haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (64, 9, 'Sizi toplanma günü bir araya getirecektir. İşte o, aldanma günüdür. Kim Allah’a iman edip salih amel yaparsa; onun günahlarını örter ve alt tarafından ırmaklar aktığı Cennetler''e sokar. Orada ebedî kalacaklardır. İşte o, en büyük kurtuluştur.');
INSERT INTO verses (sura, aya, text) VALUES (64, 10, 'Kâfirler ve ayetlerimizi yalanlayanlar, işte onlar ateş ehlidir. Orada ebedîdirler. Ne kötü bir dönüş yeri.');
INSERT INTO verses (sura, aya, text) VALUES (64, 11, 'Hiçbir musibet, Allah’ın izni olmadıkça isabet etmez. Kim, Allah’a iman ederse Allah onun kalbine hidayet verir. Allah, her şeyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (64, 12, 'O halde Allah’a itaat edin, Rasûlüne itaat edin. Eğer yüz çevirseniz, elçimize düşen ancak açıkça tebliğ etmektir.');
INSERT INTO verses (sura, aya, text) VALUES (64, 13, 'Allah, O’ndan başka (hak) bir ilah yoktur. O halde Müminler yalnız Allah’a tevekkül etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (64, 14, 'Ey iman edenler! Eşlerinizden ve çocuklarınızdan size düşman olanlar vardır. Onlardan sakının. Eğer affeder, kusurlarına bakmaz ve bağışlarsanız; Allah da bağışlar ve merhamet eder.');
INSERT INTO verses (sura, aya, text) VALUES (64, 15, 'Mallarınız da, evlatlarınız da sizin için ancak bir imtihandır. Allah katında ise büyük ecir vardır.');
INSERT INTO verses (sura, aya, text) VALUES (64, 16, 'O halde, gücünüzün yettiği kadar Allah''tan sakının, dinleyin, itaat edin ve kendi iyiliğinize olarak harcayın. Kim nefsinin cimriliğinden korunursa işte onlar kurtuluşa erenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (64, 17, 'Eğer Allah’a güzel bir şekilde ödünç verirseniz, onu size kat kat arttırır ve günahlarınızı bağışlar. Allah; Şekûr''dur (bol bol verir), Halîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (64, 18, 'Gizliyi de, açığı da bilendir, Azîzdir, Hakîmdir.');
INSERT INTO verses (sura, aya, text) VALUES (65, 1, 'Ey Peygamber! Kadınları boşayacağınızda, onları iddetlerini gözeterek boşayın ve iddeti de sayın. Rabbiniz Allah’tan korkun. Apaçık bir hayasızlık yapmaları hali bir yana, onları evlerinden çıkarmayın, kendileri de çıkmasınlar. Bunlar Allah''ın sınırlarıdır. Kim Allah''ın sınırlarını aşarsa, şüphesiz kendine zulmetmiş olur. Bilemezsin; olur ki Allah, bundan sonra bir durum ortaya çıkarıverir.');
INSERT INTO verses (sura, aya, text) VALUES (65, 2, 'İddet müddetlerini doldurduklarında onları ya meşru ölçüler içerisinde (nikâhınız altında) tutun veya onlardan meşru ölçülere göre ayrılın. İçinizden adalet sahibi iki kişiyi de şahit tutun. Şahitliği de Allah için doğru yapın. İşte bununla Allah’a ve ahiret gününe iman eden kimseler için öğüt veriliyor. Kim Allah’tan sakınırsa, Allah ona bir çıkış yolu gösterir.');
INSERT INTO verses (sura, aya, text) VALUES (65, 3, 'Ve ona hiç beklemediği bir yerden rızık verir. Kim Allah’a tevekkül ederse, O kendisine yeter. Şüphesiz Allah, emrini yerine getirendir. Allah, her şey için bir süre/ölçü koymuştur.');
INSERT INTO verses (sura, aya, text) VALUES (65, 4, 'Kadınlarınızdan âdetten kesilmiş olanlar hakkında (hüküm nedir diye) tereddüt ederseniz, onların bekleme süresi üç aydır. Henüz âdet görmemiş olanlar da böyledir. Hamile kadınların bekleme süresi, yüklerini bırakıncaya kadardır. Kim Allah’tan sakınırsa, ona işinde bir kolaylık sağlar.');
INSERT INTO verses (sura, aya, text) VALUES (65, 5, 'Bu, Allah''ın size indirdiği emridir. Kim Allah''tan sakınırsa (Allah) onun kötülüklerini örter ve onun ecrini büyütür.');
INSERT INTO verses (sura, aya, text) VALUES (65, 6, 'Boşadığınız kadınları, gücünüz ölçüsünde (iddet süresince) oturduğunuz yerde oturtun. Onları sıkıntıya düşürmek için zarar vermeye kalkışmayın. Eğer hamile iseler doğuruncaya kadar nafakalarını verin. Eğer sizin için (ücretle) emzirirlerse, onlara ücretlerini verin. Aranızda maruf/bilinen bir şekilde emredin. Eğer güçlük içine girerseniz, bu durumda (çocuğu) onun (babası) için bir başkası emzirebilir.');
INSERT INTO verses (sura, aya, text) VALUES (65, 7, 'İmkânı geniş olan, imkânının genişliğine göre nafaka versin. Rızkı daralmış bulunan da Allah''ın kendisine verdiği kadarından nafaka ödesin. Allah, hiç kimseyi verdiği (imkândan) fazlasıyla yükümlü tutmaz. Allah, zorluğun ardından bir kolaylık verir.');
INSERT INTO verses (sura, aya, text) VALUES (65, 8, 'Rabbinin ve rasullerinin emrine karşı baş kaldıran nice ülke halkı vardır ki biz onları en şiddetli bir hesaba çekmiş ve onları görülmemiş bir azapla azaplandırmışızdır.');
INSERT INTO verses (sura, aya, text) VALUES (65, 9, 'Sonunda onlar yaptıklarının cezasını tatmış oldular. İşlerin sonu da hüsran oldu.');
INSERT INTO verses (sura, aya, text) VALUES (65, 10, 'Allah onlar için çok şiddetli bir azap hazırlamıştır. Ey iman etmiş akıl sahipleri –o halde- Allah’tan korkun, gerçek şu ki Allah size bir zikir indirmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (65, 11, 'İman edip salih amel işleyenleri, karanlıklardan aydınlığa çıkarmak için size Allah''ın apaçık ayetlerini okuyan bir rasul göndermiştir. Kim Allah’a iman eder ve salih amel işlerse Allah onu, altlarından ırmaklar akan, içinde ebedî kalacakları Cennetler''e sokar. Allah o kimse için gerçekten güzel bir rızık vermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (65, 12, 'Allah, yedi kat göğü ve yerden bir o kadarını yaratandır. Onun emri bunlar arasından inip durmaktadır ki, böylece Allah''ın her şeye kadir olduğunu ve her şeyi ilmiyle kuşattığını bilesiniz.');
INSERT INTO verses (sura, aya, text) VALUES (66, 1, 'Ey Peygamber! Eşlerinin rızasını aramak için ne diye Allah’ın sana helâl kıldığını (kendine) haram ediyorsun? Allah; çok bağışlayıcıdır, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (66, 2, 'Allah, yeminlerinizin (kefaretle) çözülmesini size meşru kılmıştır. Allah, sizin mevlanızdır. O; Alîm''dir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (66, 3, 'Peygamber, eşlerinden birine gizlice bir söz söylemişti. Fakat eşi, o sözü (başkasına) haber verip Allah da bunu Peygamber''e açıklayınca, Peygamber bir kısmını bildirmiş, bir kısmından da vazgeçmişti. Peygamber bunu eşine haber verince o: "Bunu sana kim haber verdi?" dedi. "Bana, Alîm ve haberdar olan (Allah) haber verdi." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (66, 4, 'Eğer sizler (iki hanımı) Allah''a tevbe ederseniz (ne iyi); çünkü kalpleriniz eğrilik gösterdi. Eğer ona karşı birbirinize arka çıkarsanız, kuşkusuz onun velisi Allah’tır. Cebrâîl, salih Müminler ve melekler de bundan sonra ona yardımcılardır.');
INSERT INTO verses (sura, aya, text) VALUES (66, 5, 'Eğer o sizi boşarsa, Rabbi ona sizden daha hayırlı, Müslüman, inanan, sebatla itaat eden, tövbe eden, ibadet eden, oruç tutan, dul ve bakire eşler verebilir.');
INSERT INTO verses (sura, aya, text) VALUES (66, 6, 'Ey iman edenler! Kendinizi ve ailelerinizi yakıtı insanlar ve taşlar olan ateşten koruyun. Onun başında gayet haşin, sert; Allah''ın kendilerine emrettiğine karşı gelmeyen ve kendilerine emredileni yapan melekler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (66, 7, 'Ey kafirler! O gün mazeret ileri sürmeyin. Ancak yaptıklarınızın karşılığını çekeceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (66, 8, 'Ey iman edenler! Allah’a içtenlikle (nasuh) tevbe edin. Umulur ki, Rabbiniz sizin kötülüklerinizi örter, peygamberi ve onunla birlikte iman edenleri utandırmayacağı günde Allah sizi, içlerinden ırmaklar akan Cennetler''e sokar. Onların nurları önlerinden ve sağlarından aydınlatır, gider. “Ey Rabbimiz! Nûrumuzu bizim için tamamla, bizi bağışla! Çünkü senin her şeye hakkıyla gücün yeter.” derler.');
INSERT INTO verses (sura, aya, text) VALUES (66, 9, 'Ey Peygamber! Kâfirlerle ve münafıklarla cihat et, onlara karşı sert davran. Onların barınma yeri Cehennem''dir. O, pek de kötü bir dönüş yeridir.');
INSERT INTO verses (sura, aya, text) VALUES (66, 10, 'Allah, kâfir olanlara Nûh''un karısı ile Lût’un karısını örnek olarak veriyor. İkisi de, salih kullarımızdan iki kulun nikahı altında idiler. Onlara (dinlerinde) ihanet etmişlerdi. Onlar da Allah’tan gelen hiçbir şeye mani olamamışlardı. O kadınlara: "Girenlerle birlikte ateşe girin!" denildi.');
INSERT INTO verses (sura, aya, text) VALUES (66, 11, 'Allah, iman edenlere de Firavun’un karısını örnek veriyor. Hani O: "Rabbim! Katındaki Cennet''te benim için bir ev yap. Beni Firavun''dan ve onun (kötü) işinden koru ve beni zalimler topluluğundan kurtar!" demişti.');
INSERT INTO verses (sura, aya, text) VALUES (66, 12, 'İffetini koruyan İmran’ın kızı Meryem''i de... Ona ruhumuzdan üflemiştik. O da Rabbinin sözlerini ve kitaplarını tasdik etmişti. O, itaatkârlardan biri idi.');
INSERT INTO verses (sura, aya, text) VALUES (67, 1, 'Bütün mülk elinde olan Allah, yüceler yücesidir ve Onun her şeye gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (67, 2, 'O, hanginizin daha güzel amel yapacağını sınamak için ölümü ve hayatı yaratandır. O; mutlak güç sahibidir, çok bağışlayandır.');
INSERT INTO verses (sura, aya, text) VALUES (67, 3, 'Gökleri, üst üste yedi kat yaratan O’dur. Rahman’ın yaratmasında bir düzensizlik göremezsin. Gözünü çevir de bak, (gökte) bir çatlak görüyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (67, 4, 'Sonra gözünü iki kere daha çevir (de bak). Göz hakir ve umudunu kesmiş bir halde sana döner.');
INSERT INTO verses (sura, aya, text) VALUES (67, 5, 'Andolsun biz, en yakın göğü kandillerle donattık. Onları Şeytanlara atılan taşlar yaptık ve (ahirette de) onlara alevli ateş azabını hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (67, 6, 'Rablerini inkâr edenlere cehennem azabı vardır. Orası ne kötü bir varış yeri!');
INSERT INTO verses (sura, aya, text) VALUES (67, 7, 'Oraya atıldıklarında o kaynayıp coşarken onun korkunç sesini işitirler.');
INSERT INTO verses (sura, aya, text) VALUES (67, 8, 'Neredeyse Cehennem öfkeden çatlayacaktır! Oraya her bir topluluk atıldıkça oranın bekçileri onlara; “Size bir uyarıcı gelmemiş miydi?” diye sorarlar.');
INSERT INTO verses (sura, aya, text) VALUES (67, 9, 'Onlar da şöyle derler: “Evet! Bize bir uyarıcı gelmişti. Fakat biz onu yalanlamış ve Allah hiçbir şey indirmemiştir. Siz ancak büyük bir sapıklık içindesiniz demiştik.”');
INSERT INTO verses (sura, aya, text) VALUES (67, 10, 'Yine derler ki: "Eğer biz dinleseydik ve aklımızı kullanmış olsaydık, cehennemlikler arasında olmazdık."');
INSERT INTO verses (sura, aya, text) VALUES (67, 11, 'İşte böylece günahlarını itiraf ederler. Artık alevli ateştekiler Allah’ın rahmetinden uzak olsun!');
INSERT INTO verses (sura, aya, text) VALUES (67, 12, 'Görmediği halde Rablerinden korkup çekinen kimseler için de elbette bir bağışlanma ve büyük bir ödül vardır.');
INSERT INTO verses (sura, aya, text) VALUES (67, 13, 'Sözünüzü ister gizleyin ve isterse onu açığa vurun. Şüphesiz O gönüllerde olanı bilir.');
INSERT INTO verses (sura, aya, text) VALUES (67, 14, 'Yaratan bilmez mi? O latiftir, her şeyden haberdar olandır.');
INSERT INTO verses (sura, aya, text) VALUES (67, 15, 'O, yeryüzünü sizin ayaklarınızın altına serendir. Haydi onun üzerinde yürüyün ve Allah’ın rızkından yiyin. Dönüş ancak O’nadır.');
INSERT INTO verses (sura, aya, text) VALUES (67, 16, 'Gökte olanın, yeryüzü sarsıldığı zaman sizi yerin dibine batırmayacağından emin mi oldunuz?');
INSERT INTO verses (sura, aya, text) VALUES (67, 17, 'Yoksa gökte olanın üzerinize taş yağdıran (fırtınalı) bir rüzgâr göndermeyeceğinden emin misiniz? Siz o takdirde benim uyarmam nasılmış bilip öğreneceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (67, 18, 'Andolsun ki onlardan öncekiler de yalanladılar. Fakat benim inkârım nasıl oldu?');
INSERT INTO verses (sura, aya, text) VALUES (67, 19, 'Üstlerinde kanatlarını açarak ve kapayarak uçan kuşları görmediler mi? Onları Rahman''dan başkası tutmuyor. Doğrusu O, her şeyi görendir.');
INSERT INTO verses (sura, aya, text) VALUES (67, 20, 'Rahman olan Allah''a karşı şu size yardım edecek askerleriniz hani kimlerdir? Kâfirler ancak boş bir gurur/aldanış içindedirler.');
INSERT INTO verses (sura, aya, text) VALUES (67, 21, 'Eğer O, rızkınızı kesecek olsa size rızık verecek olan kimdir? Bilâkis onlar azgınlık ve nefret içinde inatla direnmektedirler.');
INSERT INTO verses (sura, aya, text) VALUES (67, 22, 'O halde, yüzüstü kapanarak yürüyen mi daha çok hidâyete erendir, yoksa dosdoğru bir yol üzerinde dimdik yürüyen kimse mi?');
INSERT INTO verses (sura, aya, text) VALUES (67, 23, 'Deki: "Sizi yaratan size işitme (için kulaklar), gözler ve kalpler veren odur. Ne kadar az şükredersiniz."');
INSERT INTO verses (sura, aya, text) VALUES (67, 24, 'Deki: "O sizi yeryüzüne dağıtıp, yayandır. Yalnız onun huzuruna toplanıp götürüleceksiniz."');
INSERT INTO verses (sura, aya, text) VALUES (67, 25, '“Eğer doğru söyleyenler iseniz, bu tehdit ne zaman gerçekleşecek?” diyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (67, 26, 'De ki: “Bunun bilgisi yalnız Allah’ın katındadır. Ben sadece apaçık bir uyarıcıyım.''''');
INSERT INTO verses (sura, aya, text) VALUES (67, 27, 'Onun yaklaştığını gördükleri zaman, kâfirlerin yüzleri kötüleşir ve onlara; “İşte, isteyip durduğunuz şey budur!” denir.');
INSERT INTO verses (sura, aya, text) VALUES (67, 28, 'De ki: “Söyleyin bakalım: "Eğer Allah beni ve beraberimdekileri helâk etse yahut bize merhamet ederse kâfirleri acıklı bir azaptan kim kurtarabilir?"');
INSERT INTO verses (sura, aya, text) VALUES (67, 29, 'De ki: “O, Rahman’dır. O''na iman ettik ve O''na tevekkül ettik. Kimin apaçık bir dalalette olduğunu yakında öğreneceksiniz.''''');
INSERT INTO verses (sura, aya, text) VALUES (67, 30, 'De ki: “Söyleyin bakalım: Suyunuz çekiliverse, size kim temiz bir akar su getirir?”');
INSERT INTO verses (sura, aya, text) VALUES (68, 1, 'Nûn.[1] Kaleme ve yazdıklarına yemin olsun.');
INSERT INTO verses (sura, aya, text) VALUES (68, 2, 'Sen, Rabbinin nimeti sayesinde bir deli değilsin.');
INSERT INTO verses (sura, aya, text) VALUES (68, 3, 'Senin için tükenmez bir ecir vardır.');
INSERT INTO verses (sura, aya, text) VALUES (68, 4, 'Şüphesiz sen, çok büyük bir ahlâk üzeresin.');
INSERT INTO verses (sura, aya, text) VALUES (68, 5, 'Sen de göreceksin, onlar da görecekler.');
INSERT INTO verses (sura, aya, text) VALUES (68, 6, 'Hanginizin delirmiş olduğunu.');
INSERT INTO verses (sura, aya, text) VALUES (68, 7, 'Doğrusu Rabbin, kendi yolundan sapan kişiyi en iyi bilendir. Hidayete erenleri de en iyi bilen O''dur.');
INSERT INTO verses (sura, aya, text) VALUES (68, 8, 'Sakın yalanlayanlara itaat etme!');
INSERT INTO verses (sura, aya, text) VALUES (68, 9, 'Onlar ister ki, sen müsamaha gösterip, yumuşak davranasın da onlar da sana yumuşak davransınlar.');
INSERT INTO verses (sura, aya, text) VALUES (68, 10, 'Sakın itaat etme çokça yemin eden, aşağılık ve değersiz her kişiye.');
INSERT INTO verses (sura, aya, text) VALUES (68, 11, 'Arkadan çekiştirip, laf götürüp getirene.');
INSERT INTO verses (sura, aya, text) VALUES (68, 12, 'İyiliğe engel olan, saldırgan günahkâra.');
INSERT INTO verses (sura, aya, text) VALUES (68, 13, 'Kabaya sonra da soysuza.');
INSERT INTO verses (sura, aya, text) VALUES (68, 14, 'O mal ve oğullar sahibi oldu diye.');
INSERT INTO verses (sura, aya, text) VALUES (68, 15, 'Karşısında ayetlerimiz okunduğunda “öncekilerin masallarıdır” der.');
INSERT INTO verses (sura, aya, text) VALUES (68, 16, 'Yakında biz onun burnu üzerine damga vuracağız.');
INSERT INTO verses (sura, aya, text) VALUES (68, 17, 'Gerçek şu ki biz o bahçe sahiplerini sınadığımız gibi bunları da sınadık: Hani sabah vaktinde onu mutlaka devşireceklerine yemin etmişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (68, 18, '(İnşaallah diyerek, yeminlerinde) istisna da yapmıyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (68, 19, 'Onlar uyurken, Rabbin tarafından bir kuşatıcı (ateş) bahçeyi sarıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (68, 20, 'Bahçeler bir anda kapkara kesildi.');
INSERT INTO verses (sura, aya, text) VALUES (68, 21, 'Sabah vakti birbirlerine seslendiler.');
INSERT INTO verses (sura, aya, text) VALUES (68, 22, 'Eğer mahsulü toplayacaksanız, erkenden yola çıkın!');
INSERT INTO verses (sura, aya, text) VALUES (68, 23, 'Kendi aralarında fısıldaşarak yola koyuldular.');
INSERT INTO verses (sura, aya, text) VALUES (68, 24, '"Sakın bugün oraya bir yoksul girip yanınıza sokulmasın" diye.');
INSERT INTO verses (sura, aya, text) VALUES (68, 25, '(Yoksulları) alıkoymaya güçleri yetiyormuş gibi erkenden gittiler.');
INSERT INTO verses (sura, aya, text) VALUES (68, 26, 'Fakat bahçeyi o halde gördüklerinde; “Biz mutlaka yolumuzu şaşırmış olmalıyız!” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (68, 27, 'Bilâkis biz, mahrum bırakıldık.');
INSERT INTO verses (sura, aya, text) VALUES (68, 28, 'Onların en mu''tedil/insaflı olanı: "Ben size, keşke Allah’ı tesbih etseydiniz dememiş miydim?" dedi.');
INSERT INTO verses (sura, aya, text) VALUES (68, 29, 'Onlar; “Rabbimizi tesbih ederiz. Şüphesiz biz, zalim kimseler imişiz.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (68, 30, 'Karşılıklı olarak birbirlerini kınamaya başladılar.');
INSERT INTO verses (sura, aya, text) VALUES (68, 31, 'Şöyle dediler: “Yazıklar olsun bize! Gerçekten biz azgın kişilermişiz!”');
INSERT INTO verses (sura, aya, text) VALUES (68, 32, '“Umulur ki, Rabbimiz bize bunun yerine daha iyisini verir. Çünkü biz artık Rabbimizi arzulayanlarız.”');
INSERT INTO verses (sura, aya, text) VALUES (68, 33, 'İşte azap böyledir. Ahiret azabı ise elbette daha büyüktür. Keşke bilselerdi.');
INSERT INTO verses (sura, aya, text) VALUES (68, 34, 'Şüphesiz Allah’a karşı gelmekten sakınanlar için Rableri katında Naîm Cennetleri vardır.');
INSERT INTO verses (sura, aya, text) VALUES (68, 35, 'Biz hiç, Müslümanlarla suçluları bir tutar mıyız?');
INSERT INTO verses (sura, aya, text) VALUES (68, 36, 'Ne oluyor size? Nasıl hüküm veriyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (68, 37, 'Yoksa sizin bir kitabınız var da ondan mı okuyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (68, 38, 'Onda, “Beğendiğiniz her şey sizindir” (diye mi yazılı?)');
INSERT INTO verses (sura, aya, text) VALUES (68, 39, 'Yoksa; “Neye hükmederseniz o yerine getirilir.” diye kıyamete kadar geçerli olacak, size verilmiş yeminler/sözler mi var?');
INSERT INTO verses (sura, aya, text) VALUES (68, 40, 'Sor onlara; hangileri bunun savunuculuğunu yapacak?');
INSERT INTO verses (sura, aya, text) VALUES (68, 41, 'Yoksa onların ortakları mı var? Eğer doğru söyleyenler iseler o halde ortaklarını getirsinler.');
INSERT INTO verses (sura, aya, text) VALUES (68, 42, 'Baldırın açılacağı o günde onlar secde etmeye davet edilecekler. Fakat buna güç yetiremezler.');
INSERT INTO verses (sura, aya, text) VALUES (68, 43, 'Gözleri korku içinde, yüzlerini zillet bürümüştür. Oysa onlar, sağ salim iken secde etmeye çağrılmışlardı.');
INSERT INTO verses (sura, aya, text) VALUES (68, 44, 'Artık beni ve bu sözü yalanlayanları baş başa bırak. Biz onları bilmeyecekleri bir yerden derece derece azaba yaklaştıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (68, 45, 'Onlara mühlet veriyorum. Çünkü benim tuzağım çok sağlamdır.');
INSERT INTO verses (sura, aya, text) VALUES (68, 46, 'Yoksa sen onlardan bir ücret istiyorsun da onlar bu yüzden ağır bir borç yükü altına mı girmişlerdir?');
INSERT INTO verses (sura, aya, text) VALUES (68, 47, 'Yoksa gayb onların yanındadır da onlar mı yazıyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (68, 48, 'Rabbinin hükmünü sabırla bekle! Balık sahibi/Yunus gibi olma! Hani o, dertli bir sesle Rabbine seslenmişti.');
INSERT INTO verses (sura, aya, text) VALUES (68, 49, 'Şayet Rabbinden ona bir nimet yetişmemiş olsaydı, o mutlaka kınanmış bir hâlde ıssız bir yere atılacaktı.');
INSERT INTO verses (sura, aya, text) VALUES (68, 50, 'Ancak Rabbi onu seçti ve onu salihlerden kıldı.');
INSERT INTO verses (sura, aya, text) VALUES (68, 51, 'Kâfirler, o zikri işittikleri vakit neredeyse seni gözleriyle devireceklerdi. “O, kesinlikle bir delidir.” diyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (68, 52, 'Oysa o (Kur''an) ancak alemler için bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (69, 1, 'Gerçekleşecek olan kıyamet!');
INSERT INTO verses (sura, aya, text) VALUES (69, 2, 'Nedir o gerçekleşecek olan kıyamet?');
INSERT INTO verses (sura, aya, text) VALUES (69, 3, 'Gerçekleşecek olan kıyametin ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (69, 4, 'Semûd ve Âd kavimleri, yüreklerini hoplatacak olan büyük felaketi (kıyameti) yalanladılar.');
INSERT INTO verses (sura, aya, text) VALUES (69, 5, 'Ama Semûd, şiddetli bir çığlık/ses ile helâk edilmişti.');
INSERT INTO verses (sura, aya, text) VALUES (69, 6, 'Âd kavmine gelince, onlar da uğultulu ve dondurucu olan şiddetli bir rüzgârla helâk edildi.');
INSERT INTO verses (sura, aya, text) VALUES (69, 7, 'O rüzgârı onlara yedi gece ve sekiz gün peşpeşe musallat kıldı. O kavmi o süre içinde içleri boşalmış hurma kütükleri imişler gibi yere yıkılmış görürdün.');
INSERT INTO verses (sura, aya, text) VALUES (69, 8, 'Onlardan arta kalan bir şey görüyor musun?');
INSERT INTO verses (sura, aya, text) VALUES (69, 9, 'Firavun da, ondan öncekiler de, altı üstüne gelen kasabalar halkı da hep hata işlediler.');
INSERT INTO verses (sura, aya, text) VALUES (69, 10, 'Rablerinin elçisine isyan ettikleri için onları şiddetli bir yakalayışla yakaladı.');
INSERT INTO verses (sura, aya, text) VALUES (69, 11, 'Doğrusu sular taştığı zaman sizi gemide biz taşımıştık.');
INSERT INTO verses (sura, aya, text) VALUES (69, 12, 'Bunu sizin için bir öğüt kılalım ve anlayışlı kulaklar duysun diye.');
INSERT INTO verses (sura, aya, text) VALUES (69, 13, 'Sûr’a tek bir üfürüşle üfürüldüğü zaman.');
INSERT INTO verses (sura, aya, text) VALUES (69, 14, 'Yeryüzü ve dağlar kaldırılıp, tek çarpışla çarpılıp darmadağın edildiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (69, 15, 'İşte o gün olacak olmuştur.');
INSERT INTO verses (sura, aya, text) VALUES (69, 16, 'Gökyüzü yarılır ve artık o gün zayıf ve güçsüzdür.');
INSERT INTO verses (sura, aya, text) VALUES (69, 17, 'Melekler, onun (göğün) etrafındadır. O gün Rabbinin arşını, bunların da üstünde sekiz (melek) yüklenir.');
INSERT INTO verses (sura, aya, text) VALUES (69, 18, 'Siz o gün (hesap için) arz olunursunuz da hiçbir sırrınız gizli kalmaz.');
INSERT INTO verses (sura, aya, text) VALUES (69, 19, 'İşte o vakit, kitabı kendisine sağından verilen kimse der ki: “Gelin, kitabımı okuyun!”');
INSERT INTO verses (sura, aya, text) VALUES (69, 20, '"Ben, zaten kesinlikle böyle bir hesapla karşılaşacağımı biliyordum." der.');
INSERT INTO verses (sura, aya, text) VALUES (69, 21, 'Artık o hoşnut olduğu bir yaşayıştadır.');
INSERT INTO verses (sura, aya, text) VALUES (69, 22, 'Yüksek bir Cennet''tedir.');
INSERT INTO verses (sura, aya, text) VALUES (69, 23, 'Meyveleri çok yakındır.');
INSERT INTO verses (sura, aya, text) VALUES (69, 24, 'Yiyin, için; afiyet olsun. Bu, geçmiş günlerde yaptıklarınızın sebebiyle (size bahşedilmiştir.)');
INSERT INTO verses (sura, aya, text) VALUES (69, 25, 'Kitabı solundan verilen kimseler ise şöyle der: “Eyvah! Keşke kitabım verilmeseydi.''''');
INSERT INTO verses (sura, aya, text) VALUES (69, 26, '"Hesabımın ne olduğunu hiç bilmeseydim."');
INSERT INTO verses (sura, aya, text) VALUES (69, 27, '"Keşke (ölüm işimi) bitirmiş olsaydı!"');
INSERT INTO verses (sura, aya, text) VALUES (69, 28, '"Malım da bana bir fayda vermedi."');
INSERT INTO verses (sura, aya, text) VALUES (69, 29, '"Saltanatım yok olup gitti."');
INSERT INTO verses (sura, aya, text) VALUES (69, 30, 'Onu yakalayın da (ellerini boynuna) bağlayın.');
INSERT INTO verses (sura, aya, text) VALUES (69, 31, 'Sonra da Cehennem''e atın!');
INSERT INTO verses (sura, aya, text) VALUES (69, 32, 'Ardından da onu yetmiş arşın boyundaki bir zincire vurup sürükleyin!');
INSERT INTO verses (sura, aya, text) VALUES (69, 33, 'Çünkü o, Yüce Allah’a iman etmiyordu.');
INSERT INTO verses (sura, aya, text) VALUES (69, 34, 'Yoksulu yedirmeye teşvik etmiyordu.');
INSERT INTO verses (sura, aya, text) VALUES (69, 35, 'Bugün onun için burada bir can yoldaşı da yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (69, 36, 'İrinden başka hiçbir yiyecek de yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (69, 37, 'O yemeği günahkârlardan başkası yemez.');
INSERT INTO verses (sura, aya, text) VALUES (69, 38, 'Yemin ederim gördüklerinize.');
INSERT INTO verses (sura, aya, text) VALUES (69, 39, 'Görmediklerinize de…');
INSERT INTO verses (sura, aya, text) VALUES (69, 40, 'Şüphesiz o, çok değerli bir elçinin sözüdür.');
INSERT INTO verses (sura, aya, text) VALUES (69, 41, 'O, bir şair sözü değildir. Ne kadar da az iman ediyorsunuz!');
INSERT INTO verses (sura, aya, text) VALUES (69, 42, 'O, bir kâhin sözü de değildir. Ne de az düşünüyorsunuz!');
INSERT INTO verses (sura, aya, text) VALUES (69, 43, 'Âlemlerin Rabbi tarafından indirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (69, 44, 'Eğer Peygamber bizim adımıza bazı sözler uydurmuş olsaydı;');
INSERT INTO verses (sura, aya, text) VALUES (69, 45, 'Elbette onu sağ tarafından kıskıvrak yakalardık.');
INSERT INTO verses (sura, aya, text) VALUES (69, 46, 'Sonra da onun can damarını kopartırdık.');
INSERT INTO verses (sura, aya, text) VALUES (69, 47, 'Sizden hiç kimse de buna engel olamazdı.');
INSERT INTO verses (sura, aya, text) VALUES (69, 48, 'Şüphesiz o, takva sahipleri için bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (69, 49, 'Elbette biz, biliyoruz ki içinizden yalanlayanlar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (69, 50, 'Şüphesiz ki o kâfirler için bir pişmanlıktır.');
INSERT INTO verses (sura, aya, text) VALUES (69, 51, 'Ve şüphesiz o, kesin bir gerçektir.');
INSERT INTO verses (sura, aya, text) VALUES (69, 52, 'O halde sen, Yüce Rabbinin adını tesbih et!');
INSERT INTO verses (sura, aya, text) VALUES (70, 1, 'İsteyen kimse inecek olan azabı istedi.');
INSERT INTO verses (sura, aya, text) VALUES (70, 2, 'Kâfirler için onu (azabı) önleyecek hiç kimse yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (70, 3, '(O azap) Yüksek dereceler sahibi olan Allah tarafındandır.');
INSERT INTO verses (sura, aya, text) VALUES (70, 4, 'Melekler ve Ruh (Cebrâîl) ona süresi elli bin yıl olan bir günde yükselir.');
INSERT INTO verses (sura, aya, text) VALUES (70, 5, 'Öyleyse sen de güzel bir sabırla sabret!');
INSERT INTO verses (sura, aya, text) VALUES (70, 6, 'Doğrusu onlar, o günü çok uzak görüyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (70, 7, 'Oysa biz onu çok yakın görüyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (70, 8, 'O gün, gökyüzü erimiş yağ/maden (tortusu) gibi olur.');
INSERT INTO verses (sura, aya, text) VALUES (70, 9, 'Dağlar ise saçılmış yünler gibi olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (70, 10, 'Hiçbir yakın dost bir yakınını sormaz bile.');
INSERT INTO verses (sura, aya, text) VALUES (70, 11, 'Onlar birbirlerine gösterilirler. Günahkâr kimse, o günün azabından (kurtuluş için) oğullarını fidye olarak vermek ister.');
INSERT INTO verses (sura, aya, text) VALUES (70, 12, 'Eşini ve kardeşini.');
INSERT INTO verses (sura, aya, text) VALUES (70, 13, 'Kendisini barındıran sülalesini.');
INSERT INTO verses (sura, aya, text) VALUES (70, 14, 'Yeryüzünde olanların hepsini de. Sonra (ister ki) kendini kurtarsın.');
INSERT INTO verses (sura, aya, text) VALUES (70, 15, 'Asla! Çünkü o alevli bir ateştir.');
INSERT INTO verses (sura, aya, text) VALUES (70, 16, 'Deriyi yakıp kavurur.');
INSERT INTO verses (sura, aya, text) VALUES (70, 17, '(Hakka) Arkasını dönüp yüz çevireni çağırır.');
INSERT INTO verses (sura, aya, text) VALUES (70, 18, 'Mal toplayıp biriktireni.');
INSERT INTO verses (sura, aya, text) VALUES (70, 19, 'İnsan, çok hırslı olarak yaratılmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (70, 20, 'Kendisine fenalık dokunduğunda sızlanır, feryat eder.');
INSERT INTO verses (sura, aya, text) VALUES (70, 21, 'Ona bir iyilik dokununca da cimrilik eder.');
INSERT INTO verses (sura, aya, text) VALUES (70, 22, 'Ancak namaz kılanlar müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (70, 23, 'Onlar ki, namazlarını devamlı kılarlar.');
INSERT INTO verses (sura, aya, text) VALUES (70, 24, 'Onların mallarında belli bir hak vardır.');
INSERT INTO verses (sura, aya, text) VALUES (70, 25, 'İsteyene ve (istemekten utanıp) mahrum kalana.');
INSERT INTO verses (sura, aya, text) VALUES (70, 26, 'Onlar hesap gününü tasdik ederler.');
INSERT INTO verses (sura, aya, text) VALUES (70, 27, 'Onlar Rablerinin azabından korkarlar.');
INSERT INTO verses (sura, aya, text) VALUES (70, 28, 'Gerçekten Rablerinin azabından güvende olunmaz.');
INSERT INTO verses (sura, aya, text) VALUES (70, 29, 'Onlar, mahrem yerlerini/ırzlarını koruyan kimselerdir.');
INSERT INTO verses (sura, aya, text) VALUES (70, 30, 'Ancak eşlerine ve sahip oldukları cariyelerine karşı müstesna. Çünkü onlar (bundan dolayı) kınanmazlar.');
INSERT INTO verses (sura, aya, text) VALUES (70, 31, 'Bundan ötesini arayanlar, işte onlar haddi aşmış olanlardır.');
INSERT INTO verses (sura, aya, text) VALUES (70, 32, 'Onlar, emanetlerine ve verdikleri sözlere riayet ederler.');
INSERT INTO verses (sura, aya, text) VALUES (70, 33, 'Onlar, şahitliklerini (gerektiği gibi) yerine getirirler.');
INSERT INTO verses (sura, aya, text) VALUES (70, 34, 'Onlar namazlarını aksatmadan gereği gibi kılarlar.');
INSERT INTO verses (sura, aya, text) VALUES (70, 35, 'İşte onlar, Cennetler''de ağırlanacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (70, 36, 'O kâfirlere ne oluyor ki, sana doğru koşuyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (70, 37, 'Sağdan soldan, bölük bölük.');
INSERT INTO verses (sura, aya, text) VALUES (70, 38, 'Yoksa onların her biri Nâim Cennet''ine konulacağını mı umuyor?');
INSERT INTO verses (sura, aya, text) VALUES (70, 39, 'Asla! Biz onları bildikleri o şeyden yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (70, 40, 'Hayır, doğuların ve batıların Rabbine yemin ederim ki mutlaka biz güç yetirenleriz.');
INSERT INTO verses (sura, aya, text) VALUES (70, 41, 'Onların yerlerine kendilerinden daha hayırlılarını getirmeye. Ve bizim önümüze geçilemez.');
INSERT INTO verses (sura, aya, text) VALUES (70, 42, 'Bırak onları; kendilerine söz verilen gün gelinceye kadar dalıp oynasınlar!');
INSERT INTO verses (sura, aya, text) VALUES (70, 43, 'O gün onlar sanki dikilmiş putlara süratle gidiyorlarmış gibi kabirlerinden hızlıca çıkarlar.');
INSERT INTO verses (sura, aya, text) VALUES (70, 44, 'Gözleri yere yıkılmış, (yüzlerini) zillet bürümüştür. İşte bu, onlara söz verilen gündür!');
INSERT INTO verses (sura, aya, text) VALUES (71, 1, 'Şüphesiz biz Nûh’u kavmine; “Kendilerine elem dolu bir azap gelmeden önce kavmini uyar!” diye gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (71, 2, 'Dedi ki: "Ey kavmim! Ben, sizin için açık bir uyarıcıyım.''''');
INSERT INTO verses (sura, aya, text) VALUES (71, 3, '"Allah’a ibadet edin, ondan sakının ve bana itaat edin.''''');
INSERT INTO verses (sura, aya, text) VALUES (71, 4, 'Ta ki günahlarımızdan bir kısmını mağfiret buyursun ve sizi belli bir süreye kadar geciktirsin. Şüphesiz ki Allah’ın takdir ettiği vakit geldi mi geri bırakılmaz. Keşke bilseydiniz.');
INSERT INTO verses (sura, aya, text) VALUES (71, 5, 'Dedi ki: “Rabbim! Ben kavmimi gece gündüz davet ettim.''''');
INSERT INTO verses (sura, aya, text) VALUES (71, 6, '"Davetim onların kaçmasından başka bir şeyi artırmadı."');
INSERT INTO verses (sura, aya, text) VALUES (71, 7, 'Doğrusu ben onları bağışlaman için her davet edişimde, onlar parmaklarını kulaklarına tıkadılar, örtülerini başlarına çektiler, direttiler ve kibirlendikçe kibirlendiler.');
INSERT INTO verses (sura, aya, text) VALUES (71, 8, 'Sonra, ben onları açıktan açığa davet ettim.');
INSERT INTO verses (sura, aya, text) VALUES (71, 9, 'Sonra onları açıktan açığa da, gizli gizli de davet ettim.');
INSERT INTO verses (sura, aya, text) VALUES (71, 10, 'Onlara dedim ki: "Rabbinizden bağışlanma dileyin. Çünkü O, çok bağışlayıcıdır.''''');
INSERT INTO verses (sura, aya, text) VALUES (71, 11, 'Gökten size bol bol yağmur yağdırsın.');
INSERT INTO verses (sura, aya, text) VALUES (71, 12, 'Sizi, mallar ve oğullarla desteklesin; sizin için bahçeler var etsin, ırmaklar akıtsın.');
INSERT INTO verses (sura, aya, text) VALUES (71, 13, 'Size ne oluyor da Allah için bir vakar (saygınlık, büyüklük) ummuyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (71, 14, 'Oysa O, sizi aşamalar halinde yarattı.');
INSERT INTO verses (sura, aya, text) VALUES (71, 15, 'Allah’ın yedi göğü kat kat nasıl yarattığını görmüyor musunuz?');
INSERT INTO verses (sura, aya, text) VALUES (71, 16, 'Onların içinde Ay’a bir ışık vermiş, Güneş''i de bir kandil yapmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (71, 17, 'Allah sizi bir bitki gibi topraktan bitirmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (71, 18, 'Sonra sizi oraya geri döndürecek ve tekrar oradan çıkaracaktır.');
INSERT INTO verses (sura, aya, text) VALUES (71, 19, 'Allah sizin için yeryüzünü bir döşek kıldı.');
INSERT INTO verses (sura, aya, text) VALUES (71, 20, 'Geniş yollarında gezip dolaşmanız için.');
INSERT INTO verses (sura, aya, text) VALUES (71, 21, 'Nûh: "Rabbim! Onlar bana isyan ettiler. Malı ve evladı kendisine hüsrandan başka bir şey artırmayan kimseye uyup, tabi oldular." dedi.');
INSERT INTO verses (sura, aya, text) VALUES (71, 22, '"Ve büyük bir tuzak kurdular.''''');
INSERT INTO verses (sura, aya, text) VALUES (71, 23, 'Ve; "Sakın ilahlarınızı bırakmayın! Sakın Ved’i, Suvâ’yı, Yeğûs’u, Yeûk’u ve Nesr’i bırakmayın!" dediler.');
INSERT INTO verses (sura, aya, text) VALUES (71, 24, 'Birçoklarını saptırdılar. Sen de o zalimlerin sapıklıklarından başka bir şeylerini artırma.');
INSERT INTO verses (sura, aya, text) VALUES (71, 25, 'Günahlarından dolayı suda boğuldular ve ateşe atıldılar. Kendilerine Allah dışında bir yardımcı da bulamadılar.');
INSERT INTO verses (sura, aya, text) VALUES (71, 26, 'Nûh dedi ki: "Rabbim! Yeryüzünde dolaşan tek bir kâfir bile bırakma!''''');
INSERT INTO verses (sura, aya, text) VALUES (71, 27, '"Eğer onları bırakırsan, senin kullarını yoldan çıkarırlar ve yalnızca ahlâksız, kâfir insanlar dünyaya getirirler."');
INSERT INTO verses (sura, aya, text) VALUES (71, 28, '"Rabbim! Beni bağışla! Anamı, babamı ve iman ederek evime giren erkek ve kadın Mü''minleri de. Zalimlerin de ancak helâkini arttır."');
INSERT INTO verses (sura, aya, text) VALUES (72, 1, 'De ki: "Cinlerden bir topluluğun dinleyip şöyle dediği bana vahyedildi: Biz, hayrete düşüren Kur''an dinledik."');
INSERT INTO verses (sura, aya, text) VALUES (72, 2, 'Doğru yola hidayet ediyor, biz ona iman ettik. Rabbimize hiç kimseyi ortak tutmayacağız.');
INSERT INTO verses (sura, aya, text) VALUES (72, 3, 'Rabbimizin azameti çok yücedir. O, eş ve çocuk edinmemiştir.');
INSERT INTO verses (sura, aya, text) VALUES (72, 4, 'Doğrusu bizim beyinsiz olanımız (İblis), Allah hakkında pek aşırı yalanlar uyduruyormuş.');
INSERT INTO verses (sura, aya, text) VALUES (72, 5, '“Biz, insanların ve cinlerin Allah hakkında yalan söylemeyeceklerini zannederdik."');
INSERT INTO verses (sura, aya, text) VALUES (72, 6, 'Şu da gerçek ki, insanlardan bazı kimseler cinlerden bazı kimselere sığınırlardı da onların taşkınlıklarını arttırırlardı.');
INSERT INTO verses (sura, aya, text) VALUES (72, 7, 'Onlar da sizin zannettiğiniz gibi Allah’ın hiç kimseyi yeniden diriltemeyeceğini sanmışlardı.');
INSERT INTO verses (sura, aya, text) VALUES (72, 8, 'Doğrusu biz (cinler) göğü yokladık, fakat onu güçlü bekçilerle, alev hüzmeleriyle (yıldızlarla) doldurulmuş bulduk.');
INSERT INTO verses (sura, aya, text) VALUES (72, 9, 'Hâlbuki (daha önce) biz onun bazı kısımlarında (haber) dinlemek için oturacak yerler (bulup) oturuyorduk. Şimdi kim dinlemek istese onu gözeten bir alev yakalıyor.');
INSERT INTO verses (sura, aya, text) VALUES (72, 10, 'Gerçekten bilmiyoruz. Yeryüzünde olanlara bir kötülük mü murat edildi? Yoksa Rableri onlara bir hayır mı diledi?');
INSERT INTO verses (sura, aya, text) VALUES (72, 11, 'Şüphesiz bizim içimizde salih olanlar da vardır, salih olmayanlar da vardır. Her birimiz ayrı ayrı yollara ayrılmışız.');
INSERT INTO verses (sura, aya, text) VALUES (72, 12, 'Biz, şüphesiz Allah''ı yeryüzünde asla aciz bırakamayacağımızı, kaçmak suretiyle de onu hiçbir şekilde aciz kılamayacağımızı anladık.');
INSERT INTO verses (sura, aya, text) VALUES (72, 13, 'Doğrusu biz, o hidayeti (Kur''an''ı) işitince ona iman ettik. Kim Rabbine iman ederse, artık bir kayıptan ve haksızlığa uğramaktan korkmaz.');
INSERT INTO verses (sura, aya, text) VALUES (72, 14, 'Bizden Müslüman olanlar da var, haksızlık edenler de (sapmış olanlar da) var. Müslüman olanlar, işte onlar doğru yola yönelenlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (72, 15, 'Doğru yoldan sapanlara gelince, onlar Cehennem''e odun olacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (72, 16, 'Eğer onlar, doğru yolda istikamet üzere olsalardı, onlara bol bol su verirdik.');
INSERT INTO verses (sura, aya, text) VALUES (72, 17, 'Bununla onları imtihan ederiz. Kim de Rabbinin zikrinden yüz çevirirse, onu çok ağır bir azaba sokar.');
INSERT INTO verses (sura, aya, text) VALUES (72, 18, 'Mescitler Allah’ındır. O halde Allah ile birlikte başkasına dua/ibadet etmeyin.');
INSERT INTO verses (sura, aya, text) VALUES (72, 19, 'Nitekim Allah’ın kulu, ona dua/ibadet için ayağa kalktığında (Kur''an dinlemek için) az kalsın üzerine toplanıp doluşurlardı.');
INSERT INTO verses (sura, aya, text) VALUES (72, 20, 'De ki: “Ben ancak Rabbime dua ederim ve O''na hiçbir şeyi ortak koşmam.''''');
INSERT INTO verses (sura, aya, text) VALUES (72, 21, 'De ki: “Benim size bir zarar vermeye de, sizi doğru yola iletmeye de gücüm yetmez.''''');
INSERT INTO verses (sura, aya, text) VALUES (72, 22, 'De ki: "Beni kimse Allah''a karşı savunamaz ve ben O''ndan başka bir sığınak bulamam."');
INSERT INTO verses (sura, aya, text) VALUES (72, 23, '(Benim görevim) ancak Allah''tan (gönderilenleri) ve (tebliğ olunması emrolunanları) tebliğ etmektir. Kim Allah’a ve elçisine karşı gelirse, onun için içinde ebedî kalacağı Cehennem ateşi vardır.');
INSERT INTO verses (sura, aya, text) VALUES (72, 24, 'Sonunda, kendilerine söz verileni gördükleri zaman, kimin yardımcısının daha güçsüz ve sayısının daha az olduğunu bileceklerdir.');
INSERT INTO verses (sura, aya, text) VALUES (72, 25, 'De ki: "Size vadedilen yakın mı? Yoksa Rabbim onu uzak mı kıldı, bilmiyorum."');
INSERT INTO verses (sura, aya, text) VALUES (72, 26, 'O, gaybı bilendir. Hiç kimseye gaybını bildirmez.');
INSERT INTO verses (sura, aya, text) VALUES (72, 27, 'Ancak elçileri içinde razı olduğu başka. Çünkü O, bunun önünde ve ardında gözleri önündedir.');
INSERT INTO verses (sura, aya, text) VALUES (72, 28, 'Böylece onların (peygamberlerin), Rablerinin gönderdiklerini hakkıyla tebliğ ettiklerini bilsin. (Allah) Onların üzerinde olup bitenleri çepeçevre kuşatmış ve her şeyi bir bir saymıştır (kaydetmiştir).');
INSERT INTO verses (sura, aya, text) VALUES (73, 1, 'Ey örtüsüne bürünmüş olan!');
INSERT INTO verses (sura, aya, text) VALUES (73, 2, 'Gece kalk, ancak birazı dışında.');
INSERT INTO verses (sura, aya, text) VALUES (73, 3, 'Yarısı kadar yahut ondan biraz eksilt.');
INSERT INTO verses (sura, aya, text) VALUES (73, 4, 'Yahut buna biraz ekle. Kur’an’ı ağır ağır, tane tane oku.');
INSERT INTO verses (sura, aya, text) VALUES (73, 5, 'Doğrusu Biz, sana, taşıması ağır bir söz vahyedeceğiz.');
INSERT INTO verses (sura, aya, text) VALUES (73, 6, 'Gerçekten, gece kalkışı etki bakımından daha kuvvetli ve okuma bakımından da daha sağlamdır.');
INSERT INTO verses (sura, aya, text) VALUES (73, 7, 'Gündüz ise senin için uzun bir uğraş vardır.');
INSERT INTO verses (sura, aya, text) VALUES (73, 8, 'Rabbinin ismini zikret ve her şeyden kendini çekerek yalnızca O''na yönel.');
INSERT INTO verses (sura, aya, text) VALUES (73, 9, 'O, doğunun da batının da Rabbidir. O’ndan başka (hak) bir ilah da yoktur. Öyleyse O''nu vekil edin.');
INSERT INTO verses (sura, aya, text) VALUES (73, 10, 'Onların söylediklerine katlan ve onlardan güzel bir şekilde ayrıl.');
INSERT INTO verses (sura, aya, text) VALUES (73, 11, 'Yalanlayan o nimet sahipleri ile beni başbaşa bırak ve onlara azıcık mühlet ver.');
INSERT INTO verses (sura, aya, text) VALUES (73, 12, 'Çünkü bizim yanımızda ağır bukağılar ve yakıcı bir ateş var.');
INSERT INTO verses (sura, aya, text) VALUES (73, 13, 'Boğazı tıkayan bir yiyecek ve acı veren bir azap vardır!');
INSERT INTO verses (sura, aya, text) VALUES (73, 14, 'O günde yer ve dağlar sarsılır, dağlar da yığılarak akıp dağılan kum gibi olur.');
INSERT INTO verses (sura, aya, text) VALUES (73, 15, 'Biz, Firavun’a bir rasûl gönderdiğimiz gibi size de üzerinize şahit olacak bir rasûl gönderdik.');
INSERT INTO verses (sura, aya, text) VALUES (73, 16, 'Firavun, rasûle karşı çıktı. Biz de onu müthiş bir şekilde yakaladık.');
INSERT INTO verses (sura, aya, text) VALUES (73, 17, 'Eğer küfredecek olursanız, çocukların saçlarını ağartan bir günde, siz kendinizi nasıl koruyacaksınız?');
INSERT INTO verses (sura, aya, text) VALUES (73, 18, 'O günün dehşetiyle gökyüzü yarılacak, O''nun vaadi mutlaka yerine gelecektir.');
INSERT INTO verses (sura, aya, text) VALUES (73, 19, 'Şüphesiz bunlar bir öğüttür. Kim dilerse Rabbine ulaştıran bir yol tutar.');
INSERT INTO verses (sura, aya, text) VALUES (73, 20, 'Şüphesiz Rabbin biliyor ki, gerçekten sen gecenin üçte ikisinden daha azı ve (bazen) yarısı ve (bazen de) üçte biri kadar (namaz için) kalkıyorsun. Beraberinde bulunanlardan (ashâbından) bir topluluk da (böyle yapıyor). Geceyi ve gündüzü Allah takdir eder. O sizin, bunu sayamayacağınızı (buna güç yetiremeyeceğinizi) bildiği için sizi bağışladı. Öyleyse Kur’an’dan (bildiğiniz) kolayınıza geleni okuyun. İçinizden hasta olacakları, bir kısmınızın yeryüzünde dolaşıp Allah’ın rızkını arayacağını, diğerlerinin Allah yolunda savaşacağını da bilmektedir. Öyleyse ondan kolayınıza geleni okuyun, namazı ikame edin, zekâtı verin ve Allah’a güzel bir borç (ile borç) verin. Kendiniz için hayır olarak (dünyada) ne sunarsanız; onu Allah katında daha iyi, daha büyük bir mükâfat ile (karşılık verilmiş) bulursunuz. Allah’tan bağışlanma dileyin. Şüphesiz Allah; çok bağışlayıcıdır, çok merhametlidir.');
INSERT INTO verses (sura, aya, text) VALUES (74, 1, 'Ey elbisesine bürünen!');
INSERT INTO verses (sura, aya, text) VALUES (74, 2, 'Kalk ve uyar!');
INSERT INTO verses (sura, aya, text) VALUES (74, 3, 'Rabbini tekbir et (yücelt).');
INSERT INTO verses (sura, aya, text) VALUES (74, 4, 'Elbiseni de temizle/Rabbini tekbir et (yücelt).');
INSERT INTO verses (sura, aya, text) VALUES (74, 5, 'Pisliklerden de uzak dur!');
INSERT INTO verses (sura, aya, text) VALUES (74, 6, '(Yaptığını) çok görerek minnet etme!');
INSERT INTO verses (sura, aya, text) VALUES (74, 7, 'Rabbin için sabret!');
INSERT INTO verses (sura, aya, text) VALUES (74, 8, 'Sûr’a üflendiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (74, 9, 'İşte o gün, çok zor bir gündür.');
INSERT INTO verses (sura, aya, text) VALUES (74, 10, 'Kâfirler için hiç kolay değildir.');
INSERT INTO verses (sura, aya, text) VALUES (74, 11, 'Beni, yarattığım kişiyle baş başa bırak.');
INSERT INTO verses (sura, aya, text) VALUES (74, 12, 'Ona ardı arkası kesilmeyen bir servet verdim.');
INSERT INTO verses (sura, aya, text) VALUES (74, 13, 'Gözlerinin önünde duran oğullar verdim.');
INSERT INTO verses (sura, aya, text) VALUES (74, 14, 'Kendisi için (dünya nimetlerini) yaydıkça yaydım.');
INSERT INTO verses (sura, aya, text) VALUES (74, 15, 'Daha da artırmamı umuyor.');
INSERT INTO verses (sura, aya, text) VALUES (74, 16, 'Asla! Çünkü o ayetlerimize karşı çok inatçıdır.');
INSERT INTO verses (sura, aya, text) VALUES (74, 17, 'Onu sarp bir yokuşa zorlayıp süreceğim.');
INSERT INTO verses (sura, aya, text) VALUES (74, 18, 'Çünkü o; düşündü, ölçtü, biçti.');
INSERT INTO verses (sura, aya, text) VALUES (74, 19, 'Kahrolası nasıl da ölçtü, biçti!');
INSERT INTO verses (sura, aya, text) VALUES (74, 20, 'Sonra (yine o) kahrolası, nasıl (da) ölçtü, biçti!');
INSERT INTO verses (sura, aya, text) VALUES (74, 21, 'Sonra şöyle bir baktı.');
INSERT INTO verses (sura, aya, text) VALUES (74, 22, 'Sonra da kaşlarını çatıp, surat astı.');
INSERT INTO verses (sura, aya, text) VALUES (74, 23, 'Sonra da arkasını dönüp büyüklendi.');
INSERT INTO verses (sura, aya, text) VALUES (74, 24, 'Ve şöyle dedi: Bu sadece öğretilegelen bir sihirdir.');
INSERT INTO verses (sura, aya, text) VALUES (74, 25, '"Bu, insan sözünden başka bir şey değildir.''''');
INSERT INTO verses (sura, aya, text) VALUES (74, 26, 'Ben onu Sekar’a (Cehennem''e) sokacağım.');
INSERT INTO verses (sura, aya, text) VALUES (74, 27, 'Sekar’ın ne olduğunu bilir misin sen?');
INSERT INTO verses (sura, aya, text) VALUES (74, 28, 'O geride bir şey koymaz ve bırakmaz.');
INSERT INTO verses (sura, aya, text) VALUES (74, 29, 'İnsan derisini yakıp kavurur.');
INSERT INTO verses (sura, aya, text) VALUES (74, 30, 'Üzerinde on dokuz (melek) vardır.');
INSERT INTO verses (sura, aya, text) VALUES (74, 31, 'Biz; kendilerine kitap verilenler kesin bir bilgiyle inansın, iman edenlerin imanları artsın, kendilerine kitap verilenler ile iman edenler şüpheye kapılmasın, kalplerinde bir hastalık olanlar ile küfre sapanlar da, “Allah, bu örnekle (on dokuz sayısı ile) neyi anlatmak istedi?” desin diye o ateşin koruyucularını meleklerden başkasını kılmadık ve onların sayısını da kâfirler için yalnızca bir fitne/imtihan yaptık. Allah; dilediğini işte böyle saptırır, dilediğine de hidayet eder. Rabbinin ordularını kendisinden başkası bilemez. Bu, insanlar için bir öğütten başka bir şey değildir.');
INSERT INTO verses (sura, aya, text) VALUES (74, 32, 'Hayır! And olsun Ay’a!');
INSERT INTO verses (sura, aya, text) VALUES (74, 33, 'Dönüp gittiği zaman geceye,');
INSERT INTO verses (sura, aya, text) VALUES (74, 34, 'Ve ağarmakta olan sabaha,');
INSERT INTO verses (sura, aya, text) VALUES (74, 35, 'Şüphesiz o (Sekar), büyük (musibetlerden) biridir.');
INSERT INTO verses (sura, aya, text) VALUES (74, 36, 'İnsanlar için bir uyarıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (74, 37, 'Sizden ileri gitmek ya da geri kalmak isteyen kimseler için.');
INSERT INTO verses (sura, aya, text) VALUES (74, 38, 'Her nefis kazandığına karşılık bir rehindir.');
INSERT INTO verses (sura, aya, text) VALUES (74, 39, 'Ancak Ashab-ı Yemin (sağ ehli) başkadır.');
INSERT INTO verses (sura, aya, text) VALUES (74, 40, '(Onlar) cennetlerdedirler. Birbirlerine sorarlar.');
INSERT INTO verses (sura, aya, text) VALUES (74, 41, 'Suçlulardan.');
INSERT INTO verses (sura, aya, text) VALUES (74, 42, '“Sizi Sekara/Cehennem''e sokan nedir?''''');
INSERT INTO verses (sura, aya, text) VALUES (74, 43, 'Onlar derler ki; "Biz namaz kılan kimseler değildik."');
INSERT INTO verses (sura, aya, text) VALUES (74, 44, '“Yoksulları da doyurmazdık.''''');
INSERT INTO verses (sura, aya, text) VALUES (74, 45, '"(Batıla) Dalanlarla beraber biz de dalıp gitmiştik."');
INSERT INTO verses (sura, aya, text) VALUES (74, 46, '“Hesap gününü de yalanlıyorduk.''''');
INSERT INTO verses (sura, aya, text) VALUES (74, 47, '“Nihayet ölüm bize gelip çatıncaya dek.''''');
INSERT INTO verses (sura, aya, text) VALUES (74, 48, 'Artık şefaat edenlerin şefaatleri onlara yarar sağlamaz.');
INSERT INTO verses (sura, aya, text) VALUES (74, 49, 'Öyleyse onlara ne oluyor da öğütten yüz çeviriyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (74, 50, 'Onlar adeta ürkütülmüş yaban eşekleri gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (74, 51, 'Aslandan ürküp, kaçan.');
INSERT INTO verses (sura, aya, text) VALUES (74, 52, 'Hayır; her biri önüne açılıvermiş sahifeler verilmesini ister.');
INSERT INTO verses (sura, aya, text) VALUES (74, 53, 'Asla! Doğrusu onlar ahiretten korkmuyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (74, 54, 'Hayır! Şüphesiz o (Kur''an) ancak bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (74, 55, 'Artık dileyen kimse ondan öğüt alır.');
INSERT INTO verses (sura, aya, text) VALUES (74, 56, 'Allah dilemedikçe onlar öğüt almazlar. Kendisinden korkulmaya layık olan da, bağışlayıcı olan da O’dur.');
INSERT INTO verses (sura, aya, text) VALUES (75, 1, 'Kıyamet gününe yemin ederim.');
INSERT INTO verses (sura, aya, text) VALUES (75, 2, 'Sürekli kendini kınayan nefse yemin ederim.');
INSERT INTO verses (sura, aya, text) VALUES (75, 3, 'İnsan biz onun kemiklerini asla toplayıp, bir araya getirmeyeceğimizi mi zanneder?');
INSERT INTO verses (sura, aya, text) VALUES (75, 4, 'Aksine onun parmak uçlarını bile yaratıp düzenlemeye gücümüz yeter.');
INSERT INTO verses (sura, aya, text) VALUES (75, 5, 'Ancak insan, önündeki (ahireti inkâr ederek) fücurla (günah işlemek) ister.');
INSERT INTO verses (sura, aya, text) VALUES (75, 6, '"Kıyamet günü ne zaman?" diye sorar.');
INSERT INTO verses (sura, aya, text) VALUES (75, 7, 'Göz dehşetle kamaştığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (75, 8, 'Ay tutulduğu zaman.');
INSERT INTO verses (sura, aya, text) VALUES (75, 9, 'Güneş ve Ay bir araya getirildiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (75, 10, '(O gün) insan: "Bugün kaçacak yer nerede?" der.');
INSERT INTO verses (sura, aya, text) VALUES (75, 11, 'Hayır! Hiçbir sığınacak yer yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (75, 12, 'O gün varıp durulacak yer Rabbinin huzurudur.');
INSERT INTO verses (sura, aya, text) VALUES (75, 13, 'O günde insana önden yolladığı şeyler ile geride bıraktığı şeyler haber verilir.');
INSERT INTO verses (sura, aya, text) VALUES (75, 14, 'Doğrusu insan, kendi aleyhine bir şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (75, 15, 'İsterse bütün mazeretlerini ortaya döksün.');
INSERT INTO verses (sura, aya, text) VALUES (75, 16, '(Ey Muhammed!) Onu (vahyi) çarçabuk almak için dilini kımıldatma.');
INSERT INTO verses (sura, aya, text) VALUES (75, 17, 'Şüphesiz onu toplamak (senin kalbine yerleştirmek) ve onu okutmak bize aittir.');
INSERT INTO verses (sura, aya, text) VALUES (75, 18, 'O halde, biz onu okuduğumuz zaman onun okunuşuna uy.');
INSERT INTO verses (sura, aya, text) VALUES (75, 19, 'Sonra onu açıklamak yine bize aittir.');
INSERT INTO verses (sura, aya, text) VALUES (75, 20, 'Hayır! Siz, acil olanı/dünyayı seviyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (75, 21, 'Ahireti ise bırakıyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (75, 22, 'Yüzler vardır ki, o gün ışıl ışıl parıldayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (75, 23, 'Rabbine bakar. (O''nu göreceklerdir)');
INSERT INTO verses (sura, aya, text) VALUES (75, 24, 'O gün birtakım yüzler de asıktır.');
INSERT INTO verses (sura, aya, text) VALUES (75, 25, 'Bel kemiklerini kıran bir felakete uğratılacaklarını anlarlar.');
INSERT INTO verses (sura, aya, text) VALUES (75, 26, 'Hayır! Can, köprücük kemiğine dayandığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (75, 27, 'Hayır! Can boğaza dayandığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (75, 28, 'Anlar ki, bu bir ayrılış.');
INSERT INTO verses (sura, aya, text) VALUES (75, 29, 'Ayakları birbirine dolaştığında.');
INSERT INTO verses (sura, aya, text) VALUES (75, 30, 'O gün varacakları yer, yalnız Rabbinin huzurudur.');
INSERT INTO verses (sura, aya, text) VALUES (75, 31, 'Tasdik etmemiş ve namaz kılmamıştı.');
INSERT INTO verses (sura, aya, text) VALUES (75, 32, 'Fakat yalanlamış ve yüz çevirmiş.');
INSERT INTO verses (sura, aya, text) VALUES (75, 33, 'Sonra da çalım satarak ailesine gitmişti.');
INSERT INTO verses (sura, aya, text) VALUES (75, 34, '“Bu azap sana layıktır, layık!"');
INSERT INTO verses (sura, aya, text) VALUES (75, 35, '"Evet! Layıktır sana, layık!” denilecek.');
INSERT INTO verses (sura, aya, text) VALUES (75, 36, 'Yoksa insan, başı boş bırakılacağını mı sanıyor?');
INSERT INTO verses (sura, aya, text) VALUES (75, 37, 'O akıtılan meniden bir nutfe değil miydi?');
INSERT INTO verses (sura, aya, text) VALUES (75, 38, 'Sonra alaka olmuş, Allah onu yaratmış ve düzenlemişti.');
INSERT INTO verses (sura, aya, text) VALUES (75, 39, 'Ondan da iki eşi, erkek ve dişiyi var etmişti.');
INSERT INTO verses (sura, aya, text) VALUES (75, 40, 'Bunu yapanın ölüleri diriltmeye gücü yetmez mi?');
INSERT INTO verses (sura, aya, text) VALUES (76, 1, 'İnsan (henüz) anılır bir şey değilken (yaratılmamışken) üzerinden uzunca bir zaman geçti.');
INSERT INTO verses (sura, aya, text) VALUES (76, 2, 'Biz, insanı katışık nutfeden yarattık. Onu imtihan edelim diye kendisini işitir ve görür kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (76, 3, 'Biz ona yolu gösterdik. İster şükreder, ister kâfir olur.');
INSERT INTO verses (sura, aya, text) VALUES (76, 4, 'Elbette biz; kâfirlere zincirler, halkalar ve alevli Cehennem hazırladık.');
INSERT INTO verses (sura, aya, text) VALUES (76, 5, 'İyiler ise katkısı kâfur olan içecekler dolu bir kadehten içerler.');
INSERT INTO verses (sura, aya, text) VALUES (76, 6, '(O) Allah’ın kullarının kendisinden içtikleri ve diledikleri gibi akıttıkları bir pınardır.');
INSERT INTO verses (sura, aya, text) VALUES (76, 7, 'Onlar adakları yerine getirirler ve kötülüğü yaygın bir günden korkarlar.');
INSERT INTO verses (sura, aya, text) VALUES (76, 8, 'Yemeğe olan sevgilerine rağmen yoksula, yetime ve esire yemek yedirirler.');
INSERT INTO verses (sura, aya, text) VALUES (76, 9, 'Biz, sizi sadece Allah yüzü/rızası için doyuruyoruz. Sizden bir karşılık ve teşekkür beklemiyoruz.');
INSERT INTO verses (sura, aya, text) VALUES (76, 10, '"Doğrusu biz, suratların asılacağı korkunç şiddetli bir günde Rabbimizden korkarız."');
INSERT INTO verses (sura, aya, text) VALUES (76, 11, 'Bundan dolayı Allah da bugünün şerrinden onları korur ve onlara bir güzellik, bir sevinç verir.');
INSERT INTO verses (sura, aya, text) VALUES (76, 12, 'Sabretmeleri sebebi ile de onları cennetle ve ipek ile mükâfatlandırır.');
INSERT INTO verses (sura, aya, text) VALUES (76, 13, 'Orada koltuklara kurulurlar. Ne yakıcı bir Güneş, ne de dondurucu bir soğuk görürler.');
INSERT INTO verses (sura, aya, text) VALUES (76, 14, 'Gölgeleri kendilerine yakındır. Devşirilecek meyveleri de eğdirildikçe eğdirilmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (76, 15, 'Çevrelerinde ise gümüş kaplar ve billur kâseler dolaştırılır.');
INSERT INTO verses (sura, aya, text) VALUES (76, 16, 'Gümüşten billur kâseler... (Hizmetçiler) Onların ihtiyaçlarına göre ölçülerini belirlemiştir.');
INSERT INTO verses (sura, aya, text) VALUES (76, 17, 'Onlara orada karışımı zencefil olan bir kadehten içirilir.');
INSERT INTO verses (sura, aya, text) VALUES (76, 18, 'Orada Selsebil adı verilen bir pınar da vardır.');
INSERT INTO verses (sura, aya, text) VALUES (76, 19, 'Yanlarında ölümsüz gençler dolaşır; onları gördüğünde saçılmış birer inci sanırsın.');
INSERT INTO verses (sura, aya, text) VALUES (76, 20, 'Nereye bakarsan orada pek çok nimetler ve büyük bir saltanat görürsün.');
INSERT INTO verses (sura, aya, text) VALUES (76, 21, 'Üzerlerinde yeşil ipekli ve parlak atlastan elbiseler vardır. Gümüş bilezikler takınmışlardır. Rableri onlara tertemiz bir içecek içirmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (76, 22, 'İşte bu, sizin için bir ödüldür. Sizin çalışmanızın karşılığıdır.');
INSERT INTO verses (sura, aya, text) VALUES (76, 23, 'Şüphe yok ki, Kur’an’ı sana elbette biz indirdik, biz!');
INSERT INTO verses (sura, aya, text) VALUES (76, 24, 'O halde Rabbinin hükmüne sabret ve onlardan hiçbir günahkâra ve kâfire de itaat etme!');
INSERT INTO verses (sura, aya, text) VALUES (76, 25, 'Sabah, akşam Rabbinin adını zikret.');
INSERT INTO verses (sura, aya, text) VALUES (76, 26, 'Geceleri de ona secde et ve geceleyin uzun (bir süre) onu tesbih et.');
INSERT INTO verses (sura, aya, text) VALUES (76, 27, 'Onlar; acele olanı (dünyayı) istiyorlar, ağır (çetin) günü arkalarına bırakıyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (76, 28, 'Onları biz yarattık ve yaratılışlarını iyiden iyiye pekiştirdik. Dilediğimiz zaman da onları benzerleriyle değiştiririz.');
INSERT INTO verses (sura, aya, text) VALUES (76, 29, 'Şüphesiz bu bir öğüttür. Dileyen kimse Rabbine giden yolu tutar.');
INSERT INTO verses (sura, aya, text) VALUES (76, 30, 'Allah dilemedikçe siz dileyemezsiniz. Şüphesiz Allah; her şeyi bilendir, Hakîm''dir.');
INSERT INTO verses (sura, aya, text) VALUES (76, 31, 'Dilediğini rahmetine sokar. Zalimlere de acı bir azap hazırlamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (77, 1, 'Yemin olsun, ardı ardına gönderilenlere.');
INSERT INTO verses (sura, aya, text) VALUES (77, 2, 'Şiddetle esip savuranlara.');
INSERT INTO verses (sura, aya, text) VALUES (77, 3, 'Yaydıkça yayanlara.');
INSERT INTO verses (sura, aya, text) VALUES (77, 4, 'Ayırdıkça ayıranlara.');
INSERT INTO verses (sura, aya, text) VALUES (77, 5, 'Zikri getirip, bırakanlara.');
INSERT INTO verses (sura, aya, text) VALUES (77, 6, 'Gerek özür için olsun, gerek uyarı için.');
INSERT INTO verses (sura, aya, text) VALUES (77, 7, 'Şüphe yok ki, size vaadedilen mutlaka gerçekleşecektir.');
INSERT INTO verses (sura, aya, text) VALUES (77, 8, 'Yıldızların ışığı söndüğü zaman.');
INSERT INTO verses (sura, aya, text) VALUES (77, 9, 'Gök yarıldığında.');
INSERT INTO verses (sura, aya, text) VALUES (77, 10, 'Dağlar parçamparça olup savrulduğunda.');
INSERT INTO verses (sura, aya, text) VALUES (77, 11, 'Peygamberlere ümmetleri hakkında şahitlik vakitleri bildirildiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (77, 12, 'Bu, hangi güne ertelenmiş?');
INSERT INTO verses (sura, aya, text) VALUES (77, 13, 'Ayrım (hüküm) gününe (ertelenmiştir).');
INSERT INTO verses (sura, aya, text) VALUES (77, 14, 'Hüküm gününün ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (77, 15, 'O gün vay yalanlayanların haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 16, 'Biz, öncekileri helak etmedik mi?');
INSERT INTO verses (sura, aya, text) VALUES (77, 17, 'Sonra arkadan gelenleri de onların arkasına takacağız.');
INSERT INTO verses (sura, aya, text) VALUES (77, 18, 'Biz, günahkârlara işte böyle yaparız.');
INSERT INTO verses (sura, aya, text) VALUES (77, 19, 'O gün vay yalanlayanların haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 20, 'Sizi basit bir sudan yaratmadık mı?');
INSERT INTO verses (sura, aya, text) VALUES (77, 21, 'Ve onu sağlam bir yere yerleştirmedik mi?');
INSERT INTO verses (sura, aya, text) VALUES (77, 22, 'Belli bir süreye kadar.');
INSERT INTO verses (sura, aya, text) VALUES (77, 23, 'Buna gücümüz yeter. Ne güzel güç yetirenleriz.');
INSERT INTO verses (sura, aya, text) VALUES (77, 24, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 25, 'Biz, yeryüzünü bir toplanma yeri kılmadık mı?');
INSERT INTO verses (sura, aya, text) VALUES (77, 26, 'Diri olanları da, ölü olanları da.');
INSERT INTO verses (sura, aya, text) VALUES (77, 27, 'Orada yüksek dağlar yaratıp size tatlı su içirmedik mi?');
INSERT INTO verses (sura, aya, text) VALUES (77, 28, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 29, 'Yalanlamış olduğunuza (azaba) doğru yürüyün bakalım!');
INSERT INTO verses (sura, aya, text) VALUES (77, 30, 'Üç kollu (ateşin) gölgesine doğru yürüyün!');
INSERT INTO verses (sura, aya, text) VALUES (77, 31, 'Ne gölgelendirir, ne alevden korur.');
INSERT INTO verses (sura, aya, text) VALUES (77, 32, 'O, her biri saraylar gibi olan kıvılcımlar saçar.');
INSERT INTO verses (sura, aya, text) VALUES (77, 33, 'Her biri sarı develer gibidir.');
INSERT INTO verses (sura, aya, text) VALUES (77, 34, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 35, 'Bu, onların konuşamayacakları bir gündür.');
INSERT INTO verses (sura, aya, text) VALUES (77, 36, 'Onların özür dilemelerine dahi izin verilmez.');
INSERT INTO verses (sura, aya, text) VALUES (77, 37, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 38, 'Bu, ayırma (hüküm) günüdür. Sizi ve evvelkileri bir araya toplarız.');
INSERT INTO verses (sura, aya, text) VALUES (77, 39, 'Eğer bir tuzağınız varsa, haydi bana karşı tuzak kurun!');
INSERT INTO verses (sura, aya, text) VALUES (77, 40, 'O gün, yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 41, 'Şüphesiz ki takva sahipleri, gölgelerde pınar başlarındadır.');
INSERT INTO verses (sura, aya, text) VALUES (77, 42, 'Ve canlarının çekip-arzu ettiği meyveler (arasındadırlar).');
INSERT INTO verses (sura, aya, text) VALUES (77, 43, 'Yaptığınız ameller sebebi ile afiyetle yiyin, için.');
INSERT INTO verses (sura, aya, text) VALUES (77, 44, 'Biz, iyilik yapanları işte böyle ödüllendiririz.');
INSERT INTO verses (sura, aya, text) VALUES (77, 45, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 46, 'Yiyin ve biraz yararlanın; muhakkak ki siz günahkârlarsınız.');
INSERT INTO verses (sura, aya, text) VALUES (77, 47, 'O gün, yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 48, 'Onlara; “Rükû edin!” denildiği zaman rükû etmezlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (77, 49, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (77, 50, 'Onlar bundan (Kur''an''dan) sonra artık hangi söze iman edecekler?');
INSERT INTO verses (sura, aya, text) VALUES (78, 1, 'Birbirlerine neyi soruyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (78, 2, 'O büyük haberi mi?');
INSERT INTO verses (sura, aya, text) VALUES (78, 3, 'Ki onlar, onda ihtilafa düşmüşlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (78, 4, 'Hayır! Onlar yakında öğrenecekler.');
INSERT INTO verses (sura, aya, text) VALUES (78, 5, 'Sonra tekrar hayır! Yakında öğrenecekler.');
INSERT INTO verses (sura, aya, text) VALUES (78, 6, 'Yeri bir döşek kılmadık mı?');
INSERT INTO verses (sura, aya, text) VALUES (78, 7, 'Dağları da birer kazık kılmadık mı?');
INSERT INTO verses (sura, aya, text) VALUES (78, 8, 'Sizleri (erkekli dişili) eşler halinde yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (78, 9, 'Uykunuzu bir dinlenme (sebebi) kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (78, 10, 'Geceyi örtü bir kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (78, 11, 'Gündüzü de geçim zamanı kıldık.');
INSERT INTO verses (sura, aya, text) VALUES (78, 12, 'Üstünüze yedi sağlam gök bina ettik.');
INSERT INTO verses (sura, aya, text) VALUES (78, 13, 'Alev alev yanan aydınlatıcı ve ısıtıcı bir kandil yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (78, 14, 'Ve yağmur yüklü bulutlardan şarıl şarıl akan bir su indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (78, 15, 'Onunla taneler ve bitkiler çıkaralım diye.');
INSERT INTO verses (sura, aya, text) VALUES (78, 16, 'Ve birbirine girmiş sarmaş dolaş bahçeler yetiştirelim diye.');
INSERT INTO verses (sura, aya, text) VALUES (78, 17, 'Şüphe yok ki hüküm verip, ayırt etme günü belirlenmiş bir vakittir.');
INSERT INTO verses (sura, aya, text) VALUES (78, 18, 'Sur’a üflendiği gün bölük bölük geleceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (78, 19, 'Ve gökyüzü açılarak orada pek çok kapılar oluşur.');
INSERT INTO verses (sura, aya, text) VALUES (78, 20, 'Dağlar yürütülüp bir seraba dönüşür.');
INSERT INTO verses (sura, aya, text) VALUES (78, 21, 'Şüphesiz Cehennem de bir gözetleme yeridir.');
INSERT INTO verses (sura, aya, text) VALUES (78, 22, 'Azgınların varacağı sığınaktır.');
INSERT INTO verses (sura, aya, text) VALUES (78, 23, 'Orada çağlar boyu kalacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (78, 24, 'Orada ne bir serinlik, ne de bir içecek tadacaklar.');
INSERT INTO verses (sura, aya, text) VALUES (78, 25, 'Yalnızca kaynar su ve irinden içecekler.');
INSERT INTO verses (sura, aya, text) VALUES (78, 26, '(Dünyada yaptıklarına karşılık) Uygun bir ceza olarak.');
INSERT INTO verses (sura, aya, text) VALUES (78, 27, 'Çünkü onlar hesaba çekilmeyi ummuyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (78, 28, 'Ayetlerimizi de alabildiğine yalanlamışlardı.');
INSERT INTO verses (sura, aya, text) VALUES (78, 29, 'Biz ise, her şeyi bir kitapta (Levh-i Mahfuz’da) tamamiyle sayıp tespit ettik.');
INSERT INTO verses (sura, aya, text) VALUES (78, 30, 'Kâfirlere şöyle denilir: “Şimdi tadın. Artık bundan sonra yalnızca azabınızı artıracağız.”');
INSERT INTO verses (sura, aya, text) VALUES (78, 31, 'Şüphesiz takva sahipleri için bir kurtuluş vardır.');
INSERT INTO verses (sura, aya, text) VALUES (78, 32, 'Bahçeler ve üzümler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (78, 33, 'Göğüsleri olgun yaşıt kızlar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (78, 34, 'Dolu dolu kadehler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (78, 35, 'Orada ne bir boş söz işitirler, ne de bir yalan.');
INSERT INTO verses (sura, aya, text) VALUES (78, 36, 'Rabbinden bir karşılık olmak üzere yeterli bir bağıştır bu.');
INSERT INTO verses (sura, aya, text) VALUES (78, 37, 'Bunlar; göklerin, yerin ve ikisi arasında bulunanların Rahman olan Rabbindendir. Ona hitap etmeye güç yetiremezler.');
INSERT INTO verses (sura, aya, text) VALUES (78, 38, 'Ruh''un ve meleklerin sıra sıra duracakları gün; Rahman''ın kendilerine izin verdikleri dışındakiler konuşamazlar. Onlar da doğruyu söylerler.');
INSERT INTO verses (sura, aya, text) VALUES (78, 39, 'İşte bu o hak gündür. O halde dileyen Rabbine bir dönüş yolu edinsin.');
INSERT INTO verses (sura, aya, text) VALUES (78, 40, 'Biz, sizi çok yakın bir azapla uyardık. Herkes o gün, kendi elleriyle ne yaptığına bir bakar ve kâfir olanlar da: "Keşke toprak olsaydım!" der.');
INSERT INTO verses (sura, aya, text) VALUES (79, 1, 'Andolsun şiddetle çekip çıkaranlara,');
INSERT INTO verses (sura, aya, text) VALUES (79, 2, 'Andolsun kolaylıkla alanlara,');
INSERT INTO verses (sura, aya, text) VALUES (79, 3, 'Andolsun yüzüp yüzüp gidenlere,');
INSERT INTO verses (sura, aya, text) VALUES (79, 4, 'Yarıştıkça yarışanlara,');
INSERT INTO verses (sura, aya, text) VALUES (79, 5, 'Her bir işi yürütmekle görevli olanlara,');
INSERT INTO verses (sura, aya, text) VALUES (79, 6, 'O gün (birinci üflemeyle) sarsılacak olan sarsılır.');
INSERT INTO verses (sura, aya, text) VALUES (79, 7, 'Bir diğeri de onu izler.');
INSERT INTO verses (sura, aya, text) VALUES (79, 8, 'O gün birtakım kalpler (tedirginlik içinde) şiddetle çarpacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (79, 9, 'Gözleri zilletle bakacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (79, 10, 'Şöyle derler: “Biz gerçekten gerisin geriye eski haimize mi döndürüleceğiz?”');
INSERT INTO verses (sura, aya, text) VALUES (79, 11, '“Bizler çürümüş kemiklere döndükten sonra mı?”');
INSERT INTO verses (sura, aya, text) VALUES (79, 12, '“Öyle ise bu hüsran dolu bir dönüştür.” dediler.');
INSERT INTO verses (sura, aya, text) VALUES (79, 13, 'Hâlbuki o, bir haykırıştan (Sûr’un üfürülmesinden) ibarettir.');
INSERT INTO verses (sura, aya, text) VALUES (79, 14, 'Birden onlar (dirilmiş halde) bir düzlük üzeredirler.');
INSERT INTO verses (sura, aya, text) VALUES (79, 15, 'Mûsâ’nın haberi sana geldi mi?');
INSERT INTO verses (sura, aya, text) VALUES (79, 16, 'Hani Rabbi ona, mukaddes Tuvâ Vadisi''nde seslenmişti.');
INSERT INTO verses (sura, aya, text) VALUES (79, 17, '"Firavun’a git! Çünkü o gerçekten azdı.''''');
INSERT INTO verses (sura, aya, text) VALUES (79, 18, 'Deki: “Sen temizlenmek istiyor musun?”');
INSERT INTO verses (sura, aya, text) VALUES (79, 19, '"Seni, Rabbine ileteyim de O’na karşı derinden saygı duyup korkasın!”');
INSERT INTO verses (sura, aya, text) VALUES (79, 20, 'Derken Mûsâ, ona en büyük mucizeyi gösterdi.');
INSERT INTO verses (sura, aya, text) VALUES (79, 21, 'Fakat o, Mûsâ’yı yalanladı ve isyan etti.');
INSERT INTO verses (sura, aya, text) VALUES (79, 22, 'Sonra sırt dönüp koşarak gitti.');
INSERT INTO verses (sura, aya, text) VALUES (79, 23, 'Hemen (adamlarını) topladı ve onlara seslendi:');
INSERT INTO verses (sura, aya, text) VALUES (79, 24, '“Ben, sizin en yüce rabbinizim!” dedi.');
INSERT INTO verses (sura, aya, text) VALUES (79, 25, 'Allah da onu dünya ve ahiret azabıyla yakaladı.');
INSERT INTO verses (sura, aya, text) VALUES (79, 26, 'Şüphesiz bunda, Allah’tan sakınıp korkan kimseler için bir ibret vardır.');
INSERT INTO verses (sura, aya, text) VALUES (79, 27, 'Sizi yaratmak mı daha güçtür yoksa göğü mü? Onu (Allah) bina etti.');
INSERT INTO verses (sura, aya, text) VALUES (79, 28, 'Onun tavanını yükseltti ve düzenledi.');
INSERT INTO verses (sura, aya, text) VALUES (79, 29, 'Gecesini karanlık yaptı, gündüzünü aydınlığa çıkardı.');
INSERT INTO verses (sura, aya, text) VALUES (79, 30, 'Ve daha sonra da yeri döşeyip yaydı.');
INSERT INTO verses (sura, aya, text) VALUES (79, 31, 'Oradan suyunu ve otlağını çıkardı.');
INSERT INTO verses (sura, aya, text) VALUES (79, 32, 'Dağları da sapasağlam yerleştirdi.');
INSERT INTO verses (sura, aya, text) VALUES (79, 33, 'Bunları sizin için ve hayvanlarınız için bir yarar kaynağı yaptı.');
INSERT INTO verses (sura, aya, text) VALUES (79, 34, 'Her şeyi alt üst eden o büyük felaket (kıyamet) geldiği vakit.');
INSERT INTO verses (sura, aya, text) VALUES (79, 35, 'O gün insan, yaptıklarını hatırlayacak.');
INSERT INTO verses (sura, aya, text) VALUES (79, 36, 'Cehennem, görenler için apaçık bir şekilde gösterilir.');
INSERT INTO verses (sura, aya, text) VALUES (79, 37, 'Artık kim taşkınlık etmiş ise.');
INSERT INTO verses (sura, aya, text) VALUES (79, 38, 'Dünya hayatını tercih ettiyse.');
INSERT INTO verses (sura, aya, text) VALUES (79, 39, 'Cehennem onun varacağı barınaktır.');
INSERT INTO verses (sura, aya, text) VALUES (79, 40, 'Kim de Rabbinin makamından korkar ve nefsini kötü arzularından alıkoyarsa,');
INSERT INTO verses (sura, aya, text) VALUES (79, 41, '(O kimse için) Hiç şüphesiz Cennet yegâne barınaktır.');
INSERT INTO verses (sura, aya, text) VALUES (79, 42, 'Sana kıyametten soruyorlar: "Gelip çatması ne zaman?" diye.');
INSERT INTO verses (sura, aya, text) VALUES (79, 43, 'Sen onu nereden bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (79, 44, 'Rabbine aittir onunla ilgili son bilgi.');
INSERT INTO verses (sura, aya, text) VALUES (79, 45, 'Sen ancak, ondan korkan kimseler için bir uyarıcısın.');
INSERT INTO verses (sura, aya, text) VALUES (79, 46, 'Onlar onu gördükleri gün sanki (dünyada) bir akşam veya kuşluk vakti kadar kaldıklarını sanırlar.');
INSERT INTO verses (sura, aya, text) VALUES (80, 1, 'Yüzünü ekşitti ve arkasını döndü.');
INSERT INTO verses (sura, aya, text) VALUES (80, 2, 'Kendisine o âmâ geldi diye.');
INSERT INTO verses (sura, aya, text) VALUES (80, 3, 'Ne bilirsin belki o temizlenecekti.');
INSERT INTO verses (sura, aya, text) VALUES (80, 4, 'Yahut öğüt alacaktı da bu öğüt ona fayda verecekti.');
INSERT INTO verses (sura, aya, text) VALUES (80, 5, 'Kendini muhtaç hissetmeyene gelince;');
INSERT INTO verses (sura, aya, text) VALUES (80, 6, 'Sen, ona yöneliyorsun.');
INSERT INTO verses (sura, aya, text) VALUES (80, 7, '(İstemiyorsa) arınmamasından sen sorumlu değilsin!');
INSERT INTO verses (sura, aya, text) VALUES (80, 8, 'Fakat koşup sana gelen kimse;');
INSERT INTO verses (sura, aya, text) VALUES (80, 9, '(Allah''tan) korkuğu halde;');
INSERT INTO verses (sura, aya, text) VALUES (80, 10, 'Sen onu bırakıp oyalanıyorsun.');
INSERT INTO verses (sura, aya, text) VALUES (80, 11, 'Hayır. Bu ancak bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (80, 12, 'Artık dileyen kimse ondan öğüt alır.');
INSERT INTO verses (sura, aya, text) VALUES (80, 13, '(O) şerefli sahifelerdedir.');
INSERT INTO verses (sura, aya, text) VALUES (80, 14, 'Yüce ve tertemiz olan.');
INSERT INTO verses (sura, aya, text) VALUES (80, 15, 'Kâtiplerin ellerinde.');
INSERT INTO verses (sura, aya, text) VALUES (80, 16, 'Değerli ve itaatkâr olan (Meleklerin).');
INSERT INTO verses (sura, aya, text) VALUES (80, 17, 'Kahrolası (inkârcı) insan! Ne nankördür o!');
INSERT INTO verses (sura, aya, text) VALUES (80, 18, 'Allah, onu hangi şeyden yarattı?');
INSERT INTO verses (sura, aya, text) VALUES (80, 19, 'Bir nutfeden yarattı ve belli bir şekle soktu.');
INSERT INTO verses (sura, aya, text) VALUES (80, 20, 'Sonra da ona yolu kolaylaştırdı.');
INSERT INTO verses (sura, aya, text) VALUES (80, 21, 'Sonra da onu öldürüp kabre koydu.');
INSERT INTO verses (sura, aya, text) VALUES (80, 22, 'Sonra dilediği zaman onu yeniden diriltir.');
INSERT INTO verses (sura, aya, text) VALUES (80, 23, 'Hayır. O (Rabbinin) kendisine emrettiğini yerine getirmedi.');
INSERT INTO verses (sura, aya, text) VALUES (80, 24, 'İnsan yiyeceğine bir baksın.');
INSERT INTO verses (sura, aya, text) VALUES (80, 25, 'Şüphesiz biz suyu/yağmuru döktükçe döktük.');
INSERT INTO verses (sura, aya, text) VALUES (80, 26, 'Sonra toprağı iyiden iyiye yardık!');
INSERT INTO verses (sura, aya, text) VALUES (80, 27, 'Ve orada taneler bitirdik.');
INSERT INTO verses (sura, aya, text) VALUES (80, 28, 'Üzümler ve yoncalar,');
INSERT INTO verses (sura, aya, text) VALUES (80, 29, 'Zeytinler ve hurmalar,');
INSERT INTO verses (sura, aya, text) VALUES (80, 30, 'Sık ağaçlı bahçeler,');
INSERT INTO verses (sura, aya, text) VALUES (80, 31, 'Meyveler ve otlaklar,');
INSERT INTO verses (sura, aya, text) VALUES (80, 32, 'Sizin ve hayvanlarınızın yararlanması için,');
INSERT INTO verses (sura, aya, text) VALUES (80, 33, 'Kulakları sağır eden o ses geldiğinde,');
INSERT INTO verses (sura, aya, text) VALUES (80, 34, 'O gün kişi kardeşinden kaçar.');
INSERT INTO verses (sura, aya, text) VALUES (80, 35, 'Anasından ve babasından,');
INSERT INTO verses (sura, aya, text) VALUES (80, 36, 'Eşinden ve evladından,');
INSERT INTO verses (sura, aya, text) VALUES (80, 37, 'O gün herkes için kendine yetecek bir işi vardır.');
INSERT INTO verses (sura, aya, text) VALUES (80, 38, 'O gün birtakım yüzler vardır ki pırıl pırıl parlarlar.');
INSERT INTO verses (sura, aya, text) VALUES (80, 39, 'Güleç ve neşelidir.');
INSERT INTO verses (sura, aya, text) VALUES (80, 40, 'Öyle yüzler de var ki o gün üzerini toz kaplamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (80, 41, 'Onları bir siyahlık bürür.');
INSERT INTO verses (sura, aya, text) VALUES (80, 42, 'İşte onlar kâfirler, facirlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (81, 1, 'Güneş dürüldüğü zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 2, 'Yıldızlar, saçılıp dağıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 3, 'Dağlar yürütüldüğü zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 4, 'Gebe develer başıboş bırakıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 5, 'Vahşi hayvanlar bir araya toplandığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 6, 'Denizler tutuşturulduğu zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 7, 'Nefisler/kişiler (benzerleriyle) birleştirildiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 8, 'Diri diri (toprağa) gömülen kız çocuğuna sorulduğu zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 9, '"Hangi günâhtan dolayı öldürüldü?" (diye).');
INSERT INTO verses (sura, aya, text) VALUES (81, 10, 'Sahifeler (amel defterleri) açıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 11, 'Gök, sıyrılıp ayrıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 12, 'Cehennem alevlendirildiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 13, 'Ve Cennet yaklaştırıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (81, 14, 'Her nefis önceden ne hazırladığını bilecektir.');
INSERT INTO verses (sura, aya, text) VALUES (81, 15, 'Hayır! Yemin ederim gizlenen (yıldızlara).');
INSERT INTO verses (sura, aya, text) VALUES (81, 16, 'O akıp akıp yörüngesinde giden ve gizlenenlere.');
INSERT INTO verses (sura, aya, text) VALUES (81, 17, 'Karardığında geceye.');
INSERT INTO verses (sura, aya, text) VALUES (81, 18, 'Aydınlanmaya başladığında sabaha.');
INSERT INTO verses (sura, aya, text) VALUES (81, 19, 'Şüphesiz o, çok değerli bir elçinin sözüdür.');
INSERT INTO verses (sura, aya, text) VALUES (81, 20, 'Kuvvet sahibi; Arşın sahibinin katında itibarlı (bir elçinin).');
INSERT INTO verses (sura, aya, text) VALUES (81, 21, 'Kendine itaat edilen, üstelik güvenilir.');
INSERT INTO verses (sura, aya, text) VALUES (81, 22, 'Arkadaşınız bir mecnun değildir.');
INSERT INTO verses (sura, aya, text) VALUES (81, 23, 'Onu (Cebrail''i) ufukta apaçık görmüştür.');
INSERT INTO verses (sura, aya, text) VALUES (81, 24, 'O, gayp hakkında cimri değildir.');
INSERT INTO verses (sura, aya, text) VALUES (81, 25, 'O, kovulmuş Şeytan''ın sözü de değildir.');
INSERT INTO verses (sura, aya, text) VALUES (81, 26, 'Öyleyse nereye gidiyorsunuz?');
INSERT INTO verses (sura, aya, text) VALUES (81, 27, 'O, yalnızca bütün âlemler için bir öğüttür.');
INSERT INTO verses (sura, aya, text) VALUES (81, 28, 'Sizden dosdoğru olmak isteyenler için.');
INSERT INTO verses (sura, aya, text) VALUES (81, 29, 'Âlemlerin Rabbi Allah dilemedikçe siz de dileyemezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (82, 1, 'Gök yarıldığında.');
INSERT INTO verses (sura, aya, text) VALUES (82, 2, 'Yıldızlar döküldüğünde.');
INSERT INTO verses (sura, aya, text) VALUES (82, 3, 'Denizler birbirine karıştırıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (82, 4, 'Kabirler alt üst edildiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (82, 5, '(Artık her) Nefis, önceden takdim ettiklerini ve ertelediklerini bilip öğrenmiş olur.');
INSERT INTO verses (sura, aya, text) VALUES (82, 6, 'Ey insan! O kerim Rabbine karşı seni aldatan nedir?');
INSERT INTO verses (sura, aya, text) VALUES (82, 7, 'O seni yarattı, sana düzenli şekil verdi ve dengeli kıldı.');
INSERT INTO verses (sura, aya, text) VALUES (82, 8, 'Seni dilediği surette terkib etti (şekillendirdi).');
INSERT INTO verses (sura, aya, text) VALUES (82, 9, 'Hayır, hayır! Siz hesap ve cezayı yalanlıyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (82, 10, 'Ve şüphe yok ki, sizin üzerinizde koruyucular/gözetleyiciler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (82, 11, 'Şerefli yazıcılar/Kiramen, Katibin vardır.');
INSERT INTO verses (sura, aya, text) VALUES (82, 12, 'Onlar ne yaptığınızı biliyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (82, 13, 'İyiler, elbette nimetler içinde olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (82, 14, 'Kötüler/günahkârlar ise kesinlikle Cehennem''dedir.');
INSERT INTO verses (sura, aya, text) VALUES (82, 15, 'Hesap günü oraya atılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (82, 16, 'Onlar oradan (bir yere) kaybolacak değildirler.');
INSERT INTO verses (sura, aya, text) VALUES (82, 17, 'Hesap ve ceza gününün ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (82, 18, 'Ve yine hesap ve ceza gününün ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (82, 19, 'O gün, hiç kimsenin başkası için hiçbir şeye malik olmadığı gündür. O gün buyruk, yalnız Allah’ındır.');
INSERT INTO verses (sura, aya, text) VALUES (83, 1, 'Ölçüde hile yapanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (83, 2, 'Onlar insanlardan (bir şey) ölçüp aldıkları zaman tam ölçerler.');
INSERT INTO verses (sura, aya, text) VALUES (83, 3, 'Ama kendileri onlara bir şey ölçtükleri veya tarttıkları zaman eksiltirler.');
INSERT INTO verses (sura, aya, text) VALUES (83, 4, 'Onlar düşünmezler mi ki, büyük bir günde (hesap vermek için) diriltilecekler?');
INSERT INTO verses (sura, aya, text) VALUES (83, 5, 'Çok büyük bir gün için.');
INSERT INTO verses (sura, aya, text) VALUES (83, 6, 'İnsanlar o günde âlemlerin Rabbinin huzuruna kalkıp, duracaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (83, 7, 'Hayır! Günahkârların kitabı muhakkak “Siccîn”dedir.');
INSERT INTO verses (sura, aya, text) VALUES (83, 8, '“Siccîn”in ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (83, 9, '(O günahkârların yazısı) Amellerinin sayılıp yazıldığı bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (83, 10, 'O gün yalanlayanların vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (83, 11, 'Ki onlar, ceza gününü yalan sayarlar.');
INSERT INTO verses (sura, aya, text) VALUES (83, 12, 'Onu; ancak her azgın, günahkâr kimse yalanlar.');
INSERT INTO verses (sura, aya, text) VALUES (83, 13, 'Ona ayetlerimiz okunsa; "Eskilerin masalları." der.');
INSERT INTO verses (sura, aya, text) VALUES (83, 14, 'Hayır, aksine onların kazandıkları kalplerini örtmüştür.');
INSERT INTO verses (sura, aya, text) VALUES (83, 15, 'Hayır! Şüphesiz onlar, kıyamet günü Rablerini görmekten mahrum bırakılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (83, 16, 'Sonra da Cehennem''e atılacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (83, 17, 'Sonra da onlara; “Yalanlamış olduğunuz işte budur!” denilecek.');
INSERT INTO verses (sura, aya, text) VALUES (83, 18, 'Hayır, şüphe yok ki iyilerin kitabı “illiyyin”dedir.');
INSERT INTO verses (sura, aya, text) VALUES (83, 19, 'İlliyyun''un ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (83, 20, 'O yazılmış bir kitaptır.');
INSERT INTO verses (sura, aya, text) VALUES (83, 21, 'Ona, Allah’a yakın olanlar şâhit olur.');
INSERT INTO verses (sura, aya, text) VALUES (83, 22, 'Şüphesiz iyi kimseler Naîm Cenneti''ndedirler.');
INSERT INTO verses (sura, aya, text) VALUES (83, 23, 'Koltuklar üzerinde (etrafı) seyrederler.');
INSERT INTO verses (sura, aya, text) VALUES (83, 24, 'Onların yüzlerinde nimetlerin sevincini görürsün.');
INSERT INTO verses (sura, aya, text) VALUES (83, 25, 'Onlara mühürlü halis bir şaraptan içirilir.');
INSERT INTO verses (sura, aya, text) VALUES (83, 26, 'Onun (içiminin) sonu bir misktir. İşte yarışanlar bunun için yarışsınlar.');
INSERT INTO verses (sura, aya, text) VALUES (83, 27, 'Onun karışımı Tesnim’dendir.');
INSERT INTO verses (sura, aya, text) VALUES (83, 28, 'Bir pınar ki, Allah’a yakın olanlar ondan içerler.');
INSERT INTO verses (sura, aya, text) VALUES (83, 29, 'Şüphesiz günahkârlar, (dünyada) iman edenlere gülüyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (83, 30, 'Yanlarından geçtiklerinde birbirlerine kaş göz işaretleri yaparlardı.');
INSERT INTO verses (sura, aya, text) VALUES (83, 31, 'Ailelerine döndükleri zaman zevk duyarak dönerlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (83, 32, 'Onları gördüklerinde: "Bunlar hiç şüphesiz sapıklardır" derlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (83, 33, 'Hâlbuki onlar, Müminlerin başına bekçi olarak gönderilmemişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (83, 34, 'İşte bugün Müminler kâfirlere gülerler.');
INSERT INTO verses (sura, aya, text) VALUES (83, 35, 'Koltuklar üzerinde (etrafı) seyrederler.');
INSERT INTO verses (sura, aya, text) VALUES (83, 36, 'Kâfirler yapmakta olduklarının karşılığını gördüler mi?');
INSERT INTO verses (sura, aya, text) VALUES (84, 1, 'Gök yarıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (84, 2, 'Ve Rabbini dinleyip kendisine yaraşır şekilde boyun eğdiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (84, 3, 'Yer uzatılıp düzlendiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (84, 4, 'İçinde ne varsa dışarıya bırakıp bütünüyle boşaldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (84, 5, 'Ve Rabbini dinleyip kendisine yaraşır şekilde boyun eğdiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (84, 6, 'Ey insan gerçekten sen Rabbine doğru durmadan çalışıp çabalayacaksın, sonunda ona kavuşacaksın.');
INSERT INTO verses (sura, aya, text) VALUES (84, 7, 'Kitabı sağ eline verilecek kimseye gelince.');
INSERT INTO verses (sura, aya, text) VALUES (84, 8, 'O kolay bir hesap ile hesaba çekilecek.');
INSERT INTO verses (sura, aya, text) VALUES (84, 9, 'Ve o ailesine sevinçli dönecektir.');
INSERT INTO verses (sura, aya, text) VALUES (84, 10, 'Kitabı arkasından verilecek kimseye gelince.');
INSERT INTO verses (sura, aya, text) VALUES (84, 11, 'Artık o da yok olmayı dileyecektir.');
INSERT INTO verses (sura, aya, text) VALUES (84, 12, 'Ve alevli ateşi boylayacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (84, 13, 'Çünkü o, (dünyada iken) ailesi içinde sevinçli idi.');
INSERT INTO verses (sura, aya, text) VALUES (84, 14, 'Çünkü o, hiçbir zaman (Rabbine) dönmeyeceğini sanırdı.');
INSERT INTO verses (sura, aya, text) VALUES (84, 15, 'Hayır. Muhakkak ki, Rabbi onu görüyordu.');
INSERT INTO verses (sura, aya, text) VALUES (84, 16, 'Yemin olsun şafak vaktine.');
INSERT INTO verses (sura, aya, text) VALUES (84, 17, 'Geceye ve içinde topladıklarına.');
INSERT INTO verses (sura, aya, text) VALUES (84, 18, 'Dolunay haline geldiği zaman aya.');
INSERT INTO verses (sura, aya, text) VALUES (84, 19, 'Muhakkak ki siz bir halden başka bir hale geçeceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (84, 20, 'O halde onlara ne oluyor da iman etmiyorlar?');
INSERT INTO verses (sura, aya, text) VALUES (84, 21, 'Onlara Kur’an okunduğu zaman secde etmiyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (84, 22, 'Aksine, kâfirler(Kur’an’ı) yalanlıyorlar.');
INSERT INTO verses (sura, aya, text) VALUES (84, 23, 'Hâlbuki Allah, içlerinde ne sakladıklarını çok iyi bilir.');
INSERT INTO verses (sura, aya, text) VALUES (84, 24, 'Öyleyse sen onlara elem dolu bir azabı müjdele!');
INSERT INTO verses (sura, aya, text) VALUES (84, 25, 'Ancak iman edip de salih ameller işleyenler başka. Onlar için bitmez tükenmez bir mükâfat vardır.');
INSERT INTO verses (sura, aya, text) VALUES (85, 1, 'Burûc sahibi/yıldızların (yörüngelerine) sahip göğe yemin olsun.');
INSERT INTO verses (sura, aya, text) VALUES (85, 2, 'Vadedilmiş güne (kıyamete) yemin olsun.');
INSERT INTO verses (sura, aya, text) VALUES (85, 3, 'Şahit olana ve şahit olunana.');
INSERT INTO verses (sura, aya, text) VALUES (85, 4, 'Kahrolsun o hendek sahipleri!');
INSERT INTO verses (sura, aya, text) VALUES (85, 5, 'Tutuşturulmuş ateşin.');
INSERT INTO verses (sura, aya, text) VALUES (85, 6, 'O vakit onlar, onun (ateşin) etrafında oturmuşlardı.');
INSERT INTO verses (sura, aya, text) VALUES (85, 7, 'Müminlere yaptıklarını seyrediyorlardı.');
INSERT INTO verses (sura, aya, text) VALUES (85, 8, 'Onlardan; sırf göklerin ve yerin mülkü kendisine ait olan, Aziz ve Hamîd olan Allah’a iman ettikleri için intikam aldılar.');
INSERT INTO verses (sura, aya, text) VALUES (85, 9, 'Allah ki; göklerin ve yerin mülkü ona aittir ve Allah her şeyin üzerine şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (85, 10, 'Şüphesiz Mümin erkeklerle Mümin kadınlara işkence edip, sonra da tevbe etmeyenlere Cehennem azabı ve yakıcı azap vardır.');
INSERT INTO verses (sura, aya, text) VALUES (85, 11, 'İman edip salih ameller işleyenlere gelince; onlara içinden ırmaklar akan Cennetler vardır. İşte bu büyük başarıdır.');
INSERT INTO verses (sura, aya, text) VALUES (85, 12, 'Şüphesiz, Rabbinin tutup, yakalaması çok çetindir.');
INSERT INTO verses (sura, aya, text) VALUES (85, 13, 'İlkin var eden, sonra yeniden dirilten O''dur.');
INSERT INTO verses (sura, aya, text) VALUES (85, 14, 'O; çok bağışlayandır, çok seven ve sevilendir.');
INSERT INTO verses (sura, aya, text) VALUES (85, 15, 'Yüce Arş''ın sahibidir.');
INSERT INTO verses (sura, aya, text) VALUES (85, 16, 'Dilediğini muhakkak yapandır.');
INSERT INTO verses (sura, aya, text) VALUES (85, 17, 'Sana o orduların haberi geldi mi?');
INSERT INTO verses (sura, aya, text) VALUES (85, 18, 'Firavun ve Semûd’un askerlerinin haberi.');
INSERT INTO verses (sura, aya, text) VALUES (85, 19, 'Hayır, bu kâfir olanlar hâlâ yalanlamaktadırlar.');
INSERT INTO verses (sura, aya, text) VALUES (85, 20, 'Oysa Allah, onları arkalarından kuşatmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (85, 21, 'Hayır! O (yalanlamakta oldukları kitap) şanı yüce bir Kur’an’dır.');
INSERT INTO verses (sura, aya, text) VALUES (85, 22, 'O, korunmuş bir levhada (Levh-i Mahfuz’da) dır.');
INSERT INTO verses (sura, aya, text) VALUES (86, 1, 'Göğe ve târıka andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (86, 2, 'Târıkın ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (86, 3, 'O, (karanlığı) delip, geçen yıldızdır.');
INSERT INTO verses (sura, aya, text) VALUES (86, 4, 'Üzerinde gözetleyici/koruyucu bulunmayan hiç bir nefis (kimse) yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (86, 5, 'Öyleyse, insan neyden yaratıldığına bir baksın.');
INSERT INTO verses (sura, aya, text) VALUES (86, 6, 'Fışkırıp çıkan bir sudan yaratıldı.');
INSERT INTO verses (sura, aya, text) VALUES (86, 7, 'Bu su, bel ile kaburga kemikleri arasından çıkar.');
INSERT INTO verses (sura, aya, text) VALUES (86, 8, 'Şüphesiz Allah’ın onu, öldükten sonra tekrar diriltmeye de gücü yeter.');
INSERT INTO verses (sura, aya, text) VALUES (86, 9, 'Sırların açığa çıktığı gün.');
INSERT INTO verses (sura, aya, text) VALUES (86, 10, '(O gün) artık insan için ne bir kuvvet vardır, ne de bir yardımcı.');
INSERT INTO verses (sura, aya, text) VALUES (86, 11, 'Yağmurlu göğe andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (86, 12, 'Yarık yarık çatlamış yere andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (86, 13, 'Şüphesiz o Kur’an, hak ile batılı ayırt eden bir sözdür.');
INSERT INTO verses (sura, aya, text) VALUES (86, 14, 'O, boş bir söz değildir.');
INSERT INTO verses (sura, aya, text) VALUES (86, 15, 'Şüphesiz onlar bir tuzak kurarlar.');
INSERT INTO verses (sura, aya, text) VALUES (86, 16, 'Ben de bir tuzak kurarım.');
INSERT INTO verses (sura, aya, text) VALUES (86, 17, 'Öyleyse kâfirlere mühlet ver, onlara biraz zaman tanı!');
INSERT INTO verses (sura, aya, text) VALUES (87, 1, 'Yüce Rabbinin adını tesbih et.');
INSERT INTO verses (sura, aya, text) VALUES (87, 2, 'O; yaratıp şekillendiren, düzene koyandır.');
INSERT INTO verses (sura, aya, text) VALUES (87, 3, 'O, (her şeyi) ölçüyle yapıp, yol gösterendir.');
INSERT INTO verses (sura, aya, text) VALUES (87, 4, 'Otlağı çıkarandır.');
INSERT INTO verses (sura, aya, text) VALUES (87, 5, 'Sonra da onu kuru siyah bir ota çevirmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (87, 6, 'Sana (Kur’an’ı) okutacağız ve sen onu unutmayacaksın.');
INSERT INTO verses (sura, aya, text) VALUES (87, 7, 'Ancak Allah’ın dilediği hariç. Şüphesiz O; açık olanı da bilir, gizliyi de.');
INSERT INTO verses (sura, aya, text) VALUES (87, 8, 'Ve sana en kolay olanı kolaylaştırırız.');
INSERT INTO verses (sura, aya, text) VALUES (87, 9, 'O halde –eğer öğüt fayda verirse- sen de öğüt ver.');
INSERT INTO verses (sura, aya, text) VALUES (87, 10, '(Allah''tan) İçi titreyerek korkan hatırlayıp kendine gelir.');
INSERT INTO verses (sura, aya, text) VALUES (87, 11, 'Kötü kimse ise öğütten kaçınır.');
INSERT INTO verses (sura, aya, text) VALUES (87, 12, 'O kimsedir ki, en büyük ateşe girecektir.');
INSERT INTO verses (sura, aya, text) VALUES (87, 13, 'Sonra onun içinde ne ölür, ne de yaşar.');
INSERT INTO verses (sura, aya, text) VALUES (87, 14, 'Arınan kimse mutlaka kurtuluşa erer.');
INSERT INTO verses (sura, aya, text) VALUES (87, 15, 'Ve Rabbinin adını anıp namaz kılan.');
INSERT INTO verses (sura, aya, text) VALUES (87, 16, 'Fakat sizler, dünya hayatını tercih ediyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (87, 17, 'Oysa ahiret daha iyi ve kalıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (87, 18, 'Şüphesiz bu, önceki sahifelerde vardır.');
INSERT INTO verses (sura, aya, text) VALUES (87, 19, 'İbrahim’in ve Mûsâ’nın sahifelerinde.');
INSERT INTO verses (sura, aya, text) VALUES (88, 1, '(Dehşeti) Her şeyi kaplayacak olan (kıyamet)in haberi sana geldi mi?');
INSERT INTO verses (sura, aya, text) VALUES (88, 2, 'O gün birtakım yüzler vardır ki, zillete bürünmüşlerdir.');
INSERT INTO verses (sura, aya, text) VALUES (88, 3, 'Çalışmış, (boşa) yorulmuşlardır.');
INSERT INTO verses (sura, aya, text) VALUES (88, 4, 'Kızgın ateşe girerler.');
INSERT INTO verses (sura, aya, text) VALUES (88, 5, 'Son derece kızgın bir kaynaktan içirilirler.');
INSERT INTO verses (sura, aya, text) VALUES (88, 6, 'Onlar için kuru bir dikenden başka yiyecek yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (88, 7, 'Ne doyurup semirtir, ne de açlıktan korur.');
INSERT INTO verses (sura, aya, text) VALUES (88, 8, 'O gün birtakım yüzler vardır ki, nimet içinde mutludurlar.');
INSERT INTO verses (sura, aya, text) VALUES (88, 9, 'Yaptıklarından dolayı hoşnutturlar.');
INSERT INTO verses (sura, aya, text) VALUES (88, 10, 'Yüksek bir Cennet''tedirler.');
INSERT INTO verses (sura, aya, text) VALUES (88, 11, 'Orada hiçbir boş söz işitmezler.');
INSERT INTO verses (sura, aya, text) VALUES (88, 12, 'Orada akan bir pınar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (88, 13, 'Orada yüksek tahtlar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (88, 14, 'Yerleştirilmiş sürahiler.');
INSERT INTO verses (sura, aya, text) VALUES (88, 15, 'Sıra sıra dizilmiş yastıklar,');
INSERT INTO verses (sura, aya, text) VALUES (88, 16, 'Ve döşenmiş nefis halılar vardır.');
INSERT INTO verses (sura, aya, text) VALUES (88, 17, 'Deveye bakmıyorlar mı, nasıl yaratılmıştır?');
INSERT INTO verses (sura, aya, text) VALUES (88, 18, 'Göğe bakmıyorlar mı, nasıl yükseltilmiştir?');
INSERT INTO verses (sura, aya, text) VALUES (88, 19, 'Dağlara bakmıyorlar mı, nasıl dikilmişlerdir?');
INSERT INTO verses (sura, aya, text) VALUES (88, 20, 'Yeryüzüne bakmıyorlar mı, nasıl yayılmıştır?');
INSERT INTO verses (sura, aya, text) VALUES (88, 21, 'Artık sen öğüt ver! Sen ancak bir öğüt vericisin.');
INSERT INTO verses (sura, aya, text) VALUES (88, 22, 'Sen onların üzerinde bir zorba değilsin.');
INSERT INTO verses (sura, aya, text) VALUES (88, 23, 'Ancak kim yüz çevirir ve küfre saparsa.');
INSERT INTO verses (sura, aya, text) VALUES (88, 24, 'İşte öylesini Allah en büyük azap ile cezalandırır.');
INSERT INTO verses (sura, aya, text) VALUES (88, 25, 'Şüphesiz onların dönüşü ancak bizedir.');
INSERT INTO verses (sura, aya, text) VALUES (88, 26, 'Sonra onların sorguya çekilmesi de sadece bize aittir.');
INSERT INTO verses (sura, aya, text) VALUES (89, 1, 'Fecre/tan yerinin ağarmasına andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (89, 2, 'Ve on geceye andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (89, 3, 'Çifte ve teke andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (89, 4, 'Yürüyüp gittiği zaman geceye andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (89, 5, 'Bunda akıl sahibi için bir yemin var (değil) mi?');
INSERT INTO verses (sura, aya, text) VALUES (89, 6, 'Rabbinin Ad (kavmin)''e ne yaptığını görmedin mi?');
INSERT INTO verses (sura, aya, text) VALUES (89, 7, 'Yüksek sütun sahibi İrem şehrine.');
INSERT INTO verses (sura, aya, text) VALUES (89, 8, 'O (İrem Şehri) ki, beldeler (ülkeler) içinde onun bir eşi yaratılmadı.');
INSERT INTO verses (sura, aya, text) VALUES (89, 9, 'Ve vadideki kayaları oyan Semûd kavmine.');
INSERT INTO verses (sura, aya, text) VALUES (89, 10, 'Ve kazıklar sahibi Firavun’.');
INSERT INTO verses (sura, aya, text) VALUES (89, 11, 'Onlar ki memleketlerde azgınlık etmişlerdi.');
INSERT INTO verses (sura, aya, text) VALUES (89, 12, 'Oralarda kötülüğü çoğalttılar.');
INSERT INTO verses (sura, aya, text) VALUES (89, 13, 'Bu yüzden Rabbin onların üzerine azap kamçısı yağdırdı.');
INSERT INTO verses (sura, aya, text) VALUES (89, 14, 'Muhakkak Rabbin gözetlemededir.');
INSERT INTO verses (sura, aya, text) VALUES (89, 15, 'Ancak insana; Rabbi ne zaman onu imtihan edip kendisine ikramda bulunsa ve nimet verse: "Rabbim bana ikramda bulundu" der.');
INSERT INTO verses (sura, aya, text) VALUES (89, 16, 'Ama ne zaman onu imtihan ederek rızkını daraltsa: "Rabbim beni hor kıldı" der.');
INSERT INTO verses (sura, aya, text) VALUES (89, 17, 'Hayır, hayır! Yetime ikram etmiyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (89, 18, 'Yoksula yemek vermeye teşvik etmiyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (89, 19, 'Haram helâl demeden mirası alabildiğine yiyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (89, 20, 'Malı da pek çok seviyorsunuz.');
INSERT INTO verses (sura, aya, text) VALUES (89, 21, 'Hayır! Yeryüzü (kıyamet sarsıntısıyla) parça parça olup dağıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (89, 22, 'Rabbin ve saf saf melekler geldiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (89, 23, 'O gün cehennem de getirilmiştir. İşte o gün insan düşünüp hatırlar. Ama hatırlamaktan ona ne (fayda) var!');
INSERT INTO verses (sura, aya, text) VALUES (89, 24, 'Der ki: "Ah keşke! (Bu) hayatım için önceden bir şeyler göndermiş olsaydım!"');
INSERT INTO verses (sura, aya, text) VALUES (89, 25, 'Artık o gün de O''nun azabı gibi hiçbir kimse azap yapamaz.');
INSERT INTO verses (sura, aya, text) VALUES (89, 26, 'Ve O''nun vuracağı bağı hiç kimse vuramaz.');
INSERT INTO verses (sura, aya, text) VALUES (89, 27, 'Ey huzura ermiş nefis!');
INSERT INTO verses (sura, aya, text) VALUES (89, 28, '“Sen O’ndan razı, O da senden razı olarak Rabbine dön!”');
INSERT INTO verses (sura, aya, text) VALUES (89, 29, 'Kullarımın arasına katıl!');
INSERT INTO verses (sura, aya, text) VALUES (89, 30, 'Ve gir Cennet''ime!');
INSERT INTO verses (sura, aya, text) VALUES (90, 1, 'Yemin olsun bu şehre!');
INSERT INTO verses (sura, aya, text) VALUES (90, 2, 'Sen de bu beldede bulunuyorsun.');
INSERT INTO verses (sura, aya, text) VALUES (90, 3, 'Babaya ve doğan çocuğa yemin olsun.');
INSERT INTO verses (sura, aya, text) VALUES (90, 4, 'Ki şüphesiz, biz insanı (dünyada) bir zorluk içinde yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (90, 5, 'O hiç kimsenin kendisine asla güç yetiremeyeceğini mi sanır?');
INSERT INTO verses (sura, aya, text) VALUES (90, 6, 'O der ki: "Ben yığın yığın mal tükettim."');
INSERT INTO verses (sura, aya, text) VALUES (90, 7, 'O kimsenin kendisini asla görmediğini mi zanneder?');
INSERT INTO verses (sura, aya, text) VALUES (90, 8, 'Biz, ona iki göz vermedik mi?');
INSERT INTO verses (sura, aya, text) VALUES (90, 9, 'Bir de bir dil ve iki dudak.');
INSERT INTO verses (sura, aya, text) VALUES (90, 10, 'Ona iki de yol gösterdik.');
INSERT INTO verses (sura, aya, text) VALUES (90, 11, 'Fakat o, sarp yokuşu aşamadı.');
INSERT INTO verses (sura, aya, text) VALUES (90, 12, 'Sarp yokuşun ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (90, 13, '(O) Köle azat etmektir.');
INSERT INTO verses (sura, aya, text) VALUES (90, 14, 'Veya açlık gününde doyurmaktır.');
INSERT INTO verses (sura, aya, text) VALUES (90, 15, 'Yakınlığı olan bir yetimi.');
INSERT INTO verses (sura, aya, text) VALUES (90, 16, 'Yahut yerde sürünen bir yoksulu doyurmaktır.');
INSERT INTO verses (sura, aya, text) VALUES (90, 17, 'Sonra iman edip, birbirlerine sabır tavsiye edenlerden ve birbirlerine merhamet tavsiye edenlerden olmaktır.');
INSERT INTO verses (sura, aya, text) VALUES (90, 18, 'İşte bunlar sağdakilerdir.');
INSERT INTO verses (sura, aya, text) VALUES (90, 19, 'Ayetlerimize küfredenler ise işte onlar soldakilerdir.');
INSERT INTO verses (sura, aya, text) VALUES (90, 20, 'Onlara, üzerlerine kapıları kapatılmış bir ateş vardır.');
INSERT INTO verses (sura, aya, text) VALUES (91, 1, 'Güneş''e ve onun aydınlığına andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (91, 2, 'Onu izlediğinde Ay’a andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (91, 3, 'Onu ortaya çıkardığında gündüze andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (91, 4, 'Onu bürüdüğünde geceye andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (91, 5, 'Göğe ve onu bina edene andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (91, 6, 'Yeryüzüne ve onu yayıp döşeyene andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (91, 7, 'Nefse ve ona bir düzen içinde biçim verene.');
INSERT INTO verses (sura, aya, text) VALUES (91, 8, 'Sonra da ona günahını ve takvasını ilham etmiş olana (andolsun ki).');
INSERT INTO verses (sura, aya, text) VALUES (91, 9, 'Şüphe yok ki, nefsini temizlemiş olan felaha ermiştir.');
INSERT INTO verses (sura, aya, text) VALUES (91, 10, 'Onu kötülüklere gömüp kirleten kimse de ziyana uğramıştır.');
INSERT INTO verses (sura, aya, text) VALUES (91, 11, 'Semûd kavmi de nefislerinin azgınlığıyla (peygamberini) yalanladı.');
INSERT INTO verses (sura, aya, text) VALUES (91, 12, 'Hani onların en bedbaht olanı (fesat çıkarmak için) ileri atılınca.');
INSERT INTO verses (sura, aya, text) VALUES (91, 13, 'Allah’ın Rasûlü de onlara şöyle dedi ki: "Allah’ın devesin(i kesmek)ten ve su içmesin(i engellemek)ten sakının."');
INSERT INTO verses (sura, aya, text) VALUES (91, 14, 'Fakat onlar, onu yalanladılar ve deveyi boğazladılar. Bunun üzerine Rableri, günâhlarından dolayı onları helâk etti ve kendilerini yerle bir etti.');
INSERT INTO verses (sura, aya, text) VALUES (91, 15, 'Allah, bunun sonucundan korkmaz!');
INSERT INTO verses (sura, aya, text) VALUES (92, 1, '(Ortalığı) bürüdüğü zaman geceye andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (92, 2, 'Açılıp aydınlandığı zaman gündüze andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (92, 3, 'Erkeği ve dişiyi yaratana andolsun ki.');
INSERT INTO verses (sura, aya, text) VALUES (92, 4, 'Şüphesiz sizin çabalarınız elbette çeşit çeşittir.');
INSERT INTO verses (sura, aya, text) VALUES (92, 5, 'Kim (malından) verir ve sakınırsa.');
INSERT INTO verses (sura, aya, text) VALUES (92, 6, 'En güzel sözü (kelime-i tevhidi) tasdik ederse.');
INSERT INTO verses (sura, aya, text) VALUES (92, 7, 'Biz, onu en kolay olana kolayca iletiriz.');
INSERT INTO verses (sura, aya, text) VALUES (92, 8, 'Kim cimrilik eder kendini müstağni sayarsa.');
INSERT INTO verses (sura, aya, text) VALUES (92, 9, 'Ve en güzeli yalanlarsa.');
INSERT INTO verses (sura, aya, text) VALUES (92, 10, 'Biz de ona zor olanı kolaylaştırırız.');
INSERT INTO verses (sura, aya, text) VALUES (92, 11, 'Cehennem''e yuvarlandığı zaman malı ona fayda vermez.');
INSERT INTO verses (sura, aya, text) VALUES (92, 12, 'Şüphesiz bize düşen sadece doğru yolu göstermektir.');
INSERT INTO verses (sura, aya, text) VALUES (92, 13, 'Şüphesiz ahiret de dünya da bizimdir.');
INSERT INTO verses (sura, aya, text) VALUES (92, 14, 'Sizi alevler saçan ateşe karşı uyardım.');
INSERT INTO verses (sura, aya, text) VALUES (92, 15, 'Ona ancak en azgın olan girecektir.');
INSERT INTO verses (sura, aya, text) VALUES (92, 16, 'Öyle yalancıdır ki, yalanlamıştır ve yüz çevirmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (92, 17, 'Takva sahibi ise oradan uzak tutulacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (92, 18, '(Ki o) Malını vererek arınır.');
INSERT INTO verses (sura, aya, text) VALUES (92, 19, 'O, verdiğini kendisine yapılan bir iyiliğin karşılığı olarak vermez.');
INSERT INTO verses (sura, aya, text) VALUES (92, 20, '(Yaptığı iyiliği) ancak yüce Rabbinin rızasını istediği için (yapar).');
INSERT INTO verses (sura, aya, text) VALUES (92, 21, 'Muhakkak kendisi de ileride razı olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (93, 1, 'Kuşluk vaktine andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (93, 2, 'Karanlığı çöktüğü vakit geceye andolsun ki.');
INSERT INTO verses (sura, aya, text) VALUES (93, 3, 'Rabbin ne seni terk etti, ne de sana darıldı.');
INSERT INTO verses (sura, aya, text) VALUES (93, 4, 'Muhakkak ki âhiret senin için dünyadan daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (93, 5, 'Elbette Rabbin sana verecek, sen de hoşnut olacaksın.');
INSERT INTO verses (sura, aya, text) VALUES (93, 6, 'Seni bir yetim olarak bulup barındırmadı mı?');
INSERT INTO verses (sura, aya, text) VALUES (93, 7, 'Ve seni (kitap ve iman nedir) bilmezken bulup hidayete eriştirmedi mi?');
INSERT INTO verses (sura, aya, text) VALUES (93, 8, 'Seni fakirken, zengin kılmadı mı?');
INSERT INTO verses (sura, aya, text) VALUES (93, 9, 'Öyleyse sakın yetimi ezme!');
INSERT INTO verses (sura, aya, text) VALUES (93, 10, 'İsteyeni de azarlama!');
INSERT INTO verses (sura, aya, text) VALUES (93, 11, 'Rabbinin nimetine gelince; işte onu anlat.');
INSERT INTO verses (sura, aya, text) VALUES (94, 1, '(Ey Muhammed!) Senin göğsünü açıp genişletmedik mi?');
INSERT INTO verses (sura, aya, text) VALUES (94, 2, 'Yükünü üzerinden kaldırıp indirmedik mi?');
INSERT INTO verses (sura, aya, text) VALUES (94, 3, 'O (yük) senin belini bükmüştü.');
INSERT INTO verses (sura, aya, text) VALUES (94, 4, 'Ve senin şanını yükseltmedik mi?');
INSERT INTO verses (sura, aya, text) VALUES (94, 5, 'Şüphesiz her zorlukla beraber bir kolaylık vardır.');
INSERT INTO verses (sura, aya, text) VALUES (94, 6, 'Gerçekten güçlükle beraber bir kolaylık vardır.');
INSERT INTO verses (sura, aya, text) VALUES (94, 7, 'O halde boş kaldığın zaman (ibadet ve dua ile) yorul.');
INSERT INTO verses (sura, aya, text) VALUES (94, 8, 'Ve yalnızca Rabbine yönel.');
INSERT INTO verses (sura, aya, text) VALUES (95, 1, 'İncire ve zeytine yemin olsun!');
INSERT INTO verses (sura, aya, text) VALUES (95, 2, 'Ve Sîna Dağı''na andolsun.');
INSERT INTO verses (sura, aya, text) VALUES (95, 3, 'Bu güvenli şehre (Mekke’ye) andolsun ki.');
INSERT INTO verses (sura, aya, text) VALUES (95, 4, 'Biz, gerçekten insanı en güzel bir biçimde yarattık.');
INSERT INTO verses (sura, aya, text) VALUES (95, 5, 'Daha sonra, onu aşağıların en aşağısına döndürdük.');
INSERT INTO verses (sura, aya, text) VALUES (95, 6, 'Ancak iman edip salih ameller işleyenler ayrı. Onlar için kesintisiz bir ecir vardır.');
INSERT INTO verses (sura, aya, text) VALUES (95, 7, '(Ey insan!) Böyle iken, hangi şey sana hesap ve cezayı yalanlatıyor?');
INSERT INTO verses (sura, aya, text) VALUES (95, 8, 'Allah, hükmedenlerin en iyi hükmedeni değil midir?');
INSERT INTO verses (sura, aya, text) VALUES (96, 1, 'Yaratan Rabbinin adıyla oku!');
INSERT INTO verses (sura, aya, text) VALUES (96, 2, 'O, insanı bir kan pıhtısından yarattı.');
INSERT INTO verses (sura, aya, text) VALUES (96, 3, 'Oku! Senin Rabbin, en cömert olandır.');
INSERT INTO verses (sura, aya, text) VALUES (96, 4, 'Ki O, kalem ile öğretmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (96, 5, 'İnsana bilmediği şeyleri öğretti.');
INSERT INTO verses (sura, aya, text) VALUES (96, 6, 'Hayır! İnsan gerçekten azgınlık eder.');
INSERT INTO verses (sura, aya, text) VALUES (96, 7, 'Kendini müstağni/ihtiyacı yok gördü diye.');
INSERT INTO verses (sura, aya, text) VALUES (96, 8, 'Şüphesiz dönüş yalnızca Rabbine olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (96, 9, 'Sen, o engel olanı gördün mü?');
INSERT INTO verses (sura, aya, text) VALUES (96, 10, 'Bir kulu namaz kıldığı vakit.');
INSERT INTO verses (sura, aya, text) VALUES (96, 11, 'Ne dersin o (Peygamber) doğru yolda ise.');
INSERT INTO verses (sura, aya, text) VALUES (96, 12, 'Yahut takvayı emrettiyse.');
INSERT INTO verses (sura, aya, text) VALUES (96, 13, 'Gördün mü? Ya o (engel olan) yalanladı ve yüz çevirdiyse!');
INSERT INTO verses (sura, aya, text) VALUES (96, 14, 'O Allah’ın, her şeyi gördüğünü bilmiyor mu?');
INSERT INTO verses (sura, aya, text) VALUES (96, 15, 'Hayır! Eğer son vermezse, elbette perçeminden yakalayıp sürükleriz.');
INSERT INTO verses (sura, aya, text) VALUES (96, 16, 'Yalancı, günahkâr perçeminden.');
INSERT INTO verses (sura, aya, text) VALUES (96, 17, 'Haydi! O meclisini /Taraftarlarını çağırsın.');
INSERT INTO verses (sura, aya, text) VALUES (96, 18, 'Biz de Zebanileri çağıracağız.');
INSERT INTO verses (sura, aya, text) VALUES (96, 19, 'Hayır ona itaat etme! Allah’a secde et ve (yalnızca) O’na yaklaş.');
INSERT INTO verses (sura, aya, text) VALUES (97, 1, 'Şüphesiz, biz onu (Kur’an’ı) Kadir Gecesi''nde indirdik.');
INSERT INTO verses (sura, aya, text) VALUES (97, 2, 'Kadir Gecesi''nin ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (97, 3, 'Kadir Gecesi bin aydan daha hayırlıdır.');
INSERT INTO verses (sura, aya, text) VALUES (97, 4, 'Melekler ve Ruh (Cebrail) o gecede, Rablerinin izniyle her türlü iş için iner dururlar.');
INSERT INTO verses (sura, aya, text) VALUES (97, 5, 'O fecrin doğuşuna kadar bir esenliktir.');
INSERT INTO verses (sura, aya, text) VALUES (98, 1, 'Kitap ehlinden ve müşriklerden kâfir olanlar kendilerine apaçık delil gelinceye kadar ayrılacak değillerdi.');
INSERT INTO verses (sura, aya, text) VALUES (98, 2, '(Bu delil) Allah tarafından (gönderilen) tertemiz sahifeler okuyan bir rasûldür.');
INSERT INTO verses (sura, aya, text) VALUES (98, 3, 'Onların içinde dosdoğru yazılı şeyler vardır.');
INSERT INTO verses (sura, aya, text) VALUES (98, 4, 'Kendilerine kitap verilenler ancak kendilerine apaçık delil geldikten sonra ayrılığa düştüler.');
INSERT INTO verses (sura, aya, text) VALUES (98, 5, 'Hâlbuki onlara, ancak dini Allah’a has kılarak, hakka yönelen kimseler olarak O’na ibadet etmeleri, namazı dosdoğru kılmaları ve zekâtı vermeleri emredilmişti. İşte bu dosdoğru dindir.');
INSERT INTO verses (sura, aya, text) VALUES (98, 6, 'Hiç şüphesiz kitap ehlinden ve müşriklerden küfre sapanlar, içinde sürekli kalıcılar olarak cehennem ateşindedirler. İşte onlar, yaratılmışların en kötüleridir.');
INSERT INTO verses (sura, aya, text) VALUES (98, 7, 'Şüphesiz, iman edip salih ameller işleyenler var ya; işte onlar yaratıkların en hayırlısıdırlar.');
INSERT INTO verses (sura, aya, text) VALUES (98, 8, 'Onların Rablerinin yanındaki mükâfatları altından ırmaklar akan Adn cennetleridir. Onlar orada ebedi kalıcıdırlar. Allah onlardan razı olmuştur, onlar da ondan hoşnut olmuşlardır. İşte bu Rabbinden korkan kimseler içindir.');
INSERT INTO verses (sura, aya, text) VALUES (99, 1, 'Yer, şiddetle sarsıldığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (99, 2, 'Ve yeryüzü, ağırlıklarını çıkardığı zaman.');
INSERT INTO verses (sura, aya, text) VALUES (99, 3, 'Ve insan ne oluyor buna dediği vakit.');
INSERT INTO verses (sura, aya, text) VALUES (99, 4, 'İşte o gün, yer kendi haberlerini anlatır.');
INSERT INTO verses (sura, aya, text) VALUES (99, 5, 'Çünkü Rabbin ona (öyle) vahyetmiştir.');
INSERT INTO verses (sura, aya, text) VALUES (99, 6, 'O gün insanlar amellerinin kendilerine gösterilmesi için bölük bölük kabirlerinden çıkacaklardır.');
INSERT INTO verses (sura, aya, text) VALUES (99, 7, 'Artık kim zerre ağırlığınca bir hayır işlerse, onun mükâfatını görecektir.');
INSERT INTO verses (sura, aya, text) VALUES (99, 8, 'Kim de zerre ağırlığınca bir kötülük işlerse, onun cezasını görecektir.');
INSERT INTO verses (sura, aya, text) VALUES (100, 1, 'Soluk soluğa koşanlara yemin olsun!');
INSERT INTO verses (sura, aya, text) VALUES (100, 2, '(Koşarken) kıvılcım saçanlara.');
INSERT INTO verses (sura, aya, text) VALUES (100, 3, 'Sabah vakti baskın yapanlara.');
INSERT INTO verses (sura, aya, text) VALUES (100, 4, 'Tozu dumana katanlara.');
INSERT INTO verses (sura, aya, text) VALUES (100, 5, 'Topluluğun tam ortasına dalanlara.');
INSERT INTO verses (sura, aya, text) VALUES (100, 6, 'İnsan, Rabbine karşı gerçekten çok nankördür.');
INSERT INTO verses (sura, aya, text) VALUES (100, 7, 'Ve şüphesiz kendisi de buna şahittir.');
INSERT INTO verses (sura, aya, text) VALUES (100, 8, 'Şüphesiz onun mal sevgisi de çok şiddetlidir.');
INSERT INTO verses (sura, aya, text) VALUES (100, 9, 'Bilmez mi ki kabirlerde olanlar alt üst edildiğinde.');
INSERT INTO verses (sura, aya, text) VALUES (100, 10, 'Kalplerde bulunan ortaya konduğunda.');
INSERT INTO verses (sura, aya, text) VALUES (100, 11, 'Şüphesiz o gün Rableri kendilerinden elbette haberdardır.');
INSERT INTO verses (sura, aya, text) VALUES (101, 1, 'Şiddetle gelip çatan.');
INSERT INTO verses (sura, aya, text) VALUES (101, 2, 'Nedir o yürekleri hoplatan büyük felaket?');
INSERT INTO verses (sura, aya, text) VALUES (101, 3, 'Yürekleri hoplatan büyük felaketin ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (101, 4, 'O gün insanlar, her biri bir tarafa uçuşan kelebekler gibi olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (101, 5, 'Dağlar da atılmış renkli yünler gibi olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (101, 6, 'İşte o vakit, kimin tartıları ağır gelmişse.');
INSERT INTO verses (sura, aya, text) VALUES (101, 7, 'Artık o, hoşnut olacağı bir hayatın içinde olacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (101, 8, 'Ama kimin de tartıları hafif gelirse.');
INSERT INTO verses (sura, aya, text) VALUES (101, 9, 'İşte onun varacağı yer Hâviye’dir.');
INSERT INTO verses (sura, aya, text) VALUES (101, 10, 'Sen Hâviye’nin ne olduğunu ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (101, 11, 'O, kızgın bir ateştir.');
INSERT INTO verses (sura, aya, text) VALUES (102, 1, 'Çoklukla övünmek sizi oyaladı.');
INSERT INTO verses (sura, aya, text) VALUES (102, 2, 'Ta ki, kabirleri ziyaret edinceye/ölünceye dek devam ettiniz.');
INSERT INTO verses (sura, aya, text) VALUES (102, 3, 'Hayır! İlerde bileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (102, 4, 'Yine hayır! İleride bileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (102, 5, 'Hayır! Kesin bir bilgiyle bilseydiniz (kaçınırdınız).');
INSERT INTO verses (sura, aya, text) VALUES (102, 6, 'Elbette Cehennem''i göreceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (102, 7, 'Yine andolsun, onu gözünüzle kesin olarak göreceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (102, 8, 'Sonra o gün, nimetlerden hesaba çekileceksiniz.');
INSERT INTO verses (sura, aya, text) VALUES (103, 1, 'Asra yemin olsun.');
INSERT INTO verses (sura, aya, text) VALUES (103, 2, 'Şüphesiz insanlık hüsran içindedir.');
INSERT INTO verses (sura, aya, text) VALUES (103, 3, 'Ancak iman edenler ve salih amel yapanlar, birbirlerine hakkı ve sabrı tavsiye edenler müstesna.');
INSERT INTO verses (sura, aya, text) VALUES (104, 1, 'Arkadan çekiştirip duran, kaş göz hareketleriyle alay eden her kişinin vay haline!');
INSERT INTO verses (sura, aya, text) VALUES (104, 2, 'Mal toplayıp, onu tekrar tekrar sayan.');
INSERT INTO verses (sura, aya, text) VALUES (104, 3, 'Malının kendisini ebedi kılacağını zanneder.');
INSERT INTO verses (sura, aya, text) VALUES (104, 4, 'Hayır! Andolsun ki o, Hutâme’ye atılacaktır.');
INSERT INTO verses (sura, aya, text) VALUES (104, 5, 'Hutâme’nin ne olduğunu sen ne bileceksin?');
INSERT INTO verses (sura, aya, text) VALUES (104, 6, 'O, Allah''ın tutuşturulmuş ateşidir.');
INSERT INTO verses (sura, aya, text) VALUES (104, 7, 'Öyle ki, o kalplere kadar işler.');
INSERT INTO verses (sura, aya, text) VALUES (104, 8, 'Şüphe yok ki, bu onların üzerilerine kapatılmıştır.');
INSERT INTO verses (sura, aya, text) VALUES (104, 9, 'Uzatılmış sütunlarla (kapatılmıştır).');
INSERT INTO verses (sura, aya, text) VALUES (105, 1, 'Rabbinin, fil sahiplerine ne yaptığını görmedin mi?');
INSERT INTO verses (sura, aya, text) VALUES (105, 2, 'Onların tuzaklarını boşa çıkarmadı mı?');
INSERT INTO verses (sura, aya, text) VALUES (105, 3, 'Onların üzerine bölük bölük kuş sürüleri gönderdi.');
INSERT INTO verses (sura, aya, text) VALUES (105, 4, 'O kuşlar, onların üzerilerine pişkin tuğladan yapılmış taşlar atıyordu.');
INSERT INTO verses (sura, aya, text) VALUES (105, 5, 'Nihayetinde onları yenmiş ekin yaprakları gibi yapıverdi.');
INSERT INTO verses (sura, aya, text) VALUES (106, 1, 'Kureyş’in güvenliği ve esenliği için.');
INSERT INTO verses (sura, aya, text) VALUES (106, 2, 'Onların kış ve yaz yolculuklarının güvenliği için.');
INSERT INTO verses (sura, aya, text) VALUES (106, 3, 'Bu evin (Kâbe) Rabbine ibadet etsinler.');
INSERT INTO verses (sura, aya, text) VALUES (106, 4, 'Onları açlıktan doyuran ve korkularından emin kılana.');
INSERT INTO verses (sura, aya, text) VALUES (107, 1, 'Hesap gününü yalanlayanı gördün mü?');
INSERT INTO verses (sura, aya, text) VALUES (107, 2, 'Yetimi itip kakan da işte odur.');
INSERT INTO verses (sura, aya, text) VALUES (107, 3, 'Ve yoksulu doyurmaya teşvik etmez.');
INSERT INTO verses (sura, aya, text) VALUES (107, 4, 'Vay o namaz kılanların haline ki:');
INSERT INTO verses (sura, aya, text) VALUES (107, 5, 'Onlar kıldıkları namazdan gafildirler.');
INSERT INTO verses (sura, aya, text) VALUES (107, 6, 'Onlar gösteriş yaparlar.');
INSERT INTO verses (sura, aya, text) VALUES (107, 7, 'Hem de mâûnu da vermeyip, engellerler.');
INSERT INTO verses (sura, aya, text) VALUES (108, 1, 'Şüphesiz biz sana Kevser''i verdik.');
INSERT INTO verses (sura, aya, text) VALUES (108, 2, 'Öyleyse sen de Rabbin için namaz kıl ve kurban kes!');
INSERT INTO verses (sura, aya, text) VALUES (108, 3, 'Şüphesiz asıl sana kin besleyenin soyu kesiktir.');
INSERT INTO verses (sura, aya, text) VALUES (109, 1, 'De ki: Ey kâfirler!');
INSERT INTO verses (sura, aya, text) VALUES (109, 2, 'Ben sizin ibadet ettiklerinize ibadet etmem.');
INSERT INTO verses (sura, aya, text) VALUES (109, 3, 'Siz de benim ibadet ettiğime ibadet etmezsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (109, 4, 'Ben, sizin ibadet ettiklerinize ibadet edecek de değilim.');
INSERT INTO verses (sura, aya, text) VALUES (109, 5, 'Siz de benim ibadet ettiğime ibadet edecek değilsiniz.');
INSERT INTO verses (sura, aya, text) VALUES (109, 6, 'Sizin dininiz size, benim dinim ise banadır.');
INSERT INTO verses (sura, aya, text) VALUES (110, 1, 'Allah’ın yardımı geldiği ve fetih gerçekleştiği zaman.');
INSERT INTO verses (sura, aya, text) VALUES (110, 2, 'İnsanların akın akın Allah’ın dinine girdiğini gördüğün zaman.');
INSERT INTO verses (sura, aya, text) VALUES (110, 3, 'Hemen, hamdederek Rabbini tesbih et ve O’ndan bağışlanma dile. Şüphesiz O, çok bağışlayıcıdır.');
INSERT INTO verses (sura, aya, text) VALUES (111, 1, 'Elleri kurusun Ebu Leheb’in! Zaten kurudu da.');
INSERT INTO verses (sura, aya, text) VALUES (111, 2, 'Malı ve kazandıkları ona bir fayda vermedi.');
INSERT INTO verses (sura, aya, text) VALUES (111, 3, 'O, alevli bir ateşe girecektir.');
INSERT INTO verses (sura, aya, text) VALUES (111, 4, 'Karısı da odun taşıyacak.');
INSERT INTO verses (sura, aya, text) VALUES (111, 5, 'Boynunda hurma lifinden bir halat olduğu halde.');
INSERT INTO verses (sura, aya, text) VALUES (112, 1, 'De ki: O Allah birdir.');
INSERT INTO verses (sura, aya, text) VALUES (112, 2, 'Allah Samed''dir.');
INSERT INTO verses (sura, aya, text) VALUES (112, 3, 'Doğurmamıştır, doğurulmamıştır.');
INSERT INTO verses (sura, aya, text) VALUES (112, 4, 'O''nun hiçbir dengi yoktur.');
INSERT INTO verses (sura, aya, text) VALUES (113, 1, 'De ki: Ben, sabahın Rabbine sığınırım.');
INSERT INTO verses (sura, aya, text) VALUES (113, 2, 'Yarattığı varlıkların şerrinden.');
INSERT INTO verses (sura, aya, text) VALUES (113, 3, 'Karanlığı çöktüğü zaman gecenin şerrinden.');
INSERT INTO verses (sura, aya, text) VALUES (113, 4, 'Düğümlere üfleyenlerin şerrinden.');
INSERT INTO verses (sura, aya, text) VALUES (113, 5, 'Haset ettiği zaman hasetçinin şerrinden.');
INSERT INTO verses (sura, aya, text) VALUES (114, 1, 'De ki: İnsanların Rabbine sığınırım.');
INSERT INTO verses (sura, aya, text) VALUES (114, 2, 'İnsanların hükümdarına.');
INSERT INTO verses (sura, aya, text) VALUES (114, 3, 'İnsanların ilahına.');
INSERT INTO verses (sura, aya, text) VALUES (114, 4, 'Sinsi/(Allah anıldığında geri kaçan) vesvesecinin şerrinden.');
INSERT INTO verses (sura, aya, text) VALUES (114, 5, 'Ki o, insanların göğüslerine vesvese verir.');
INSERT INTO verses (sura, aya, text) VALUES (114, 6, 'Gerek cinlerden, gerek insanlardan (olur).');
